#!/usr/bin/env python3
"""aide — the AIDE framework CLI.

A single, stdlib-only command-line tool for the deterministic parts of the AIDE
loop, so agents don't spend reasoning tokens on mechanical git/document surgery.
It is **venv-independent** (it must run before/without the project venv) and
**project-agnostic** — every project fact comes from ``aide.toml``.

Subcommands::

    python .aide/scripts/aide.py check [--queue NNN]   # consistency gate over docs/aide
    python .aide/scripts/aide.py scope [NNN]           # branch diff vs the item's authorised paths
    python .aide/scripts/aide.py progress set NNN <in-progress|in-review|done>
    python .aide/scripts/aide.py progress set NNN deferred --reason TEXT  # ⏸️, with its why
    python .aide/scripts/aide.py progress set --stage N --deliverable K deferred --reason TEXT  # ⏸️ on a bullet with no item marker
    python .aide/scripts/aide.py progress set --stage N --deliverable K dropped --reason TEXT  # ❌ on one the stage does not need
    python .aide/scripts/aide.py progress set NNN resumed --reason TEXT  # ⏸️ back to 📋 (--stage N --deliverable K for an unmarked bullet)
    python .aide/scripts/aide.py progress set NNN dropped --reason TEXT  # ❌ on an item the stage does not need
    python .aide/scripts/aide.py progress set NNN restored --reason TEXT  # ❌ back to 📋 (--stage N --deliverable K for an unmarked bullet)
    python .aide/scripts/aide.py gate list|approve|decline [N|ID]  # human gates in progress.md
    python .aide/scripts/aide.py queue start NNN       # create the queue branch (--specs for specs-)
    python .aide/scripts/aide.py queue tidy NNN        # mark a superseded queue as completed
    python .aide/scripts/aide.py queue gate NNN        # raise a planned queue's plan-review gate
    python .aide/scripts/aide.py queue restack         # merge a stack of queue branches forward
    python .aide/scripts/aide.py queue pr [NNN]        # open the queue branch's draft PR
    python .aide/scripts/aide.py queue ready [NNN]     # mark the queue PR ready (--undo: back to draft)
    python .aide/scripts/aide.py queue discard NNN     # delete an empty queue branch (no commits past its base)
    python .aide/scripts/aide.py insights add|list|tick|archive|resolve  # the insight inbox
    python .aide/scripts/aide.py ledger abandon NNN --rounds N  # the ledger row for an item that never merged
    python .aide/scripts/aide.py claim [--queue NNN]   # pick + claim the next 📋 item
    python .aide/scripts/aide.py test                  # run the suite, recorded for merge to reuse
    python .aide/scripts/aide.py merge NNN [--base R]  # merge a validated item per git.mode
    python .aide/scripts/aide.py env                   # dependency report (git, origin, gh, runner, venv) + bootstrap
    python .aide/scripts/aide.py sync [--item NNN]     # preflight: fetch, clean-tree check, right branch
    python .aide/scripts/aide.py gc [--merged] [--yes] # delete claim branches whose work landed
    python .aide/scripts/aide.py status                # one-call roadmap-state report

The parsing/editing helpers are pure functions so they can be unit-tested without
touching git or the real filesystem (see ``.aide/scripts/tests``).
"""
from __future__ import annotations

import argparse
import ast
import contextlib
import fnmatch
import hashlib
import json
import os
import re
import shlex
import shutil
import signal
import subprocess
import sys
import tempfile
import time
import unicodedata
from pathlib import Path, PurePosixPath, PurePath
from typing import Callable, Collection, Dict, Iterator, List, NamedTuple, Optional, Sequence, Set, Tuple

# --------------------------------------------------------------------------- #
# Status icons (the format contract — see .aide/conventions.md)
# --------------------------------------------------------------------------- #
STATUS_TO_ICON = {
    "planned": "📋",
    "in-progress": "🚧",
    "in-review": "🔍",
    "complete": "✅",
    "deferred": "⏸️",
    "excluded": "❌",
}
ICON_TO_STATUS = {v: k for k, v in STATUS_TO_ICON.items()}
#: `in-review` sits between 🚧 and ✅ because it is strictly more advanced than
#: in-progress and strictly less than merged. It exists because ✅ used to mean
#: two different things depending on `git.mode`: under `auto-merge` the item was
#: merged, under `pr` it was pushed and awaiting a human — and everything
#: downstream read ✅ as "done", including the destructive sweep, which then
#: offered to delete the head branch of an open PR. **✅ now means merged, in
#: every mode**, and is set by `aide merge` when the merge actually happens.
RANK = {"planned": 0, "excluded": 1, "deferred": 2, "in-progress": 3,
        "in-review": 4, "complete": 5}
#: The statuses that still hold a dependent back. A dependency leaves the way
#: only by being merged (✅) or by leaving the queue's path (❌ excluded,
#: ⏸️ deferred, or 📋 in a withdrawn stage — `still_blocks`) — 🚧 and 🔍 both
#: block, because work in progress and work whose PR is still open are alike
#: missing from the base a dependent would branch from. Named once because
#: two separate decisions turn on it being the same set: which item `aide
#: claim` may offer, and whether a declared dependency actually orders two
#: specs (`queue_spec_findings`).
BLOCKING_STATUSES = ("planned", "in-progress", "in-review")


def still_blocks(n: int, item_status: Dict[int, str],
                 withdrawn: Collection[int] = ()) -> bool:
    """Whether item *n* still holds back what waits on it — a dependent, a
    queue-end item, or its queue's open state.

    `BLOCKING_STATUSES`, bar a 📋 item in *withdrawn* (`withdrawn_stage_items`,
    every bullet of it in a stage whose summary row is ❌): `claim` never
    offers one, so it has left the queue's way as a ❌ item has, and blocking
    on it stranded its dependents for good (issue #393). A 🚧 or 🔍 item of a
    withdrawn stage still blocks — live work until its owner drops it (§2).
    An item progress.md does not know counts as 📋. The one reading behind
    `queue_is_open`, `queue_end_holds`, `_pick_item`, the `none left` report,
    `_early_ready` and `check --queue`, so they cannot disagree.
    """
    st = item_status.get(n, "planned")
    return st in BLOCKING_STATUSES and not (st == "planned" and n in withdrawn)

# Icons may be multi-codepoint (⏸️ = U+23F8 U+FE0F), so match by alternation
# (longest first), never a character class.
_ICON_ALT = "(?:" + "|".join(re.escape(i) for i in sorted(ICON_TO_STATUS, key=len, reverse=True)) + ")"
_ICON_RE = re.compile(_ICON_ALT)
# A deliverable bullet: leading "- " then a status icon.
_BULLET_RE = re.compile(r"^(?P<indent>\s*[-*]\s*)(?P<icon>" + _ICON_ALT + r")")
_CHECKBOX_RE = re.compile(r"^(?P<pre>\s*[-*]\s*\[)(?P<mark>[ xX])(?P<post>\].*)$")
_STAGE_HEADER_RE = re.compile(r"^##\s+Stage\s+(\d+)\b(.*)$")
_ANY_HEADER_RE = re.compile(r"^#{1,2}\s+")
# A stage header's status icon is the TRAILING icon only (the "— <icon>" tail);
# an icon inside the title text is plain text.
_TRAILING_ICON_RE = re.compile(r"(" + _ICON_ALT + r")\s*$")


# Every file this CLI reads is project-owned and hand-editable — aide.toml and the
# docs/aide/ living documents. Windows editors (Notepad, PowerShell's Out-File,
# "Save as UTF-8" in several IDEs) prepend a BOM, and a leading U+FEFF breaks
# first-line parsing *silently*: on the 3.9 fallback parser a BOM'd aide.toml loses
# only its FIRST table, because "^\[table\]$" fails on that one line while every
# later table still matches. [project] vanishes (source_dir back to its default)
# while [git] is honoured — a half-correct config, no error, every command
# reporting success. On 3.11 the same file raises an uncaught TOMLDecodeError.
# "utf-8-sig" strips a BOM when present and is byte-identical to "utf-8" when
# absent, so it is the correct default for anything a human may have touched.
_ENCODING = "utf-8-sig"


#: The accepted item-reference forms, as ONE definition (see conventions.md §1):
#:   *(Item 006)*            a single item
#:   *(Items 006, 044)*      a list — what create-queue tells authors to write
#:   *(Items 089/090)*       a list, slash-separated
#:   *(Items 071–075)*       an inclusive range, hyphen or en-dash
#: Everything that asks "does this line reference item NNN" goes through
#: _referenced_item_numbers, so the answer cannot differ between callers. It did
#: once: the status parse read only the FIRST number of a list, while the
#: progress-set matcher read any number literally present. Items after the first
#: were then orphaned — planned forever on a ✅ bullet, holding their queue open
#: and (since the live queue is the lowest-numbered open one) stranding
#: `aide claim` on a finished queue, while `aide progress set` acted on them
#: happily.
#: A number that opens a `YYYY-MM-DD` date is not an item number, and this is
#: the guard that says so. Without it the provenance shape AGENT-CONTEXT.md
#: itself prescribes — `*(item NNN, YYYY-MM-DD, engine X.Y.Z)*` — parsed as the
#: list `NNN, 2026, -08, -30`, and the unguarded `int()` below raised. The blast
#: radius was the whole verb, not the line: `aide progress set` reads every line
#: of progress.md, so four evidence annotations written in the documented
#: convention took `progress set` down for EVERY item repo-wide until a human
#: approved rewording them (issue #120).
#:
#: Two alternatives on purpose. `-\d{1,2}-\d{1,2}` recognises the date tail;
#: the bare `\d` forbids the backtrack that would otherwise let `\d+` give back
#: digits ("2026" → "202") until the tail no longer starts at the cursor and
#: the lookahead passed anyway. A range keeps working: "-092" carries one
#: hyphen group, not two.
_ITEM_REF_NOT_A_DATE = r"(?!\d|-\d{1,2}-\d{1,2})"
_ITEM_REF_NUM = r"0*\d+" + _ITEM_REF_NOT_A_DATE
_ITEM_REF_GROUP_RE = re.compile(
    r"[Ii]tems?\s+(" + _ITEM_REF_NUM + r"(?:\s*[,/–-]\s*" + _ITEM_REF_NUM + r")*)")
_ITEM_REF_SPLIT_RE = re.compile(r"\s*[,/]\s*")
_ITEM_REF_RANGE_RE = re.compile(r"^0*(\d+)\s*[–-]\s*0*(\d+)$")
#: The second, independent hardening: what the split hands back must LOOK like
#: an item number before it is read as one. Either fix alone stops the crash;
#: both are kept because the regex is a statement about one known prose shape
#: while this is the invariant — a part that is not a number is provenance
#: prose to skip, never a traceback out of an unrelated verb.
_ITEM_REF_NUMBER_RE = re.compile(r"^0*\d+$")

#: An inclusive range wider than this is treated as a typo and contributes only
#: its endpoints, so a stray "Items 6-9999" cannot invent thousands of items.
_ITEM_RANGE_MAX_SPAN = 50


def _referenced_item_numbers(text: str) -> List[int]:
    """Every item number referenced in ``text``, ranges expanded inclusively."""
    nums: List[int] = []
    for group in _ITEM_REF_GROUP_RE.finditer(text):
        for part in _ITEM_REF_SPLIT_RE.split(group.group(1)):
            part = part.strip()
            if not part:
                continue
            rng = _ITEM_REF_RANGE_RE.match(part)
            if rng is None:
                if _ITEM_REF_NUMBER_RE.match(part):
                    nums.append(int(part))
                continue
            lo, hi = int(rng.group(1)), int(rng.group(2))
            if lo <= hi <= lo + _ITEM_RANGE_MAX_SPAN:
                nums.extend(range(lo, hi + 1))
            else:
                nums.extend((lo, hi))
    return nums


def _has_typo_range(text: str) -> bool:
    """Does ``text`` carry a range so wide the reader treats it as a typo?

    `_referenced_item_numbers` keeps only such a range's ENDPOINTS, so what it
    hands back is deliberately not what the author wrote — `Items 044-999` reads
    as {44, 999}, and 999 is an artifact of the typo, not an item. That is a
    safe misreading while it stays in memory. It is not safe for a caller that
    writes the numbers back into the document, which is why the desugar asks.
    """
    for group in _ITEM_REF_GROUP_RE.finditer(text):
        for part in _ITEM_REF_SPLIT_RE.split(group.group(1)):
            rng = _ITEM_REF_RANGE_RE.match(part.strip())
            if rng is None:
                continue
            lo, hi = int(rng.group(1)), int(rng.group(2))
            if not lo <= hi <= lo + _ITEM_RANGE_MAX_SPAN:
                return True
    return False


def _references_item(text: str, num: int) -> bool:
    """Does ``text`` reference item ``num`` in any accepted form?"""
    return num in _referenced_item_numbers(text)


#: The item-reference MARKER that closes a deliverable bullet —
#: `- 📋 <text>. *(Item 006)*` — the `*(…)*` suffix the templates prescribe
#: (§1 → progress.md calls it "the *(Item NNN)* suffix"). Only this trailing
#: marker ties items to the bullet: a reference elsewhere in the bullet's prose
#: ("absorbing *(Item 095)*'s scope") is free text and attributes nothing
#: (issue #99). Several adjacent markers at the end all count, and a trailing
#: period after the last one is tolerated.
_BULLET_MARKER_RE = re.compile(
    r"(?:\*\(\s*[Ii]tems?\s+[^)\n]*\)\*[ \t.]*)+$")


def _bullet_marker_item_numbers(last_line: str) -> List[int]:
    """Item numbers in the trailing marker of a bullet's final line, if any."""
    m = _BULLET_MARKER_RE.search(last_line)
    return _referenced_item_numbers(m.group(0)) if m else []


def _deliverable_bullet_spans(lines: List[str]) -> List[Tuple[int, int]]:
    """``(first, last)`` line indices of each deliverable bullet.

    A deliverable bullet is a ``_BULLET_RE`` line plus its wrapped continuation
    lines — indented text carrying no bullet marker of its own. A blank line, a
    non-deliverable bullet, or an unindented new block ends the span. This is
    the ONE definition of a bullet's extent; ``_parse_item_status`` (read) and
    ``set_item_status`` (write) both build on it, so "which bullet owns item
    NNN" cannot differ between the two directions.
    """
    spans: List[Tuple[int, int]] = []
    open_span = False
    for i, line in enumerate(lines):
        if _BULLET_RE.match(line):
            spans.append((i, i))
            open_span = True
        elif not line.strip() or re.match(r"^\s*[-*]\s", line) or not re.match(r"^\s+\S", line):
            open_span = False
        elif open_span:
            spans[-1] = (spans[-1][0], i)
    return spans


# --------------------------------------------------------------------------- #
# TOML config (tomllib on 3.11+, tiny fallback for the aide.toml subset on 3.9)
# --------------------------------------------------------------------------- #
DEFAULT_CONFIG: Dict[str, Dict[str, object]] = {
    "project": {"name": "project", "source_dir": "src", "tests_dir": "tests", "docs_dir": "docs/aide"},
    # `interpreter` names what `env --bootstrap` builds the venv from — a
    # command on PATH ("python3.12", "py -3.12") or an absolute path. Empty
    # means the Python running the CLI, which is whatever launched it: a
    # consumer whose dependency closure only resolves on 3.12 got a 3.14 venv
    # from an ambient conda, a source build that failed on cmake, and an
    # `env` that still said OK (issue #166). `bootstrap` is what the build
    # installs with, read by its first word in `bootstrap_argv` (issue #378).
    "python": {"venv": ".venv", "bootstrap": "pip install -e .[dev]",
               "test_command": "python -m pytest", "import_check": "",
               "interpreter": ""},
    "git": {"mode": "auto-merge", "main_branch": "main", "branch_prefix": "aide/"},
    # `review` names whether the item loop runs an adversarial read of the diff
    # alongside the spec-relative one (conventions.md §9). Prose-consumed by the
    # orchestrator, the way `clarify` is: "off" (default) runs the validator
    # alone; "background" also dispatches a reviewer concurrently with it, and
    # the merge waits for both. Off by default because a review round costs
    # tokens on every item, and a consumer with CI and hosted reviewers may
    # reasonably decline it (issue #151). `validation_rounds` is prose-consumed
    # the same way: the ceiling on build<->validate rounds per item. 5 leaves
    # room for quick fixes to different new failures; one that keeps coming
    # back is stopped by the orchestrator's escalation rule long before
    # (issue #264). `max_open_queues` is engine-read: `aide queue start`
    # refuses a queue branch that would take the number of unmerged ones past
    # it, and 1 is the one-queue-at-a-time flow. `plan_review` is read by
    # `aide queue gate`: which plan-review gate a newly planned queue gets —
    # "queue" (one per queue), "stage" (one per stage a queue opens) or
    # "none" (issue #302). Both are validated by `aide check`.
    "loop": {"queue_cap": 10, "validation_rounds": 5, "clarify": "assume",
             "claim_scope": "live-queue", "review": "off",
             "max_open_queues": 1, "plan_review": "queue"},
    "framework": {"repo": ""},
    # [validation] — named environment profiles for queue-end items and item
    # Validation sections: <name> = <python expression>, true iff the
    # environment provides the capability (e.g.
    # gpu = "__import__('torch').cuda.is_available()").
    "validation": {},
}


# Escape sequences this reader decodes inside a basic (double-quoted) string. TOML
# also defines \b \t \n \f \r \uXXXX \UXXXXXXXX; rather than half-implement them and
# quietly disagree with tomllib, an unlisted escape is a ConfigError (see below).
_BASIC_ESCAPES = {'"': '"', "\\": "\\"}


def _read_quoted_value(key: str, stripped: str, lineno: int) -> str:
    """Decode the quoted string at the start of ``stripped``, or raise ``ConfigError``.

    Finding where a string ENDS and extracting what it CONTAINS are the same scan, so
    they live in one function. Splitting them is what produced the bug this replaces:
    the validator walked the value escape-aware while the extractor used a naive
    ``split(quote, 1)[0]``, so ``msg = "he said \\"hi\\""`` passed validation and was
    then silently truncated to ``he said \\``.

    Single-quoted strings are TOML *literal* strings: no escapes, backslash is itself.
    Double-quoted are *basic* strings, where a backslash escapes the next character.
    """
    quote = stripped[0]
    out: List[str] = []
    i = 1
    while i < len(stripped):
        ch = stripped[i]
        if quote == '"' and ch == "\\":
            nxt = stripped[i + 1] if i + 1 < len(stripped) else ""
            if not nxt:
                raise ConfigError(
                    f"line {lineno}: unterminated escape in the value for key {key!r} — "
                    "a backslash at the end of a basic string escapes nothing"
                )
            if nxt not in _BASIC_ESCAPES:
                raise ConfigError(
                    f"line {lineno}: unsupported escape '\\{nxt}' in the value for "
                    f"key {key!r} — this minimal reader decodes only \\\\ and \\\"; "
                    f"use a single-quoted 'literal string' (backslashes are literal "
                    f"there) or forward slashes"
                )
            out.append(_BASIC_ESCAPES[nxt])
            i += 2
            continue
        if ch == quote:
            tail = stripped[i + 1:].lstrip()
            if tail and not tail.startswith("#"):
                raise ConfigError(
                    f"line {lineno}: trailing characters after the quoted value for "
                    f"key {key!r}: {tail!r}"
                )
            return "".join(out)
        out.append(ch)
        i += 1

    raise ConfigError(
        f"line {lineno}: unterminated string for key {key!r} — "
        f"the value opens with {quote} but never closes it"
    )


class ConfigError(Exception):
    """``aide.toml`` cannot be trusted — malformed, so its facts are unknowable.

    Raised instead of guessing. Every project fact the framework acts on comes from
    that file, so silently falling back to defaults would scope the builder at the
    wrong directory, pick the wrong git mode, or run the wrong test command while
    reporting success. ``main`` catches this and prints it as a plain error.
    """


class MissingTool(Exception):
    """A program a verb must run is not there, or cannot do its job — git
    refusing the repository it is pointed at (issue #352).

    Raised by the one guarded entry for each program the engine runs — `git`
    and the configured test command — and turned by ``main`` into
    ``aide <verb>: <sentence>`` and exit 1. Deliberately **not** an
    ``OSError``: the engine's best-effort readers catch ``OSError`` to degrade
    one answer, and a missing program is not one answer degraded but every
    later one — `_list_claim_branches` once read it as "no claim branches",
    so `merge` refused with "no claim branch found".
    """


class GitMissing(MissingTool):
    def __init__(self) -> None:
        super().__init__("git is not on PATH — install git or put it on PATH, "
                         "then re-run")


class GitRefused(MissingTool):
    """git ran, and could not read a repository whose `.git` is there."""

    def __init__(self, repo_root: Path, stderr: str) -> None:
        why = next((l.strip() for l in (stderr or "").splitlines() if l.strip()),
                   "git gave no reason")
        super().__init__(f"git cannot read the repository {repo_root} is in — "
                         f"{why}")


class RunnerMissing(MissingTool):
    def __init__(self, program: str, repo_root: Optional[Path] = None) -> None:
        # A path is read from the repository root, where the command runs.
        at = Path(program)
        if not at.is_absolute() and repo_root is not None:
            at = Path(repo_root) / at
        where = ("is not on PATH" if not ("/" in program or os.sep in program)
                 else "is not an executable file" if at.is_file()
                 else "does not exist")
        super().__init__(f"the test command '{program}' {where} — install it, "
                         f"or fix [python] test_command in aide.toml")


class ToolMisconfigured(MissingTool):
    """`.aide/local.toml` names where a program is, and it is not there — or
    the file cannot be read, so where it puts the program cannot be known
    (issue #353).

    Raised by `resolve_tool` and never passed over for whatever PATH holds:
    a key someone wrote is a decision, and a run that quietly used another
    `gh` or `git` than the one named would report on a machine nobody
    configured.
    """


#: The per-machine config, relative to the repository root: machine facts —
#: where a program is, the framework clone, sibling repos — that a committed
#: `aide.toml` may not hold. Gitignored; `local.toml.example` is its shape.
LOCAL_CONFIG = Path(".aide") / "local.toml"

#: The programs `[tools]` in `LOCAL_CONFIG` may locate for the engine to run.
#: `python` is in the table too, but it is only ever printed (`printed_python`).
RUN_TOOLS = ("gh", "git")


def _local_tools(repo_root: Path) -> Dict[str, object]:
    """The `[tools]` table of *repo_root*'s `.aide/local.toml`; empty when
    the file or the table is absent.

    Only the `[tools]` table's own lines are parsed. The other tables belong
    to an adapter's hooks, whose reader is lenient, so a file those hooks
    have always accepted — a double-quoted Windows path in `extra_repos`,
    say — never stops a git call here. A `[tools]` table that is there and
    cannot be read or parsed raises `ToolMisconfigured`: where it puts a
    program is then unknowable, and reading it as "nothing configured" is
    the silent fallback to PATH a key exists to prevent. Only a verb that
    runs a program asks, so one that runs none is untouched by it.

    Read on every ask, never cached: the file is a few lines, a spawn costs
    far more, and a cache would outlive an edit made between two verbs run in
    one process.
    """
    path = Path(repo_root) / LOCAL_CONFIG
    try:
        text = path.read_text(encoding=_ENCODING)
    except FileNotFoundError:
        return {}
    except (OSError, UnicodeDecodeError) as exc:
        if not path.exists():
            return {}
        raise ToolMisconfigured(f"{LOCAL_CONFIG.as_posix()} cannot be read "
                                f"({exc}), so where its [tools] table puts a "
                                f"program is unknown — fix or remove it") from None
    try:
        import tomllib  # type: ignore
        parse = tomllib.loads
    except ModuleNotFoundError:
        parse = _parse_toml
    table: List[str] = []
    inside = False
    top_level = True
    for line in text.splitlines():
        header = re.match(r"\s*\[(\[?)\s*([^\]]*?)\s*\]", line)
        if header:
            top_level = False
            name = header.group(2)
            inside = name == "tools" and not header.group(1)
            if inside:
                # Canonical, so the 3.9 reader — which knows only a bare
                # `[name]` line — sees the header a trailing comment hides.
                table.append("[tools]")
                continue
            if name.strip("\"'") == "tools":
                raise ToolMisconfigured(
                    f"{LOCAL_CONFIG.as_posix()}: {line.strip()} is not the "
                    f"[tools] table — write it as [tools] with one key per "
                    f"program")
        elif top_level and re.match(r"\s*[\"']?tools[\"']?\s*[.=]", line):
            raise ToolMisconfigured(
                f"{LOCAL_CONFIG.as_posix()}: {line.strip()} is not the [tools] "
                f"table — write it as [tools] with one key per program")
        if inside:
            table.append(line)
    if not table:
        return {}
    try:
        parsed = parse("\n".join(table) + "\n")
    except (ConfigError, ValueError) as exc:
        raise ToolMisconfigured(f"{LOCAL_CONFIG.as_posix()} is malformed "
                                f"({exc}), so where its [tools] table puts a "
                                f"program is unknown — fix it") from None
    return parsed.get("tools", {})


def _has_directory(command: str) -> bool:
    """Does *command* name a file by its path, rather than a name for PATH?"""
    return (os.path.isabs(command) or "/" in command
            or (os.sep != "/" and os.sep in command)
            or bool(os.altsep and os.altsep in command))


def _pathext_file(path: str) -> Optional[str]:
    """*path* with the first PATHEXT suffix that names a file, or None.

    `shutil.which` applies PATHEXT to a path only from Python 3.12, so on an
    older Windows interpreter `C:/tools/gh` would miss the `gh.exe` beside
    it — and `gh-2.40` its `gh-2.40.exe`: a dot is not always a suffix.
    """
    for ext in os.environ.get("PATHEXT", ".EXE;.CMD;.BAT").split(os.pathsep):
        if ext and os.path.isfile(path + ext):
            return path + ext
    return None


def resolve_tool(name: str, repo_root: Path,
                 path: Optional[str] = None) -> Optional[str]:
    """Where the program *name* is, for the engine to run: the one resolver
    every program the engine starts goes through (issue #353).

    For `gh` and `git` (`RUN_TOOLS`), a non-empty `[tools] <name>` in
    *repo_root*'s `.aide/local.toml` decides: a path (absolute, or relative
    to *repo_root*) must be an executable file, and a bare name is looked up
    on PATH. Either way, one that is not there raises `ToolMisconfigured`
    naming the key — never a fallback to PATH. Unset or empty, *name* is
    looked up on PATH, and ``None`` is "not there": the caller says what that
    means for it. Any other *name* — a test command's program — is only
    looked up, from *repo_root* when it carries a directory. `shutil.which`
    applies PATHEXT on Windows, so `gh` finds the `gh.exe` installed there.
    *path*, when given, is the search path a bare name is looked up on in
    place of this process's PATH — the one the program will run with, as
    `env --bootstrap`'s command does with the venv first (issue #378).
    """
    configured = _local_tools(repo_root).get(name) if name in RUN_TOOLS else None
    if configured is None or configured == "":
        command = name
    elif not isinstance(configured, str):
        raise ToolMisconfigured(f"[tools] {name} = {configured!r} in "
                                f"{LOCAL_CONFIG.as_posix()} is not a string — "
                                f"write a command on PATH or a path, in quotes")
    else:
        command = configured.strip()
    if _has_directory(command):
        where = Path(command)
        if not where.is_absolute():
            where = Path(repo_root) / where
        found = shutil.which(str(where))
        if found is None and os.name == "nt":
            found = _pathext_file(str(where))
    else:
        where = None
        found = (shutil.which(command) if path is None
                 else shutil.which(command, path=path))
    if found is not None or configured in (None, ""):
        return found
    if where is None:
        why = "is not on PATH"
    elif where.is_file():
        why = "is not an executable file"
    else:
        why = "does not exist"
    raise ToolMisconfigured(f"[tools] {name} = {configured!r} in "
                            f"{LOCAL_CONFIG.as_posix()} {why} — fix it, or "
                            f"remove the key to look for {name} on PATH")


def _git_unavailable(repo_root: Path) -> Optional[str]:
    """Why git cannot be run for *repo_root*, or None when it can."""
    try:
        return None if resolve_tool("git", repo_root) else "git is not on PATH"
    except ToolMisconfigured as exc:
        return str(exc)


def printed_python(repo_root: Optional[Path]) -> str:
    """The interpreter the engine prints in the commands it suggests:
    `[tools] python`, else ``python``.

    Printed, never run and never checked — a suggestion is not a spawn, and
    a malformed file reads as unset here, since every program the engine
    does run refuses on it already. Quoted when it holds a space, so a
    pasted `C:/Program Files/…` stays one word.
    """
    value = "python"
    if repo_root is not None:
        try:
            configured = _local_tools(repo_root).get("python")
        except ToolMisconfigured:
            configured = None
        if isinstance(configured, str) and configured.strip():
            value = configured.strip()
    return f'"{value}"' if " " in value else value


def aide_command(repo_root: Optional[Path], rest: str) -> str:
    """``<python> .aide/scripts/aide.py <rest>``, as the engine prints it."""
    return f"{printed_python(repo_root)} .aide/scripts/aide.py {rest}"


def _parse_toml(text: str) -> Dict[str, Dict[str, object]]:
    """Minimal TOML reader for the flat ``[table] key = value`` shape of aide.toml.

    Supports string/int/float/bool scalars and ``#`` comments. Used only when the
    stdlib ``tomllib`` (Python 3.11+) is unavailable, so the CLI and its tests run
    on the project's 3.9 venv too.

    Deliberately lenient about what it *ignores* (unknown lines, blank tables) but
    strict about what it would otherwise *misread*, because a wrong-but-plausible
    value is worse than a refusal: an unterminated quoted string used to yield the
    truncated text, so a typo became a believable answer on 3.9 while 3.11's tomllib
    rejected the same file. Quoted values are decoded by ``_read_quoted_value``,
    which raises ``ConfigError`` rather than guess — so both parser paths agree on
    which files are readable.
    """
    data: Dict[str, Dict[str, object]] = {}
    table: Optional[Dict[str, object]] = None
    for lineno, raw in enumerate(text.splitlines(), start=1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        m = re.match(r"^\[([A-Za-z0-9_.]+)\]$", line)
        if m:
            table = data.setdefault(m.group(1), {})
            continue
        if table is None or "=" not in line:
            continue
        key, _, value = line.partition("=")
        key = key.strip()
        value = value.strip()
        # A quoted value owns everything up to its closing quote — a '#' inside it is
        # data, not a comment — so it is scanned before any comment stripping. Only
        # an UNquoted value is truncated at '#'.
        if value and value[0] in "\"'":
            table[key] = _read_quoted_value(key, value, lineno)
            continue
        token = value.split("#", 1)[0].strip()
        if not token:
            raise ConfigError(f"line {lineno}: missing value for key {key!r}")
        if token.lower() in ("true", "false"):
            table[key] = token.lower() == "true"
        else:
            try:
                table[key] = int(token)
            except ValueError:
                try:
                    table[key] = float(token)
                except ValueError:
                    table[key] = token
    return data


def _config_error(path: Path, what: str, exc: object) -> "ConfigError":
    """One phrasing for every way ``aide.toml`` can fail, so they cannot drift.

    ``what`` distinguishes the causes a reader would act on differently: a file that
    ``is malformed`` needs an edit, one that ``cannot be read`` needs permissions or
    disk attention. The rest — naming the path, and why defaults are not an
    acceptable fallback — is identical in every case.
    """
    return ConfigError(
        f"{path} {what}: {exc}\n"
        f"  aide.toml states this project's facts (source_dir, git mode, test "
        f"command); refusing to continue with defaults that would be silently wrong."
    )


def load_config(repo_root: Path) -> Dict[str, Dict[str, object]]:
    """Load ``aide.toml`` merged over defaults.

    A *missing* file is fine — defaults apply, which is what an unconfigured repo
    means. A *malformed* file is not: it states project facts that cannot be read,
    so this raises ``ConfigError`` naming the file rather than falling back to
    defaults that would silently be wrong.
    """
    merged = {k: dict(v) for k, v in DEFAULT_CONFIG.items()}
    path = repo_root / "aide.toml"
    if path.is_file():
        try:
            text = path.read_text(encoding=_ENCODING)
        except UnicodeDecodeError as exc:
            raise _config_error(path, "is malformed", exc) from exc
        except OSError as exc:
            # Present but unreadable (permissions, a device error, a dangling
            # link). The file may be perfectly well-formed — say so accurately
            # rather than sending the reader to hunt for a syntax mistake.
            raise _config_error(path, "cannot be read", exc) from exc
        try:
            import tomllib  # type: ignore
        except ModuleNotFoundError:
            detail_source = _parse_toml
        else:
            # tomllib.TOMLDecodeError subclasses ValueError; catching ValueError
            # keeps this working if that relationship ever changes.
            detail_source = tomllib.loads
        try:
            parsed = detail_source(text)
        except (ConfigError, ValueError) as exc:
            # Both parsers report line/column but neither knows the path, and the
            # path is the one thing a reader needs to go fix it.
            raise _config_error(path, "is malformed", exc) from exc
        for section, values in parsed.items():
            merged.setdefault(section, {})
            if isinstance(values, dict):
                merged[section].update(values)
    return merged


#: `[loop] plan_review`'s values, in the order `aide queue gate -h` names them.
PLAN_REVIEW_VALUES = ("queue", "stage", "none")


def max_open_queues(config: Dict[str, Dict[str, object]]
                    ) -> Tuple[Optional[int], Optional[str]]:
    """``(cap, None)``, or ``(None, why)`` when ``[loop] max_open_queues`` is unusable.

    A positive integer and nothing else: a bool is an int to Python and a
    float or a quoted "2" reads as a number to a person, and each would be a
    cap nobody wrote. Refused rather than coerced, like every other value that
    decides what the loop may do unattended.
    """
    value = config.get("loop", {}).get("max_open_queues", 1)
    if isinstance(value, bool) or not isinstance(value, int) or value < 1:
        return None, (f"aide.toml [loop] max_open_queues = {value!r} is not a "
                      f"positive integer — it caps how many queue branches may "
                      f"be unmerged at once (default 1)")
    return value, None


def plan_review(config: Dict[str, Dict[str, object]]
                ) -> Tuple[Optional[str], Optional[str]]:
    """``(value, None)``, or ``(None, why)`` when ``[loop] plan_review`` is unusable."""
    value = config.get("loop", {}).get("plan_review", "queue")
    if not isinstance(value, str) or value not in PLAN_REVIEW_VALUES:
        return None, (f"aide.toml [loop] plan_review = {value!r} is not one of "
                      f"{', '.join(repr(v) for v in PLAN_REVIEW_VALUES)} — it "
                      f"decides which plan-review gate `aide queue gate` "
                      f"raises (default 'queue')")
    return value, None


#: `[git] mode`'s values. Every site compares against one of them, so any
#: other string — a `"Local"` — silently ran as `auto-merge` (issue #352).
GIT_MODE_VALUES = ("auto-merge", "pr", "local")


def git_mode_error(config: Dict[str, Dict[str, object]]) -> Optional[str]:
    """Why ``[git] mode`` is unusable, or ``None``."""
    value = config.get("git", {}).get("mode", "auto-merge")
    if isinstance(value, str) and value in GIT_MODE_VALUES:
        return None
    return (f"aide.toml [git] mode = {value!r} is not one of "
            f"{', '.join(repr(v) for v in GIT_MODE_VALUES)} — any other value "
            f"runs as 'auto-merge' (default 'auto-merge')")


#: `[git] forge`'s values: "github" is the one forge the engine can ask, through
#: `gh`; "none" declares there is none (issue #355).
GIT_FORGE_VALUES = ("github", "none")
#: `[git] ci`'s values: "pr" runs CI on the queue PR, "none" declares no CI.
#: There is no push-triggered value: the queue end reads only the PR.
GIT_CI_VALUES = ("pr", "none")


def declared_forge(config: Dict[str, Dict[str, object]]) -> str:
    """``[git] forge`` as the verbs act on it: ``none`` only when it says so.

    Any other value — ``github``, unset, or one `aide check` reports as an
    error — is ``github``, so a misspelt key keeps today's behaviour rather
    than silently dropping the queue PR.
    """
    return "none" if config.get("git", {}).get("forge") == "none" else "github"


def declared_ci(config: Dict[str, Dict[str, object]]) -> str:
    """``[git] ci`` as the verbs act on it: ``pr`` or ``none``.

    Unset, it follows the forge: ``pr`` on ``github``, ``none`` with no forge,
    since CI on a pull request needs a forge to hold one. A forge of ``none``
    is ``none`` whatever ``ci`` says; `aide check` reports the contradiction.
    """
    if declared_forge(config) == "none":
        return "none"
    return "none" if config.get("git", {}).get("ci") == "none" else "pr"


def git_forge_errors(config: Dict[str, Dict[str, object]]) -> List[str]:
    """Why ``[git] forge`` / ``[git] ci`` are unusable, alone or together."""
    git_cfg = config.get("git", {})
    errors: List[str] = []
    forge = git_cfg.get("forge", "github")
    if not (isinstance(forge, str) and forge in GIT_FORGE_VALUES):
        errors.append(
            f"aide.toml [git] forge = {forge!r} is not one of "
            f"{', '.join(repr(v) for v in GIT_FORGE_VALUES)} — any other "
            f"value runs as 'github' (default 'github')")
    ci = git_cfg.get("ci")
    if ci is not None and not (isinstance(ci, str) and ci in GIT_CI_VALUES):
        errors.append(
            f"aide.toml [git] ci = {ci!r} is not one of "
            f"{', '.join(repr(v) for v in GIT_CI_VALUES)} — any other value "
            f"runs as the default ('pr' with a forge, 'none' without)")
    if forge == "none":
        if git_cfg.get("mode", "auto-merge") == "pr":
            errors.append(
                'aide.toml [git] mode = "pr" with forge = "none": under pr a '
                "person opens each item's pull request on the forge, so the "
                'mode needs one — declare forge = "github", or set mode = '
                '"auto-merge" or "local"')
        if ci == "pr":
            errors.append(
                'aide.toml [git] ci = "pr" with forge = "none": CI on the '
                "queue PR needs a forge to hold the PR — set ci = \"none\", "
                'or declare forge = "github"')
    return errors


def loop_config_errors(config: Dict[str, Dict[str, object]]) -> List[str]:
    """``aide check``'s errors for the ``aide.toml`` keys the loop itself
    reads: ``[loop]`` ``max_open_queues`` and ``plan_review``, and ``[git]
    mode``, ``forge`` and ``ci``."""
    return [why for why in (max_open_queues(config)[1], plan_review(config)[1],
                            git_mode_error(config), *git_forge_errors(config))
            if why is not None]


def find_repo_root(start: Optional[Path] = None) -> Path:
    """Walk up from ``start`` (default cwd) to the directory holding aide.toml."""
    start = (start or Path.cwd()).resolve()
    for candidate in (start, *start.parents):
        if (candidate / "aide.toml").is_file():
            return candidate
    return start


def docs_dir(repo_root: Path, config: Dict[str, Dict[str, object]]) -> Path:
    return repo_root / str(config["project"].get("docs_dir", "docs/aide"))


# --------------------------------------------------------------------------- #
# progress.md — parsing helpers
# --------------------------------------------------------------------------- #
def _icon_status(text: str) -> Optional[str]:
    m = _ICON_RE.search(text)
    return ICON_TO_STATUS[m.group(0)] if m else None


def _header_status(line: str) -> Optional[str]:
    """A stage header's status — its trailing icon only."""
    m = _TRAILING_ICON_RE.search(line)
    return ICON_TO_STATUS[m.group(1)] if m else None


def _split_row(line: str) -> List[str]:
    return [c.strip() for c in line.strip().strip("|").split("|")]


def _structural_status(line: str) -> Optional[str]:
    """Status conveyed by a line's STRUCTURAL icon position only.

    Structural positions (the format contract, conventions.md §1): the leading
    icon of a deliverable bullet, a table row's Status (last) cell, and a stage
    header's trailing icon. An icon anywhere else on a line is plain text and
    is never read as status — prose stays free of the icon vocabulary.
    """
    m = _BULLET_RE.match(line)
    if m:
        return ICON_TO_STATUS[m.group("icon")]
    if line.strip().startswith("|"):
        cells = _split_row(line)
        return _icon_status(cells[-1]) if cells else None
    if _STAGE_HEADER_RE.match(line):
        return _header_status(line)
    return None


def stage_sections(lines: List[str]) -> List[Tuple[int, int, str]]:
    """Return ``(start_index, end_index_exclusive, stage_number)`` per stage section."""
    out: List[Tuple[int, int, str]] = []
    starts: List[Tuple[int, str]] = []
    for i, line in enumerate(lines):
        m = _STAGE_HEADER_RE.match(line)
        if m:
            starts.append((i, m.group(1)))
    for idx, (start, num) in enumerate(starts):
        end = len(lines)
        for j in range(start + 1, len(lines)):
            if _ANY_HEADER_RE.match(lines[j]):
                end = j
                break
        out.append((start, end, num))
    return out


def stage_deliverable_statuses(lines: List[str], start: int, end: int) -> List[str]:
    """Statuses of the flat deliverable bullets within a stage section."""
    statuses: List[str] = []
    for line in lines[start:end]:
        if _CHECKBOX_RE.match(line):
            continue
        m = _BULLET_RE.match(line)
        if m:
            statuses.append(ICON_TO_STATUS[m.group("icon")])
    return statuses


def rollup_status(statuses: List[str]) -> Optional[str]:
    """Derive a stage status from its deliverable statuses (None if no bullets)."""
    if not statuses:
        return None
    if all(s in ("complete", "excluded") for s in statuses) and any(
        s == "complete" for s in statuses
    ):
        return "complete"
    # 🔍 is deliberately absent from the set above: an item awaiting review has
    # not landed, so a stage holding one is 🚧, never ✅. That is the whole point
    # of the state — a `pr`-mode run must not roll a stage up to "shipped" on
    # work that is still an open PR.
    #
    # ⏸ is absent for the stronger version of the same reason (issue #173): a
    # deferred deliverable has landed even less than a reviewed one — it is a
    # decision to do the work *later*, so a stage still holding one has not
    # shipped. ❌ stays terminal because an excluded deliverable is a decision
    # not to do the work at all, and there is nothing left to wait for. This is
    # the distinction `scope` already draws one layer down, where the spent set
    # is `{complete, excluded}` and the comment says ⏸ claims are "dormant, not
    # dead"; the two read the same icon the same way now.
    #
    # ⏸ is a stage state of its own once nothing else is left open (issue
    # #281): every bullet ✅, ❌ or ⏸ with at least one ⏸ means the only work
    # the stage still holds is work someone decided to do later. Until 2.5.0
    # that stage read 📋 (or 🚧 beside a ✅), so a whole stage an owner had
    # deferred was indistinguishable from one nobody had started, in the file,
    # in `aide status` and in the planner's input. A 📋, 🚧 or 🔍 bullet beside
    # the ⏸ one still wins: that work is open, and the stage is not deferred.
    if any(s == "deferred" for s in statuses) and all(
        s in ("complete", "excluded", "deferred") for s in statuses
    ):
        return "deferred"
    if any(s in ("complete", "in-progress", "in-review") for s in statuses):
        return "in-progress"
    return "planned"


# --------------------------------------------------------------------------- #
# Outcome targets (optional table — see conventions.md §1)
# --------------------------------------------------------------------------- #
_TARGETS_HEADING_RE = re.compile(r"^#{1,2}\s+Outcome targets\b", re.IGNORECASE)
#: Table-local status vocabulary (like the env-gated verification table's):
#: the cell's LEADING mark decides, the rest is evidence/notes for humans.
_TARGET_STATUS_KIND = {"✅": "met", "❌": "not-met", "❓": "unverified"}


class OutcomeTarget(NamedTuple):
    lineno: int              # 1-based line number in progress.md
    text: str                # the Target cell
    objectives: List[str]    # G-codes named in the Objective cell
    kind: Optional[str]      # "met" | "not-met" | "unverified" | None (unrecognised)


#: The optional Environment-Gated Capability Verification table (§1 →
#: environment-gated capabilities). Outside the rollup like Outcome targets,
#: but gating nothing at all: its reader surfaces state, and warns.
_CAPABILITIES_HEADING_RE = re.compile(
    r"^#{1,2}\s+Environment-Gated Capability Verification\b", re.IGNORECASE)
_CAPABILITY_STATUS_KIND = {"✅": "verified", "❓": "unverified"}
#: A row's link to the `[validation]` profile that would verify it, written in
#: its Package / Tool cell as `` `gpu` profile `` or `` profile `gpu` ``.
_PROFILE_LINK_RE = re.compile(
    r"`([A-Za-z0-9_-]+)`\s+profile\b|\bprofile\s+`([A-Za-z0-9_-]+)`", re.IGNORECASE)
#: The introducing stage(s): the first `Stage N` / `Stages N, M` / `Stage 3 / 4`
#: / `Stages 5–7` run in the Introduced by cell. A later "closed by Stage 12"
#: names a different stage, which is why only the first run counts.
_INTRODUCED_BY_RE = re.compile(
    r"\bStages?\s+(\d+(?:\s*(?:,|/|&|\band\b|[-–])\s*\d+)*)", re.IGNORECASE)
#: A Notes cell holding only a dash records nothing.
_EMPTY_CELL = {"", "-", "—", "–"}


class GatedCapability(NamedTuple):
    lineno: int              # 1-based line number in progress.md
    text: str                # the Capability cell
    profiles: List[str]      # [validation] profiles the Package / Tool cell names
    stages: List[int]        # the stage(s) the Introduced by cell names first
    kind: Optional[str]      # "verified" | "unverified" | None (unrecognised)
    noted: bool              # the Notes cell records something
    #: Items the Introduced by cell references (`*(Item NNN)*`, the
    #: template's form) — how a spec declaring the capability finds its row.
    items: Tuple[int, ...] = ()


#: The optional `## Human gates` table — a decision only a person can make,
#: blocking work until they make it. Kept separate from acceptance boxes
#: deliberately: conventions.md §1 defines those as observable checks OF THE
#: BUILT THING, which a steering decision is not. Same reasoning that gave
#: Outcome targets their own table rather than overloading the checkboxes.
_GATES_HEADING_RE = re.compile(r"^#{1,2}\s+Human gates\b", re.IGNORECASE)
#: Table-local vocabulary, like Outcome targets': the LEADING mark decides.
_GATE_STATUS_KIND = {"⏳": "awaiting", "✅": "approved", "❌": "declined"}
#: A gate whose Blocks cell says this halts every item, everywhere — for a
#: programme-level decision ("no work proceeds until sign-off").
_GATE_BLOCKS_ALL = "all"
#: `stage N` — every item the named stage's deliverables reference. Blocking is
#: tied to a STAGE, never to a queue: a queue is an incidental batch boundary
#: (part of a stage, a stage, or several small ones), so "the live queue" names
#: different work from one week to the next while the decision has not changed.
#: A stage is the roadmap's own unit and means the same thing over time.
#:
#: Two wider forms reach several stages at once (#304): `stage N+` — stage N
#: and every stage numbered after it — and the closed range `stage N–M` (en
#: dash or hyphen). Without them, holding everything from a milestone on took
#: one row per stage, and a stage added to the roadmap later was not covered —
#: the one thing a reach that resolves live exists to avoid — while `all` also
#: held the stages before the milestone. "After" is by stage NUMBER, never by
#: position in the document: a stage heading is numeric only, and the number
#: is the stage's identity everywhere the engine reads one. The whole cell must
#: match, so `stage 6+` or `stage 6-8` can never fall through to the item
#: reader and be read as items 6 or 6–8.
_GATE_BLOCKS_STAGE_RE = re.compile(
    r"^stages?\s+0*(?P<first>\d+)"
    r"(?:\s*(?P<open>\+)|\s*[–-]\s*0*(?P<last>\d+))?$", re.IGNORECASE)


class HumanGate(NamedTuple):
    lineno: int              # 1-based line number in progress.md
    text: str                # the Gate cell
    blocks: List[int]        # item numbers named directly (empty for stage/all)
    stage: Optional[str]     # FIRST stage number of any stage reach, else None
    blocks_all: bool         # True when the cell reads "all"
    kind: Optional[str]      # "awaiting" | "approved" | "declined" | None
    #: The last stage of a closed ``stage N–M`` range; None for ``stage N``
    #: and ``stage N+``. Kept as written, so a reversed range stays visible to
    #: the check rather than being silently swapped.
    stage_last: Optional[int] = None
    #: True for ``stage N+`` — stage N and every later-numbered stage.
    stage_open: bool = False
    #: The Blocks cell as written, stripped. Read where "names nothing" must
    #: be told apart from "names something no reader parses" (issue #396).
    blocks_cell: str = ""

    @property
    def stage_range(self) -> Optional[Tuple[int, Optional[int]]]:
        """``(first, last)`` stage numbers this gate reaches, or None.

        ``last`` is None for an open ``stage N+`` reach; ``stage N`` is the
        one-stage range ``(N, N)``. A reversed range comes back reversed —
        it reaches nothing, and ``gate_warnings`` says so.
        """
        if self.stage is None:
            return None
        first = int(self.stage)
        if self.stage_open:
            return first, None
        return first, (first if self.stage_last is None else self.stage_last)

    @property
    def reach(self) -> str:
        """How far this gate reaches, for a human-readable report."""
        if self.blocks_all:
            return "all items"
        if self.stage is not None:
            if self.stage_open:
                return f"stage {self.stage}+"
            if self.stage_last is not None:
                return f"stage {self.stage}–{self.stage_last}"
            return f"stage {self.stage}"
        return ("items " + ", ".join(f"{i:03d}" for i in self.blocks)
                if self.blocks else "nothing named")


def stage_section(lines: List[str], stage: str) -> Optional[Tuple[int, int, str]]:
    """The stage section numbered *stage*, or None if no such section exists.

    The single place the "which section is stage N" lookup lives. Callers need
    to tell "no such stage" from "the stage is there and empty" — an absent
    section is a typo, an empty one is a stage nobody has queued work for yet —
    and a helper that collapses both into a falsy return makes that
    indistinguishable at every call site.
    """
    return next((sec for sec in stage_sections(lines)
                 if _same_stage(sec[2], stage)), None)


def stage_item_numbers(lines: List[str], stage: str) -> List[int]:
    """Item numbers referenced by *stage*'s deliverable bullets in progress.md.

    Reuses the §1 rule that only a deliverable bullet (and its wrapped
    continuation lines) carries an item reference, so a Notes cell or an
    acceptance checkbox naming an item does not widen a stage gate's reach.

    Empty for a stage that does not exist *and* for one whose deliverables name
    no item yet; ``stage_section`` is what separates the two.
    """
    section = stage_section(lines, stage)
    if section is None:
        return []
    start, end, _ = section
    return sorted(_parse_item_status(lines[start:end])[2])


def gate_stage_numbers(lines: List[str], g: "HumanGate") -> List[str]:
    """The stage numbers in progress.md that *g*'s stage reach covers, in order.

    Resolved on every read, like the stage's contents: a stage section added
    after the gate was raised is covered the moment it is written, which is
    what makes ``stage N+`` mean "from here on". Each number once, as
    ``stage_section`` finds the first section of a number; empty for a gate
    with no stage reach, for a reversed range, and for a reach that names no
    stage the document has yet.
    """
    rng = g.stage_range
    if rng is None:
        return []
    first, last = rng
    out: List[str] = []
    for _, _, num in stage_sections(lines):
        n = int(num)
        if n >= first and (last is None or n <= last) \
                and not any(_same_stage(num, seen) for seen in out):
            out.append(num)
    return out


def gate_stage_items(lines: List[str], g: "HumanGate") -> List[int]:
    """Item numbers *g*'s stage reach holds: the union of ``stage_item_numbers``
    over every stage it covers.

    The single resolver every stage-reach caller goes through — the claim
    filter, the claim stall report and the check's breadth — so ``stage N``,
    ``stage N+`` and ``stage N–M`` cannot resolve differently in two places.
    """
    items: Set[int] = set()
    for num in gate_stage_numbers(lines, g):
        items.update(stage_item_numbers(lines, num))
    return sorted(items)


def _blocked_item_numbers(cell: str) -> List[int]:
    """Item numbers in a gate's ``Blocks`` cell.

    Accepts the §1 reference forms (``Items 106, 110–112``) *and* the bare
    numbers an author naturally writes in a column already headed "Blocks"
    (``106``, ``110, 111``). The shared extractor keys off the word "Item", so
    a bare list would parse as **nothing** — and a gate blocking nothing is a
    gate that silently does not work, the one failure mode this table exists to
    prevent. Normalising the cell first reuses that extractor's list/range
    handling rather than growing a second dialect.
    """
    text = cell if re.search(r"\bitems?\b", cell, re.IGNORECASE) else f"Items {cell}"
    return _referenced_item_numbers(text)


# --------------------------------------------------------------------------- #
# progress.md tables — the rows a reader can use, and the rows it cannot
# --------------------------------------------------------------------------- #
_SUMMARY_HEADING_RE = re.compile(r"^#{1,2}\s+Stage summary\b", re.IGNORECASE)
_OBJECTIVES_HEADING_RE = re.compile(r"^#{1,2}\s+Objective coverage\b", re.IGNORECASE)


class _ProgressTable(NamedTuple):
    """One of the five ``progress.md`` tables the engine reads."""
    name: str                # how a finding names the table
    heading: "re.Pattern"    # the section the template puts the table under
    width: int               # cells in a data row
    header: str              # the header row's first cell, lower-cased
    #: Why a row of the right width is still unusable, or None.
    cell_problem: Callable[[List[str]], Optional[str]]
    #: What stops being checked while such a row is dropped.
    loses: str
    #: True for a table whose reader takes rows by shape from anywhere in the
    #: document rather than from under its heading — see ``_table_rows``.
    anywhere: bool = False
    #: False for a table no other check gates on, whose unusable row is
    #: therefore a warning: dropping it takes no error with it (issue #207).
    error: bool = True


def _summary_row_problem(cells: List[str]) -> Optional[str]:
    if not re.fullmatch(r"\d+", cells[0]):
        return "has a Stage cell that is not an integer"
    if not _icon_status(cells[3]):
        return "has no status icon in its Status cell"
    return None


def _objective_row_problem(cells: List[str]) -> Optional[str]:
    if not re.match(r"G\d+", cells[0]):
        return "has an Objective cell that does not start with a G<n> code"
    if not _icon_status(cells[2]):
        return "has no status icon in its Status cell"
    return None


def _target_row_problem(cells: List[str]) -> Optional[str]:
    """An Objective cell naming no ``G<n>`` is read: such a target gates no
    objective, which a measured cost or runtime target may mean to (`—`)."""
    return None if cells[0] else "has an empty Target cell"


_STAGE_SUMMARY = _ProgressTable(
    "stage summary", _SUMMARY_HEADING_RE, 4, "stage", _summary_row_problem,
    "its stage's ✅ is never checked against the deliverables under it",
    anywhere=True)
_OBJECTIVE_COVERAGE = _ProgressTable(
    "objective coverage", _OBJECTIVES_HEADING_RE, 3, "objective",
    _objective_row_problem,
    "its objective's ✅ is never checked against its Outcome targets",
    anywhere=True)
_OUTCOME_TARGETS = _ProgressTable(
    "Outcome targets", _TARGETS_HEADING_RE, 5, "target", _target_row_problem,
    "no objective is checked against it")
#: An unrecognised Status is read, and blocks — a typo in the mark must not
#: open a gate — so width is the only thing that makes a gate row unusable.
_HUMAN_GATES = _ProgressTable(
    "human-gate", _GATES_HEADING_RE, 4, "gate", lambda cells: None,
    "what it blocks is unknown, and `aide claim` holds every item until it "
    "is fixed")
_CAPABILITIES = _ProgressTable(
    "capability", _CAPABILITIES_HEADING_RE, 5, "capability",
    lambda cells: None if cells[0] else "has an empty Capability cell",
    "`aide status` never lists it and no closed stage is checked against it",
    error=False)
_PROGRESS_TABLES = (_STAGE_SUMMARY, _OBJECTIVE_COVERAGE, _OUTCOME_TARGETS,
                    _HUMAN_GATES, _CAPABILITIES)


def _reads(table: _ProgressTable, cells: List[str]) -> bool:
    """Whether *table*'s reader can use a row — the one test every reader of
    these tables applies, and the one the check reports the failures of."""
    return len(cells) == table.width and table.cell_problem(cells) is None


def _is_separator_row(cells: List[str]) -> bool:
    """The ``|---|:---:|`` row: every non-empty cell a delimiter, and one at least.

    Every cell, not the first: a gate titled ``-`` is data. And a NON-EMPTY
    one: `set("") <= set("-: ")` is true, so an empty first cell used to read
    as a separator, and a mis-shaped row like `| | 028 | ⏳ Awaiting | a | pipe |`
    was skipped without a word.
    """
    return (any(cells)
            and all(re.fullmatch(r":?-+:?", c) for c in cells if c))


def _is_table_furniture(cells: List[str], header: str) -> bool:
    """True for a table's header or separator row — never for data.

    A header is recognised by its first cell alone. Markdown's own rule — the
    row above the separator — would read the only row of a table written
    without a header as its header, and drop it unreported: an ``all`` gate
    raised by hand in a project whose optional section was deleted would
    then hold nothing.
    """
    return _is_separator_row(cells) or bool(cells) and cells[0].lower() == header


def _pipe_blocks(lines: List[str]) -> List[List[int]]:
    """Indices of each run of consecutive ``|`` lines — each markdown table."""
    blocks: List[List[int]] = []
    for i, line in enumerate(lines):
        if not line.strip().startswith("|"):
            continue
        if blocks and blocks[-1][-1] == i - 1:
            blocks[-1].append(i)
        else:
            blocks.append([i])
    return blocks


def _table_rows(lines: List[str], table: _ProgressTable
                ) -> Iterator[Tuple[int, List[str], Optional[str]]]:
    """``(index, cells, problem)`` for each data row of *table* in *lines*.

    *problem* is None for a row the table's reader can use (``_reads``), and
    otherwise says why it cannot. The rows are every ``|`` line in the section
    under the table's template heading — a second table there is read as part
    of this one, and fails closed. An ``anywhere`` table whose section holds
    no readable row — the heading missing, or the table under another one,
    where its reader still finds it by shape — also takes in every markdown
    table the reader takes a row from, so it is checked row by row all the
    same. (Not always: with a readable table under the heading, a table of the
    author's own elsewhere that happens to hold one summary-shaped row would
    have its every other row reported.) "Skipped" and "reported" are thereby
    one decision rather than two that can drift: issue #202 found three
    behaviours for the one situation, and the rows silently dropped were the
    ones taking an error with them.
    """
    scope: List[int] = []
    in_section = False
    for i, line in enumerate(lines):
        if table.heading.match(line):
            in_section = True
        elif in_section and _ANY_HEADER_RE.match(line):
            break  # next section — the table is over
        elif in_section and line.strip().startswith("|"):
            scope.append(i)
    if table.anywhere and not any(_reads(table, _split_row(lines[i])) for i in scope):
        scope = sorted(set(scope).union(
            i for block in _pipe_blocks(lines)
            if any(_reads(table, _split_row(lines[j])) for j in block)
            for i in block))
    for i in scope:
        cells = _split_row(lines[i])
        if _is_table_furniture(cells, table.header):
            continue
        yield i, cells, (f"has {len(cells)} cells, not {table.width}"
                         if len(cells) != table.width else table.cell_problem(cells))


def unreadable_row_errors(lines: List[str]) -> List[str]:
    """One error per row of a read table that its reader cannot use.

    An error, not a warning, because the row's cells cannot be trusted to be in
    position — the usual cause is a `|` that shifted them — so there is no
    telling whether it was a ✅ a check exists to catch. The check it would
    have fed cannot run, so the check fails on the row instead: the only
    reading of an unreadable row that cannot pass an over-claim.

    A table no check gates on (``error=False``) is the exception, reported by
    ``unreadable_row_warnings``: its dropped row carries no over-claim away.
    """
    return _unreadable_row_findings(lines, error=True)


def unreadable_row_warnings(lines: List[str]) -> List[str]:
    """``unreadable_row_errors``'s findings for the tables that gate nothing."""
    return _unreadable_row_findings(lines, error=False)


def _unreadable_row_findings(lines: List[str], error: bool) -> List[str]:
    out: List[str] = []
    for table, i, cells, problem in _unreadable_rows(lines):
        if table.error is not error:
            continue
        below = lines[i + 1] if i + 1 < len(lines) else ""
        if below.strip().startswith("|") and _is_separator_row(_split_row(below)):
            # Header position: most likely a retitled header, possibly the
            # only row of a table written without one. Say both.
            out.append(
                f"progress.md:{i + 1}: {table.name} row {problem}, above the "
                f"separator — a header row's first cell reads "
                f"'{table.header.capitalize()}'; as data, it is not read, so "
                f"{table.loses}.")
            continue
        hint = (" A '|' inside a cell is the usual cause."
                if len(cells) != table.width else "")
        out.append(f"progress.md:{i + 1}: {table.name} row {problem} — it "
                   f"is not read, so {table.loses}.{hint}")
    return out


def _unreadable_rows(lines: List[str]
                     ) -> List[Tuple[_ProgressTable, int, List[str], str]]:
    """``(table, index, cells, problem)`` for every row no reader can use."""
    return [(table, i, cells, problem) for table in _PROGRESS_TABLES
            for i, cells, problem in _table_rows(lines, table)
            if problem is not None]


def unreadable_gate_rows(lines: List[str]) -> List[Tuple[int, str]]:
    """``(line number, problem)`` for each ``## Human gates`` row no reader can use.

    ``aide claim`` holds every item while one exists: what the row blocks is
    unknown, so any item released could be one it was written to hold — the
    same fail-closed reading that makes an unrecognised Status block.
    """
    return [(i + 1, problem) for i, _, problem in _table_rows(lines, _HUMAN_GATES)
            if problem is not None]


def human_gates(lines: List[str]) -> List[HumanGate]:
    """Rows of the optional ``## Human gates`` table in progress.md.

    A gate is a decision only a person can make — approving a direction,
    signing off an irreversible change, confirming an out-of-band prerequisite
    arrived. It blocks work until resolved, and **no agent may resolve one**:
    that is the entire point, and the reason the state lives in a CLI-written
    table rather than a checkbox any role could tick.

    ``Blocks`` accepts the item-reference forms of §1 (``106``, ``106, 107``,
    ``106–108``), ``stage N`` for every item that stage's deliverables
    reference, ``stage N+`` / ``stage N–M`` for the same over every stage
    numbered from N on / from N to M, or ``all`` for a programme-level stop.

    A row of the wrong width is not a gate; ``unreadable_gate_rows`` reports
    it, and ``aide claim`` holds everything while it stands.
    """
    out: List[HumanGate] = []
    for i, cells, problem in _table_rows(lines, _HUMAN_GATES):
        if problem is not None:
            continue
        kind = next((k for icon, k in _GATE_STATUS_KIND.items()
                     if cells[2].startswith(icon)), None)
        blocks_cell = cells[1].strip()
        blocks_all = blocks_cell.lower() == _GATE_BLOCKS_ALL
        sm = _GATE_BLOCKS_STAGE_RE.match(blocks_cell)
        stage = sm.group("first") if sm else None
        stage_last = int(sm.group("last")) if sm and sm.group("last") else None
        if stage_last is not None and stage_last == int(stage):
            # `stage N–N` IS `stage N` (§1): one representation, so it prints,
            # resolves and is checked as the one-stage form everywhere.
            stage_last = None
        stage_open = bool(sm and sm.group("open"))
        blocks = [] if (blocks_all or stage) else _blocked_item_numbers(blocks_cell)
        out.append(HumanGate(i + 1, cells[0], blocks, stage, blocks_all, kind,
                             stage_last, stage_open, blocks_cell))
    return out


def blocking_gates(lines: List[str]) -> List[HumanGate]:
    """Gates still holding work up — every gate that is not ``✅ Approved``.

    **A declined gate keeps blocking.** It is *resolved* — a person decided —
    but the decision was "no", so releasing the work it guards would run
    exactly what was refused. The remedy is to re-plan (drop the item, or
    change what the gate asks), not to let the loop proceed. Only approval
    opens a gate.

    An unrecognised status also blocks: a typo in the mark must not silently
    open one.
    """
    return [g for g in human_gates(lines) if g.kind != "approved"]


def gate_blocked_items(lines: List[str]) -> Tuple[set, List[HumanGate]]:
    """``(blocked item numbers, block-everything gates)`` from the blocking gates.

    A stage gate resolves through progress.md to the items its stages'
    deliverables reference, so its reach follows the roadmap as the stages'
    contents change — which is the whole reason reach is anchored to a stage
    rather than to whichever queue happens to be live.
    """
    blocked, everything = set(), []
    for g in blocking_gates(lines):
        if g.blocks_all:
            everything.append(g)
        elif g.stage is not None:
            blocked.update(gate_stage_items(lines, g))
        else:
            blocked.update(g.blocks)
    return blocked, everything


# --------------------------------------------------------------------------- #
# gate IDs — the durable handle (conventions.md §1 → human gates, #293)
# --------------------------------------------------------------------------- #
#: The shortest hex a gate ID is printed with; lengthened per gate only as far
#: as it takes to tell apart two *different* Gate cells — see ``gate_ids``.
GATE_ID_MIN_HEX = 4
#: A gate ID as written: ``gate-`` then lowercase hex, a prefix of the Gate
#: cell's SHA-256. The word is part of the token, so the ID is its own
#: citation — no digit-only form, which is what a position looks like.
_GATE_ID_SHAPE = r"gate-[0-9a-f]{%d,64}" % GATE_ID_MIN_HEX
_GATE_ID_RE = re.compile(r"^gate-(?P<hex>[0-9a-f]{%d,64})$" % GATE_ID_MIN_HEX)


def gate_hash(gate: HumanGate) -> Optional[str]:
    """The full SHA-256 hex of a gate's Gate cell, or None when it has no ID.

    Only the Gate cell is hashed — the question the gate asks, which
    conventions.md §1 makes its identity. Status and Decision / evidence are
    what ``aide gate approve``/``decline`` write, and Blocks is re-planned
    while the question stands, so none of them moves the ID; nor does a merge
    that renumbers the rows, which is the defect the ID exists for (#293).

    Normalised like an insight claim: whitespace runs collapse to one space,
    Unicode is composed (NFC), nothing else is folded. An empty Gate cell asks
    nothing nameable and has no ID.
    """
    text = " ".join(unicodedata.normalize("NFC", gate.text).split())
    if not text:
        return None
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def gate_ids(gates: List[HumanGate]) -> List[Optional[str]]:
    """The printed ID of each gate in *gates*, aligned with it.

    ``gate-<hex>``, the hash cut to ``GATE_ID_MIN_HEX`` characters or longer
    only as far as it takes to differ from every *different* Gate cell in the
    table. Two rows asking the same question share an ID; ``resolve_gate_ref``
    reports that rather than guessing. A longer prefix of the same hash is the
    same ID, so one once written keeps resolving while its row stands.
    """
    hashes = [gate_hash(g) for g in gates]
    distinct = {h for h in hashes if h is not None}
    out: List[Optional[str]] = []
    for h in hashes:
        if h is None:
            out.append(None)
            continue
        others = [o for o in distinct if o != h]
        n = GATE_ID_MIN_HEX
        while n < len(h) and any(o.startswith(h[:n]) for o in others):
            n += 1
        out.append(f"gate-{h[:n]}")
    return out


def is_gate_id(ref: str) -> bool:
    """Does *ref* have the shape of a gate ID (not: does it resolve)?"""
    return _GATE_ID_RE.match(ref) is not None


def resolve_gate_ref(ref: str, gates: List[HumanGate]) -> List[int]:
    """Indices into *gates* whose Gate cell the ID *ref* names (hash prefix)."""
    m = _GATE_ID_RE.match(ref)
    if m is None:
        return []
    return [i for i, g in enumerate(gates)
            if (gate_hash(g) or "").startswith(m.group("hex"))]


def gate_index_for_ref(ref: str, gates: List[HumanGate]) -> int:
    """The 1-based position an ``N`` or a gate ID names, for a verb that edits.

    ``N`` is taken as it stands (``set_gate_status`` reports one out of
    range). An ID must name exactly one row: none is a gate that was removed
    or re-asked, and two is one question asked twice, which only a position
    tells apart. Raises ``ValueError`` with the reason.
    """
    if ref.isdigit():
        return int(ref)
    if not is_gate_id(ref):
        raise ValueError(
            f"{ref!r} is neither a gate number nor a gate ID "
            f"(gate-<hex>, as `aide gate list` prints it)")
    if not gates:
        raise ValueError("no '## Human gates' table in progress.md")
    hits = resolve_gate_ref(ref, gates)
    if not hits:
        raise ValueError(
            f"no gate {ref} in progress.md — its row was removed, or its Gate "
            f"cell reworded, which makes it a different gate; see `aide gate list`")
    if len({gate_hash(gates[i]) for i in hits}) > 1:
        ids = gate_ids(gates)
        raise ValueError(
            f"{ref} matches more than one gate — use the longer ID of the one "
            f"meant: {', '.join(sorted({ids[i] for i in hits}))}")
    if len(hits) > 1:
        raise ValueError(
            f"{ref} names {len(hits)} rows asking the same question (gates "
            f"{', '.join(str(i + 1) for i in hits)}) — resolve by position, "
            f"and reword one of them so each has its own ID")
    return hits[0] + 1


def outcome_targets(lines: List[str]) -> List[OutcomeTarget]:
    """Rows of the optional ``## Outcome targets`` table in progress.md.

    An outcome target is a MEASURED result the roadmap commits to (an error
    rate, a benchmark) — something shipped work can enable but never guarantee,
    so it is deliberately outside the stage rollup: a stage's ✅ keeps meaning
    "the planned work shipped", and goal truth lives here, gating the
    OBJECTIVE rows instead (an objective linked to a target that is not
    ``✅ Met`` cannot roll up to ✅).

    A row of the wrong width, or with an empty Target cell, is not read;
    ``unreadable_row_errors`` reports it.
    """
    out: List[OutcomeTarget] = []
    for i, cells, problem in _table_rows(lines, _OUTCOME_TARGETS):
        if problem is not None:
            continue
        kind = next((k for icon, k in _TARGET_STATUS_KIND.items()
                     if cells[3].startswith(icon)), None)
        out.append(OutcomeTarget(i + 1, cells[0], re.findall(r"G\d+", cells[1]), kind))
    return out


def _introducing_stages(cell: str) -> List[int]:
    """Stage numbers in the first ``Stage N`` run of an Introduced by cell."""
    m = _INTRODUCED_BY_RE.search(cell)
    if not m:
        return []
    stages: List[int] = []
    for part in re.split(r"\s*(?:,|/|&|\band\b)\s*", m.group(1), flags=re.IGNORECASE):
        bounds = re.split(r"\s*[-–]\s*", part)
        lo, hi = int(bounds[0]), int(bounds[-1])
        stages.extend(range(lo, hi + 1) if lo <= hi else [lo, hi])
    return stages


def gated_capabilities(lines: List[str]) -> List[GatedCapability]:
    """Rows of the optional Environment-Gated Capability Verification table.

    A row records whether a capability only some environments can exercise has
    had its gated path run for real — which a skip-clean suite and a ✅ stage
    never show. The table gates no stage, objective or claim, so every finding
    about it is a warning (issue #207).

    A row of the wrong width, or with an empty Capability cell, is not read;
    ``unreadable_row_warnings`` reports it.
    """
    out: List[GatedCapability] = []
    for i, cells, problem in _table_rows(lines, _CAPABILITIES):
        if problem is not None:
            continue
        kind = next((k for icon, k in _CAPABILITY_STATUS_KIND.items()
                     if cells[3].startswith(icon)), None)
        profiles = [a or b for a, b in _PROFILE_LINK_RE.findall(cells[1])]
        out.append(GatedCapability(
            i + 1, cells[0], list(dict.fromkeys(profiles)),
            _introducing_stages(cells[2]), kind,
            cells[4].strip() not in _EMPTY_CELL,
            tuple(_referenced_item_numbers(cells[2]))))
    return out


def capability_warnings(lines: List[str], profiles: Dict[str, object]) -> List[str]:
    """``aide check``'s findings over the capability table — warnings, all.

    *profiles* is ``[validation]`` from aide.toml: a row linking to a profile
    that is not there cannot be evaluated by ``aide status --profiles``.
    """
    summary: Dict[int, Optional[str]] = {}
    for line in lines:
        cells = _split_row(line) if line.strip().startswith("|") else []
        if cells and _reads(_STAGE_SUMMARY, cells):
            summary[int(cells[0])] = _icon_status(cells[3])
    out = unreadable_row_warnings(lines)
    for c in gated_capabilities(lines):
        where = f"progress.md:{c.lineno}: capability '{c.text}'"
        if c.kind is None:
            out.append(f"{where} has an unrecognised Status (expected "
                       f"'✅ Verified' or '❓ Unverified')")
        for name in c.profiles:
            if name not in profiles:
                out.append(f"{where} names profile '{name}', which [validation] "
                           f"in aide.toml does not define")
        closed = [s for s in c.stages if summary.get(s) == "complete"]
        if c.kind == "unverified" and closed and not c.noted:
            out.append(f"{where} is still ❓ Unverified under stage {closed[0]}, "
                       f"which is ✅, and its Notes cell records no reason")
    return out


# --------------------------------------------------------------------------- #
# progress.md — editing
# --------------------------------------------------------------------------- #
def _replace_first_icon(line: str, status: str) -> str:
    return _ICON_RE.sub(STATUS_TO_ICON[status], line, count=1)


def _sub_status_cell(line: str, status: str) -> str:
    """Replace the icon in a table row's Status (last) cell only.

    Icons in other cells (a title, an objective description) are plain text and
    must survive the edit untouched.
    """
    head, sep, tail = line.rpartition("|")
    if sep:
        body, sep2, cell = head.rpartition("|")
        if sep2:
            return body + "|" + _ICON_RE.sub(STATUS_TO_ICON[status], cell, count=1) + "|" + tail
    return _ICON_RE.sub(STATUS_TO_ICON[status], line, count=1)


def _held_by_hand(current: Optional[str], allow_downgrade: bool,
                  touched: bool) -> bool:
    """Whether a rolled-up cell is left exactly as it reads.

    ❌ always is: an excluded stage or objective is a decision no bullet
    speaks for. ⏸️ is until a verb moves a bullet of that stage (issue #281):
    the rollup computes ⏸️ itself now, so a ⏸️ it did not compute was set by
    hand, and it stands — `aide check` names the disagreement — rather than
    being rewritten by a `set` for some other stage's item. A verb acting on
    the stage's own bullets is the owner's next decision about it, and the
    cell then follows the bullets like any other.
    """
    if current == "excluded":
        return True
    return current == "deferred" and not (allow_downgrade or touched)


def _set_summary_row(lines: List[str], stage_num: str, status: str,
                     allow_downgrade: bool = False, touched: bool = False) -> None:
    for i, line in enumerate(lines):
        if not line.strip().startswith("|"):
            continue
        cells = _split_row(line)
        if len(cells) == 4 and cells[0] == stage_num and _icon_status(cells[3]):
            current = _icon_status(cells[3])
            if _held_by_hand(current, allow_downgrade, touched):
                return
            if allow_downgrade or RANK[status] >= RANK[current]:
                lines[i] = _sub_status_cell(line, status)
            return


def _set_stage_header(lines: List[str], start: int, status: str,
                      allow_downgrade: bool = False, touched: bool = False) -> None:
    line = lines[start]
    current = _header_status(line)
    if _held_by_hand(current, allow_downgrade, touched):
        return
    if current is None:
        lines[start] = line.rstrip() + f" — {STATUS_TO_ICON[status]}"
    elif allow_downgrade or RANK[status] >= RANK[current]:
        lines[start] = _TRAILING_ICON_RE.sub(STATUS_TO_ICON[status], line)


def _same_stage(a: str, b: str) -> bool:
    """Compare two stage numbers, ignoring zero-padding when both are numeric."""
    sa, sb = str(a).strip(), str(b).strip()
    if sa.isdigit() and sb.isdigit():
        return int(sa) == int(sb)
    return sa == sb


def acceptance_boxes(lines: List[str], start: int, end: int) -> List[int]:
    """Line indices of the acceptance checkboxes in one stage section, in order.

    An acceptance box is an *attestation*: a human states that an observable
    criterion holds. It is deliberately not derived from anything — the rollup
    skips checkbox lines (see ``stage_deliverable_statuses``), no ``aide check``
    rule gates a ✅ stage on them, and nothing else reads them. That is why
    ``set_item_status`` no longer ticks them as a side effect of a status
    change: a rollup cannot attest, and auto-ticking made the honest state
    "shipped, but this criterion is not met" impossible to keep — the same
    state Outcome targets exist to express at the objective level.

    Ticking now goes through ``aide progress accept``, which is deliberate,
    logged, and cannot be undone by an unrelated item's status change.
    """
    return [i for i in range(start, end) if _CHECKBOX_RE.match(lines[i])]


def accept_criteria(text: str, stage: str, criteria: Optional[List[int]],
                    evidence: Optional[str] = None) -> Tuple[str, List[str]]:
    """Tick acceptance boxes in *stage*; return (updated text, messages).

    ``criteria`` is a list of 1-based box indices, or None for every box in the
    stage. An already-ticked box is reported and left alone rather than being
    silently counted as newly accepted. Raises ``ValueError`` when the stage or
    an index does not exist — a typo'd stage must not pass as a no-op.

    The stage is matched numerically, so ``accept 6`` finds a section headed
    ``## Stage 06`` — ``stage_sections`` reports the header text verbatim, and
    a caller typing the correct number should not have to guess its padding.
    """
    lines = text.splitlines()
    section = stage_section(lines, stage)
    if section is None:
        raise ValueError(f"no Stage {stage} section in progress.md")
    start, end, _ = section
    boxes = acceptance_boxes(lines, start, end)
    if not boxes:
        raise ValueError(f"Stage {stage} has no acceptance checkboxes")
    wanted = list(range(1, len(boxes) + 1)) if criteria is None else criteria
    for n in wanted:
        if not 1 <= n <= len(boxes):
            raise ValueError(
                f"Stage {stage} has {len(boxes)} acceptance criteria; {n} is out of range")
    messages: List[str] = []
    for n in wanted:
        i = boxes[n - 1]
        m = _CHECKBOX_RE.match(lines[i])
        if m.group("mark") != " ":
            messages.append(f"criterion {n}: already ticked, unchanged")
            continue
        lines[i] = m.group("pre") + "x" + m.group("post")
        if evidence:
            # On the box's LAST line, which is its first only when it does not
            # wrap: an annotation dropped mid-criterion splits the sentence it
            # attests (issue #237).
            last = acceptance_box_last(lines, i, end)
            lines[last] = lines[last].rstrip() + f" *({evidence})*"
        messages.append(f"criterion {n}: accepted")
    return "\n".join(lines) + ("\n" if text.endswith("\n") else ""), messages


#: A correction line under an acceptance box: same shape as an insights.md
#: status trail (§1), and for the same reason — the attestation above it is
#: never reworded, so everything said *about* it afterwards goes underneath,
#: dated, newest last. Indentation is what separates a trail line from the next
#: box, so leading whitespace is required where `_CHECKBOX_RE` forbids it.
_ACCEPT_TRAIL_RE = re.compile(
    r"^(?P<indent>\s+)[-*]\s+\*\*(?P<date>\d{4}-\d{2}-\d{2})\*\*\s*→\s*(?P<text>.*)$")
#: The one trail prefix the tooling reads back. A correction is prose nobody
#: parses; a retraction changes what the box claims, so `check` and `status`
#: have to find it again after the fact.
_RETRACTED_PREFIX = "retracted: "
#: An attestation annotation, as `accept --evidence` writes it: a trailing
#: `*(…)*`. `reword` refuses over one — see `reword_criterion`. The body is
#: greedy and the close anchored at end of line, because evidence carrying its
#: own parentheses is ordinary ("(4 cores)", "(see §6)"): a `[^)]*` body
#: stopped at the first `)` and then matched nothing at all, so the guard
#: opened on exactly the annotations most worth keeping (#143).
_ACCEPT_EVIDENCE_RE = re.compile(r"\*\(.*\)\*\s*$")


#: A continuation line of a wrapped box: indented, non-blank, and not a bullet
#: — a bullet under a box is its trail (or a malformed one), never its text.
_BOX_CONTINUATION_RE = re.compile(r"^\s+(?![-*+]\s)\S")


def acceptance_box_last(lines: List[str], box: int, end: int) -> int:
    """Index of the last physical line of the acceptance box at *box*.

    A criterion is one sentence, and a hand- or template-authored file wraps
    it at a column: the box is its checkbox line **plus** every indented
    non-bullet line that follows, up to the next box, trail line, blank or
    section end (issue #237). Every writer that appends to a box or inserts
    under it starts from here — `accept --evidence`, `amend`, `retract`,
    `reword` — so a wrapped criterion keeps its sentence in one piece.
    """
    last = box
    for i in range(box + 1, end):
        if _BOX_CONTINUATION_RE.match(lines[i]) and not _ACCEPT_TRAIL_RE.match(lines[i]):
            last = i
            continue
        break
    return last


def acceptance_box_trail(lines: List[str], box: int, end: int) -> List[int]:
    """Line indices of the correction trail under the acceptance box at *box*.

    A box owns every indented trail line between it and the next box, header,
    or the end of its section. Returned in file order, so the last element is
    where the newest correction goes after. The scan starts below the box's
    last wrapped line, so a trail under a wrapped box is found, not mistaken
    for prose that ends it.
    """
    out: List[int] = []
    for i in range(acceptance_box_last(lines, box, end) + 1, end):
        if _ACCEPT_TRAIL_RE.match(lines[i]):
            out.append(i)
            continue
        if not lines[i].strip():
            # A blank line inside the trail is tolerated, but only if more
            # trail follows: a blank then prose ends the box.
            if any(_ACCEPT_TRAIL_RE.match(lines[j]) for j in range(i + 1, end)
                   if lines[j].strip()):
                continue
        break
    return out


def _resolve_box(text: str, stage: str, n: int) -> Tuple[List[str], int, int]:
    """``(lines, section_end, box_line_index)`` for criterion *n* of *stage*.

    The shared front half of amend/retract/reword: every one of them resolves
    exactly one box and refuses the same way when it cannot, so the error text
    a consumer sees does not depend on which verb they reached for.
    """
    lines = text.splitlines()
    section = stage_section(lines, stage)
    if section is None:
        raise ValueError(f"no Stage {stage} section in progress.md")
    start, end, _ = section
    boxes = acceptance_boxes(lines, start, end)
    if not boxes:
        raise ValueError(f"Stage {stage} has no acceptance checkboxes")
    if not 1 <= n <= len(boxes):
        raise ValueError(
            f"Stage {stage} has {len(boxes)} acceptance criteria; {n} is out of range")
    return lines, end, boxes[n - 1]


def _append_trail(lines: List[str], box: int, end: int, date: str, note: str) -> str:
    """Insert a dated trail line after the box at *box*; return the line written.

    Indentation follows an existing trail line when there is one, so a file
    that indents by four spaces keeps doing so.
    """
    return _insert_trail_line(lines, box, acceptance_box_last(lines, box, end),
                              acceptance_box_trail(lines, box, end), date, note)


def _insert_trail_line(lines: List[str], first: int, last: int,
                       trail: List[int], date: str, note: str) -> str:
    """Write one dated trail line below whatever owns *trail*; return it.

    *first* and *last* are the owner's first and last physical lines and
    *trail* its existing trail lines, file order. The one writer of the trail
    grammar (`_ACCEPT_TRAIL_RE`), shared by an acceptance box and a
    deliverable bullet alike, so the two cannot drift into two shapes. A first
    trail line sits two spaces in from its owner's own marker, so one under a
    nested bullet is nested under it rather than level with it; a later one
    follows the trail line before it.
    """
    owner = lines[first]
    indent = owner[: len(owner) - len(owner.lstrip())] + "  "
    if trail:
        prev = lines[trail[-1]]
        indent = prev[: len(prev) - len(prev.lstrip())]
    written = f"{indent}- **{date}** → {note}"
    lines.insert((trail[-1] if trail else last) + 1, written)
    return written


def amend_criterion(text: str, stage: str, n: int, note: str,
                    date: str) -> Tuple[str, str]:
    """Correct the evidence on a **ticked** acceptance box, append-only.

    The attestation stands; what was recorded about it was wrong or thin. The
    original line is never touched — that is the whole guard, and it is the
    same one insights.md's immutability rule buys: a verb that can only add
    cannot be used to make an inconvenient attestation agree with a shipped
    stage. Over-using it costs verbosity, never truth.

    Refuses on an unticked box, which has no attestation to correct: that is
    `accept` (to make one) or `reword` (to fix the criterion's wording).
    """
    lines, end, box = _resolve_box(text, stage, n)
    m = _CHECKBOX_RE.match(lines[box])
    if m.group("mark") == " ":
        raise ValueError(
            f"Stage {stage} criterion {n} is not ticked, so there is no "
            f"attestation to amend — `accept` records one, `reword` fixes the "
            f"criterion's wording")
    _append_trail(lines, box, end, date, note)
    return ("\n".join(lines) + ("\n" if text.endswith("\n") else ""),
            f"criterion {n}: amended ({date}) — {note}")


def retract_criterion(text: str, stage: str, n: int, reason: str,
                      date: str) -> Tuple[str, str]:
    """Untick a **ticked** acceptance box, keeping the original attestation.

    The sharp half of the pair: the criterion does not hold after all. The box
    goes back to `- [ ]` and both the original annotation and the retraction
    stay visible, so the record reads as "this was claimed, then withdrawn,
    for this reason" rather than as a box that was never ticked.

    A retraction is a *finding*, so `aide progress retract` routes it like one
    — an insights.md `gap` entry in the same commit (§1's Outcome-target rule,
    applied one level down). That is what keeps it cheap to be honest.
    """
    lines, end, box = _resolve_box(text, stage, n)
    m = _CHECKBOX_RE.match(lines[box])
    if m.group("mark") == " ":
        raise ValueError(
            f"Stage {stage} criterion {n} is already unticked — nothing to retract")
    written = _append_trail(lines, box, end, date, _RETRACTED_PREFIX + reason)
    # The trail was inserted below the box, so the box index still addresses it.
    lines[box] = m.group("pre") + " " + m.group("post")
    return ("\n".join(lines) + ("\n" if text.endswith("\n") else ""),
            f"criterion {n}: retracted — {reason}")


def reword_criterion(text: str, stage: str, n: int, new_text: str) -> Tuple[str, str]:
    """Reword an **unticked, unevidenced** acceptance criterion in place.

    The one amendment that edits rather than appends, and it is safe for
    exactly one reason: nothing has been claimed yet. The precondition is
    mechanical, so no instruction has to carry it — a box that is ticked, or
    annotated, or already carries a correction trail, has an attestation
    hanging off its wording, and rewording it would silently re-point that
    attestation at a different criterion.
    """
    if "\n" in new_text or "\r" in new_text:
        raise ValueError(
            "the criterion text may not contain a line break — it is written "
            "into a single checkbox line, and a break would split one "
            "criterion into two and renumber every box below it")
    lines, end, box = _resolve_box(text, stage, n)
    m = _CHECKBOX_RE.match(lines[box])
    last = acceptance_box_last(lines, box, end)
    # The wording is the whole box, continuation lines included: an annotation
    # sits on its last line, and the rewrite replaces every line of it.
    body = " ".join([m.group("post")[1:].strip()]
                    + [lines[i].strip() for i in range(box + 1, last + 1)])
    if m.group("mark") != " ":
        raise ValueError(
            f"Stage {stage} criterion {n} is ticked; its wording is what an "
            f"attestation was made against. Retract it first (`aide progress "
            f"retract`) if the criterion itself was wrong")
    annotation = _ACCEPT_EVIDENCE_RE.search(body)
    if annotation:
        raise ValueError(
            f"Stage {stage} criterion {n} carries an annotation "
            f"({annotation.group(0).strip()}), so "
            f"something has already been recorded against this wording")
    if acceptance_box_trail(lines, box, end):
        raise ValueError(
            f"Stage {stage} criterion {n} carries a correction trail, so "
            f"something has already been recorded against this wording")
    old = body.strip()
    lines[box] = m.group("pre") + m.group("mark") + "] " + new_text.strip()
    del lines[box + 1:last + 1]
    return ("\n".join(lines) + ("\n" if text.endswith("\n") else ""), old)


class Retraction(NamedTuple):
    """One retracted acceptance box, as `check` and `status` report it.

    ``date`` and ``reason`` are the box's **latest** retraction. ``reaccepted``
    is whether the box is ticked today — `accept` after a retraction is the
    path the retraction itself names — and ``reaccepted_on`` the date of the
    newest dated trail line after that retraction, or None when the tick left
    no dated line (``accept --evidence`` annotates the box line, not the trail).
    """

    stage: str
    criterion: int
    date: str
    reason: str
    reaccepted: bool = False
    reaccepted_on: Optional[str] = None


def _latest_trail_note(lines: List[str], trail: List[int], prefix: str
                       ) -> Optional[Tuple[str, str, Optional[str]]]:
    """``(date, text, newest later date)`` for the last *prefix* line of a trail.

    The trail is newest last, so the last matching line is the latest event,
    and any dated line after it is something that happened since. None when
    no trail line carries *prefix*.
    """
    hit: Optional[int] = None
    for pos, i in enumerate(trail):
        if _ACCEPT_TRAIL_RE.match(lines[i]).group("text").startswith(prefix):
            hit = pos
    if hit is None:
        return None
    tm = _ACCEPT_TRAIL_RE.match(lines[trail[hit]])
    later = [_ACCEPT_TRAIL_RE.match(lines[i]).group("date")
             for i in trail[hit + 1:]]
    return (tm.group("date"), tm.group("text")[len(prefix):].strip(),
            later[-1] if later else None)


def retracted_criteria(lines: List[str]) -> List[Retraction]:
    """One `Retraction` per acceptance box that was ever retracted.

    Read back out of the trail so `check` and `status` can surface it: a
    retraction that only ever appeared in one commit's diff is exactly the
    quiet the append-only rule exists to prevent. Keyed on the box's latest
    retraction and read against its tick today, so a box re-accepted since is
    reported as that rather than as open (issue #273) — and one retracted
    again after that is open, and reported by the second retraction.
    """
    out: List[Retraction] = []
    for start, end, num in stage_sections(lines):
        for n, box in enumerate(acceptance_boxes(lines, start, end), start=1):
            latest = _latest_trail_note(
                lines, acceptance_box_trail(lines, box, end), _RETRACTED_PREFIX)
            if latest is None:
                continue
            date, reason, later = latest
            ticked = _CHECKBOX_RE.match(lines[box]).group("mark") != " "
            out.append(Retraction(num, n, date, reason, ticked,
                                  later if ticked else None))
    return out


def retraction_summary(r: Retraction) -> str:
    """What `check` says about one retracted box — worded by its tick today."""
    if not r.reaccepted:
        return (f"stage {r.stage} criterion {r.criterion} was retracted on "
                f"{r.date} ({r.reason}) — the box is open again, and the "
                f"original attestation is kept above the correction")
    since = f"on {r.reaccepted_on}" if r.reaccepted_on else "since"
    return (f"stage {r.stage} criterion {r.criterion} was retracted on "
            f"{r.date} ({r.reason}) and re-accepted {since} — the box is "
            f"ticked again, and the retraction is kept in its trail")


#: The roadmap block whose bullets become a stage's acceptance boxes, and the
#: prefix that marks a bullet as an Outcome target instead (§1 → progress.md:
#: a measured outcome is deliberately NOT an acceptance box, so it must not
#: consume a box index when the two files are lined up).
_ROADMAP_ACCEPTANCE_RE = re.compile(r"^\*\*Validation\s*/\s*acceptance\.?\*\*", re.I)
_ROADMAP_BLOCK_END_RE = re.compile(r"^\*\*\S")
_ROADMAP_TARGET_RE = re.compile(r"^\s*[-*]\s+Target:", re.I)
#: Authoring guidance in the template — `_italic line_`, read then replaced.
#: It sits inside the block and is not a criterion.
_GUIDANCE_RE = re.compile(r"^\s*_.*_\s*$")


def roadmap_acceptance_bullets(lines: List[str], stage: str) -> Optional[List[int]]:
    """Line indices of *stage*'s acceptance bullets in roadmap.md, in order.

    ``None`` when the stage has no Validation / acceptance block at all — a
    roadmap that never mirrored the criteria, which is a different situation
    from one whose block disagrees with progress.md and must not be treated
    the same way (see ``_cmd_progress_reword``).

    ``Target:`` bullets are skipped: §1 routes a measured outcome to the
    Outcome-targets table precisely so it is not an acceptance box, so
    counting one here would slide every index below it by one.
    """
    section = stage_section(lines, stage)
    if section is None:
        return None
    start, end, _ = section
    head = next((i for i in range(start, end)
                 if _ROADMAP_ACCEPTANCE_RE.match(lines[i])), None)
    if head is None:
        return None
    out: List[int] = []
    for i in range(head + 1, end):
        line = lines[i]
        if _ROADMAP_BLOCK_END_RE.match(line):
            break
        if not line.strip() or _GUIDANCE_RE.match(line):
            continue
        if _ROADMAP_TARGET_RE.match(line):
            continue
        if re.match(r"^\s*[-*]\s+\S", line):
            out.append(i)
    return out


def reword_roadmap_bullet(text: str, stage: str, n: int, new_text: str,
                          expected: int) -> Tuple[Optional[str], Optional[str]]:
    """Mirror a reworded criterion into roadmap.md; ``(new_text, error)``.

    Returns ``(None, None)`` when the stage has no acceptance block to mirror —
    nothing to keep in step — and ``(None, <reason>)`` when there is one but it
    cannot be lined up with progress.md's *expected* box count. The caller
    writes neither file in that case: a rewording that lands in one document
    and not the other leaves exactly the two-file drift this verb exists to
    prevent.
    """
    lines = text.splitlines()
    bullets = roadmap_acceptance_bullets(lines, stage)
    if bullets is None:
        return None, None
    if len(bullets) != expected:
        return None, (
            f"roadmap.md stage {stage} lists {len(bullets)} acceptance "
            f"bullet{'' if len(bullets) == 1 else 's'} but progress.md has "
            f"{expected} box{'' if expected == 1 else 'es'}, so criterion {n} "
            f"cannot be matched across the two. Line them up by hand, then "
            f"re-run — nothing was written")
    i = bullets[n - 1]
    m = re.match(r"^(?P<pre>\s*[-*]\s+)(?P<body>.*)$", lines[i])
    lines[i] = m.group("pre") + new_text.strip()
    # A wrapped bullet is its first line plus every indented non-bullet line
    # under it, the shape `acceptance_box_last` reads on the progress side —
    # replace them all, or the old wording's tail stays under the new text
    # (issue #391).
    last = i
    while (last + 1 < len(lines)
           and _BOX_CONTINUATION_RE.match(lines[last + 1])
           and not _GUIDANCE_RE.match(lines[last + 1])):
        last += 1
    del lines[i + 1:last + 1]
    return "\n".join(lines) + ("\n" if text.endswith("\n") else ""), None


def acceptance_drift_warnings(ddir: Path, plines: List[str]) -> List[str]:
    """Stages whose acceptance box count disagrees with roadmap.md's mirror.

    §1 → progress.md says the Acceptance boxes come "from the matching roadmap
    stage", and `templates/roadmap.md` says the Validation / acceptance bullets
    become those boxes — the one mirror in §1 nothing enforced (issue #142).
    The observed drift: a consumer's stage carried a fourth, load-bearing box
    its roadmap never grew, and there was no moment at which anything would
    have said so. Since 1.35.0 the silence also has teeth: `aide progress
    reword` matches boxes to bullets by index and refuses on a drifted stage,
    so a consumer met a refusal with no tool that would say which stages drift
    or where.

    Counts, not text: comparing wording would fire on every honest tightening
    of a criterion's prose, which is exactly what `reword` exists to make
    cheap. The count is the signal that a criterion was *added or dropped* on
    one side only.

    A warning, never an error — a stage may legitimately be mid-replan, and a
    document set that was fine yesterday must not start failing today. Silent
    when roadmap.md is absent, when a stage has no roadmap section, and when
    its section has no Validation / acceptance block at all: no mirror is a
    different situation from a mirror that disagrees, and
    ``roadmap_acceptance_bullets`` keeps the two apart for `reword` already.
    """
    rpath = ddir / "roadmap.md"
    if not rpath.is_file():
        return []
    rlines = rpath.read_text(encoding=_ENCODING).splitlines()
    out: List[str] = []
    for start, end, stage in stage_sections(plines):
        bullets = roadmap_acceptance_bullets(rlines, stage)
        if bullets is None:
            continue
        boxes = len(acceptance_boxes(plines, start, end))
        if boxes != len(bullets):
            out.append(
                f"stage {stage}: progress.md has {boxes} acceptance "
                f"box{'' if boxes == 1 else 'es'} but roadmap.md's Validation "
                f"/ acceptance block lists {len(bullets)} "
                f"bullet{'' if len(bullets) == 1 else 's'} — a criterion was "
                f"added or dropped on one side only; line the two up by hand "
                f"('aide progress reword' refuses on this stage until they "
                f"agree)")
    return out


def _objective_stages(delivered_by: str) -> List[str]:
    return re.findall(r"\bStage[s]?\s+([\d,\s]+)", delivered_by)


def stage_rollups(lines: List[str]) -> Dict[str, str]:
    """Each stage's rollup over its Deliverables bullets, by stage number.

    A stage with no deliverable bullet has nothing to derive, and is absent.
    The one reading of "what the bullets say" that both the writer
    (`_recompute_rollups`) and `aide check` take a stage's status from.
    """
    out: Dict[str, str] = {}
    for start, end, stage_num in stage_sections(lines):
        derived = rollup_status(stage_deliverable_statuses(lines, start, end))
        if derived is not None:
            out[stage_num] = derived
    return out


def _objective_row_stages(delivered_by: str) -> List[str]:
    """The stage numbers an Objective row's Delivered-by cell is read as naming."""
    return re.findall(r"\d+", delivered_by)


def withdrawn_stages(lines: List[str]) -> Set[str]:
    """The stage numbers whose Stage summary row reads ❌ — withdrawn whole.

    A ❌ summary row is what excludes a stage (§1 → `progress.md`), and no
    rollup writes or overwrites one. Read by `objective_rollup`'s callers,
    so an objective is derived from the stages still in scope (issue #382).
    """
    out: Set[str] = set()
    for line in lines:
        cells = _split_row(line) if line.strip().startswith("|") else []
        if (cells and _reads(_STAGE_SUMMARY, cells)
                and _icon_status(cells[3]) == "excluded"):
            out.add(cells[0])
    return out


def withdrawn_stage_items(lines: List[str]) -> Dict[int, List[str]]:
    """Items every deliverable bullet of which sits in a withdrawn stage,
    each mapped to those stages' numbers (issue #387).

    A ❌ summary row withdraws the stage's work whatever its bullets still
    read (`withdrawn_stages`), so an item with a bullet in any stage still in
    scope, or outside every stage section, is not one: part of it is still
    wanted. Stage numbers are matched by value, so `Stage 07` is stage 7.
    """
    withdrawn = {str(int(s)) if s.isdigit() else s
                 for s in withdrawn_stages(lines)}
    if not withdrawn:
        return {}
    inside: Dict[int, List[str]] = {}
    rest = list(lines)
    for start, end, num in stage_sections(lines):
        if (str(int(num)) if num.isdigit() else num) not in withdrawn:
            continue
        for n in _parse_item_status(lines[start:end])[2]:
            inside.setdefault(n, []).append(num)
        rest[start:end] = [""] * (end - start)
    elsewhere = _parse_item_status(rest)[2]
    return {n: stages for n, stages in inside.items() if n not in elsewhere}


def spent_by_withdrawal(lines: List[str],
                        item_status: Dict[int, str]) -> Dict[int, str]:
    """Items whose claim branch is spent by a ❌ rather than a ✅, each with
    the words saying what the item is (issue #387): ``❌ (dropped)`` for an
    item ❌ by its own bullets, ``📋 in withdrawn stage N`` for one every
    bullet of which sits in a withdrawn stage — the stage is ❌, not the
    item, so the message says which.

    The ❌ half of §2's stale-claim ground, which `aide check`, `aide status`
    and `aide gc` read beside the ✅ half. The withdrawn-stage route takes a
    📋 item only (a ❌ one is ``dropped`` already): a 🚧 or ⏸️ item there is
    live or owner-held work, a ✅ one is the other half, and a 🔍 one's
    branch is an open PR's head — none is stale until its owner drops it
    (`aide progress set NNN dropped`), which puts it on the dropped ground.
    """
    out: Dict[int, str] = {n: "❌ (dropped)" for n, st in item_status.items()
                           if st == "excluded"}
    for n, stages in withdrawn_stage_items(lines).items():
        if n not in out and item_status.get(n, "planned") == "planned":
            out[n] = (f"📋 in withdrawn stage{'' if len(stages) == 1 else 's'} "
                      + ", ".join(stages))
    return out


def objective_rollup(nums: List[str], stage_status: Dict[str, str],
                     withdrawn: Set[str] = frozenset()) -> Optional[str]:
    """What an Objective row derives to from the stages it names — in full.

    The stage rule over the stages' own rollups (a stage never rolls up to
    ❌, so `rollup_status` reads them exactly as it reads bullets): ✅ when
    every named stage is ✅, ⏸️ when every one is ✅ or ⏸️, 🚧 when any is
    ✅ or 🚧, otherwise 📋. Both callers then hold a ✅ at 🚧 for a row linked
    to an Outcome target not ✅ Met (`_blocked_objectives`). A named number
    with no stage section, or one whose section has no bullet, contributes
    nothing; None when none does. No never-downgrade and no hand-held cell:
    those are the writer's (`_apply_objective_rollup`), and `aide check`
    compares a row with this (`derived_cell_findings`).

    A stage in *withdrawn* — its summary row ❌ (`withdrawn_stages`) — is left
    out, since its bullets no longer speak for it, and a row every named
    stage of which is withdrawn derives to ❌ (issue #382). Read from the
    bullets alone, a stage withdrawn with 📋 bullets held an objective it
    shared with a ✅ stage at 🚧 for good, and a ✅ typed there was an error.
    """
    live = [n for n in nums if n not in withdrawn]
    if nums and not live:
        return "excluded"
    return rollup_status([stage_status[n] for n in live if n in stage_status])


def _blocked_objectives(lines: List[str]) -> Set[str]:
    """G-codes linked to an Outcome target that is not ✅ Met."""
    return {g for t in outcome_targets(lines) if t.kind != "met"
            for g in t.objectives}


def _apply_objective_rollup(lines: List[str], stage_status: Dict[str, str],
                            downgrade_stages: Set[str] = frozenset(),
                            touched_stages: Set[str] = frozenset()) -> None:
    """Roll each Objective row up from the stages its Delivered-by cell names.

    The derivation is `objective_rollup`'s; what this adds is when a row may
    be written. Never downgrades a row, except one naming a stage in
    *downgrade_stages* — the stages a reopen or a deferral just sent back
    (issues #271, #281), and nothing else, so an unrelated row is never
    rewritten by it — and except to ⏸️: a row whose stages are all ✅ or ⏸️,
    at least one ⏸️, is ⏸️ whatever it read, since the work it still waits on
    is work deferred — and except a row naming a stage that rolls up to ⏸️,
    which `_recompute_rollups` writes down from any status, so the row
    follows it. A ⏸️ row is left alone unless it names a stage in either set
    (`_held_by_hand`).

    A stage whose summary row is ❌ is withdrawn and speaks for no row
    (issue #382): it is left out of the derivation and of the downgrade
    test, and a row every stage of which is withdrawn is written ❌ from any
    status, the one ❌ the writer puts on a row — what the summary rows
    already decided, so `aide check` finds nothing to report there."""
    # An objective linked to an outcome target that is not ✅ Met can never
    # roll up to ✅: its stages shipping is necessary but not sufficient.
    blocked = _blocked_objectives(lines)
    withdrawn = withdrawn_stages(lines)
    for i, line in enumerate(lines):
        if not line.strip().startswith("|"):
            continue
        cells = _split_row(line)
        gm = re.match(r"G\d+", cells[0]) if len(cells) == 3 else None
        if gm and _icon_status(cells[2]):
            nums = _objective_row_stages(cells[1])
            if not nums:
                continue
            current = _icon_status(cells[2])
            # Released by a verb only: a stage the calling verb moved. A ⏸️ row
            # set by hand stands through a `set` elsewhere (`_held_by_hand`).
            by_verb = any(n in downgrade_stages for n in nums)
            if _held_by_hand(current, by_verb,
                             any(n in touched_stages for n in nums)):
                continue
            # The downgrade itself mirrors `_recompute_rollups`: a stage that
            # rolls up to ⏸️ is written ⏸️ from any status, so a row naming
            # one must be free to follow it down too, or a stage that
            # self-heals from 🚧 to ⏸️ leaves its objective 🚧 over stages that
            # say ⏸️ and 📋 (issue #281, PR #284 review).
            allow_downgrade = by_verb or any(
                stage_status.get(n) == "deferred"
                for n in nums if n not in withdrawn)
            derived = objective_rollup(nums, stage_status, withdrawn)
            if derived is None or (derived == "planned" and not allow_downgrade):
                # 📋 only on a way down — a reopen or a deferral, or a row over
                # a stage that rolls up to ⏸️; otherwise the row stays as set.
                derived = current
            if derived == "complete" and gm.group(0) in blocked:
                derived = "in-progress"
            if (allow_downgrade or derived in ("deferred", "excluded")
                    or RANK[derived] >= RANK[current]):
                lines[i] = _sub_status_cell(line, derived)


def _spec_stage_and_title(repo_root: Path, config, number: int) -> Tuple[Optional[str], Optional[str]]:
    """(stage, title) from the item's spec header, best effort."""
    idir = docs_dir(repo_root, config) / "items"
    specs = item_spec_paths(idir, number)
    if not specs:
        return None, None
    text = specs[0].read_text(encoding=_ENCODING)
    tm = re.search(r"^#\s+Item\s+0*" + str(number) + r"\s*[—–-]\s*(.+?)\s*$", text, re.MULTILINE)
    sm = re.search(r"\*\*Stage:\*\*\s*(\d+)", text)
    return (sm.group(1) if sm else None), (tm.group(1) if tm else None)


def insert_item_reference(text: str, number: int, stage: str, title: str) -> Optional[str]:
    """Append a planned deliverable bullet for item ``number`` to the given
    stage's Deliverables block (used when a queue back-fill was missed, so
    ``progress set`` can self-heal instead of hard-erroring). Returns the
    updated text, or None when the stage section / Deliverables block is
    missing — that stays a loud error."""
    lines = text.splitlines()
    for start, end, snum in stage_sections(lines):
        if snum != str(stage):
            continue
        insert_at = next((i + 1 for i in range(start, end)
                          if lines[i].strip().startswith("**Deliverables")), None)
        # After the last bullet's WHOLE span, continuations included. Icon
        # line + 1 used to split a wrapped bullet in two — cosmetic while any
        # reference on any line attributed, but under the trailing-marker rule
        # (issue #99) the split strands the new bullet's marker mid-span and
        # hands the wrapped bullet's marker to the wrong owner.
        spans = _deliverable_bullet_spans(lines[start:end])
        if spans:
            # And after its correction trail: a bullet slipped in above a
            # `reopened:` line would take that line as its own (issue #271).
            last = start + spans[-1][1]
            trail = deliverable_bullet_trail(lines, last)
            insert_at = (trail[-1] if trail else last) + 1
        if insert_at is None:
            return None
        lines.insert(insert_at, f"- 📋 {title}. *(Item {number:03d})*")
        return "\n".join(lines) + ("\n" if text.endswith("\n") else "")
    return None


class BulletSplit(NamedTuple):
    """One shared-marker bullet ``_split_multi_item_bullets`` desugared.

    ``marker`` is the marker the bullet carried (``*(Items 044, 045)*``);
    ``copies`` is one ``(item number, 1-based line)`` per bullet it became,
    the line being the copy's first line in the text the split produced. The
    copies all carry the prose the shared bullet had, which described N items
    at once and now stands under each of them alone — the caller's job is to
    say so, since the file cannot (issue #169).
    """

    marker: str
    copies: List[Tuple[int, int]]


def _split_multi_item_bullets(lines: List[str], num: int, status: str,
                              splits: Optional[List[BulletSplit]] = None,
                              downgrade: bool = False) -> List[str]:
    """One bullet, one item: desugar a bullet that owns ``num`` *and* siblings.

    A trailing marker may name several items — ``*(Items 016, 017)*``, the form
    §1 → progress.md blesses and `/aide-create-queue` step 8 recommends — but a
    bullet carries ONE icon, and that icon is the status cell. So flipping the
    bullet for 016 also completed 017: never specced, never built, thereafter
    read as ✅ by everything that parses the file, and silently discounted from
    its queue's open count (issue #131). The engine's own writer had already
    modelled one item per bullet — `insert_item_reference` appends a singular
    marker — so the shape it told authors to write was one its status machinery
    could not represent.

    The form stays legal and desugars here: the bullet becomes one bullet per
    item, same text, one ``*(Item NNN)*`` each, in the marker's order. The item
    being flipped then moves alone and its siblings keep the status they had —
    the sibling protection issue #99 gave a prose mention, given to the list
    form that actually attributes.

    Only a flip that would ADVANCE the bullet splits it — or, with
    *downgrade*, one that would move it back at all (`progress reopen`, issue
    #271). A `progress set` that changes nothing must rewrite nothing:
    re-running one, or setting a status the bullet already holds, is not a
    reason to reshape a consumer's file.

    What the split writes is the shared prose, verbatim, N times. It cannot be
    otherwise — the bullet had one sentence for N items, and the engine has no
    other — but that leaves N−1 copies whose text describes work that is not
    the item named on them, and once one is ticked the file states something
    undone as done (issue #169: a consumer's ✅ line for item 045 described
    items 046/047's still-open work). So every split is *recorded* in
    ``splits``, and the callers print the copies as a chore that the author
    now owes; ``identical_deliverable_warnings`` keeps reporting them from
    `aide check` until each copy's prose is its own.
    """
    for start, last in reversed(_deliverable_bullet_spans(lines)):
        marker = _BULLET_MARKER_RE.search(lines[last])
        if marker is None:
            continue
        nums = list(dict.fromkeys(_referenced_item_numbers(marker.group(0))))
        if num not in nums or len(nums) < 2:
            continue
        # A range wider than the typo limit contributes only its endpoints, so
        # `nums` is not what the author wrote: `*(Items 044-999)*` would grow a
        # bullet for a phantom item 999, indistinguishable from a real one and
        # thereafter counted by `check`, `claim` and every queue rollup. Writing
        # fiction into the tracked document is worse than the shared cell this
        # function exists to remove, so a malformed marker keeps the old
        # behaviour and this leaves it exactly as the author typed it.
        #
        # Whole-bullet, deliberately: in `*(Items 006, 044-999)*` the sound half
        # keeps the shared cell too. Splitting the good elements while preserving
        # the malformed one is a lot of machinery for a marker whose own author
        # has already mistyped it, and the loud version — refusing the flip — is
        # worse, since it would strand a real item behind a typo in prose.
        if _has_typo_range(marker.group(0)):
            continue
        current = ICON_TO_STATUS[_BULLET_RE.match(lines[start]).group("icon")]
        if not current or status == current or (
                not downgrade and RANK[status] <= RANK[current]):
            continue
        head = lines[last][:marker.start()]
        # Whatever followed the last `)*` — the sentence-ending period the
        # marker regex tolerates — belongs to every copy, not just the first.
        matched = marker.group(0)
        tail = matched[len(matched.rstrip(" \t.")):]
        block: List[str] = []
        copies: List[Tuple[int, int]] = []
        span = last + 1 - start
        for n in nums:
            copy = lines[start:last + 1]
            copy[-1] = f"{head}*(Item {n:03d})*{tail}"
            copies.append((n, start + len(block) + 1))
            block.extend(copy)
        lines[start:last + 1] = block
        if splits is not None:
            # Spans are walked from the bottom, so a split here shifts every
            # copy already recorded below it by the lines this one grew.
            grown = len(block) - span
            splits[:] = [BulletSplit(s.marker, [(n, ln + grown if ln > start else ln)
                                                for n, ln in s.copies])
                         for s in splits]
            splits.append(BulletSplit(matched.rstrip(" \t."), copies))
    return lines


def set_item_status(text: str, num: int, status: str,
                    splits: Optional[List[BulletSplit]] = None) -> str:
    """Flip item NNN's deliverable bullet(s) to ``status`` and roll stages up.

    ``status`` is ``in-progress``, ``in-review`` or ``complete``. Updates summary/header/
    objective rows only for stages that fully complete. Never downgrades an
    existing status (additive log), and never touches an acceptance checkbox —
    those are human attestations, ticked only by ``aide progress accept``.
    A ⏸️ bullet ranks below all three, so setting one resumes deferred work
    (issue #281); ``defer_item`` is the way in, and takes a reason.

    A bullet whose marker names several items is split into one bullet per item
    first (see ``_split_multi_item_bullets``), so no sibling is carried along by
    a flip it did not earn. Each such split is appended to ``splits`` when the
    caller passes a list: the copies carry prose written for all the items at
    once, and the caller is the one who can say so (issue #169).
    """
    lines = text.splitlines()
    # A marker naming several items is one status cell for all of them, so the
    # bullet is desugared into one bullet per item BEFORE anything flips
    # (issue #131). After this the flip below can only move `num`.
    lines = _split_multi_item_bullets(lines, num, status, splits)
    # Flip the icon of every bullet whose trailing marker names this item —
    # the same ownership rule `_parse_item_status` reads by (issue #99), so a
    # bullet that merely mentions the item in prose is never flipped.
    touched: Set[str] = set()
    for start, last in _deliverable_bullet_spans(lines):
        if num not in _bullet_marker_item_numbers(lines[last]):
            continue
        current = ICON_TO_STATUS[_BULLET_RE.match(lines[start]).group("icon")]
        if current and RANK[status] > RANK[current]:
            lines[start] = _replace_first_icon(lines[start], status)
            stage = _stage_of_line(lines, start)
            if stage is not None:
                touched.add(stage)

    # Recompute rollups for every stage (never downgrading); a stage whose
    # bullet this moved lets go of a ⏸️ it no longer computes (issue #281).
    _recompute_rollups(lines, touched_stages=touched)
    return "\n".join(lines) + ("\n" if text.endswith("\n") else "")


def _recompute_rollups(lines: List[str],
                       downgrade_stages: Set[str] = frozenset(),
                       touched_stages: Set[str] = frozenset()) -> None:
    """Roll every stage header, summary row and Objective row up, in place.

    Never downgrades, except a stage in *downgrade_stages* and the Objective
    rows naming one: the stages a reopen or a deferral just sent back (issues
    #271, #281), whose rolled-up cells must follow the bullet down or
    `aide check` reports the drift the moment the verb lands. A stage that
    rolls up to ⏸️ is written ⏸️ from any status but ❌: ⏸️ ranks below 🚧,
    yet a stage whose last open bullet merged beside a deferred one has
    nothing in progress, and leaving it 🚧 would be the drift `check` reports.

    *touched_stages* are the stages whose bullets the calling verb moved; a
    ⏸️ cell there follows the rollup, where elsewhere it is left as set by
    hand (`_held_by_hand`).
    """
    stage_status = stage_rollups(lines)
    for start, end, stage_num in stage_sections(lines):
        derived = rollup_status(stage_deliverable_statuses(lines, start, end))
        if derived is None:
            continue
        down = stage_num in downgrade_stages or derived == "deferred"
        touched = stage_num in touched_stages
        _set_stage_header(lines, start, derived, allow_downgrade=down,
                          touched=touched)
        _set_summary_row(lines, stage_num, derived, allow_downgrade=down,
                         touched=touched)
    _apply_objective_rollup(lines, stage_status, downgrade_stages, touched_stages)


#: The trail prefix a reopen writes under a deliverable bullet — read back by
#: `check` and `status` exactly as `_RETRACTED_PREFIX` is under a box.
_REOPENED_PREFIX = "reopened: "


def deliverable_bullet_trail(lines: List[str], last: int) -> List[int]:
    """Line indices of the correction trail under the bullet ending at *last*.

    The trail lines immediately below the bullet's last wrapped line, in file
    order. `_deliverable_bullet_spans` ends a bullet at any line carrying a
    list marker, so a trail line is never part of the bullet — its marker is
    not read from one, and `_NESTED_DELIVERABLE_RE` never matches one, since
    it carries a date where a status bullet carries an icon.
    """
    out: List[int] = []
    for i in range(last + 1, len(lines)):
        if not _ACCEPT_TRAIL_RE.match(lines[i]):
            break
        out.append(i)
    return out


def _stage_of_line(lines: List[str], index: int) -> Optional[str]:
    for start, end, num in stage_sections(lines):
        if start <= index < end:
            return num
    return None


def reopen_item(text: str, num: int, reason: str, date: str,
                splits: Optional[List[BulletSplit]] = None) -> Tuple[str, str]:
    """Send a ✅ item back to 📋, append-only; ``(updated text, message)``.

    Every deliverable bullet whose trailing marker names *num* flips to 📋 and
    gains a dated ``reopened: <reason>`` trail line — the same grammar as an
    acceptance box's correction trail — and the stages holding them roll up
    with a downgrade allowed. Nothing else in the file changes: the bullet's
    own text and marker, other items, and every acceptance box stay as they
    were.

    Refuses unless every such bullet is ✅: an item that is not done has
    nothing to reopen, and one ✅ bullet beside a 🚧 one is not a closed item.
    A shared marker is desugared first, as `set` does, so no sibling is
    carried back with it.
    """
    lines = text.splitlines()
    owned = [(s, l) for s, l in _deliverable_bullet_spans(lines)
             if num in _bullet_marker_item_numbers(lines[l])]
    if not owned:
        raise ValueError(
            f"no deliverable bullet's trailing *(Item {num:03d})* marker names "
            f"item {num:03d}, so there is nothing to reopen")
    statuses = [ICON_TO_STATUS[_BULLET_RE.match(lines[s]).group("icon")]
                for s, _ in owned]
    if any(st != "complete" for st in statuses):
        shown = ", ".join(sorted({f"{STATUS_TO_ICON[st]} {st}" for st in statuses}))
        raise ValueError(
            f"item {num:03d} is {shown}, not ✅ — only a completed item can be "
            f"reopened")
    lines = _split_multi_item_bullets(lines, num, "planned", splits, downgrade=True)
    stages: Set[str] = set()
    # Bottom-up, so an inserted trail line never shifts a span still to visit.
    for start, last in reversed(_deliverable_bullet_spans(lines)):
        if num not in _bullet_marker_item_numbers(lines[last]):
            continue
        lines[start] = _replace_first_icon(lines[start], "planned")
        _insert_trail_line(lines, start, last,
                           deliverable_bullet_trail(lines, last),
                           date, _REOPENED_PREFIX + reason)
        stage = _stage_of_line(lines, start)
        if stage is not None:
            stages.add(stage)
    _recompute_rollups(lines, stages)
    return ("\n".join(lines) + ("\n" if text.endswith("\n") else ""),
            f"item {num:03d}: reopened — {reason}")


#: The trail prefix a deferral writes under a deliverable bullet (issue #281):
#: the why of a ⏸️, kept on the record the way a reopening's is.
_DEFERRED_PREFIX = "deferred: "
#: What `defer_item` moves to ⏸️. ✅ has shipped (`reopen` first) and ❌ was
#: decided against, so neither is work to postpone.
_DEFERRABLE = ("planned", "in-progress", "in-review")


def defer_item(text: str, num: int, reason: str, date: str,
               splits: Optional[List[BulletSplit]] = None) -> Tuple[str, str]:
    """Defer item NNN — its bullets to ⏸️, append-only; ``(updated text, message)``.

    Every deliverable bullet whose trailing marker names *num* and is 📋, 🚧 or
    🔍 flips to ⏸️ and gains a dated ``deferred: <reason>`` trail line — the
    grammar `reopen_item` writes — and the stages holding them roll up with a
    downgrade allowed, so a stage left with nothing but ⏸️ open reads ⏸️ and one
    whose 🚧 bullet was deferred falls back to what its other bullets say.

    Refuses when any such bullet is ✅ or ❌, naming the status found: shipped
    work is reopened first, and excluded work is not postponed. An item already
    ⏸️ throughout is no change, as a repeated `set` is. A shared marker is
    desugared first, as `set` does, so no sibling is deferred with it.
    """
    lines = text.splitlines()
    owned = [(s, l) for s, l in _deliverable_bullet_spans(lines)
             if num in _bullet_marker_item_numbers(lines[l])]
    if not owned:
        raise ValueError(
            f"no deliverable bullet's trailing *(Item {num:03d})* marker names "
            f"item {num:03d}, so there is nothing to defer")
    statuses = [ICON_TO_STATUS[_BULLET_RE.match(lines[s]).group("icon")]
                for s, _ in owned]
    final = [st for st in statuses if st not in _DEFERRABLE + ("deferred",)]
    if final:
        shown = ", ".join(sorted({f"{STATUS_TO_ICON[st]} {st}" for st in final}))
        hint = (" — send it back with `aide progress reopen` first"
                if "complete" in final else "")
        raise ValueError(
            f"item {num:03d} is {shown}; only a 📋, 🚧 or 🔍 item can be "
            f"deferred{hint}")
    if all(st == "deferred" for st in statuses):
        return text, f"item {num:03d}: no change (already deferred)"
    lines = _split_multi_item_bullets(lines, num, "deferred", splits, downgrade=True)
    stages: Set[str] = set()
    # Bottom-up, so an inserted trail line never shifts a span still to visit.
    for start, last in reversed(_deliverable_bullet_spans(lines)):
        if num not in _bullet_marker_item_numbers(lines[last]):
            continue
        current = ICON_TO_STATUS[_BULLET_RE.match(lines[start]).group("icon")]
        if current == "deferred":
            continue
        lines[start] = _replace_first_icon(lines[start], "deferred")
        _insert_trail_line(lines, start, last,
                           deliverable_bullet_trail(lines, last),
                           date, _DEFERRED_PREFIX + reason)
        stage = _stage_of_line(lines, start)
        if stage is not None:
            stages.add(stage)
    _recompute_rollups(lines, stages)
    return ("\n".join(lines) + ("\n" if text.endswith("\n") else ""),
            f"item {num:03d}: deferred — {reason}")


#: The trail prefix a resumption writes under a deliverable bullet (issue
#: #380): why deferred work is wanted now, beside the deferral's why.
_RESUMED_PREFIX = "resumed: "


def _item_bullet_statuses(lines: List[str], num: int) -> List[str]:
    """The statuses of every deliverable bullet whose trailing marker names
    item *num*, in file order — empty when none does."""
    return [ICON_TO_STATUS[_BULLET_RE.match(lines[s]).group("icon")]
            for s, l in _deliverable_bullet_spans(lines)
            if num in _bullet_marker_item_numbers(lines[l])]


def resume_item(text: str, num: int, reason: str, date: str,
                splits: Optional[List[BulletSplit]] = None) -> Tuple[str, str]:
    """Resume a deferred item — its ⏸️ bullets back to 📋, append-only;
    ``(updated text, message)`` (issue #380).

    The one way out of ⏸️ through `set`: a forward status on a ⏸️ item that
    was never claimed left it 🚧 with no branch, which `claim` never offers
    and `status` counts as work to build. 📋 is what `claim` hands out, so the
    item is claimable again — or, when a claim branch from before the
    deferral still exists, resumed on it by the runner. Every ⏸️ bullet whose
    trailing marker names *num* flips to 📋 and gains a dated ``resumed:
    <reason>`` trail line — the grammar `defer_item` writes — and the stages
    holding them roll up with a downgrade allowed, as a deferral's do.

    Refuses when any such bullet is 🚧, 🔍, ✅ or ❌, naming the status found:
    only postponed work is resumed, and a ❌ item was decided against rather
    than postponed. An item already 📋 throughout is no change, as a repeated
    deferral is. A shared marker is desugared first, so no sibling is resumed
    with it.
    """
    lines = text.splitlines()
    statuses = _item_bullet_statuses(lines, num)
    if not statuses:
        raise ValueError(
            f"no deliverable bullet's trailing *(Item {num:03d})* marker names "
            f"item {num:03d}, so there is nothing to resume")
    other = [st for st in statuses if st not in ("deferred", "planned")]
    if other:
        shown = ", ".join(sorted({f"{STATUS_TO_ICON[st]} {st}" for st in other}))
        raise ValueError(
            f"item {num:03d} is {shown}; only a ⏸️ deferred item can be "
            f"resumed")
    if "deferred" not in statuses:
        return text, f"item {num:03d}: no change (already 📋 planned)"
    lines = _split_multi_item_bullets(lines, num, "planned", splits, downgrade=True)
    stages: Set[str] = set()
    # Bottom-up, so an inserted trail line never shifts a span still to visit.
    for start, last in reversed(_deliverable_bullet_spans(lines)):
        if num not in _bullet_marker_item_numbers(lines[last]):
            continue
        if ICON_TO_STATUS[_BULLET_RE.match(lines[start]).group("icon")] != "deferred":
            continue
        lines[start] = _replace_first_icon(lines[start], "planned")
        _insert_trail_line(lines, start, last,
                           deliverable_bullet_trail(lines, last),
                           date, _RESUMED_PREFIX + reason)
        stage = _stage_of_line(lines, start)
        if stage is not None:
            stages.add(stage)
    _recompute_rollups(lines, stages)
    return ("\n".join(lines) + ("\n" if text.endswith("\n") else ""),
            f"item {num:03d}: resumed — {reason}")


#: The trail prefix a restoration writes under a deliverable bullet (issue
#: #381): why work decided against is wanted after all, beside the drop's why.
_RESTORED_PREFIX = "restored: "


def held_from_forward(lines: List[str], num: int) -> Optional[str]:
    """``"deferred"`` or ``"excluded"`` when a forward `set` must refuse item
    *num*, else None (issues #380, #381).

    An item is held only where the verb that takes it back to 📋 can: one
    whose bullets are all ⏸️ or 📋, at least one ⏸️, is ``resumed``'s, and
    one whose bullets are all ❌ or 📋, at least one ❌, is ``restored``'s. A
    ⏸️ or ❌ bullet beside started or settled work — only a hand edit makes
    one — is an item both verbs refuse, so the forward set stays its way out.
    `aide merge` reads the ❌ half; a ⏸️ item it still ticks.
    """
    bullets = set(_item_bullet_statuses(lines, num))
    for status in ("deferred", "excluded"):
        if status in bullets and bullets <= {status, "planned"}:
            return status
    return None


def _stages_left_all_dropped(lines: List[str], stages: Set[str]) -> List[str]:
    """Those of *stages* whose every deliverable bullet reads ❌ — the stage a
    drop must not leave behind, which the rollup reads as 📋 (issue #362).

    A stage already withdrawn — its summary row ❌ — is not one: the refusal
    exists to send the owner to that row, and its bullets no longer speak for
    the stage (issue #381, PR #386 review)."""
    out: List[str] = []
    withdrawn = withdrawn_stages(lines)
    for start, end, stage_num in stage_sections(lines):
        statuses = stage_deliverable_statuses(lines, start, end)
        if (stage_num in stages and stage_num not in withdrawn and statuses
                and all(st == "excluded" for st in statuses)):
            out.append(stage_num)
    return out


def drop_item(text: str, num: int, reason: str, date: str,
              splits: Optional[List[BulletSplit]] = None) -> Tuple[str, str]:
    """Drop item NNN as not needed — its open bullets to ❌, append-only;
    ``(updated text, message)`` (issue #381).

    The item form of `drop_deliverable`. No verb wrote ❌ on an item, so an
    abandoned item stayed 🚧, a carried one was hand-typed ❌, and one its
    owner decided against was a hand edit. Every 📋, 🚧, 🔍 or ⏸️ bullet
    whose trailing marker names *num* flips to ❌ and gains a dated
    ``dropped: <reason>`` trail line, and the stages holding them roll up
    with a downgrade allowed, as a deferral's do; ❌ counts toward ✅.

    Refuses an item no bullet names; one with a ✅ bullet, which shipped
    (`reopen` first); and a drop that would leave every deliverable bullet of
    a stage ❌, which the rollup reads as 📋 — that stage is withdrawn whole,
    by its ❌ summary row. An item already ❌ throughout is no change. A
    shared marker is desugared first, so no sibling is dropped with it.
    """
    lines = text.splitlines()
    statuses = _item_bullet_statuses(lines, num)
    if not statuses:
        raise ValueError(
            f"no deliverable bullet's trailing *(Item {num:03d})* marker names "
            f"item {num:03d}, so there is nothing to drop")
    if "complete" in statuses:
        raise ValueError(
            f"item {num:03d} is ✅ complete; it shipped, so there is nothing "
            f"to drop — send it back with `aide progress reopen` first")
    if all(st == "excluded" for st in statuses):
        return text, f"item {num:03d}: no change (already dropped)"
    lines = _split_multi_item_bullets(lines, num, "excluded", splits,
                                      downgrade=True)
    stages: Set[str] = set()
    # Bottom-up, so an inserted trail line never shifts a span still to visit.
    for start, last in reversed(_deliverable_bullet_spans(lines)):
        if num not in _bullet_marker_item_numbers(lines[last]):
            continue
        if ICON_TO_STATUS[_BULLET_RE.match(lines[start]).group("icon")] == "excluded":
            continue
        lines[start] = _replace_first_icon(lines[start], "excluded")
        _insert_trail_line(lines, start, last,
                           deliverable_bullet_trail(lines, last),
                           date, _DROPPED_PREFIX + reason)
        stage = _stage_of_line(lines, start)
        if stage is not None:
            stages.add(stage)
    emptied = _stages_left_all_dropped(lines, stages)
    if emptied:
        shown = ", ".join(emptied)
        raise ValueError(
            f"dropping item {num:03d} would leave every deliverable of stage "
            f"{shown} ❌, and a stage whose every deliverable is dropped has "
            f"nothing left to deliver — withdraw the stage whole instead, by "
            f"marking its row in the Stage summary table ❌, which takes its "
            f"header with it, and any Objective row only this stage delivers")
    _recompute_rollups(lines, stages)
    return ("\n".join(lines) + ("\n" if text.endswith("\n") else ""),
            f"item {num:03d}: dropped — {reason}")


def restore_item(text: str, num: int, reason: str, date: str,
                 splits: Optional[List[BulletSplit]] = None) -> Tuple[str, str]:
    """Restore a dropped item — its ❌ bullets back to 📋, append-only;
    ``(updated text, message)`` (issue #381).

    The one way out of ❌ through `set`: `RANK` puts ❌ lowest, so a forward
    status over a ❌ item used to flip it silently, with no reason and no
    trail line, and `aide merge` ticked it ✅ the same way. Both refuse a
    dropped item now and name this verb. Every ❌ bullet whose trailing
    marker names *num* flips to 📋 — what `claim` hands out — and gains a
    dated ``restored: <reason>`` trail line beside the drop's, and the stages
    holding them roll up with a downgrade allowed: a stage the ❌ let close
    is open work again.

    Refuses when any such bullet is 🚧, 🔍, ✅ or ⏸️, naming the status
    found: only work decided against is restored, and a ⏸️ one is resumed.
    An item already 📋 throughout is no change. A shared marker is desugared
    first, so no sibling is restored with it.
    """
    lines = text.splitlines()
    statuses = _item_bullet_statuses(lines, num)
    if not statuses:
        raise ValueError(
            f"no deliverable bullet's trailing *(Item {num:03d})* marker names "
            f"item {num:03d}, so there is nothing to restore")
    other = [st for st in statuses if st not in ("excluded", "planned")]
    if other:
        shown = ", ".join(sorted({f"{STATUS_TO_ICON[st]} {st}" for st in other}))
        hint = (f" — a ⏸️ item is resumed with `aide progress set {num:03d} "
                f"resumed --reason …`" if set(other) == {"deferred"}
                else "")
        raise ValueError(
            f"item {num:03d} is {shown}; only a ❌ dropped item can be "
            f"restored{hint}")
    if "excluded" not in statuses:
        return text, f"item {num:03d}: no change (already 📋 planned)"
    lines = _split_multi_item_bullets(lines, num, "planned", splits, downgrade=True)
    stages: Set[str] = set()
    # Bottom-up, so an inserted trail line never shifts a span still to visit.
    for start, last in reversed(_deliverable_bullet_spans(lines)):
        if num not in _bullet_marker_item_numbers(lines[last]):
            continue
        if ICON_TO_STATUS[_BULLET_RE.match(lines[start]).group("icon")] != "excluded":
            continue
        lines[start] = _replace_first_icon(lines[start], "planned")
        _insert_trail_line(lines, start, last,
                           deliverable_bullet_trail(lines, last),
                           date, _RESTORED_PREFIX + reason)
        stage = _stage_of_line(lines, start)
        if stage is not None:
            stages.add(stage)
    _recompute_rollups(lines, stages)
    return ("\n".join(lines) + ("\n" if text.endswith("\n") else ""),
            f"item {num:03d}: restored — {reason}")


def stage_deliverable_spans(lines: List[str], stage: str
                            ) -> Optional[List[Tuple[int, int]]]:
    """``(first, last)`` of each deliverable bullet in stage *stage*, in file
    order — ``None`` when no ``## Stage N`` section has that number.

    The bullets `stage_deliverable_statuses` rolls up, each with its wrapped
    continuation lines (`_deliverable_bullet_spans`), so position K here is
    the Kth status the rollup reads. The first section of the number wins, as
    the rollup's header write does.
    """
    for start, end, num in stage_sections(lines):
        if int(num) == int(stage):
            return [(s, l) for s, l in _deliverable_bullet_spans(lines)
                    if start <= s < end and not _CHECKBOX_RE.match(lines[s])]
    return None


def _unmarked_open_positions(lines: List[str], stage: str) -> List[int]:
    """1-based positions of stage *stage*'s 📋, 🚧 and 🔍 deliverable bullets
    that carry no item marker — the ones only `defer_deliverable` can defer."""
    spans = stage_deliverable_spans(lines, stage) or []
    out: List[int] = []
    for k, (start, last) in enumerate(spans, start=1):
        status = ICON_TO_STATUS[_BULLET_RE.match(lines[start]).group("icon")]
        if status in _DEFERRABLE and not _bullet_marker_item_numbers(lines[last]):
            out.append(k)
    return out


def _stage_can_lose_a_bullet(lines: List[str], stage: str) -> bool:
    """Whether dropping one of stage *stage*'s open bullets leaves a bullet
    that is not ❌ — the condition `drop_deliverable` refuses without, so a
    remedy names the drop only where it would be taken (issue #362)."""
    spans = stage_deliverable_spans(lines, stage) or []
    return sum(ICON_TO_STATUS[_BULLET_RE.match(lines[start]).group("icon")]
               != "excluded" for start, _ in spans) >= 2


def _unmarked_deliverable_at(lines: List[str], stage: int, position: int,
                             verb: str) -> Tuple[int, int, str, str]:
    """``(first, last, where, status)`` of stage *stage*'s *position*-th
    deliverable bullet, refusing one the positional forms cannot address.

    The lookup `defer_deliverable`, `drop_deliverable`, `resume_deliverable`
    and `restore_deliverable` share: an unknown
    stage, a position outside the stage's bullets (naming how many it has) and
    a bullet that carries an item marker are refused, each with a ValueError
    whose message *verb* words — an itemised bullet's status is its item's, so
    no positional form moves it, and the message names the item form.
    """
    spans = stage_deliverable_spans(lines, str(stage))
    if spans is None:
        raise ValueError(f"no '## Stage {stage}' section in progress.md")
    where = f"stage {stage} deliverable {position}"
    if not 1 <= position <= len(spans):
        count = (f"has {len(spans)} deliverable bullet"
                 f"{'' if len(spans) == 1 else 's'}, numbered from 1"
                 if spans else "has no deliverable bullet")
        raise ValueError(f"{where}: stage {stage} {count}")
    start, last = spans[position - 1]
    marked = _bullet_marker_item_numbers(lines[last])
    if marked:
        # Every positional status has its item form since issue #381, so the
        # refusal names it rather than only saying what the bullet is not.
        named = ", ".join(f"item {n:03d}" for n in marked)
        forms = " / ".join(f"`aide progress set {n:03d} {verb} --reason …`"
                           for n in marked)
        raise ValueError(
            f"{where} is itemised — its trailing marker names {named}, so "
            f"{_POSITIONAL_VERB[verb]} it by item with {forms}")
    current = ICON_TO_STATUS[_BULLET_RE.match(lines[start]).group("icon")]
    return start, last, where, current


#: The imperative each positional status's refusal words its item form with.
_POSITIONAL_VERB = {"deferred": "defer", "dropped": "drop",
                    "resumed": "resume", "restored": "restore"}


def _write_unmarked_deliverable(text: str, lines: List[str], start: int,
                                last: int, status: str, date: str,
                                trail: str) -> str:
    """Flip the bullet at *start* to *status*, write its dated *trail* line
    under *last*, and roll its stage up with a downgrade allowed — which also
    releases a ⏸️ cell held by hand, since a verb moved a bullet of the stage."""
    lines[start] = _replace_first_icon(lines[start], status)
    _insert_trail_line(lines, start, last, deliverable_bullet_trail(lines, last),
                       date, trail)
    stage_num = _stage_of_line(lines, start)
    _recompute_rollups(lines, {stage_num} if stage_num is not None else set())
    return "\n".join(lines) + ("\n" if text.endswith("\n") else "")


def defer_deliverable(text: str, stage: int, position: int, reason: str,
                      date: str) -> Tuple[str, str]:
    """Defer stage *stage*'s *position*-th deliverable bullet, one with no item
    marker; ``(updated text, message)`` (issue #336).

    `defer_item` addresses a bullet by its trailing ``*(Item NNN)*`` marker, so
    a bullet never itemised — a roadmap deliverable no queue has planned yet —
    had no route to ⏸️ but a hand edit, and a stage deferred by hand over such
    bullets warned for good. This is the same write addressed by position: the
    bullet flips to ⏸️, gains the dated ``deferred: <reason>`` trail line, and
    its stage rolls up with a downgrade allowed.

    Refuses an unknown stage, a position outside the stage's bullets (naming
    how many it has), a bullet that carries a marker (naming the ``set NNN
    deferred`` form that addresses it), and a ✅ or ❌ bullet. A bullet already
    ⏸️ is no change, as a repeated ``set NNN deferred`` is.
    """
    lines = text.splitlines()
    start, last, where, current = _unmarked_deliverable_at(
        lines, stage, position, "deferred")
    if current == "deferred":
        return text, f"{where}: no change (already deferred)"
    if current not in _DEFERRABLE:
        raise ValueError(
            f"{where} is {STATUS_TO_ICON[current]} {current}; only a 📋, 🚧 or "
            f"🔍 deliverable can be deferred")
    return (_write_unmarked_deliverable(text, lines, start, last, "deferred",
                                        date, _DEFERRED_PREFIX + reason),
            f"{where}: deferred — {reason}")


#: The trail prefix a drop writes under a deliverable bullet (issue #362): why
#: the stage turned out not to need it.
_DROPPED_PREFIX = "dropped: "
#: What `drop_deliverable` moves to ❌: any bullet still open, a deferred one
#: included — the issue's case is a ⏸️ bullet the owner then decides the stage
#: does not need. ✅ has shipped, so there is nothing left to drop.
_DROPPABLE = _DEFERRABLE + ("deferred",)


def drop_deliverable(text: str, stage: int, position: int, reason: str,
                     date: str) -> Tuple[str, str]:
    """Drop stage *stage*'s *position*-th deliverable bullet, one with no item
    marker, as not needed; ``(updated text, message)`` (issue #362).

    A ⏸️ bullet is kept out of the ✅ rule (#173), so a started stage whose
    only open bullet the owner had deferred could roll up no further than ⏸️ —
    and a stage whose Dependencies name it could never see it met. A drop is
    the other decision about such a bullet: the stage does not need it. The
    bullet flips to ❌, which counts toward ✅, gains a dated ``dropped:
    <reason>`` trail line, and its stage rolls up with a downgrade allowed, as
    a deferral's does.

    Refuses an unknown stage, a position outside the stage's bullets, a bullet
    that carries a marker, a ✅ bullet, and a drop that would leave every
    deliverable bullet of the stage ❌ — which the rollup reads as 📋, a stage
    still to plan. A stage with nothing left to deliver is withdrawn whole, by
    a ❌ on its summary row, which no rollup overwrites, and on any Objective
    row only it delivers. A bullet already ❌ is no
    change.
    """
    lines = text.splitlines()
    start, last, where, current = _unmarked_deliverable_at(
        lines, stage, position, "dropped")
    if current == "excluded":
        return text, f"{where}: no change (already dropped)"
    if current not in _DROPPABLE:
        raise ValueError(
            f"{where} is {STATUS_TO_ICON[current]} {current}; it shipped, so "
            f"there is nothing to drop — only a 📋, 🚧, 🔍 or ⏸️ deliverable "
            f"can be dropped")
    others = [ICON_TO_STATUS[_BULLET_RE.match(lines[first]).group("icon")]
              for first, _ in stage_deliverable_spans(lines, str(stage)) or []
              if first != start]
    # A stage already withdrawn by its ❌ summary row is not refused: the
    # refusal points at that row, which already says it (PR #386 review).
    if (all(st == "excluded" for st in others)
            and str(stage) not in withdrawn_stages(lines)):
        raise ValueError(
            f"{where} is the last deliverable of stage {stage} not ❌, and a "
            f"stage whose every deliverable is dropped has nothing left to "
            f"deliver — withdraw the stage whole instead, by marking its row "
            f"in the Stage summary table ❌, which takes its header with it, and "
            f"any Objective row only this stage delivers")
    return (_write_unmarked_deliverable(text, lines, start, last, "excluded",
                                        date, _DROPPED_PREFIX + reason),
            f"{where}: dropped — {reason}")


def resume_deliverable(text: str, stage: int, position: int, reason: str,
                       date: str) -> Tuple[str, str]:
    """Resume stage *stage*'s *position*-th deliverable bullet, one with no
    item marker, from ⏸️ back to 📋; ``(updated text, message)`` (issue #380).

    The positional mirror of `resume_item`. A deferred bullet no marker names
    used to resume only "once it is itemised" — but an item born on a ⏸️
    bullet is ⏸️ itself, so its queue read as done the moment it was written.
    The bullet is resumed first, here, and itemised as a 📋 one. It gains a
    dated ``resumed: <reason>`` trail line and its stage rolls up with a
    downgrade allowed, as a deferral's does.

    Refuses an unknown stage, a position outside the stage's bullets, a bullet
    that carries a marker, and a bullet that is not ⏸️ — a ❌ one was decided
    against, not postponed. A bullet already 📋 is no change.
    """
    lines = text.splitlines()
    start, last, where, current = _unmarked_deliverable_at(
        lines, stage, position, "resumed")
    if current == "planned":
        return text, f"{where}: no change (already 📋 planned)"
    if current != "deferred":
        raise ValueError(
            f"{where} is {STATUS_TO_ICON[current]} {current}; only a ⏸️ "
            f"deferred deliverable can be resumed")
    return (_write_unmarked_deliverable(text, lines, start, last, "planned",
                                        date, _RESUMED_PREFIX + reason),
            f"{where}: resumed — {reason}")


def restore_deliverable(text: str, stage: int, position: int, reason: str,
                        date: str) -> Tuple[str, str]:
    """Restore stage *stage*'s *position*-th deliverable bullet, one with no
    item marker, from ❌ back to 📋; ``(updated text, message)`` (issue #381).

    The positional mirror of `restore_item`, and the way back from
    `drop_deliverable`: a drop was the one decision about such a bullet that
    had no undo but typing 📋 over it. The bullet gains a dated ``restored:
    <reason>`` trail line beside the drop's, and its stage rolls up with a
    downgrade allowed — a stage the drop let close is open work again.

    Refuses an unknown stage, a position outside the stage's bullets, a bullet
    that carries a marker, and a bullet that is not ❌ — a ⏸️ one is resumed.
    A bullet already 📋 is no change.
    """
    lines = text.splitlines()
    start, last, where, current = _unmarked_deliverable_at(
        lines, stage, position, "restored")
    if current == "planned":
        return text, f"{where}: no change (already 📋 planned)"
    if current != "excluded":
        raise ValueError(
            f"{where} is {STATUS_TO_ICON[current]} {current}; only a ❌ "
            f"dropped deliverable can be restored")
    return (_write_unmarked_deliverable(text, lines, start, last, "planned",
                                        date, _RESTORED_PREFIX + reason),
            f"{where}: restored — {reason}")


def reword_deliverable(text: str, num: int, new_text: str
                       ) -> Tuple[str, str, int]:
    """Rewrite the prose of item *num*'s deliverable bullet; ``(text, old, line)``.

    The repair the split's copies are owed (issue #320). ``_split_multi_item_bullets``
    writes a shared bullet's sentence under every item it named, `aide check`
    reports the copies as identical until each says what its own item delivers
    (#169) — and until this verb no verb could change a bullet's words, so the
    only fix was the hand edit every role is steered away from.

    Allowed whatever the bullet's icon, ✅ included, which is where the criterion
    form's refusal does not carry over: a box's wording is what an attestation
    was made against, while a bullet's icon is the item's status and says
    nothing about the sentence beside it. The ✅ copy is the one whose words
    describe a sibling's open work as done, so it is the one most owed a fix.

    The bullet is found the one way every progress verb finds it — its
    trailing marker, over ``_deliverable_bullet_spans`` — and exactly one must
    name *num*, naming no other item: a shared ``*(Items …)*`` bullet's prose
    is one sentence for all its items. The new prose goes on the bullet's first
    line between the icon and the marker, the wrapped lines it replaces are
    dropped, and whatever hangs below the bullet (sub-lines, a trail) is not
    part of its span and is left alone. ``line`` is the bullet's 1-based line;
    a rewording to the prose it already has returns *text* unchanged.
    """
    prose = new_text.strip()
    if not prose:
        raise ValueError(
            "the new text is empty — a deliverable bullet says what its item "
            "delivers")
    if "\n" in prose or "\r" in prose:
        raise ValueError(
            "the new text may not contain a line break — it is written onto "
            "the bullet's one line, and a break would end the bullet before "
            "its marker")
    icon = _ICON_RE.match(prose)
    if icon:
        raise ValueError(
            f"the new text starts with a status icon ({icon.group(0)}), which "
            f"would put a second status on the bullet — pass the prose alone; "
            f"the bullet keeps its own icon")
    ref = _BULLET_MARKER_RE.search(prose)
    if ref:
        raise ValueError(
            f"the new text ends with an item reference "
            f"({ref.group(0).strip()}), which would join the bullet's trailing "
            f"marker and attribute its items to the bullet — pass the prose "
            f"alone; the bullet keeps its own *(Item {num:03d})* marker")
    lines = text.splitlines()
    owned = [(s, l) for s, l in _deliverable_bullet_spans(lines)
             if num in _bullet_marker_item_numbers(lines[l])]
    if not owned:
        raise ValueError(
            f"no deliverable bullet's trailing *(Item {num:03d})* marker names "
            f"item {num:03d}, so there is nothing to reword")
    if len(owned) > 1:
        where = ", ".join(f"progress.md:{s + 1}" for s, _ in owned)
        raise ValueError(
            f"{len(owned)} deliverable bullets' trailing markers name item "
            f"{num:03d} ({where}), and the verb rewords one bullet — which is "
            f"meant is not the engine's to guess")
    start, last = owned[0]
    marker = _BULLET_MARKER_RE.search(lines[last])
    items = list(dict.fromkeys(_referenced_item_numbers(marker.group(0))))
    if len(items) > 1:
        listed = ", ".join(f"{n:03d}" for n in items)
        raise ValueError(
            f"item {num:03d}'s bullet (progress.md:{start + 1}) carries the "
            f"shared marker {marker.group(0).strip()}: its prose is one "
            f"sentence for items {listed}, so rewording it for one would "
            f"reword it for all. `aide progress set` splits it into one bullet "
            f"per item the first time one of them moves; reword item "
            f"{num:03d}'s copy after that")
    old = _bullet_prose(lines, start, last)
    if prose == old:
        return text, old, start + 1
    head = lines[start][:_BULLET_RE.match(lines[start]).end()]
    rewritten = f"{head} {prose} {marker.group(0).strip()}"
    candidate = lines[:start] + [rewritten] + lines[last + 1:]
    # The guard behind the four refusals above: the rewritten bullet must read
    # back as the same one bullet, naming only this item, carrying this prose.
    # A shape the checks did not foresee is refused here rather than written.
    spans = [(s, l) for s, l in _deliverable_bullet_spans(candidate)
             if num in _bullet_marker_item_numbers(candidate[l])]
    if (spans != [(start, start)]
            or _bullet_marker_item_numbers(candidate[start]) != [num]
            or _bullet_prose(candidate, start, start) != prose):
        raise ValueError(
            f"the new text would change what item {num:03d}'s bullet "
            f"attributes or where it ends — pass the prose alone")
    return ("\n".join(candidate) + ("\n" if text.endswith("\n") else ""),
            old, start + 1)


class Reopening(NamedTuple):
    """One reopened item, as `check` and `status` report it.

    ``date`` and ``reason`` are the item's latest reopening, across every
    bullet it owns. ``completed`` is whether the item is ✅ again today, and
    ``completed_on`` the newest dated trail line after that reopening, or None
    when nothing dated was written since (a merge flips the icon and writes no
    trail line).
    """

    item: int
    date: str
    reason: str
    status: str
    completed: bool = False
    completed_on: Optional[str] = None


def reopened_items(lines: List[str]) -> List[Reopening]:
    """One `Reopening` per item whose bullet carries a ``reopened:`` trail line.

    Keyed on the item's status today (issue #273's rule, one level up): an item
    ✅ again since is reported as that, never as open.
    """
    item_status = _parse_item_status(lines)[2]
    latest: Dict[int, Tuple[Tuple[str, int], str, str, Optional[str]]] = {}
    for start, last in _deliverable_bullet_spans(lines):
        trail = deliverable_bullet_trail(lines, last)
        hit = _latest_trail_note(lines, trail, _REOPENED_PREFIX)
        if hit is None:
            continue
        date, reason, later = hit
        for num in _bullet_marker_item_numbers(lines[last]):
            key = (date, start)
            if num not in latest or key >= latest[num][0]:
                latest[num] = (key, date, reason, later)
    out: List[Reopening] = []
    for num in sorted(latest):
        _, date, reason, later = latest[num]
        status = item_status.get(num, "planned")
        done = status == "complete"
        out.append(Reopening(num, date, reason, status, done,
                             later if done else None))
    return out


def reopening_summary(r: Reopening) -> str:
    """What `check` says about one reopened item — worded by its status today."""
    if not r.completed:
        return (f"item {r.item:03d} was reopened on {r.date} ({r.reason}) — it "
                f"is {STATUS_TO_ICON[r.status]} again, and the trail under its "
                f"bullet keeps the earlier ✅ on record")
    since = f"on {r.completed_on}" if r.completed_on else "since"
    return (f"item {r.item:03d} was reopened on {r.date} ({r.reason}) and "
            f"completed again {since} — the reopening is kept in the trail "
            f"under its bullet")


#: A reopening whose reason starts with this is a **CI reopening** — the
#: queue-end step's fix round sending an item back for a red check (issue
#: #332). `reopen` stamps its round; `status` and `aide merge`
#: read it back.
_CI_REASON_PREFIX = "CI "
#: The round stamp `reopen` appends to a CI reopening's reason. The engine
#: writes it and a caller never does: a reason already ending in one is
#: refused, so the count is never one a runner kept in its head.
_CI_ROUND_RE = re.compile(r"\s*\[CI round (\d+)\]\s*$")
#: What a reopened item's `gap` entry leads with — written by `reopen`,
#: matched by `aide merge` as the item merges back.
_REOPEN_GAP_LEAD = "item reopened"
_OPEN_STATUSES = ("planned", "in-progress", "in-review")


def ci_fix_rounds(lines: List[str], items: Set[int]) -> Tuple[int, bool]:
    """``(rounds, live)`` over the CI reopenings of *items* (issue #332).

    ``rounds`` is the highest ``[CI round N]`` stamped on any ``reopened: CI
    …`` trail line under a bullet naming one of *items* — every such line,
    not only an item's latest, since a later round may leave an earlier
    round's item alone. ``live`` is whether an item of *items* whose latest
    reopening is a CI one is open today (📋, 🚧 or 🔍): a round begun and not
    yet merged back.

    The count has to be stamped when the reopening is written, not derived
    here from the trail alone: a merge flips an icon and writes no trail
    line, so whether item A re-merged before item B was reopened — the one
    fact that separates two rounds from one — is not on record afterwards.
    """
    top = 0
    ci = _REOPENED_PREFIX + _CI_REASON_PREFIX
    for _, last in _deliverable_bullet_spans(lines):
        if not set(_bullet_marker_item_numbers(lines[last])) & items:
            continue
        for i in deliverable_bullet_trail(lines, last):
            text = _ACCEPT_TRAIL_RE.match(lines[i]).group("text")
            m = _CI_ROUND_RE.search(text) if text.startswith(ci) else None
            if m:
                top = max(top, int(m.group(1)))
    live = any(r.item in items and r.status in _OPEN_STATUSES
               and r.reason.startswith(_CI_REASON_PREFIX)
               for r in reopened_items(lines))
    return top, live


def next_ci_round(lines: List[str], items: Set[int]) -> int:
    """The round a CI reopening of one of *items* joins or begins.

    While a CI-reopened item of *items* is still open the round under way is
    joined — the fix round reopens every item it traced before claiming any;
    once none is, the queue has been exhausted and marked ready since, and
    this reopening begins the next round.
    """
    top, live = ci_fix_rounds(lines, items)
    return top if (live and top) else top + 1


# --------------------------------------------------------------------------- #
# Item & queue file naming — the filename half of the branch helpers
# --------------------------------------------------------------------------- #
#: Item numbers and queue numbers share one namespace with no syntactic marker
#: between them. `_branch_item_number`/`_is_queue_branch` centralise that hazard
#: for BRANCH names (and their docstrings record what it cost to learn); these
#: four do the same for FILE names, which were previously re-derived as raw
#: globs and f-strings at thirteen call sites. Nothing here fixes a live bug —
#: every one of those sites was correct. The point is that the convention is now
#: written down once, so the 1.13.0 class of misread has one place to reappear
#: and one place to be tested, and a change to the convention is a change here.


#: The literal tokens every queue name is built from — the file stem, both
#: branch shapes, and the regexes that read them back. Written once so that a
#: change to the convention is a change *here* and everything moves with it;
#: restating "queue-" in a constructor and again in a recogniser is exactly the
#: drift 1.15.0 removed for filenames and this block removes for branches.
_QUEUE_TOKEN = "queue-"
_SPECS_TOKEN = "specs-"


def queue_name(number: int) -> str:
    """``queue-NNN`` — the stem a queue file and its status prose both use."""
    return f"{_QUEUE_TOKEN}{number:03d}"


def queue_number(path: Path) -> Optional[int]:
    """Queue number named by *path*, or None when it names no queue.

    Anchored at the start of the stem, for the same reason the branch helpers
    are: an unanchored digit search reads ``specs-queue-015.md`` or a consumer's
    ``notes-on-queue-016.md`` as a queue file. Tolerates a trailing slug
    (``queue-016-stage-27.md``) so the deferred naming harmonisation does not
    have to touch the parser, and unpadded digits on read.
    """
    m = re.match(re.escape(_QUEUE_TOKEN) + r"0*(\d+)(?:-|$)", path.stem)
    return int(m.group(1)) if m else None


def iter_queue_paths(qdir: Path) -> List[Path]:
    """Every queue file under *qdir*, in queue-number order ([] if no dir).

    Ordered by the parsed number rather than lexicographically, so the order
    stays the number's even once a name carries a slug after it.
    """
    if not qdir.is_dir():
        return []
    numbered = [(n, p.name, p) for p, n in
                ((p, queue_number(p)) for p in qdir.glob(f"{_QUEUE_TOKEN}*.md"))
                if n is not None]
    return [p for _, _, p in sorted(numbered)]


def queue_path(qdir: Path, number: int) -> Optional[Path]:
    """The queue file for *number*, or None when it does not exist.

    **Resolves by glob, never by construction.** Constructing
    ``qdir / f"queue-{n:03d}.md"`` hardcodes the assumption that the number is
    the whole name; resolving means a slugged queue file is found by the same
    call, and a caller that wants a name for an error message asks
    `queue_name` for one instead of half-building a path it may not have.
    """
    matches = [p for p in iter_queue_paths(qdir) if queue_number(p) == number]
    return matches[0] if matches else None


def item_spec_paths(idir: Path, number: int) -> List[Path]:
    """Spec files for item *number* under *idir* — ``items/NNN-*.md``, sorted.

    Returns a list because the convention permits only one and the filesystem
    does not; every caller takes ``[0]`` and the extras are a consumer's
    problem, not something to raise over here.
    """
    if not idir.is_dir():
        return []
    return sorted(idir.glob(_item_spec_glob(number)))


def _item_spec_glob(number: int) -> str:
    return f"{number:03d}-*.md"


def item_spec_number(path: Path) -> Optional[int]:
    """The item number whose `item_spec_paths` lookup returns *path*, or None.

    A file under ``items/`` is a spec only if a lookup can find it, so the
    number is read off the filename's leading digits and then **confirmed
    against the lookup's own glob**, never a second pattern: ``12-foo.md`` and
    ``0012-foo.md`` both read as 12 and neither answers ``012-*.md``, so both
    are None, exactly as ``notes.md`` is (issue #228). `PurePath.match` applies
    the platform's case rule, as the glob does.
    """
    m = re.match(r"\d+", path.name)
    if not m:
        return None
    number = int(m.group(0))
    return number if PurePath(path.name).match(_item_spec_glob(number)) else None


def _unfindable_spec_warning(path: Path) -> str:
    """`aide check`'s warning for a file under ``items/`` no lookup returns."""
    m = re.match(r"(\d+)[-_ ]*(.*)$", path.name)
    if m and m.group(2).lower() not in ("", ".md"):
        fix = f"rename it to {int(m.group(1)):03d}-{m.group(2)}"
    else:
        fix = "rename it NNN-<slug>.md, NNN its item number zero-padded to three digits"
    return (f"items/{path.name}: not named NNN-<slug>.md, so `aide scope`, "
            f"`aide claim` and `aide check --queue` never find it and no other "
            f"spec lint reads it — {fix}")


# --------------------------------------------------------------------------- #
# queue.md helpers
# --------------------------------------------------------------------------- #
_QUEUE_STATUS_RE = re.compile(r"^>\s*\*\*Status:\*\*\s*(.*)$")
_QUEUE_ITEM_RE = re.compile(r"^###\s+Item\s+0*(\d+)\b", re.MULTILINE)


def queue_status(text: str) -> Optional[str]:
    for line in text.splitlines():
        m = _QUEUE_STATUS_RE.match(line)
        if m:
            return m.group(1).strip()
    return None


#: A declared status may lead with an icon, the form `aide queue tidy` writes
#: (``✅ Completed — …``); ⏸ is matched with or without its variation selector.
_LEADING_STATUS_ICON_RE = re.compile(r"^(?:" + _ICON_ALT + r"|⏸)\ufe0f?\s*")


def declares_live(status: str) -> bool:
    """Whether a queue's declared ``> **Status:**`` text says Live — the one
    reader for both `aide check` and the no-progress.md fallback, so
    ``🚧 Live`` reads as ``Live`` (issue #287)."""
    return _LEADING_STATUS_ICON_RE.sub("", status.strip()).lower().startswith("live")


def is_live_queue(text: str) -> bool:
    return declares_live(queue_status(text) or "")


def queue_item_numbers(text: str) -> List[int]:
    return [int(m.group(1)) for m in _QUEUE_ITEM_RE.finditer(text)]


def queue_is_open(text: str, item_status: Dict[int, str],
                  withdrawn: Collection[int] = ()) -> bool:
    """Derived queue state: open iff any item is 📋/🚧/🔍 per progress.md.

    🔍 counts as open: an item whose PR is still awaiting review is not work the
    queue is finished with, and marking the queue completed over it would strand
    the review.

    Queue state is DERIVED, never declared — a ``> **Status:**`` line in a
    queue file is decorative (kept for human readers), and the "live" queue is
    simply the lowest-numbered open one. An item progress.md doesn't know yet
    counts as planned, so a freshly wired queue is open.

    A 📋 item in *withdrawn* — every bullet of it in a stage whose summary
    row is ❌ (`withdrawn_stage_items`) — does not count, since `claim` will
    never offer it: a queue left with only such items stayed the live queue
    and `claim` reported them held rather than moving on (issue #389). A 🚧
    or 🔍 item there still counts — live work until its owner drops it, as
    §2 reads it for the stale ground. Every engine reader of "open" passes
    the set since issue #393 — `status`, `check`'s declared-status comparison
    and the record readers had kept the bullets alone and disagreed with
    `claim` about the same tree; without it the bullets alone are read.
    """
    return any(still_blocks(n, item_status, withdrawn)
               for n in queue_item_numbers(text))


def _progress_item_status(repo_root: Path, config) -> Dict[int, str]:
    path = docs_dir(repo_root, config) / "progress.md"
    if not path.is_file():
        return {}
    _, _, item_status = _parse_item_status(path.read_text(encoding=_ENCODING).splitlines())
    return item_status


#: The item statuses whose spec §1 keeps as a **record** for the sweeps that
#: ask an author to edit a document (issue #338). ⏸️ is here although
#: `template_drift_warnings` keeps a deferred spec in its own scope: a
#: deferred item is neither built from nor edited while it waits — the
#: settled set `queue_is_open` and `check --queue` already use — and the
#: exemption is read from progress.md on every run, so the warnings return
#: the moment the item is 📋 again, which is when its author acts on them.
_RECORD_ITEM_STATUSES = ("complete", "excluded", "deferred")


def record_documents(ddir: Path, item_status: Dict[int, str],
                     withdrawn: Collection[int] = ()) -> Set[Path]:
    """The documents under *ddir* that are records, not live (issue #338).

    An item spec whose item is ✅, ❌ or ⏸️ in progress.md, and a queue file
    naming at least one item and none still open (``queue_is_open``). §1
    says a merged spec is never rewritten, so a warning on one that asks for
    an edit can never be cleared and returns on every run. A queue naming no
    item yet is live: it is being wired. An item progress.md does not know
    counts as planned, so with no progress.md nothing is a record.

    A 📋 item in *withdrawn* (`withdrawn_stage_items`) is settled as a ⏸️
    one is: its spec is a record, and it keeps no queue open — `claim` never
    offers it (issue #393). Like ⏸️, the exemption is read on every run, so
    the warnings return once the stage's summary row is off ❌.
    """
    out: Set[Path] = set()
    idir = ddir / "items"
    if idir.is_dir():
        for ipath in idir.glob("*.md"):
            n = item_spec_number(ipath)
            if n is None:
                continue
            st = item_status.get(n, "planned")
            if st in _RECORD_ITEM_STATUSES or (st == "planned"
                                               and n in withdrawn):
                out.add(ipath)
    for qpath in iter_queue_paths(ddir / "queue"):
        try:
            qtext = qpath.read_text(encoding=_ENCODING)
        except (OSError, UnicodeDecodeError):
            continue
        if queue_item_numbers(qtext) and not queue_is_open(
                qtext, item_status, withdrawn):
            out.add(qpath)
    return out


def _docs_records(ddir: Path) -> Set[Path]:
    """`record_documents` over ``ddir/progress.md``, read once for the item
    statuses and the withdrawn stages; unreadable, nothing is a record."""
    path = ddir / "progress.md"
    try:
        lines = path.read_text(encoding=_ENCODING).splitlines()
    except (OSError, UnicodeDecodeError):
        lines = []
    return record_documents(ddir, _parse_item_status(lines)[2],
                            withdrawn_stage_items(lines))


def tidy_queue_text(text: str, superseded_by: int, date: str) -> str:
    """Rewrite a queue's Status line to 'Completed — superseded by queue-NNN'."""
    new_status = (f"> **Status:** ✅ Completed — superseded by "
                  f"{queue_name(superseded_by)} ({date}).")
    lines = text.splitlines()
    for i, line in enumerate(lines):
        if _QUEUE_STATUS_RE.match(line):
            lines[i] = new_status
            return "\n".join(lines) + ("\n" if text.endswith("\n") else "")
    # No status line: insert after the H1.
    for i, line in enumerate(lines):
        if line.startswith("# "):
            lines.insert(i + 1, new_status)
            break
    return "\n".join(lines) + ("\n" if text.endswith("\n") else "")


# --------------------------------------------------------------------------- #
# check
# --------------------------------------------------------------------------- #
#: An AIDE slot is a bare ``{{name}}``. The negative lookbehind exempts a `$`
#: immediately before the braces — GitHub Actions expression syntax, which is
#: foreign syntax a living document may legitimately quote when it documents a
#: workflow. Without it, an item spec explaining what a CI step runs, or an
#: insight recording a workflow's arguments, turns `aide check` red on prose
#: that is correct as written, and the only remedy is to stop naming the real
#: syntax — making the documentation worse exactly where accuracy matters.
#:
#: Suppressing matches inside backtick code spans would be the wrong fix: the
#: item template's own `Suggested branch` line carries a genuine slot inside a
#: code span (``aide/{{nnn}}-descriptive-name``), so that rule would make a
#: real unfilled slot invisible. AIDE slots are never `$`-prefixed, so keying
#: on the `$` is precise in both directions.
_TEMPLATE_SLOT_RE = re.compile(r"(?<!\$)\{\{[^}]*\}\}")


def template_residue_errors(ddir: Path) -> List[str]:
    """Flag unfilled ``{{slot}}`` template markers left in generated documents.

    Templates use ``{{slot-name}}`` for values an author must fill in (see
    ``.aide/templates/``); a real ``docs/aide/`` document should never contain
    one. Scanning for the literal ``{{`` is deterministic and cheap — the
    format contract's answer to "did someone forget to fill in the template".
    """
    errors: List[str] = []
    if not ddir.is_dir():
        return errors
    for path in sorted(ddir.rglob("*.md")):
        text = path.read_text(encoding=_ENCODING)
        for lineno, line in enumerate(text.splitlines(), start=1):
            for m in _TEMPLATE_SLOT_RE.finditer(line):
                errors.append(
                    f"{path.relative_to(ddir).as_posix()}:{lineno}: "
                    f"unfilled template slot {m.group(0)}"
                )
    return errors


_INSIGHT_TYPES = ("knowledge", "defect", "gap", "automation", "framework")
#: What may stand between ``*(`` and the date: anything but a close-paren or a
#: line break, or nothing at all.
#:
#: Deliberately a slug and not a grammar. Only the **date** is load-bearing —
#: ``archive`` cuts on it and ``list`` prints it; nothing routes on the item
#: number — while the frame around the provenance already pins the checkbox, a
#: known type, the dash, a non-empty claim and an ISO date. A provenance that
#: fails an enumerated shape inside that frame names no defect anyone can act
#: on.
#:
#: Enumerating the accepted forms means predicting what an author will write,
#: and the cost of predicting wrong is not the usual one: conventions.md §1
#: makes the captured line immutable, so a rejected provenance is a warning
#: that can never be cleared, on an entry ``archive`` then declines to move
#: (see ``archive_insight_text``). Until 1.21.0 the shape was ``item NNN``
#: alone, which rejected two provenances the loop produces routinely —
#: ``queue-NNN`` for planning done before any item exists, and
#: ``items NNN-NNN`` for a finding that genuinely spans several. Both were
#: unfixable in place, since collapsing a range to one item is a rewording
#: *and* destroys the provenance the marker exists to record.
#:
#: Canonical forms are still documented (conventions.md §1, and the template's
#: header) so captures converge — guidance, which the reader can follow, rather
#: than enforcement, which the immutability rule makes permanent.
#:
#: It must still end in a non-blank character, so a stray comma — ``*(   ,
#: 2026-01-01)*`` — is a shape warning rather than a silently accepted
#: provenance that says nothing. Free-form is not the same as empty.
_INSIGHT_SOURCE = r"[^)\n]*[^\s)\n]"
#: What may stand **after** the date, in the same marker: the conditions the
#: observation was made under, conventionally ``engine X.Y.Z`` — one read of
#: ``.aide/VERSION`` at capture time (conventions.md §1).
#:
#: The date cannot proxy for it: a project runs an engine for as long as it
#: likes after a release, so two entries captured the same week may sit either
#: side of a restructure. It matters most on a ``framework`` entry, which is
#: triaged in another repo, months later, by someone with no other way to know.
#:
#: Free-form for the same reason the provenance is, and the reason is sharper
#: here: this component arrived after entries already existed, so a grammar
#: (``engine`` plus a SemVer triple, say) would reject a consumer's own honest
#: spelling permanently — the claim line is immutable, and the warning could
#: never be cleared. Conventional, not grammatical.
#:
#: Free-form everywhere except one character: ``)`` closes the marker, so a note
#: containing one — ``engine 1.2.3 (rc1)`` — does not parse, drawing a permanent
#: shape warning and losing the date that ``archive`` and ``tick`` read. Write
#: the note without parentheses.
_INSIGHT_NOTE = r"[^)\n]*[^\s)\n]"
#: A provenance naming exactly one item — the only form that yields an item
#: *number*. A range, a queue, or anything else leaves ``item`` ``None``, as a
#: bare date always has.
_INSIGHT_ONE_ITEM_RE = re.compile(r"^[Ii]tems? (\d+)$")
# "- [ ] <type> — <one line> *(item NNN, YYYY-MM-DD, engine X.Y.Z)*"; the
# provenance and the trailing note are both free-form and optional, and ticked
# entries append " → <where it landed>".
_INSIGHT_RE = re.compile(
    r"^- \[[ xX]\] (?:" + "|".join(_INSIGHT_TYPES) + r") [—–-] .+"
    r"\*\((?:" + _INSIGHT_SOURCE + r", )?\d{4}-\d{2}-\d{2}"
    r"(?:, " + _INSIGHT_NOTE + r")?\)\*"
)


def insight_warnings(ddir: Path) -> List[str]:
    """Shape-check ``insights.md`` (the compound-engineering inbox), if present.

    Non-blocking: capture must stay cheap, so a malformed entry is a warning,
    never an error. Every ``- `` bullet in the file is expected to be an entry.

    **The live file only.** ``aide insights archive`` moves closed entries into
    ``insights/archive-YYYY-QN.md``, and those are deliberately not re-checked
    here: an archived claim is frozen, so a warning on one names a defect no
    one may fix — the immutability rule forbids rewording the line. (Unfilled
    ``{{slot}}`` markers *are* still caught in archives, because
    ``template_residue_errors`` walks the whole tree; that one is a genuine
    error wherever it appears.)
    """
    path = ddir / "insights.md"
    if not path.is_file():
        return []
    out: List[str] = []
    for lineno, line in enumerate(path.read_text(encoding=_ENCODING).splitlines(), start=1):
        if not line.startswith("- "):
            continue
        if not _INSIGHT_RE.match(line):
            out.append(
                f"insights.md:{lineno}: entry does not match "
                f"'- [ ] <{'|'.join(_INSIGHT_TYPES)}> — <one line> "
                f"*(<where it came from>, YYYY-MM-DD, engine X.Y.Z)*' — the "
                f"provenance and the trailing engine version are free-form "
                f"and may be omitted; the ISO date may not"
            )
    return out


#: The three git conflict markers that can never be legitimate markdown at the
#: start of a line, and so are safe to lint on. ``=======`` is deliberately
#: **not** among them: it is also a setext heading underline, and a lint that
#: fires on a heading is a lint a reader learns to skim. A real conflict always
#: carries an opener and a closer, so nothing is missed by leaving it out.
_CONFLICT_OPEN_RE = re.compile(r"^<{7}(?: |$)")
_CONFLICT_BASE_RE = re.compile(r"^\|{7}(?: |$)")
_CONFLICT_SEP_RE = re.compile(r"^={7}$")
_CONFLICT_CLOSE_RE = re.compile(r"^>{7}(?: |$)")
_CONFLICT_LINT_RES = (_CONFLICT_OPEN_RE, _CONFLICT_BASE_RE, _CONFLICT_CLOSE_RE)


def conflict_marker_errors(ddir: Path,
                           repo_root: Optional[Path] = None) -> List[str]:
    """Flag git conflict markers committed into ``insights.md`` — an error.

    The inbox is append-only by contract (conventions.md §1 → ``insights.md``),
    so two branches that each captured an insight conflict on every merge, and
    the conflict is always the same trivial shape. That makes a *committed*
    marker a format-contract error rather than the usual warning. `parse_insights`
    skips the marker lines themselves — they do not start with ``- `` — which
    is worse than misreading them: **both sides' entries land in one numbered
    list**, so ``list`` numbers straight across the halves and the ``N`` a
    reader takes from it points ``tick`` at a different claim than the one they
    read. ``archive`` will happily move an entry out from between the markers
    and leave them behind.

    An error, unlike the shape warnings above, because it is always fixable —
    ``aide insights resolve`` is the fix, and the message says so. The live
    file only, for the reason ``insight_warnings`` gives: the resolver works on
    the file the loop appends to, and an archive is frozen.
    """
    path = ddir / "insights.md"
    if not path.is_file():
        return []
    out: List[str] = []
    for lineno, line in enumerate(path.read_text(encoding=_ENCODING).splitlines(), start=1):
        if any(rx.match(line) for rx in _CONFLICT_LINT_RES):
            out.append(
                f"insights.md:{lineno}: an unresolved git conflict marker "
                f"({line.split(' ')[0]}) — the inbox is append-only, so this "
                f"merge is a union of entries; resolve it with "
                f"`{aide_command(repo_root, 'insights resolve')}` (add "
                f"--dry-run to see it first) rather than by hand, which is "
                f"where a captured claim gets reworded"
            )
    return out


#: An entry's full shape, parsed rather than merely validated: the claim, its
#: provenance, and the optional " → <where it landed>" pointer a tick appends.
#: ``text`` is non-greedy up to the provenance so a claim may itself contain
#: parentheses; ``tail`` is whatever follows it, which is the pointer or "".
#: The pointer separator, written by `tick` and by hand before it existed.
_INSIGHT_POINTER = " → "
#: ``source`` is the provenance verbatim (``None`` for a bare date), because a
#: listing that re-derives it from an item number can print nothing else back.
_INSIGHT_ENTRY_HEAD = (
    r"^- \[(?P<mark>[ xX])\] (?P<type>" + "|".join(_INSIGHT_TYPES) + r") [—–-] "
    r"(?P<text>.+?)\*\((?:(?P<source>" + _INSIGHT_SOURCE + r"), )?"
    r"(?P<date>\d{4}-\d{2}-\d{2})(?:, (?P<note>" + _INSIGHT_NOTE + r"))?\)\*"
)
#: Which marker is the provenance, when a line carries more than one.
#:
#: ``text`` is non-greedy, so it stops at the *first* ``*(…, date)*`` — and a
#: free-form provenance means an aside inside the claim can wear that shape:
#: ``… default is *(prod, 2020-01-01)* not *(item 099, 2026-07-26)*`` would take
#: the aside's date and file the entry in the wrong archive quarter, silently,
#: since the line still parses. Greedy is not the answer either — it takes the
#: *last* marker, which a pointer may equally carry (``→ see *(note, …)*``).
#:
#: So neither position decides it: the provenance is the marker that leaves a
#: **well-formed tail** — nothing, or the ``→`` pointer `tick` writes. That is
#: the strict pattern, and it resolves both cases above. A tail matching
#: neither is a hand-written entry predating `tick` (``*(…)* — landed in X``);
#: the loose pattern accepts it exactly as before, so widening the provenance
#: costs no entry its parse.
_INSIGHT_FULL_RE = re.compile(_INSIGHT_ENTRY_HEAD + r"(?P<tail>\s*(?:→.*)?)$")
_INSIGHT_FULL_LOOSE_RE = re.compile(_INSIGHT_ENTRY_HEAD + r"(?P<tail>.*)$")
#: A status-trail line: indented under its entry, newest last (conventions.md
#: §1). Indentation is what distinguishes it from the next entry, so this must
#: require leading whitespace where the entry pattern forbids it.
_INSIGHT_TRAIL_RE = re.compile(r"^\s+[-*]\s")
#: An ISO date, validated rather than trusted: `archive --before` compares it
#: lexicographically against every entry's date, which is only equivalent to
#: comparing dates while both sides are known to be YYYY-MM-DD.
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


class InsightEntry(NamedTuple):
    """One inbox entry: the parsed claim plus where it sits in the file.

    ``ordinal`` is 1-based position in the live file and is the identity every
    verb here takes, because an entry has no number of its own. That is sound
    only because the file is append-only by contract — a claim is "never
    reworded, reordered or deleted" — so an entry's position is stable for as
    long as it lives in the file. ``archive`` is the one thing that moves
    entries out, and it therefore renumbers what remains; it says so when it
    runs, and ``tick`` refuses to invent a pointer on a number it cannot
    resolve.

    A malformed entry (one ``aide check`` warns about) still gets an ordinal.
    Skipping it would make ``insights list`` number entries differently from
    the file itself, so the one number a reader can act on would be wrong for
    every entry after the first typo.
    """

    ordinal: int
    lineno: int                 # 1-based, of the entry line itself
    raw: str                    # the entry line, verbatim
    ticked: bool
    type: Optional[str]         # None when the line does not parse
    text: str                   # the claim, without provenance or pointer
    date: Optional[str]
    source: Optional[str]       # the provenance verbatim; None for a bare date
    note: Optional[str]         # what follows the date, verbatim — by
                                # convention "engine X.Y.Z"; None when absent
    item: Optional[int]         # only when `source` names exactly one item
    pointer: Optional[str]      # what follows " → ", when ticked in place
    trail: List[str]            # raw status-trail lines, in file order
    end_lineno: int             # 1-based, of the entry's last trail line


def parse_insights(text: str) -> List[InsightEntry]:
    """Parse ``insights.md`` into entries, malformed ones included.

    Pure: it takes the file's text, never a path, so the shape rules are
    testable without a filesystem (the module convention — see
    ``.aide/scripts/tests``).
    """
    lines = text.splitlines()
    entries: List[InsightEntry] = []
    for lineno, line in enumerate(lines, start=1):
        if not line.startswith("- "):
            if entries and _INSIGHT_TRAIL_RE.match(line):
                # A trail line belongs to the entry above it; NamedTuple is
                # immutable, so grow the list it holds rather than rebuilding.
                entries[-1].trail.append(line)
                entries[-1] = entries[-1]._replace(end_lineno=lineno)
            continue
        m = _INSIGHT_FULL_RE.match(line) or _INSIGHT_FULL_LOOSE_RE.match(line)
        if m is None:
            entries.append(InsightEntry(
                ordinal=len(entries) + 1, lineno=lineno, raw=line,
                ticked=line.startswith("- [x]") or line.startswith("- [X]"),
                type=None, text=line[2:].strip(), date=None, source=None,
                note=None, item=None, pointer=None, trail=[],
                end_lineno=lineno))
            continue
        tail = m.group("tail")
        pointer = (tail.split(_INSIGHT_POINTER, 1)[1].strip()
                   if _INSIGHT_POINTER in tail else None)
        source = m.group("source")
        one_item = _INSIGHT_ONE_ITEM_RE.match(source) if source else None
        entries.append(InsightEntry(
            ordinal=len(entries) + 1, lineno=lineno, raw=line,
            ticked=m.group("mark") in ("x", "X"),
            type=m.group("type"), text=m.group("text").strip(),
            date=m.group("date"), source=source, note=m.group("note"),
            item=int(one_item.group(1)) if one_item else None,
            pointer=pointer, trail=[], end_lineno=lineno))
    return entries


def _find_entry(entries: List[InsightEntry], ordinal: int) -> InsightEntry:
    for e in entries:
        if e.ordinal == ordinal:
            return e
    raise ValueError(
        f"no entry {ordinal} — the file holds {len(entries)} "
        f"entr{'y' if len(entries) == 1 else 'ies'}; run `insights list` for "
        f"current numbers (an archive renumbers what remains)")


# --------------------------------------------------------------------------- #
# insight IDs — the durable handle (conventions.md §1 → insights.md, #276)
# --------------------------------------------------------------------------- #
#: The shortest hex an ID is printed with. Lengthened per entry only as far as
#: it takes to tell apart two *different* claims captured on the same date —
#: see ``insight_ids``.
INSIGHT_ID_MIN_HEX = 4
#: An insight ID as written: the capture date, a hyphen, then lowercase hex —
#: a prefix of the claim's SHA-256, never shorter than the minimum.
_INSIGHT_ID_SHAPE = r"\d{4}-\d{2}-\d{2}-[0-9a-f]{%d,64}" % INSIGHT_ID_MIN_HEX
_INSIGHT_ID_RE = re.compile(r"^(?P<date>\d{4}-\d{2}-\d{2})-(?P<hex>[0-9a-f]{%d,64})$"
                            % INSIGHT_ID_MIN_HEX)


def insight_claim_hash(entry: InsightEntry) -> Optional[str]:
    """The full SHA-256 hex of an entry's claim, or None when it has no ID.

    Only the claim is hashed — the free text between the type's dash and the
    ``*(…)*`` marker, which conventions.md §1 makes immutable. Everything
    triage writes is outside it: the checkbox, the ``→`` pointer after the
    marker, the trail lines under the entry. So a tick, a trail line, an
    archive (which moves the line unchanged) and a ``resolve`` (which never
    retypes one) all leave the hash where it was.

    Normalised by collapsing whitespace runs to one space and composing
    Unicode (NFC), so a rewrap by an editor or a composed/decomposed accent is
    not a different claim; nothing else is folded — the claim is compared as
    written. A line too malformed to parse, or one without a date, has no ID:
    the date is half of it.
    """
    if entry.type is None or entry.date is None:
        return None
    claim = " ".join(unicodedata.normalize("NFC", entry.text).split())
    return hashlib.sha256(claim.encode("utf-8")).hexdigest()


def insight_ids(entries: List[InsightEntry]) -> List[Optional[str]]:
    """The printed ID of each entry in *entries*, aligned with it.

    ``<date>-<hex>``, where hex is the claim hash cut to
    ``INSIGHT_ID_MIN_HEX`` characters, or longer only as far as it takes to
    differ from every *different* claim captured on the same date among
    *entries*. The pool a caller passes is the inbox **and** its archives, so
    an ID printed today is unambiguous across both. Two entries with the same
    claim on the same date — two independent captures, which §1 keeps both of —
    share one ID: they are the same claim.

    A longer prefix of the same hash is the same ID, so an ID once written
    never stops resolving; a later same-day collision can only make its short
    form *ambiguous*, which ``resolve_insight_ref`` reports rather than guesses.
    """
    hashes = [insight_claim_hash(e) for e in entries]
    by_date: Dict[str, Set[str]] = {}
    for e, h in zip(entries, hashes):
        if h is not None:
            by_date.setdefault(e.date, set()).add(h)
    out: List[Optional[str]] = []
    for e, h in zip(entries, hashes):
        if h is None:
            out.append(None)
            continue
        others = [o for o in by_date[e.date] if o != h]
        n = INSIGHT_ID_MIN_HEX
        while n < len(h) and any(o.startswith(h[:n]) for o in others):
            n += 1
        out.append(f"{e.date}-{h[:n]}")
    return out


def is_insight_id(ref: str) -> bool:
    """Does *ref* have the shape of an insight ID (not: does it resolve)?"""
    return _INSIGHT_ID_RE.match(ref) is not None


def resolve_insight_ref(ref: str, entries: List[InsightEntry]) -> List[int]:
    """Indices into *entries* whose claim the ID *ref* names.

    Matching is by date and hash **prefix**, so every length of an ID ≥ the
    minimum names the same entry. The caller reads the result: empty is a
    dangling ID; entries whose claims differ (``insight_claim_hash``) is an
    ambiguous one; one claim — even held by two entries — is resolved.
    """
    m = _INSIGHT_ID_RE.match(ref)
    if m is None:
        return []
    date, hexpart = m.group("date"), m.group("hex")
    return [i for i, e in enumerate(entries)
            if e.date == date
            and (insight_claim_hash(e) or "").startswith(hexpart)]


def insight_archive_files(ddir: Path) -> List[Path]:
    """The archives `aide insights archive` writes, in name (= quarter) order."""
    adir = ddir / "insights"
    if not adir.is_dir():
        return []
    return sorted(p for p in adir.glob("archive-*.md") if p.is_file())


def load_insight_pool(ddir: Path) -> List[Tuple[str, InsightEntry]]:
    """Every entry an ID may name: the live inbox, then each archive.

    Pairs each entry with the file it sits in, relative to *ddir* in POSIX
    form (``insights.md``, ``insights/archive-2026-Q3.md``). An archive is
    written in the inbox's own entry shape, so the one parser reads both.
    """
    pool: List[Tuple[str, InsightEntry]] = []
    live = ddir / "insights.md"
    files = ([live] if live.is_file() else []) + insight_archive_files(ddir)
    for path in files:
        rel = path.relative_to(ddir).as_posix()
        for e in parse_insights(path.read_text(encoding=_ENCODING)):
            pool.append((rel, e))
    return pool


def live_ordinal_for_ref(ref: str, pool: List[Tuple[str, InsightEntry]]) -> int:
    """The live-inbox position an ``N`` or an ID names, for a verb that edits.

    ``N`` is taken as it stands (``_find_entry`` reports one out of range). An
    ID is resolved against the whole pool so that its answer is the same one
    `aide check` gives, and then refused unless it names exactly one entry in
    the live file: an archived entry is frozen, an ambiguous ID names no one
    claim, and two live captures of one claim can only be told apart by
    position. Raises ``ValueError`` with the reason.
    """
    if ref.isdigit():
        return int(ref)
    if not is_insight_id(ref):
        raise ValueError(
            f"{ref!r} is neither an entry number nor an insight ID "
            f"(YYYY-MM-DD-<hex>, as `insights list` prints it)")
    entries = [e for _, e in pool]
    hits = resolve_insight_ref(ref, entries)
    if not hits:
        raise ValueError(f"no entry {ref} in insights.md or its archives")
    if len({insight_claim_hash(entries[i]) for i in hits}) > 1:
        ids = insight_ids(entries)
        raise ValueError(
            f"{ref} matches more than one claim captured that day — use the "
            f"longer ID of the one meant: {', '.join(sorted({ids[i] for i in hits}))}")
    live = [entries[i] for i in hits if pool[i][0] == "insights.md"]
    if not live:
        raise ValueError(
            f"insight {ref} is archived in {pool[hits[0]][0]} — an archive is "
            f"frozen, so there is nothing to tick")
    if len(live) > 1:
        raise ValueError(
            f"insight {ref} is one claim captured {len(live)} times (entries "
            f"{', '.join(str(e.ordinal) for e in live)}) — tick by position")
    return live[0].ordinal


#: A citation of an insight by ID, as `aide check` reads one: the word
#: *insight* (either plural, either case, optionally followed by *entry* and
#: then *ID*), then the ID itself, backticks or emphasis allowed between. The
#: word is required — see ``insight_reference_findings`` for why a bare
#: date-shaped token is not enough.
_INSIGHT_ID_CITATION_RE = re.compile(
    r"(?i:\b(?:insights?)(?:\s+(?:entry|entries))?(?:\s+id)?)[\s`*]+"
    r"(?P<id>" + _INSIGHT_ID_SHAPE + r")(?![0-9A-Za-z_-])")
#: The bare ``entry <ID>`` form — read as a citation only on a line that says
#: *insight* or *inbox* somewhere, as with ``_ENTRY_POSITION_RE``: an audit or
#: ledger "entry 2026-05-11-1530" is a timestamp, and a false error there
#: would block a merge.
_ENTRY_ID_CITATION_RE = re.compile(
    r"(?i:\b(?:entry|entries)(?:\s+id)?)[\s`*]+"
    r"(?P<id>" + _INSIGHT_ID_SHAPE + r")(?![0-9A-Za-z_-])")
#: A citation of an insight by position: ``insight 28``, ``insights.md entry
#: 28``, ``inbox entry #28``. The number may not run on into a date, a version
#: or a word (``insight 2026-…`` is the ID form, ``entry 1.2`` is not a
#: position), and may not start with a zero: ``list`` never pads a position,
#: and ``037`` is the item-number shape (issue #335).
_INSIGHT_POSITION_RE = re.compile(
    r"(?i:\b(?:insights?(?:\.md)?|inbox)(?:\s+(?:entry|entries))?)\s+#?"
    r"(?P<n>[1-9]\d{0,3})(?![\w-]|\.\d)")
#: The bare ``entry 28`` form — read as an insight citation only on a line that
#: says *insight* or *inbox* somewhere, since a ledger row or a table entry is
#: an "entry" too.
_ENTRY_POSITION_RE = re.compile(
    r"(?i:\b(?:entry|entries))\s+#?(?P<n>[1-9]\d{0,3})(?![\w-]|\.\d)")
_INSIGHT_CONTEXT_RE = re.compile(r"(?i)\b(?:insights?|inbox)")


def _citation_files(repo_root: Path, config: Dict[str, Dict[str, object]],
                    ddir: Path) -> Tuple[List[Path], List[Path]]:
    """``(docs files, test files)`` an insight citation is looked for in.

    The docs half is every ``*.md`` under docs_dir **except** the inbox and
    its archives, whose claims are immutable — a finding there could never be
    cleared. The tests half is the files the test-hygiene lints read
    (``_test_files``). A test file that also sits under docs_dir is read once,
    as a docs file.
    """
    docs: List[Path] = []
    if ddir.is_dir():
        frozen = {ddir / "insights.md", *insight_archive_files(ddir)}
        docs = [p for p in sorted(ddir.rglob("*.md"))
                if p.is_file() and p not in frozen]
    seen = set(docs)
    tests = [p for p in _test_files(repo_root, config) if p not in seen]
    return docs, tests


def _positional_citations(line: str, pool_size: Callable[[], int]) -> List["re.Match"]:
    """The citations of an insight *by position* on one line — the one detector.

    ``insight 28``, ``insights.md entry 28`` and ``inbox entry #28`` anywhere;
    a bare ``entry 28`` only on a line that also says *insight* or *inbox*,
    since a ledger row or a table entry is an "entry" too. *pool_size* is
    called only when a match looks like a year: "insights 2026" is a year, not
    entry 2026, so a bare number that reads as one counts only after "entry"
    or "#", or when the inbox and its archives really hold that many entries.
    Shared by `aide check` (``insight_reference_findings``) and by `insights
    archive` (``insight_position_citations``), so the two can never disagree
    on what a positional citation is.
    """
    positions = list(_INSIGHT_POSITION_RE.finditer(line))
    if _INSIGHT_CONTEXT_RE.search(line):
        covered = {m.span("n") for m in positions}
        positions += [m for m in _ENTRY_POSITION_RE.finditer(line)
                      if m.span("n") not in covered]
    out = []
    for m in positions:
        n = int(m.group("n"))
        if (1900 <= n <= 2099 and not re.search(r"(?i)entr|#", m.group(0))
                and n > pool_size()):
            continue
        out.append(m)
    return out


def insight_position_citations(repo_root: Path,
                               config: Dict[str, Dict[str, object]],
                               ddir: Path,
                               pool_size: int) -> List[Tuple[str, int, str, int]]:
    """Every citation of an insight by position in docs_dir and tests_dir.

    ``(where, lineno, cited text, position)``, in file then line order, over
    the files ``insight_reference_findings`` reads (``_citation_files`` — the
    inbox and its archives excepted). What `insights archive` lists before it
    renumbers the inbox (issue #295): the run is the last point at which a
    position still means what its author wrote.

    Records are listed too, unlike `aide check`'s positional warning (issue
    #338): the listing is printed once, by the run that moves the entries,
    and its ID is the one the position held before this move — the mapping
    that preserves what a record's citation meant. The check recovers it
    from git history since issue #361 (``_CitationHistory``), but only where
    the history is there to read; this listing needs none.
    """
    out: List[Tuple[str, int, str, int]] = []
    docs, tests = _citation_files(repo_root, config, ddir)
    for path in docs + tests:
        try:
            text = path.read_text(encoding=_ENCODING)
        except (OSError, UnicodeDecodeError):
            continue
        where = _rel_display(path, repo_root)
        for lineno, line in enumerate(text.splitlines(), start=1):
            for m in _positional_citations(line, lambda: pool_size):
                out.append((where, lineno, m.group(0).strip(), int(m.group("n"))))
    return out


def insight_reference_findings(repo_root: Path,
                               config: Dict[str, Dict[str, object]],
                               ddir: Path) -> Tuple[List[str], List[str]]:
    """``(errors, warnings)`` for insight citations in durable artefacts.

    conventions.md §1 → insights.md: an entry is cited by its ID. Three
    findings, over docs_dir and tests_dir:

    * an **ID that resolves to no entry** in the inbox or its archives — an
      error, since it names a claim no reader can find (issue #276's
      fabricated index was exactly this, found by accident);
    * an **ID that matches two different claims** — a warning naming the
      longer IDs that tell them apart; it resolved when written, and only a
      later same-day capture made its short form ambiguous;
    * a **citation by position** (``_positional_citations``) — a warning
      naming the ID the position held when the citing line was committed
      (``_CitationHistory``, issue #361), since an archive or a merge
      renumbers it; today's holder only for an uncommitted line, or as a
      labelled fallback where there is no history to read. Tests are read
      too (issue #295): a comment or an assertion message naming "insight
      28" goes stale on the same archive a spec does. A record
      (``record_documents`` — a ✅, ❌ or ⏸️ item's spec, or a 📋 one of a
      withdrawn stage, and a queue with no open item) is not warned about
      (issue #338, #393): §1 never rewrites one, so the warning could not be
      cleared.

    The first finding holds in a record too: an ID naming nothing is a
    citation no reader can follow, whoever wrote it.

    Only the cited form is read (``_INSIGHT_ID_CITATION_RE``): the word
    *insight* before the ID, or *entry* on a line that also says *insight* or
    *inbox* (``_ENTRY_ID_CITATION_RE``). A bare ``YYYY-MM-DD-<hex>`` token is
    also a timestamp, a slug, a file name, and an error here blocks `merge`.
    """
    errors: List[str] = []
    warnings: List[str] = []
    docs, tests = _citation_files(repo_root, config, ddir)
    if not docs and not tests:
        return errors, warnings
    records = _docs_records(ddir)
    # Read lazily and once: most files cite nothing, and a repo whose tests
    # cite no insight never opens the inbox or an archive for this check.
    cache: Dict[str, object] = {}
    history = _CitationHistory(repo_root, ddir)

    def _entries() -> List[InsightEntry]:
        if "pool" not in cache:
            pool = load_insight_pool(ddir) if ddir.is_dir() else []
            cache["pool"] = pool
            cache["entries"] = [e for _, e in pool]
            cache["ids"] = insight_ids(cache["entries"])
            cache["live_ids"] = [i for (rel, _), i in zip(pool, cache["ids"])
                                 if rel == "insights.md"]
        return cache["entries"]  # type: ignore[return-value]

    for path in docs + tests:
        try:
            # newline="": universal-newline reading turns a lone \r into \n,
            # which git does not count, so the line numbers git blames by
            # could no longer be recovered (`_git_line_numbers`).
            with open(path, encoding=_ENCODING, newline="") as fh:
                text = fh.read()
        except (OSError, UnicodeDecodeError):
            continue
        where = _rel_display(path, repo_root)
        gitline = _git_line_numbers(text)
        if path not in records:
            # Every cited line first, so the file is blamed once for all.
            for lineno, line in enumerate(text.splitlines(), start=1):
                if _positional_citations(line, lambda: len(_entries())):
                    history.want(path, gitline[lineno - 1])
        for lineno, line in enumerate(text.splitlines(), start=1):
            cited = list(_INSIGHT_ID_CITATION_RE.finditer(line))
            if _INSIGHT_CONTEXT_RE.search(line):
                seen = {m.span("id") for m in cited}
                cited += [m for m in _ENTRY_ID_CITATION_RE.finditer(line)
                          if m.span("id") not in seen]
            for m in cited:
                ref = m.group("id")
                entries = _entries()
                hits = resolve_insight_ref(ref, entries)
                if not hits:
                    errors.append(
                        f"{where}:{lineno}: insight {ref} resolves to no entry "
                        f"in insights.md or its archives — cite an ID "
                        f"`aide insights list` prints (conventions.md §1 → "
                        f"insights.md)")
                elif len({insight_claim_hash(entries[i]) for i in hits}) > 1:
                    ids = cache["ids"]
                    names = ", ".join(sorted({ids[i] for i in hits}))  # type: ignore[index]
                    warnings.append(
                        f"{where}:{lineno}: insight {ref} matches more than one "
                        f"claim captured that day — cite the longer ID of the "
                        f"one meant: {names}")
            if path in records:
                continue
            for m in _positional_citations(line, lambda: len(_entries())):
                _entries()
                meant = history.hint(path, gitline[lineno - 1], int(m.group("n")),
                                     cache["pool"], cache["ids"])  # type: ignore[arg-type]
                warnings.append(
                    f"{where}:{lineno}: `{m.group(0).strip()}` cites an insight "
                    f"by position, which an archive or a merge renumbers — "
                    f"cite its ID (`aide insights list`){meant}")
    return errors, warnings


class _CitationHistory:
    """What a positional insight citation meant when it was written (#361).

    `aide check`'s positional warning used to name the entry a position
    holds *today*. For a citation written before an `insights archive` that
    is a different claim, and following the hint rewrote the citation to
    something its author never meant. So the position is resolved against
    the inbox as it stood in the commit that last wrote the citing line:

    * ``git blame --porcelain`` names that commit — **one run per file**, over
      every cited line in it at once. Lines are git's, counted by ``\n``
      alone; the caller maps its own numbering onto them (``_git_line_numbers``);
    * ``git show <commit>:./<inbox>`` reads the inbox then — **once per
      commit**, cached, since a batch of citations usually shares one. The
      path is taken from *repo_root*, which may sit below git's top level;
    * the entry at that position is named by the ID it has **today**, found
      by its date and claim hash in the inbox and its archives — an ID
      resolves in an archive too, so it is always a citation `check` accepts.

    A line not committed yet (blame's all-zero commit), and a file git does
    not track, were written against the working tree's inbox: today's holder
    is then the right answer, and the hint says why. Everything that leaves
    the past inbox unknown falls back to today's holder, **labelled** "history
    unavailable", rather than stating something about the past: no git, not a
    work tree, a path outside it, a blame that fails, a ``git show`` that
    fails (the inbox under another path then, say), and a line blamed on a
    shallow clone's boundary commit — blame stops there, so the commit it
    names is where history ends, not where the line was written. "Named no
    entry" is said only when that commit's inbox was read and is shorter.
    """

    _ZERO = re.compile(r"^0+$")
    _HEADER = re.compile(r"^(?P<sha>[0-9a-f]{40,64}) \d+ (?P<final>\d+)(?: \d+)?$")
    #: A blamed line whose commit is past what this clone holds.
    UNKNOWN = ""

    def __init__(self, repo_root: Path, ddir: Path) -> None:
        self.repo_root = repo_root
        self.inbox_rel = self._rel(insights_path(ddir))
        self._blame: Dict[Path, Optional[Dict[int, Optional[str]]]] = {}
        self._shown: Dict[str, Optional[List[InsightEntry]]] = {}
        self._wanted: Dict[Path, Set[int]] = {}
        self._grafts: Optional[Set[str]] = None

    def _rel(self, path: Path) -> Optional[str]:
        try:
            return path.resolve().relative_to(self.repo_root.resolve()).as_posix()
        except ValueError:
            return None

    def want(self, path: Path, gitline: int) -> None:
        """Register a cited line, so the file's one blame covers all of them."""
        self._wanted.setdefault(path, set()).add(gitline)

    def _shallow_commits(self) -> Set[str]:
        """The commits a shallow clone was cut at; empty in a full clone."""
        if self._grafts is None:
            self._grafts = set()
            try:
                where = git(["rev-parse", "--git-path", "shallow"],
                            self.repo_root, check=False).stdout.strip()
                path = Path(where)
                if where and not path.is_absolute():
                    path = self.repo_root / path
                if where and path.is_file():
                    self._grafts = {l.strip() for l in path.read_text(
                        encoding="utf-8", errors="replace").splitlines() if l.strip()}
            except (OSError, subprocess.SubprocessError):
                pass
        return self._grafts

    def _commits(self, path: Path) -> Optional[Dict[int, Optional[str]]]:
        """``{git line: commit, None when not committed, UNKNOWN past a
        shallow boundary}``; None for the whole file: no history."""
        if path in self._blame:
            return self._blame[path]
        rel = self._rel(path)
        lines = sorted(self._wanted.get(path, ()))
        out: Optional[Dict[int, Optional[str]]] = None
        if rel is not None and lines:
            try:
                res = git(["blame", "--porcelain",
                           *[f"-L{n},{n}" for n in lines], "--", rel],
                          self.repo_root, check=False)
                if res.returncode == 0:
                    out = {}
                    boundary: Set[str] = set()
                    current = None
                    for text in res.stdout.splitlines():
                        h = self._HEADER.match(text)
                        if h:
                            current = h.group("sha")
                            out[int(h.group("final"))] = (
                                None if self._ZERO.match(current) else current)
                        elif text == "boundary" and current:
                            boundary.add(current)
                    # `boundary` also marks a true root commit; only one the
                    # clone was cut at hides where the line was written.
                    cut = boundary & self._shallow_commits()
                    for n, sha in out.items():
                        if sha in cut:
                            out[n] = self.UNKNOWN
                elif git(["rev-parse", "--is-inside-work-tree"], self.repo_root,
                         check=False).stdout.strip() == "true" and git(
                             ["ls-files", "--error-unmatch", "--", rel],
                             self.repo_root, check=False).returncode != 0:
                    # A file git does not track (or a repository with no
                    # commit yet): every line of it is uncommitted work.
                    out = {n: None for n in lines}
            except (OSError, subprocess.SubprocessError):
                out = None
        self._blame[path] = out
        return out

    def _inbox_at(self, sha: str) -> Optional[List[InsightEntry]]:
        """The inbox's entries in *sha*, or None when they cannot be read."""
        if sha not in self._shown:
            entries: Optional[List[InsightEntry]] = None
            if self.inbox_rel is not None:
                try:
                    # `./` makes the path relative to the cwd, repo_root —
                    # a bare `<sha>:<path>` is read from git's top level.
                    res = git(["show", f"{sha}:./{self.inbox_rel}"],
                              self.repo_root, check=False)
                    if res.returncode == 0:
                        text = res.stdout
                        if text.startswith("\ufeff"):
                            # `git()` decodes as utf-8, not utf-8-sig: a BOM
                            # would make the first entry no `- ` line.
                            text = text[1:]
                        entries = parse_insights(text)
                except (OSError, subprocess.SubprocessError):
                    pass
            self._shown[sha] = entries
        return self._shown[sha]

    @staticmethod
    def _fallback(n: int, today: Optional[str]) -> str:
        if today is None:
            return f"; history unavailable, and today's inbox has no entry {n}"
        return (f"; entry {n} of the inbox is insight {today} today "
                f"(today's holder; history unavailable) — cite that if it is "
                f"the one meant")

    def hint(self, path: Path, gitline: int, n: int,
             pool: List[Tuple[str, InsightEntry]],
             ids: List[Optional[str]]) -> str:
        """The warning's second half: the ID entry *n* meant, and how known."""
        live_ids = [i for (rel, _), i in zip(pool, ids) if rel == "insights.md"]
        today = live_ids[n - 1] if 1 <= n <= len(live_ids) else None
        commits = self._commits(path)
        if commits is None or gitline not in commits:
            return self._fallback(n, today)
        sha = commits[gitline]
        if sha is None:
            if today is None:
                return (f"; this line is not committed, and today's inbox has "
                        f"no entry {n}")
            return (f"; this line is not committed, so it was written against "
                    f"today's inbox, where entry {n} is insight {today} — cite "
                    f"that")
        then = self._inbox_at(sha) if sha else None
        if then is None:
            return self._fallback(n, today)
        when = f"when {sha[:7]} wrote this line"
        if n > len(then):
            return (f"; the inbox held no entry {n} {when}, so the citation "
                    f"named no entry — find the claim meant with `aide "
                    f"insights list`")
        entry = then[n - 1]
        claim = insight_claim_hash(entry)
        if claim is None:
            return (f"; entry {n} {when} was a malformed line with no ID — "
                    f"find the claim meant with `aide insights list`")
        found = [i for i, (_, e) in enumerate(pool)
                 if e.date == entry.date and insight_claim_hash(e) == claim]
        if not found:
            meant = insight_ids(then)[n - 1]
            return (f"; entry {n} was insight {meant} {when}, a claim no longer "
                    f"in the inbox or its archives")
        meant = ids[found[0]]
        if meant == today:
            return f"; entry {n} was insight {meant} {when}, and still is — cite that"
        return (f"; entry {n} was insight {meant} {when} — cite that; an "
                f"archive or a merge has moved it since")


def _git_line_numbers(text: str) -> List[int]:
    """For each line `str.splitlines` yields, the line git counts it on.

    git numbers lines by ``\n`` alone; `splitlines` also breaks on ``\r``,
    ``\x0b``, ``\x0c``, ``\x1c``–``\x1e``, ``\x85``, U+2028 and U+2029, so
    after any of those the two numberings part — and a blame asked for the
    wrong line names the wrong commit.
    """
    out: List[int] = []
    line = 1
    for chunk in text.splitlines(keepends=True):
        out.append(line)
        line += chunk.count("\n")
    return out


#: A citation of a human gate by ID: the ``gate-<hex>`` token itself, standing
#: alone. The word is inside the token, so there is no context word to
#: require; instead a token that is part of a path, a file name, a URL or a
#: heading anchor (``/gate-cafe``, ``gate-0001.md``, ``#gate-2026``,
#: ``?id=gate-beef``) is not
#: read — an error here blocks a merge, and none of those is a citation.
_GATE_ID_CITATION_RE = re.compile(
    r"(?<![\w\-#/.=?&])(?P<id>" + _GATE_ID_SHAPE + r")(?![\w\-/]|\.\w)")
#: A citation of a human gate by position: ``gate 3``, ``human gate #3``,
#: ``gates 2`` — the word, then the number. The number may not run on into a
#: word, a hyphen or a version (``gate 1.2`` is not a position), and may not
#: start with a zero: a position is never padded, while ``gates 041/042`` in
#: dependency prose is two item numbers (issue #335).
_GATE_POSITION_RE = re.compile(
    r"(?i:\b(?:human\s+)?gates?)\s+#?(?P<n>[1-9]\d{0,2})(?![\w-]|\.\d)")


def gate_reference_findings(repo_root: Path,
                            config: Dict[str, Dict[str, object]],
                            ddir: Path,
                            lines: List[str]) -> Tuple[List[str], List[str]]:
    """``(errors, warnings)`` for human-gate citations in docs_dir.

    conventions.md §1 → human gates: a durable artefact cites a gate by its ID
    (issue #293). *lines* is progress.md, read once by the caller. Three
    findings, over the files ``insight_reference_findings`` reads in docs_dir
    (the inbox and its archives excepted — their claims are immutable):

    * a **gate ID that names no row** — an error: the row was removed, or its
      Gate cell reworded into a different question, and a citation of it now
      names a decision no one can find;
    * a **gate ID that matches two different Gate cells** — a warning naming
      the longer IDs that tell them apart;
    * a **citation by position** — a warning naming the ID that row holds
      today, and only while progress.md's ``## Human gates`` table has a
      row: with none, "gate 3" is some other gate. Never in a record
      (``record_documents``, issue #338), which §1 does not rewrite; a
      dangling ID there is still an error.

    tests_dir is not read: a gate is cited by the documents that plan work,
    and "gate-" followed by hex is ordinary vocabulary in a test suite.
    """
    errors: List[str] = []
    warnings: List[str] = []
    docs, _ = _citation_files(repo_root, config, ddir)
    gates = human_gates(lines)
    unreadable = bool(unreadable_gate_rows(lines))
    # Rows, not the heading: the progress template ships the section empty,
    # and in a table with no row "gate 2" names nothing it could mean.
    has_rows = bool(gates) or unreadable
    ids = gate_ids(gates)
    records = record_documents(ddir, _parse_item_status(lines)[2],
                               withdrawn_stage_items(lines))
    for path in docs:
        try:
            text = path.read_text(encoding=_ENCODING)
        except (OSError, UnicodeDecodeError):
            continue
        where = _rel_display(path, repo_root)
        for lineno, line in enumerate(text.splitlines(), start=1):
            for m in _GATE_ID_CITATION_RE.finditer(line):
                ref = m.group("id")
                hits = resolve_gate_ref(ref, gates)
                if not hits:
                    # An unreadable row is dropped before IDs are computed, so
                    # its citations dangle too; the row's own error is the fix.
                    also = (" — or it is one of the unreadable gate rows "
                            "reported above, which has no ID until it is fixed"
                            if unreadable else "")
                    errors.append(
                        f"{where}:{lineno}: {ref} names no human gate in "
                        f"progress.md — its row was removed, or its Gate cell "
                        f"reworded into a different gate{also}; cite an ID "
                        f"`aide gate list` prints (conventions.md §1 → human "
                        f"gates)")
                elif len({gate_hash(gates[i]) for i in hits}) > 1:
                    names = ", ".join(sorted({ids[i] for i in hits}))  # type: ignore[misc]
                    warnings.append(
                        f"{where}:{lineno}: {ref} matches more than one human "
                        f"gate — cite the longer ID of the one meant: {names}")
            if not has_rows or path in records:
                continue
            for m in _GATE_POSITION_RE.finditer(line):
                n = int(m.group("n"))
                now = ""
                if 1 <= n <= len(ids) and ids[n - 1]:
                    now = (f"; gate {n} is {ids[n - 1]} today — cite that if "
                           f"it is the one meant")
                warnings.append(
                    f"{where}:{lineno}: `{m.group(0).strip()}` cites a human "
                    f"gate by position, which a merge renumbers — cite its ID "
                    f"(`aide gate list`){now}")
    return errors, warnings


def tick_insight_text(text: str, ordinal: int, pointer: str,
                      date: str, trail_only: bool = False) -> Tuple[str, str]:
    """Tick entry *ordinal*, or append a dated trail line if already ticked.

    The two halves of conventions.md §1's lifecycle, chosen by the entry's own
    state rather than by a flag: the **first** routing flips the checkbox and
    records where the claim landed on the entry line; **everything after** it —
    a re-route, a resolution, a premise that decayed — is bookkeeping and goes
    in the appendable status trail underneath.

    *trail_only* is the third case §1 → insights-triage.md names — a judgement
    that leaves the entry **open** (a duplicate, a reason it stays untriaged)
    and is still recorded as a dated trail line under it (issue #236). The
    checkbox is not touched; on an entry already ticked it is the ordinary
    second-update path.

    The captured claim is never touched by either path. Returns
    ``(new_text, message)``; raises ``ValueError`` if the ordinal does not
    resolve or the entry is too malformed to edit safely.
    """
    if "\n" in pointer or "\r" in pointer:
        raise ValueError(
            "the pointer may not contain a line break — it is written into a "
            "single entry line, so a break would split one claim into two and "
            "renumber everything below it")
    entries = parse_insights(text)
    entry = _find_entry(entries, ordinal)
    lines = text.splitlines()
    trailing_newline = text.endswith("\n")

    if entry.ticked or trail_only:
        if not entry.ticked and entry.type is None:
            raise ValueError(
                f"entry {ordinal} does not parse as an inbox entry, so there "
                f"is no entry to write a trail line under safely: "
                f"{entry.raw!r}. Fix the line's shape first (`aide check` "
                f"names the rule)")
        # end_lineno is 1-based, so as a 0-based list index it is the slot
        # just past the entry's last line — where the next trail line goes.
        insert_at = entry.end_lineno
        indent = "  "
        if entry.trail:
            indent = entry.trail[-1][: len(entry.trail[-1]) - len(entry.trail[-1].lstrip())]
        lines.insert(insert_at, f"{indent}- **{date}** {_INSIGHT_POINTER.strip()} {pointer}")
        if entry.ticked:
            message = f"entry {ordinal}: already ticked — appended a {date} trail line"
        else:
            message = f"entry {ordinal}: left open — appended a {date} trail line"
    else:
        if entry.type is None:
            raise ValueError(
                f"entry {ordinal} does not parse as an inbox entry, so there "
                f"is no checkbox to tick safely: {entry.raw!r}. Fix the line's "
                f"shape first (`aide check` names the rule)")
        line = entry.raw.replace("- [ ]", "- [x]", 1)
        if entry.pointer is None:
            line = line + _INSIGHT_POINTER + pointer
            message = f"entry {ordinal}: ticked → {pointer}"
        else:
            # A pointer written by hand before the tick: keep it, and record
            # this routing where a second one belongs.
            lines[entry.lineno - 1] = line
            # 1-based end_lineno as a 0-based index = just past the entry.
            lines.insert(entry.end_lineno,
                         f"  - **{date}** {_INSIGHT_POINTER.strip()} {pointer}")
            return ("\n".join(lines) + ("\n" if trailing_newline else ""),
                    f"entry {ordinal}: ticked; existing pointer kept, "
                    f"added a {date} trail line")
        lines[entry.lineno - 1] = line

    return ("\n".join(lines) + ("\n" if trailing_newline else "")), message


def insight_quarter(date: str) -> str:
    """``"2026-08-24"`` → ``"2026-Q3"`` — the archive file an entry belongs to."""
    year, month = int(date[:4]), int(date[5:7])
    return f"{year}-Q{(month - 1) // 3 + 1}"


def archive_insight_text(
    text: str, before: str,
) -> Tuple[str, Dict[str, List[str]], List[InsightEntry]]:
    """Split closed entries dated before *before* out of the live file.

    Returns ``(remaining_text, {quarter: [lines]}, undatable)``, where
    ``undatable`` holds the **closed entries this pass could not date** and so
    could not consider. An entry too malformed to yield a date is excluded from
    every ``--before`` cut however old and however closed it is, and reporting
    it here is what keeps that from being silent: the same pass that declines
    to move it says which lines they were, so the operator can fix a shape
    instead of wondering why the live file will not shrink. It is returned
    rather than logged because this helper is pure — the caller prints.

    **Only ticked entries move**: an open entry is the live working set whatever its date, and
    archiving one would hide exactly the backlog this verb exists to surface.
    An entry travels with its whole status trail, so the archive stays readable
    on its own.

    Pure, and it never rewrites a claim: each line's *text* is carried across
    unchanged, which is what keeps the immutability rule true through the move.
    Line endings are not carried — like every writer in this module, it rebuilds
    the text with ``\n`` — so the promise is the claim, not the bytes around it.
    """
    lines = text.splitlines()
    entries = parse_insights(text)
    moving = {e.ordinal for e in entries
              if e.ticked and e.date is not None and e.date < before}
    # Closed, so it was a candidate; undated, so no cut can ever reach it.
    undatable = [e for e in entries if e.ticked and e.date is None]
    moved: Dict[str, List[str]] = {}
    drop: set = set()
    for e in entries:
        if e.ordinal not in moving:
            continue
        block = lines[e.lineno - 1:e.end_lineno]
        moved.setdefault(insight_quarter(e.date), []).extend(block)
        drop.update(range(e.lineno - 1, e.end_lineno))
    kept = [ln for i, ln in enumerate(lines) if i not in drop]
    return _collapse_blank_runs(kept, text.endswith("\n")), moved, undatable


def _collapse_blank_runs(lines: List[str], trailing_newline: bool) -> str:
    """Join *lines*, leaving at most one blank line where entries were removed.

    Lifting entries out of a blank-separated list otherwise leaves the gaps
    behind, and a file that grows whitespace every time it is tidied is not
    tidied.
    """
    out: List[str] = []
    for line in lines:
        if not line.strip() and out and not out[-1].strip():
            continue
        out.append(line)
    return "\n".join(out) + ("\n" if trailing_newline else "")


# --------------------------------------------------------------------------- #
# insights resolve — an entry-level union of a conflicted inbox
# --------------------------------------------------------------------------- #
#: A checkbox left at the front of a line too malformed to parse as an entry.
#: Stripped before an identity is taken, so a tick on such a line does not make
#: it look like a *different* claim and get appended twice.
_CONFLICT_CHECKBOX_RE = re.compile(r"^\[[ xX]\]\s*")
#: The date a trail line carries, written by `tick` as ``- **YYYY-MM-DD** → …``.
_TRAIL_DATE_RE = re.compile(r"\*\*(\d{4}-\d{2}-\d{2})\*\*")


def split_conflict_sides(text: str) -> Tuple[str, str, int]:
    """Split a conflicted file into its two whole documents.

    Returns ``(ours, theirs, blocks)`` — each side reconstructed as a complete
    file (the common regions plus that side's half of every conflict block),
    and how many blocks there were. Whole documents rather than the hunks
    alone, because the entry numbering that gives an inbox entry its identity
    is positional: a hunk read on its own has no idea which entry it starts at.

    ``diff3``/``zdiff3`` conflict style is understood and its ``|||||||`` base
    section discarded — it belongs to neither side, and appending it to both
    would duplicate every entry the merge base already had.

    Raises ``ValueError`` on a malformed block (nested, unterminated, or a
    closer with no opener). That is a refusal, not a repair: a file whose
    markers do not nest is not a file this verb can reason about.
    """
    ours: List[str] = []
    theirs: List[str] = []
    state = "common"
    blocks = 0
    for lineno, line in enumerate(text.splitlines(), start=1):
        if state == "common":
            if _CONFLICT_OPEN_RE.match(line):
                state = "ours"
            elif _CONFLICT_CLOSE_RE.match(line) or _CONFLICT_BASE_RE.match(line):
                raise ValueError(
                    f"insights.md:{lineno}: {line.split(' ')[0]} outside a "
                    f"conflict block — the markers do not nest")
            else:
                ours.append(line)
                theirs.append(line)
        elif state == "ours":
            if _CONFLICT_BASE_RE.match(line):
                state = "base"
            elif _CONFLICT_SEP_RE.match(line):
                state = "theirs"
            elif _CONFLICT_OPEN_RE.match(line) or _CONFLICT_CLOSE_RE.match(line):
                raise ValueError(
                    f"insights.md:{lineno}: {line.split(' ')[0]} inside an "
                    f"open conflict block — the markers do not nest")
            else:
                ours.append(line)
        elif state == "base":
            if _CONFLICT_SEP_RE.match(line):
                state = "theirs"
            elif (_CONFLICT_OPEN_RE.match(line) or _CONFLICT_CLOSE_RE.match(line)
                    or _CONFLICT_BASE_RE.match(line)):
                raise ValueError(
                    f"insights.md:{lineno}: {line.split(' ')[0]} inside the "
                    f"merge-base section of a conflict block")
            # else: the base's own lines, which belong to neither side.
        else:  # theirs
            if _CONFLICT_CLOSE_RE.match(line):
                state = "common"
                blocks += 1
            elif (_CONFLICT_OPEN_RE.match(line) or _CONFLICT_BASE_RE.match(line)
                    or _CONFLICT_SEP_RE.match(line)):
                raise ValueError(
                    f"insights.md:{lineno}: {line.split(' ')[0]} inside the "
                    f"second half of a conflict block — the markers do not nest")
            else:
                theirs.append(line)
    if state != "common":
        raise ValueError("the last conflict block is never closed — no "
                         "'>>>>>>>' line, so half the file has no second side")
    end = "\n" if text.endswith("\n") else ""
    return ("\n".join(ours) + (end if ours else ""),
            "\n".join(theirs) + (end if theirs else ""), blocks)


def insight_identity(entry: InsightEntry) -> Tuple[str, ...]:
    """What makes two entries the *same* captured claim across two branches.

    The immutable half of an entry and nothing else (conventions.md §1 →
    ``insights.md``): its type, claim text, date and provenance. The checkbox,
    the ``→`` pointer and the status trail are bookkeeping, so an entry ticked
    on one branch and untouched on the other is one entry here — which is what
    lets the tick be merged instead of the claim being appended twice.

    A line too malformed to parse has only itself, minus any checkbox.
    """
    if entry.type is None:
        return ("", _CONFLICT_CHECKBOX_RE.sub("", entry.text).strip())
    return (entry.type, entry.text, entry.date or "", entry.source or "",
            entry.note or "")


def _entry_blocks(text: str) -> Tuple[List[str], List[Tuple[InsightEntry, List[str]]],
                                     List[str]]:
    """``(head, [(entry, its lines)], tail)`` — the file cut at entry boundaries.

    An entry's block runs from its own line to just before the next entry's, so
    whatever sits between two entries (the blank line an archive can leave)
    travels with the entry above it and no line is dropped by a rebuild.
    """
    lines = text.splitlines()
    entries = parse_insights(text)
    if not entries:
        return lines, [], []
    head = lines[:entries[0].lineno - 1]
    blocks: List[Tuple[InsightEntry, List[str]]] = []
    for i, e in enumerate(entries):
        stop = (entries[i + 1].lineno - 1) if i + 1 < len(entries) else e.end_lineno
        blocks.append((e, lines[e.lineno - 1:stop]))
    return head, blocks, lines[entries[-1].end_lineno:]


def _strip_trailing_blanks(lines: List[str]) -> List[str]:
    out = list(lines)
    while out and not out[-1].strip():
        out.pop()
    return out


def _merge_trail(ours: List[str], theirs: List[str]) -> List[str]:
    """Both sides' trail lines, deduplicated, in date order (§1 — newest last).

    The sort is stable and an undated line inherits the date of the line above
    it, so a hand-written continuation stays under the line it continues
    instead of being hoisted to the top of the trail.
    """
    seen = set()
    merged: List[str] = []
    for line in list(ours) + list(theirs):
        key = line.strip()
        if key in seen:
            continue
        seen.add(key)
        merged.append(line)
    keys: List[str] = []
    last = ""
    for line in merged:
        m = _TRAIL_DATE_RE.search(line)
        if m:
            last = m.group(1)
        keys.append(last)
    return [line for _, line in sorted(zip(keys, merged), key=lambda p: p[0])]


def _merge_entry_block(ours: InsightEntry, ours_lines: List[str],
                       theirs: InsightEntry, theirs_lines: List[str],
                       date: str) -> Tuple[List[str], Optional[str]]:
    """Merge one entry both sides hold. Returns ``(lines, flag)``.

    The claim line is taken whole from the side that ticked it, never rebuilt —
    that is how the immutability rule survives a merge. Trails are unioned.
    Two ticks with two different pointers is the one case a machine may not
    decide: both are kept, the second as a dated trail line, and the flag says
    a human must pick.
    """
    if ours_lines == theirs_lines:
        return ours_lines, None
    # Which side's claim line survives, in the order that loses least: the side
    # that ticked, then — when both did — the side carrying a routing pointer.
    # Preferring ours unconditionally dropped `theirs`' pointer whenever ours
    # was ticked without one, and a routing record is the whole reason a tick
    # is worth merging.
    if ours.ticked != theirs.ticked:
        kept, other = (ours, theirs) if ours.ticked else (theirs, ours)
    elif ours.pointer or not theirs.pointer:
        kept, other = ours, theirs
    else:
        kept, other = theirs, ours
    flag = None
    extra: List[str] = []
    if other.pointer and other.pointer != kept.pointer:
        # Two pointers, one per side: the one case a machine may not decide, so
        # it decides nothing and keeps both. Not conditioned on the other side
        # having *ticked* — a pointer written by hand before a tick is a
        # routing record like any other, and dropping it is the silent loss
        # this whole branch exists to prevent.
        extra.append(f"  - **{date}** {_INSIGHT_POINTER.strip()} {other.pointer} "
                     f"(second pointer, from the other side of the merge)")
        flag = (f"entry {ours.ordinal} carries a different pointer on each side "
                f"of the merge ({kept.pointer!r} and {other.pointer!r}); both "
                f"are kept — the entry line carries the first and the second is "
                f"a trail line, so a human must decide which is true")
    trail = _merge_trail(ours.trail, theirs.trail) + extra
    # Anything the block held that is neither the claim nor a trail line, from
    # BOTH sides — ours first. Taking it from ours alone dropped whatever sat
    # under the entry on the other side and still called the merge clean.
    # Blank separators are not among them: the caller strips those and puts
    # each entry's own back.
    rest = [ln for ln in ours_lines[1:] if ln not in ours.trail]
    rest += [ln for ln in theirs_lines[1:]
             if ln not in theirs.trail and ln not in rest]
    return [kept.raw] + trail + rest, flag


def resolve_insights_text(text: str, date: str,
                          base_text: Optional[str] = None,
                          ) -> Tuple[str, List[str], List[str]]:
    """Union the two sides of a conflicted inbox. ``(merged, notes, refusals)``.

    Non-empty ``refusals`` means nothing was merged and the caller must not
    write: the conflict is not the append shape this verb exists for, and the
    only safe thing to do with a claim this code cannot align is leave it in
    front of a human.

    **What "pure append" means here.** Both sides must start with the same
    entries, in the same order, differing only in bookkeeping; everything past
    that point is new on one side or the other and is concatenated, ours then
    theirs. Positional ordinals need no renumbering because nothing moves.

    *base_text* — the merge base, which a conflicted index can supply — makes
    that check exact rather than inferred: the shared history is the base, so a
    rewritten prefix is caught even when the rewrite is at the tail, where the
    two sides alone cannot tell a reworded claim from a second capture. Without
    it the check falls back to the longest common prefix of the two sides,
    which still catches every reorder, deletion and archive: an archive cuts
    closed entries out of the middle, so entries survive on both sides *past*
    the common prefix, and that overlap is a refusal.
    """
    refusals: List[str] = []
    try:
        ours_text, theirs_text, blocks = split_conflict_sides(text)
    except ValueError as exc:
        return text, [], [str(exc)]
    if not blocks:
        return text, [], []

    head_o, blocks_o, tail_o = _entry_blocks(ours_text)
    head_t, blocks_t, tail_t = _entry_blocks(theirs_text)
    if _strip_trailing_blanks(head_o) != _strip_trailing_blanks(head_t):
        refusals.append(
            "the two sides differ above the first entry — the conflict reaches "
            "the file's header, which is not an append; resolve it by hand")
    if _strip_trailing_blanks(tail_o) != _strip_trailing_blanks(tail_t):
        refusals.append(
            "the two sides differ below the last entry — the conflict reaches "
            "past the entry list, which is not an append; resolve it by hand")
    if refusals:
        return text, [], refusals

    ids_o = [insight_identity(e) for e, _ in blocks_o]
    ids_t = [insight_identity(e) for e, _ in blocks_t]
    if base_text is not None:
        ids_b = [insight_identity(e) for e in parse_insights(base_text)]
        n = len(ids_b)
        rewritten = [side for side, ids in (("HEAD", ids_o), ("the other side", ids_t))
                     if ids[:n] != ids_b]
        if rewritten:
            return text, [], [
                f"{' and '.join(rewritten)} rewrote the {n} entr"
                f"{'y' if n == 1 else 'ies'} the two branches share — a claim "
                f"was reworded, reordered, deleted or archived, and §1 makes "
                f"every one of those something a human must see. Resolve this "
                f"one by hand."]
        common = n
    else:
        common = 0
        while (common < len(ids_o) and common < len(ids_t)
               and ids_o[common] == ids_t[common]):
            common += 1

    overlap = set(ids_o[common:]) & set(ids_t[common:])
    if overlap:
        return text, [], [
            f"{len(overlap)} entr{'y' if len(overlap) == 1 else 'ies'} appear"
            f"{'s' if len(overlap) == 1 else ''} on both sides after the "
            f"history they share — the file was reordered or an archive cut "
            f"entries out of the middle of it, so the two sides are not one "
            f"append on top of a common prefix. Resolve this one by hand "
            f"(first: {' | '.join(x[1] for x in sorted(overlap))[:120]})"]

    # A blank line between two entries belongs to neither entry, and only a
    # *last* entry can lack one — its blanks went to the file's tail instead.
    # So the two sides can disagree about an entry neither of them touched,
    # purely by where it sits. Each entry is therefore split into its own lines
    # and its own trailing blanks: the lines are merged, and the blanks are
    # carried through untouched, so an entry nobody edited is re-emitted with
    # exactly the spacing it had. Only a *join* the append newly created — an
    # entry that was last on its side and now has one behind it — needs a
    # separator supplied, and the one it had is the one its own side's tail is
    # still holding.
    strip = _strip_trailing_blanks

    def own(block: List[str]) -> List[str]:
        return block[len(strip(block)):]

    def leading_blanks(lines: List[str]) -> List[str]:
        out: List[str] = []
        for line in lines:
            if line.strip():
                break
            out.append(line)
        return out

    last_o = len(blocks_o) - 1
    last_t = len(blocks_t) - 1
    # What each side's final entry would have been followed by, had anything
    # followed it. Empty for a file whose entries sit on consecutive lines.
    end_o = leading_blanks(tail_o)
    end_t = leading_blanks(tail_t)

    def spacing(*candidates: List[str]) -> List[str]:
        for c in candidates:
            if c:
                return c
        return []

    # (block, what followed it, whether it ended its side). A block that ended
    # its side and was followed by nothing has no observed spacing at all —
    # that is the join the append newly created, and the only place a
    # separator may be *invented*. Everywhere else an empty `after` is a fact
    # about the file, and re-spacing entries neither side touched on the
    # strength of a blank line somewhere else in the file is a reformat.
    merged_blocks: List[Tuple[List[str], List[str], bool]] = []
    flags: List[str] = []
    ticks = 0
    for i, ((eo, lo), (et, lt)) in enumerate(
            zip(blocks_o[:common], blocks_t[:common])):
        block, flag = _merge_entry_block(eo, strip(lo), et, strip(lt), date)
        if strip(lo) != strip(lt):
            # A shared claim whose bookkeeping the two sides disagreed on —
            # counted whichever side won, since the decision is the news.
            ticks += 1
        if flag:
            flags.append(flag)
        merged_blocks.append((block, spacing(
            own(lo), own(lt),
            end_o if i == last_o else [], end_t if i == last_t else []),
            i == last_o or i == last_t))
    for i, (_, blk) in enumerate(blocks_o[common:], start=common):
        merged_blocks.append((strip(blk),
                              spacing(own(blk), end_o if i == last_o else []),
                              i == last_o))
    for i, (_, blk) in enumerate(blocks_t[common:], start=common):
        merged_blocks.append((strip(blk),
                              spacing(own(blk), end_t if i == last_t else []),
                              i == last_t))

    out: List[str] = list(head_o)
    previous: List[str] = []
    for i, (block, after, ended_a_side) in enumerate(merged_blocks):
        out.extend(block)
        if i == len(merged_blocks) - 1:     # the last entry's blanks are the tail's
            break
        # Inherit from the entry above only where there is nothing to inherit
        # *from* the entry itself, which is exactly the newly created join.
        after = after or (previous if ended_a_side else [])
        out.extend(after)
        previous = after
    out.extend(tail_o)

    notes = [f"{common} entr{'y' if common == 1 else 'ies'} shared, "
             f"{len(blocks_o) - common} added on HEAD, "
             f"{len(blocks_t) - common} added on the other side, "
             f"{ticks} merged in place"]
    notes.extend(flags)
    merged_text = "\n".join(out) + ("\n" if text.endswith("\n") else "")
    return merged_text, notes, []


def absolute_path_test_warnings(repo_root: Path,
                                config: Dict[str, Dict[str, object]]) -> List[str]:
    """Warn on a test file containing the repository's own absolute path.

    The one portability rule of conventions.md §6 a script can decide, and the
    one whose recorded instance was invisible to every other gate for weeks: a
    test pinned the authoring sandbox's own filesystem path instead of
    resolving relative to the test file. Because that path *is* where the
    project sits on that machine, it passed the builder's run, both validator
    rounds, and even a fresh clone into a different directory — an absolute
    path ignores where the process runs from. On every CI runner the glob
    matched nothing, the digest collapsed to SHA-256 of empty input, and all
    four legs failed.

    Matching the repo root literally keeps this exact: a test that hardcodes
    the path of the repository it lives in is wrong on any other machine, with
    no judgement call and no false positive to argue about.
    """
    tests_dir = repo_root / str(config["project"].get("tests_dir", "tests"))
    if not tests_dir.is_dir():
        return []
    # Three spellings, because the offending literal is whatever the authoring
    # platform wrote and this check must fire wherever it runs. On POSIX all
    # three collapse to one string; on Windows they are genuinely different:
    #   as_posix()  C:/path/to/repo    — a forward-slash literal
    #   str()       C:\path\to\repo    — a raw string, r"C:\path\to\repo"
    #   escaped     C:\\path\\to\\repo — an ordinary literal, the COMMON form
    # Omitting the third would make this portability lint miss the most likely
    # Windows spelling of the very defect it exists to catch.
    root = repo_root.resolve()
    needles = {root.as_posix(), str(root), str(root).replace("\\", "\\\\")}
    out: List[str] = []
    for path in sorted(tests_dir.rglob("*.py")):
        if "__pycache__" in path.parts:
            continue
        try:
            text = path.read_text(encoding=_ENCODING)
        except (OSError, UnicodeDecodeError):
            continue
        for lineno, line in enumerate(text.splitlines(), start=1):
            if any(n in line for n in needles):
                rel = _rel_display(path, repo_root)
                out.append(
                    f"{rel}:{lineno}: contains this repository's absolute path — "
                    f"it passes here and matches nothing on any other checkout; "
                    f"resolve from the test file instead "
                    f"(Path(__file__).resolve().parents[N]). See conventions.md §6")
                break   # one warning per file is enough to act on
    return out


def _reach_with_breadth(lines: List[str], g: HumanGate) -> str:
    """*g*'s reach with the held items resolved and counted.

    A ``stage N`` reach reads plausibly right while holding items its author
    never meant to hold — the observed case gated the very deliberation that
    was to produce the gate's evidence. ``aide claim`` already names what it
    holds, but that surfaces only when a runner stalls; the check computes the
    same breadth (``gate_stage_items``) and used to throw it away, so the
    contradiction was invisible at authoring time. Only the stage forms need
    resolving, a ``stage N+`` or ``stage N–M`` reach most of all: an
    item-list reach already names its items, and ``all`` is its own answer.

    The count covers the items the gate still sits in front of: a ✅ item has
    merged and a ❌ one is out, so "holding" either would overstate the reach
    against the very enforcement this message mirrors. "Out" is read as
    ``_declined_reach_spent`` reads it (issue #409): ❌ by the item's own
    bullets, or 📋 with every bullet in a withdrawn stage
    (``spent_by_withdrawal``) — ``claim`` offers neither, so a warning that
    goes quiet on that reading must not count them while it still fires.
    (``claim``'s stall report narrows further, to the claimable subset of one
    queue — that is the runtime view; this is the authoring-time view of the
    same fact, and a stage whose every item merged falls back to the bare
    reach.)
    """
    if g.stage is None:
        return g.reach
    _, _, item_status = _parse_item_status(lines)
    left = spent_by_withdrawal(lines, item_status)
    items = [i for i in gate_stage_items(lines, g)
             if item_status.get(i) != "complete" and i not in left]
    if not items:
        return g.reach
    return (f"{g.reach} — holding {len(items)} item(s): "
            + ", ".join(f"{i:03d}" for i in items))


def _declined_reach_spent(lines: List[str], g: HumanGate) -> bool:
    """True when declined gate *g* holds nothing open, now or later (issue #396).

    Such a gate has already been re-planned: its items have merged or left,
    or its Blocks cell is deliberately empty (``—``), kept as the record after
    the question was re-asked. The check's "still blocks … drop those items
    or change what the gate asks" then names a remedy with nothing to apply
    it to, on every run, and no verb can close it. Enforcement is not touched
    — ``blocking_gates`` still lists the gate — only the warning goes quiet.

    "Open" is what ``claim`` would still offer were the gate gone: an item is
    spent when it is ✅, or ❌ by its own bullets or by every one of them
    sitting in a withdrawn stage while it is 📋 (``spent_by_withdrawal``,
    which ``claim`` never offers either). Anything else — an item with no
    bullet at all included — is open. Everything that could still hold work
    later reads open too, erring toward the warning:

    - a Blocks cell that is not empty yet names no reach (``stage 3a``,
      ``TBD``) is a typo, not a decision to hold nothing;
    - ``all`` holds every item, including ones not written yet;
    - ``stage N+`` arms every stage numbered from N on, written or not;
    - each stage of a ``stage N`` / ``stage N–M`` reach must be written, and
      every item its bullets reference spent; a stage still in scope must
      also have at least one bullet, every one ✅ or ❌ — one not written
      yet, or with nothing queued, may still receive the refused work.
      A withdrawn stage (❌ summary row) needs no bullet of its own.
    """
    if g.blocks_all or g.stage_open:
        return False
    item_status = _parse_item_status(lines)[2]
    left = spent_by_withdrawal(lines, item_status)

    def spent(n: int) -> bool:
        return item_status.get(n) == "complete" or n in left

    if g.stage is None:
        if not g.blocks:
            return g.blocks_cell.strip() in _EMPTY_CELL
        return all(spent(n) for n in g.blocks)
    first, last = g.stage_range
    withdrawn = {int(n) for n in withdrawn_stages(lines) if n.strip().isdigit()}
    sections: Dict[int, Tuple[int, int, str]] = {}
    for sec in stage_sections(lines):
        if sec[2].isdigit():
            sections.setdefault(int(sec[2]), sec)
    if last - first + 1 > len(sections) + len(withdrawn):
        return False   # some stage in the range is not written yet
    for n in range(first, last + 1):
        if n not in sections:
            if n in withdrawn:
                continue   # withdrawn, and no section to hold an item
            return False
        start, end, num = sections[n]
        if n not in withdrawn:
            statuses = stage_deliverable_statuses(lines, start, end)
            if not statuses or any(s not in ("complete", "excluded")
                                   for s in statuses):
                return False
        if not all(spent(i) for i in stage_item_numbers(lines, num)):
            return False
    return True


def gate_warnings(lines: List[str]) -> List[str]:
    """One warning per unresolved human gate.

    A warning, never an error: an outstanding gate is a normal state — work is
    waiting on a person, which is what it is for. The point is that the state
    is *visible* rather than buried in an item spec's prose. A row too
    mis-shaped to be a gate is not a state but a defect, and is an error in
    ``unreadable_row_errors``.
    """
    out: List[str] = []
    gates = human_gates(lines)
    for n, (g, gid) in enumerate(zip(gates, gate_ids(gates)), start=1):
        if g.kind == "approved":
            continue
        name = f"human gate {n}{', ' + gid if gid else ''} ({g.text})"
        if g.kind is None:
            out.append(
                f"progress.md:{g.lineno}: {name} has an "
                f"unrecognised status — use ⏳ Awaiting, ✅ Approved or ❌ Declined; "
                f"until it reads one of those the gate counts as unresolved")
            continue
        rng = g.stage_range
        if rng is not None and rng[1] is not None and rng[1] < rng[0]:
            # Malformed, not merely empty: every stage from N to a smaller M
            # is none, so the gate holds nothing whatever it was decided —
            # and "stage 8–6" reads like a guarded range to anyone skimming.
            out.append(
                f"progress.md:{g.lineno}: {name} reaches {g.reach} — a "
                f"reversed range, whose first stage is after its last, so "
                f"this gate holds NOTHING; write it as stage {rng[1]}–{rng[0]}")
            continue
        if g.kind == "declined":
            if _declined_reach_spent(lines, g):
                # Re-planned already: nothing left to drop, so the remedy the
                # warning names cannot be followed (issue #396).
                continue
            if not (g.blocks or g.stage or g.blocks_all):
                # A cell that is not empty and names no reach: a typo, which
                # the silence above must not swallow.
                out.append(
                    f"progress.md:{g.lineno}: {name} was DECLINED and its "
                    f"Blocks cell '{g.blocks_cell}' names no item, no "
                    f"'stage N' (or 'stage N+', 'stage N–M'), and is not "
                    f"'all' — write '—' if the gate is meant to hold "
                    f"nothing, or the reach it was meant to hold")
                continue
            out.append(
                f"progress.md:{g.lineno}: {name} was DECLINED "
                f"and still blocks {_reach_with_breadth(lines, g)} — a refusal does not release the "
                f"work it guards; drop those items or change what the gate asks")
            continue
        if g.stage is not None and (g.stage_open or g.stage_last is not None) \
                and not gate_stage_items(lines, g):
            # The multi-stage forms. For `stage N+` a missing stage is the
            # expected state — the reach exists to cover stages not written
            # yet — so it is armed whether or not any stage >= N exists. A
            # closed range none of whose stages exists is the typo case.
            first, last = rng
            if g.stage_open:
                reach = (f"{g.reach} — which has no items queued yet, so it "
                         f"holds nothing today and will block the items of "
                         f"stage {first} and every later stage as they are "
                         f"created")
            elif not gate_stage_numbers(lines, g):
                reach = (f"{g.reach} — no stage numbered {first} to {last} "
                         f"exists, so this gate holds NOTHING; check the "
                         f"stage numbers")
            else:
                reach = (f"{g.reach} — which has no items queued yet, so it "
                         f"holds nothing today and will block the items of "
                         f"stages {first} to {last} as they are created")
        elif g.stage is not None and not gate_stage_items(lines, g):
            # An empty reach has two causes and only one is a mistake.
            if stage_section(lines, g.stage) is None:
                # No such section: a typo, invisible otherwise — the gate looks
                # like it guards a stage while holding nothing at all, ever.
                reach = (f"stage {g.stage} — which has no deliverable "
                         f"referencing any item, so this gate holds NOTHING; "
                         f"check the stage number")
            else:
                # The section is there and simply has nothing queued for it
                # yet. Raising a gate before the work exists is the cheapest
                # time to raise one, and `stage N` reach re-resolves through
                # progress.md on every read — so this gate is armed and will
                # hold that stage's items as they appear. Calling the feature's
                # own happy path a typo trains the reader to ignore the check.
                reach = (f"stage {g.stage} — which has no items queued yet, so "
                         f"it holds nothing today and will block that stage's "
                         f"items as they are created")
        elif g.blocks or g.stage or g.blocks_all:
            reach = _reach_with_breadth(lines, g)
        else:
            # Quote a non-empty cell, as the declined branch does: the typo
            # is then on the line that reports it.
            cell = ("" if g.blocks_cell.strip() in _EMPTY_CELL
                    else f" '{g.blocks_cell}'")
            reach = (f"nothing named — the Blocks cell{cell} names no item, "
                     "no 'stage N' (or 'stage N+', 'stage N–M'), and is not "
                     "'all', so this gate holds nothing")
        out.append(f"progress.md:{g.lineno}: {name} is "
                   f"awaiting a decision — blocks {reach}")
    return out


#: A deliverable bullet must be FLAT (conventions.md §1). `_BULLET_RE` allows
#: leading whitespace, so a nested bullet is read as a **full deliverable** —
#: not ignored. That is the hazard: nesting implies subordination to a reader
#: while the rollup counts it as a peer, so a `📋` child silently drags its ✅
#: parent's stage to 🚧. Verified: ['complete', 'planned'] -> in-progress.
_NESTED_DELIVERABLE_RE = re.compile(r"^\s+[-*]\s*(?P<icon>" + _ICON_ALT + r")")

#: Documents whose template carries a header blockquote. Not every file under
#: docs_dir: a generated artifact or a project note is not a living document,
#: and insights.md's template deliberately opens with a comment instead.
_BLOCKQUOTE_DOCS = ("vision.md", "roadmap.md", "progress.md")

#: A status FIELD in an item header: `**Status:** x` or `**Status**: x`. The
#: colon is required, so bold emphasis on the word in prose is not a match.
_ITEM_STATUS_FIELD_RE = re.compile(
    r"\*\*\s*(?P<name>Status|Completed)\s*(?::\s*\*\*|\*\*\s*:)")


#: Calls that spawn a process. Matched through the AST, never by line text: the
#: one occurrence in the consumer measured against was a DOCSTRING explaining
#: why the author had removed a subprocess — a line-based lint flags the file
#: documenting the correct practice.
_SUBPROCESS_FUNCS = frozenset({"run", "Popen", "check_output", "check_call", "call"})


def _rel_display(path: Path, repo_root: Path) -> str:
    """*path* relative to the repo for a message, falling back to absolute.

    `tests_dir` may be configured absolute or resolve outside the repo via a
    symlink, and `relative_to` raises then. Shared by every test-hygiene lint:
    fixing this once in `absolute_path_test_warnings` and then hand-writing the
    same call in two new ones is exactly how it came back.
    """
    try:
        return path.relative_to(repo_root).as_posix()
    except ValueError:
        return path.as_posix()


def _test_files(repo_root: Path, config: Dict[str, Dict[str, object]]) -> List[Path]:
    tests_dir = repo_root / str(config["project"].get("tests_dir", "tests"))
    if not tests_dir.is_dir():
        return []
    return [p for p in sorted(tests_dir.rglob("*.py"))
            if "__pycache__" not in p.parts]


def separator_dependent_test_warnings(repo_root: Path,
                                      config: Dict[str, Dict[str, object]]) -> List[str]:
    """Tests stringifying a relative `Path` into a value that gets compared.

    conventions.md §6: any `Path` entering a hash, comparison or match must be
    `.as_posix()`. Narrowed to `.relative_to(`, the shape all four recorded
    CI-only failures took, reached two ways — an explicit `str(...)` and an
    f-string, which calls `str()` for you.

    Matched through the AST, because a regex cannot tell an f-string's `{...}`
    from a dict or set literal: `{p.relative_to(root): 1}` never stringifies the
    Path and must not be flagged. A lint that cries wolf stops being read.
    """
    out: List[str] = []
    for path in _test_files(repo_root, config):
        try:
            tree = ast.parse(path.read_text(encoding=_ENCODING))
        except (OSError, UnicodeDecodeError, SyntaxError):
            continue

        def _ends_in_relative_to(node) -> bool:
            """True when the OUTERMOST call of *node* is `.relative_to(...)`.

            Deliberately the outermost, not anywhere in the subtree: searching
            the subtree flags `str(p.relative_to(root).as_posix())`, which is
            already separator-stable and is exactly what the rule asks for.
            Flagging compliant code is how a lint stops being read, so this
            errs narrow — it reports the recorded shape and stays quiet on
            anything already normalised.
            """
            return (isinstance(node, ast.Call)
                    and isinstance(node.func, ast.Attribute)
                    and node.func.attr == "relative_to")

        for node in ast.walk(tree):
            hit = False
            if (isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                    and node.func.id == "str" and len(node.args) == 1):
                hit = _ends_in_relative_to(node.args[0])
            elif isinstance(node, ast.JoinedStr):
                hit = any(_ends_in_relative_to(v.value) for v in node.values
                          if isinstance(v, ast.FormattedValue))
            if hit:
                out.append(
                    f"{_rel_display(path, repo_root)}:{node.lineno}: a relative "
                    f"Path rendered with str() carries the OS separator, so this "
                    f"value differs on Windows — use .as_posix() "
                    f"(conventions.md §6)")
                break
    return out


def cli_subprocess_test_warnings(repo_root: Path,
                                 config: Dict[str, Dict[str, object]]) -> List[str]:
    """Tests shelling out to `aide.py` instead of calling its function.

    conventions.md §6: prefer calling the function over shelling out to the
    command that calls it. The logic is importable and returns structured data;
    the subprocess adds stdout encoding, platform quirks, and a re-parse of what
    was structured a moment earlier. The recorded instance returned
    ``stdout is None`` on a Windows runner — and had it returned ``""`` the test
    would have passed while checking nothing.

    **No exemption for the self-referential case**, asked for and declined
    (issue #123). A test whose whole job is to replay `aide check`'s literal
    stdout trips this rule, which reads like the verb flagging itself. It is
    not: `cmd_check` calls `run_checks`, that function returns
    ``(errors, warnings)`` as structured data, and asserting on it in-process
    is both the fix and the better test — which is what the reporting consumer
    did. Exempting the shape would license the worse test in the one place the
    argument for it sounds strongest.

    What the report actually found is a *measurement* defect, and it belongs to
    the spec, not to this lint: a module that shells out to the CLI raises the
    warning count by one the moment it is committed, so any baseline count
    recorded before it existed is falsified by the act of adding it. Measured:
    a spec recorded 3, the base commit already carrying the module reported 4,
    and the 4th was the module. §6 now says never to pin a count that way.
    """
    out: List[str] = []
    for path in _test_files(repo_root, config):
        try:
            tree = ast.parse(path.read_text(encoding=_ENCODING))
        except (OSError, UnicodeDecodeError, SyntaxError):
            continue
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            func = node.func
            name = func.attr if isinstance(func, ast.Attribute) else getattr(func, "id", "")
            if name not in _SUBPROCESS_FUNCS:
                continue
            if any(isinstance(c, ast.Constant) and isinstance(c.value, str)
                   and "aide.py" in c.value for c in ast.walk(node)):
                rel = _rel_display(path, repo_root)
                out.append(
                    f"{rel}:{node.lineno}: shells out to aide.py — call the "
                    f"function instead (e.g. run_checks); a subprocess adds a "
                    f"stdout/encoding surface that has failed on Windows only, "
                    f"and can pass while checking nothing (conventions.md §6)")
                break
    return out


#: Branch names a hardcoded diff range is written against. The configured
#: `main_branch` is the honest one; `main` and `master` ride along because this
#: shape is copied between projects — a consumer whose base is `develop` and
#: whose test says `main...HEAD` has written the same wrong assertion, and the
#: lint that only knew its own config would stay silent on it.
_CONVENTIONAL_BASES = ("main", "master")


def _scope_range_re(config: Dict[str, Dict[str, object]]) -> "re.Pattern":
    names = {str(config["git"].get("main_branch", "main")), *_CONVENTIONAL_BASES}
    alt = "|".join(re.escape(n) for n in sorted(names))
    return re.compile(rf"\b(?:origin/)?(?:{alt})\.{{2,3}}HEAD\b"
                      rf"|\bHEAD\.{{2,3}}(?:origin/)?(?:{alt})\b")


def scope_claim_test_warnings(repo_root: Path,
                              config: Dict[str, Dict[str, object]]) -> List[str]:
    """Diff-time scope claims written as suite assertions.

    §1 → authorised-paths-proof says a *diff-time scope claim* — "item N did
    not touch X" — belongs under **Asserts against** and is retired when its
    item merges, and `cmd_scope` exists precisely so the claim is not
    "enshrined as a suite assertion that outlives its truth". Both statements were already written
    down, and reached neither the spec-author writing the criterion nor the
    test-writer implementing it: two independent items in one consumer wrote the
    same `git diff main...HEAD` guard (issue #132), which is the signature of a
    missing check rather than a careless author.

    The shape fails in the direction that wastes the most time. Under a stacked
    queue the item's base is the **queue branch**, so `main` is stale by the
    whole queue and every sibling item's legitimate change is reported as this
    item's scope violation. The obvious repair is wrong too: deriving the base
    from `aide scope` makes the assertion pass only while the suite runs on the
    item's own claim branch, and `aide merge` re-runs that suite from the merge
    target — so it fails by construction inside the loop's own post-merge run.
    Skip-guarding is not an escape either: once the claim branch is deleted the
    test is skipped forever, which §6 ("tests that can actually fail") forbids.

    **Two literal shapes, deliberately, and no attempt at the general one.** A
    hardcoded `<base>...HEAD` range, and a shell-out to `aide scope`. A test
    that diffs the branch against a base it computes — `git merge-base HEAD
    origin/main`, then `diff` — is NOT reported, and this framework's own
    `tests/test_repo_versioning.py` is why: it is that shape, it is legitimate,
    and it is a claim about the branch rather than about an item's scope. No
    lint can tell those apart from the source, so this one decides only what is
    literal, and §6's rule holds where it cannot look. An interpolated range
    (`f"{base}...HEAD"`) is missed for the same reason.

    The `aide scope` half also trips `cli_subprocess_test_warnings`, which says
    "call the function instead". That advice is right about the boundary and
    wrong about the fix — the assertion should not be in the suite at all — so
    this warning is worth its line beside it.
    """
    out: List[str] = []
    rng = _scope_range_re(config)
    for path in _test_files(repo_root, config):
        try:
            tree = ast.parse(path.read_text(encoding=_ENCODING))
        except (OSError, UnicodeDecodeError, SyntaxError):
            continue
        rel = _rel_display(path, repo_root)
        hit = next((n for n in ast.walk(tree)
                    if isinstance(n, ast.Constant) and isinstance(n.value, str)
                    and rng.search(n.value)), None)
        if hit is not None:
            out.append(
                f"{rel}:{hit.lineno}: a hardcoded '{rng.search(hit.value).group(0)}' "
                f"range makes this test a diff-time scope claim — it asserts "
                f"what an item did NOT touch, which stops being true the moment "
                f"that item merges into the base, and is red by construction on "
                f"a stacked queue where the real base is the queue branch. "
                f"Declare the pinned file under '## Asserts against' in the item "
                f"spec and let 'aide scope' decide it on the claim branch "
                f"(conventions.md §1 → authorised-paths-proof, §6)")
            continue
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            func = node.func
            name = func.attr if isinstance(func, ast.Attribute) else getattr(func, "id", "")
            if name not in _SUBPROCESS_FUNCS:
                continue
            consts = [c.value for c in ast.walk(node)
                      if isinstance(c, ast.Constant) and isinstance(c.value, str)]
            if not any("aide.py" in c for c in consts):
                continue
            if not any(c == "scope" or c.endswith(" scope") or " scope " in c
                       for c in consts):
                continue
            out.append(
                f"{rel}:{node.lineno}: shells out to 'aide scope' from the "
                f"suite — the verb resolves its base from the CURRENT branch's "
                f"recorded base, so this passes only while the suite runs on "
                f"the item's own claim branch and fails by construction in "
                f"the post-merge run of 'aide merge', from the merge target. "
                f"Scope is "
                f"checked on the branch, not asserted in the suite: declare the "
                f"pinned file under '## Asserts against' instead "
                f"(conventions.md §1 → authorised-paths-proof, §6)")
            break
    return out


#: Calls whose first argument is a path the result still names: a `Path`
#: built from it, a file opened on it, a string joined onto it. The rest of the
#: arguments of the joining ones are appended as further pieces.
_PATH_BUILDERS = frozenset({"Path", "PurePath", "PurePosixPath", "PureWindowsPath",
                            "WindowsPath", "PosixPath", "open", "join", "joinpath",
                            "resolve", "absolute"})
#: Calls that stand for the directory the suite runs from — the repository,
#: under every runner that starts in it.
_CWD_CALLS = frozenset({"cwd", "getcwd"})


def _path_pieces(value: str) -> Optional[List[str]]:
    """A literal path's pieces, either separator; None for an absolute one."""
    if value.startswith(("/", "\\")) or re.match(r"^[A-Za-z]:", value):
        return None
    return [p for p in re.split(r"[\\/]+", value) if p not in ("", ".")]


def _repo_path(node: ast.AST, env: Dict[str, Tuple[str, List[str]]]
               ) -> Optional[Tuple[str, List[str]]]:
    """Where *node* points, as far as literals say: ``(root, pieces)``.

    *root* is ``"repo"`` for anything derived from ``__file__``, ``"cwd"`` for
    a relative literal or ``Path.cwd()``/``os.getcwd()``, ``"other"`` for any
    name the module never bound to one of those (``tmp_path``, a fixture
    argument). *pieces* are the literal path components appended after it.
    ``None`` when the expression is not a path built this way at all.
    """
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        pieces = _path_pieces(node.value)
        return None if pieces is None else ("cwd", pieces)
    if isinstance(node, ast.Name):
        if node.id == "__file__":
            return ("repo", [])
        return env.get(node.id, ("other", []))
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Div):
        left = _repo_path(node.left, env)
        if left is None or not (isinstance(node.right, ast.Constant)
                                and isinstance(node.right.value, str)):
            return None
        right = _path_pieces(node.right.value)
        return None if right is None else (left[0], left[1] + right)
    if isinstance(node, (ast.Attribute, ast.Subscript)):
        # `Path(__file__).resolve().parents[2]`, `ROOT.parent`: navigation
        # keeps the anchor and drops the pieces — they no longer end the path.
        inner = _repo_path(node.value, env)
        return None if inner is None else (inner[0], [])
    if isinstance(node, ast.Call):
        func = node.func
        name = func.attr if isinstance(func, ast.Attribute) else getattr(func, "id", "")
        if name in _CWD_CALLS:
            return ("cwd", [])
        if name not in _PATH_BUILDERS:
            return None
        receiver = (func.value if isinstance(func, ast.Attribute)
                    and name in ("joinpath", "resolve", "absolute") else None)
        args = list(node.args)
        if receiver is not None:
            base = _repo_path(receiver, env)
        elif args:
            base = _repo_path(args.pop(0), env)
        else:
            return None
        if base is None:
            return None
        pieces = list(base[1])
        for a in args:
            if not (isinstance(a, ast.Constant) and isinstance(a.value, str)):
                return None
            more = _path_pieces(a.value)
            if more is None:
                return None
            pieces += more
        return (base[0], pieces)
    return None


_COMPREHENSIONS = (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)
_SCOPE_NODES = (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda, ast.ClassDef,
                *_COMPREHENSIONS)
#: Capture patterns bind the name they carry (``case [ROOT]:``). Read by type
#: name, never as ``ast.MatchAs``: the engine's floor is Python 3.9, which has
#: no ``match`` statement and no such classes.
_MATCH_CAPTURES = {"MatchAs": "name", "MatchStar": "name", "MatchMapping": "rest"}


def _comprehension_walrus_targets(comp: ast.AST) -> Set[str]:
    """Names a walrus inside *comp* binds — in the enclosing function, as
    Python does, however deep the comprehensions nest (lambdas and functions
    inside stop it)."""
    names: Set[str] = set()
    stack = [comp]
    while stack:
        node = stack.pop()
        if isinstance(node, ast.NamedExpr) and isinstance(node.target, ast.Name):
            names.add(node.target.id)
        for child in ast.iter_child_nodes(node):
            if not isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef,
                                      ast.Lambda, ast.ClassDef)):
                stack.append(child)
    return names


def _scope_parts(scope: ast.AST) -> Tuple[List[ast.AST], List[ast.AST]]:
    """``(own nodes, child scopes)`` of a module, function, lambda, class or
    comprehension.

    A nested scope's decorators and default values, and a comprehension's
    outermost iterable, are evaluated in the enclosing one, so they are walked
    as its nodes; the rest of the nested scope is not.
    """
    if isinstance(scope, _COMPREHENSIONS):
        roots: List[ast.AST] = ([scope.key, scope.value] if isinstance(scope, ast.DictComp)
                                else [scope.elt])
        for i, g in enumerate(scope.generators):
            roots += [g.target] + ([g.iter] if i else []) + list(g.ifs)
    elif isinstance(scope, ast.Lambda):
        roots = [scope.body]
    elif isinstance(scope, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
        roots = list(scope.body)
    else:
        roots = [scope]
    own: List[ast.AST] = []
    children: List[ast.AST] = []
    stack = list(reversed(roots))
    while stack:
        node = stack.pop()
        if node is not scope and isinstance(node, _SCOPE_NODES):
            children.append(node)
            outer: List[ast.AST] = list(getattr(node, "decorator_list", []))
            if isinstance(node, _COMPREHENSIONS):
                outer.append(node.generators[0].iter)
            elif isinstance(node, ast.ClassDef):
                outer += node.bases + [k.value for k in node.keywords]
            else:
                outer += [d for d in node.args.defaults + node.args.kw_defaults if d]
            stack.extend(reversed(outer))
            continue
        own.append(node)
        stack.extend(reversed(list(ast.iter_child_nodes(node))))
    return own, children


def _local_names(scope: ast.AST, own: List[ast.AST],
                 children: List[ast.AST]) -> Set[str]:
    """Every name *scope* binds, so shadows for its whole body — as Python does.

    A comprehension binds its targets and nothing else: a walrus inside one
    binds in the enclosing scope, so it is counted there.
    """
    names: Set[str] = set()
    if isinstance(scope, _COMPREHENSIONS):
        for g in scope.generators:
            names.update(n.id for n in ast.walk(g.target) if isinstance(n, ast.Name))
        return names
    if isinstance(scope, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
        a = scope.args
        for arg in a.posonlyargs + a.args + a.kwonlyargs + [a.vararg, a.kwarg]:
            if arg is not None:
                names.add(arg.arg)
    declared: Set[str] = set()
    for node in own:
        if isinstance(node, ast.Name) and isinstance(node.ctx, (ast.Store, ast.Del)):
            names.add(node.id)
        elif isinstance(node, (ast.Import, ast.ImportFrom)):
            names.update((al.asname or al.name).split(".")[0] for al in node.names)
        elif isinstance(node, ast.ExceptHandler) and node.name:
            names.add(node.name)
        elif isinstance(node, (ast.Global, ast.Nonlocal)):
            declared.update(node.names)
        elif type(node).__name__ in _MATCH_CAPTURES:
            bound = getattr(node, _MATCH_CAPTURES[type(node).__name__], None)
            if bound:
                names.add(bound)
    for c in children:
        if isinstance(c, _COMPREHENSIONS):
            names.update(_comprehension_walrus_targets(c))
        elif not isinstance(c, ast.Lambda):
            names.add(c.name)
    return names - declared


def _repo_rooted_reads(tree: ast.AST, target: List[str]) -> List[ast.AST]:
    """Nodes building a repo-rooted path ending in *target*, scope by scope.

    Each module, function, lambda, class body and comprehension resolves
    names in its own
    environment: the enclosing one's bindings, minus every name this scope
    binds anywhere (a parameter such as ``tmp_path``, an assignment, an
    import), plus its own repo- or cwd-rooted bindings, found to a fixpoint so
    ``DOCS = ROOT / "docs"`` resolves whichever order the two are written in.
    A class body's names are not seen by its methods, as in Python.
    """
    hits: List[ast.AST] = []

    def visit(scope: ast.AST, parent: Dict[str, Tuple[str, List[str]]]) -> None:
        own, children = _scope_parts(scope)
        local = _local_names(scope, own, children) if not isinstance(scope, ast.Module) else set()
        env = {k: v for k, v in parent.items() if k not in local}
        assigns = [n for n in own if isinstance(n, (ast.Assign, ast.AnnAssign))]
        for _ in range(len(assigns) + 1):
            changed = False
            for a in assigns:
                if a.value is None:
                    continue
                where = _repo_path(a.value, env)
                if where is None or where[0] == "other":
                    continue
                targets = a.targets if isinstance(a, ast.Assign) else [a.target]
                for t in targets:
                    if isinstance(t, ast.Name) and env.get(t.id) != where:
                        env[t.id] = where
                        changed = True
            if not changed:
                break
        for node in own:
            if not isinstance(node, (ast.BinOp, ast.Call)):
                continue
            where = _repo_path(node, env)
            if (where is not None and where[0] in ("repo", "cwd")
                    and where[1][-len(target):] == target):
                hits.append(node)
        inherit = parent if isinstance(scope, ast.ClassDef) else env
        for child in children:
            visit(child, inherit)

    visit(tree, {})
    return hits


def insights_fixture_test_warnings(repo_root: Path,
                                   config: Dict[str, Dict[str, object]]) -> List[str]:
    """Tests reading the live insight inbox as a fixture.

    conventions.md §6: a test never uses a living document as a fixture. The
    inbox is the one that cost most (issue #276): merged tests asserted
    properties of specific ticked entries by reading ``insights.md`` itself,
    so an archive turned six of them red and the inbox could not be archived
    until they changed; and a test that pinned one entry's checkbox as
    unticked blocked every merge the moment triage ticked it.

    **What is recognised.** A path whose last pieces are docs_dir's pieces
    then ``insights.md``, rooted at the repository: built from ``__file__``
    (directly, or through a name the module binds to such a path, followed
    through reassignment), from ``Path.cwd()``/``os.getcwd()``, or given as a
    relative literal to ``Path(...)``/``open(...)``/``os.path.join(...)``.
    The pieces may be written as one literal, in either separator, or split
    across ``/`` operands and join arguments — so ``ROOT / "docs" / "aide" /
    "insights.md"``, ``ROOT / r"docs\\aide" / "insights.md"`` and
    ``DOCS / "insights.md"`` after ``DOCS = ROOT / "docs/aide"`` all match.

    **What is not, deliberately.** The same path under any name the module
    never anchored — ``tmp_path / "docs" / "aide" / "insights.md"`` is how a
    test *should* build its inbox, and a helper argument named ``repo`` is
    indistinguishable from it — and a bare string that no path call receives
    (a docstring, an assertion message).

    **The limit, stated rather than left to be discovered:** literals only. A
    root imported from another module or returned by a fixture, a path
    assembled by an f-string or ``+``, a glob, or docs_dir itself read from
    ``aide.toml`` at test time is not seen; nor is any other living document
    under docs_dir, which §6's rule covers and this lint does not. Those are
    the misses. Names are resolved per scope, as Python does
    (``_repo_rooted_reads``): a function that binds ``ROOT = tmp_path``, takes
    a parameter of that name or captures it in a ``case`` pattern shadows the
    module's ``ROOT`` for its whole body, and a comprehension's target shadows
    it inside that comprehension only. What scoping cannot settle is order
    within one scope: bindings there are not read by control flow, so a name
    bound both to the repository and, on another branch or line, to
    ``tmp_path`` reads as the repository — a false positive. Silence means
    "no read of the recorded shape", never "this suite builds its own
    fixtures".
    """
    ddir = docs_dir(repo_root, config)
    try:
        rel = ddir.resolve().relative_to(repo_root.resolve())
    except ValueError:
        return []           # a docs_dir outside the repo is no test's fixture
    target = [p for p in rel.parts if p not in ("", ".")] + ["insights.md"]
    out: List[str] = []
    for path in _test_files(repo_root, config):
        try:
            tree = ast.parse(path.read_text(encoding=_ENCODING))
        except (OSError, UnicodeDecodeError, SyntaxError):
            continue
        hits = _repo_rooted_reads(tree, target)
        hit = min(hits, key=lambda n: (n.lineno, n.col_offset)) if hits else None
        if hit is not None:
            out.append(
                f"{_rel_display(path, repo_root)}:{hit.lineno}: reads the live "
                f"{'/'.join(target)} — a living document is no fixture: an "
                f"archive, a tick or a merge changes it under the test. Build "
                f"the entries the test needs in tmp_path instead "
                f"(conventions.md §6)")
    return out


#: The subprocess entry points that can hand *decoded* text back to the caller.
#: `call` and `check_call` return an exit status and never a capture, so a
#: `text=` on one of those decodes nothing and flagging it would be exactly the
#: false positive that stops a lint being read.
_DECODING_SUBPROCESS_FUNCS = frozenset({"run", "Popen", "check_output"})

#: Both spellings of "decode this for me". `universal_newlines=` is the pre-3.7
#: name and is still accepted, so a lint that knows only `text=` sees half the
#: shape — and the older spelling is the one an author copies from an old
#: answer, which is where this class comes from in the first place.
_TEXT_MODE_KWARGS = frozenset({"text", "universal_newlines"})


def _subprocess_names(tree: ast.AST) -> Tuple[set, Dict[str, str]]:
    """How this module spells `subprocess`: `(module aliases, name -> real)`.

    Matching on the method name alone flags `Runner().run(text=True)`, which has
    nothing to do with `subprocess` — caught in review, and the reason the
    docstring below can claim precision it would otherwise only assert. Both
    import forms are followed, aliases included:

        import subprocess              -> {"subprocess"}
        import subprocess as sp        -> {"sp"}
        from subprocess import run     -> {"run": "run"}
        from subprocess import run as r-> {"r": "run"}

    A star import binds every name at once and is treated as binding exactly
    the ones this lint cares about — caught in review, where resolving imports
    had turned `from subprocess import *` from a reported call into a silent
    one. Trading a false positive for a false negative is the wrong direction
    here, and this section says why.

    A binding made any other way — `run = subprocess.run`, or the module object
    re-exported through a sibling (`from helpers import subprocess`) — is not
    followed, and the lint stays quiet on it rather than guessing.
    """
    modules: set = set()
    funcs: Dict[str, str] = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name == "subprocess":
                    modules.add(alias.asname or alias.name)
        elif isinstance(node, ast.ImportFrom) and node.module == "subprocess":
            for alias in node.names:
                if alias.name == "*":
                    funcs.update({f: f for f in _DECODING_SUBPROCESS_FUNCS})
                    continue
                funcs[alias.asname or alias.name] = alias.name
    return modules, funcs


def _asks_for_text(node: ast.Call) -> bool:
    """Does this call ask for decoded output, as far as the source can say?

    `text=False` and `universal_newlines=None` ask for bytes and are not the
    defect. Anything else — `True`, a name, an expression — is treated as
    asking, because a call that may decode and names no codec is wrong in
    exactly the way a call that certainly decodes is.
    """
    for kw in node.keywords:
        if kw.arg not in _TEXT_MODE_KWARGS:
            continue
        if isinstance(kw.value, ast.Constant) and not kw.value.value:
            continue
        return True
    return False


def subprocess_encoding_test_warnings(repo_root: Path,
                                      config: Dict[str, Dict[str, object]]) -> List[str]:
    """Tests decoding subprocess output with whatever codec the platform guesses.

    conventions.md §6: a test that captures subprocess output as text passes
    `encoding="utf-8"`. Without it Python decodes with
    `locale.getpreferredencoding()` — UTF-8 on a Linux runner, **cp1252** on a
    Windows one — so the same bytes become different strings on the two legs of
    the same CI run.

    The recorded instance is the reason this is a lint and not advice. Six
    items in one consumer queue independently wrote
    `subprocess.run(..., capture_output=True, text=True)`; all six passed the
    Linux-only validator, and `windows-latest` returned a `KeyError` on a
    cp1252-mangled em-dash heading in one test and — worse — an **emoji-diff
    guard that matched nothing and reported PASS** in another. The second is a
    false negative: a gate that reports green having verified nothing, which is
    the worst outcome this loop has available and is invisible to every gate
    inside it (§7). Six independent authors reproducing one shape in one queue
    is the signature of a missing rule, not of a careless author.

    Decidable by AST, in the same shape as the eol-pin lint next door: a call
    to `run` / `Popen` / `check_output` carrying a `text=` or
    `universal_newlines=` keyword and no `encoding=` keyword. Three narrowings
    put together mean every warning this emits names a call that really would
    decode — the function set above, a literal-false `text=`, and the call
    having to reach `subprocess` through an import this module actually makes
    (`_subprocess_names`), without which `Runner().run(text=True)` is reported
    for sharing a method name.

    **The limit, stated rather than left to be discovered:** only a direct
    call is seen. A project that has wrapped its subprocess calls in a helper
    — which is the fix a consumer reached for — presents one call site to this
    lint and silence for the rest, and a `**kwargs` spread hides the keyword
    entirely. Silence here means "no call of the recorded shape", never "this
    suite decodes safely".
    """
    out: List[str] = []
    for path in _test_files(repo_root, config):
        try:
            tree = ast.parse(path.read_text(encoding=_ENCODING))
        except (OSError, UnicodeDecodeError, SyntaxError):
            continue
        modules, funcs = _subprocess_names(tree)
        if not modules and not funcs:
            continue                      # this module never imports subprocess
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            func = node.func
            if isinstance(func, ast.Attribute):
                # `subprocess.run(...)`, or whatever this module called it.
                if not (isinstance(func.value, ast.Name)
                        and func.value.id in modules):
                    continue
                name = func.attr
            elif isinstance(func, ast.Name):
                name = funcs.get(func.id, "")
            else:
                continue
            if name not in _DECODING_SUBPROCESS_FUNCS:
                continue
            if any(kw.arg == "encoding" for kw in node.keywords):
                continue
            if not _asks_for_text(node):
                continue
            out.append(
                f"{_rel_display(path, repo_root)}:{node.lineno}: captures "
                f"subprocess output as text with no encoding= — Python then "
                f"decodes with the platform's locale codec, UTF-8 here and "
                f"cp1252 on a Windows runner, which mangles non-ASCII and has "
                f"defeated a guard silently rather than failing. Pass "
                f'encoding="utf-8". See conventions.md §6')
            break
    return out


def _gitattributes_no_rewrite_patterns(repo_root: Path) -> Optional[List[str]]:
    """Every pattern in `.gitattributes` that stops the CRLF rewrite.

    ``None`` (not ``[]``) when the file is absent, so the caller can tell "no
    pins" from "no file" and say the more useful of the two.

    **Three spellings, not one.** `eol=lf` is the one §6 names, but `binary`
    (git's macro for `-text -diff`) and a bare `-text` both switch the
    conversion off outright, and a file under either is exactly as safe. Only
    accepting `eol=lf` made the lint warn about a `*.png binary` fixture and
    tell its author to add a pin that would be wrong for it — a wolf-cry on
    code that had already done the right thing, which is how a lint stops being
    read.
    """
    path = repo_root / ".gitattributes"
    if not path.is_file():
        return None
    out: List[str] = []
    try:
        text = path.read_text(encoding=_ENCODING)
    except (OSError, UnicodeDecodeError):
        return None
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        # `eol=lf` alone is enough: `text eol=lf` and a bare `eol=lf` both stop
        # core.autocrlf rewriting the file, which is the whole point here — as
        # do `binary` and an unsetting `-text`. A bare `text` is NOT in the
        # list: it *enables* the conversion.
        if len(parts) > 1 and any(a in ("eol=lf", "binary", "-text")
                                  for a in parts[1:]):
            out.append(parts[0])
    return out


def _gitattributes_matches(rel_posix: str, pattern: str) -> bool:
    """Does a `.gitattributes` pattern cover this repo-relative path?

    Git's pattern rules, not `fnmatch`'s: a `*` stops at a `/` (so
    `tests/*.json` must not match `tests/a/b.json`, which `fnmatch` would),
    `**` crosses separators, and a pattern with **no** slash matches at any
    depth — which is how `*.json` covers the whole tree.
    """
    pattern = pattern.strip().rstrip("/")
    if not pattern:
        return False
    if pattern.startswith("/"):
        pattern = pattern[1:]
    if "/" not in pattern:
        # basename match at any depth, per gitattributes(5)
        return _glob_segment(rel_posix.rsplit("/", 1)[-1], pattern)
    return _glob_path(rel_posix, pattern)


def _glob_segment(name: str, pattern: str) -> bool:
    """`fnmatch` on a single path component (no separators involved)."""
    return fnmatch.fnmatchcase(name, pattern)


def _glob_path(rel_posix: str, pattern: str) -> bool:
    """Match a path against a slash-aware glob, honouring `**`."""
    regex = []
    i = 0
    while i < len(pattern):
        ch = pattern[i]
        if pattern.startswith("**/", i):
            regex.append("(?:.*/)?")     # zero or more leading directories
            i += 3
            continue
        if pattern.startswith("**", i):
            regex.append(".*")
            i += 2
            continue
        if ch == "*":
            regex.append("[^/]*")        # a single `*` never crosses a `/`
        elif ch == "?":
            regex.append("[^/]")
        elif ch == "/":
            regex.append("/")
        else:
            regex.append(re.escape(ch))
        i += 1
    return re.fullmatch("".join(regex), rel_posix) is not None


class _LiteralPathResolver(ast.NodeVisitor):
    """Module-level names whose value is a path built only from literals.

    Deliberately narrow. It follows exactly two roots — ``Path(__file__)``
    walked up with ``.parent`` / ``.parents[N]``, and a name this same module
    already resolved — joined with string literals via ``/``. Anything built at
    run time (a ``tmp_path`` fixture, a function argument, a constant imported
    from another package) resolves to nothing and is skipped, which is the
    point: those are not committed files, and guessing at them is how a lint
    starts crying wolf.
    """

    def __init__(self, file_path: Path) -> None:
        self.file_path = file_path
        self.names: Dict[str, Path] = {}

    def visit_Assign(self, node: ast.Assign) -> None:
        resolved = self._resolve(node.value)
        if resolved is not None:
            for target in node.targets:
                if isinstance(target, ast.Name):
                    self.names[target.id] = resolved

    def visit_AnnAssign(self, node: ast.AnnAssign) -> None:
        # `GOLDEN: Path = REPO_ROOT / "x.json"` — annotated, same shape.
        if node.value is None or not isinstance(node.target, ast.Name):
            return
        resolved = self._resolve(node.value)
        if resolved is not None:
            self.names[node.target.id] = resolved

    def _resolve(self, node: ast.AST) -> Optional[Path]:
        if isinstance(node, ast.Name):
            return self.names.get(node.id)
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Div):
            left = self._resolve(node.left)
            if left is None:
                return None
            right = node.right
            if isinstance(right, ast.Constant) and isinstance(right.value, str):
                return left / right.value
            return None
        if isinstance(node, ast.Attribute) and node.attr == "parent":
            base = self._resolve(node.value)
            return None if base is None else base.parent
        if isinstance(node, ast.Subscript) and isinstance(node.value, ast.Attribute) \
                and node.value.attr == "parents":
            base = self._resolve(node.value.value)
            index = node.slice
            if base is None or not isinstance(index, ast.Constant) \
                    or not isinstance(index.value, int):
                return None
            try:
                return base.parents[index.value]
            except IndexError:
                return None
        if isinstance(node, ast.Call):
            func = node.func
            # `.resolve()` / `.absolute()` are identity here: the file path this
            # walks from is already absolute.
            if isinstance(func, ast.Attribute) and func.attr in ("resolve", "absolute"):
                return self._resolve(func.value)
            if isinstance(func, ast.Name) and func.id == "Path" and len(node.args) == 1:
                arg = node.args[0]
                if isinstance(arg, ast.Name) and arg.id == "__file__":
                    return self.file_path
                if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
                    candidate = Path(arg.value)
                    return candidate if candidate.is_absolute() else None
        return None


#: Attribute calls that read a file's exact bytes, or text that a byte-exact
#: golden comparison is one edit away from. `read_text()` is included because
#: its universal-newline translation only *hides* an unpinned CRLF checkout —
#: the consumer instance that prompted this had two such comparisons sitting
#: latent until someone switched them to `read_bytes()`.
_BYTE_EXACT_READS = ("read_bytes", "read_text")


def _read_call_name(node: ast.AST,
                    readers: Tuple[str, ...] = _BYTE_EXACT_READS
                    ) -> Optional[Tuple[str, int]]:
    """`(name, lineno)` if *node* is `NAME.read_bytes()` / `NAME.read_text()`.

    *readers* narrows which of the two counts. The comparison and hash sites
    pass `("read_text",)`: `read_bytes()` is collected unconditionally a few
    lines below, so letting them match it too appended every such read twice.
    Harmless downstream — the caller dedupes by resolved path — but the two
    rules are disjoint by construction and the code should say so.
    """
    if not isinstance(node, ast.Call):
        return None
    func = node.func
    if isinstance(func, ast.Attribute) and func.attr in readers \
            and isinstance(func.value, ast.Name):
        return func.value.id, func.lineno
    return None


def _byte_exact_reads(tree: ast.AST) -> List[Tuple[str, int]]:
    """`(name, lineno)` for reads whose bytes are actually *compared*.

    The narrowing that keeps this lint worth reading. An earlier draft flagged
    every `NAME.read_text()` in the tests tree and, run against a real consumer,
    produced twenty-odd warnings of which the overwhelming majority were plain
    helper reads --

        def _read_progress() -> str:
            return _PROGRESS_PATH.read_text(encoding="utf-8")

    -- whose callers go on to assert a *substring*. Universal-newline
    translation makes those immune to the CRLF rewrite, so a pin buys them
    nothing and the warning is pure noise. Requiring the read to sit directly
    inside an equality comparison, or to be fed to a hash, is what separates
    `a.read_bytes() == golden.read_bytes()` from reading a file to look inside
    it. A read stored in a local and compared later is missed on purpose: that
    indirection is the shape of a determinism check between two generated
    files, which needs no pin at all.

    **The two readers are not equally safe, and the split above is drawn on
    exactly that** (issue #124). `read_text()` applies universal-newline
    translation, so a CRLF-rewritten file arrives with `\n` either way: a
    *parsed* text read — `json.loads`, a Markdown table walked cell by cell —
    is immune to the rewrite, and covering it would be wrong rather than merely
    noisy. `read_bytes()` translates nothing, so that immunity does not exist
    for it and **any** use of it on a committed path is byte-sensitive; the
    `\r` survives into whatever parses the result. Hence: `read_bytes()`
    anywhere counts, `read_text()` only where its result is compared or hashed.

    Review caught the earlier version of this docstring claiming the immunity
    for the whole "parses rather than byte-compares" class. It is a property of
    `read_text()`, not of parsing — measured: `p.read_bytes().decode()` on a
    CRLF checkout leaves `' value\r'` in the last cell of a Markdown row where
    `read_text()` leaves `' value'`.

    What stays silent is a `read_text()` parse, and that silence is still not
    coverage: the file may need a pin for a byte-reproducibility claim asserted
    somewhere this lint cannot see — a regenerate-and-diff, a digest kept
    elsewhere — and that claim is the project's to assert directly.
    """
    # Reads sitting directly under a membership or ordering test — `b"{" in
    # p.read_bytes()`. Kept exempt from the blanket `read_bytes()` rule below:
    # the needle is what decides there, and a literal one carrying no newline
    # is immune to the rewrite. Collected first because `ast.walk` reaches the
    # inner call without the Compare that gives it its meaning.
    loose_operands: set = set()
    for node in ast.walk(tree):
        if not isinstance(node, ast.Compare):
            continue
        sides = [node.left, *node.comparators]
        for i, side in enumerate(sides):
            # `a == b < c` is one node meaning `a == b and b < c`, so an
            # operand is exempt only when *neither* comparison it takes part
            # in is an equality. Judging the node as a whole exempted `b` here,
            # which really is on one side of an `==`.
            adjacent = [op for j, op in enumerate(node.ops) if j in (i - 1, i)]
            if not any(isinstance(op, (ast.Eq, ast.NotEq)) for op in adjacent):
                loose_operands.add(id(side))

    out: List[Tuple[str, int]] = []
    for node in ast.walk(tree):
        # `read_bytes()` in any other position. It translates nothing, so there
        # is no context in which the CRLF rewrite passes through it harmlessly
        # — the `\r` survives into whatever parses the result.
        if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                and node.func.attr == "read_bytes"
                and isinstance(node.func.value, ast.Name)
                and id(node) not in loose_operands):
            out.append((node.func.value.id, node.func.lineno))
            continue
        if isinstance(node, ast.Compare):
            # Only `==` / `!=`: an ordering or membership test on file contents
            # is not a byte-exactness claim.
            if not all(isinstance(op, (ast.Eq, ast.NotEq)) for op in node.ops):
                continue
            for side in [node.left, *node.comparators]:
                found = _read_call_name(side, ("read_text",))
                if found is not None:
                    out.append(found)
        elif isinstance(node, ast.Call):
            func = node.func
            # `h.update(p.read_bytes())` and `hashlib.sha256(p.read_bytes())` --
            # a digest is a byte-exact claim by another name, and the recorded
            # whole-tree-hash failures took exactly this shape.
            is_hash_sink = (
                (isinstance(func, ast.Attribute)
                 and (func.attr == "update"
                      or func.attr.startswith(("sha", "md5", "blake"))))
                or (isinstance(func, ast.Name)
                    and func.id.startswith(("sha", "md5", "blake")))
            )
            if not is_hash_sink:
                continue
            for arg in node.args:
                found = _read_call_name(arg, ("read_text",))
                if found is not None:
                    out.append(found)
    return out


def gitattributes_eol_pin_warnings(repo_root: Path,
                                   config: Dict[str, Dict[str, object]]) -> List[str]:
    """Warn on a committed fixture compared byte-for-byte with no `eol=lf` pin.

    conventions.md §6 states the rule — *"a committed byte-exact fixture needs a
    `.gitattributes` `text eol=lf` pin"* — and until now nothing checked it.
    Without the pin, `core.autocrlf` rewrites the file on a Windows checkout and
    every byte comparison against it fails **on Windows only**, which is exactly
    the platform §7 says no gate in this loop ever sees. The recorded instance
    cost 13 red tests across three modules, invisible to every local run.

    **Precision over recall, deliberately.** The resolver follows only paths
    built from literals — `Path(__file__)` walked up, joined with string
    constants — so a fixture whose path arrives from a `tmp_path` fixture, a
    function argument or a constant imported from another package resolves to
    nothing and is skipped in silence. That is not a gap to be closed later by
    guessing: the overwhelming majority of `read_bytes()` calls in a real suite
    compare two *freshly generated* files to each other (a determinism check),
    and those need no pin at all. Flagging them would make the lint noise, and a
    lint that cries wolf stops being read. What remains — a literal path or an
    obvious glob beside a `read_bytes()` — is every instance recorded so far.

    A resolved path is only reported if it **exists** in the checkout, which is
    the cheap proxy for "committed": a path that resolves but is not there is a
    generated artifact, not a fixture.

    **Two causes of silence, and only one of them is the one above.** The first
    is resolution: a path this lint cannot follow is skipped. The second is
    shape, in `_byte_exact_reads` — a committed artifact whose tests
    `read_text()` and *parse* draws no warning whether or not it is pinned,
    because universal newlines make that read immune. The second is the one
    that misleads, because such a file looks exactly like the kind this lint
    exists for. Recorded (issue #124): a spec wrote "the eol-pin lint passes"
    as an acceptance criterion for a committed generated JSON artifact its
    tests `json.loads`; the criterion was vacuous by construction, and the pin
    had to be asserted by a project-side test instead. Read a warning here as
    authoritative and silence as *no reading taken*.
    """
    files = _test_files(repo_root, config)
    if not files:
        return []
    patterns = _gitattributes_no_rewrite_patterns(repo_root)
    out: List[str] = []
    seen: set = set()
    root = repo_root.resolve()
    for path in files:
        try:
            source = path.read_text(encoding=_ENCODING)
            tree = ast.parse(source)
        except (OSError, UnicodeDecodeError, SyntaxError):
            continue
        resolver = _LiteralPathResolver(path.resolve())
        resolver.visit(tree)
        if not resolver.names:
            continue
        for name, lineno in _byte_exact_reads(tree):
            target = resolver.names.get(name)
            if target is None:
                continue
            try:
                rel = target.resolve().relative_to(root)
            except ValueError:
                continue                      # outside the repo: not ours to pin
            if not target.exists():
                continue                      # generated, not committed
            rel_posix = rel.as_posix()
            key = (_rel_display(path, repo_root), rel_posix)
            if key in seen:
                continue
            seen.add(key)
            if patterns is None:
                out.append(
                    f"{_rel_display(path, repo_root)}:{lineno}: compares "
                    f"{rel_posix} byte-for-byte, but this repo has no "
                    f".gitattributes — on a Windows checkout core.autocrlf "
                    f"rewrites it and the comparison fails there and nowhere "
                    f"else. Add `{rel_posix} text eol=lf`. See conventions.md §6")
                continue
            if any(_gitattributes_matches(rel_posix, p) for p in patterns):
                continue
            out.append(
                f"{_rel_display(path, repo_root)}:{lineno}: compares "
                f"{rel_posix} byte-for-byte, but no .gitattributes `eol=lf` "
                f"pin covers it — on a Windows checkout core.autocrlf rewrites "
                f"it and the comparison fails there and nowhere else. Add "
                f"`{rel_posix} text eol=lf`. See conventions.md §6")
    return out


def nested_deliverable_warnings(lines: List[str]) -> List[str]:
    """Status-bearing bullets nested anywhere inside a stage section.

    The parser matches indented bullets, so a nested one counts as a full
    deliverable in the rollup and in item-status parsing. The nesting says
    "subordinate" to a reader while the tooling says "peer" — so a `📋` child
    quietly holds its ✅ parent's stage open, and nothing reconciles the two
    readings.

    **Scanned across the whole stage section, deliberately, not just the
    Deliverables block.** `stage_deliverable_statuses` reads `lines[start:end]`
    — every leading-icon bullet in the section, skipping only checkboxes — so an
    indented status bullet under **Acceptance** drags the stage exactly the same
    way. Verified: such a bullet turns `['complete']` into
    `['complete', 'planned']` and a ✅ stage into 🚧. Narrowing this to the
    Deliverables block would under-report a bullet that really does break the
    rollup.
    """
    out: List[str] = []
    for start, end, num in stage_sections(lines):
        for i in range(start, end):
            m = _NESTED_DELIVERABLE_RE.match(lines[i])
            if m:
                out.append(
                    f"progress.md:{i + 1}: stage {num} has a nested status bullet "
                    f"({m.group('icon')}) — the rollup counts it as a full "
                    f"deliverable despite the indent, so it can hold the stage "
                    f"open while reading as subordinate. Flatten it, or drop "
                    f"its icon.")
    return out


def _bullet_prose(lines: List[str], start: int, last: int) -> str:
    """A deliverable bullet's text with its icon and trailing marker removed,
    whitespace-normalised — the part an author wrote about the work."""
    body = lines[start:last + 1]
    # Tail first, then head: on a one-line bullet both cuts land on the same
    # string, and the marker's offset is only right before the icon is gone.
    marker = _BULLET_MARKER_RE.search(body[-1])
    if marker is not None:
        body[-1] = body[-1][:marker.start()]
    first = _BULLET_RE.match(lines[start])
    if first:
        body[0] = body[0][first.end():]
    return " ".join(part.strip() for part in body).strip()


def identical_deliverable_warnings(lines: List[str]) -> List[str]:
    """Single-item deliverable bullets in one stage with the same prose.

    That shape is what `_split_multi_item_bullets` leaves behind: a shared
    ``*(Items …)*`` marker desugared into one bullet per item, every copy
    carrying the sentence written for all of them. It is correct the moment
    it is written and wrong the moment one copy is ticked — the ✅ then
    describes the siblings' work as done — and rewording is invisible to every
    other check, so an un-reworded copy simply stood (issue #169). Reported
    per stage and per prose, naming the items, until each copy says what its
    own item delivers. A consumer that genuinely ships two identical
    deliverables in one stage sees the same warning; the remedy is the same
    sentence either way. The warning names `aide progress reword --item`,
    the verb that makes it (issue #320) — before it, the remedy it asked for
    was a hand edit.
    """
    out: List[str] = []
    for start, end, num in stage_sections(lines):
        groups: Dict[str, List[Tuple[int, int]]] = {}
        for s, last in _deliverable_bullet_spans(lines[start:end]):
            s, last = s + start, last + start
            items = _bullet_marker_item_numbers(lines[last])
            if len(items) != 1:
                continue
            prose = _bullet_prose(lines, s, last)
            if prose:
                groups.setdefault(prose, []).append((items[0], s + 1))
        for prose, hits in groups.items():
            if len(hits) < 2:
                continue
            listed = ", ".join(f"{n:03d}" for n, _ in hits)
            out.append(
                f"progress.md:{hits[0][1]}: stage {num} has {len(hits)} "
                f"deliverable bullets with identical prose, attributed to "
                f"items {listed} — the shape a split of a shared *(Items …)* "
                f"marker leaves behind, so a ✅ on one describes the others' "
                f"work too. Reword each copy with `aide progress reword --item "
                f"NNN --text …` to say what its own item delivers.")
    return out


def unattributed_reference_warnings(lines: List[str]) -> List[str]:
    """Deliverable bullets that reference items but attribute none of them.

    Only a bullet's trailing ``*(Item NNN)*`` marker ties items to it (§1,
    issue #99). A bullet whose references all sit mid-prose therefore tracks
    nothing: the items it names stay planned, hold their queue open, and
    `aide progress set` cannot find the bullet — a silent gap unless it is
    reported where the author can fix it. A bullet that has a trailing marker
    is fine, whatever else its prose mentions: the prose is free text by
    design, not a mistake.
    """
    out: List[str] = []
    for start, last in _deliverable_bullet_spans(lines):
        if _bullet_marker_item_numbers(lines[last]):
            continue
        span_text = "\n".join(lines[start:last + 1])
        nums = sorted(set(_referenced_item_numbers(span_text)))
        if nums:
            listed = ", ".join(f"{n:03d}" for n in nums)
            out.append(
                f"progress.md:{start + 1}: deliverable bullet references "
                f"item(s) {listed} but ends with no *(Item NNN)* marker — only "
                f"the trailing marker ties an item to a bullet, so this bullet "
                f"tracks nothing and those items read as untracked. End it "
                f"with the marker (e.g. '. *(Item {nums[0]:03d})*').")
    return out


def _line_after_title(lines: List[str]) -> str:
    """The first content line after the `#` title, or "" if there is none.

    Two subtleties. A multi-line HTML comment must be skipped **whole** — only
    its opening line starts with `<!--`, so testing line-by-line lets its body
    read as content. And the search stops at the first line after the title
    rather than skipping further headings: "opens with a blockquote" means the
    next thing, so `# Title` / `## Intro` / `> …` does not satisfy it.
    """
    in_comment = False
    seen_title = False
    for line in lines:
        stripped = line.strip()
        if in_comment:
            if "-->" in stripped:
                in_comment = False
            continue
        if stripped.startswith("<!--"):
            if "-->" not in stripped:
                in_comment = True
            continue
        if not stripped:
            continue
        if not seen_title:
            if stripped.startswith("#"):
                seen_title = True
            continue
        return stripped
    return ""


def header_blockquote_warnings(ddir: Path) -> List[str]:
    """Living documents that do not open with their header blockquote.

    The blockquote carries the document's place in the loop and what it derives
    from — structural facts a reader landing anywhere needs (conventions.md §1).
    """
    out: List[str] = []
    targets = [ddir / name for name in _BLOCKQUOTE_DOCS]
    for sub in ("queue", "items"):
        if (ddir / sub).is_dir():
            targets.extend(sorted((ddir / sub).glob("*.md")))
    for path in targets:
        if not path.is_file():
            continue
        first = _line_after_title(path.read_text(encoding=_ENCODING).splitlines())
        if not first.startswith(">"):
            # Relative to docs_dir, matching `progress.md:12` and `items/…`.
            rel = path.relative_to(ddir).as_posix()
            out.append(f"{rel}: no header blockquote — the line after the title "
                       f"should carry this document's place in the loop and what "
                       f"it derives from")
    return out


#: The vision sections `templates/vision.md` marks `MANDATORY`, minus Goals &
#: objectives, whose mandatory substance is the G-code table checked separately
#: — a heading over an empty section would satisfy a heading check while giving
#: the roadmap nothing to trace. Each entry: (heading text, why it is needed).
_VISION_MANDATORY_SECTIONS = (
    ("Guiding principles", "the validator checks implementation against these"),
    ("Out of scope", "the validator flags work that contradicts this"),
    ("Success criteria", "they define when the project is done"),
)


def _has_g_code_row(lines: List[str]) -> bool:
    """True when any table row's first cell names a vision G-code (`G1 …`).

    The shape both mandatory tables share: vision's objectives table and the
    roadmap's objective → stage coverage table each open every row with the
    G-code. Cell counts differ (3 and 2), so the first cell is the invariant.
    """
    for line in lines:
        if not line.strip().startswith("|"):
            continue
        cells = _split_row(line)
        if cells and re.match(r"G\d+\b", cells[0]):
            return True
    return False


#: The two build postures `vision.md`'s optional header line may name
#: (conventions.md §1 → vision.md, issue #241). A closed set: the line says how
#: much to build, and a value nobody defined is a value no role can apply.
_VISION_POSTURES = ("prototype", "durable")


#: The separators a header blockquote line folds several labelled fields with.
#: `templates/vision.md` writes `**Status:** … · **Created:** …` on one line, so
#: a posture folded onto it is a field of that line rather than a line of its
#: own — read by field, or an explicit `durable` reads as no posture at all.
_HEADER_FIELD_SEP_RE = re.compile(r"[\u00b7|]")


def vision_posture(text: str) -> Optional[str]:
    """The value of `vision.md`'s optional `**Posture:** …` header field, or ``None``.

    The scan window is every line above the first `##` heading that starts with
    `>`; each such line is split into fields on `·` and `|`, and each field has
    its quote marker and emphasis removed before its label is read. So the line
    of its own the template writes, the plain `> Posture: durable`, and a
    posture folded onto the `**Status:** … · **Created:** …` line with the
    template's own separator are one shape. The first field labelled `posture`
    wins. The value is returned exactly as written, including an unknown or
    empty one: deciding what it means is the caller's, and the check below
    warns rather than correcting it.

    ``None`` means the document carries no such field, which §1 → vision.md
    reads as ``prototype``. This returns ``None`` rather than that default so
    the two states stay distinguishable — the check must not warn about an
    absent line, and a role that wants the default applies it itself.
    """
    for line in text.splitlines():
        stripped = line.lstrip()
        if stripped.startswith("##"):
            break
        if not stripped.startswith(">"):
            continue
        for field in _HEADER_FIELD_SEP_RE.split(stripped[1:]):
            plain = field.replace("*", "").replace("`", "").strip()
            if plain.lower().startswith("posture:"):
                return plain.split(":", 1)[1].strip()
    return None


def root_document_warnings(ddir: Path) -> List[str]:
    """Root documents missing the sections their templates mark MANDATORY.

    `templates/vision.md` annotates four sections `MANDATORY: validator
    checks…` and `templates/roadmap.md` two, and until issue #86 nothing
    verified any of them: a hand-written vision with none of the sections
    passed `aide check`, so the promise the annotations make was kept by no
    code. The observed failure is exactly that — a vision authored free-hand
    in a consumer, structurally plausible, checked by nobody.

    Headings are matched tolerantly (any level, the template's `2.` numbering
    optional, case-insensitive): the lint is for a *dropped* section, and a
    renumbered heading is not a dropped section.

    The vision's optional build posture is read here too (issue #241): a value
    that is neither `prototype` nor `durable` is warned about by name, while an
    absent line is not — absence is the default, and warning about it would ask
    every vision to state the value it already has.

    Warnings, not errors, matching the item specs' mandatory-Assumptions lint:
    root documents predating this check exist in real consumers, and an
    unattended run must not start failing over a document none of its items
    touch — the queue-boundary human reads warnings. A missing file is silent:
    a repo may adopt the CLI without the root documents (issue #57), and
    `create-progress` onward is where `progress.md` becomes a hard error.
    """
    out: List[str] = []
    vpath = ddir / "vision.md"
    if vpath.is_file():
        vtext = vpath.read_text(encoding=_ENCODING)
        for title, why in _VISION_MANDATORY_SECTIONS:
            if not re.search(rf"^#{{1,6}}\s*(?:\d+\.\s*)?{title}\b", vtext,
                             re.MULTILINE | re.IGNORECASE):
                out.append(f"vision.md: no '{title}' section — the template "
                           f"marks it MANDATORY: {why}")
        posture = vision_posture(vtext)
        if posture is not None and posture.lower() not in _VISION_POSTURES:
            # Named, not corrected, and never silently defaulted: a typo that
            # meant `durable` would otherwise build less than the human asked
            # for and say nothing. An absent line is the default and is silent.
            out.append(f"vision.md: the header's Posture line reads "
                       f"'{posture}', which is neither 'prototype' nor "
                       f"'durable' — no role applies an unknown posture, and "
                       f"a vision with no Posture line at all is read as "
                       f"'prototype'")
        if not _has_g_code_row(vtext.splitlines()):
            out.append("vision.md: no G-code objectives table (rows opening "
                       "'| G1 |…') — the template marks it MANDATORY: the "
                       "roadmap and progress.md trace every stage back to "
                       "these codes")
    rpath = ddir / "roadmap.md"
    if rpath.is_file():
        rtext = rpath.read_text(encoding=_ENCODING)
        if not _has_g_code_row(rtext.splitlines()):
            out.append("roadmap.md: no objective → stage coverage rows "
                       "(opening '| G1 …|') — the template marks the table "
                       "MANDATORY: it is what shows every vision G-code "
                       "mapped to a stage")
        if not re.search(r"^#{1,6}\s*Stage\s+\d+", rtext,
                         re.MULTILINE | re.IGNORECASE):
            out.append("roadmap.md: no '## Stage N — Title' sections — the "
                       "template marks the shape MANDATORY: queues are scoped "
                       "to a stage and progress.md is generated from these "
                       "sections")
    return out


#: A roadmap stage's Dependencies block opener, and the text on its line.
_ROADMAP_DEPS_RE = re.compile(r"^\*\*Dependencies\s*[.:]?\*\*\s*:?\s*(?P<text>.*)$",
                              re.IGNORECASE)
#: Where the blocking slot ends: the first `;`, dash-set clause, sentence end,
#: or one of the template's two ordering lead-ins (`independent of`, `queue
#: before`). The template keeps the slot to blocking stages and puts
#: ordering without blocking in a sentence after it (`None. Independent of
#: Stage 17 — …`), and a consumer's forward dependency read `Depends on Stage
#: 5; … may be delivered after it` — both are read correctly by stopping at the
#: first of these. The lead-ins end it too, so the template's phrasings stay
#: unread when an author writes them with no `None.` before them.
_DEPS_SLOT_END_RE = re.compile(
    r";|\s[—–]\s|\s-\s|[.!?](?=\s|$)"
    r"|\bindependent\s+of\b|\bqueued?\s+before\b", re.IGNORECASE)
#: Stage numbers in the slot: after `Stage`/`Stages`, a list of numbers joined
#: by commas, `and`, `or`, `&` or a range dash, each optionally re-prefixed; a
#: comma before the conjunction (`Stages 10, 11, and 12`) is one separator.
_DEPS_SEP = r"(?:\s*,\s*(?:(?:and|or|to)\b\s*)?|\s*(?:&|\band\b|\bor\b|\bto\b|[-–—])\s*)"
_DEPS_STAGE_LIST_RE = re.compile(
    r"\bStages?\s+(\d+(?:" + _DEPS_SEP + r"(?:Stages?\s+)?\d+)*)", re.IGNORECASE)
#: A slot holding bare stage numbers only — `3`, `3, 4`, `3 and 4`.
_DEPS_BARE_LIST_RE = re.compile(r"^\s*\d+(?:" + _DEPS_SEP + r"\d+)*\s*$",
                                re.IGNORECASE)


def blocking_dependency_stages(text: str) -> List[int]:
    """Stage numbers named in the blocking slot of a Dependencies block's *text*.

    The slot is the text up to its first `;`, spaced dash, sentence end or
    ordering lead-in (`independent of`, `queue before`) —
    §1 → roadmap.md reads the slot only, and a sentence after it about
    ordering without blocking names what it likes. Numbers are taken after
    `Stage`/`Stages`, or from a slot of bare numbers and nothing else, so an
    item number or a version in the slot is not read as a stage.
    """
    return named_stage_numbers(_DEPS_SLOT_END_RE.split(text.strip(),
                                                       maxsplit=1)[0])


def named_stage_numbers(text: str) -> List[int]:
    """Stage numbers *text* names, in order and without repeats.

    One reading for every cell or slot whose job is to name stages — the
    blocking slot of a Dependencies block (issue #282) and a roadmap
    coverage row's Delivered-by cell (issue #289). Emphasis and code spans are
    stripped first. A number is taken after `Stage`/`Stages`, in a list
    joined by commas, `and`, `or`, `&` or a range dash, each element
    optionally re-prefixed — wherever that run sits, so prose around it
    (`Stages 4, 5 (specification: **Stage 30**)`) is read for its stages and
    nothing else — or from a text of bare numbers and nothing else. A number
    anywhere else (`extended by 2–4`, `item 012`, `v2`) is not a stage: the
    bare `\\d+` reading of a Delivered-by cell matched exactly that prose
    (issue #285). A range names its two endpoints, as written.
    """
    plain = text.replace("*", "").replace("`", "")
    runs = [m.group(1) for m in _DEPS_STAGE_LIST_RE.finditer(plain)]
    if not runs and _DEPS_BARE_LIST_RE.match(plain):
        runs = [plain]
    out: List[int] = []
    for run in runs:
        for n in re.findall(r"\d+", run):
            if int(n) not in out:
                out.append(int(n))
    return out


def _roadmap_dependency_text(lines: List[str], start: int, end: int) -> Optional[str]:
    """The text of the stage section's Dependencies block, wrapped lines joined.

    ``None`` when the section has no Dependencies block. The block runs from
    its opener to the first blank line, list bullet, guidance line or next
    bold block opener.
    """
    head = next((i for i in range(start, end)
                 if _ROADMAP_DEPS_RE.match(lines[i])), None)
    if head is None:
        return None
    parts = [_ROADMAP_DEPS_RE.match(lines[head]).group("text")]
    for i in range(head + 1, end):
        line = lines[i]
        if (not line.strip() or _ROADMAP_BLOCK_END_RE.match(line)
                or _GUIDANCE_RE.match(line) or re.match(r"^\s*[-*]\s", line)):
            break
        parts.append(line.strip())
    return " ".join(p for p in parts if p)


def _stages_under_way(ddir: Path, plines: List[str]) -> Set[str]:
    """Stage numbers (by value) that are under way, for issue #384's warning:
    deliverables rolling up to 🚧, or a 📋 item listed in an open queue.

    The open queues are `queue_is_open`'s, read from the queue files under
    *ddir*, and a withdrawn stage's 📋 item is neither open nor queued work,
    as `claim` reads it (issue #393); an item belongs to the stages whose
    bullets name it (`stage_item_numbers`). A queued item with bullets in two
    stages makes both under way — an accepted false positive, since this
    feeds a warning.
    """
    out = {str(int(n)) for n, st in stage_rollups(plines).items()
           if n.isdigit() and st == "in-progress"}
    item_status = _parse_item_status(plines)[2]
    withdrawn = withdrawn_stage_items(plines)
    queued: Set[int] = set()
    for path in iter_queue_paths(ddir / "queue"):
        text = path.read_text(encoding=_ENCODING)
        if queue_is_open(text, item_status, withdrawn):
            queued.update(n for n in queue_item_numbers(text)
                          if item_status.get(n, "planned") == "planned"
                          and n not in withdrawn)
    if queued:
        for _start, _end, num in stage_sections(plines):
            if num.isdigit() and queued & set(stage_item_numbers(plines, num)):
                out.add(str(int(num)))
    return out


def forward_dependency_warnings(ddir: Path) -> List[str]:
    """Roadmap stages whose blocking Dependencies name a later-numbered stage.

    §1 → roadmap.md (issue #282): stages close in number order, so a stage
    waiting on a later one cannot close when its turn comes, and a queue cut
    from it either leaves the stage open or queues work toward a closure that
    cannot happen yet. The observed case read `Depends on Stage N+2; … may be
    delivered after it`, and nothing said so until the owner swept the
    roadmap by hand.

    Silent for a stage `progress.md` shows at ⏸️ — on its header or its
    summary row — since a deferral is the one forward dependency the section
    tolerates; a missing `progress.md` exempts nothing. A missing
    `roadmap.md` is silent, as in `root_document_warnings`.

    A warning, never an error: roadmaps written before the rule exist, and a
    started stage is frozen, so an error would fail a document the author has
    no edit left to fix but a deferral — a decision for the human at the
    queue boundary, who reads warnings.

    The same pass warns on a stage **under way over an unmet earlier
    dependency** (issue #384): one whose deliverables roll up to 🚧 in
    `progress.md`, or that has a 📋 item listed in an open queue, while an
    earlier stage its blocking slot names is ⏸️ (header or summary row) or
    withdrawn (summary row ❌, `withdrawn_stages`). §1 → roadmap.md meets a
    dependency only once its stage is ✅; a 📋, 🚧 or 🔍 earlier stage is
    the ordinary wait a queue ends, so only the two states a queue cannot
    end are named. A dependent stage itself ⏸️ or withdrawn is not under way;
    with no `progress.md` nothing is.
    """
    rpath = ddir / "roadmap.md"
    if not rpath.is_file():
        return []
    rlines = rpath.read_text(encoding=_ENCODING).splitlines()
    deferred: Set[str] = set()
    withdrawn: Set[str] = set()
    under_way: Set[str] = set()
    ppath = ddir / "progress.md"
    if ppath.is_file():
        plines = ppath.read_text(encoding=_ENCODING).splitlines()
        for start, _end, num in stage_sections(plines):
            if _header_status(plines[start]) == "deferred":
                deferred.add(str(int(num)))
        for line in plines:
            cells = _split_row(line) if line.strip().startswith("|") else []
            if (cells and _reads(_STAGE_SUMMARY, cells) and cells[0].isdigit()
                    and _icon_status(cells[3]) == "deferred"):
                deferred.add(str(int(cells[0])))
        withdrawn = {str(int(n)) for n in withdrawn_stages(plines) if n.isdigit()}
        under_way = _stages_under_way(ddir, plines) - deferred - withdrawn
    out: List[str] = []
    for start, end, num in stage_sections(rlines):
        text = _roadmap_dependency_text(rlines, start, end)
        if text is None:
            continue
        named_deps = blocking_dependency_stages(text)
        if str(int(num)) in under_way:
            for dep in (n for n in named_deps if n < int(num)):
                if str(dep) in withdrawn:
                    out.append(
                        f"roadmap.md: stage {int(num)} is under way while "
                        f"stage {dep}, which its Dependencies name, is "
                        f"withdrawn (❌ summary row in progress.md) — a "
                        f"dependency on a withdrawn stage is never met, so "
                        f"stage {int(num)} is re-planned: its Dependencies "
                        f"reworded while it is 📋, or it is withdrawn too, or "
                        f"what it still needs enters as a new stage — "
                        f"§1 → roadmap.md")
                elif str(dep) in deferred:
                    out.append(
                        f"roadmap.md: stage {int(num)} is under way while "
                        f"stage {dep}, which its Dependencies name, is ⏸️ "
                        f"deferred — a dependency is met only once its stage "
                        f"is ✅, so stage {int(num)} waits until stage "
                        f"{dep}'s owner resumes or drops its deferred work "
                        f"— §1 → roadmap.md")
        later = [n for n in named_deps if n > int(num)]
        if not later or str(int(num)) in deferred:
            continue
        named = ", ".join(str(n) for n in later)
        out.append(
            f"roadmap.md: stage {int(num)}'s Dependencies name later "
            f"stage{'' if len(later) == 1 else 's'} {named} — stages close in "
            f"number order, so it cannot close when its turn comes; reorder "
            f"the planned stages so the dependency comes first, or defer "
            f"stage {int(num)} (⏸️ in progress.md) — §1 → roadmap.md")
    return out


#: The G-code(s) opening a roadmap coverage row's first cell — `G2`, or a
#: leading run `G2, G7`, `G2 and G7`, `G2/G7` — after emphasis, code spans and
#: one leading parenthetical annotation are set aside: a consumer keeps a
#: withdrawn objective's row as `*(out of scope 2026-07-25)* G5 Deploy on
#: XNAT`, and that row still maps G5 to its stages. The separators are
#: `_DEPS_SEP`'s, with `/` added and no range dash (`G2–G4` is not a
#: coverage-row shape); each element must be a G-code, so `G2 and more`
#: reads G2 alone. The joining words match in any case (`G2 Or G7`), as
#: `_DEPS_SEP`'s do; the G-codes themselves stay upper-case, as the vision's are.
_COVERAGE_SEP = r"(?:\s*,\s*(?:(?i:and|or)\b\s*)?|\s*(?:&|/|\b(?i:and|or)\b)\s*)"
_COVERAGE_CODES_RE = re.compile(
    r"^\s*(?:\([^)]*\)\s*)?(G\d+(?:" + _COVERAGE_SEP + r"G\d+)*)\b")


def _coverage_row_codes(cells: List[str]) -> List[int]:
    """The objective numbers a table row maps, read from its first cell."""
    if len(cells) < 2:
        return []
    m = _COVERAGE_CODES_RE.match(cells[0].replace("*", "").replace("`", ""))
    return [int(n) for n in re.findall(r"G(\d+)", m.group(1))] if m else []


def coverage_completeness_warnings(ddir: Path) -> List[str]:
    """The three coverage tables, each checked for completeness (issue #289).

    `root_document_warnings` and the progress.md presence errors say that
    each table *exists*; this says that it leaves nothing out, which §1
    states for each table:

    1. **Every `## Stage N` section of progress.md has a Stage summary row.**
       Since #285 the header and bullets of such a stage are compared, but
       the summary left it out without a word — and `aide check` reads the
       summary row for three things no other cell gives it: a ❌ row drops
       the stage from every rollup comparison (`derived_cell_findings`), a
       ✅ row closes the stage for the capability table
       (`capability_warnings`), and a ⏸️ row exempts it from the forward
       dependency lint (`forward_dependency_warnings`, which reads the
       header too). A ⏸️ or ❌ stage is therefore no exception. A
       row the reader cannot use still counts as the stage's row when its
       Stage cell holds that number: it is `unreadable_row_errors`'s to
       report, once.
    2. **Every vision.md G-code has a roadmap.md coverage row**, or no stage
       is mapped to deliver the objective. A G-code the vision has withdrawn
       keeps its identity, and its row: the codes are never reused.
    3. **Every stage a roadmap.md coverage row names has a `## Stage N`
       section in roadmap.md** — the roadmap-side counterpart of #285's
       Objective row naming no stage with a section, per stage rather than
       per row, since a coverage row is read for every stage it maps. The
       Delivered-by cell is read by `named_stage_numbers`, the reading the
       Dependencies slot takes: stages after `Stage`/`Stages` wherever they
       sit in the cell's prose, or a cell of bare numbers, never a bare number
       in prose. A stage's status does not enter: a deferred or excluded
       stage keeps its roadmap section like any other.

    Stage numbers and G-codes are matched by value, so `Stage 07` is stage 7.
    A missing file is silent for the cases that need it, as in
    `root_document_warnings`; so is a missing table (or, for case 3, a
    roadmap with no `## Stage N` section at all), since that is reported
    already and one missing table would otherwise be reported once per row.

    A warning, never an error: a missing row under-reports rather than
    over-claims, and documents written before the rule exist.
    """
    out: List[str] = []
    ppath = ddir / "progress.md"
    if ppath.is_file():
        plines = ppath.read_text(encoding=_ENCODING).splitlines()
        rows = list(_table_rows(plines, _STAGE_SUMMARY))
        in_summary: Set[int] = set()
        for _i, cells, problem in rows:
            m = (re.fullmatch(r"\d+", cells[0]) if problem is None
                 else re.search(r"\d+", cells[0]))
            if m:
                in_summary.add(int(m.group(0)))
        if rows:
            for _start, _end, num in stage_sections(plines):
                if int(num) not in in_summary:
                    out.append(
                        f"progress.md: stage {int(num)} has a '## Stage "
                        f"{int(num)}' section but no Stage summary row — "
                        f"`aide check` reads a stage's ❌ exclusion and its ✅ "
                        f"closure for the capability table from that row, so "
                        f"the summary silently leaves out a stage this file "
                        f"tracks; add its row — §1 → progress.md")

    rpath = ddir / "roadmap.md"
    if not rpath.is_file():
        return out
    rlines = rpath.read_text(encoding=_ENCODING).splitlines()
    covered: Set[int] = set()
    coverage_rows: List[Tuple[List[int], str]] = []
    for line in rlines:
        if not line.strip().startswith("|"):
            continue
        cells = _split_row(line)
        codes = _coverage_row_codes(cells)
        if codes:
            covered.update(codes)
            coverage_rows.append((codes, cells[1]))

    vpath = ddir / "vision.md"
    if vpath.is_file() and _has_g_code_row(rlines):
        vision_codes: List[int] = []
        for line in vpath.read_text(encoding=_ENCODING).splitlines():
            cells = _split_row(line) if line.strip().startswith("|") else []
            m = re.match(r"G(\d+)\b", cells[0]) if cells else None
            if m and int(m.group(1)) not in vision_codes:
                vision_codes.append(int(m.group(1)))
        for g in vision_codes:
            if g not in covered:
                out.append(
                    f"roadmap.md: vision objective G{g} has no row in the "
                    f"objective → stage coverage table, so no stage is "
                    f"mapped to deliver it; add a 'G{g} | Stage N' row — "
                    f"§1 → roadmap.md")

    sections = {int(num) for _s, _e, num in stage_sections(rlines)}
    if sections:
        for codes, cell in coverage_rows:
            missing = [n for n in named_stage_numbers(cell) if n not in sections]
            if not missing:
                continue
            named = ", ".join(str(n) for n in missing)
            plural = len(missing) != 1
            out.append(
                f"roadmap.md: the coverage row for "
                f"{', '.join(f'G{g}' for g in codes)} names "
                f"stage{'s' if plural else ''} {named}, which "
                f"{'have' if plural else 'has'} no '## Stage N' section in "
                f"roadmap.md, so the objective is mapped to a stage the plan "
                f"does not lay out; name the stage that delivers it, or give "
                f"that stage its section — §1 → roadmap.md")
    return out


#: The line every template carries after its header comment, and every document
#: created from one keeps: ``<!-- aide-template: progress 1 -->``. The name is
#: the template's file stem and the number its own integer version, which moves
#: only when the template changes in a way a document built from the old one
#: would want to follow — independent of ``VERSION`` (issue #164).
_TEMPLATE_MARKER_RE = re.compile(
    r"^<!--\s*aide-template:\s*(?P<name>[a-z][a-z0-9-]*)\s+(?P<version>\d+)\s*-->\s*$",
    re.MULTILINE)
#: A line that opens like the marker, so one the regex above rejects is reported
#: rather than taken for a document with no marker at all.
_TEMPLATE_MARKER_OPENER_RE = re.compile(r"^<!--\s*aide-template:", re.MULTILINE)


def _above_title(text: str) -> str:
    """The part of *text* before its first heading line — where the marker lives.

    Every template puts the line between its header comment and its title, and a
    document whose header comment was deleted keeps it above the title. Reading
    only that far means a marker quoted in a document's body — an example in an
    item spec, a note about a template change — is never taken for the
    document's own.
    """
    m = re.search(r"^#", text, re.MULTILINE)
    return text[:m.start()] if m else text


def template_marker(text: str) -> Optional[Tuple[str, int]]:
    """``(name, version)`` from the marker line above *text*'s title, or ``None``."""
    m = _TEMPLATE_MARKER_RE.search(_above_title(text))
    return (m.group("name"), int(m.group("version"))) if m else None


def installed_template_versions() -> Dict[str, int]:
    """``name -> version`` for every template installed beside this script.

    A template without a readable marker is left out, so a document naming it
    is reported as naming a template this engine does not ship — the truthful
    reading of an install that lost the line.
    """
    versions: Dict[str, int] = {}
    if not _TEMPLATES_DIR.is_dir():
        return versions
    for path in sorted(_TEMPLATES_DIR.glob("*.md")):
        marker = template_marker(path.read_text(encoding=_ENCODING))
        if marker and marker[0] == path.stem:
            versions[marker[0]] = marker[1]
    return versions


def template_drift_warnings(ddir: Path, item_status: Dict[int, str],
                            installed: Optional[Dict[str, int]] = None,
                            withdrawn: Collection[int] = ()) -> List[str]:
    """Documents whose template marker disagrees with the installed template.

    Rung 4 of the copies rule (``ADAPTER-SPEC.md``, *Copies of engine text*):
    ``docs/aide/**`` is the project's, so the engine *reports* a document that
    predates its template and never fails a run over one. A template gaining a
    section reaches the next document created from it and no earlier one;
    before the marker, nothing recorded which template a document was built
    from, and the only signal was a changelog entry nobody was pointed at.

    Which documents are read, and why:

    * ``vision.md``, ``roadmap.md``, ``progress.md``, ``insights.md`` and
      ``ledger.md`` — long-lived, appended to or edited for the life of the
      project, so a newer template is something their author may still act on.
    * A queue while it is open, and an item spec while its item is not ✅ or
      ❌ — the same measure ``--queue`` uses for "spent". A finished item's
      spec is a record, and a warning on every one of them each time a template
      moves is permanent noise over files nobody should edit. Open is
      `queue_is_open`'s with *withdrawn* (`withdrawn_stage_items`), as `claim`
      reads it (issue #393); a withdrawn stage's 📋 item keeps its spec here,
      as a ⏸️ one does, since a summary row taken off ❌ revives it.

    Only the marker above the title counts (``_above_title``). A document
    **without** one is silent. Every document written before
    the marker existed has none, and the engine cannot say which template it
    came from; a warning that asks the author to guess a version names no
    action, and repeating it on every run is how a real warning gets tuned out.
    A line that opens like the marker but does not parse is reported, since
    that one the author wrote and can fix.
    """
    if installed is None:
        installed = installed_template_versions()
    targets = [ddir / name for name in
               ("vision.md", "roadmap.md", "progress.md", "insights.md",
                "ledger.md")]
    qdir = ddir / "queue"
    if qdir.is_dir():
        for qpath in iter_queue_paths(qdir):
            if queue_is_open(qpath.read_text(encoding=_ENCODING), item_status,
                             withdrawn):
                targets.append(qpath)
    idir = ddir / "items"
    if idir.is_dir():
        for ipath in sorted(idir.glob("*.md")):
            n = item_spec_number(ipath)
            if n is not None and item_status.get(n, "planned") in (
                    "complete", "excluded"):
                continue
            targets.append(ipath)

    out: List[str] = []
    for path in targets:
        if not path.is_file():
            continue
        text = path.read_text(encoding=_ENCODING)
        rel = path.relative_to(ddir).as_posix()
        marker = template_marker(text)
        if marker is None:
            if _TEMPLATE_MARKER_OPENER_RE.search(_above_title(text)):
                out.append(f"{rel}: unreadable aide-template line — expected "
                           f"'<!-- aide-template: <name> <N> -->'")
            continue
        name, version = marker
        current = installed.get(name)
        if current is None:
            out.append(f"{rel}: names template '{name}', which this engine "
                       f"does not ship")
        elif version < current:
            out.append(f"{rel}: created from {name} template {version}; the "
                       f"installed template is {current} — the framework "
                       f"CHANGELOG entry naming '{name} template {current}' "
                       f"says what changed and what, if anything, to edit; "
                       f"then set the line to {current}")
        elif version > current:
            out.append(f"{rel}: created from {name} template {version}, newer "
                       f"than the installed {current} — this checkout runs an "
                       f"older engine than the document was written under")
    return out


#: An assumption bullet that names the engine it was true for — the §1 marker
#: ``- **A8 (engine 1.28.1):** …``. The engine version goes in the bold label,
#: beside the assumption's own code, because that is where a reader looking for
#: "which claim is this?" already is; a version buried in the assumption's prose
#: is not read, so a claim about engine behaviour written without the marker
#: goes unchecked rather than wrongly checked.
#:
#: The marker is free-form apart from the word ``engine`` and a SemVer triple:
#: it may carry a re-check — ``(engine 1.28.1, re-checked 1.35.0)`` — and the
#: **newest** version it names is the one the claim currently stands on.
#: The **label run** of an assumption bullet: the bold opener the template
#: writes. Two real spellings, and the marker has to survive both — the closing
#: `**` may sit right after the label (`- **A8 (engine 1.28.1):** …`) or at the
#: end of the whole sentence (`- **A8 (engine 1.28.1): the CLI warns …**`),
#: which is what one consumer's 112 specs actually use. An unbolded bullet
#: falls back to the text before its first colon, so `- A8 (engine 1.28.1): …`
#: is read too; without that boundary the marker would be hunted through the
#: assumption's whole prose, where a version is being discussed rather than
#: pinned.
_ASSUMPTION_LABEL_RE = re.compile(r"^\s*[-*]\s+(?:\*\*(?P<bold>.+?)\*\*|(?P<plain>[^:*]*):)")
#: A parenthesised marker naming the engine, anywhere in that label run.
_ENGINE_MARKER_RE = re.compile(r"\(([^)]*engine[^)]*)\)", re.IGNORECASE)
#: A SemVer triple anywhere in that marker. Prerelease and build suffixes are
#: not read: the comparison below is on `major.minor` alone, and a consumer
#: running `1.29.0-rc1` is on 1.29 for the purpose of "has the engine moved".
_SEMVER_RE = re.compile(r"\b(\d+)\.(\d+)\.(\d+)\b")


def _feature_line(version: str) -> Optional[Tuple[int, int]]:
    """``(major, minor)`` of *version*, or ``None`` if it is not SemVer.

    Deliberately drops the patch. This repo's own bump policy defines patch as
    "a fix with no interface change", so a patch release cannot falsify a claim
    about what a verb does or what `check` reports — warning on one would be
    noise the consumer cannot act on, on a record it is not allowed to rewrite.
    """
    m = _SEMVER_RE.search(version)
    return (int(m.group(1)), int(m.group(2))) if m else None


def assumption_engine_pin(line: str) -> Optional[Tuple[str, str]]:
    """``(label, version)`` for an engine-marked assumption bullet, else None.

    *version* is the newest SemVer triple in the marker, so a re-check note
    supersedes the original pin: that is how a stale marker is cleared without
    rewriting the assumption itself — the claim stands, and what was learned
    about it afterwards is appended, exactly as `progress amend` and an
    insights status trail already work (§1).
    """
    m = _ASSUMPTION_LABEL_RE.match(line)
    if not m:
        return None
    run = m.group("bold") or m.group("plain") or ""
    versions = [f"{a}.{b}.{c}"
                for marker in _ENGINE_MARKER_RE.findall(run)
                for a, b, c in _SEMVER_RE.findall(marker)]
    if not versions:
        return None
    newest = max(versions, key=lambda v: tuple(int(x) for x in v.split(".")))
    # The label is what stands before the marker — "A8" out of "A8 (engine
    # 1.28.1): the CLI warns …" — so the warning names the assumption the way
    # the spec's own cross-references do.
    label = run.split("(", 1)[0].strip().rstrip(":").strip()
    return (label or "assumption"), newest


def _assumption_bullets(text: str) -> List[str]:
    """The bullets of the ``## Assumptions`` block, each joined onto one line.

    Joining is the whole point: a real spec's assumption runs to a paragraph,
    so its bold label routinely opens on the bullet line and closes two lines
    down — two of the three specs issue #144 was filed over are written that
    way. A line-at-a-time reader sees an unterminated `**`, matches nothing,
    and the check silently never fires.

    A blank line ends a bullet, a `## ` heading ends the block, and a `### `
    sub-heading does not: it is still inside Assumptions.
    """
    out: List[str] = []
    current: Optional[str] = None
    in_block = False
    for line in text.splitlines():
        if re.match(r"^##\s+", line):
            if current:
                out.append(current)
                current = None
            in_block = bool(re.match(r"^##\s+Assumptions\b", line))
            continue
        if not in_block:
            continue
        if re.match(r"^\s*[-*]\s+\S", line):
            if current:
                out.append(current)
            current = line.strip()
        elif current is not None:
            if line.strip():
                current += " " + line.strip()
            else:
                out.append(current)
                current = None
    if current:
        out.append(current)
    return out


def _stale_assumption_pins(text: str, engine: str) -> List[Tuple[str, str]]:
    """Engine-marked assumptions in *text* whose engine predates *engine*.

    Reads the ``## Assumptions`` block only. An assumption is a durable record
    that outlives its branch and can legitimately pin **engine** behaviour —
    what `aide check` warns about, what a verb does — and `install.py --update`
    says nothing about the specs whose assumptions it has just falsified
    (issue #144). One consumer carried three merged specs asserting warnings a
    later release had deliberately removed, one of them calling their presence
    "expected output"; nothing detected it, and the specs are records, so the
    repair is not to edit them.
    """
    installed = _feature_line(engine)
    if installed is None:
        return []
    out: List[Tuple[str, str]] = []
    for bullet in _assumption_bullets(text):
        pin = assumption_engine_pin(bullet)
        if pin is None:
            continue
        pinned = _feature_line(pin[1])
        if pinned is not None and pinned < installed:
            out.append(pin)
    return out


def item_spec_warnings(ddir: Path, ddir_rel: str = "docs/aide",
                       engine: Optional[str] = None) -> List[str]:
    """Item specs that break the shapes §1 and §5 fix.

    Four rules: the `# Item NNN — Title` heading must agree with the filename
    (the status report parses the title from it); the header must carry NO
    status field (status lives only in progress.md, and a duplicate has no
    owner and only drifts); the **Assumptions** block is mandatory, since it
    is what the validator surfaces for audit; and no always-authorised path
    may sit under **Asserts against** — the loop itself edits those on every
    item (the mandatory status flip alone touches progress.md), so the pin can
    never hold and `aide scope` would fail the item on its routine
    bookkeeping. Pinning progress.md is the natural way to write an AC that
    reads a gate row, which is exactly why it needs a spec-time warning.

    A fifth is advisory rather than structural: an assumption marked with the
    engine it was true for — `- **A8 (engine 1.28.1):** …` — whose engine
    predates the installed one. See `_stale_assumption_pins`. It is read on
    live specs only — not one whose item progress.md shows ✅, ❌ or ⏸️, or 📋
    in a withdrawn stage (``record_documents``, issues #338, #393): §1 never
    rewrites a merged spec, and the appended re-check that clears the
    warning goes stale at the next release, so on a record it would return
    forever.

    None of them reads a file that no lookup finds: one whose name
    `item_spec_number` rejects gets a single warning naming the rename instead
    (issue #228), since every verb that reads a spec treats its item as having
    none, and a number printed off the filename would disagree with them.

    *ddir_rel* is the docs dir as specs spell it in their repo-relative paths;
    `run_checks` passes the configured value, and the default matches the
    scaffolded `aide.toml`. *engine* is the installed engine version, as
    `.aide/VERSION` holds it; `None` (the default, and what a script copied
    away from its VERSION file gets) skips the assumption check entirely.

    The missing-Assumptions finding is reported as ONE aggregated line. Specs
    predating the rule are common — 32 of 112 in the consumer this was measured
    against — and 32 separate warnings would bury the substantive ones, which is
    the failure mode issue #13 was filed for.
    """
    idir = ddir / "items"
    if not idir.is_dir():
        return []
    always = _always_authorised_paths(ddir_rel)
    out: List[str] = []
    missing_assumptions: List[str] = []
    stale_pins: List[str] = []
    records = _docs_records(ddir) if engine else set()
    for path in sorted(idir.glob("*.md")):
        num = item_spec_number(path)
        if num is None:
            out.append(_unfindable_spec_warning(path))
            continue
        text = path.read_text(encoding=_ENCODING)
        if not re.search(rf"^#\s+Item\s+0*{num}\s*[—–-]\s*\S", text, re.MULTILINE):
            out.append(f"items/{path.name}: no '# Item {num:03d} — Title' heading "
                       f"matching the filename")
        head = text.split("\n---", 1)[0]
        # A FIELD, not bold emphasis. Two conditions keep this precise: the line
        # is part of the header blockquote, and a colon sits beside the bold —
        # inside it (`**Status:**`, the template's own spelling) or right after
        # (`**Status**:`). Matching bare `**Status**` anywhere would flag prose
        # that merely emphasises the word.
        sm = next((m for line in head.splitlines() if line.lstrip().startswith(">")
                   for m in [_ITEM_STATUS_FIELD_RE.search(line)] if m), None)
        if sm:
            out.append(f"items/{path.name}: header carries a '{sm.group('name')}' field — "
                       f"status lives only in progress.md; a duplicate has no owner "
                       f"and only drifts")
        if not re.search(r"^##\s+Assumptions", text, re.MULTILINE):
            missing_assumptions.append(f"{num:03d}")
        elif engine and path not in records:
            stale_pins.extend(f"{num:03d} {label} (engine {version})"
                              for label, version in _stale_assumption_pins(text, engine))
        parsed = parse_authorised_paths(text)
        for pin in (parsed.asserts_against if parsed else []):
            if any(patterns_overlap(pin, a) for a in always):
                out.append(
                    f"items/{path.name}: '{pin}' is pinned under Asserts "
                    f"against, but every item is authorised to edit it — the "
                    f"status flip and the insight append are loop bookkeeping "
                    f"— so the pin can never hold and `aide scope` will report "
                    f"a contradiction on every run; put the read-only content "
                    f"check in an acceptance criterion's test instead")
        # Asserts against means pinned-NOT-changed — `aide scope` prints
        # exactly that — so a path the spec also authorises itself to change
        # is a contradiction authored into the spec: the moment the item uses
        # the authorisation, scope fails it with no spec-side fix visible
        # (issue #94). The same holds when a pin glob covers a May change
        # entry (issue #269): every change that entry authorises is inside the
        # pin. One direction only — a literal pin under a May change glob is
        # the legitimate carve-out shape ("I may edit docs/** but not
        # docs/api.md") and scope stays the judge of whether it held.
        # Silent narrowing, made loud where it is authored (issue #119): the
        # spans after a bullet's first are dropped, and so is anything on a
        # continuation line, so the item is authorised for less than its spec
        # says and only an `aide scope` FAIL much later reveals it.
        for declared, dropped in dropped_bullet_spans(text):
            shown = ", ".join(f"'{d}'" for d in dropped)
            out.append(
                f"items/{path.name}: the Authorised paths bullet for "
                f"'{declared}' also names {shown}, and `aide scope` reads none "
                f"of them — a bullet declares ONE path, the first backtick "
                f"span of its opening line, and a continuation line is not "
                f"read at all. Give each path its own bullet, or the item is "
                f"authorised for less than its spec says")
        may_normalised = {_strip_dot_slash(p.strip())
                         for p in (parsed.may_change if parsed else [])}
        for pin in (parsed.asserts_against if parsed else []):
            covered = [m for m in parsed.may_change if pattern_covers(pin, m)]
            if _strip_dot_slash(pin.strip()) in may_normalised:
                out.append(
                    f"items/{path.name}: '{pin}' is listed under both May "
                    f"change and Asserts against — Asserts against means "
                    f"pinned-not-changed, so `aide scope` will report every "
                    f"change to it as a contradiction. If the item writes the "
                    f"file and its tests assert against the final state, list "
                    f"it only under May change and say so in prose")
            elif covered:
                shown = ", ".join(f"'{m}'" for m in covered)
                out.append(
                    f"items/{path.name}: '{pin}' under Asserts against covers "
                    f"{shown}, which May change names — Asserts against means "
                    f"pinned-not-changed, so `aide scope` will report every "
                    f"change May change authorises there as a contradiction. "
                    f"Narrow the pin so it leaves the May change path out, or "
                    f"put the read-only check in an acceptance criterion's "
                    f"test instead")
    if missing_assumptions:
        shown = ", ".join(missing_assumptions[:8])
        more = (f" (+{len(missing_assumptions) - 8} more)"
                if len(missing_assumptions) > 8 else "")
        out.append(f"{len(missing_assumptions)} item spec(s) have no mandatory "
                   f"'## Assumptions' block: {shown}{more} — it is what the "
                   f"validator surfaces for audit at the queue boundary")
    if stale_pins:
        shown = "; ".join(stale_pins[:6])
        more = f" (+{len(stale_pins) - 6} more)" if len(stale_pins) > 6 else ""
        out.append(f"{len(stale_pins)} assumption(s) pin an engine older than "
                   f"the installed {engine}: {shown}{more} — the engine has "
                   f"moved under the claim, so re-check it before a reader "
                   f"trusts it. The spec is a record: append the outcome to "
                   f"the marker (`(engine 1.28.1, re-checked {engine})`) "
                   f"rather than rewriting the assumption")
    return out


def _stray_icons_in_line(line: str) -> List[str]:
    """Status icons on this line that sit where one could plausibly be
    mistaken for a structural status declaration.

    conventions.md §1 is explicit that icons are read *only* at structural
    positions — a deliverable bullet's leading icon, a table row's last cell,
    a stage header's trailing icon — and that "an icon anywhere else […] is
    plain text and is never read as status, so authors need not avoid the
    icon vocabulary in free text." A bullet with no leading icon, or an
    ordinary paragraph, therefore has *no* structural position at all, and
    any icon it contains is exactly that free text — never stray. Only a
    heading, whose sole structural slot is the trailing icon, can still carry
    a status-shaped icon somewhere a reader would misread as the header's
    status.
    """
    icons = list(_ICON_RE.finditer(line))
    if not icons:
        return []
    if _QUEUE_STATUS_RE.match(line):
        return []  # "> **Status:** …" lines legitimately carry an icon
    if line.strip().startswith("|"):
        return []  # table rows: parsers read specific cells only, never prose
    if _BULLET_RE.match(line):
        return []  # bullets: only the leading icon is structural; the rest is free prose
    if re.match(r"^#{1,6}\s", line):  # any heading level may carry a trailing icon
        t = _TRAILING_ICON_RE.search(line)
        allowed = t.span(1) if t else None
        return [i.group(0) for i in icons if i.span() != allowed]
    return []  # ordinary paragraph text: no structural position exists here at all


def stray_icon_warnings(ddir: Path) -> List[str]:
    """Warn on status icons outside structural positions in the status-bearing
    documents (``progress.md`` and queue files).

    The parsers only ever read icons at structural positions (conventions.md
    §1), so a stray icon is never *misread* — this lint surfaces near-misses so
    the status documents stay unambiguous to human readers too. Other documents
    (vision, roadmap, item specs) are not scanned: nothing parses icons there,
    so their prose is free.
    """
    out: List[str] = []
    paths: List[Path] = []
    progress = ddir / "progress.md"
    if progress.is_file():
        paths.append(progress)
    paths.extend(iter_queue_paths(ddir / "queue"))
    for path in paths:
        for lineno, line in enumerate(path.read_text(encoding=_ENCODING).splitlines(), start=1):
            for icon in _stray_icons_in_line(line):
                out.append(
                    f"{path.relative_to(ddir).as_posix()}:{lineno}: status icon {icon} outside a "
                    f"structural status position (parsers treat it as plain text; move "
                    f"or remove it if status was intended)"
                )
    return out


def _cells_shown(cells: List[Tuple[str, str]]) -> str:
    return " and ".join(f"{where} {STATUS_TO_ICON[st]} {st}" for where, st in cells)


def _deferral_fix(whose: str, unmarked: List[Tuple[str, List[int]]],
                  marked_open: bool, derived: str,
                  droppable: bool = False) -> str:
    """The remedy for a ⏸️ cell over open work: defer that work, each bullet
    by the form that addresses it, or restore what the rollup computes.

    *unmarked* pairs each stage with the 1-based positions of its open bullets
    that carry no item marker (issue #336), which only the positional form
    reaches; *marked_open* says an itemised bullet is open too, so the item
    form is named beside it. The positional form also drops such a bullet
    the stage does not need (issue #362), so the remedy names that beside it
    where *droppable* says every stage in *unmarked* would take the drop: a
    ⏸️ cell over an unmarked bullet the owner meant as "not needed" is the
    case the drop exists for, and a stage left all ❌ is the one it refuses.
    """
    restore = f"or restore {STATUS_TO_ICON[derived]}"
    item_form = "'aide progress set NNN deferred --reason …'"
    if not unmarked:
        return f"defer {whose} open items with {item_form}, {restore}"
    if len(unmarked) == 1:
        stage, ks = unmarked[0]
        by_position = (f"'aide progress set --stage {stage} --deliverable K "
                       f"deferred --reason …' (K = {', '.join(map(str, ks))})")
    else:
        where = "; ".join(f"stage {n}: K = {', '.join(map(str, ks))}"
                          for n, ks in unmarked)
        by_position = (f"'aide progress set --stage N --deliverable K "
                       f"deferred --reason …' ({where})")
    if droppable:
        by_position += (" — or `dropped` in place of `deferred` for one the "
                        "stage does not need")
    if marked_open:
        return (f"defer {whose} open items with {item_form} and the "
                f"deliverables with no item marker with {by_position}, "
                f"{restore}")
    return (f"{whose} open deliverables carry no item marker, so defer them "
            f"with {by_position}, {restore}")


def _stage_drift_fix(off: List[Tuple[str, str]], derived: str,
                     stage: str = "N", unmarked: Sequence[int] = (),
                     marked_open: bool = True, droppable: bool = False) -> str:
    """The remedy a stage's drift warning names, by what the cells and the
    bullets disagree about.

    *unmarked* are the 1-based positions of the stage's open bullets that
    carry no item marker, which `set NNN deferred` cannot address (issue
    #336): the remedy names the positional form for them, beside the item
    form while *marked_open* says an itemised bullet is open too.
    """
    target = "cells" if len(off) > 1 else off[0][0]
    if derived == "deferred":
        return f"every open deliverable is ⏸️, so set the {target} to ⏸️"
    if any(st == "deferred" for _, st in off):
        if derived == "complete":
            return "nothing is left open to defer, so restore ✅"
        return _deferral_fix("the stage's" if marked_open or not unmarked
                             else "its", [(stage, list(unmarked))]
                             if unmarked else [], marked_open, derived,
                             droppable)
    return (f"a stage's cells follow its bullets, so set the {target} to "
            f"{STATUS_TO_ICON[derived]}, or move the bullets with "
            f"'aide progress set'")


def derived_cell_findings(lines: List[str]
                          ) -> Tuple[List[str], List[str], Set[str]]:
    """``(errors, warnings, objectives named)`` over every derived cell (#285).

    A stage's header and summary row are compared with `rollup_status` over
    its bullets, an Objective row with `objective_rollup` over the stages it
    names — the writer's own derivation, with none of the writer's restraint:
    no never-downgrade and no hand-held ⏸️, which are rules about when a verb
    may *write* a cell, not about what the cell should say. So a file the
    verbs alone wrote never trips this, while a hand-set ⏸️ the writer leaves
    standing is named for as long as it disagrees.

    A ✅ the derivation does not support is an error, as the ✅ summary row
    always was — one per cell; every other disagreement is a warning, a
    stage's off cells named together in one. One message per cell: the
    header-against-summary comparison runs only where neither cell was named
    — which leaves it the stage with no bullet to derive from, and a ❌
    header. ❌ is never compared: it is a scope decision, not a rollup, and a
    ❌ summary row drops its whole stage (header included) as before. An
    Objective row whose stages roll up to ✅ under a target that is not ✅ Met
    is the target comparisons' to report, which already do, so a ✅ row
    there is not reported twice; and the third value, the G-codes this named,
    is what `run_checks` leaves out of those target comparisons in turn. A
    stage whose summary row is ❌ is left out of an Objective row's
    derivation too (issue #382), and a row naming withdrawn stages alone is
    compared with ❌ — an error where it reads ✅, a warning otherwise.
    """
    errors: List[str] = []
    warnings: List[str] = []
    named: Set[str] = set()
    summary_status: Dict[str, str] = {}
    for line in lines:
        cells = _split_row(line) if line.strip().startswith("|") else []
        if cells and _reads(_STAGE_SUMMARY, cells):
            summary_status[cells[0]] = _icon_status(cells[3])

    for start, end, num in stage_sections(lines):
        header_status = _header_status(lines[start])
        derived = rollup_status(stage_deliverable_statuses(lines, start, end))
        summ = summary_status.get(num)
        if summ == "excluded":
            continue
        off = [(where, st) for where, st in (("summary", summ),
                                             ("header", header_status))
               if st and st != "excluded" and derived and st != derived]
        over = [(w, st) for w, st in off if st == "complete"]
        rest = [(w, st) for w, st in off if st != "complete"]
        for where, _ in over:
            errors.append(
                f"stage {num}: {where} marked ✅ but has non-complete "
                f"deliverables — they roll up to {STATUS_TO_ICON[derived]} "
                f"{derived}")
        if rest:
            unmarked = _unmarked_open_positions(lines, num)
            marked_open = len(unmarked) < sum(
                st in _DEFERRABLE for st in stage_deliverable_statuses(lines, start, end))
            if derived == "complete" and not any(st == "deferred" for _, st in rest):
                shown = " and ".join(f"{w} shows {st}" for w, st in rest)
                warnings.append(
                    f"stage {num}: all deliverables ✅ but {shown} — if the "
                    f"work shipped but the stage's goal is unmet, record the "
                    f"goal as an Outcome target (❌ Not met) and close the "
                    f"stage; stages track shipped work, targets track "
                    f"measured outcomes")
            else:
                warnings.append(
                    f"stage {num}: {_cells_shown(rest)} but its deliverables "
                    f"roll up to {STATUS_TO_ICON[derived]} {derived} — "
                    f"{_stage_drift_fix(rest, derived, num, unmarked, marked_open, _stage_can_lose_a_bullet(lines, num))}")
        if not off and header_status and summ and header_status != summ:
            warnings.append(
                f"stage {num}: header {header_status} disagrees with summary {summ}")

    stage_status = stage_rollups(lines)
    section_nums = {num for _, _, num in stage_sections(lines)}
    blocked = _blocked_objectives(lines)
    withdrawn = {n for n, st in summary_status.items() if st == "excluded"}
    for line in lines:
        cells = _split_row(line) if line.strip().startswith("|") else []
        if not (cells and _reads(_OBJECTIVE_COVERAGE, cells)):
            continue
        g = re.match(r"G\d+", cells[0]).group(0)
        current = _icon_status(cells[2])
        nums = _objective_row_stages(cells[1])
        if nums and not any(n in section_nums for n in nums):
            warnings.append(
                f"objective {g}: Delivered by '{cells[1]}' names no stage "
                f"with a '## Stage N' section, so nothing derives its "
                f"{STATUS_TO_ICON[current]} — name the stage that delivers it")
            continue
        if current == "excluded":
            continue
        derived = objective_rollup(nums, stage_status, withdrawn)
        if derived is None:
            continue
        if derived == "excluded":
            # Every stage the row names is withdrawn (issue #382): nothing is
            # left to deliver it, and a ✅ claims delivery by none of them.
            named.add(g)
            shown = ", ".join(nums)
            (errors if current == "complete" else warnings).append(
                f"objective {g}: {STATUS_TO_ICON[current]} {current} but "
                f"every stage it names (stage {shown}) is withdrawn — ❌ in "
                f"the Stage summary table — so set it to ❌")
            continue
        held = derived == "complete" and g in blocked
        if held:
            if current == "complete":
                continue  # the Outcome target comparisons name this row
            derived = "in-progress"
        if current == derived:
            continue
        named.add(g)
        stages = ", ".join(
            f"{n} ❌ withdrawn" if n in withdrawn
            else f"{n} {STATUS_TO_ICON[stage_status[n]]}"
            for n in nums if n in stage_status or n in withdrawn)
        why = (" (held below ✅ by an Outcome target not ✅ Met)"
               if held else "")
        if current == "complete":
            errors.append(
                f"objective {g} marked ✅ but the stages it names (stage "
                f"{stages}) roll up to {STATUS_TO_ICON[derived]} {derived} — "
                f"an objective is delivered only when every stage that "
                f"delivers it is ✅")
            continue
        if derived == "deferred":
            fix = "every stage it names is ✅ or ⏸️, so set it to ⏸️"
        elif current == "deferred":
            named_sections = [(start, end, n) for start, end, n in
                              stage_sections(lines)
                              if n in nums and n not in withdrawn]
            unmarked = [(n, _unmarked_open_positions(lines, n))
                        for _, _, n in named_sections]
            unmarked = [(n, ks) for n, ks in unmarked if ks]
            open_total = sum(st in _DEFERRABLE
                             for start, end, _ in named_sections
                             for st in stage_deliverable_statuses(lines, start, end))
            marked_open = open_total > sum(len(ks) for _, ks in unmarked)
            fix = _deferral_fix("the" if marked_open or not unmarked else "its",
                                unmarked, marked_open, derived,
                                bool(unmarked) and all(
                                    _stage_can_lose_a_bullet(lines, n)
                                    for n, _ in unmarked))
        else:
            fix = (f"an Objective row follows its stages, so set it to "
                   f"{STATUS_TO_ICON[derived]}")
        warnings.append(
            f"objective {g}: {STATUS_TO_ICON[current]} {current} but the "
            f"stages it names (stage {stages}) roll up to "
            f"{STATUS_TO_ICON[derived]} {derived}{why} — {fix}")
    return errors, warnings, named


def run_checks(repo_root: Path, config: Dict[str, Dict[str, object]],
               branches: Optional[List[str]] = None) -> Tuple[List[str], List[str]]:
    """Return ``(errors, warnings)``. Empty errors == pass.

    Every check above the two early returns below runs before, and survives,
    them, for one of two reasons. The seven test-hygiene lints —
    `absolute_path_test_warnings`, `separator_dependent_test_warnings`,
    `cli_subprocess_test_warnings`, `subprocess_encoding_test_warnings`,
    `gitattributes_eol_pin_warnings`, `scope_claim_test_warnings`,
    `insights_fixture_test_warnings` — read `tests_dir` and never touch
    `docs_dir` (the last reads docs_dir's *name* from the config, to know
    what path a test must not open), and `insight_reference_findings`
    reads both, so they are the ones that make this function worth calling in
    a repo with no document set. The rest *are* document checks; they simply
    find nothing to say when `docs_dir` is absent, so keeping them costs
    nothing and they still report on a `docs_dir` that exists but has no
    `progress.md`.

    Three cases, kept apart: a repo with **no `docs_dir` at all** gets the
    test-hygiene lints and passes; a `docs_dir` that **exists but is not a
    directory** is a misconfigured `aide.toml` and an error; and a `docs_dir`
    that is a directory but has **lost its `progress.md`** is the error it
    always was.
    """
    errors: List[str] = []
    warnings: List[str] = []
    ddir = docs_dir(repo_root, config)
    progress_path = ddir / "progress.md"

    # Config first, and before the early returns: a value the engine acts on
    # is wrong whether or not this repo keeps a document set (issue #302).
    errors.extend(loop_config_errors(config))
    errors.extend(template_residue_errors(ddir))
    errors.extend(conflict_marker_errors(ddir, repo_root))
    warnings.extend(stray_icon_warnings(ddir))
    warnings.extend(insight_warnings(ddir))
    # Reads tests_dir as well as docs_dir, so it runs before the early
    # returns below, like the test-hygiene lints (issue #276).
    ref_errors, ref_warnings = insight_reference_findings(repo_root, config, ddir)
    errors.extend(ref_errors)
    warnings.extend(ref_warnings)
    warnings.extend(ledger_warnings(ddir))
    warnings.extend(absolute_path_test_warnings(repo_root, config))
    warnings.extend(separator_dependent_test_warnings(repo_root, config))
    warnings.extend(cli_subprocess_test_warnings(repo_root, config))
    warnings.extend(subprocess_encoding_test_warnings(repo_root, config))
    warnings.extend(gitattributes_eol_pin_warnings(repo_root, config))
    warnings.extend(scope_claim_test_warnings(repo_root, config))
    warnings.extend(insights_fixture_test_warnings(repo_root, config))
    warnings.extend(header_blockquote_warnings(ddir))
    warnings.extend(root_document_warnings(ddir))
    warnings.extend(forward_dependency_warnings(ddir))
    warnings.extend(coverage_completeness_warnings(ddir))
    # A docs_dir outside the repo falls back to its absolute spelling, which
    # cannot appear in a spec's repo-relative paths — the always-authorised
    # pin lint then has nothing to match; the other spec-shape lints still
    # apply.
    warnings.extend(item_spec_warnings(ddir, _rel_display(ddir, repo_root),
                                       installed_engine_version()))
    if ddir.exists() and not ddir.is_dir():
        # `docs_dir` pointing at something that is not a directory is a
        # misconfiguration, and a third case again: it is neither "no document
        # set" nor "a document set missing its progress.md". Left folded into
        # the partial-adoption branch below it would report "this repo has no
        # AIDE document set" and exit 0 — a typo in aide.toml passing as a
        # deliberate choice not to adopt the loop.
        errors.append(
            f"{_rel_display(ddir, repo_root)} is configured as docs_dir but is "
            f"not a directory — fix [project] docs_dir in aide.toml")
        return errors, warnings
    if not ddir.is_dir():
        # Two different situations used to produce one error. A repo with no
        # document set at all is not a broken loop repo — it is a repo that
        # adopted the conventions and the CLI without the roadmap documents,
        # and the document checks simply do not apply to it. Everything above
        # has already run and is kept: three of those lints read `tests_dir`,
        # not `docs_dir`, and conflating the two cases made them unreachable
        # for any such repo — this framework's own repository included, which
        # is where they were written (issue #57).
        return errors, warnings
    if not progress_path.is_file():
        # `docs_dir` exists but its central document does not: a real error.
        return [f"missing {progress_path}"], warnings
    # One read, reused: two reads can disagree if the file changes between them.
    text = progress_path.read_text(encoding=_ENCODING)
    lines = text.splitlines()
    # Before anything reads the tables: a row no reader can use is dropped by
    # every check below, including the ones that would have errored on it.
    errors.extend(unreadable_row_errors(lines))
    warnings.extend(gate_warnings(lines))
    gate_errors, gate_ref_warnings = gate_reference_findings(repo_root, config,
                                                             ddir, lines)
    errors.extend(gate_errors)
    warnings.extend(gate_ref_warnings)
    warnings.extend(capability_warnings(lines, config.get("validation") or {}))
    # A withdrawn attestation is normal, not a defect — the point is that it
    # stays visible. Retracting is append-only, so without a surfacing rule the
    # withdrawal would live only in one commit's diff, which is exactly the
    # quiet the trail exists to prevent.
    for retraction in retracted_criteria(lines):
        warnings.append(f"progress.md: {retraction_summary(retraction)}")
    # The same rule one level up (issue #271): a reopened item stays visible,
    # worded by the item's status today.
    for reopening in reopened_items(lines):
        warnings.append(f"progress.md: {reopening_summary(reopening)}")
    warnings.extend(nested_deliverable_warnings(lines))
    warnings.extend(identical_deliverable_warnings(lines))
    warnings.extend(unattributed_reference_warnings(lines))
    warnings.extend(acceptance_drift_warnings(ddir, lines))
    warnings.extend(template_drift_warnings(ddir, _parse_item_status(lines)[2],
                                            withdrawn=withdrawn_stage_items(lines)))

    # Mandatory sections. Rows are taken by shape from anywhere in the file,
    # with the one test `unreadable_row_errors` reports the failures of.
    # A table whose every row is unreadable is present, and already reported
    # row by row; "missing" on top of that would send the author looking for
    # a table that is there. One written without leading `|` is missing: no
    # reader or writer here has ever taken a row from it.
    table_rows = [_split_row(l) for l in lines if l.strip().startswith("|")]
    reported = {t.name for t, *_ in _unreadable_rows(lines)}
    has_stage_table = (any(_reads(_STAGE_SUMMARY, c) for c in table_rows)
                       or _STAGE_SUMMARY.name in reported)
    has_obj_table = (any(_reads(_OBJECTIVE_COVERAGE, c) for c in table_rows)
                     or _OBJECTIVE_COVERAGE.name in reported)
    sections = stage_sections(lines)
    if not has_stage_table:
        errors.append("progress.md: missing Stage summary table")
    if not has_obj_table:
        errors.append("progress.md: missing Objective coverage table")
    if not sections:
        errors.append("progress.md: no '## Stage N' sections")

    # Every derived cell against the rollup (issue #285).
    cell_errors, cell_warnings, named_objectives = derived_cell_findings(lines)
    errors.extend(cell_errors)
    warnings.extend(cell_warnings)
    summary_status: Dict[str, str] = {}
    for cells in table_rows:
        if _reads(_STAGE_SUMMARY, cells):
            summary_status[cells[0]] = _icon_status(cells[3])
    section_nums = {num for _, _, num in sections}

    for num in summary_status:
        if num not in section_nums:
            warnings.append(f"stage {num}: in summary table but has no '## Stage {num}' section")

    # Outcome targets: goal truth gates the OBJECTIVE rows. Claiming an
    # objective ✅ over an unmet target is the goal-level over-claim this
    # table exists to prevent (issue #14) — the mirror of the deliverable-level
    # error above.
    obj_status: Dict[str, str] = {}
    for cells in table_rows:
        if _reads(_OBJECTIVE_COVERAGE, cells):
            obj_status[re.match(r"G\d+", cells[0]).group(0)] = _icon_status(cells[2])
    for t in outcome_targets(lines):
        if t.kind is None:
            warnings.append(
                f"progress.md:{t.lineno}: outcome target '{t.text}' has an "
                f"unrecognised Status (expected '✅ Met', '❌ Not met' or "
                f"'❓ Unverified')")
        for g in t.objectives:
            # A row the derived-cell pass already named gets no second
            # message: its stages do not support the ✅ to begin with.
            if obj_status.get(g) != "complete" or g in named_objectives:
                continue
            if t.kind == "not-met":
                errors.append(
                    f"objective {g} marked ✅ but outcome target '{t.text}' "
                    f"is ❌ Not met")
            elif t.kind != "met":
                warnings.append(
                    f"objective {g} marked ✅ but outcome target '{t.text}' "
                    f"is not ✅ Met")

    # Queues: state is DERIVED from progress.md (open = any 📋/🚧 item); a
    # declared "> **Status:**" line is decorative — warn only when it lies.
    # Open as `claim` reads it: a withdrawn stage's 📋 item keeps no queue
    # open (`queue_is_open`), so a queue left with only such items, stamped
    # completed, is not warned as still open (issue #393).
    qdir = ddir / "queue"
    seen: Dict[int, str] = {}
    if qdir.is_dir():
        _, _, istat = _parse_item_status(lines)
        q_withdrawn = withdrawn_stage_items(lines)
        for qpath in iter_queue_paths(qdir):
            qtext = qpath.read_text(encoding=_ENCODING)
            derived_open = queue_is_open(qtext, istat, q_withdrawn)
            declared = queue_status(qtext)
            if declared:
                declared_live = declares_live(declared)
                if declared_live and not derived_open:
                    idle = any(n in q_withdrawn
                               and istat.get(n, "planned") == "planned"
                               for n in queue_item_numbers(qtext))
                    warnings.append(
                        f"{qpath.name}: declares 'Live' but every item is finished"
                        f"{' or 📋 in a withdrawn stage' if idle else ''} — "
                        f"state is derived from progress.md; run 'aide queue tidy' "
                        f"or drop the decorative Status line")
                elif not declared_live and derived_open:
                    warnings.append(
                        f"{qpath.name}: marked completed but still has open items "
                        f"in progress.md")
            for n in queue_item_numbers(qtext):
                if n in seen and seen[n] != qpath.name:
                    errors.append(f"item {n:03d} appears in both {seen[n]} and {qpath.name}")
                seen[n] = qpath.name

    # Item spec files: no duplicate numbers.
    idir = ddir / "items"
    if idir.is_dir():
        spec_nums: Dict[int, str] = {}
        for ipath in sorted(idir.glob("*.md")):
            n = item_spec_number(ipath)
            if n is None:
                continue  # item_spec_warnings names it
            if n in spec_nums:
                errors.append(f"duplicate item spec number {n:03d}: {spec_nums[n]} and {ipath.name}")
            spec_nums[n] = ipath.name

    # Claim-branch <-> status agreement (best effort).
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    if branches is None:
        branches = _list_claim_branches(repo_root, prefix)
    _, _, item_status = _parse_item_status(lines)
    withdrawn_items = spent_by_withdrawal(lines, item_status)
    off_origin = (_branches_off_origin(repo_root, config, prefix)
                  if branches else {})
    for br in branches:
        n = _branch_item_number(br, prefix)
        why = off_origin.get(br)
        # Read against the last fetch, like every other remote question here,
        # and a warning rather than an error for that reason. Only a branch
        # origin never had is advised a push: one deleted there was deleted
        # on purpose, as far as this checkout can tell (issue #364).
        if why is not None and why.kind == OFF_ORIGIN_UNPUBLISHED:
            warnings.append(
                f"unpublished branch {br}: this checkout has it and origin "
                f"does not, so it is invisible to every other checkout — a "
                f"failed 'aide claim' or 'aide queue start' push is the usual "
                f"cause. Publish it ('git push -u origin {br}') or delete it.")
        elif why is not None and why.kind == OFF_ORIGIN_GONE_LANDED:
            warnings.append(
                f"stale branch {br}: it was published and has since been "
                f"deleted on origin, and everything on it is already in "
                f"{why.where}, so there is nothing to publish — "
                f"'{_gc_merged_hint(why.where, config)}' deletes it.")
        elif why is not None:
            warnings.append(
                f"branch {br} was deleted on origin and its work COULD NOT BE "
                f"FOUND in {why.where}: it was published (its upstream "
                f"origin/{br} is gone), so either it landed in a shape this "
                f"check cannot see — squash-merged and then built over on the "
                f"same lines, or squash-merged under git older than 2.38 — or "
                f"this checkout holds the only copy. Check whether its work "
                f"merged: if it did, 'git branch -D {br}' deletes it ('aide "
                f"gc --merged' measures the same way and will not); if not, "
                f"land the work through a reviewed branch before deleting "
                f"anything. Never re-publish it blindly.")
        if n is None:
            # Not a claim branch. A queue branch is expected and silent; anything
            # else carrying the prefix is reported rather than ignored, so a real
            # stale claim named unconventionally cannot hide behind the anchor.
            if not _is_queue_branch(br, prefix):
                warnings.append(
                    f"unrecognised branch {br}: carries the claim prefix but is "
                    f"not '{prefix}NNN-short-name' (conventions.md §4), so no "
                    f"item status is tracked for it — rename it to the claim "
                    f"shape, or once it is merged run 'aide gc --merged' to "
                    f"delete it")
            continue
        # 🔍 is deliberately NOT reported: a claim branch whose item is awaiting
        # review is a normal, correct state, and warning about it on every run
        # until the human merges is how a real warning gets tuned out.
        if item_status.get(n) == "complete":
            warnings.append(f"stale claim branch {br}: item {n:03d} is already ✅")
        elif n in withdrawn_items:
            # The ❌ half of the stale ground (issue #387): a dropped item's
            # branch had no route out, since `merge` refuses a ❌ item.
            warnings.append(
                f"stale claim branch {br}: item {n:03d} is "
                f"{withdrawn_items[n]}, so nothing will merge it — 'aide gc' "
                f"deletes it once git shows nothing on it unlanded, and "
                f"'aide gc --abandon' deletes it with its work")

    return errors, warnings


def _parse_item_status(lines: List[str]) -> Tuple[List[str], List[str], Dict[int, str]]:
    """Map item number -> most-advanced status found on its deliverable bullets.

    The only structural status declaration (conventions.md §1) is a deliverable
    bullet's leading icon — a line matching ``_BULLET_RE`` — together with any
    of its wrapped continuation lines (indented text carrying no bullet marker
    of its own). A reference anywhere else — a table cell, an acceptance
    checkbox, an ordinary paragraph — is free text and is never read as status,
    however many item numbers it happens to name (issue #15): a verification
    table's Notes column narrating what went wrong with several items, or a
    checkbox that merely cites the item that satisfies it, must not pull that
    item's tracked status backwards.

    Within a bullet, only the trailing ``*(Item NNN)*`` marker attributes — §1
    already calls it "the suffix [that] ties an item to the bullet". A
    reference form elsewhere in the bullet's prose is as free as one in a
    table cell: a ✅ bullet whose text mentions a live sibling ("absorbing
    *(Item 095)*'s scope") used to mark that sibling complete, overriding its
    own 📋 bullet — and once spent items were discounted from the cross-spec
    checks, the mis-attribution silenced exactly the pre-build errors the
    checks exist to raise (issue #99).
    """
    item_status: Dict[int, str] = {}
    for start, last in _deliverable_bullet_spans(lines):
        bullet_status = ICON_TO_STATUS[_BULLET_RE.match(lines[start]).group("icon")]
        for num in _bullet_marker_item_numbers(lines[last]):
            if num not in item_status or RANK[bullet_status] > RANK[item_status[num]]:
                item_status[num] = bullet_status
    return [], [], item_status


# --------------------------------------------------------------------------- #
# git plumbing
# --------------------------------------------------------------------------- #
def git(args: List[str], repo_root: Path, check: bool = True) -> subprocess.CompletedProcess:
    """Run git and hand back its output decoded as UTF-8, never as the locale.

    conventions.md §6, applied to the engine that states it. `text=True` alone
    decodes with `locale.getpreferredencoding()` — cp1252 on a Windows
    consumer — so a branch name, a changed path or a commit subject carrying a
    non-ASCII character came back as different characters there than here, and
    a prefix match against it quietly stopped matching. Git speaks UTF-8 for
    refs and paths, so this says so.

    `errors="replace"` rather than strict: a stray byte in one branch name must
    not raise out of `aide claim`. The replacement character fails the same
    match a mangled one did, and does it identically on every platform.

    The one entry the engine runs git through, so the one place its absence
    is read: `GitMissing`, never a `FileNotFoundError` traceback (issue
    #352). `resolve_tool` decides where git is — `[tools] git` in
    `.aide/local.toml`, else PATH — and a key naming a git that is not there
    is its `ToolMisconfigured` (issue #353). Decided before the spawn,
    because a missing *cwd* raises the same error with git present.
    """
    try:
        exe = resolve_tool("git", repo_root)
        missing: Optional[MissingTool] = None if exe else GitMissing()
    except ToolMisconfigured as exc:
        exe, missing = None, exc
    if exe is None:
        assert missing is not None
        if _GIT_OPTIONAL:
            failed = subprocess.CompletedProcess(
                ["git", *args], 127, "", str(missing))
            if check:
                raise subprocess.CalledProcessError(
                    127, failed.args, "", failed.stderr)
            return failed
        raise missing
    return subprocess.run(
        [exe, *args], cwd=str(repo_root), check=check,
        stdout=subprocess.PIPE, stderr=subprocess.PIPE,
        encoding="utf-8", errors="replace",
    )


#: Set by `aide check` alone, for its one run, when git is not on PATH: a
#: missing git then reads as a git that failed — no repository, no branches,
#: no history — instead of `GitMissing`. The check is the documents' verdict,
#: and it has judged them in a repository whose git is off PATH since 1.26.0;
#: what it could not look at is said in one warning, never passed over. That
#: aide.toml needs a git this machine lacks is a separate error, from the
#: dependency report (issue #354).
_GIT_OPTIONAL = False

#: `git_toplevel`'s answers, by repo root, for one invocation: `main` clears
#: it, so a test that drives several verbs in one process never reads a stale
#: one, and a verb asks git at most once however many sites need the answer.
_TOPLEVEL: Dict[str, Optional[Path]] = {}


def _dot_git_at_or_above(repo_root: Path) -> bool:
    """Is there a `.git` at *repo_root* or any directory above it?

    Not the reading of "is this a repository" — `git_toplevel` is — but what
    tells the two ways git can fail to give one apart: no git and no `.git`
    is a directory nothing was ever committed in, while a `.git` git cannot
    read, or cannot be run over, is a repository something is wrong with.
    """
    try:
        here = Path(repo_root).resolve()
    except OSError:
        here = Path(repo_root)
    return any((d / ".git").exists() for d in (here, *here.parents))


def git_toplevel(repo_root: Path) -> Optional[Path]:
    """The top of the git work tree *repo_root* is in, or ``None`` outside one.

    The engine's one reading of "is this a repository" (issue #352), from git
    rather than from ``repo_root / ".git"``: `aide.toml` may sit below the
    top level, where no `.git` is, and a linked worktree's `.git` is a file.
    Asked once per repo root per invocation, since a spawn costs about 13x
    as much on Windows.

    Where git cannot answer, a `.git` decides what that means. Git not on
    PATH: a `.git` at or above *repo_root* is a repository it cannot be run
    over, so `GitMissing`; none is no repository, and a recording verb leaves
    its edit uncommitted as it always did. Git ran and refused: only a `.git`
    at *repo_root itself* is this project's repository, and `GitRefused`
    carries git's own words (a `safe.directory` ownership check, a bare or
    corrupt repository). One further up that git refuses — a `~/.git` owned
    by another user, a bare dotfiles repository — is someone else's, and
    reads as no repository, as it did before the engine asked git (issue
    #352). Under `aide check`'s `_GIT_OPTIONAL` every case reads as none.
    """
    key = str(repo_root)
    if key not in _TOPLEVEL:
        top: Optional[Path] = None
        if Path(repo_root).is_dir():
            try:
                res = git(["rev-parse", "--show-toplevel"], repo_root, check=False)
            except GitMissing:
                if _dot_git_at_or_above(repo_root):
                    raise
                res = None
            out = res.stdout.strip() if res is not None else ""
            if res is not None and res.returncode == 0 and out:
                top = Path(out)
            elif (res is not None and not _GIT_OPTIONAL
                  and (Path(repo_root) / ".git").exists()):
                raise GitRefused(repo_root, res.stderr)
        _TOPLEVEL[key] = top
    return _TOPLEVEL[key]


def _root_prefix(repo_root: Path) -> List[str]:
    """*repo_root*'s path below git's top level, as parts; empty at the top."""
    top = git_toplevel(repo_root)
    if top is None:
        return []
    try:
        rel = Path(repo_root).resolve().relative_to(top.resolve())
    except (ValueError, OSError):
        return []
    return [p for p in rel.as_posix().split("/") if p not in ("", ".")]


def root_relative(repo_root: Path, paths: List[str]) -> List[str]:
    """Paths git named from its top level, renamed relative to *repo_root*.

    Every path reader that compares git's output with the engine's own paths
    goes through this (issue #352): `aide.toml` may sit below the top level,
    where git's `project/src/a.py` is the engine's `src/a.py`. A path outside
    *repo_root* comes back as `../…` rather than being dropped, so `scope`
    still reports a change there — `--relative` would hide it. Unchanged at
    the top level, the common case, with no spawn beyond the cached one.
    """
    prefix = _root_prefix(repo_root)
    if not prefix:
        return list(paths)
    out: List[str] = []
    for path in paths:
        parts = path.split("/")
        i = 0
        while i < len(prefix) and i < len(parts) - 1 and parts[i] == prefix[i]:
            i += 1
        out.append("/".join([".."] * (len(prefix) - i) + parts[i:]))
    return out


def in_repository(repo_root: Path) -> bool:
    """Is *repo_root* inside a git work tree? See `git_toplevel`."""
    return git_toplevel(repo_root) is not None


def not_a_repository(verb: str, repo_root: Path) -> str:
    """The one sentence a verb that needs a repository refuses with outside one.

    Its hint depends on git being there: `git init` is no advice on a machine
    without git, where this is the answer for no `.git` and no git at all.
    """
    why = _git_unavailable(repo_root)
    hint = ("('git init' makes one)" if why is None
            else "— git is not on PATH either, so install it first"
            if why == "git is not on PATH" else f"— and {why}")
    return (f"aide {verb}: {repo_root} is not inside a git repository — this "
            f"verb reads and records git state, so run it from a git work "
            f"tree {hint}")


def _require_repository(verb: str, repo_root: Path) -> bool:
    """Print `not_a_repository` and return False outside a repository."""
    if in_repository(repo_root):
        return True
    print(not_a_repository(verb, repo_root), file=sys.stderr)
    return False


def _commits_here(no_commit: bool, repo_root: Path,
                  before: Optional[Dict[Path, Optional[bytes]]] = None) -> bool:
    """Does a recording verb commit the edit it has just written?

    Not under ``--no-commit``, and not outside a repository. Outside one with
    git not on PATH either — no `.git` at or above *repo_root* — the edit is
    kept uncommitted, as it always was there, and a `notice:` says why. A
    repository git cannot be run over, or cannot read, is different: the
    edit in *before* is put back before the `MissingTool` goes on to
    ``main``, since an edit left written and uncommitted reads as made to the
    re-run that follows (issue #309).
    """
    if no_commit:
        return False
    try:
        if in_repository(repo_root):
            return True
    except MissingTool:
        if before:
            _put_back(before)
        raise
    why = _git_unavailable(repo_root)
    if why is not None:
        print(f"notice: left uncommitted — {why}, and there is "
              f"no .git at or above {repo_root}")
    return False


def _push_new_branch(repo_root: Path, branch: str) -> Optional[str]:
    """``git push -u origin <branch>``: None on success, else a sentence.

    Three verbs publish a branch they have just created — `queue start`,
    `claim`, and `merge` under `pr` mode — and all three pushed with git()'s
    default `check=True`, so every cause of a failed push (no remote at all,
    origin unreachable, expired credentials, a rejecting server-side hook)
    left `main()` on a `CalledProcessError`: a raw traceback in a flow whose
    whole point is to run unattended. `cmd_queue_start` guarded exactly one
    cause in prose — the branch already on origin — and let the rest crash.

    The push is the *last* thing each of those verbs does, so its local half is
    already on disk when it fails. Handing back git's own words lets each
    caller say what survives and how to finish it by hand, which is the
    difference between a stall a person can act on and a stack trace.

    `queue restack` calls it too, and so does `_push_if_ahead` for `queue pr`
    and `queue ready`. No remote at all is not a cause it normally meets:
    off local mode every caller refuses a missing origin before it pushes —
    `queue start`, `claim`, `queue restack` and `merge` through
    `_require_origin`, before their local half exists (issue #377), and
    `queue pr` and `queue ready` through `_queue_pr_branch`'s own check. What
    reaches here is an origin that is there and does not take the push.
    """
    res = git(["push", "-u", "origin", branch], repo_root, check=False)
    if res.returncode == 0:
        return None
    detail = (res.stderr.strip() or res.stdout.strip()
              or f"git exited {res.returncode} without a message")
    return f"pushing {branch} to origin FAILED:\n{detail}"


def _list_claim_branches(repo_root: Path, prefix: str) -> List[str]:
    """Every claim branch, local or on origin, by its short name.

    Empty outside a repository. A git that cannot be run is *not* empty: it
    raises, since "no claim branch" is an answer `merge` refuses on and `check`
    reports no stale branch from (issue #352).
    """
    if not in_repository(repo_root):
        return []
    out_local = git(["branch", "--format=%(refname:short)"], repo_root, check=False).stdout
    out_remote = git(["branch", "-r", "--format=%(refname:short)"], repo_root, check=False).stdout
    names: List[str] = []
    for line in (out_local + out_remote).splitlines():
        name = line.strip()
        short = name.split("/", 1)[1] if name.startswith("origin/") else name
        if short.startswith(prefix):
            names.append(short)
    return sorted(set(names))


# --------------------------------------------------------------------------- #
# command handlers
# --------------------------------------------------------------------------- #
# --------------------------------------------------------------------------- #
# Cross-spec queue check — do a queue's specs conflict, before any is built?
# --------------------------------------------------------------------------- #
class SpecFinding(NamedTuple):
    """One cross-item conflict between the specs on a queue."""

    severity: str          # "error" | "warning"
    kind: str              # machine-readable class, for the --report seam
    items: Tuple[int, ...]
    message: str


def pattern_covers(outer: str, inner: str) -> bool:
    """True when every file *inner* can name is also covered by *outer*.

    The directional half of `patterns_overlap`, deciding the same three cases:
    an identical pattern, a subtree wildcard over the other, and a literal path
    under the other's glob. The direction is what a spec-time lint needs when
    one side's carve-out is legitimate and the other side's is not.
    """
    outer = _strip_dot_slash(outer.strip())
    inner = _strip_dot_slash(inner.strip())
    if outer == inner:
        return True
    if outer.endswith("/**"):
        prefix = outer[: -len("/**")]
        if inner == prefix or inner.startswith(prefix + "/"):
            return True
    return not any(c in inner for c in "*?[") and path_matches(inner, outer)


def patterns_overlap(a: str, b: str) -> bool:
    """True when two ``## Authorised paths`` patterns can cover the same file.

    Deliberately decides only the cases a script *can* decide: an identical
    pattern, a subtree wildcard swallowing the other, and a literal path
    covered by the other's glob. Two unrelated globs that would happen to
    intersect on some file neither spec has thought of are not modelled —
    reporting those would mean guessing at a future tree, and this check exists
    to be trusted, not to be argued with.
    """
    return pattern_covers(a, b) or pattern_covers(b, a)


def _built_after(graph: Dict[int, List[int]]) -> Dict[int, Set[int]]:
    """For each item, every item it is built *after* — its declared
    dependencies and theirs, transitively.

    The ordering `## Dependencies` actually promises. Direct listing is not
    enough on its own: an item that names one sibling which in turn names
    another is built after both, and the pair the caller is about to judge may
    be the far end of that chain.

    Cycle-safe by the `in out` guard rather than by trusting the graph — a
    mutual pair is a real shape here (`_dependency_cycles` reports it as the
    error it is) and must not hang the check that discovers it.
    """
    closure: Dict[int, Set[int]] = {}
    for node in graph:
        out: Set[int] = set()
        stack = list(graph.get(node, []))
        while stack:
            dep = stack.pop()
            if dep in out:
                continue
            out.add(dep)
            stack.extend(graph.get(dep, []))
        out.discard(node)
        closure[node] = out
    return closure


def _dependency_cycles(graph: Dict[int, List[int]]) -> List[List[int]]:
    """Every dependency cycle in *graph*, each reported once.

    A cycle deadlocks `aide claim` outright: every item in it is blocked by
    another item in it, so none is ever claimable and the queue silently stops
    producing work rather than failing.
    """
    cycles: List[List[int]] = []
    seen: set = set()
    state: Dict[int, int] = {}   # 0 = visiting, 1 = done

    def walk(node: int, stack: List[int]) -> None:
        state[node] = 0
        stack.append(node)
        for nxt in graph.get(node, []):
            if state.get(nxt) == 0:
                cycle = stack[stack.index(nxt):]
                key = tuple(sorted(cycle))
                if key not in seen:
                    seen.add(key)
                    cycles.append(cycle)
            elif nxt not in state and nxt in graph:
                walk(nxt, stack)
        stack.pop()
        state[node] = 1

    for node in sorted(graph):
        if node not in state:
            walk(node, [])
    return cycles


def queue_spec_findings(repo_root: Path, config: Dict[str, Dict[str, object]],
                        number: int) -> Tuple[List[SpecFinding], List[int]]:
    """``(findings, unspecced)`` for every spec on queue *number*.

    Runs in the window `/aide-spec-queue` creates and currently leaves
    unguarded: N specs authored on one branch before any is built, where every
    cross-item conflict is both possible and cheap to fix. The invariant it
    enforces is the one a consumer's post-mortem arrived at — *predicting the
    one collision a spec happens to name is not the same as proving no sibling
    assertion depends on state this item's authorised edit changes.*
    """
    ddir = docs_dir(repo_root, config)
    qdir = ddir / "queue"
    qpath = queue_path(qdir, number)
    if qpath is None:
        return ([SpecFinding("error", "missing-queue", (),
                             f"no {queue_name(number)} file under "
                             f"{_rel_display(qdir, repo_root)}")],
                [])

    numbers = queue_item_numbers(qpath.read_text(encoding=_ENCODING))
    idir = ddir / "items"
    findings: List[SpecFinding] = []
    unspecced: List[int] = []
    declared: Dict[int, AuthorisedPaths] = {}

    # A finding against a SPENT item — merged (✅) or excluded (❌) — is an
    # error no later item can clear: the spec is a record nobody may edit, a
    # merged May-change claim can neither be harmed by a later writer nor harm
    # one, and an excluded item is never offered. Such findings are reported
    # for the rest of the queue's life, which teaches a reader to skim the run
    # where one is real — so spent items are discounted below, on both sides
    # of every comparison. Deferred (⏸️) items are NOT spent: their claims are
    # dormant, not dead, and a conflict with one is worth surfacing while
    # re-planning is still cheap. A 📋 item of a withdrawn stage is spent as
    # an excluded one is (issue #393): `claim` never offers it, and its
    # owner's way back is the drop, so a conflict with it is never built.
    ppath = ddir / "progress.md"
    plines = (ppath.read_text(encoding=_ENCODING).splitlines()
              if ppath.is_file() else [])
    item_status = _parse_item_status(plines)[2]
    withdrawn = withdrawn_stage_items(plines)
    spent = {n for n in numbers
             if item_status.get(n, "planned") in ("complete", "excluded")
             or (item_status.get(n, "planned") == "planned"
                 and n in withdrawn)}

    for num in numbers:
        specs = item_spec_paths(idir, num)
        if not specs:
            # Normal mid-queue state, not a conflict: /aide-spec-queue exists to
            # fill these. Counted and reported, never silently dropped.
            unspecced.append(num)
            continue
        parsed = parse_authorised_paths(specs[0].read_text(encoding=_ENCODING))
        rel = _rel_display(specs[0], repo_root)
        if declares_nothing(parsed):
            if num not in spent:
                # A spent spec with no scope section merged (or was dropped)
                # regardless; the remedy the message names is no longer
                # available, so the warning would be pure unclearable noise.
                findings.append(SpecFinding(
                    "warning", "undeclared-scope", (num,),
                    f"item {num:03d} ({rel}) declares no '## Authorised paths' — its "
                    f"scope cannot be compared with its siblings'. Add the section "
                    f"(conventions.md §1); until then this item needs a human scope "
                    f"review, and `aide scope` cannot check it either"))
            continue
        declared[num] = parsed

    # Read once, used twice: the declared ordering exempts pinned-state pairs
    # below, and the same edges are the cycle graph further down. Reading each
    # spec's Dependencies section twice would be the only alternative.
    deps_by_item = {num: _item_dependencies(repo_root, config, num)
                    for num in numbers if num not in unspecced}
    # An item is built after everything it declares a dependency on, and after
    # what those declare in turn — but only along edges that still ORDER the
    # two items. A dependency `aide claim` no longer waits for does not hold
    # its dependent back: a ⏸️ deferred blocker — or a ❌ or withdrawn-stage 📋
    # one (`still_blocks`) — is skipped by `_pick_item`, so the dependent is
    # claimable today and would pin a tree the blocker has not touched yet.
    # Filtering the edges rather than the pairs also settles the transitive
    # case, where the link that fails to hold is an intermediate: `b → c (⏸️)
    # → a` leaves b free to build before a.
    ordering_edges = {num: [d for d in deps
                            if still_blocks(d, item_status, withdrawn)]
                      for num, deps in deps_by_item.items()}
    built_after = _built_after(ordering_edges)

    # The loop bookkeeping every item writes anyway (`aide scope` authorises
    # these without them being listed). Specs often list them redundantly, and
    # two items "conflicting" over progress.md is not a conflict — it is the
    # claim protocol working. Excluded from the overlap check, never from the
    # pinned-state check: pinning progress.md would be a real assertion.
    ddir_rel = _rel_display(ddir, repo_root)
    bookkeeping = set(_always_authorised_paths(ddir_rel))

    ordered = sorted(n for n in declared if n not in spent)
    for i, a in enumerate(ordered):
        for b in ordered[i + 1:]:
            # Row 1 — two items claim edit rights on the same file.
            for pa in declared[a].may_change:
                if pa in bookkeeping:
                    continue
                for pb in declared[b].may_change:
                    if patterns_overlap(pa, pb):
                        findings.append(SpecFinding(
                            "warning", "may-change-overlap", (a, b),
                            f"items {a:03d} and {b:03d} both claim '{pa}'"
                            + (f" / '{pb}'" if pa != pb else "")
                            + " under May change — whichever builds second "
                              "inherits the first's edits; confirm that is intended"))
        # Rows 2+3 — one item may change what another pins. Under the
        # `## Authorised paths` vocabulary these are one check: an "Asserts
        # against" entry covers a byte-hash pin and a live recomputation alike,
        # which is the point — the live-recomputed case is the one a survey
        # hunting fragile-looking hashes missed.
        for b in ordered:
            if a == b:
                continue
            if a in built_after.get(b, ()):
                # Item a still holds item b back — b declares a dependency on
                # it, directly or through a chain, along links that all still
                # order (`ordering_edges`). So b is authored and built against
                # a tree that already holds a's edit: a landing cannot break a
                # pin b writes afterwards, by construction. This is the whole shape
                # of a queue-end item (`Validate stage N`) — it exists to pin the artifacts
                # its stage's items produce, and it names them as dependencies
                # — which made the error fire against every such item, with
                # neither remedy the message offers available: widening the pin
                # drops what the item exists to observe, and narrowing the
                # earlier edits removes the stage's whole point. A pair with no
                # declared dependency keeps the error: an undeclared ordering
                # is exactly what this check exists to find.
                continue
            for pa in declared[a].may_change:
                for pb in declared[b].asserts_against:
                    if patterns_overlap(pa, pb):
                        findings.append(SpecFinding(
                            "error", "changes-pinned-state", (a, b),
                            f"item {a:03d} may change '{pa}', which item {b:03d} "
                            f"pins as '{pb}' under Asserts against — item {b:03d}'s "
                            f"assertion breaks when item {a:03d} lands. Decide now "
                            f"which side is wrong: widen the pin, narrow the edit, "
                            f"or — if item {b:03d} is meant to be built after item "
                            f"{a:03d} and to pin what it produced — say so under "
                            f"item {b:03d}'s '## Dependencies', which both orders "
                            f"the queue and retires this finding"))

    # Row 5 — the dependency graph. A cycle deadlocks `aide claim`: every item
    # in it is blocked by another in it, so the queue silently stops producing
    # work rather than failing. The graph holds only items that can still
    # block a claim — the same reading `_pick_item` gives (`still_blocks`): a
    # complete, excluded or deferred dependency does not block, nor a 📋 one
    # of a withdrawn stage, and such an item is never offered, so no cycle
    # through one can deadlock (a cycle whose members all merged has PROVED
    # its order was satisfiable). The typo
    # pass below shares the filter: a mistyped dependency in a spent or
    # deferred item's spec blocks nothing today, and the warning about it
    # would be unclearable.
    graph = {num: deps for num, deps in deps_by_item.items()
             if still_blocks(num, item_status, withdrawn)}
    for cycle in _dependency_cycles(graph):
        chain = " → ".join(f"{n:03d}" for n in cycle + [cycle[0]])
        findings.append(SpecFinding(
            "error", "dependency-cycle", tuple(cycle),
            f"dependency cycle {chain} — every item in it is blocked by another "
            f"in it, so `aide claim` will never offer any of them"))

    known = set(numbers)
    for num, deps in graph.items():
        for dep in deps:
            if dep in known:
                continue
            has_spec = bool(item_spec_paths(idir, dep))
            in_a_queue = any(dep in queue_item_numbers(p.read_text(encoding=_ENCODING))
                             for p in iter_queue_paths(ddir / "queue"))
            if not has_spec and not in_a_queue:
                findings.append(SpecFinding(
                    "warning", "unknown-dependency", (num, dep),
                    f"item {num:03d} depends on item {dep:03d}, which has no spec "
                    f"and appears in no queue — a typo here blocks the item forever"))

    return findings, unspecced


# --------------------------------------------------------------------------- #
# The queue-end item — does this queue need one? (§1 → queue-NNN.md, #333)
# --------------------------------------------------------------------------- #
#: An AC's *(closes Stage N criterion M)* annotation (§1 → items.md). A list
#: (`criteria 2, 3`) reads as one pair per number, so an author folding two
#: annotations into one is not read as closing only the first.
_CLOSES_CRITERION_RE = re.compile(
    r"\bcloses\s+Stage\s+0*(\d+)\s+criteri(?:on|a)\s+"
    r"(\d+(?:\s*(?:,|&|\band\b)\s*\d+)*)", re.IGNORECASE)
#: The item template's optional section for an item introducing an
#: environment-gated capability (§1 → environment-gated capabilities).
_ENV_DEPS_HEADING_RE = re.compile(
    r"^##\s+Environment\s*/\s*Hardware Dependencies\b", re.MULTILINE | re.IGNORECASE)


def spec_closed_criteria(text: str) -> Set[Tuple[int, int]]:
    """``(stage, criterion)`` pairs the spec's Acceptance Criteria annotate as
    closed — the only mapping from an AC to a stage criterion (§1 → items.md);
    an AC that names none closes none."""
    out: Set[Tuple[int, int]] = set()
    for m in _CLOSES_CRITERION_RE.finditer(_section_text(text, _AC_HEADING_RE)):
        for n in re.findall(r"\d+", m.group(2)):
            out.add((int(m.group(1)), int(n)))
    return out


def queue_end_stages(title: Optional[str]) -> Optional[List[int]]:
    """The stages a queue-end item's *title* names, or None for any other item.

    The stage variant — the only one today — is titled `Validate stage N:
    <stage title>`, the same test the ledger's `validate-stage` kind reads, so
    the two cannot disagree about which item is one. The stage numbers are
    read as an Introduced by cell's are: the first `Stage N` run.
    """
    if not title or not _VALIDATE_STAGE_TITLE_RE.match(title):
        return None
    return _introducing_stages(title)


def queue_item_title(repo_root: Path, config, titles: Dict[int, str],
                     number: int) -> Optional[str]:
    """Item *number*'s title: the queue's `### Item NNN:` line, else its spec's.

    The one title a queue-end reading goes by, so `aide claim`'s hold and
    `aide check --queue`'s warnings cannot disagree about which item is one.
    """
    return titles.get(number) or _spec_stage_and_title(repo_root, config, number)[1]


def queue_end_holds(repo_root: Path, config, queue_text: str,
                    item_status: Dict[int, str],
                    withdrawn: Collection[int] = ()) -> Dict[int, List[int]]:
    """Each queue-end item the queue lists, with the queue-mates holding it.

    A queue-end item runs after the rest of its queue whatever order the file
    lists it in (issue #347): it is held by every other item the queue lists
    that is not itself a queue-end item and whose status still blocks a claim
    (📋, 🚧, 🔍). Read from the queue file and progress.md alone — an item with
    no spec is held as surely as one with. Queue-end items never hold each
    other, since a queue ending on two would otherwise never start either, and
    an item whose spec depends on the queue-end item — directly or through
    other queue-mates' `## Dependencies` — never holds it, since each would
    then wait on the other for ever.

    Nor does a 📋 item in *withdrawn* (`withdrawn_stage_items`) hold it: claim
    never offers one, so a queue-end item waiting on it waited for ever and an
    unattended run stalled (issue #389). A 🚧 or 🔍 item of a withdrawn stage
    still holds it — live work until its owner drops it (§2).
    """
    titles = _queue_titles(queue_text)
    order = queue_item_numbers(queue_text)
    ends = [n for n in order
            if queue_end_stages(queue_item_title(repo_root, config, titles, n))
            is not None]
    rest = [n for n in order if n not in ends
            and still_blocks(n, item_status, withdrawn)]
    deps = {n: set(_item_dependencies(repo_root, config, n)) for n in rest}
    holds: Dict[int, List[int]] = {}
    for end in ends:
        after: Set[int] = {end}
        grew = True
        while grew:
            grew = False
            for n in rest:
                if n not in after and deps[n] & after:
                    after.add(n)
                    grew = True
        holds[end] = [n for n in rest if n not in after]
    return holds


def queue_closed_stages(lines: List[str], qdir: Path, number: int) -> List[str]:
    """The stages queue *number* closes, in progress.md order.

    Stage N is closed by the queue when an item the queue lists is referenced
    by a stage N deliverable, and every stage N deliverable that is 📋, 🚧 or
    🔍 names only items listed on this queue or an earlier one. A bullet in
    one of those states with no item reference is unqueued work, so its stage
    is not closed. ✅ and ❌ bullets are done with, and a ⏸️ bullet never holds
    closure, on any queue and with or without a reference: deferred work is by
    definition not what the stage's closing queue builds, and a bullet that
    held closure would hold it until someone resumed it — for ever, if nobody
    does. For the same reason a ⏸️ bullet is not what makes the queue touch
    the stage: a queue whose only work in it is deferred closes nothing.
    Read from the documents alone.
    """
    listed: Dict[int, int] = {}
    for path in iter_queue_paths(qdir):
        q = queue_number(path)
        if q is None:
            continue
        for n in queue_item_numbers(path.read_text(encoding=_ENCODING)):
            listed[n] = min(q, listed.get(n, q))
    out: List[str] = []
    for start, end, num in stage_sections(lines):
        stage = str(int(num))
        if stage in out:
            continue
        section = [ln for ln in lines[start:end] if not _CHECKBOX_RE.match(ln)]
        touches, closes = False, True
        for first, last in _deliverable_bullet_spans(section):
            status = ICON_TO_STATUS[_BULLET_RE.match(section[first]).group("icon")]
            refs = _bullet_marker_item_numbers(section[last])
            if status != "deferred" and any(listed.get(r) == number for r in refs):
                touches = True
            if status in ("complete", "excluded", "deferred"):
                continue
            closes = closes and bool(refs) and all(
                listed.get(r) is not None and listed[r] <= number for r in refs)
        if touches and closes:
            out.append(stage)
    return out


def queue_end_findings(repo_root: Path, config: Dict[str, Dict[str, object]],
                       number: int) -> List[SpecFinding]:
    """Whether queue *number* needs a queue-end item, reported both ways.

    A stage the queue closes needs one when it has an unticked acceptance box
    no item spec annotates, a ❓ Unverified capability row it introduced, or an
    item its bullets reference, not ❌, whose spec declares an
    environment-gated capability the table has no row for. A
    queue-end item's own spec, and an excluded item's, annotate nothing here —
    the first would count the item as the reason it is not needed. The need is
    met by a queue-end item naming the stage in the queue's trailing run of
    them, or by one naming it that is still open anywhere on the queue. The
    mirror warning names a planned queue-end item with nothing to do, and a
    third names an open queue-end item listed ahead of open work that is not
    one (issue #347). A queue whose items are all spent gets none of them:
    nothing is left to plan.
    """
    ddir = docs_dir(repo_root, config)
    qdir, idir = ddir / "queue", ddir / "items"
    qpath = queue_path(qdir, number)
    ppath = ddir / "progress.md"
    if qpath is None or not ppath.is_file():
        return []
    qtext = qpath.read_text(encoding=_ENCODING)
    order = queue_item_numbers(qtext)
    lines = ppath.read_text(encoding=_ENCODING).splitlines()
    item_status = _parse_item_status(lines)[2]
    withdrawn = withdrawn_stage_items(lines)

    # ⏸️ is settled here as ✅ and ❌ are: `queue_is_open` does not count a
    # deferred item as open, and nobody plans or drops one until it resumes.
    # Nor a 📋 item of a withdrawn stage, which `claim` never offers (issue
    # #393): spent is exactly not open (`still_blocks`).
    def spent(n: int) -> bool:
        return not still_blocks(n, item_status, withdrawn)

    if all(spent(n) for n in order):
        return []

    titles = _queue_titles(qtext)

    def title_of(n: int) -> Optional[str]:
        return queue_item_title(repo_root, config, titles, n)

    end_stages = {n: queue_end_stages(title_of(n)) for n in order}
    # The need is met by a queue-end item that will run last: one in the
    # queue's trailing run of them, or one still open anywhere on it, since
    # `aide claim` holds an open one until the rest of the queue has left the
    # way (issue #347) — where it sits is `queue-end-not-last`'s business. A
    # spent one listed before open work ran before that work, so it meets
    # nothing.
    met: Set[int] = set()
    for n in reversed(order):
        if end_stages[n] is None:
            break
        met.update(end_stages[n])
    for n in order:
        if end_stages[n] and not spent(n):
            met.update(end_stages[n])

    annotated: Set[Tuple[int, int]] = set()
    specced: Set[int] = set()
    env_items: Set[int] = set()
    for path in sorted(idir.glob("*.md")) if idir.is_dir() else []:
        n = item_spec_number(path)
        if n is None:
            continue
        specced.add(n)
        if item_status.get(n) == "excluded" or queue_end_stages(title_of(n)) is not None:
            continue
        text = path.read_text(encoding=_ENCODING)
        annotated |= spec_closed_criteria(text)
        # ⏸️ skipped like ❌: a deferred capability is not built by this stage.
        if item_status.get(n) != "deferred" and _ENV_DEPS_HEADING_RE.search(text):
            env_items.add(n)
    capabilities = gated_capabilities(lines)

    findings: List[SpecFinding] = []
    reasons_by_stage: Dict[int, List[str]] = {}
    for stage in queue_closed_stages(lines, qdir, number):
        s = int(stage)
        start, end, _ = stage_section(lines, stage)
        boxes = acceptance_boxes(lines, start, end)
        unannotated = [i for i, at in enumerate(boxes, start=1)
                       if _CHECKBOX_RE.match(lines[at]).group("mark") == " "
                       and (s, i) not in annotated]
        reasons: List[str] = []
        if unannotated:
            waiting = [n for n in order
                       if n not in specced and end_stages[n] is None
                       and not spent(n)]
            reasons.append(
                f"acceptance criteri{'on' if len(unannotated) == 1 else 'a'} "
                f"{', '.join(map(str, unannotated))} of stage {s}, which no item "
                f"spec annotates *(closes Stage {s} criterion M)*"
                + (f" ({len(waiting)} item(s) on the queue not yet specced)"
                   if waiting else ""))
        rows = [c.text for c in capabilities
                if c.kind == "unverified" and s in c.stages]
        if rows:
            reasons.append("❓ Unverified capability row(s) stage "
                           f"{s} introduced: " + ", ".join(f"'{r}'" for r in rows))
        # An item declaring a gated capability is a need until the table has
        # a row for it, whatever the item's status but ❌ or ⏸️: a merged item
        # whose row was never written is exactly the gap the queue-end item
        # closes. A row whose Introduced by cell references the item covers
        # it, whatever stage the cell names. A row naming this stage and no
        # item covers one item and no more — one row is one capability — so
        # such rows are counted off against the items no referencing row
        # covers, lowest number first, and the rest are reported. Its status
        # is (b)'s business, not this.
        referenced = {n for c in capabilities for n in c.items}
        stage_only = sum(1 for c in capabilities if s in c.stages and not c.items)
        stage_items = set(stage_item_numbers(lines, stage))
        envs = sorted(n for n in env_items & stage_items
                      if n not in referenced)[stage_only:]
        if envs:
            reasons.append("item(s) " + ", ".join(f"{n:03d}" for n in envs)
                           + " declaring an environment-gated capability "
                             "(## Environment / Hardware Dependencies) with no "
                             "capability row")
        reasons_by_stage[s] = reasons
        if reasons and s not in met:
            findings.append(SpecFinding(
                "warning", "queue-end-needed", (number,),
                f"queue {number:03d} closes stage {s} and needs a queue-end "
                f"item: " + "; ".join(reasons) + f". End the queue with "
                f"`Validate stage {s}: <stage title>` (§1 → queue-NNN.md)"))

    # A queue-end item a fix round reopened (issue #332) was needed once and
    # is back for a fix: its stage's boxes are ticked by its own first run,
    # so it would read as idle and be dropped mid-round.
    back = {r.item for r in reopened_items(lines) if r.status in _OPEN_STATUSES}
    for n in order:
        named = end_stages[n]
        if named is None or spent(n) or n in back:
            continue
        if not named:
            findings.append(SpecFinding(
                "warning", "queue-end-idle", (n,),
                f"item {n:03d} is titled as a queue-end item but names no "
                f"stage — title it `Validate stage N: <stage title>`"))
        for s in named:
            if s not in reasons_by_stage:
                why = f"queue {number:03d} does not close stage {s}"
            elif not reasons_by_stage[s]:
                why = (f"stage {s} has nothing left for it: every unticked "
                       f"acceptance criterion is annotated by an item's AC, no "
                       f"capability row it introduced is ❓ Unverified, and "
                       f"every item declaring an environment-gated capability "
                       f"has a row")
            else:
                continue
            findings.append(SpecFinding(
                "warning", "queue-end-idle", (n,),
                f"item {n:03d} is a queue-end item for stage {s}, but {why} — "
                f"drop it before it is claimed"))

    # Out of place (issue #347): an open queue-end item listed ahead of open
    # work that is not one. `aide claim` holds it until that work has left the
    # way, so it still runs last; the warning keeps the file saying so. A
    # settled record either side (✅, ❌, ⏸️) is history, not a plan (#338),
    # and an item whose dependencies lead back to it belongs after it.
    holds = queue_end_holds(repo_root, config, qtext, item_status, withdrawn)
    for i, n in enumerate(order):
        if end_stages[n] is None or spent(n):
            continue
        after = [m for m in order[i + 1:] if m in holds.get(n, ())]
        if after:
            findings.append(SpecFinding(
                "warning", "queue-end-not-last", (n, *after),
                f"item {n:03d} is a queue-end item, but queue {number:03d} "
                f"lists open item(s) "
                + ", ".join(f"{m:03d}" for m in after)
                + " after it — move it to the end of the queue; `aide claim` "
                f"holds it until they are ✅, ❌ or ⏸️ either way "
                f"(§1 → queue-NNN.md)"))
    return findings


def _write_findings_report(path: Path, number: int,
                           findings: List[SpecFinding],
                           unspecced: List[int]) -> None:
    """Write the machine-readable report — the seam a reviewer pass consumes as
    its worklist rather than re-deriving what this check already decided."""
    payload = {
        "queue": number,
        "unspecced_items": unspecced,
        "findings": [
            {"severity": f.severity, "kind": f.kind,
             "items": list(f.items), "message": f.message}
            for f in findings
        ],
    }
    path.parent.mkdir(parents=True, exist_ok=True)
    # Plain utf-8, NOT `_ENCODING`: that is utf-8-sig, which writes a BOM. A BOM
    # is right for the markdown documents (Windows editors add one and the
    # parsers must tolerate it) and wrong here — `json.loads` rejects a leading
    # BOM outright, so the seam would be unreadable by the very consumer it
    # exists for.
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n",
                    encoding="utf-8")


def cmd_check(args: argparse.Namespace) -> int:
    """The consistency gate over the document set — and two writes.

    One is asked for by flag: ``--report PATH`` writes the cross-spec findings
    file for `spec-reviewer`. The other is ``ensure_insights_inbox``: a
    ``docs_dir`` that exists but has no ``insights.md`` gets one, byte-exact
    from the template, committed where git allows, and the run says so in a
    ``notice:``. It is the engine keeping §1's promise that capture is a plain
    append to a file that exists, placed in the verb every consumer is told to
    run before its first unattended run. The exit code never depends on it:
    the creation cannot fail a run — a commit that git refuses, or a ``git``
    that cannot be run, is a sentence in the notice, not an error — and a
    document set whose inbox already exists is reported exactly as before.
    """
    queue = getattr(args, "queue", None)
    if getattr(args, "report", None) and queue is None:
        # Silently ignoring it would be worse than refusing: the caller asked
        # for a file that would never appear, and only the missing file would
        # ever say so.
        print("aide check: --report needs --queue; there are no cross-spec "
              "findings to report without one", file=sys.stderr)
        return 2

    global _GIT_OPTIONAL
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    ddir = docs_dir(repo_root, config)
    # A git that is not there fails no document (issue #352): every reading
    # that needs it comes back empty, and one warning says so — "OK" alone
    # would claim branches and history were checked.
    # The same for a git that runs and refuses the repository (a
    # `safe.directory` check): the refusal's own words are the warning.
    git_problem = _git_unavailable(repo_root)
    if git_problem is None:
        try:
            in_repository(repo_root)
        except MissingTool as exc:
            git_problem = str(exc)
    # What the committed configuration needs of this machine and it lacks,
    # decided offline (issue #354). Asked before git turns optional below,
    # so a repository git refuses is git's own words here too. Only where
    # an aide.toml is there — the check also lints repos with no AIDE
    # configuration, whose defaults nobody committed — and only on a plain
    # run: `--queue` is a planner's or reviewer's judgement of documents,
    # and a machine error there would invite the edit of `[git] mode` or
    # `test_command` §4 forbids. Prefixed, so no reader takes one for a
    # document error.
    machine_errors = ([f"{MACHINE_PREFIX}{e}" for e in
                       dependency_errors(repo_root, config)]
                      if queue is None and (repo_root / "aide.toml").is_file()
                      else [])
    _GIT_OPTIONAL = git_problem is not None
    try:
        # Before the checks, so the file they then shape-check is the one that
        # exists — a run that created the inbox and warned about its absence in
        # the same breath would be reporting on two different repositories.
        ensure_insights_inbox(repo_root, config, verb="check")
        errors, warnings = run_checks(repo_root, config)
        errors.extend(machine_errors)
        if git_problem is not None:
            warnings.append(f"{git_problem}, so nothing that reads git was "
                            f"checked — stale claim branches, insight citations' "
                            f"history, and the commit of a created inbox")

        if not ddir.exists() and queue is None:
            # A notice, not a warning: nothing is wrong, but the reader must not
            # read "OK" as "the documents were checked and are fine".
            #
            # Only on a non-`--queue` run. `--queue` sends `queue_spec_findings`
            # looking for a queue file under the same absent directory, so it runs
            # and errors — and "only the repo-agnostic checks ran" would be false
            # next to that error. The notice exists to stop a *pass* being
            # over-read; a run that fails needs no such guard.
            print(f"notice: no {_rel_display(ddir, repo_root)}/ — this repo has no "
                  f"AIDE document set, so only the repo-agnostic checks ran")

        if queue is not None:
            findings, unspecced = queue_spec_findings(repo_root, config, queue)
            # Not a cross-spec conflict, so not `queue_spec_findings`' — but the
            # same run the planner makes after writing a queue, and the same
            # worklist the spec-reviewer reads once the specs exist (#333).
            findings += queue_end_findings(repo_root, config, queue)
            for f in findings:
                (errors if f.severity == "error" else warnings).append(f.message)
            if unspecced:
                listed = ", ".join(f"{n:03d}" for n in unspecced)
                print(f"aide check: queue {queue:03d} — {len(unspecced)} item(s) "
                      f"not yet specced, so not compared: {listed}")
            report = getattr(args, "report", None)
            if report:
                _write_findings_report(Path(report), queue, findings, unspecced)
                print(f"aide check: wrote {report}")

        for w in warnings:
            print(f"warning: {w}")
        for e in errors:
            print(f"error: {e}")
        if errors:
            print(f"aide check: FAIL ({len(errors)} error(s), {len(warnings)} warning(s))")
            return 1
        print(f"aide check: OK ({len(warnings)} warning(s))")
        return 0
    finally:
        # Reset here, not only by the next `main()`: a caller that runs the
        # check in-process and then another verb must not inherit it.
        _GIT_OPTIONAL = False


def set_gate_status(text: str, index: int, kind: str,
                    note: Optional[str] = None, today: Optional[str] = None) -> str:
    """Resolve the *index*-th (1-based) row of the ``## Human gates`` table.

    Writes the decision and the date into the Status cell, and *note* into the
    last cell. Raises ``ValueError`` for a missing table or an out-of-range
    index — a typo must not pass as a silent no-op, which is exactly how a
    hand-edited gate went wrong before there was a verb for it.
    """
    lines = text.splitlines()
    gates = human_gates(lines)
    if not gates:
        raise ValueError("no '## Human gates' table in progress.md")
    if not 1 <= index <= len(gates):
        raise ValueError(f"there are {len(gates)} human gate(s); {index} is out of range")
    gate = gates[index - 1]
    if note and ("|" in note or "\n" in note or "\r" in note):
        raise ValueError(
            "the note may not contain '|' or a line break — either breaks the "
            "row's shape, and a gate row the parser cannot read stops being a "
            "gate: `aide check` fails and `aide claim` holds every item until "
            "someone repairs it")
    icon = {"approved": "✅ Approved", "declined": "❌ Declined"}[kind]
    import datetime as _dt
    stamp = today or _dt.date.today().isoformat()
    i = gate.lineno - 1
    cells = _split_row(lines[i])
    cells[2] = f"{icon} ({stamp})"
    if note:
        cells[3] = note
    lines[i] = "| " + " | ".join(cells) + " |"
    return "\n".join(lines) + ("\n" if text.endswith("\n") else "")


#: The header a `## Human gates` table is written with when a verb has to
#: create one — the template's, cell for cell (§1 → human gates).
_GATES_TABLE_HEAD = ("| Gate | Blocks | Status | Decision / evidence |",
                     "|------|--------|--------|---------------------|")


def add_gate_rows(text: str, rows: List[Tuple[str, str]]) -> str:
    """Append one ``⏳ Awaiting`` row per ``(Gate cell, Blocks cell)`` in *rows*.

    Into the ``## Human gates`` table, after its last row; under the heading
    when it has no table yet; and as a new section at the end of the file
    when the project deleted the optional one. The four cells are the §1
    shape, so the row is a gate the moment it is written.
    """
    lines = text.splitlines()
    new = [f"| {gate} | {blocks} | ⏳ Awaiting | — |" for gate, blocks in rows]
    head = next((i for i, line in enumerate(lines)
                 if _GATES_HEADING_RE.match(line)), None)
    if head is None:
        while lines and not lines[-1].strip():
            lines.pop()
        lines += ["", "## Human gates", "", *_GATES_TABLE_HEAD, *new]
    else:
        end = next((j for j in range(head + 1, len(lines))
                    if _ANY_HEADER_RE.match(lines[j])), len(lines))
        pipes = [j for j in range(head + 1, end)
                 if lines[j].strip().startswith("|")]
        if pipes:
            at = pipes[-1] + 1
            lines[at:at] = new
        else:
            at = end
            while at > head + 1 and lines[at - 1].strip() in ("", "---"):
                at -= 1
            lines[at:at] = ["", *_GATES_TABLE_HEAD, *new]
    return "\n".join(lines) + "\n"


def item_ranges(numbers: List[int]) -> str:
    """``231–240`` / ``005, 007–009`` — item numbers as a Blocks cell writes them.

    Runs never span more than the reader expands (``_ITEM_RANGE_MAX_SPAN``),
    so the cell always reads back as exactly *numbers*.
    """
    nums = sorted(set(numbers))
    parts: List[str] = []
    i = 0
    while i < len(nums):
        j = i
        while (j + 1 < len(nums) and nums[j + 1] == nums[j] + 1
               and nums[j + 1] - nums[i] <= _ITEM_RANGE_MAX_SPAN):
            j += 1
        parts.append(f"{nums[i]:03d}" if i == j else f"{nums[i]:03d}–{nums[j]:03d}")
        i = j + 1
    return ", ".join(parts)


def queue_opened_stages(lines: List[str], qdir: Path, first: int,
                        items: List[int]) -> List[str]:
    """The stages the queues from *first* on, listing *items*, open.

    A queue opens stage N when one of its items is referenced by a stage N
    deliverable in progress.md and no item stage N's deliverables reference is
    listed in a queue file numbered below *first*. Read from the documents
    alone, so the same tree always gives the same answer.
    """
    earlier: Set[int] = set()
    for path in iter_queue_paths(qdir):
        n = queue_number(path)
        if n is not None and n < first:
            earlier.update(queue_item_numbers(path.read_text(encoding=_ENCODING)))
    wanted = set(items)
    out: List[str] = []
    for _, _, num in stage_sections(lines):
        stage = str(int(num))
        if stage in out:
            continue
        in_stage = set(stage_item_numbers(lines, num))
        if in_stage & wanted and not in_stage & earlier:
            out.append(stage)
    return out


def cmd_gate(args: argparse.Namespace) -> int:
    """List or resolve the human gates in progress.md.

    Resolving a gate is a **person's** act. No agent may run `approve` or
    `decline`: a gate exists precisely because the decision is not derivable
    from the work, so an agent resolving one destroys the only thing it was
    protecting.
    """
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    ppath = docs_dir(repo_root, config) / "progress.md"
    if not ppath.is_file():
        print(f"aide gate: missing {ppath}", file=sys.stderr)
        return 2
    text = ppath.read_text(encoding=_ENCODING)
    gates = human_gates(text.splitlines())
    unreadable = unreadable_gate_rows(text.splitlines())

    if args.action == "list":
        if not gates and not unreadable:
            print("aide gate: no '## Human gates' table (nothing gated)")
            return 0
        for n, (g, gid) in enumerate(zip(gates, gate_ids(gates)), start=1):
            reach = g.reach
            mark = {"approved": "✅", "declined": "❌", "awaiting": "⏳"}.get(g.kind, "⚠")
            print(f"  {n}. {mark} {gid or '(no ID — empty Gate cell)'} "
                  f"{g.text} — blocks {reach}")
        # Unnumbered: `approve <n>` counts readable gates only, and a row the
        # parser cannot read is not one a verb should write into.
        for lineno, problem in unreadable:
            print(f"  ⚠ progress.md:{lineno}: a row that {problem} — not a "
                  f"gate, and holds every item until it is fixed")
        outstanding = len(blocking_gates(text.splitlines()))
        print(f"aide gate: {len(gates)} gate(s), {outstanding} still blocking"
              + (f", {len(unreadable)} unreadable row(s) holding everything"
                 if unreadable else ""))
        return 0

    if args.number is None:
        print(f"aide gate: '{args.action}' needs a gate number or ID — see "
              f"`aide gate list`", file=sys.stderr)
        return 2
    kind = "approved" if args.action == "approve" else "declined"
    try:
        index = gate_index_for_ref(args.number, gates)
        updated = set_gate_status(text, index, kind, args.note)
    except ValueError as exc:
        print(f"aide gate: {exc}", file=sys.stderr)
        return 2
    # NOT _ENCODING: "utf-8-sig" *strips* a BOM on read but *writes* one, so
    # passing it here made every gate decision prepend U+FEFF to progress.md —
    # manufacturing the exact hazard that constant exists to absorb. Every
    # other writer in this module already writes plain "utf-8"; this was the
    # one outlier. Read tolerantly, write clean.
    before = _snapshot([ppath])
    ppath.write_text(updated, encoding="utf-8")
    # Named by its ID, which a reader of the log can still find after a merge
    # renumbers the rows; an empty Gate cell has none, so falls back to the
    # position it was resolved at.
    handle = gate_ids(gates)[index - 1] or f"gate {index}"
    print(f"{handle}: {kind}")
    if _commits_here(args.no_commit, repo_root, before):
        # A decision left written but uncommitted reads as resolved to a
        # re-run, which would never commit it (issue #309).
        return _commit_or_restore(repo_root, config, f"aide gate {args.action}",
                                  "the decision", f"docs: human {handle} {kind}",
                                  [_progress_rel(config)], before)
    return 0


#: What `aide progress set` accepts, and the tracked status each records.
#: `done` stays the word for ✅ — a consumer's muscle memory and every existing
#: runbook use it — and `in-review` is additive.
_SET_STATUS_MAP = {"in-progress": "in-progress", "in-review": "in-review",
                   "done": "complete"}


def _report_bullet_splits(number: int, lines: List[str],
                          splits: List[BulletSplit]) -> None:
    """Print the copies a flip's split wrote, as the chore they are.

    The split is the engine's edit, made with no author present, and it
    produces N bullets carrying one bullet's prose — text that described the
    shared deliverable and now stands, unchanged, under each item alone. The
    engine cannot write the right words; it can refuse to be silent about the
    wrong ones (issue #169). ``lines`` is the text *after* the flip, so the
    copies print with the icons they ended up with.
    """
    for split in sorted(splits, key=lambda s: s.copies[0][1]):
        print(f"item {number:03d}: split the shared bullet {split.marker} into "
              f"one bullet per item. Every copy still carries the SHARED "
              f"prose — reword each with `aide progress reword --item NNN "
              f"--text …` to describe its own item's work, or `aide check` "
              f"keeps reporting them as identical:")
        for _, lineno in split.copies:
            print(f"  progress.md:{lineno}: {lines[lineno - 1].strip()}")


def cmd_progress(args: argparse.Namespace) -> int:
    #: The acceptance verbs, in the order §1 describes them: make an
    #: attestation, correct its evidence, withdraw it, or reword a criterion
    #: nobody has attested yet. `reopen` is `retract` one level up — an item,
    #: not a box (issue #271).
    #:
    #: NUMBER is optional to argparse only because `reword --item` takes none
    #: (issue #320); every other action still requires it, and says so here.
    if (isinstance(args.number, str) and args.stage is None
            and args.deliverable is None):
        # `_progress_number` passes a non-number through only so the
        # positional-free `set --stage N --deliverable K deferred` can take
        # its status there; anywhere else it is refused by the subparser's
        # own error — usage, `error:` and exit 2 — as `type=int` refused it.
        args.progress_parser.error(
            f"argument number: invalid int value: '{args.number}'")
    if args.item is not None and args.action != "reword":
        print(f"aide progress {args.action}: --item belongs to `reword` alone "
              f"(reword --item NNN --text TEXT)", file=sys.stderr)
        return 2
    if args.stage is not None or args.deliverable is not None:
        return _cmd_progress_defer_deliverable(args)
    if args.number is None and args.action != "reword":
        print(f"usage: aide progress {args.action} NUMBER … "
              f"(see aide progress -h)", file=sys.stderr)
        return 2
    if args.action == "accept":
        return _cmd_progress_accept(args)
    if args.action == "amend":
        return _cmd_progress_amend(args)
    if args.action == "retract":
        return _cmd_progress_retract(args)
    if args.action == "reword":
        return _cmd_progress_reword(args)
    if args.action == "reopen":
        return _cmd_progress_reopen(args)
    if args.action != "set":
        print("usage: aide progress set NNN <in-progress|in-review|done> | "
              "set NNN <deferred|resumed|dropped|restored> --reason TEXT | "
              "reopen NNN --reason TEXT | accept|amend|retract|reword STAGE "
              "(see aide progress -h)", file=sys.stderr)
        return 2
    if args.status is None:
        print("usage: aide progress set NNN <in-progress|in-review|done> | "
              "set NNN <deferred|resumed|dropped|restored> --reason TEXT",
              file=sys.stderr)
        return 2
    if args.status in _ITEM_SET:
        return _cmd_progress_defer(args)
    if args.status not in _SET_STATUS_MAP:
        print("status must be 'in-progress', 'in-review', 'done', "
              "'deferred', 'resumed', 'dropped' or 'restored'",
              file=sys.stderr)
        return 2
    status_map = _SET_STATUS_MAP
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    progress_path = docs_dir(repo_root, config) / "progress.md"
    if not progress_path.is_file():
        print(f"error: {progress_path} not found", file=sys.stderr)
        return 1
    text = progress_path.read_text(encoding=_ENCODING)
    original = text
    # A ⏸️ item leaves ⏸️ by `set NNN resumed` alone (issue #380). A forward
    # status over it used to resume it, and `in-progress` on one never
    # claimed left it 🚧 with no branch: `claim` offered nothing, `status`
    # counted it as work to build and `sync --item` asked for a claim.
    # A ❌ item leaves ❌ by `set NNN restored` alone (issue #381): ❌ ranks
    # lowest, so a forward status cleared a drop silently, with no reason
    # and no trail line. Only an item the way back can take is held
    # (`held_from_forward`); one it refuses — a ⏸️ or ❌ beside a 🚧/🔍/✅
    # bullet, which only a hand edit makes — keeps the forward set as its
    # way out.
    held = held_from_forward(text.splitlines(), args.number)
    if held is not None:
        word, verb = (("deferred", "resumed") if held == "deferred"
                      else ("dropped", "restored"))
        print(f"error: item {args.number:03d} is {STATUS_TO_ICON[held]} "
              f"{word}, and a {word} item is not set forward — {verb[:-1]} it "
              f"with `aide progress set {args.number:03d} {verb} --reason …`, "
              f"which sends it back to 📋 for `aide claim` to offer; "
              f"progress.md NOT changed", file=sys.stderr)
        return 1
    # An item is only trackable if some deliverable bullet's trailing marker
    # names it — the ownership rule set_item_status flips by — otherwise the
    # set would be a silent no-op. A prose mention on someone else's bullet
    # does not count (issue #99). When the queue back-fill was missed,
    # self-heal deterministically from the item spec's own Stage/title header;
    # only when that context is missing too does this stay a loud, blocking
    # error.
    healed_note: Optional[str] = None
    if args.number not in _parse_item_status(text.splitlines())[2]:
        stage, title = _spec_stage_and_title(repo_root, config, args.number)
        healed = insert_item_reference(text, args.number, stage, title) if stage and title else None
        if healed is None:
            print(
                f"item {args.number:03d}: ERROR — no deliverable in progress.md "
                f"references 'Item {args.number:03d}', and no item spec with a "
                f"Stage header was found to insert one from; status NOT "
                f"recorded. Add the reference to the owning stage's deliverable "
                f"bullet (e.g. '- 📋 <deliverable>. *(Item {args.number:03d})*'), "
                f"then re-run.",
                file=sys.stderr,
            )
            return 1
        text = healed
        # Announced only after the guard below confirms the back-fill took —
        # a success-flavoured line right before "NOT changed" reads as a
        # contradiction in an unattended log.
        healed_note = (f"item {args.number:03d}: back-filled missing "
                       f"deliverable reference under Stage {stage} "
                       f"(from the item spec)")
    splits: List[BulletSplit] = []
    updated = set_item_status(text, args.number, status_map[args.status], splits)
    if args.number not in _parse_item_status(updated.splitlines())[2]:
        # Belt to the heal's braces: if the back-fill (or anything else) left
        # no bullet whose trailing marker names this item, the set recorded
        # nothing — say so and write nothing, instead of printing success over
        # a silent no-op (the failure shape a review of issue #99 found).
        print(
            f"item {args.number:03d}: ERROR — after the back-fill, no "
            f"deliverable bullet's trailing *(Item {args.number:03d})* marker "
            f"names this item, so the status could not be recorded; progress.md "
            f"NOT changed. Add the marker to the owning bullet's last line, "
            f"then re-run.",
            file=sys.stderr,
        )
        return 1
    if healed_note:
        print(healed_note)
    before: Optional[Dict[Path, Optional[bytes]]] = None
    if updated == original:
        print(f"item {args.number:03d}: no change (already >= {args.status})")
    else:
        before = _snapshot([progress_path])
        progress_path.write_text(updated, encoding="utf-8")
        print(f"item {args.number:03d}: set to {args.status}")
        _report_bullet_splits(args.number, updated.splitlines(), splits)
    if _commits_here(args.no_commit, repo_root, before):
        message = f"progress(aide): item {args.number:03d} -> {args.status}"
        if before is None:
            # Nothing written, so nothing of this run's to lose: the commit
            # stays the best-effort sweep it always was, and a no-op exits 0.
            _commit_docs_files(repo_root, config, message,
                               [_progress_rel(config)])
        else:
            return _commit_or_restore(repo_root, config, "aide progress set",
                                      "the status", message,
                                      [_progress_rel(config)], before)
    return 0


def _cmd_progress_accept(args: argparse.Namespace) -> int:
    """``aide progress accept STAGE --criterion N`` — tick an acceptance box.

    The explicit counterpart to the auto-tick ``set_item_status`` used to
    perform. An acceptance criterion is attested by a human who checked it, so
    it takes a deliberate command that records what was accepted and, with
    ``--evidence``, on what basis.
    """
    if args.criterion is None and not args.all_criteria:
        print("usage: aide progress accept STAGE (--criterion N | --all) "
              "[--evidence TEXT]", file=sys.stderr)
        return 2
    if args.criterion is not None and args.all_criteria:
        print("aide progress accept: pass --criterion or --all, not both", file=sys.stderr)
        return 2
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    progress_path = docs_dir(repo_root, config) / "progress.md"
    if not progress_path.is_file():
        print(f"error: {progress_path} not found", file=sys.stderr)
        return 1
    text = progress_path.read_text(encoding=_ENCODING)
    criteria = None if args.all_criteria else [args.criterion]
    try:
        updated, messages = accept_criteria(text, str(args.number), criteria, args.evidence)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    for msg in messages:
        print(f"stage {args.number}: {msg}")
    if updated == text:
        return 0
    before = _snapshot([progress_path])
    progress_path.write_text(updated, encoding="utf-8")
    if _commits_here(args.no_commit, repo_root, before):
        what = "all criteria" if args.all_criteria else f"criterion {args.criterion}"
        return _commit_or_restore(
            repo_root, config, "aide progress accept", "the acceptance",
            f"progress(aide): stage {args.number} accept {what}",
            [_progress_rel(config)], before)
    return 0


#: ``.aide/VERSION`` beside this script, for the engine stamp a captured
#: insight carries (§1). One directory up from ``scripts/``, which is the
#: layout in a consumer *and* in the framework's own tree (``core/VERSION``),
#: so one relative step serves both — the same reasoning ``_TEMPLATES_DIR``
#: is built on. Missing only where the script has been copied away from its
#: siblings, and that is not an error: the note is free-form and optional, so
#: the entry is written without it.
_VERSION_FILE = Path(__file__).resolve().parents[1] / "VERSION"


def installed_engine_version() -> Optional[str]:
    """The engine version this script belongs to, or None if it cannot be read.

    Two readers: the stamp a captured insight carries (§1), and the assumption
    marker check in `item_spec_warnings`. Both treat a missing file as "say
    nothing" rather than as an error — the script may have been copied away
    from its siblings, and neither reader is load-bearing enough to fail over.
    """
    try:
        v = _VERSION_FILE.read_text(encoding=_ENCODING).strip()
    except OSError:
        return None
    return v or None


def _engine_stamp() -> Optional[str]:
    v = installed_engine_version()
    return f"engine {v}" if v else None


def _route_retraction_to_insights(repo_root: Path, config, stage: str, n: int,
                                  reason: str, date: str) -> Tuple[Optional[str], str]:
    """Append the ``gap`` entry a retraction *is*; ``(rel_path, message)``.

    §1 already says a `❌ Not met` outcome target is a finding and must be
    routed like one. A withdrawn acceptance box is the same event one level
    down, so the verb does the routing itself rather than asking the caller to
    remember: the honest path has to be the cheap one, or the quiet path wins.
    """
    return _route_gap_to_insights(repo_root, config, "retraction",
                                  "acceptance criterion retracted",
                                  f"stage {stage} criterion {n}", reason, date)


def _route_gap_to_insights(repo_root: Path, config, event: str, lead: str,
                           source: str, reason: str,
                           date: str) -> Tuple[Optional[str], str]:
    """Append ``- [ ] gap — <lead>: <reason> *(<source>, <date>, engine)*``.

    The one writer for a correction verb's finding — `retract` for a box,
    `reopen` for an item (issue #271) — so both entries have the one shape
    `aide check`'s inbox rule reads. ``(rel_path, message)``; no path when
    there is no inbox to write to, and the message says so.
    """
    ddir = docs_dir(repo_root, config)
    path = insights_path(ddir)
    if not path.is_file():
        return None, (f"notice: no insights.md, so the {event} was not "
                      f"routed — capture it wherever this project keeps findings")
    stamp = _engine_stamp()
    marker = f"*({source}, {date}" + (f", {stamp}" if stamp else "") + ")*"
    entry = f"- [ ] gap — {lead}: {reason} {marker}"
    text = path.read_text(encoding=_ENCODING)
    if not text.endswith("\n"):
        text += "\n"
    path.write_text(text + entry + "\n", encoding="utf-8")
    rel = str(config["project"].get("docs_dir", "docs/aide")) + "/insights.md"
    return rel, f"insights.md: captured a gap entry for the {event}"


def _cmd_progress_amend(args: argparse.Namespace) -> int:
    """``aide progress amend STAGE --criterion N --evidence TEXT`` — append-only.

    The correction path for an attestation whose *evidence* was wrong, which
    before this verb had no CLI route at all: `accept` reports an already-ticked
    box as "unchanged", so the only remedy was the hand edit of `progress.md`
    every role is otherwise forbidden from making (issue #118).
    """
    if args.all_criteria:
        print("aide progress amend: --all is not offered — an attestation is "
              "corrected one at a time, or the correction says nothing about "
              "any of them", file=sys.stderr)
        return 2
    if args.criterion is None:
        print("usage: aide progress amend STAGE --criterion N --evidence TEXT",
              file=sys.stderr)
        return 2
    if not (args.evidence or "").strip():
        print("aide progress amend: --evidence is required — a correction "
              "with no stated basis is not one", file=sys.stderr)
        return 2
    return _apply_criterion_edit(
        args, lambda text, date: amend_criterion(
            text, str(args.number), args.criterion, args.evidence.strip(), date),
        f"stage {args.number} amend criterion {args.criterion}")


def _cmd_progress_retract(args: argparse.Namespace) -> int:
    """``aide progress retract STAGE --criterion N --reason TEXT``.

    Unticks, keeps the original attestation visible, and captures the finding.
    """
    if args.all_criteria:
        print("aide progress retract: --all is not offered — each attestation "
              "was made separately and is withdrawn separately", file=sys.stderr)
        return 2
    if args.criterion is None:
        print("usage: aide progress retract STAGE --criterion N --reason TEXT",
              file=sys.stderr)
        return 2
    if not (args.reason or "").strip():
        print("aide progress retract: --reason is required — the reason is "
              "what the record keeps", file=sys.stderr)
        return 2
    reason = args.reason.strip()
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    progress_path = docs_dir(repo_root, config) / "progress.md"
    if not progress_path.is_file():
        print(f"error: {progress_path} not found", file=sys.stderr)
        return 1
    import datetime as _dt
    date = args.date or _dt.date.today().isoformat()
    text = progress_path.read_text(encoding=_ENCODING)
    try:
        updated, message = retract_criterion(
            text, str(args.number), args.criterion, reason, date)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    before = _snapshot([progress_path, insights_path(progress_path.parent)])
    progress_path.write_text(updated, encoding="utf-8")
    print(f"stage {args.number}: {message}")
    rel_insights, note = _route_retraction_to_insights(
        repo_root, config, str(args.number), args.criterion, reason, date)
    print(note)
    # The retraction warning `aide check` now emits is permanent by design, and
    # a consumer that pins the tolerated warning set discovers that at its
    # merge gate rather than here — a suite reddened by honest self-correction,
    # with nothing at retraction time having said so (issue #152). Say it here,
    # so the widening lands in the same change as the retraction.
    print(f"notice: `aide check` will warn about this retraction from now on — "
          f"the record is permanent, not a defect to clear. A test that pins "
          f"the tolerated warning set needs widening for stage {args.number} "
          f"criterion {args.criterion}; do it in this change, not at the merge "
          f"gate")
    if _commits_here(args.no_commit, repo_root, before):
        rels = [_progress_rel(config)]
        if rel_insights:
            rels.append(rel_insights)
        else:
            before = {progress_path: before[progress_path]}
        return _commit_or_restore(
            repo_root, config, "aide progress retract", "the retraction",
            f"progress(aide): stage {args.number} retract criterion {args.criterion}",
            rels, before)
    return 0


def _cmd_progress_reopen(args: argparse.Namespace) -> int:
    """``aide progress reopen NNN --reason TEXT`` — send a ✅ item back to 📋.

    The item-level counterpart of `retract` (issue #271): a deliverable closed
    on merged code whose operator run never happened had no verb back, so it
    was hand-edited from ✅ to 📋 and left no trail. This flips the bullet,
    writes the reason under it, and routes the finding, exactly as `retract`
    does for a box.
    """
    usage = "usage: aide progress reopen NNN --reason TEXT [--date YYYY-MM-DD]"
    if args.status is not None or args.criterion is not None or args.all_criteria:
        print(f"{usage}\naide progress reopen: an item is reopened whole — it "
              f"takes no status, --criterion or --all", file=sys.stderr)
        return 2
    if not (args.reason or "").strip():
        print("aide progress reopen: --reason is required — the reason is "
              "what the record keeps", file=sys.stderr)
        return 2
    reason = args.reason.strip()
    if "\n" in reason or "\r" in reason:
        print("aide progress reopen: the reason may not contain a line break "
              "— it is written into one trail line", file=sys.stderr)
        return 2
    if re.match(r"CI[:\-]", reason):
        print(f"aide progress reopen: a reason naming CI is a CI reopening "
              f"only in the form `{_CI_REASON_PREFIX}<check>: <failing test or "
              f"step>` — `CI` then a space — so {reason[:12]!r}… would not be "
              f"counted as one; write it in that form", file=sys.stderr)
        return 2
    if _CI_ROUND_RE.search(reason):
        print("aide progress reopen: the reason may not end in a `[CI round "
              "N]` stamp — the engine writes the round on a reason starting "
              f"`{_CI_REASON_PREFIX}`, so no runner counts it",
              file=sys.stderr)
        return 2
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    progress_path = docs_dir(repo_root, config) / "progress.md"
    if not progress_path.is_file():
        print(f"error: {progress_path} not found", file=sys.stderr)
        return 1
    import datetime as _dt
    date = args.date or _dt.date.today().isoformat()
    text = progress_path.read_text(encoding=_ENCODING)
    if reason.startswith(_CI_REASON_PREFIX):
        scope = _ci_round_scope(repo_root, config, args.number)
        reason += f" [CI round {next_ci_round(text.splitlines(), scope)}]"
    splits: List[BulletSplit] = []
    try:
        updated, message = reopen_item(text, args.number, reason, date, splits)
    except ValueError as exc:
        print(f"error: {exc}; progress.md NOT changed", file=sys.stderr)
        return 1
    before = _snapshot([progress_path, insights_path(progress_path.parent)])
    progress_path.write_text(updated, encoding="utf-8")
    print(message)
    _report_bullet_splits(args.number, updated.splitlines(), splits)
    rel_insights, note = _route_gap_to_insights(
        repo_root, config, "reopening", _REOPEN_GAP_LEAD,
        f"item {args.number:03d}", reason, date)
    print(note)
    # Issue #152's advice, one level up: the warning is permanent by design.
    print(f"notice: `aide check` will warn about this reopening from now on — "
          f"the record is permanent, not a defect to clear. A test that pins "
          f"the tolerated warning set needs widening for item "
          f"{args.number:03d}; do it in this change, not at the merge gate")
    if _commits_here(args.no_commit, repo_root, before):
        rels = [_progress_rel(config)]
        if rel_insights:
            rels.append(rel_insights)
        else:
            before = {progress_path: before[progress_path]}
        return _commit_or_restore(
            repo_root, config, "aide progress reopen", "the reopening",
            f"progress(aide): item {args.number:03d} reopen", rels, before)
    return 0


def _ci_round_scope(repo_root: Path, config: Dict[str, Dict[str, object]],
                    num: int) -> Set[int]:
    """The items whose CI reopenings share a round count with item *num*.

    On a queue branch with a recorded base, the items of every queue it
    carries (`_branch_queue_items`) — one PR, one CI, one count, a
    maintenance queue and the stage queue after it included — which is
    exactly the set `status` counts for that branch. Anywhere else, the items
    of the queue file(s) listing *num*. *num* is always in it.
    """
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    branch = _current_branch(repo_root)
    base = (_recorded_branch_base(repo_root, branch)
            if _is_stack_branch(branch, prefix) else None)
    items = (_branch_queue_items(repo_root, config, "HEAD", base, branch)
             if base else set())
    if num not in items:
        for path in iter_queue_paths(docs_dir(repo_root, config) / "queue"):
            listed = queue_item_numbers(path.read_text(encoding=_ENCODING))
            if num in listed:
                items.update(listed)
    return items | {num}


#: The statuses `set NNN` writes with a reason, each with the function that
#: writes it and the noun its commit and messages use (issues #281, #380).
_ITEM_SET = {"deferred": (defer_item, "the deferral"),
             "resumed": (resume_item, "the resumption"),
             "dropped": (drop_item, "the drop"),
             "restored": (restore_item, "the restoration")}


def _cmd_progress_defer(args: argparse.Namespace) -> int:
    """``aide progress set NNN <deferred|resumed|dropped|restored> --reason
    TEXT`` — postpone an item or drop it, or take either back up.

    The one way to write ⏸️ on a deliverable (issue #281): it used to be a hand
    edit, with no record of why, and a whole stage deferred that way read as
    one nobody had started. The reason goes on a trail line under each flipped
    bullet, as `reopen`'s does. `resumed` is the way back to 📋 (issue #380),
    with its own reason beside the deferral's. `dropped` writes ❌ on an item
    the stage does not need, and `restored` takes it back to 📋 (issue #381).
    No insight is captured by any of them: a deferral and a resumption are
    decisions about order, a drop and a restoration decisions about scope,
    not findings about the work.
    """
    status = args.status
    usage = (f"usage: aide progress set NNN {status} --reason TEXT "
             f"[--date YYYY-MM-DD]")
    if args.criterion is not None or args.all_criteria:
        print(f"{usage}\naide progress set: an item is {status} whole — it "
              f"takes no --criterion or --all", file=sys.stderr)
        return 2
    if not (args.reason or "").strip():
        print(f"aide progress set NNN {status}: --reason is required — the "
              f"reason is what the record keeps", file=sys.stderr)
        return 2
    reason = args.reason.strip()
    if "\n" in reason or "\r" in reason:
        print(f"aide progress set NNN {status}: the reason may not contain a "
              f"line break — it is written into one trail line", file=sys.stderr)
        return 2
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    progress_path = docs_dir(repo_root, config) / "progress.md"
    if not progress_path.is_file():
        print(f"error: {progress_path} not found", file=sys.stderr)
        return 1
    import datetime as _dt
    date = args.date or _dt.date.today().isoformat()
    text = progress_path.read_text(encoding=_ENCODING)
    splits: List[BulletSplit] = []
    write, noun = _ITEM_SET[status]
    try:
        updated, message = write(text, args.number, reason, date, splits)
    except ValueError as exc:
        print(f"error: {exc}; progress.md NOT changed", file=sys.stderr)
        return 1
    print(message)
    if updated == text:
        return 0
    before = _snapshot([progress_path])
    progress_path.write_text(updated, encoding="utf-8")
    _report_bullet_splits(args.number, updated.splitlines(), splits)
    if _commits_here(args.no_commit, repo_root, before):
        return _commit_or_restore(
            repo_root, config, "aide progress set", noun,
            f"progress(aide): item {args.number:03d} -> {status}",
            [_progress_rel(config)], before)
    return 0


#: The statuses `set --stage N --deliverable K` writes, each with the
#: function that writes it and the noun its commit and messages use.
_POSITIONAL_SET = {"deferred": (defer_deliverable, "the deferral"),
                   "dropped": (drop_deliverable, "the drop"),
                   "resumed": (resume_deliverable, "the resumption"),
                   "restored": (restore_deliverable, "the restoration")}


def _cmd_progress_defer_deliverable(args: argparse.Namespace) -> int:
    """``aide progress set --stage N --deliverable K
    <deferred|dropped|resumed|restored> --reason TEXT``.

    The deferral of a deliverable bullet no item marker names (issue #336),
    addressed by its position in the stage, its drop as not needed (issue
    #362), its resumption from ⏸️ back to 📋 so it can be itemised (issue
    #380), and its restoration from ❌ back to 📋 (issue #381). Otherwise
    `_cmd_progress_defer` exactly: the reason is required and on one line,
    and the edit is committed or put back. No insight is captured by any of
    them: a deferral and a resumption are decisions about order, a drop and a
    restoration ones about scope.
    """
    usage = ("usage: aide progress set --stage N --deliverable K "
             "<deferred|dropped|resumed|restored> --reason TEXT "
             "[--date YYYY-MM-DD]")
    tag = "aide progress set --stage/--deliverable"
    if args.action != "set":
        print(f"{usage}\naide progress {args.action}: --stage and "
              f"--deliverable belong to `set … deferred`, `set … dropped`, "
              f"`set … resumed` and `set … restored` alone", file=sys.stderr)
        return 2
    if args.stage is None or args.deliverable is None:
        print(f"{usage}\n{tag}: --stage and --deliverable go together — the "
              f"stage names the section, the deliverable its Kth bullet",
              file=sys.stderr)
        return 2
    status = args.status
    if isinstance(args.number, str) and status is None:
        status = args.number
    elif args.number is not None:
        # Every positional status has its item form (issues #380, #381).
        named = status if status in _POSITIONAL_SET else "deferred"
        print(f"{usage}\n{tag}: takes no item number — an itemised bullet "
              f"is {named} with `aide progress set NNN {named} --reason …`",
              file=sys.stderr)
        return 2
    if status not in _POSITIONAL_SET:
        shown = f"'{status}'" if status else "no status"
        print(f"{usage}\n{tag}: only `deferred`, `dropped`, `resumed` or "
              f"`restored` is set by position, not {shown} — a deliverable "
              f"with no item marker moves forward once it is itemised, after "
              f"which `aide progress set NNN <status>` moves it",
              file=sys.stderr)
        return 2
    if args.criterion is not None or args.all_criteria:
        print(f"{usage}\n{tag}: a deliverable is {status} whole — it takes no "
              f"--criterion or --all", file=sys.stderr)
        return 2
    if not (args.reason or "").strip():
        print(f"{tag} {status}: --reason is required — the reason is what the "
              f"record keeps", file=sys.stderr)
        return 2
    reason = args.reason.strip()
    if "\n" in reason or "\r" in reason:
        print(f"{tag} {status}: the reason may not contain a line break — it "
              f"is written into one trail line", file=sys.stderr)
        return 2
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    progress_path = docs_dir(repo_root, config) / "progress.md"
    if not progress_path.is_file():
        print(f"error: {progress_path} not found", file=sys.stderr)
        return 1
    import datetime as _dt
    date = args.date or _dt.date.today().isoformat()
    text = progress_path.read_text(encoding=_ENCODING)
    write, noun = _POSITIONAL_SET[status]
    try:
        updated, message = write(text, args.stage, args.deliverable, reason,
                                 date)
    except ValueError as exc:
        print(f"error: {exc}; progress.md NOT changed", file=sys.stderr)
        return 1
    print(message)
    if updated == text:
        return 0
    before = _snapshot([progress_path])
    progress_path.write_text(updated, encoding="utf-8")
    if _commits_here(args.no_commit, repo_root, before):
        return _commit_or_restore(
            repo_root, config, "aide progress set", noun,
            f"progress(aide): stage {args.stage} deliverable "
            f"{args.deliverable} -> {status}",
            [_progress_rel(config)], before)
    return 0


def _progress_number(value: str):
    """`aide progress`'s NUMBER: an int, or the word as typed when it is not
    one — so `set --stage N --deliverable K deferred` can carry its status in
    that first positional. `cmd_progress` refuses a word anywhere else with
    the message argparse's `type=int` would have printed."""
    try:
        return int(value)
    except ValueError:
        return value


def _cmd_progress_reword(args: argparse.Namespace) -> int:
    """``aide progress reword STAGE --criterion N --text TEXT``.

    Both files or neither wherever the roadmap mirrors the stage. The roadmap
    mirrors the criteria, so a rewording that lands in one document is the
    drift the verb exists to remove; when the two cannot be lined up, nothing is
    written and the message says so. A stage with no roadmap acceptance block —
    or no roadmap.md at all — has no mirror to drift from, so progress.md alone
    is written and the message says that too (issue #216).
    """
    if args.all_criteria:
        what = ("bullets are reworded one item at a time"
                if args.item is not None
                else "criteria are reworded one at a time")
        print(f"aide progress reword: --all is not offered — {what}",
              file=sys.stderr)
        return 2
    if args.item is not None:
        return _cmd_progress_reword_deliverable(args)
    if args.criterion is None or args.number is None:
        print("usage: aide progress reword STAGE --criterion N --text TEXT | "
              "reword --item NNN --text TEXT", file=sys.stderr)
        return 2
    if not (args.text or "").strip():
        print("aide progress reword: --text is required", file=sys.stderr)
        return 2
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    ddir = docs_dir(repo_root, config)
    progress_path = ddir / "progress.md"
    roadmap_path = ddir / "roadmap.md"
    if not progress_path.is_file():
        print(f"error: {progress_path} not found", file=sys.stderr)
        return 1
    text = progress_path.read_text(encoding=_ENCODING)
    try:
        updated, old = reword_criterion(
            text, str(args.number), args.criterion, args.text)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    # How many boxes the stage has, for lining the roadmap up against it.
    plines = text.splitlines()
    psec = stage_section(plines, str(args.number))
    box_count = len(acceptance_boxes(plines, psec[0], psec[1]))
    road_updated: Optional[str] = None
    if roadmap_path.is_file():
        road_updated, err = reword_roadmap_bullet(
            roadmap_path.read_text(encoding=_ENCODING), str(args.number),
            args.criterion, args.text, box_count)
        if err:
            print(f"error: {err}", file=sys.stderr)
            return 1
    before = _snapshot([progress_path] + ([roadmap_path] if road_updated is not None
                                          else []))
    progress_path.write_text(updated, encoding="utf-8")
    rels = [_progress_rel(config)]
    print(f"stage {args.number}: criterion {args.criterion} reworded")
    print(f"  was: {old}")
    print(f"  now: {args.text.strip()}")
    if road_updated is not None:
        roadmap_path.write_text(road_updated, encoding="utf-8")
        rels.append(str(config["project"].get("docs_dir", "docs/aide")) + "/roadmap.md")
        print("  roadmap.md: mirrored")
    else:
        print("  roadmap.md: no acceptance block for this stage — nothing to mirror")
    if _commits_here(args.no_commit, repo_root, before):
        return _commit_or_restore(
            repo_root, config, "aide progress reword", "the rewording",
            f"progress(aide): stage {args.number} reword criterion {args.criterion}",
            rels, before)
    return 0


def _cmd_progress_reword_deliverable(args: argparse.Namespace) -> int:
    """``aide progress reword --item NNN --text TEXT`` — a bullet's prose.

    The bullet form of `reword` (issue #320): the repair `aide check`'s
    identical-prose warning and the split report ask for. progress.md alone is
    written. roadmap.md mirrors a stage's acceptance criteria, which is why the
    criterion form writes both; its Deliverables bullets carry no item marker —
    items are born after the roadmap, in the queue — so there is no bullet of
    item NNN there to keep in step, and nothing to refuse over.
    """
    usage = "usage: aide progress reword --item NNN --text TEXT"
    if args.number is not None or args.status is not None:
        print(f"{usage}\naide progress reword --item: takes no STAGE — the "
              f"bullet is found by its item's marker, wherever it sits",
              file=sys.stderr)
        return 2
    if not (args.text or "").strip():
        print(f"{usage}\naide progress reword: --text is required",
              file=sys.stderr)
        return 2
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    progress_path = docs_dir(repo_root, config) / "progress.md"
    if not progress_path.is_file():
        print(f"error: {progress_path} not found", file=sys.stderr)
        return 1
    text = progress_path.read_text(encoding=_ENCODING)
    try:
        updated, old, lineno = reword_deliverable(text, args.item, args.text)
    except ValueError as exc:
        print(f"error: {exc}; progress.md NOT changed", file=sys.stderr)
        return 1
    if updated == text:
        print(f"item {args.item:03d}: no change (progress.md:{lineno} already "
              f"reads so)")
        return 0
    before = _snapshot([progress_path])
    progress_path.write_text(updated, encoding="utf-8")
    print(f"item {args.item:03d}: deliverable bullet reworded "
          f"(progress.md:{lineno})")
    print(f"  was: {old}")
    print(f"  now: {args.text.strip()}")
    if _commits_here(args.no_commit, repo_root, before):
        return _commit_or_restore(
            repo_root, config, "aide progress reword", "the rewording",
            f"progress(aide): item {args.item:03d} reword deliverable",
            [_progress_rel(config)], before)
    return 0


def _apply_criterion_edit(args: argparse.Namespace, edit, message: str) -> int:
    """Read progress.md, apply *edit*, write and commit — the amend path."""
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    progress_path = docs_dir(repo_root, config) / "progress.md"
    if not progress_path.is_file():
        print(f"error: {progress_path} not found", file=sys.stderr)
        return 1
    import datetime as _dt
    date = args.date or _dt.date.today().isoformat()
    text = progress_path.read_text(encoding=_ENCODING)
    try:
        updated, msg = edit(text, date)
    except ValueError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1
    before = _snapshot([progress_path])
    progress_path.write_text(updated, encoding="utf-8")
    print(f"stage {args.number}: {msg}")
    if _commits_here(args.no_commit, repo_root, before):
        return _commit_or_restore(
            repo_root, config, f"aide progress {args.action}", "the edit",
            f"progress(aide): {message}", [_progress_rel(config)], before)
    return 0


def _progress_rel(config) -> str:
    return str(config["project"].get("docs_dir", "docs/aide")) + "/progress.md"


def _snapshot(paths: List[Path]) -> Dict[Path, Optional[bytes]]:
    """Each path's bytes as they are now — ``None`` for one not yet written —
    for `_commit_or_restore` to put back."""
    return {p: (p.read_bytes() if p.is_file() else None) for p in paths}


def _put_back(before: Dict[Path, Optional[bytes]]) -> None:
    """Every file in *before* back to its bytes; one that did not exist, gone."""
    for path, data in before.items():
        if data is not None:
            path.write_bytes(data)
        elif path.exists():
            path.unlink()


def _commit_or_put_back(repo_root: Path, config, message: str,
                        rels: List[str], before: Dict[Path, Optional[bytes]],
                        pull: bool = True) -> Tuple[Optional[str], bool]:
    """Commit *rels*; ``(None, False)`` when the edit is in ``HEAD``, else
    ``(reason, committed)`` — with every file in *before* put back when the
    reason stopped the commit itself.

    The mechanism under `_commit_or_restore` and under `aide merge`'s tick,
    which differ only in what they say and what they refuse next (issues
    #309, #312). *committed* is read from git rather than from the reason:
    ``HEAD`` moved, so the edit is in a commit and is kept — the replay onto
    origin stopped, or a path was left out of it — and the reason is what
    that commit still lacks. ``HEAD`` did not move, so nothing of this edit
    is anywhere but the worktree, and each file goes back to its bytes (line
    endings and all; a file that did not exist is removed). "Nothing to
    commit" is no reason at all: the edit is already in ``HEAD``.
    """
    try:
        head: Optional[str] = _rev(repo_root, "HEAD")
    except (OSError, subprocess.SubprocessError):
        head = None
    failure = _commit_docs_files(repo_root, config, message, rels, pull=pull)
    if not failure or failure == "nothing to commit":
        return None, False
    try:
        # An unborn branch reads as "", so a HEAD afterwards is still a move.
        moved = head is not None and _rev(repo_root, "HEAD") != head
    except (OSError, subprocess.SubprocessError):
        moved = False
    if moved:
        return failure, True
    _put_back(before)
    return failure, False


def _commit_or_restore(repo_root: Path, config, tag: str, what: str,
                       message: str, rels: List[str],
                       before: Dict[Path, Optional[bytes]],
                       pull: bool = True) -> int:
    """Commit the edit a verb has just written; 0, or 1 with the edit undone.

    For a verb a person or an agent runs to record a decision (issue #309):
    an edit left written but uncommitted reads as already made to a re-run,
    which then finds nothing to do and never commits it, and the dirty file
    stops the next `aide sync` with nothing naming the verb. So a commit that
    did not happen — ``HEAD`` did not move — puts every file in *before* back
    to its bytes (line endings and all; a file that did not exist is removed)
    and exits 1, and the re-run once the cause is fixed makes the edit and
    commits it. A commit that happened but whose replay onto origin stopped
    keeps the edit, which is in that commit, and exits 1 on the reason
    `_commit_docs_files` has already printed in full. "Nothing to commit" is
    not a failure: the edit is already in ``HEAD``.

    `ensure_insights_inbox` is the deliberate exception and does not come
    here: the inbox is a file `check` creates on the caller's behalf, and its
    commit failing is a notice on a check, never the check's exit.
    """
    failure, committed = _commit_or_put_back(repo_root, config, message, rels,
                                             before, pull=pull)
    if failure is None:
        return 0
    if committed:
        print(f"{tag}: {what} is committed, but {failure}", file=sys.stderr)
        return 1
    names = [p.name for p in before]
    state = (f"{names[0]} is as it was" if len(names) == 1
             else f"{', '.join(names)} are as they were")
    print(f"{tag}: {what} could not be committed — {failure}. {state}; "
          f"re-run once that is fixed.", file=sys.stderr)
    return 1


def _commit_docs_files(repo_root: Path, config, message: str,
                       rels: List[str], pull: bool = True) -> Optional[str]:
    """Commit exactly *rels* — repo-relative paths — with *message*.

    Returns ``None`` when every named path is in a new commit on this
    branch, otherwise a one-line reason — so a caller that announces a commit
    announces what happened, not what it intended. Two things are reasons:
    the commit did not happen (a refused tree, a failed ``git commit``, a
    path the commit left out), and the commit happened but replaying it onto
    the upstream stopped mid-rebase, since the branch no longer carries it
    until that rebase is finished. A rebase that was skipped or never started
    is **not** a reason: the commit is complete and local, and that case is a
    printed notice, never a return. "Exactly" is enforced by pathspec: ``git commit -- <rels>``
    commits the named paths and nothing else, so a builder's staged work
    sitting in the index stays staged and out of the bookkeeping commit; a
    bare ``git commit`` would have swept it in, which is why ``git add <rel>``
    alone was never enough.

    What a caller does with a reason is split by who ran it (issue #309).
    A verb a person or an agent runs to record something — `gate`, the
    `progress` sub-verbs, `insights add`/`tick`/`archive`, `ledger`, `queue gate` —
    goes through `_commit_or_restore`, which turns a reason into exit 1 and,
    when no commit was made, puts the edit back so a re-run makes it again.
    ``ensure_insights_inbox`` keeps the reason a printed notice: the inbox is
    a file ``check`` creates on its caller's behalf, and a check's exit is
    the documents' verdict, not the commit's. The no-op sweep in `progress
    set` is best effort too: it wrote nothing, so it has nothing to lose.
    `merge`'s tick is not, though it once was on the ground that the merge had
    already landed: it had landed in this repository only, and the push after
    it carried the merge to origin without the ✅, the ledger row or the
    inbox entry, deleted the claim branch a re-run needed, and left the tree
    dirty for the next `aide sync` (issue #312). It goes through
    `_commit_or_put_back`, the mechanism under `_commit_or_restore`, and a
    reason there stops the merge before its push.

    A commit that fails — no ``user.name`` on a fresh clone, a hook, a path
    ``.gitignore`` reaches — leaves *rels* unstaged again, so the tree degrades
    to "modified" or "untracked" rather than "staged": ``aide sync`` refuses
    either, but a caller can say which and why. A ``git`` that cannot be run
    at all is a reason, not a traceback; ``check`` in particular must keep
    judging the documents in a repo whose ``git`` is off PATH, as it did
    before 1.26.0.

    *pull* rebases the new commit onto the upstream **afterwards**, which is
    right for an edit to a file other machines also edit (a tick, an archive)
    and wrong for a file that did not exist a moment ago —
    ``ensure_insights_inbox`` passes ``False`` so that ``check``, a gate,
    never fetches on the caller's behalf. The order is the whole point: every
    caller has already written its edit to the worktree, and ``git pull
    --rebase`` refuses over an unstaged change before it starts, so a pull
    *ahead* of the commit never ran in the ordinary path and two machines
    ticking the same inbox diverged until push time (issue #180). Committing
    first leaves a clean tree in the common case, the rebase is real, and a
    conflict then stops **inside** a rebase — a state with a marker, which
    `_stalled_pull` names and routes the same way `aide merge` does.

    A tree already stopped in an earlier operation is refused *before* the
    commit, and for every caller, *pull* or not — git lets a commit through
    once the conflicts are staged, and a bookkeeping commit in the middle of
    someone's rebase is the state this exists to prevent (issue #178); the
    guard reads the git directory and fetches nothing, so ``check`` stays a
    gate. Two shapes the pull itself deliberately does not touch. Under
    ``git.mode = "local"``, or with no ``origin``, there is nothing to rebase
    onto and the other sites skip it too. And a ``HEAD`` carrying a merge
    commit origin has not seen is never rebased by a bookkeeping verb: the
    rebase drops the merge and replays both parents, bringing back every
    conflict resolved inside it (issue #133) — and `aide merge` reaches here
    with exactly that commit on ``HEAD`` whenever its merge was not a
    fast-forward, having integrated origin itself before the suite ran, so
    the skip is silent there by design. A fast-forward leaves no merge
    commit, and the tick is then rebased like any other; a replay that stops
    is a reason `merge` refuses its push on (issue #312).
    """
    joined = ", ".join(rels)
    try:
        what = _interrupted_op(repo_root)
        if what is not None:
            # Refused, and refused HERE rather than left to `git commit`: with
            # the conflicts staged git accepts a commit mid-rebase, and a
            # caller that keeps the reason a notice would print its success
            # line over a tick sitting in the middle of an unfinished
            # operation. Unconditional on `pull`: the one caller
            # that passes False (`ensure_insights_inbox`) is creating a file,
            # and a new file committed mid-rebase is the same misplaced commit.
            reason = (f"the repository is stopped in an earlier operation "
                      f"— {_stopped_state(repo_root, config, what)}")
            print(f"aide: could not commit {joined} — {reason}", file=sys.stderr)
            return reason
        refused_add = ""
        for rel in rels:
            added = git(["add", "--", rel], repo_root, check=False)
            if added.returncode != 0 and not refused_add:
                refused_add = next(
                    (l.strip() for l in (added.stderr + added.stdout).splitlines()
                     if l.strip()), "")
        res = git(["commit", "-m", message, "--", *rels], repo_root, check=False)
        if res.returncode != 0:
            git(["reset", "-q", "--", *rels], repo_root, check=False)
            text = (res.stdout + res.stderr).strip()
            if "nothing to commit" in text or "no changes added" in text:
                return "nothing to commit"
            first = next((l.strip() for l in text.splitlines() if l.strip()),
                         "git commit failed")
            if refused_add and refused_add != first:
                # The commit's own complaint about a path a refused `add`
                # never staged — "pathspec … did not match" for a file this
                # verb has just created — names the casualty; the add's names
                # the cause, a held index.lock say, which is what a person has
                # to fix before the re-run (issue #312).
                first = f"{first} (git add: {refused_add})"
            print(f"aide: could not commit {joined} — {first}", file=sys.stderr)
            return first
        # One path per line, never whitespace-split: a `docs_dir` with a space
        # in it must match its own entry. `core.quotepath=false` keeps a
        # non-ASCII path literal rather than octal-escaped and quoted.
        # `--relative`: *rels* are relative to repo_root, which may sit below
        # git's top level (issue #352), and git names paths from the top.
        out = git(["-c", "core.quotepath=false", "show", "--name-only",
                   "--relative", "--format=", "HEAD"], repo_root,
                  check=False).stdout
        shown = [line.strip() for line in out.splitlines() if line.strip()]
        missing = [r for r in rels if r not in shown]
        if missing:
            # `add` was refused (an ignored path, say) and `commit -- <path>`
            # then committed the rest of the list: a commit happened, the file
            # is not in it, and "committed" would be a lie about the one path
            # that matters. Printed as well as returned, like every other
            # arm: not every caller prints the return, and `insights archive`
            # reaches this with the archive file it just created.
            reason = f"{', '.join(missing)} is not in the commit (ignored by .gitignore?)"
            print(f"aide: {reason}", file=sys.stderr)
            return reason
        mode = str(config["git"].get("mode", "auto-merge"))
        if not pull or mode == "local" or not _has_origin(repo_root):
            return None
        if _has_unpushed_merge(repo_root):
            return None
        pulled = git(["pull", "--rebase"], repo_root, check=False)
    except (OSError, subprocess.SubprocessError, MissingTool) as exc:
        # Loud here, not only in the return: the best-effort callers discard
        # the reason, and a verb that prints its success line over an
        # uncommitted edit is the failure this names.
        why = f"git could not be run ({exc.__class__.__name__}: {exc})"
        print(f"aide: could not commit {joined} — {why}", file=sys.stderr)
        return why
    stalled = _stalled_pull(repo_root, config, pulled)
    if stalled is not None:
        # The commit exists and is being replayed; the tree is now mid-rebase
        # and the next verb will meet it. Said in full, because
        # `_commit_or_restore` quotes only the reason and the one verb that ends the usual case
        # (`insights resolve`) is named inside `stalled`.
        print(f"aide: {joined} is committed here, but replaying that commit "
              f"onto origin stopped: {stalled}", file=sys.stderr)
        return stalled
    if pulled.returncode != 0:
        # Non-zero with the tree untouched: unstaged changes beside the tick
        # (git refuses to start over ANY of them), an origin that cannot be
        # reached, a branch with no upstream. The commit is complete and
        # local, so this is a notice rather than a reason — but a silent one
        # would have the docstring promising a convergence that did not
        # happen, which is the state issue #180 was filed on.
        why = next((l.strip() for l in (pulled.stderr + pulled.stdout).splitlines()
                    if l.strip()), "git gave no reason")
        print(f"aide: {joined} is committed here but NOT rebased onto origin — "
              f"{why}. The commit is in this repository only until a later "
              f"pull or push settles it.", file=sys.stderr)
    return None


def insights_path(ddir: Path) -> Path:
    """The live inbox. One name, one place — see ``queue_name``/``item_spec_paths``."""
    return ddir / "insights.md"


#: The engine's own templates — installed as ``.aide/templates/`` beside
#: ``.aide/scripts/``, and laid out the same way in the framework's source tree,
#: so one relative step serves both. Module-level so a test can point it at a
#: directory with no template in it.
_TEMPLATES_DIR = Path(__file__).resolve().parents[1] / "templates"


def ensure_insights_inbox(repo_root: Path, config: Dict[str, Dict[str, object]],
                          verb: str, commit: bool = True) -> Optional[Path]:
    """Create ``insights.md`` from the template when the document set has none.

    Returns the path when a file was created, ``None`` otherwise. Idempotent
    and deliberately narrow: an existing file is never touched (not even a
    malformed one — the immutability rule, conventions.md §1), and a repo with
    no ``docs_dir`` gets nothing, since a project may adopt the CLI without
    the loop and the directory itself is project-owned.

    This is the engine's side of the §1 guarantee that capture — `insights
    add`, or a line of the same shape written by hand — appends to a file
    that exists. Before it, every agent spec told the role to
    copy the template by hand the first time an insight needed a home — six
    restatements of one step, and the one that made every spec name
    ``templates/`` (issue #85). The copy is byte-exact: ``read_bytes`` /
    ``write_bytes`` carries a BOM or CRLF the installer may have written
    through unchanged.

    The file is committed (named path, no pull) when *commit* is set and the
    repo is one: ``aide sync`` refuses a dirty tree, so a creation left
    untracked would stall the next preflight of the very loop it serves.
    Two cases decline the commit and say so in the notice rather than
    pretend: a detached ``HEAD``, where the commit would dangle and the file
    vanish on the next checkout; and a commit git refuses or cannot run (no
    identity on a fresh clone, ``git`` off PATH) — the file then stays
    untracked and the reason is printed, for the next write verb to carry.
    In a repository with no commits yet the inbox becomes the root commit;
    that is the scaffold-time ``check`` the quickstart mandates, and a root
    commit is a fine place for a file the loop owns.
    """
    ddir = docs_dir(repo_root, config)
    if not ddir.is_dir():
        return None
    path = insights_path(ddir)
    if path.exists():
        return None
    template = _TEMPLATES_DIR / "insights.md"
    rel = _rel_display(path, repo_root)
    if not template.is_file():
        print(f"aide {verb}: {rel} is missing and could not be created — "
              f"{_rel_display(template, repo_root)} is not there, so the install "
              f"is incomplete (`{printed_python(repo_root)} install.py --into . "
              f"--check` from a "
              f"framework checkout says how)", file=sys.stderr)
        return None
    path.write_bytes(template.read_bytes())
    fate = ""
    if not commit:
        fate = ", left uncommitted (--no-commit)"
    elif _git_unavailable(repo_root) is not None:
        # Created whatever git's state: the inbox is a file `check` makes on
        # its caller's behalf, and a missing git is the notice's reason, never
        # the run's failure (issue #352).
        why = _git_unavailable(repo_root)
        fate = (f" but NOT committed — {why}; commit it with the "
                "next work" if _dot_git_at_or_above(repo_root)
                else f", left untracked — {why}")
    elif _commits_here(False, repo_root, {path: None}):
        why = _commit_created_file(repo_root, config, rel)
        fate = (" and committed it" if why is None
                else f" but NOT committed — {why}; commit it with the next work")
    print(f"notice: created {rel} from .aide/templates/insights.md{fate} — the "
          f"insight inbox, which `insights add` captures into (conventions.md §1)")
    return path


def _commit_created_file(repo_root: Path, config, rel: str) -> Optional[str]:
    """Commit the inbox `ensure_insights_inbox` just wrote — or say why not.

    ``None`` on success, else the reason, in the same shape
    ``_commit_docs_files`` returns. The detached-``HEAD`` check lives here and
    not in the shared committer because it is a policy for a *new* file: a
    commit would succeed, dangle, and take the file with it on the next
    checkout while every message reported success.
    """
    try:
        on_branch = git(["symbolic-ref", "-q", "HEAD"], repo_root,
                        check=False).returncode == 0
    except (OSError, subprocess.SubprocessError) as exc:
        return f"git could not be run ({exc.__class__.__name__}: {exc})"
    if not on_branch:
        return "HEAD is detached, so the commit would dangle"
    return _commit_docs_files(repo_root, config, "docs(aide): create the insight inbox",
                              [rel], pull=False)


def insight_archive_path(ddir: Path, quarter: str) -> Path:
    """``docs/aide/insights/archive-2026-Q3.md`` — one file per quarter.

    A directory sibling to the live file, not a suffix on it, so the live file
    keeps the exact name every role appends to and the archive can grow without
    that name ever changing.
    """
    return ddir / "insights" / f"archive-{quarter}.md"


_ARCHIVE_HEADER = (
    "# Insight Archive — {quarter}\n\n"
    "_Closed entries moved out of `insights.md` by `aide insights archive`._\n"
    "_Frozen: the claims are immutable and, unlike the live file, this one is_\n"
    "_not shape-checked — see `insight_warnings`._\n"
)


def cmd_insights(args: argparse.Namespace) -> int:
    """Read and maintain ``insights.md`` — the one living document with no verb.

    Every other document has the CLI doing its mechanical work; this one made
    each triage pass an agent reading and hand-parsing the whole file, which is
    the cost that kept triage getting deferred. ``add`` captures one entry in
    the §1 shape, ``list`` answers "what is outstanding" without loading the
    archive with it, ``tick`` performs the one in-place edit the immutability
    rule permits, ``archive`` keeps the live file the size of its working set,
    and ``resolve`` merges the file's one recurring conflict — two branches
    that each appended — without a hand ever retyping a claim.
    """
    import datetime as _dt
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    ddir = docs_dir(repo_root, config)
    path = insights_path(ddir)
    if args.claim is not None and args.action != "add":
        print(f"aide insights {args.action}: unexpected argument "
              f"{args.claim!r} — only add takes a claim", file=sys.stderr)
        return 2
    capture: Optional[str] = None
    if args.action == "add":
        # Refused before anything is created: a refusal writes nothing, the
        # inbox included.
        capture, problem = insight_capture_line(
            args.number, args.claim, args.provenance,
            _dt.date.today().isoformat(), _engine_stamp())
        if problem is not None:
            print(f"aide insights add: {problem}", file=sys.stderr)
            return 2
        if args.date is not None:
            print("aide insights add: --date is not taken — an entry is dated "
                  "the day it is captured", file=sys.stderr)
            return 2
    if args.action in ("list", "add"):
        # An empty backlog is an answer, not an error: `list` on a repo whose
        # document set has no inbox yet creates the inbox — the same way
        # `check` does — and reports it empty; `add` creates it to append to.
        # The other verbs edit an entry, and there is no entry to edit in a
        # file that does not exist.
        if not ddir.is_dir():
            what = "capture into" if args.action == "add" else "list"
            print(f"aide insights: no {_rel_display(ddir, repo_root)}/ — this "
                  f"repo has no AIDE document set, so there is no inbox to "
                  f"{what}", file=sys.stderr)
            return 2
        ensure_insights_inbox(repo_root, config, verb="insights",
                              commit=not args.no_commit)
    if not path.is_file():
        print(f"aide insights {args.action}: no {_rel_display(path, repo_root)} "
              f"— nothing to {args.action}; `aide check` creates the inbox "
              f"(conventions.md §1)", file=sys.stderr)
        return 2
    text = path.read_text(encoding=_ENCODING)
    ddir_rel = ddir.relative_to(repo_root).as_posix()

    if args.action == "add":
        return _cmd_insights_add(path, ddir, ddir_rel, repo_root, config, args,
                                 capture or "")
    if args.action == "list":
        return _cmd_insights_list(parse_insights(text), load_insight_pool(ddir), args)
    if args.action == "tick":
        return _cmd_insights_tick(path, text, ddir, ddir_rel, repo_root, config,
                                  args, _dt.date.today().isoformat())
    if args.action == "resolve":
        return _cmd_insights_resolve(path, text, ddir_rel, repo_root, args,
                                     _dt.date.today().isoformat())
    return _cmd_insights_archive(path, text, ddir, ddir_rel, repo_root, config, args)


def _render_insight(e: InsightEntry, label: str, iid: Optional[str],
                    trail: bool, where: str = "") -> None:
    if e.type is None:
        # Nothing parsed, so render the line as it stands rather than
        # dressing it in fields this listing only guessed at — no ID either,
        # since a line with no parsed claim has none.
        print(f"  {label} ?? {e.raw}{where}")
        return
    # The whole marker is reprinted verbatim: "where did this come from"
    # is half of what triage routes on, and a listing that drops it — or
    # re-derives it from the item number, which can only print back the
    # single-item form — sends the reader to the file it exists to replace.
    # The trailing note is reprinted for the same reason: it carries the
    # engine version a `framework` entry is triaged against, and triage
    # reads this listing rather than the file.
    prov = (f" *({e.source + ', ' if e.source else ''}{e.date}"
            f"{', ' + e.note if e.note else ''})*") if e.date else ""
    mark = "x" if e.ticked else " "
    print(f"  {label} {iid + ' ' if iid else ''}[{mark}] {e.type:<10} — "
          f"{e.text}{prov}{_INSIGHT_POINTER + e.pointer if e.pointer else ''}"
          f"{where}")
    if trail:
        for line in e.trail:
            print(f"        {line.strip()}")


def _cmd_insights_list(entries: List[InsightEntry],
                       pool: List[Tuple[str, InsightEntry]],
                       args: argparse.Namespace) -> int:
    if args.type and args.type not in _INSIGHT_TYPES:
        print(f"aide insights: --type must be one of {', '.join(_INSIGHT_TYPES)}",
              file=sys.stderr)
        return 2
    # IDs are computed over the inbox *and* its archives, so the one printed
    # here is the one `aide check` resolves — unambiguous across both.
    pool_ids = insight_ids([e for _, e in pool])
    live_ids = [i for (rel, _), i in zip(pool, pool_ids) if rel == "insights.md"]
    if args.number is not None:
        return _cmd_insights_list_one(args.number, entries, live_ids, pool,
                                      pool_ids, args)
    shown = [e for e in entries
             if (not args.open_only or not e.ticked)
             and (not args.type or e.type == args.type)]
    for e in shown:
        iid = live_ids[e.ordinal - 1] if e.ordinal <= len(live_ids) else None
        _render_insight(e, f"{e.ordinal:>3}.", iid, args.trail)
    open_entries = [e for e in entries if not e.ticked]
    by_type = {t: sum(1 for e in open_entries if e.type == t) for t in _INSIGHT_TYPES}
    breakdown = ", ".join(f"{n} {t}" for t, n in by_type.items() if n)
    malformed = sum(1 for e in entries if e.type is None)
    print(f"aide insights: {len(entries)} entr{'y' if len(entries) == 1 else 'ies'}, "
          f"{len(open_entries)} open"
          f"{' (' + breakdown + ')' if breakdown else ''}"
          f"{f'; {malformed} malformed — see `aide check`' if malformed else ''}")
    if len(shown) != len(entries):
        print(f"aide insights: {len(shown)} shown by the filters given")
    return 0


def _cmd_insights_list_one(ref: str, entries: List[InsightEntry],
                           live_ids: List[Optional[str]],
                           pool: List[Tuple[str, InsightEntry]],
                           pool_ids: List[Optional[str]],
                           args: argparse.Namespace) -> int:
    """`insights list N|ID` — the one entry a citation names, trail included.

    An ID is looked up in the archives too, which is what makes a citation of
    an archived entry findable by a verb; a position only ever means the live
    file.
    """
    if ref.isdigit():
        try:
            e = _find_entry(entries, int(ref))
        except ValueError as exc:
            print(f"aide insights list: {exc}", file=sys.stderr)
            return 1
        _render_insight(e, f"{e.ordinal:>3}.", live_ids[e.ordinal - 1]
                        if e.ordinal <= len(live_ids) else None, True)
        return 0
    if not is_insight_id(ref):
        print(f"aide insights list: {ref!r} is neither an entry number nor an "
              f"insight ID (YYYY-MM-DD-<hex>)", file=sys.stderr)
        return 2
    hits = resolve_insight_ref(ref, [e for _, e in pool])
    if not hits:
        print(f"aide insights list: no entry {ref} in insights.md or its "
              f"archives", file=sys.stderr)
        return 1
    for i in hits:
        rel, e = pool[i]
        if rel == "insights.md":
            _render_insight(e, f"{e.ordinal:>3}.", pool_ids[i], True)
        else:
            _render_insight(e, "   -", pool_ids[i], True, f"  [{rel}]")
    if len({pool_ids[i] for i in hits}) > 1:
        print(f"aide insights list: {ref} matches more than one claim — cite "
              f"the longer ID of the one meant")
    return 0


def _cmd_insights_tick(path: Path, text: str, ddir: Path, ddir_rel: str,
                       repo_root: Path, config, args: argparse.Namespace,
                       today: str) -> int:
    if args.number is None:
        print("usage: aide insights tick N|ID --pointer TEXT", file=sys.stderr)
        return 2
    if not (args.pointer or "").strip():
        print("aide insights tick: --pointer says where the claim landed — a "
              "doc, an item, an issue. A tick without one records that triage "
              "happened and loses what it decided.", file=sys.stderr)
        return 2
    pool = load_insight_pool(ddir)
    try:
        ordinal = live_ordinal_for_ref(args.number, pool)
        updated, message = tick_insight_text(text, ordinal, args.pointer.strip(),
                                             args.date or today,
                                             trail_only=args.trail)
    except ValueError as exc:
        print(f"aide insights tick: {exc}", file=sys.stderr)
        return 1
    # The commit names the entry by its ID, which is what a reader of the log
    # can still find after an archive; a malformed line has none, so falls
    # back to the position it was ticked at.
    live_ids = [i for (rel, _), i in zip(pool, insight_ids([e for _, e in pool]))
                if rel == "insights.md"]
    handle = (live_ids[ordinal - 1] if ordinal <= len(live_ids) else None) or str(ordinal)
    before = _snapshot([path])
    path.write_text(updated, encoding="utf-8")
    print(f"{message} (insight {handle})" if handle != str(ordinal) else message)
    if _commits_here(args.no_commit, repo_root, before):
        return _commit_or_restore(
            repo_root, config, "aide insights tick", "the tick",
            f"docs(aide): triage insight {handle}",
            [f"{ddir_rel}/insights.md"], before)
    return 0


def _has_line_break(text: str) -> bool:
    """Would `str.splitlines` break *text*? It breaks on more than ``\n`` and
    ``\r`` (``\x0b``, ``\x0c``, ``\x1c``–``\x1e``, ``\x85``, U+2028,
    U+2029), and `parse_insights` reads the file through it, so any of them
    inside a claim would split one captured entry into two lines."""
    return len((text + "x").splitlines()) > 1


def insight_capture_line(type_: Optional[str], claim: Optional[str],
                         provenance: Optional[str], date: str,
                         stamp: Optional[str]) -> Tuple[str, Optional[str]]:
    """The entry line `insights add` writes, and why not when it cannot.

    ``(line, None)``, or ``("", reason)`` when the input is refused. The line
    is §1's shape — ``- [ ] <type> — <claim> *(<provenance>, <date>,
    <stamp>)*``, the provenance and the stamp each dropped with its comma
    when absent. Refused: a type §1 does not name, an empty claim, a line
    break in the claim or the provenance, and **any input whose line would
    read back as a different entry**. That last one is decided by parsing the
    line with `parse_insights` and comparing every field to what was given —
    not by a list of dangerous characters — so the refusal is exactly as wide
    as the reader: a provenance holding ``)`` (the marker would close early),
    a claim carrying an ``*(…, YYYY-MM-DD)*`` aside followed by ``→`` (read as
    the marker and a pointer), a claim or provenance the shape check would
    warn on. An aside the parser reads past is not refused: it reads back as
    written.
    """
    types = "|".join(_INSIGHT_TYPES)
    if type_ not in _INSIGHT_TYPES:
        what = f"{type_!r} is not" if type_ else "no type given; it must be"
        return "", f"{what} one of {types}"
    claim = (claim or "").strip()
    if not claim:
        return "", "the claim is empty — capture is one line of text"
    if _has_line_break(claim):
        return "", ("the claim contains a line break — an entry is one line, "
                    "so write it as one")
    prov = (provenance or "").strip() or None
    if prov is not None and _has_line_break(prov):
        return "", "--provenance contains a line break — it is part of one line"
    if prov is not None and ")" in prov:
        return "", ("--provenance contains ')', which would close the entry's "
                    "*(…)* marker early — write it without one")
    marker = ", ".join(x for x in (prov, date, stamp) if x)
    line = f"- [ ] {type_} — {claim} *({marker})*"
    parsed = parse_insights(line + "\n")
    want = {"type": type_, "claim": claim, "provenance": prov, "date": date,
            "engine note": stamp, "pointer": None}
    if len(parsed) != 1 or not _INSIGHT_RE.match(line):
        return "", ("the line would not read back as one well-formed entry — "
                    "an insights.md shape warning from the moment it landed")
    e = parsed[0]
    got = {"type": e.type, "claim": e.text, "provenance": e.source,
           "date": e.date, "engine note": e.note, "pointer": e.pointer}
    for field, value in want.items():
        if got[field] != value:
            return "", (f"the line would read back with its {field} as "
                        f"{got[field]!r}, not {value!r} — a `*(…, YYYY-MM-DD)*` "
                        f"aside in the claim, or a `)` in --provenance, is what "
                        f"does that; reword it")
    return line, None


def _append_line_bytes(path: Path, line: str) -> None:
    """Append *line* at the end of *path*, touching no byte already there.

    Bytes rather than text, so a BOM and the file's line endings survive: the
    new line ends with ``\r\n`` when the file already uses it, and a file
    whose last line has no newline gets one before the new line rather than
    the new line glued onto it. An empty file gets the line alone.
    """
    data = path.read_bytes()
    body = data[3:] if data.startswith(b"\xef\xbb\xbf") else data
    eol = b"\r\n" if b"\r\n" in body else b"\n"
    lead = eol if body and not body.endswith(b"\n") else b""
    with open(path, "ab") as fh:
        fh.write(lead + line.encode("utf-8") + eol)


def _cmd_insights_add(path: Path, ddir: Path, ddir_rel: str, repo_root: Path,
                      config, args: argparse.Namespace, line: str) -> int:
    """`insights add TYPE CLAIM [--provenance TEXT]` — capture one entry (#363).

    *line* was built and checked by ``insight_capture_line`` before the inbox
    was created, so nothing here can refuse. The entry is appended, its ID is
    printed — the one `insights list` would print, computed over the inbox
    and its archives so a same-day prefix clash is already lengthened — and
    the file is committed the way `tick` commits: by default, not under
    --no-commit, and on a failed commit the file is put back and the verb
    exits 1 (`_commit_or_restore`). The ID is printed only once the entry is
    certain to stay: after the commit, or under --no-commit — never for an
    entry the failed commit has just removed again.
    """
    text = path.read_text(encoding=_ENCODING)
    if any(rx.match(l) for l in text.splitlines() for rx in _CONFLICT_LINT_RES):
        # An entry appended below a conflict's closing marker is one more
        # line for `resolve` to place, and one the refusal there would name
        # as a change to the shared history.
        print(f"aide insights add: insights.md carries an unresolved git "
              f"conflict — run `{aide_command(repo_root, 'insights resolve')}` "
              f"first, then capture", file=sys.stderr)
        return 2
    before = _snapshot([path])
    _append_line_bytes(path, line)
    pool = load_insight_pool(ddir)
    live_ids = [i for (rel, _), i in zip(pool, insight_ids([e for _, e in pool]))
                if rel == "insights.md"]
    iid = live_ids[-1] if live_ids else None
    handle = iid or "(no ID)"
    if _commits_here(args.no_commit, repo_root, before):
        rc = _commit_or_restore(
            repo_root, config, "aide insights add", "the capture",
            f"docs(aide): capture insight {handle}",
            [f"{ddir_rel}/insights.md"], before)
        if rc != 0 and _snapshot([path]) == before:
            # Put back: there is no entry to cite, so no ID is printed.
            return rc
        if rc != 0:
            # Committed, but its replay onto origin stopped: the entry is in
            # a commit here, and its ID stands.
            print(f"aide insights add: captured insight {handle} — cite it "
                  f"by that ID")
            return rc
    print(f"aide insights add: captured insight {handle} — cite it by that ID")
    return 0


def archive_position_map(text: str, remaining: str) -> Dict[int, Optional[int]]:
    """Old live position → new live position (None: archived) for one archive.

    ``archive_insight_text`` only removes whole entries and never reorders, so
    the remaining entries are a subsequence of the original with their entry
    lines unchanged — a walk matching entry lines in order recovers where each
    one went. Only positions that change are returned: an entry above the
    first moved one keeps its number and every citation of it stays true.
    """
    before = parse_insights(text)
    after = parse_insights(remaining)
    out: Dict[int, Optional[int]] = {}
    j = 0
    for e in before:
        if j < len(after) and after[j].raw == e.raw:
            if after[j].ordinal != e.ordinal:
                out[e.ordinal] = after[j].ordinal
            j += 1
        else:
            out[e.ordinal] = None
    return out


def _print_invalidated_citations(text: str, remaining: str, ddir: Path,
                                 repo_root: Path, config, dry_run: bool) -> None:
    """List every positional citation this archive changes the meaning of.

    Each with the ID its position holds *before* the move, which is the
    mapping an author needs to rewrite it and the one thing the archive run is
    the last to know (issue #295). A warning, not a refusal: the listing
    itself preserves the mapping, and the move already waits on --yes.
    """
    shifted = archive_position_map(text, remaining)
    if not shifted:
        return
    pool = load_insight_pool(ddir)
    ids = insight_ids([e for _, e in pool])
    live_ids = [i for (rel, _), i in zip(pool, ids) if rel == "insights.md"]
    hits = [c for c in insight_position_citations(repo_root, config, ddir, len(pool))
            if c[3] in shifted]
    if not hits:
        return
    verb = "would renumber" if dry_run else "renumbers"
    print(f"aide insights archive: this archive {verb} {len(hits)} citation"
          f"{'' if len(hits) == 1 else 's'} by position — rewrite each as the "
          f"ID its position holds before the move (conventions.md §1 → "
          f"insights.md):")
    for where, lineno, cited, n in hits:
        iid = live_ids[n - 1] if n <= len(live_ids) else None
        dest = shifted[n]
        fate = "archived" if dest is None else f"entry {dest} after it"
        print(f"  {where}:{lineno}: `{cited}` is insight "
              f"{iid or '(no ID — the entry does not parse)'} before the move "
              f"({fate})")


def _cmd_insights_archive(path: Path, text: str, ddir: Path, ddir_rel: str,
                          repo_root: Path, config, args: argparse.Namespace) -> int:
    if not _DATE_RE.match(args.before or ""):
        print("usage: aide insights archive --before YYYY-MM-DD", file=sys.stderr)
        return 2
    remaining, moved, undatable = archive_insight_text(text, args.before)
    # Before the early return: an operator whose file will not shrink needs
    # this most in the run where nothing moved at all.
    for e in undatable:
        print(f"aide insights archive: entry {e.ordinal} "
              f"(insights.md:{e.lineno}) is closed but carries no readable "
              f"date, so no --before cut can move it: {e.raw!r}", file=sys.stderr)
    if undatable:
        print(f"aide insights archive: {len(undatable)} closed entr"
              f"{'y' if len(undatable) == 1 else 'ies'} could not be dated and "
              f"stay in the live file; `aide check` names the shape rule",
              file=sys.stderr)
    if not moved:
        print(f"aide insights: nothing closed before {args.before} to archive")
        return 0
    total = 0
    for quarter in sorted(moved):
        entries = sum(1 for ln in moved[quarter] if ln.startswith("- "))
        total += entries
        print(f"  {insight_archive_path(ddir, quarter).relative_to(repo_root).as_posix()}"
              f" ← {entries} closed entr{'y' if entries == 1 else 'ies'}")
    _print_invalidated_citations(text, remaining, ddir, repo_root, config,
                                 dry_run=not args.yes)
    if not args.yes:
        print(f"aide insights archive: dry run — {total} entr"
              f"{'y' if total == 1 else 'ies'} would move; re-run with --yes")
        return 0

    rels = [f"{ddir_rel}/insights.md"]
    before = _snapshot([path] + [insight_archive_path(ddir, q) for q in sorted(moved)])
    made_dir = not (ddir / "insights").is_dir()
    for quarter in sorted(moved):
        apath = insight_archive_path(ddir, quarter)
        apath.parent.mkdir(parents=True, exist_ok=True)
        body = "\n".join(moved[quarter]) + "\n"
        if apath.is_file():
            existing = apath.read_text(encoding=_ENCODING)
            apath.write_text(existing.rstrip("\n") + "\n" + body, encoding="utf-8")
        else:
            apath.write_text(_ARCHIVE_HEADER.format(quarter=quarter) + "\n" + body,
                             encoding="utf-8")
        rels.append(apath.relative_to(repo_root).as_posix())
    path.write_text(remaining, encoding="utf-8")
    print(f"aide insights archive: moved {total} entr{'y' if total == 1 else 'ies'}; "
          f"{len(parse_insights(remaining))} remain — their list numbers have shifted")
    if _commits_here(args.no_commit, repo_root, before):
        code = _commit_or_restore(
            repo_root, config, "aide insights archive", "the archive",
            f"docs(aide): archive insights closed before {args.before}",
            rels, before)
        if code and made_dir:
            # The first archive made `insights/` to hold it; a restore that
            # removed the file takes the directory too, if nothing else is in
            # it. A no-op when the archive was committed.
            try:
                (ddir / "insights").rmdir()
            except OSError:
                pass
        return code
    return 0


def _is_unmerged(repo_root: Path, rel: str) -> bool:
    """Does git hold *rel* unmerged in the index — i.e. is it still conflicted?

    Kept apart from `_merge_base_text` because the two questions have different
    answers on an **add/add** conflict, where both branches created the file:
    the index then holds stages 2 and 3 and **no stage 1**, so the merge base
    is genuinely absent while the path is very much unmerged. That shape is
    routine here — `check`, `claim` and `queue start` each create the inbox
    from the template when it is missing — and conflating the two made the
    verb decline to stage exactly the conflict a consumer hits first.

    Outside a repository, no. A git that is not there, or refuses the
    repository, is `in_repository`'s `MissingTool`, not an answer here.
    """
    if not in_repository(repo_root):
        return False
    out = git(["ls-files", "-u", "--", rel], repo_root, check=False)
    return out.returncode == 0 and bool(out.stdout.strip())


def _merge_base_text(repo_root: Path, rel: str) -> Optional[str]:
    """Stage 1 of *rel* — the merge base of a stalled merge or rebase, or None.

    What turns the resolver's append check from an inference into a fact.
    ``None`` covers every way it can be absent: no repository, no conflict,
    or an add/add conflict that has no base at all, and the resolver then
    falls back to comparing the two sides alone. A git that is not there is
    not one of them: `_is_unmerged` raises `MissingTool` first (issue #352).
    """
    if not _is_unmerged(repo_root, rel):
        return None
    out = git(["show", f":1:./{rel}"], repo_root, check=False)
    return out.stdout if out.returncode == 0 else None


def _cmd_insights_resolve(path: Path, text: str, ddir_rel: str, repo_root: Path,
                          args: argparse.Namespace, today: str) -> int:
    """Resolve a conflicted inbox as the union of both sides' entries.

    The verb exists because the alternative is an agent retyping the block, and
    that is exactly where conventions.md §1's "never reword a captured claim"
    gets broken — the merge conflict is the one moment the whole file is in
    front of something willing to rewrite it.
    """
    rel = f"{ddir_rel}/insights.md"
    if not any(rx.match(line) for line in text.splitlines()
               for rx in _CONFLICT_LINT_RES):
        if not _is_unmerged(repo_root, rel):
            print(f"aide insights resolve: no conflict markers in {rel} — "
                  f"nothing to resolve")
            return 0
        # Markers gone but the path still unmerged: someone resolved the file
        # by hand and stopped short of staging it. Finishing that is the same
        # end state this verb reaches on its own, and leaving it undone is how
        # an unattended run stalls on `git commit` with nothing in the message
        # naming the cause.
        add = git(["add", "--", rel], repo_root, check=False)
        if add.returncode != 0:
            print(f"aide insights resolve: {rel} has no conflict markers but "
                  f"git still holds it unmerged, and staging it failed "
                  f"({add.stderr.strip()}) — `git add {rel}` before continuing",
                  file=sys.stderr)
            return 1
        print(f"aide insights resolve: no conflict markers in {rel}, but git "
              f"still held it unmerged — staged it as it stands, so the merge "
              f"or rebase can continue. Nothing was rewritten; if a claim was "
              f"reworded resolving it by hand, §1 says that is the thing to "
              f"look at.")
        return 0
    base = _merge_base_text(repo_root, rel)
    merged, notes, refusals = resolve_insights_text(text, args.date or today, base)
    if refusals:
        for why in refusals:
            print(f"aide insights resolve: {why}", file=sys.stderr)
        print(f"aide insights resolve: {rel} left exactly as it is — the "
              f"markers are still in place and the claims are still both "
              f"there", file=sys.stderr)
        return 1
    for note in notes:
        print(f"  {note}")
    if args.dry_run:
        # The union itself, not just the counts: reviewing the merge before it
        # is written is the whole of what --dry-run is for, and every place
        # that documents the flag says it prints what would be written.
        print(f"--- {rel} would become ---")
        print(merged, end="" if merged.endswith("\n") else "\n")
        print(f"aide insights resolve: dry run — {rel} not written")
        return 0
    path.write_text(merged, encoding="utf-8")
    staged = ""
    # Asked again rather than inferred from `base`: an add/add conflict has no
    # merge base and is still unmerged, and writing the file does not touch the
    # index, so this is the same answer it would have given a moment ago.
    if _is_unmerged(repo_root, rel):
        add = git(["add", "--", rel], repo_root, check=False)
        staged = (" and staged it, so the conflict is marked resolved; finish "
                  "the merge or rebase as usual"
                  if add.returncode == 0 else
                  f" but could NOT stage it ({add.stderr.strip()}) — `git add "
                  f"{rel}` before continuing")
    print(f"aide insights resolve: wrote {rel} as the union of both sides"
          f"{staged}")
    return 0


# --------------------------------------------------------------------------- #
# ledger — one row per item worked (§1 → ledger.md)
# --------------------------------------------------------------------------- #
#: The row, in the order `.aide/templates/ledger.md` draws it. The template is
#: the shape's executable statement (§1) and this tuple is what writes it, so
#: the two move together: a column added here is a column added there, and
#: `test_aide_ledger.py` holds the pair.
LEDGER_COLUMNS = ("Item", "Queue", "Stage", "Kind", "Outcome", "ACs", "Tests",
                  "Files", "Rounds", "Blocking", "Minor", "Nit", "Engine",
                  "Date", "Suite s", "Inherited")
#: How many of those a row written under `ledger template 2` carries — every
#: column up to `Date`. Such a row is still a whole row (§1 → `ledger.md`):
#: the two columns after it were appended in 2.7.0 (issue #275), a row is
#: never edited, and a reader reads a missing trailing cell as a blank one.
LEDGER_TEMPLATE_2_WIDTH = 14
#: Cells whose value is an integer or nothing at all — what `ledger_warnings`
#: reads, and the blank-cell rule's whole surface.
LEDGER_INTEGER_COLUMNS = ("ACs", "Tests", "Files", "Rounds", "Blocking",
                          "Minor", "Nit", "Suite s", "Inherited")
#: What follows a `Suite s` cell's seconds where `aide merge` took the run
#: `aide test` recorded rather than running the suite (§1 → ledger.md): the
#: seconds are that run's, and the mark says whose.
LEDGER_REUSED_SUFFIX = " (reused)"
#: The three ranks `--findings` accepts, in the order they are written.
LEDGER_FINDING_RANKS = ("blocking", "minor", "nit")
#: What the three finding cells hold where the project runs with no reviewer
#: at all (§1 → `ledger.md`): not a count, and not the absence of one either.
#: It is the engine's own answer, read from `[loop] review`, so a blank in
#: those three columns means exactly one thing — a count that should have been
#: passed and was not.
LEDGER_NO_REVIEW_CELL = "-"
#: How an item left the loop: `merge` writes one, `ledger abandon` the other.
LEDGER_OUTCOMES = ("merged", "abandoned")
#: An item cell: the zero-padded number the verbs write, and anything a reader
#: can resolve to an item.
_LEDGER_ITEM_RE = re.compile(r"^0*\d+$")
#: A queue-end item, titled `Validate stage N` (§1 → queue-NNN.md) — test-heavy
#: by design, so it is its own `kind` (§1 → ledger.md), and the one test
#: `queue_end_stages` reads too. Read off the item's title, which is the only place the
#: engine ever learns what an item is: the spec's `# Item NNN — <title>` line,
#: or the queue's `### Item NNN: <title>` where no spec is left.
_VALIDATE_STAGE_TITLE_RE = re.compile(r"^\s*validate\s+stage\b", re.IGNORECASE)
#: The three insight types that become a maintenance item (§1 → the
#: maintenance queue); a `knowledge` or `framework` entry never does.
_LEDGER_MAINTENANCE_TYPES = ("defect", "gap", "automation")


def ledger_path(ddir: Path) -> Path:
    """The run ledger. One name, one place — see ``insights_path``."""
    return ddir / "ledger.md"


def review_is_off(config: Dict[str, Dict[str, object]]) -> bool:
    """Whether `[loop] review` leaves this project with no reviewer at all.

    The one reader of that key in the engine (§9 is prose the orchestrator
    consumes), and the one thing the ledger needs from it: anything other than
    the default `"off"` means some adversarial read runs, so a blank finding
    cell is a count that was not passed rather than a review that never
    happened.
    """
    return str(config.get("loop", {}).get("review", "off")).strip().lower() == "off"


def parse_findings(value: str) -> Dict[str, int]:
    """``"blocking=1,minor=2"`` -> ``{"blocking": 1, "minor": 2}``.

    Strict, and strict on purpose: the counts are a claim the caller makes
    about work the engine cannot see (§1 → `ledger.md`), so the one thing this
    must never do is guess. Every rank is optional and the order is free; an
    unknown rank, a repeated one, a missing `=` and a value that is not a
    non-negative integer are each a usage error naming what was wrong, because
    a mistyped rank silently dropped would record a blank where a count was
    passed. Raises ``ValueError``; the parser turns it into argparse's usage
    error.
    """
    counts: Dict[str, int] = {}
    ranks = ", ".join(LEDGER_FINDING_RANKS)
    for part in value.split(","):
        part = part.strip()
        if not part:
            raise ValueError(
                f"empty entry in '{value}' — write <rank>=<count> pairs "
                f"separated by commas, with the ranks you have ({ranks})")
        rank, sep, count = part.partition("=")
        rank = rank.strip().lower()
        if not sep:
            raise ValueError(f"'{part}' is not <rank>=<count>")
        if rank not in LEDGER_FINDING_RANKS:
            raise ValueError(f"unknown rank '{rank}' — one of {ranks}")
        if rank in counts:
            raise ValueError(f"rank '{rank}' given twice")
        count = count.strip()
        if not re.fullmatch(r"[0-9]+", count):
            raise ValueError(
                f"'{rank}={count}' is not a non-negative integer")
        counts[rank] = int(count)
    return counts


def _findings_argument(value: str) -> Dict[str, int]:
    try:
        return parse_findings(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _non_negative_argument(value: str) -> int:
    if not re.fullmatch(r"[0-9]+", value.strip()):
        raise argparse.ArgumentTypeError(
            f"'{value}' is not a non-negative integer")
    return int(value.strip())


def _item_queue_number(repo_root: Path, config, number: int) -> Optional[int]:
    """The queue whose file lists item *number*, or ``None``."""
    qdir = docs_dir(repo_root, config) / "queue"
    if not qdir.is_dir():
        return None
    for qpath in iter_queue_paths(qdir):
        try:
            text = qpath.read_text(encoding=_ENCODING)
        except (OSError, UnicodeDecodeError):
            continue
        if number in queue_item_numbers(text):
            return queue_number(qpath)
    return None


def _queue_item_title(repo_root: Path, config, number: int) -> Optional[str]:
    """The item's title as its queue file writes it, or ``None``."""
    qdir = docs_dir(repo_root, config) / "queue"
    if not qdir.is_dir():
        return None
    for qpath in iter_queue_paths(qdir):
        try:
            title = _queue_titles(qpath.read_text(encoding=_ENCODING)).get(number)
        except (OSError, UnicodeDecodeError):
            continue
        if title:
            return title
    return None


def _insight_derived_item(repo_root: Path, config, number: int) -> bool:
    """Did an insight become item *number*?

    §1 → the maintenance queue: the author who queues an open `defect`, `gap`
    or `automation` entry ticks it with the item number it became
    (`insights tick N --pointer "item NNN"`), so the inbox is where the engine
    can read that an item is insight-derived. The pointer and the entry's trail
    are read; its **provenance** deliberately is not — that names the item the
    insight was captured *in*, which is the opposite claim.
    """
    path = insights_path(docs_dir(repo_root, config))
    if not path.is_file():
        return False
    try:
        entries = parse_insights(path.read_text(encoding=_ENCODING))
    except (OSError, UnicodeDecodeError):
        return False
    for entry in entries:
        if entry.type not in _LEDGER_MAINTENANCE_TYPES:
            continue
        for text in ([entry.pointer] if entry.pointer else []) + list(entry.trail):
            if _references_item(text, number):
                return True
    return False


def item_kind(repo_root: Path, config, number: int,
              title: Optional[str] = None) -> str:
    """The item's `kind` cell: one of `validate-stage`, `maintenance`, `normal`.

    `validate-stage` wins over `maintenance`, because it is the reading that
    changes how every other cell on the row is read: such an item exists to
    add tests, so its tests-per-criterion is not comparable with anything
    else's whatever else the item also is.
    """
    if title is None:
        title = (_spec_stage_and_title(repo_root, config, number)[1]
                 or _queue_item_title(repo_root, config, number))
    if title and _VALIDATE_STAGE_TITLE_RE.match(title):
        return "validate-stage"
    if _insight_derived_item(repo_root, config, number):
        return "maintenance"
    return "normal"


def _ledger_diff_cells(repo_root: Path, config, number: int,
                       branch: Optional[str],
                       base: Optional[str]) -> Tuple[str, str]:
    """``(tests added, files changed)`` for item *number*'s *branch* against
    *base*.

    Both blank when the diff cannot be taken — no branch left, no base
    recorded, a ref git cannot resolve. The counting is `aide scope`'s
    (`added_test_functions`), read from the branch tip rather than the working
    tree so the answer does not depend on what happens to be checked out; and
    so is the split — a test `aide scope` reports as reconciled in another
    item's test file (`split_reconciled_tests`) is that item's, not a test
    this one added.
    """
    if not branch or not base:
        return "", ""
    mb = git(["merge-base", base, branch], repo_root, check=False)
    if mb.returncode != 0:
        return "", ""
    merge_base = mb.stdout.strip()
    diff = git(["-c", "core.quotePath=false", "diff", "--name-only",
                merge_base, branch], repo_root, check=False)
    if diff.returncode != 0:
        return "", ""
    changed = root_relative(repo_root, [line.strip() for line in
                                        diff.stdout.splitlines() if line.strip()])
    added = added_test_functions(repo_root, config, changed, merge_base,
                                 renamed_paths(repo_root, merge_base), ref=branch)
    own, others = split_reconciled_tests(repo_root, config, added, number)
    tests = len(own) + sum(len(o.untraced) for o in others.values())
    return str(tests), str(len(changed))


def ledger_cells(repo_root: Path, config, number: int, outcome: str,
                 rounds: Optional[int] = None,
                 findings: Optional[Dict[str, int]] = None,
                 branch: Optional[str] = None,
                 base: Optional[str] = None,
                 date: Optional[str] = None,
                 no_review: bool = False,
                 suite_seconds: Optional[int] = None,
                 inherited: Optional[int] = None) -> List[str]:
    """One row's cells, in `LEDGER_COLUMNS` order.

    Everything but *rounds* and *findings* is derived here, from the documents,
    the branch and `.aide/VERSION`; those two are the caller's, and an absent
    one is a blank cell rather than a zero (§1 → `ledger.md`). Every derivation
    degrades to a blank: a spec that is gone, a queue that never listed the
    item, a stage the spec header does not name and a diff with no branch to
    take it from each cost one cell, never the row.
    """
    import datetime as _dt
    findings = findings or {}
    stage, title = _spec_stage_and_title(repo_root, config, number)
    specs = item_spec_paths(docs_dir(repo_root, config) / "items", number)
    criteria = ""
    if specs:
        try:
            spec_text = specs[0].read_text(encoding=_ENCODING)
        except (OSError, UnicodeDecodeError):
            spec_text = ""
        if _AC_HEADING_RE.search(spec_text):
            criteria = str(len(spec_acceptance_numbers(spec_text)))
    queue = _item_queue_number(repo_root, config, number)
    tests, files = _ledger_diff_cells(repo_root, config, number, branch, base)
    cells = {
        "Item": f"{number:03d}",
        "Queue": f"{queue:03d}" if queue is not None else "",
        "Stage": stage or "",
        "Kind": item_kind(repo_root, config, number, title),
        "Outcome": outcome,
        "ACs": criteria,
        "Tests": tests,
        "Files": files,
        "Engine": installed_engine_version() or "",
        "Date": date or _dt.date.today().isoformat(),
        "Suite s": "" if suite_seconds is None else str(suite_seconds),
        "Inherited": "" if inherited is None else str(inherited),
    }
    cells.update(zip(LEDGER_COUNT_COLUMNS,
                     _ledger_count_cells(rounds=rounds, findings=findings,
                                         no_review=no_review)))
    return [cells[column] for column in LEDGER_COLUMNS]


#: The caller-supplied cells, in the order `_ledger_count_cells` renders them.
LEDGER_COUNT_COLUMNS = ("Rounds",) + tuple(r.capitalize() for r in LEDGER_FINDING_RANKS)
#: Those of them that count findings — the three that may carry the no-review
#: marker, named once so `ledger_warnings` and the renderer cannot disagree.
LEDGER_FINDING_COLUMNS = tuple(r.capitalize() for r in LEDGER_FINDING_RANKS)


def _ledger_count_cells(rounds: Optional[int],
                        findings: Optional[Dict[str, int]],
                        no_review: bool = False) -> List[str]:
    """Render the caller's counts — a count nobody passed is `""`, never `0`.

    *no_review* is the project's `[loop] review` read as "off": with no
    reviewer in the loop there are no findings to count, so the three rank
    cells carry `LEDGER_NO_REVIEW_CELL` instead of the blank that would read
    as a count somebody forgot. Counts passed anyway win over it, whole — a
    count is a claim its caller made, and the engine records claims rather
    than correcting them from the configuration.
    """
    findings = findings or {}
    absent = LEDGER_NO_REVIEW_CELL if (no_review and not findings) else ""
    out = ["" if rounds is None else str(rounds)]
    for rank in LEDGER_FINDING_RANKS:
        got = findings.get(rank)
        out.append(absent if got is None else str(got))
    return out


def ledger_row(cells: List[str]) -> str:
    """The cells as the one line appended to the ledger."""
    return "| " + " | ".join(cells) + " |"


def append_ledger_row(repo_root: Path, config, cells: List[str],
                      verb: str) -> Optional[str]:
    """Append one row, creating the ledger from the template if it is missing.

    Returns the repo-relative path of the file written, so the caller can put
    it in the commit that records the item — or ``None`` when there is nowhere
    to write: a repo with no ``docs_dir`` (a project may adopt the CLI without
    the loop) or an install whose template is gone. Both say why. Raises
    nothing else on purpose: every caller is a verb whose real work has
    already succeeded.
    """
    ddir = docs_dir(repo_root, config)
    if not ddir.is_dir():
        print(f"aide {verb}: no {_rel_display(ddir, repo_root)} directory, so "
              f"no ledger row was recorded", file=sys.stderr)
        return None
    path = ledger_path(ddir)
    rel = _rel_display(path, repo_root)
    if not path.exists():
        template = _TEMPLATES_DIR / "ledger.md"
        if not template.is_file():
            print(f"aide {verb}: {rel} is missing and could not be created — "
                  f"{_rel_display(template, repo_root)} is not there, so the "
                  f"install is incomplete (`{printed_python(repo_root)} "
                  f"install.py --into . --check` "
                  f"from a framework checkout says how)", file=sys.stderr)
            return None
        path.write_bytes(template.read_bytes())
        print(f"notice: created {rel} from .aide/templates/ledger.md — the run "
              f"ledger, one row per item worked (conventions.md §1)")
    text = path.read_text(encoding=_ENCODING)
    if text and not text.endswith("\n"):
        text += "\n"
    path.write_text(text + ledger_row(cells) + "\n", encoding="utf-8")
    return rel


def _merged_row_already_recorded(repo_root: Path, config, number: int,
                                 cells: List[str]) -> Optional[str]:
    """``ledger.md:<line>`` of the row an earlier merge of this item wrote, or None.

    Only where the item is **already ✅** on every bullet before this run
    ticks it (issue #346): a merge whose tick commit landed and whose push
    failed is re-run with the ✅ and the row both in place, and a second row
    would be a second record of one merge. A reopened item is never ✅ when it merges again —
    `progress reopen` sends every bullet back to 📋 — so the second row §1 →
    `ledger.md` expects for it is appended as before; so is the first row of
    an item ticked by hand ahead of its merge, since there is no `merged` row
    for it to find. Matched on the item and its queue, as the row records
    them.
    """
    ddir = docs_dir(repo_root, config)
    progress, path = ddir / "progress.md", ledger_path(ddir)
    if not (progress.is_file() and path.is_file()):
        return None
    try:
        lines = progress.read_text(encoding=_ENCODING).splitlines()
        rows = ledger_rows(path.read_text(encoding=_ENCODING))
    except (OSError, UnicodeDecodeError):
        return None
    # Every bullet ✅, not the most advanced one `_parse_item_status` reports:
    # a reopened item with one bullet ticked by hand is still owed its row.
    statuses = [ICON_TO_STATUS[_BULLET_RE.match(lines[start]).group("icon")]
                for start, last in _deliverable_bullet_spans(lines)
                if number in _bullet_marker_item_numbers(lines[last])]
    if not statuses or any(st != "complete" for st in statuses):
        return None
    want = dict(zip(LEDGER_COLUMNS, cells))
    for lineno, row_cells in rows:
        row = dict(zip(LEDGER_COLUMNS, row_cells))
        if (row.get("Item") == want["Item"] and row.get("Outcome") == "merged"
                and row.get("Queue", "") == want["Queue"]):
            return f"{path.name}:{lineno}"
    return None


def ledger_rows(text: str) -> List[Tuple[int, List[str]]]:
    """``(lineno, cells)`` for every data row of a ledger — the one reader.

    Table furniture is skipped, and so is **everything inside an HTML
    comment**: the document is created as a byte-exact copy of the template,
    whose header comment draws the row it is about to write, so a reader that
    took any `|` line for data would read that example as an item. The
    comment is the author's to delete and most never do, which makes this the
    ordinary case rather than the odd one.
    """
    out: List[Tuple[int, List[str]]] = []
    in_comment = False
    for lineno, line in enumerate(text.splitlines(), start=1):
        rest = line
        while rest:
            if in_comment:
                _, sep, rest = rest.partition("-->")
                if not sep:
                    rest = ""
                in_comment = bool(not sep)
            else:
                before, sep, rest = rest.partition("<!--")
                if not sep:
                    rest = ""
                else:
                    in_comment = True
                if before.strip().startswith("|"):
                    cells = _split_row(before)
                    if not _is_table_furniture(cells, LEDGER_COLUMNS[0].lower()):
                        out.append((lineno, cells))
                if not sep:
                    break
    return out


def ledger_warnings(ddir: Path) -> List[str]:
    """Rows of `ledger.md` no reader can use — warnings, never errors.

    Capture has to stay cheap: the file records work that is already finished,
    so a mis-shaped row is worth reporting and never worth failing a run over
    — and a row nobody can fix without rewriting a record is exactly the kind
    of finding that teaches a reader to skim (§1 → `ledger.md`, and rung 4 of
    the copies rule: `docs/aide/**` is the project's). An absent file is
    silent: a project that has not merged an item through the engine has no
    ledger, and that is not a defect.
    """
    path = ledger_path(ddir)
    if not path.is_file():
        return []
    out: List[str] = []
    for lineno, cells in ledger_rows(path.read_text(encoding=_ENCODING)):
        if len(cells) not in (len(LEDGER_COLUMNS), LEDGER_TEMPLATE_2_WIDTH):
            out.append(f"ledger.md:{lineno}: {len(cells)} cell(s), not "
                       f"{len(LEDGER_COLUMNS)} — the columns "
                       f"`.aide/templates/ledger.md` draws (a row written "
                       f"under ledger template 2 has "
                       f"{LEDGER_TEMPLATE_2_WIDTH}, and is read as it stands)")
            continue
        row = dict(zip(LEDGER_COLUMNS, cells))
        if not _LEDGER_ITEM_RE.match(row["Item"]):
            out.append(f"ledger.md:{lineno}: Item cell '{row['Item']}' is not "
                       f"an item number")
        if row["Outcome"] not in LEDGER_OUTCOMES:
            out.append(f"ledger.md:{lineno}: Outcome cell "
                       f"'{row['Outcome']}' is not one of "
                       f"{', '.join(LEDGER_OUTCOMES)}")
        for column in LEDGER_INTEGER_COLUMNS:
            value = row.get(column, "")
            # The three finding columns may also carry the no-review marker,
            # which the writing verbs put there themselves (§1 → ledger.md).
            if (value == LEDGER_NO_REVIEW_CELL
                    and column in LEDGER_FINDING_COLUMNS):
                continue
            if (column == "Suite s"
                    and re.fullmatch(r"[0-9]+" + re.escape(LEDGER_REUSED_SUFFIX),
                                     value)):
                continue
            if value and not re.fullmatch(r"[0-9]+", value):
                out.append(f"ledger.md:{lineno}: {column} cell '{value}' is "
                           f"neither an integer nor blank")
    return out


#: Which of `ledger`'s options each action reads; one given to the other action
#: is a usage error, never silently ignored — `report --rounds 3` must not read
#: as though it recorded something (the `_QUEUE_OPTIONS` reasoning).
_LEDGER_OPTIONS = {
    "abandon": {"number", "rounds", "findings", "no_commit"},
    "report": {"queue", "as_json"},
}


def cmd_ledger(args: argparse.Namespace) -> int:
    """Write a ledger row for an item no merge will ever write one for, or
    report on the rows already written."""
    stray = sorted(opt for action, opts in _LEDGER_OPTIONS.items()
                   if action != args.action for opt in opts
                   if getattr(args, opt, None) is not None
                   and getattr(args, opt, None) is not False)
    if stray:
        names = ", ".join("<number>" if o == "number" else
                          "--json" if o == "as_json" else
                          "--" + o.replace("_", "-") for o in stray)
        verb = "does" if len(stray) == 1 else "do"
        print(f"aide ledger {args.action}: {names} {verb} not belong to "
              f"{args.action}, which does not read it", file=sys.stderr)
        return 2
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    if args.action == "report":
        return _ledger_report_command(repo_root, config, args)
    if args.number is None:
        print(f"aide ledger {args.action}: the item number is required",
              file=sys.stderr)
        return 2
    if args.rounds is None:
        print(f"aide ledger {args.action}: --rounds is required — the round "
              f"count is why this row exists, and an abandoned item with no "
              f"count recorded is indistinguishable from one nobody wrote "
              f"down.", file=sys.stderr)
        return 2
    no_review = review_is_off(config)
    ddir = docs_dir(repo_root, config)
    path = ledger_path(ddir)
    if path.is_file():
        counts = _ledger_count_cells(rounds=args.rounds,
                                     findings=args.findings,
                                     no_review=no_review)
        for lineno, cells in ledger_rows(path.read_text(encoding=_ENCODING)):
            row = dict(zip(LEDGER_COLUMNS, cells))
            if (row.get("Item") == f"{args.number:03d}"
                    and row.get("Outcome") == "abandoned"
                    and [row.get(c) for c in LEDGER_COUNT_COLUMNS] == counts):
                # A retried orchestrator step is the ordinary way to arrive
                # here twice; a second row would count one abandonment as
                # two in every ratio read from the file. Different counts are
                # a different abandonment — an item resumed after the cap and
                # stopped again — and that row is appended like any other.
                print(f"aide ledger {args.action}: item {args.number:03d} is "
                      f"already recorded as abandoned with these counts "
                      f"({path.name}:{lineno}); nothing appended")
                return 0
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    branch = _find_claim_branch(repo_root, prefix, args.number)
    base = _recorded_branch_base(repo_root, branch) if branch else None
    cells = ledger_cells(repo_root, config, args.number, "abandoned",
                         rounds=args.rounds, findings=args.findings,
                         branch=branch, base=base, no_review=no_review)
    before = _snapshot([path])
    rel = append_ledger_row(repo_root, config, cells, f"ledger {args.action}")
    if rel is None:
        return 1
    print(f"aide ledger {args.action}: item {args.number:03d} recorded in {rel} "
          f"as abandoned after {args.rounds} round(s)")
    if _commits_here(args.no_commit, repo_root, before):
        # No pull: this is an append to a file the loop owns, on whatever
        # branch the cap was hit on, and a verb that only records must not
        # fetch on the caller's behalf (`ensure_insights_inbox` reasons the
        # same way). A row left uncommitted would read as recorded to a
        # retry, which the duplicate guard above then refuses (issue #309).
        if _commit_or_restore(repo_root, config, f"aide ledger {args.action}",
                              "the row",
                              f"docs(aide): ledger row for item {args.number:03d} "
                              f"(abandoned)", [rel], before, pull=False):
            return 1
    print(f"aide ledger {args.action}: progress.md is untouched — this verb "
          f"records what the run cost and decides nothing about the item's "
          f"status; if its owner decides against the work, `aide progress "
          f"set {args.number:03d} dropped --reason …` records that")
    return 0


# ledger report — the rows read back, per engine cohort and kind (issue #251)
# --------------------------------------------------------------------------- #
#: The first engine whose finding cells mean what §1 → `ledger.md` says: from
#: 1.59.0 a no-review run writes `-`, so a blank is a count not passed. Before
#: it a blank finding cell could also be a project with no reviewer at all,
#: and a ratio over such rows is not the reading a later cohort's is.
LEDGER_FINDINGS_SINCE = (1, 59, 0)
#: Where each kind sits in a report; a kind outside the vocabulary follows,
#: as written.
_LEDGER_KIND_ORDER = ("normal", "maintenance", "validate-stage")


def _ledger_engine_key(cell: str) -> Optional[Tuple[int, int, int]]:
    """``"2.25.0"`` -> ``(2, 25, 0)``; anything else -> ``None``."""
    m = re.fullmatch(r"(\d+)\.(\d+)\.(\d+)", cell.strip())
    return (int(m.group(1)), int(m.group(2)), int(m.group(3))) if m else None


def _ledger_count(cell: str) -> Optional[int]:
    """A cell's integer, or ``None`` for a blank or anything that is not one."""
    return int(cell) if re.fullmatch(r"[0-9]+", cell.strip()) else None


def _ratio(numerator: float, denominator: float) -> Optional[float]:
    return round(numerator / denominator, 2) if denominator else None


def ledger_report(text: str, queue: Optional[int] = None) -> Dict[str, object]:
    """The readings `aide ledger report` prints, over a ledger's text.

    Pure: a function of the rows alone, so the verb's `-h` is a statement
    about this and nothing else. Every ratio is returned with its `n`, the
    rows it was drawn from, and never averaged across two kinds (§1 →
    `ledger.md`). What it reads the cells as, each exactly as the section
    defines them: a blank is unrecorded and joins no ratio; `-` says no review
    ran and joins no finding ratio; a merged row whose Tests and Files are
    both `0` lost its diff rather than measured an empty one.
    """
    skipped: List[int] = []
    rows: List[Tuple[int, Dict[str, str]]] = []
    queue_at = LEDGER_COLUMNS.index("Queue")
    for lineno, cells in ledger_rows(text):
        if queue is not None and (len(cells) <= queue_at
                                  or _ledger_count(cells[queue_at]) != queue):
            continue
        if len(cells) not in (len(LEDGER_COLUMNS), LEDGER_TEMPLATE_2_WIDTH):
            skipped.append(lineno)
            continue
        cells = cells + [""] * (len(LEDGER_COLUMNS) - len(cells))
        rows.append((lineno, dict(zip(LEDGER_COLUMNS, cells))))

    # A merge re-run after a failed push, before 2.25.1 (issue #346),
    # appended a second `merged` row for the item with its diff read after
    # the branch had landed: Tests and Files both 0. That row is the
    # duplicate and the earlier one is the record; any other repeat is a
    # reopened item merged again, and both rows count.
    def number(cell: str) -> str:
        value = _ledger_count(cell)
        return cell if value is None else str(value)

    merged_before: Set[Tuple[str, str]] = set()
    dropped: List[int] = []
    kept: List[Tuple[int, Dict[str, str]]] = []
    for lineno, row in rows:
        key = (number(row["Item"]), number(row["Queue"]))
        if row["Outcome"] == "merged":
            if (key in merged_before and _ledger_count(row["Tests"]) == 0
                    and _ledger_count(row["Files"]) == 0):
                dropped.append(lineno)
                continue
            merged_before.add(key)
        kept.append((lineno, row))

    groups: Dict[Tuple[str, str], List[Dict[str, str]]] = {}
    for _, row in kept:
        groups.setdefault((row["Engine"], row["Kind"]), []).append(row)

    def order(key: Tuple[str, str]):
        engine, kind = key
        version = _ledger_engine_key(engine)
        rank = (_LEDGER_KIND_ORDER.index(kind) if kind in _LEDGER_KIND_ORDER
                else len(_LEDGER_KIND_ORDER))
        return (version is None, version or (0, 0, 0), engine, rank, kind)

    cohorts: List[Dict[str, object]] = []
    for key in sorted(groups, key=order):
        cohorts.append(_ledger_group(key[0], key[1], groups[key]))
    return {"rows": len(kept), "skipped": skipped, "counted_once": dropped,
            "cohorts": cohorts}


def _ledger_group(engine: str, kind: str,
                  rows: List[Dict[str, str]]) -> Dict[str, object]:
    """One cohort-and-kind's readings — see ``ledger_report``."""
    version = _ledger_engine_key(engine)
    withheld = version is None or version < LEDGER_FINDINGS_SINCE
    unrecorded = {c: 0 for c in ("ACs", "Tests", "Files") + LEDGER_COUNT_COLUMNS}
    rounds: List[int] = []
    tests = criteria = tests_n = 0
    found = {c: [] for c in LEDGER_FINDING_COLUMNS}
    no_review = blank = cells = unknown_diff = 0
    for row in rows:
        ac, test, files = (_ledger_count(row[c]) for c in ("ACs", "Tests", "Files"))
        if row["Outcome"] == "merged" and test == 0 and files == 0:
            test = files = None
            unknown_diff += 1
        for column, value in (("ACs", ac), ("Tests", test), ("Files", files)):
            unrecorded[column] += value is None
        # A spec with no criterion has no tests-per-criterion to give.
        if ac and test is not None:
            tests, criteria, tests_n = tests + test, criteria + ac, tests_n + 1
        r = _ledger_count(row["Rounds"])
        cells += 1
        if r is None:
            unrecorded["Rounds"] += 1
            blank += 1
        else:
            rounds.append(r)
        if withheld:
            continue
        if any(row[c] == LEDGER_NO_REVIEW_CELL for c in LEDGER_FINDING_COLUMNS):
            no_review += 1
        for column in LEDGER_FINDING_COLUMNS:
            if row[column] == LEDGER_NO_REVIEW_CELL:
                continue
            cells += 1
            value = _ledger_count(row[column])
            if value is None:
                unrecorded[column] += 1
                blank += 1
            else:
                found[column].append(value)
    histogram: Dict[str, int] = {}
    for r in sorted(rounds):
        histogram[str(r)] = histogram.get(str(r), 0) + 1

    def dated(column: str) -> List[str]:
        return sorted({row[column] for row in rows if row[column]},
                      key=lambda v: (_ledger_count(v) is None,
                                     _ledger_count(v) or 0, v))

    dates = sorted(row["Date"] for row in rows if row["Date"])
    return {
        "engine": engine, "kind": kind, "rows": len(rows),
        "merged": sum(row["Outcome"] == "merged" for row in rows),
        "abandoned": sum(row["Outcome"] == "abandoned" for row in rows),
        "queues": dated("Queue"), "stages": dated("Stage"),
        "first_date": dates[0] if dates else None,
        "last_date": dates[-1] if dates else None,
        "rounds": {"per_item": _ratio(sum(rounds), len(rounds)),
                   "n": len(rounds), "max": max(rounds) if rounds else None,
                   "histogram": histogram},
        "tests_per_ac": {"value": _ratio(tests, criteria), "n": tests_n},
        "findings": None if withheld else {
            column.lower(): {"per_item": _ratio(sum(values), len(values)),
                             "n": len(values)}
            for column, values in found.items()},
        "no_review": None if withheld else no_review,
        "caller_blank": {"blank": blank, "cells": cells},
        "unrecorded": {c: (None if withheld and c in LEDGER_FINDING_COLUMNS
                           else n) for c, n in unrecorded.items()},
        "unknown_diff": unknown_diff,
    }


def _ledger_reading(value: Optional[float], n: int) -> str:
    return "—" if value is None else f"{value:g} (n={n})"


def _ledger_report_table(report: Dict[str, object]) -> List[str]:
    """The report as a markdown table, one line per cohort and kind."""
    head = ["Engine", "Kind", "Stages", "Rows", "Merged", "Abandoned",
            "Rounds/item", "Rounds", "Tests/AC", "Blocking/item",
            "Minor/item", "Nit/item", "Blank"]
    body = []
    for c in report["cohorts"]:
        findings = c["findings"]
        ranks = (["withheld"] * 3 if findings is None else
                 [_ledger_reading(findings[r]["per_item"], findings[r]["n"])
                  for r in LEDGER_FINDING_RANKS])
        body.append([
            c["engine"] or "(blank)", c["kind"] or "(blank)",
            ",".join(c["stages"]) or "—", str(c["rows"]), str(c["merged"]),
            str(c["abandoned"]),
            _ledger_reading(c["rounds"]["per_item"], c["rounds"]["n"]),
            " ".join(f"{k}:{v}" for k, v in c["rounds"]["histogram"].items())
            or "—",
            _ledger_reading(c["tests_per_ac"]["value"], c["tests_per_ac"]["n"]),
            *ranks,
            f"{c['caller_blank']['blank']}/{c['caller_blank']['cells']}"])
    widths = [max(len(r[i]) for r in [head] + body) for i in range(len(head))]

    def line(cells: List[str]) -> str:
        return "| " + " | ".join(v.ljust(w) for v, w in zip(cells, widths)) + " |"
    return ([line(head), "|" + "|".join("-" * (w + 2) for w in widths) + "|"]
            + [line(r) for r in body])


def _ledger_report_command(repo_root: Path, config,
                           args: argparse.Namespace) -> int:
    """`aide ledger report` — read-only, so a missing file is a report too."""
    path = ledger_path(docs_dir(repo_root, config))
    rel = _rel_display(path, repo_root)
    queue = args.queue
    if not path.is_file():
        if args.as_json:
            print(json.dumps({"ledger": rel, "exists": False,
                              "queue": queue, "rows": 0, "skipped": [],
                              "counted_once": [], "cohorts": []}, indent=2))
        else:
            print(f"aide ledger report: no {rel} — no item has been merged or "
                  f"abandoned through the engine yet; nothing to report")
        return 0
    report = ledger_report(path.read_text(encoding=_ENCODING), queue)
    if args.as_json:
        print(json.dumps({"ledger": rel, "exists": True, "queue": queue,
                          **report}, indent=2, ensure_ascii=False))
        return 0
    scope = f" on queue {queue:03d}" if queue is not None else ""
    if not report["cohorts"]:
        print(f"aide ledger report: {rel} holds no row{scope}")
    else:
        print(f"aide ledger report: {report['rows']} row(s){scope} in {rel}, "
              f"by Engine cell and Kind (n = the rows a ratio is drawn from)")
        print()
        for text in _ledger_report_table(report):
            print(text)
    if report["counted_once"]:
        print(f"counted once: {', '.join(f'{path.name}:{n}' for n in report['counted_once'])} "
              f"— a repeat merged row with Tests and Files both 0, a merge "
              f"re-run's duplicate; the earlier row is read")
    if report["skipped"]:
        print(f"skipped: {', '.join(f'{path.name}:{n}' for n in report['skipped'])} "
              f"— a cell count no ledger template draws (`aide check` names it)")
    return 0


#: Which of `queue`'s shared options each action reads; any other one given
#: is a usage error, never silently ignored — `ready --dry-run` must not push
#: and flip (issue #330). The older actions are checked only against the
#: options `pr` and `ready` brought, which they never read. `discard` reads
#: none, so `discard --dry-run` is refused rather than run (issue #383).
_QUEUE_OPTIONS = {
    "pr": {"body", "body_file"},
    "ready": {"undo"},
    "discard": set(),
}
_QUEUE_OPTION_DEFAULTS = {"through": None, "no_commit": False, "specs": False,
                          "base": None, "dry_run": False, "date": None,
                          "body": None, "body_file": None, "undo": False}
_QUEUE_PR_OPTIONS = {"body", "body_file", "undo"}


def _queue_stray_options(args: argparse.Namespace) -> List[str]:
    """The options given to *args.action* that it does not read."""
    reads = _QUEUE_OPTIONS.get(args.action)
    checked = (set(_QUEUE_OPTION_DEFAULTS) if reads is not None
               else _QUEUE_PR_OPTIONS)
    reads = reads or set()
    return ["--" + k.replace("_", "-") for k in sorted(checked - reads)
            if getattr(args, k, _QUEUE_OPTION_DEFAULTS[k])
            != _QUEUE_OPTION_DEFAULTS[k]]


def cmd_queue(args: argparse.Namespace) -> int:
    stray = _queue_stray_options(args)
    if stray:
        print(f"usage: aide queue {args.action} does not take "
              f"{', '.join(stray)} — nothing was done", file=sys.stderr)
        return 2
    if args.action == "restack":
        return _queue_restack(args)
    if args.action == "pr":
        return _queue_pr(args)
    if args.action == "ready":
        return _queue_ready(args)
    if args.number is None:
        print(f"usage: aide queue {args.action} NNN — {args.action} takes a "
              f"queue number", file=sys.stderr)
        return 2
    if args.action == "start":
        return _queue_start(args)
    if args.action == "gate":
        return _queue_gate(args)
    if args.action == "discard":
        return _queue_discard(args)
    if args.action != "tidy":
        print("usage: aide queue {start|tidy|gate|discard} NNN | aide queue restack "
              "[NNN --base REF] | aide queue {pr|ready} [NNN]", file=sys.stderr)
        return 2
    import datetime as _dt
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    qdir = docs_dir(repo_root, config) / "queue"
    target = queue_path(qdir, args.number)
    if target is None:
        print(f"error: no {queue_name(args.number)} file under {qdir}", file=sys.stderr)
        return 1
    # Supersede by the highest-numbered queue after this one.
    later = [n for n in (queue_number(p) for p in iter_queue_paths(qdir))
             if n > args.number]
    superseded_by = max(later) if later else args.number + 1
    date = args.date or _dt.date.today().isoformat()
    text = target.read_text(encoding=_ENCODING)
    target.write_text(tidy_queue_text(text, superseded_by, date), encoding="utf-8")
    print(f"{queue_name(args.number)}: marked completed "
          f"(superseded by {queue_name(superseded_by)})")
    return 0


def _queue_start(args: argparse.Namespace) -> int:
    """Create (and, off ``local`` mode, push) a queue or specs-queue branch.

    The branch half of what `claim` does for an item. It exists because
    conventions.md §3 says a raw git form is wrong wherever a verb covers it,
    and until 1.20.0 two of the three branch shapes the engine recognises were
    covered by no verb at all: the framework's own prose told an agent to type
    `git switch -c <prefix>queue-NNN`, and the regex that must later parse that
    name never saw it until something had already gone wrong. A typo did not
    fail loudly — it made `claim` infer `main_branch` as the base and merge the
    item past the queue branch, silently.

    Recording the base is the second half. `_record_branch_base` ran only at
    claim, so a queue branch had no recorded base of its own; a queue branched
    off something other than `main_branch` had to be given `--base` at every
    later call that cared.
    """
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    if not _require_repository("queue start", repo_root):
        return 1
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    mode = str(config["git"].get("mode", "auto-merge"))
    if not _require_origin("queue start", repo_root, mode):
        return 1
    branch = (specs_queue_branch_name(prefix, args.number) if args.specs
              else queue_branch_name(prefix, args.number))

    base = args.base or str(config["git"].get("main_branch", "main"))
    if not _local_branch_exists(repo_root, base):
        print(f"aide queue start: base '{base}' is not a local branch — a queue "
              f"branch is branched from its base and merged back into it, so "
              f"the base must be a branch this checkout can update",
              file=sys.stderr)
        return 1
    if _local_branch_exists(repo_root, branch):
        print(f"aide queue start: {branch} already exists — switch to it rather "
              f"than recreating it", file=sys.stderr)
        return 1
    # Also on origin: another machine (or another session) already started this
    # queue. Creating it locally would succeed and the `push -u` would then fail
    # — an uncaught CalledProcessError, i.e. a raw traceback in what is meant to
    # be an unattended flow. Fail as a sentence instead.
    if mode != "local" and _has_origin(repo_root) and branch in _remote_branches(repo_root):
        print(f"aide queue start: {branch} already exists on origin — someone "
              f"has started this queue; fetch and switch to it rather than "
              f"recreating it", file=sys.stderr)
        return 1

    # The cap and the stack shape (issue #302). A specs-queue branch is where
    # a queue already on main_branch has its specs written; it is never a
    # batch of its own, so it is neither counted nor stacked.
    if not args.specs:
        cap, problem = max_open_queues(config)
        if problem:
            print(f"aide queue start: {problem}. Nothing was started.",
                  file=sys.stderr)
            return 1
        main = str(config["git"].get("main_branch", "main"))
        unmerged = _unmerged_queue_branches(repo_root, config)
        if len(unmerged) >= cap:
            unsure = sorted(b for b, v in unmerged.items() if v is None)
            # Where a queue lands decides the remedy: through a PR into
            # origin's main_branch, which a pull brings here — or, in local
            # mode, by a person merging it into this checkout's main_branch,
            # where there is nothing to pull. Off local mode origin is there:
            # `_require_origin` refused above without one (issue #377).
            if mode != "local":
                remedy = (f"once a PR merges, update {main} from origin "
                          f"('git switch {main}', then 'git pull')")
            else:
                remedy = (f"in local mode nothing is pulled, so a queue "
                          f"lands when it is merged into {main} here ('git "
                          f"switch {main}', then 'git merge <its branch>')")
            print(f"aide queue start: "
                  f"{_plural(len(unmerged), 'queue branch is', 'queue branches are')} "
                  f"unmerged ({', '.join(sorted(unmerged))}) and [loop] "
                  f"max_open_queues is {cap}, so {branch} would exceed it. A "
                  f"queue branch counts until its work has landed in this "
                  f"checkout's {main}: {remedy}, and start again. Nothing "
                  f"was started."
                  + (f" Git cannot tell whether {', '.join(unsure)} landed "
                     f"(no start is recorded): if it did, delete it with "
                     f"'aide gc --merged --yes'; if it is open, record its "
                     f"start with 'aide queue restack <NNN> --base {main}'."
                     if unsure else ""),
                  file=sys.stderr)
            return 3
        if unmerged:
            refusal = _stack_top_refusal(repo_root, prefix, main, base, unmerged)
            if refusal:
                print(f"aide queue start: {refusal}. Nothing was started.",
                      file=sys.stderr)
                return 1

    if args.dry_run:
        print(f"would start {branch}; base {base}")
        return 0
    # Branch FROM the base explicitly, for the reason `claim` does: with no
    # start point `switch -c` uses HEAD, which lets the branch's actual origin
    # disagree with the base it records.
    git(["switch", "-c", branch, base], repo_root)
    _record_branch_base(repo_root, branch, base)
    # The commit it forked from: what lets `queue restack` tell a queue
    # branch main_branch was fast-forwarded to from one with no commits of
    # its own (issue #301).
    _record_branch_start(repo_root, branch, _rev(repo_root, base))
    # `/aide-run-roadmap` (queue-planner) and `/aide-spec-queue` (spec-author,
    # spec-reviewer) start here and reach a role before any `check` runs, so
    # the inbox is guaranteed at the same point `claim` guarantees it.
    created = ensure_insights_inbox(repo_root, config, verb="queue start")
    if mode != "local":
        failure = _push_new_branch(repo_root, branch)
        if failure is not None:
            # One command per step (§3). `queue discard` takes a queue branch
            # with no commit beyond its base, so not a specs-queue branch and
            # not one carrying the inbox this start just committed (#383).
            over = (f"'aide queue discard {args.number:03d}'"
                    if created is None and not args.specs else
                    f"'git switch {base}', then 'git branch -D {branch}'")
            print(f"aide queue start: {failure}\n"
                  f"{branch} exists locally, branched from {base}, and is "
                  f"checked out — nothing is lost. Publish it with "
                  f"'git push -u origin {branch}' once the remote is "
                  f"reachable, or start over with {over}.", file=sys.stderr)
            return 1
    note = "" if base == str(config["git"].get("main_branch", "main")) else f" (base {base})"
    print(f"started {branch}{note}")
    return 0


def _queue_discard(args: argparse.Namespace) -> int:
    """Delete a queue branch that carries nothing beyond its base; see -h.

    The undo of `queue start` for a queue nobody planned (issue #383): a
    planner that hands back writes no queue, and the branch `queue start`
    made and pushed is left open and empty, counting against
    `max_open_queues`. The precondition is the whole safety — no commit on
    the branch, nor on origin's copy as last fetched, beyond the recorded
    base — so there is nothing to lose, and no `--yes` or dry run to ask
    for: `gc` previews because its ground is a judgement about landed work,
    and here there is no work. Origin's copy is deleted with a lease on the
    commit that was counted, so a push made since is never deleted.

    Off `local` mode with no remote named origin it still runs, and deletes
    the local branch only: nothing on origin can be reached, and the local
    branch is still the one counted against the cap.

    A queue file for the number, or the one after it (a maintenance queue's
    stage queue), written and not committed is refused too: a
    planner that broke "a hand-back writes nothing" would otherwise have its
    plan carried onto the base by the switch, stranded there. Origin's copy
    already gone (a stale remote-tracking ref) is asked of origin itself,
    never read from git's localised message, and counts as deleted.
    """
    tag = "aide queue discard"
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    if not _require_repository("queue discard", repo_root):
        return 1
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    mode = str(config["git"].get("mode", "auto-merge"))
    branch = queue_branch_name(prefix, args.number)
    tracking = f"origin/{branch}"
    on_origin = (mode != "local" and _has_origin(repo_root)
                 and _ref_exists(repo_root, f"refs/remotes/{tracking}"))
    if not _local_branch_exists(repo_root, branch):
        if on_origin:
            print(f"{tag}: {branch} is on origin only — this checkout did not "
                  f"start it, so its base is unknown here; discard it where "
                  f"it was started", file=sys.stderr)
        else:
            print(f"{tag}: {branch} is not a branch in this checkout or on "
                  f"origin — there is nothing to discard", file=sys.stderr)
        return 1
    base = _recorded_branch_base(repo_root, branch)
    if base is None:
        print(f"{tag}: {branch} has no recorded base, so whether it carries "
              f"work beyond one cannot be told — if it is empty, delete it by "
              f"hand ('git branch -D {branch}')", file=sys.stderr)
        return 1
    for ref in [branch] + ([tracking] if on_origin else []):
        counted = git(["rev-list", "--count", f"{base}..{ref}"],
                      repo_root, check=False)
        ahead = counted.stdout.strip()
        if counted.returncode != 0 or not ahead.isdigit():
            print(f"{tag}: git could not count {ref}'s commits beyond its "
                  f"base {base} ({counted.stderr.strip() or 'no answer'}); "
                  f"nothing was discarded", file=sys.stderr)
            return 1
        if ahead != "0":
            print(f"{tag}: {ref} carries "
                  f"{_plural(int(ahead), 'commit', 'commits')} beyond {base}, "
                  f"which no plan review covers — landing or deleting "
                  f"{'it' if ahead == '1' else 'them'} is a person's call; "
                  f"nothing was discarded", file=sys.stderr)
            return 1
    qrel = f"{_docs_rel(config)}/queue"
    status = git(["status", "--porcelain", "-z", "--untracked-files=all",
                  "--", qrel], repo_root, check=False)
    fields, written = status.stdout.split("\0"), set()
    while fields:
        record = fields.pop(0)
        if len(record) < 4:
            continue
        if record[0] in "RC" and fields:
            fields.pop(0)                  # a rename's source is its own field
        written.add(record[3:])
    # The numbers the branch could own: its own, and NNN+1, the stage queue
    # a maintenance queue NNN is written with on the same branch.
    loose = sorted(p for p in written if p.endswith(".md")
                   and queue_number(Path(p)) in (args.number, args.number + 1))
    if loose:
        print(f"{tag}: {', '.join(loose)} "
              f"{'is' if len(loose) == 1 else 'are'} written and not "
              f"committed — a plan for this branch, which discarding it would "
              f"leave stranded on {base}; commit it on {branch} or remove it, "
              f"then re-run. Nothing was discarded.", file=sys.stderr)
        return 1
    current = _current_branch(repo_root)
    # `worktree list` names the branch each attached worktree sits on. Not
    # `_checked_out_branches`, which on a detached HEAD adds every branch at
    # HEAD's commit — a fresh queue branch is at its base's.
    sitting = {line[len("branch refs/heads/"):].strip() for line in
               git(["worktree", "list", "--porcelain"], repo_root,
                   check=False).stdout.splitlines()
               if line.startswith("branch refs/heads/")}
    if branch != current and branch in sitting:
        print(f"{tag}: {branch} is checked out in another worktree, and git "
              f"deletes no branch a checkout is sitting on — switch that "
              f"worktree off it first; nothing was discarded", file=sys.stderr)
        return 1
    if branch == current:
        unsafe = _unsafe_tree_state(repo_root)
        if unsafe:
            print(f"{tag}: refusing — {unsafe}. {branch} is checked out and "
                  f"discarding it switches to {base}; commit, stash or finish "
                  f"that state first. Nothing was discarded.", file=sys.stderr)
            return 1
        switched = git(["switch", base], repo_root, check=False)
        moved = f"; the checkout is now on {base}"
        if switched.returncode != 0:
            print(f"{tag}: git would not switch to {base} "
                  f"({switched.stderr.strip() or 'no answer'}); nothing was "
                  f"discarded", file=sys.stderr)
            return 1
    else:
        moved = ""
    if on_origin:
        lease = f"--force-with-lease=refs/heads/{branch}:{_rev(repo_root, tracking)}"
        pushed = git(["push", lease, "origin", "--delete", branch],
                     repo_root, check=False)
        if pushed.returncode != 0:
            there = git(["ls-remote", "origin", f"refs/heads/{branch}"],
                        repo_root, check=False)
            if there.returncode == 0 and not there.stdout.strip():
                # Already gone on origin: the tracking ref was stale.
                git(["update-ref", "-d", f"refs/remotes/{tracking}"],
                    repo_root, check=False)
            else:
                print(f"{tag}: origin did not delete {branch} "
                      f"({pushed.stderr.strip() or 'no answer'}) — origin "
                      f"may hold a commit pushed since the last fetch; "
                      f"nothing was discarded{moved}", file=sys.stderr)
                return 1
    deleted = git(["branch", "-D", branch], repo_root, check=False)
    if deleted.returncode != 0:
        print(f"{tag}: git would not delete {branch} "
              f"({deleted.stderr.strip() or 'no answer'})"
              + ("; its copy on origin is already deleted" if on_origin
                 else "") + moved, file=sys.stderr)
        return 1
    print(f"discarded {branch} (base {base})")
    return 0


def _queue_gate(args: argparse.Namespace) -> int:
    """Raise a newly planned queue's plan-review gate; see `aide queue -h`.

    The row used to be typed by the planner from prose (issue #300), which
    put the one decision `[loop] plan_review` makes — which gate, if any — in
    an agent's reading of a paragraph. The verb makes it from the documents,
    and writes the §1 shape, so the row is a gate the moment it lands
    (issue #302).
    """
    tag = "aide queue gate"
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    first = args.number
    last = args.through if args.through is not None else first
    if last < first:
        print(f"usage: aide queue gate NNN [--through MMM] — MMM ({last}) is "
              f"below NNN ({first})", file=sys.stderr)
        return 2
    setting, problem = plan_review(config)
    if problem:
        print(f"{tag}: {problem}. Nothing was raised.", file=sys.stderr)
        return 1
    ddir = docs_dir(repo_root, config)
    qdir = ddir / "queue"
    items: List[int] = []
    for n in range(first, last + 1):
        path = queue_path(qdir, n)
        if path is None:
            print(f"{tag}: no {queue_name(n)} file under {qdir} — the gate is "
                  f"raised over a queue that is already written",
                  file=sys.stderr)
            return 1
        items.extend(queue_item_numbers(path.read_text(encoding=_ENCODING)))
    what = (queue_name(first) if first == last
            else f"{queue_name(first)}–{last:03d}")
    if not items:
        print(f"{tag}: {what} lists no items, so there is no plan to gate",
              file=sys.stderr)
        return 1
    if setting == "none":
        print(f"{tag}: [loop] plan_review is \"none\" — no plan gate raised "
              f"for {what}; the plan is reviewed in its queue PR")
        return 0
    ppath = ddir / "progress.md"
    if not ppath.is_file():
        print(f"{tag}: missing {ppath}", file=sys.stderr)
        return 1
    text = ppath.read_text(encoding=_ENCODING)
    lines = text.splitlines()
    if setting == "queue":
        cell = (f"Queue {first:03d} plan reviewed before build" if first == last
                else f"Queues {first:03d}–{last:03d} plan reviewed before build")
        rows = [(cell, item_ranges(items))]
    else:
        rows = [(f"Stage {s} plan reviewed before build", f"stage {s}")
                for s in queue_opened_stages(lines, qdir, first, items)]
        if not rows:
            print(f"{tag}: [loop] plan_review is \"stage\" and {what} opens no "
                  f"stage — no plan gate raised")
            return 0

    def key(cell: str) -> Optional[str]:
        return gate_hash(HumanGate(0, cell, [], None, False, None))

    present = {gate_hash(g) for g in human_gates(lines)}
    new = [r for r in rows if key(r[0]) not in present]
    before = _snapshot([ppath])
    if new:
        text = add_gate_rows(text, new)
        ppath.write_text(text, encoding="utf-8")
    gates = human_gates(text.splitlines())
    ids = gate_ids(gates)
    for cell, blocks in rows:
        gid = next(i for g, i in zip(gates, ids) if gate_hash(g) == key(cell))
        state = "raised" if (cell, blocks) in new else "already raised"
        print(f"{gid}: {state} — {cell} (blocks {blocks})")
    if new and _commits_here(args.no_commit, repo_root, before):
        # A row left written and uncommitted reads as "already raised" to a
        # re-run, which would then never commit it.
        return _commit_or_restore(repo_root, config, tag, "the gate row",
                                  f"docs(aide): plan gate for {what}",
                                  [_progress_rel(config)], before)
    return 0


# --------------------------------------------------------------------------- #
# queue pr / queue ready — the queue's own pull request (issue #330)
# --------------------------------------------------------------------------- #
def _queue_pr_branch(repo_root: Path, config: Dict[str, Dict[str, object]],
                     tag: str, number: Optional[int]
                     ) -> Tuple[Optional[str], Optional[int]]:
    """The queue branch `queue pr` / `queue ready` act on, or a refusal.

    ``(branch, number)``, or ``(None, None)`` after printing why: *number*'s
    ``<prefix>queue-NNN``, which must be a local branch, else the current
    branch, which must be one. A specs-queue branch is not: its work lands on
    its queue branch, which carries the PR. The branch must carry its own
    queue file, committed — whatever the mode. Then the forge must be
    reachable at all — `[git] forge = "none"`, `local` mode and a checkout
    with no origin open no PR.
    """
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    mode = str(config["git"].get("mode", "auto-merge"))
    if number is not None:
        branch = queue_branch_name(prefix, number)
        if not _local_branch_exists(repo_root, branch):
            print(f"{tag}: {branch} is not a branch in this checkout — "
                  f"'aide queue start {number:03d}' creates it", file=sys.stderr)
            return None, None
    else:
        branch = _current_branch(repo_root)
        if not _is_stack_branch(branch, prefix):
            print(f"{tag}: '{branch}' is not a queue branch "
                  f"({prefix}{_QUEUE_TOKEN}NNN) — switch to one, or name its "
                  f"queue number", file=sys.stderr)
            return None, None
        number = int(branch[len(prefix) + len(_QUEUE_TOKEN):])
    # Before the mode and the forge (issue #383): the branch `queue start`
    # made for a planner that then handed back holds no plan, and a caller
    # reading a no-forge refusal as "carry on without a PR" must not carry on
    # from there.
    if not _branch_carries_queue_file(repo_root, config, branch, number):
        print(f"{tag}: {branch} carries no {queue_name(number)} file under "
              f"{_docs_rel(config)}/queue, so there is no plan for a pull "
              f"request to carry — commit the queue file first; nothing was "
              f"pushed or asked of the forge", file=sys.stderr)
        return None, None
    if declared_forge(config) == "none":
        print(f'{tag}: no forge is declared (git.forge = "none")',
              file=sys.stderr)
        return None, None
    if mode == "local":
        print(f"{tag}: git.mode is \"local\", which pushes nothing and opens "
              f"no pull request", file=sys.stderr)
        return None, None
    if not _has_origin(repo_root):
        print(f"{tag}: this checkout has no remote named origin, so there is "
              f"no forge to ask", file=sys.stderr)
        return None, None
    return branch, number


def _branch_carries_queue_file(repo_root: Path,
                               config: Dict[str, Dict[str, object]],
                               branch: str, number: int) -> bool:
    """Does *branch*'s tip hold a queue file for *number*?

    Read at the branch, not in the working tree: a PR carries what is
    committed. A listing git cannot give reads as no file, and the caller
    refuses, which changes nothing.
    """
    listed = git(["ls-tree", "--name-only", branch,
                  f"{_docs_rel(config)}/queue/"], repo_root, check=False)
    if listed.returncode != 0:
        return False
    return any(queue_number(Path(p.strip())) == number
               for p in listed.stdout.splitlines()
               if p.strip().endswith(".md"))


def _push_if_ahead(repo_root: Path, tag: str, branch: str) -> bool:
    """Push *branch* where origin lacks commits it has; False on a failed push.

    With no ``origin/<branch>`` at all it is published with ``-u``. A branch
    that has diverged from origin is pushed without force, so the push fails
    and says so rather than overwriting what someone else pushed.
    """
    there = f"origin/{branch}"
    if _ref_exists(repo_root, there):
        res = git(["rev-list", "--count", f"{there}..{branch}"],
                  repo_root, check=False)
        ahead = res.stdout.strip()
        if res.returncode != 0 or not ahead.isdigit():
            print(f"{tag}: git could not count {branch}'s commits ahead of "
                  f"{there} ({res.stderr.strip() or 'no answer'}); nothing "
                  f"was pushed or changed on the forge", file=sys.stderr)
            return False
        if ahead == "0":
            return True
    failure = _push_new_branch(repo_root, branch)
    if failure is not None:
        print(f"{tag}: {failure}\nNothing was changed on the forge.",
              file=sys.stderr)
        return False
    print(f"{tag}: pushed {branch}")
    return True


def _queue_pr_title(repo_root: Path, config: Dict[str, Dict[str, object]],
                    branch: str, base: str, number: int) -> str:
    """``aide: work queue NNN``, or ``aide: work queues NNN-MMM`` for a pair."""
    nums = sorted(n for n in _branch_queue_files(repo_root, config, branch,
                                                 base, number) if n >= number)
    last = nums[-1] if nums else number
    if last == number:
        return f"aide: work queue {number:03d}"
    return f"aide: work queues {number:03d}-{last:03d}"


def _queue_pr(args: argparse.Namespace) -> int:
    """Open the queue branch's draft PR against its recorded base; see -h."""
    tag = "aide queue pr"
    if (args.body is None) == (args.body_file is None):
        print("usage: aide queue pr [NNN] (--body TEXT | --body-file PATH) — "
              "exactly one body", file=sys.stderr)
        return 2
    body_file: Optional[Path] = None
    if args.body_file is not None:
        body_file = Path(args.body_file).resolve()
        if not body_file.is_file():
            print(f"usage: aide queue pr — --body-file {args.body_file} is "
                  f"not a file", file=sys.stderr)
            return 2
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    if not _require_repository("queue pr", repo_root):
        return 1
    branch, number = _queue_pr_branch(repo_root, config, tag, args.number)
    if branch is None or number is None:
        return 1
    base = _recorded_branch_base(repo_root, branch)
    if base is None:
        print(f"{tag}: {branch} has no recorded base, so there is nothing to "
              f"open its PR against — 'aide queue restack {number:03d} --base "
              f"<base>' records one", file=sys.stderr)
        return 1
    counted = git(["rev-list", "--count", f"{base}..{branch}"],
                  repo_root, check=False)
    ahead = counted.stdout.strip()
    if counted.returncode != 0 or not ahead.isdigit():
        print(f"{tag}: git could not count {branch}'s commits ahead of its "
              f"base {base} ({counted.stderr.strip() or 'no answer'})",
              file=sys.stderr)
        return 1
    if ahead == "0":
        print(f"{tag}: {branch} has no commits ahead of its base {base}, and "
              f"the forge opens no PR without one — commit the plan first",
              file=sys.stderr)
        return 1
    pr, why = _branch_pr_facts(repo_root, branch)
    if why is not None:
        print(f"{tag}: could not ask the forge about {branch} ({why}); "
              f"nothing was opened", file=sys.stderr)
        return 1
    if pr is not None and pr.state in ("open", "draft"):
        print(f"{tag}: {branch} already has PR {pr.label} — nothing opened")
        return 0
    if pr is not None:
        print(f"{tag}: {branch}'s PR {pr.label} was {pr.state} — a person "
              f"decided that, so no second PR is opened over it",
              file=sys.stderr)
        return 1
    if not _push_if_ahead(repo_root, tag, branch):
        return 1
    title = _queue_pr_title(repo_root, config, branch, base, number)
    body = (["--body-file", str(body_file)] if body_file is not None
            else ["--body", str(args.body)])
    out, why = _gh(repo_root, ["pr", "create", "--draft", "--base", base,
                               "--head", branch, "--title", title, *body])
    if out is None:
        print(f"{tag}: the forge did not open the PR ({why})", file=sys.stderr)
        return 1
    url = next((l.strip() for l in out.splitlines() if l.strip()), "")
    print(f"{tag}: opened draft PR '{title}' for {branch} against {base}"
          + (f" — {url}" if url else ""))
    return 0


def _queue_ready(args: argparse.Namespace) -> int:
    """Mark the queue branch's PR ready, or back to draft; see -h."""
    tag = "aide queue ready" + (" --undo" if args.undo else "")
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    if not _require_repository("queue ready", repo_root):
        return 1
    branch, number = _queue_pr_branch(repo_root, config, tag, args.number)
    if branch is None or number is None:
        return 1
    pr, why = _branch_pr_facts(repo_root, branch)
    if why is not None:
        print(f"{tag}: could not ask the forge about {branch} ({why}); "
              f"nothing was changed", file=sys.stderr)
        return 1
    if pr is None:
        print(f"{tag}: {branch} has no pull request — 'aide queue pr "
              f"{number:03d}' opens its draft", file=sys.stderr)
        return 1
    if pr.state not in ("open", "draft"):
        print(f"{tag}: {branch}'s PR {pr.label} is {pr.state} — there is "
              f"nothing to mark", file=sys.stderr)
        return 1
    if args.undo:
        if pr.state == "draft":
            print(f"{tag}: PR #{pr.number} ({branch}) is already a draft")
            return 0
        out, why = _gh(repo_root, ["pr", "ready", str(pr.number), "--undo"])
        if out is None:
            print(f"{tag}: the forge did not turn PR #{pr.number} back to "
                  f"draft ({why})", file=sys.stderr)
            return 1
        print(f"{tag}: PR #{pr.number} ({branch}) is a draft again")
        return 0
    if not _push_if_ahead(repo_root, tag, branch):
        return 1
    if pr.state == "open":
        print(f"{tag}: PR #{pr.number} ({branch}) is already ready for review")
        return 0
    out, why = _gh(repo_root, ["pr", "ready", str(pr.number)])
    if out is None:
        print(f"{tag}: the forge did not mark PR #{pr.number} ready ({why})",
              file=sys.stderr)
        return 1
    print(f"{tag}: PR #{pr.number} ({branch}) is marked ready for review")
    return 0


# --------------------------------------------------------------------------- #
# queue restack — keep a stack of queue branches merged forward (issue #301)
# --------------------------------------------------------------------------- #
#: Only `<prefix>queue-NNN` stacks. A specs-queue branch is where a queue's
#: specs were authored in the two-branch flow and lands on its own queue
#: branch, so it is never the base of another queue's PR; since 2.13.1 the
#: specs are written on the queue branch itself.
_STACK_TOKEN_RE = re.compile(re.escape(_QUEUE_TOKEN) + r"\d+$")
#: `merge-tree --merge-base` — what lets a squash-merged lower be merged past.
_MERGE_BASE_OPTION_MIN_GIT = (2, 40)


def _is_stack_branch(branch: str, prefix: str) -> bool:
    return (branch.startswith(prefix)
            and _STACK_TOKEN_RE.match(branch[len(prefix):]) is not None)


def _rev(repo_root: Path, ref: str) -> str:
    return git(["rev-parse", "--verify", "--quiet", f"{ref}^{{commit}}"],
               repo_root, check=False).stdout.strip()


def _is_ancestor(repo_root: Path, ancestor: str, ref: str) -> bool:
    return git(["merge-base", "--is-ancestor", ancestor, ref],
               repo_root, check=False).returncode == 0


def _on_first_parent_chain(repo_root: Path, tip: str, main: str) -> bool:
    """Is *tip* a commit on *main*'s first-parent history?

    The first-parent walk from *main* down to the first commit *tip* reaches:
    the commit below the oldest one listed is *tip* itself exactly when *tip*
    sits on the chain. That is the shape of a branch with no commits of its
    own, and of one *main* was fast-forwarded to — git alone cannot tell the
    two apart; the start commit `queue start` records can.
    """
    tip_sha, main_sha = _rev(repo_root, tip), _rev(repo_root, main)
    if not tip_sha or not main_sha:
        return False
    if tip_sha == main_sha:
        return True
    out = git(["rev-list", "--first-parent", f"{tip_sha}..{main_sha}"],
              repo_root, check=False).stdout.split()
    if not out:
        return False
    return _rev(repo_root, f"{out[-1]}^1") == tip_sha


def _stack_branch_landed(repo_root: Path, main: str, ref: str,
                         start: Optional[str] = None) -> Optional[bool]:
    """Has *ref*'s work landed in *main*? Git only — never a pull request.

    A tip on *main*'s first-parent history is a fast-forward landing when the
    branch has moved past its recorded *start*, and a branch with no commits
    of its own when it has not; with no *start* the two cannot be told apart,
    and the answer is None — a caller must neither read it as landed nor
    report the stack consistent over it. Off that history,
    `_branch_content_landed` is the oracle `gc` trusts before `-D`, and it sees
    a squash or rebase merge; where git is too old for it, ancestry is the
    fallback, which sees only a merge commit.
    """
    tip = _rev(repo_root, ref)
    if not tip:
        return False
    if _on_first_parent_chain(repo_root, ref, main):
        if not start:
            return None
        return tip != start and _is_ancestor(repo_root, start, tip)
    content = _branch_content_landed(repo_root, main, ref)
    if content is None:
        return _is_ancestor(repo_root, ref, main)
    return content


def _stack_own_landing(repo_root: Path, main: str, ref: str,
                       lower: Optional[str], start: Optional[str]) -> Optional[bool]:
    """Has stack branch *ref* itself landed in *main*? The one judgement.

    *lower* is the ref of the queue branch it is stacked on, or None when its
    base is main_branch. Only a branch with commits beyond its lower can have
    landed on its own, so one without reads False (open) here; above a lower,
    the lower's tip stands in for an unrecorded *start*, so only a bottom can
    answer None. `queue restack` plans from this verdict and `queue start`
    counts unmerged branches by it — one reading of "landed", not two.
    """
    if lower is None:
        return _stack_branch_landed(repo_root, main, ref, start)
    if _is_ancestor(repo_root, ref, lower):
        return False
    return _stack_branch_landed(repo_root, main, ref,
                                start or _rev(repo_root, lower))


def _unmerged_queue_branches(repo_root: Path, config
                             ) -> Dict[str, Optional[bool]]:
    """Every ``<prefix>queue-NNN`` branch whose own work is not in main_branch.

    Name -> False (open) or None (git cannot tell, so it is counted, never
    guessed landed). The branches this checkout has and, off `local` mode,
    origin's as last fetched; each judged by `_stack_own_landing` against
    this checkout's main_branch, with the base and start `queue start`
    recorded. A specs-queue branch is never one (`_is_stack_branch`).
    """
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    mode = str(config["git"].get("mode", "auto-merge"))
    main = str(config["git"].get("main_branch", "main"))
    local = set(_local_branches(repo_root))
    remote = (set(_remote_branches(repo_root))
              if mode != "local" and _has_origin(repo_root) else set())
    main_ref = main if main in local or main not in remote else f"origin/{main}"
    out: Dict[str, Optional[bool]] = {}
    for b in sorted(x for x in local | remote if _is_stack_branch(x, prefix)):
        if b in local:
            ref, base = b, _recorded_branch_base(repo_root, b)
            start = _recorded_branch_start(repo_root, b)
        else:
            ref, base, start = f"origin/{b}", None, None
        lower = (base if base and base != main and base in local
                 and _is_stack_branch(base, prefix) else None)
        verdict = _stack_own_landing(repo_root, main_ref, ref, lower, start)
        if not verdict:
            out[b] = verdict
    return out


def _stack_top_refusal(repo_root: Path, prefix: str, main: str, base: str,
                       unmerged: Dict[str, Optional[bool]]) -> Optional[str]:
    """Why a queue started on *base* would not sit on top of the one stack.

    Walking recorded bases down from *base* must reach every unmerged queue
    branch: then *base* is the top, and the new queue makes the stack one
    taller. Anything else — a base beside the stack, a base another branch is
    already stacked on, an unmerged branch no walk reaches — would make a
    second stack, which stacking does not offer (conventions §4).
    """
    names = sorted(unmerged)
    below = {b: _recorded_branch_base(repo_root, b) for b in names}
    tops = [b for b in names if b not in below.values()]
    top = tops[0] if len(tops) == 1 else None
    hint = (f"--base {top}" if top else
            f"--base the top one, once every unmerged queue branch records "
            f"its base ('aide queue restack <NNN> --base <its base>')")
    if base not in unmerged:
        return (f"{', '.join(names)} "
                f"{'is' if len(names) == 1 else 'are'} unmerged, so a new "
                f"queue stacks on top of them ({hint}); starting from {base} "
                f"would begin a second stack beside the first")
    chain: List[str] = []
    x: Optional[str] = base
    while x in unmerged and x not in chain:
        chain.append(x)
        x = below.get(x)
        if not x or x == main:
            break
    outside = [b for b in names if b not in chain]
    if outside:
        return (f"{base} is not the top of the stack of unmerged queue "
                f"branches — {', '.join(outside)} "
                f"{'is' if len(outside) == 1 else 'are'} not below it, so a "
                f"queue on {base} would make a second stack ({hint})")
    return None


def _other_worktree_branches(repo_root: Path) -> Set[str]:
    """Branches checked out in a worktree other than this one."""
    here = git(["rev-parse", "--show-toplevel"], repo_root, check=False).stdout.strip()
    out: Set[str] = set()
    path: Optional[str] = None
    for line in git(["worktree", "list", "--porcelain"],
                    repo_root, check=False).stdout.splitlines():
        if line.startswith("worktree "):
            path = line[len("worktree "):].strip()
        elif line.startswith("branch refs/heads/") and path is not None:
            try:
                same = Path(path).resolve() == Path(here).resolve()
            except OSError:
                same = False
            if not same:
                out.add(line[len("branch refs/heads/"):].strip())
    return out


def _advance_branch(repo_root: Path, branch: str, new: str,
                    current: str) -> Optional[str]:
    """Move *branch* forward to *new*: None, or git's words for why not.

    The checked-out branch moves with its working tree (`merge --ff-only` over
    the clean tree the verb requires); any other branch by `update-ref`, which
    names the old value so a concurrent change to the ref is refused rather
    than overwritten.
    """
    if branch == current:
        res = git(["merge", "--ff-only", "--quiet", new], repo_root, check=False)
    else:
        old = _rev(repo_root, branch)
        res = git(["update-ref", "-m", "aide queue restack",
                   f"refs/heads/{branch}", new, old], repo_root, check=False)
    if res.returncode == 0:
        return None
    return (res.stderr.strip() or res.stdout.strip()
            or f"git exited {res.returncode}")


def _restack_merge(repo_root: Path, upper: str, other: str, current: str,
                   merge_base: Optional[str] = None) -> Optional[str]:
    """Merge *other* into *upper*: None on success, else why it stopped.

    With `merge-tree --write-tree` (git 2.38+) the merge is computed without
    touching the working tree, so a conflict leaves nothing to abort; the
    commit is then written with both parents and *upper* moved forward to it.
    *merge_base* is honoured where git has `--merge-base` (2.40+): it is how a
    squash-merged lower's tip stands in for the ancestry main_branch lacks.
    On older git the merge runs in the working tree, and a conflict is aborted
    here; the caller restores the branch the run started on. Both paths honour
    `commit.gpgSign` and run no commit hook.
    """
    if _is_ancestor(repo_root, upper, other):
        # Nothing of *upper*'s own to keep: the merge git would make is a
        # fast-forward, so make that rather than a two-parent commit.
        return _advance_branch(repo_root, upper, _rev(repo_root, other), current)
    if _has_merge_tree(repo_root):
        cmd = ["merge-tree", "--write-tree", "--name-only", "--no-messages"]
        version = _git_version(repo_root)
        if merge_base and version is not None and version >= _MERGE_BASE_OPTION_MIN_GIT:
            cmd.append(f"--merge-base={merge_base}")
        res = git([*cmd, upper, other], repo_root, check=False)
        lines = res.stdout.splitlines()
        if res.returncode == 1:
            paths = root_relative(repo_root, [l.strip() for l in lines[1:] if l.strip()])
            return f"conflicts in {', '.join(paths) or 'the tree'}"
        if res.returncode != 0 or not lines:
            return (res.stderr.strip() or f"git merge-tree exited {res.returncode}")
        # `commit-tree` ignores `commit.gpgSign`; `git merge` below honours
        # it. Asked for here, so both paths sign, and a signing failure stops
        # the run with nothing moved on either.
        sign = git(["config", "--type=bool", "--get", "commit.gpgSign"],
                   repo_root, check=False).stdout.strip() == "true"
        commit = git(["commit-tree", *(["-S"] if sign else []),
                      lines[0].strip(), "-p", upper, "-p", other,
                      "-m", f"Merge {other} into {upper} (aide queue restack)"],
                     repo_root, check=False)
        if commit.returncode != 0:
            return commit.stderr.strip() or "git commit-tree failed"
        return _advance_branch(repo_root, upper, commit.stdout.strip(), current)
    switched = git(["switch", "--quiet", upper], repo_root, check=False)
    if switched.returncode != 0:
        return switched.stderr.strip() or f"could not switch to {upper}"
    # `--no-verify`: `commit-tree` above runs no hook, so neither does this —
    # one behaviour on every git version (issue #301).
    res = git(["merge", "--no-edit", "--no-verify", "--quiet", "-m",
               f"Merge {other} into {upper} (aide queue restack)", other],
              repo_root, check=False)
    if res.returncode == 0:
        return None
    paths = _unmerged_paths(repo_root)
    if (_git_dir(repo_root) / "MERGE_HEAD").exists():
        git(["merge", "--abort"], repo_root, check=False)
    if paths:
        return f"conflicts in {', '.join(paths)}"
    return res.stderr.strip() or res.stdout.strip() or "git merge failed"


def _queue_restack(args: argparse.Namespace) -> int:
    """Merge a stack of queue branches forward; see `aide queue -h`.

    Git only, by decision (issue #301): no pull-request state is read and no
    host CLI is called, so the verb behaves the same in `local` mode, on a
    machine with no `gh`, and on any host. "Landed" is the content oracle
    `gc` already trusts. "Closed without merging" is not visible to git — the
    branch is simply still there — so a caller that can see PRs checks for
    that before calling this.
    """
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    if not _require_repository("queue restack", repo_root):
        return 1
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    mode = str(config["git"].get("mode", "auto-merge"))
    if not _require_origin("queue restack", repo_root, mode):
        return 1
    main = str(config["git"].get("main_branch", "main"))
    dry = bool(args.dry_run)
    say = "would " if dry else ""
    tag = "aide queue restack"

    if (args.number is None) != (args.base is None):
        print(f"usage: aide queue restack [NNN --base REF] — NNN and --base "
              f"go together: they record REF as queue NNN's base",
              file=sys.stderr)
        return 2
    unsafe = _unsafe_tree_state(repo_root)
    if unsafe:
        print(f"{tag}: refusing — {unsafe}. Restacking merges into branches "
              f"and may move the checked-out one; commit, stash or finish "
              f"that state, then re-run.", file=sys.stderr)
        return 1
    if not _local_branch_exists(repo_root, main):
        print(f"{tag}: main_branch '{main}' is not a local branch here, so "
              f"there is no bottom to read a stack from", file=sys.stderr)
        return 1

    remote_on = mode != "local" and _has_origin(repo_root)
    if remote_on:
        fetched = git(["fetch", "--prune", "origin"], repo_root, check=False)
        if fetched.returncode != 0:
            detail = fetched.stderr.strip() or f"git exited {fetched.returncode}"
            print(f"{tag}: fetching origin FAILED — {detail}\nNothing was "
                  f"changed: without the fetch a lower branch's review edits "
                  f"on origin would be missed. Re-run once origin is "
                  f"reachable.", file=sys.stderr)
            return 1

    local = set(_local_branches(repo_root))
    remote = set(_remote_branches(repo_root)) if remote_on else set()
    stack_names = sorted(b for b in local | remote if _is_stack_branch(b, prefix))

    def ref(b: str) -> str:
        return b if b in local else f"origin/{b}"

    bases: Dict[str, str] = {b: _recorded_branch_base(repo_root, b) or ""
                             for b in stack_names if b in local}
    forced: Optional[str] = None
    if args.number is not None:
        target = queue_branch_name(prefix, args.number)
        given = args.base
        if target not in local and target not in remote:
            print(f"{tag}: {target} exists neither here nor on origin",
                  file=sys.stderr)
            return 1
        if given != main and not (_is_stack_branch(given, prefix)
                                  and given in local):
            print(f"{tag}: --base '{given}' must be main_branch ('{main}') or "
                  f"a <prefix>queue-NNN branch this checkout has — record a "
                  f"lower branch first ('queue restack <its NNN> --base "
                  f"<its base>'), bottom up", file=sys.stderr)
            return 1
        if given == target:
            print(f"{tag}: {target} cannot be its own base", file=sys.stderr)
            return 1
        if given != main and not bases.get(given):
            print(f"{tag}: {given} has no recorded base of its own, so a "
                  f"branch stacked on it cannot be read either — record it "
                  f"first ('queue restack "
                  f"{given[len(prefix) + len(_QUEUE_TOKEN):]} --base <its "
                  f"base>'), bottom up. Nothing was changed.", file=sys.stderr)
            return 1
        if not dry and target not in local:
            made = git(["branch", "--track", target, f"origin/{target}"],
                       repo_root, check=False)
            if made.returncode != 0:
                print(f"{tag}: could not create {target} from origin — "
                      f"{made.stderr.strip()}", file=sys.stderr)
                return 1
            local.add(target)
        # The base itself is written as a planned step, after the merges it
        # implies: a run that stops on a conflict must leave the record it
        # found, or the next run reads a stack the branches do not have.
        # A missing start record is written now — it is a fact about where
        # the branch forked, true whatever the merge does.
        if not dry and not _recorded_branch_start(repo_root, target):
            _record_branch_start(repo_root, target, git(
                ["merge-base", ref(target), given], repo_root,
                check=False).stdout.strip())
        bases[target] = given
        forced = target

    # ---- read the stack --------------------------------------------------- #
    unread: List[str] = []
    outside: List[str] = []
    broken: List[str] = []
    for b in stack_names:
        base = bases.get(b, "")
        if not base:
            if not _stack_branch_landed(repo_root, main, ref(b)):
                unread.append(b)       # None (cannot tell) included
        elif base in bases and not bases[base]:
            broken.append(f"{b} records {base} as its base, which has no "
                          f"recorded base of its own")
        elif base == main or (base in bases and base != b):
            continue
        elif _is_stack_branch(base, prefix):
            broken.append(f"{b} records {base} as its base, and this "
                          f"checkout has no local {base}")
        else:
            outside.append(f"{b} (based on {base})")
    uppers: Dict[str, List[str]] = {}
    for b, base in bases.items():
        if base and base != main and base in bases:
            uppers.setdefault(base, []).append(b)
    order: List[str] = []
    queue_ = sorted(b for b, base in bases.items() if base == main)
    while queue_:
        b = queue_.pop(0)
        order.append(b)
        queue_.extend(sorted(uppers.get(b, [])))
    # Only a real cycle is named as one: a branch left out of `order` because
    # a base below it is unrecorded is already in `broken` for that reason.
    cyclic: List[str] = []
    for b in bases:
        seen, x = [b], bases[b]
        while x in bases and x not in seen and bases[x] and bases[x] != main:
            seen.append(x)
            x = bases[x]
        if x == b:
            cyclic.append(b)
    cyclic.sort()
    if cyclic:
        broken.append(f"{', '.join(cyclic)} record bases that form a cycle")
    if broken:
        print(f"{tag}: the stack cannot be read, and nothing was changed — "
              f"{'; '.join(broken)}. If the missing branch landed in {main}, "
              f"'queue restack <NNN> --base {main}' re-records the branch "
              f"above it; if it is on origin, 'queue restack <its NNN> --base "
              f"<its base>' creates and records it.", file=sys.stderr)
        return 1
    for b in unread:
        print(f"{tag}: {b} has no recorded base (this checkout did not start "
              f"it), so it is not read into any stack; if it belongs to one, "
              f"'queue restack {b[len(prefix) + len(_QUEUE_TOKEN):]} --base "
              f"<its base>' records it", file=sys.stderr)
    for b in outside:
        print(f"{tag}: {b} is not stacked on main_branch or a queue branch, "
              f"so it is left alone")

    # Only branches in a stack of two or more — or the one --base named — are
    # touched. A lone queue branch on main_branch is the ordinary one-queue
    # flow, and restacking it would merge main_branch into it unasked.
    members = [b for b in order
               if b == forced or bases[b] != main or uppers.get(b)]
    if not members:
        print(f"{tag}: no stack of queue branches to restack — nothing to do")
        return 0

    # ---- bring the stack level with origin -------------------------------- #
    behind: Dict[str, str] = {}
    ahead: Set[str] = set()
    if remote_on:
        diverged: List[str] = []
        for b in [main, *members]:
            if b not in local or b not in remote:
                continue
            here, there = _rev(repo_root, b), _rev(repo_root, f"origin/{b}")
            if here == there:
                continue
            if _is_ancestor(repo_root, here, there):
                behind[b] = there
            elif _is_ancestor(repo_root, there, here):
                ahead.add(b)
            else:
                diverged.append(b)
        if diverged:
            print(f"{tag}: refusing — {', '.join(diverged)} "
                  f"{'has' if len(diverged) == 1 else 'have'} diverged from "
                  f"origin. Restacking merges and pushes without force, so it "
                  f"will not choose a side: reconcile "
                  f"{'it' if len(diverged) == 1 else 'them'} with origin, "
                  f"then re-run. Nothing was changed.", file=sys.stderr)
            return 1
    others = _other_worktree_branches(repo_root)
    busy = sorted(b for b in set(members) | set(behind) if b in others)
    if busy:
        print(f"{tag}: refusing — {', '.join(busy)} "
              f"{'is' if len(busy) == 1 else 'are'} checked out in another "
              f"worktree, and moving a branch under a checkout desynchronises "
              f"it. Nothing was changed.", file=sys.stderr)
        return 1

    start = _current_branch(repo_root)
    start_sha = _rev(repo_root, "HEAD")

    def eff(b: str) -> str:
        """The ref *b* is judged by: origin's where this run fast-forwards to it."""
        return f"origin/{b}" if dry and b in behind else ref(b)

    if not dry:
        for b, sha in behind.items():
            failure = _advance_branch(repo_root, b, sha, start)
            if failure:
                print(f"{tag}: fast-forwarding {b} to origin FAILED — "
                      f"{failure}", file=sys.stderr)
                return 1
    for b in behind:
        print(f"{tag}: {say}fast-forward {b} to origin/{b}")

    # ---- plan ------------------------------------------------------------- #
    # Every step is decided from the refs as they stand, before any merge is
    # made: which lower landed and which upper already contains its lower do
    # not change under a merge into a *different* branch, and a branch this
    # run merges into is marked `changed`, so the one above it takes the merge.
    steps: List[Tuple[str, str, str, Optional[str]]] = []  # (kind, upper, other, merge_base)
    changed: Set[str] = set()
    landed: Set[str] = set()
    held: List[str] = []        # bottoms git cannot judge, and what resolves each
    blocked: Dict[str, str] = {}  # branch -> the unjudged bottom beneath it
    base_now = dict(bases)
    starts = {b: _recorded_branch_start(repo_root, b) for b in members}

    def number(b: str) -> str:
        return b[len(prefix) + len(_QUEUE_TOKEN):]

    for b in order:
        if b not in members:
            continue
        lower = base_now[b]
        # Each branch's own landing is judged at its own step, whatever lies
        # below it: a branch main_branch took whole (by merge, squash, rebase
        # or fast-forward) has everything beneath it that it holds, so the
        # branch above it is owed main_branch even while a lower stays open.
        # Only a branch with commits beyond its lower can have landed on its
        # own; one without has landed exactly when its lower has. Above a
        # lower, the lower's tip is where the branch started, recorded or not
        # — so only a bottom can be undecidable.
        verdict = _stack_own_landing(repo_root, eff(main), eff(b),
                                     None if lower == main else eff(lower),
                                     starts.get(b))
        if verdict:
            landed.add(b)
            if lower != main:
                base_now[b] = main
                steps.append(("record", b, main, None))
            continue
        if lower in blocked:
            root = blocked[lower]
            blocked[b] = root
            if root == lower:
                held.append(
                    f"{lower}'s tip is on {main}'s first-parent history and "
                    f"no start is recorded for it, so git cannot tell whether "
                    f"{main} was fast-forwarded to it (it landed) or it has no "
                    f"commits of its own (it is open); {b} above it is left "
                    f"as it is. If it landed: 'queue restack {number(b)} "
                    f"--base {main}'. If it is open: 'queue restack "
                    f"{number(lower)} --base {main}' records its start")
            continue
        if verdict is None:             # a bottom only, see above
            blocked[b] = b
            continue
        if lower == main:
            # Not into a branch with nothing main_branch lacks: that merge is
            # a fast-forward, after which an open branch reads as one that
            # landed.
            if (b == forced and not _is_ancestor(repo_root, eff(main), eff(b))
                    and not _is_ancestor(repo_root, eff(b), eff(main))):
                steps.append(("merge", b, main, None))
                changed.add(b)
            if b == forced and _recorded_branch_base(repo_root, b) != main:
                steps.append(("record", b, main, None))
            continue
        if lower not in landed:
            if lower in changed or not _is_ancestor(repo_root, eff(lower), eff(b)):
                steps.append(("merge", b, lower, None))
                changed.add(b)
            continue
        base_now[b] = main
        if not _is_ancestor(repo_root, eff(lower), eff(b)):
            steps.append(("merge", b, lower, None))
            changed.add(b)
        if not _is_ancestor(repo_root, eff(main), eff(b)):
            # A squash or rebase merge leaves main_branch without the lower's
            # commits, so git's own merge base is the stack's fork point and
            # the lower's changes meet themselves — a conflict wherever the
            # upper edited next to them. The lower's tip, inside `b` by now,
            # is the base that says "already in both".
            squashed = not _is_ancestor(repo_root, eff(lower), eff(main))
            steps.append(("merge", b, main,
                          _rev(repo_root, eff(lower)) if squashed else None))
            changed.add(b)
        steps.append(("record", b, main, None))
    if forced and forced not in blocked and forced in members and not any(
            k == "record" and u == forced for k, u, _o, _m in steps) \
            and _recorded_branch_base(repo_root, forced) != bases[forced]:
        # Right after the forced branch's own merges, before any branch above
        # it: a stop further up must not cost a record whose merges landed.
        rank = {b: i for i, b in enumerate(order)}
        at = sum(1 for _k, u, _o, _m in steps if rank[u] <= rank[forced])
        steps.insert(at, ("record", forced, bases[forced], None))

    to_push: List[str] = []
    if mode != "local":
        to_push = [b for b in members
                   if b not in landed and (b in changed or b in ahead)]

    if not steps and not to_push and not held:
        print(f"{tag}: every stack is consistent — nothing to merge")
        return 0

    # ---- execute ---------------------------------------------------------- #
    done: List[str] = []
    stopped: Optional[str] = None
    if dry:
        for kind, upper, other, _mb in steps:
            print(f"{tag}: would merge {other} into {upper}" if kind == "merge"
                  else f"{tag}: would record {other} as {upper}'s base")
    else:
        try:
            with _restore_on_signal():
                for kind, upper, other, mb in steps:
                    if kind == "record":
                        _record_branch_base(repo_root, upper, other)
                        print(f"{tag}: recorded {other} as {upper}'s base")
                        continue
                    if _is_ancestor(repo_root, other, upper):
                        continue
                    failure = _restack_merge(repo_root, upper, other,
                                             _current_branch(repo_root), mb)
                    if failure:
                        stopped = (f"merging {other} into {upper} stopped — "
                                   f"{failure}. The merge was not made and "
                                   f"{upper} is as it was: resolving it is a "
                                   f"person's call, never this verb's")
                        break
                    done.append(upper)
                    print(f"{tag}: merged {other} into {upper}")
        finally:
            if (_git_dir(repo_root) / "MERGE_HEAD").exists():
                git(["merge", "--abort"], repo_root, check=False)
            if _current_branch(repo_root) != start or start == "HEAD":
                if start == "HEAD":
                    git(["switch", "--quiet", "--detach", start_sha],
                        repo_root, check=False)
                else:
                    git(["switch", "--quiet", start], repo_root, check=False)
    for line in held if stopped else []:
        print(f"{tag}: {line}.", file=sys.stderr)
    if stopped:
        kept = sorted(set(done))
        print(f"{tag}: {stopped}.\n"
              + (f"Merges made before it stay local and unpushed "
                 f"({', '.join(kept)}); a re-run after the conflict is "
                 f"settled pushes them.\n" if kept else "")
              + "Nothing was pushed.", file=sys.stderr)
        return 1

    failures: List[str] = []
    for b in to_push:
        if dry:
            print(f"{tag}: would push {b}")
            continue
        failure = _push_new_branch(repo_root, b)
        if failure:
            failures.append(failure)
        else:
            print(f"{tag}: pushed {b}")
    if failures:
        print(f"{tag}: " + "\n".join(failures) + "\nThe merges are made "
              f"locally and nothing is lost; re-run 'aide queue restack' once "
              f"origin is reachable — it pushes every stack branch ahead of "
              f"origin.", file=sys.stderr)
        return 1
    if dry:
        print(f"{tag}: dry run — nothing was changed")
    if held:
        # Never "consistent" over a lower git cannot judge: the branch above
        # it may be owed main_branch, and nothing here can say.
        for line in held:
            print(f"{tag}: {line}.", file=sys.stderr)
        return 1
    return 0


# --------------------------------------------------------------------------- #
# git layer — claim / merge / env
# --------------------------------------------------------------------------- #
def venv_python(repo_root: Path, config: Dict[str, Dict[str, object]]) -> Path:
    """Resolve the venv interpreter path (Windows Scripts vs. posix bin)."""
    venv = repo_root / str(config["python"].get("venv", ".venv"))
    if os.name == "nt":
        return venv / "Scripts" / "python.exe"
    return venv / "bin" / "python"


def has_venv(config: Dict[str, Dict[str, object]]) -> bool:
    """Does this project keep a venv? ``[python] venv = ""`` says it does not
    (issue #354): a project in another language, whose `aide env` would
    otherwise fail forever on a venv nobody meant to build."""
    return bool(str(config["python"].get("venv", ".venv") or "").strip())


def resolve_test_command(repo_root: Path, config: Dict[str, Dict[str, object]]) -> List[str]:
    """The configured test command, with a leading ``python`` bound to the venv."""
    raw = str(config["python"].get("test_command", "python -m pytest")).split()
    vpy = venv_python(repo_root, config)
    if raw and raw[0] == "python" and has_venv(config) and vpy.exists():
        return [str(vpy), *raw[1:]]
    return raw


#: Written beside the venv's own files by `env --bootstrap`, read by
#: `env_report`: the exit status of the install that populated the venv. A
#: `pip install -e .[dev]` that aborts partway leaves the editable project
#: importable and the dependency closure unfinished, so an import check alone
#: reads a half-install as healthy (issue #166). The record is the one thing
#: that distinguishes them.
_BOOTSTRAP_RECORD = "aide-bootstrap.json"


def _venv_dir(repo_root: Path, config: Dict[str, Dict[str, object]]) -> Path:
    return repo_root / str(config["python"].get("venv", ".venv"))


def _configured_interpreter(config: Dict[str, Dict[str, object]]) -> List[str]:
    """The command `--bootstrap` builds the venv with, else the Python running
    this CLI.

    `[python] interpreter` is either a path or a command line. A value that
    names an existing file is the whole command, spaces and all — Windows's
    own default install lives under `Program Files`, and splitting that is
    what turned a valid key into "cannot be run". Anything else is a command
    line (`py -3.12`, `"C:\\Some Dir\\python.exe" -X utf8`), split the way
    the platform's shell would: shlex on POSIX; on Windows in non-POSIX mode,
    which keeps backslashes and leaves the quotes on a quoted token for this
    to strip.
    """
    raw = str(config["python"].get("interpreter", "") or "").strip()
    if not raw:
        return [sys.executable]
    if Path(raw).is_file():
        return [raw]
    if os.name == "nt":
        return [token.strip('"') for token in shlex.split(raw, posix=False)]
    return shlex.split(raw)


def _test_runner_module(config: Dict[str, Dict[str, object]]) -> Optional[str]:
    """The module `test_command` runs with ``python -m``, if that is its shape.

    Only that shape is answerable from inside the venv: `resolve_test_command`
    binds a leading `python` to the venv, so `python -m pytest` runs *the
    venv's* pytest and its absence is the venv's fault. A bare `pytest` or a
    `make test` resolves on PATH, and whether PATH has it is not a property
    of the venv this reports on.
    """
    raw = str(config["python"].get("test_command", "python -m pytest")).split()
    if len(raw) >= 3 and raw[0] == "python" and raw[1] == "-m":
        return raw[2]
    return None


def _python_version(command: List[str], cwd: Path) -> Optional[str]:
    """``major.minor`` of the interpreter *command* starts, or None when it
    cannot be run at all."""
    try:
        res = subprocess.run(
            [*command, "-c", "import sys; print('%d.%d' % sys.version_info[:2])"],
            cwd=str(cwd), stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            encoding="utf-8", errors="replace")
    except OSError:
        return None
    if res.returncode != 0:
        return None
    return res.stdout.strip() or None


def _read_bootstrap_record(venv: Path) -> Optional[Dict[str, object]]:
    path = venv / _BOOTSTRAP_RECORD
    if not path.is_file():
        return None
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    return data if isinstance(data, dict) else None


def env_report(repo_root: Path, config: Dict[str, Dict[str, object]]) -> Tuple[str, str]:
    """``(status, detail)`` for the project venv: 'ok', 'missing' or 'stale'.

    'ok' is a claim the loop acts on — the validator reads it and runs the
    suite — so it is only made when every question this can ask of the venv
    is answered: the venv exists; the last `--bootstrap` that built it
    finished; it is the Python `[python] interpreter` names, where that is
    set and runnable; `import_check` imports; and the module `test_command`
    runs with `-m` imports too. A venv with no `pytest` cannot report OK
    (issue #166). The detail is one sentence for the report line.
    """
    vpy = venv_python(repo_root, config)
    venv = _venv_dir(repo_root, config)
    if not vpy.exists():
        return "missing", f"no venv at {venv}"
    record = _read_bootstrap_record(venv)
    if record is not None and record.get("unrun"):
        return "stale", (f"the last `env --bootstrap` could not start its "
                         f"command, so nothing was installed — "
                         f"{record.get('unrun')}")
    if record is not None and record.get("exit") not in (0, None):
        return "stale", (f"the last `env --bootstrap` exited "
                         f"{record.get('exit')}, so its install did not finish")
    facts: List[str] = []
    actual = _python_version([str(vpy)], repo_root)
    if actual is None:
        return "stale", f"{vpy} cannot be run"
    facts.append(f"venv is Python {actual}")
    configured = str(config["python"].get("interpreter", "") or "").strip()
    if configured:
        wanted = _python_version(_configured_interpreter(config), repo_root)
        if wanted is None:
            facts.append(f"[python] interpreter '{configured}' cannot be run "
                         f"on this machine, so the venv was judged on its own")
        elif wanted != actual:
            return "stale", (f"venv is Python {actual} but [python] interpreter "
                             f"'{configured}' is {wanted} — rebuild it")
        else:
            facts[-1] += f" ({configured})"
    for what, module in (("import_check", str(config["python"].get("import_check", "") or "").strip()),
                         ("test_command", _test_runner_module(config))):
        if not module:
            continue
        res = subprocess.run([str(vpy), "-c", f"import {module}"], cwd=str(repo_root),
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if res.returncode != 0:
            why = ("its test runner is not installed, so `python -m "
                   f"{module}` cannot run" if what == "test_command"
                   else f"`import {module}` fails")
            return "stale", why
        facts.append(f"`import {module}` succeeds")
    return "ok", "; ".join(facts)


def env_status(repo_root: Path, config: Dict[str, Dict[str, object]]) -> str:
    """Return 'ok', 'missing', or 'stale' for the project venv."""
    return env_report(repo_root, config)[0]


# --------------------------------------------------------------------------- #
# the dependency report — what this machine has for what the config asks
# --------------------------------------------------------------------------- #
class Requirement(NamedTuple):
    """One line of `aide env`'s dependency report (issue #354).

    ``needed_by`` is what makes the requirement one — ``"always"``, or the
    setting that asks for it (``[git] mode = "pr"``) — and ``None`` where the
    configuration does not need it. ``refusal`` is the sentence for a
    requirement the configuration needs and this machine lacks, naming the
    setting and the two ways out: meet it, or change the setting. Never an
    adaptation: nothing here lowers a mode to fit the machine. ``in_check``
    marks the four `aide check` also errors on — git, the repository,
    `origin`, the test command — decidable offline and about the project; a
    gh login needs the network, and the interpreter and venv are `env`'s own.
    ``note`` is a fact worth fixing that fails nothing: the interpreter the
    engine prints in its suggestions, which no verb runs.
    """
    name: str
    found: str
    needed_by: Optional[str]
    refusal: Optional[str] = None
    in_check: bool = False
    note: Optional[str] = None


def origin_url(repo_root: Path) -> Optional[str]:
    """The URL of the remote named ``origin``, or None when there is none."""
    res = git(["remote", "get-url", "origin"], repo_root, check=False)
    url = res.stdout.strip()
    return url if res.returncode == 0 and url else None


def _version_text(repo_root: Path) -> Optional[str]:
    """git's own version string (``2.43.0``), or None when unreadable."""
    out = git(["--version"], repo_root, check=False).stdout
    m = re.search(r"\d+\.\d+(?:\.\d+)?", out)
    return m.group(0) if m else None


def _git_requirement(repo_root: Path, offline: bool
                     ) -> Tuple[Requirement, bool]:
    """The git line, and whether git can be run for the lines after it.
    *offline* leaves the version out: it decides no refusal, and a check
    pays for every spawn."""
    try:
        exe = resolve_tool("git", repo_root)
    except ToolMisconfigured as exc:
        return Requirement("git", "not run", "always", str(exc), True), False
    if exe is None:
        return Requirement(
            "git", "not on PATH", "always",
            "git is not on PATH — every claim, merge and document edit is "
            "recorded in git; install it, or name one in [tools] git in "
            f"{LOCAL_CONFIG.as_posix()}", True), False
    if offline:
        return Requirement("git", exe, "always", None, True), True
    text = _version_text(repo_root)
    version = (tuple(int(n) for n in text.split(".")[:2])
               if text is not None else None)
    features = []
    for minimum, what in ((_MERGE_TREE_MIN_GIT, "merge-tree --write-tree "
                           "(gc's landed check)"),
                          (_MERGE_BASE_OPTION_MIN_GIT, "merge-tree --merge-base "
                           "(queue restack past a squash)")):
        has = version is not None and version >= minimum
        features.append(f"{what}, {minimum[0]}.{minimum[1]}+: "
                        f"{'yes' if has else 'no'}")
    found = f"{exe}, {text or 'version unreadable'} — {'; '.join(features)}"
    return Requirement("git", found, "always", None, True), True


def _repository_requirement(repo_root: Path, git_runs: bool
                            ) -> Tuple[Requirement, bool]:
    """The repository line, and whether there is one for `origin` to be in."""
    if not git_runs:
        return Requirement("repository", "not asked — git cannot be run",
                           "always", None, True), False
    try:
        top = git_toplevel(repo_root)
    except MissingTool as exc:
        return Requirement("repository", "unreadable", "always", str(exc),
                           True), False
    if top is None:
        return Requirement(
            "repository", "none", "always",
            f"{repo_root} is not inside a git repository — the loop records "
            f"its work in git; run 'git init' there", True), False
    if not (Path(repo_root) / "aide.toml").is_file():
        where = "no aide.toml at the repo root, so the defaults apply"
    else:
        rel = _root_prefix(repo_root)
        where = ("aide.toml at its top level" if not rel
                 else f"aide.toml in {'/'.join(rel)}/, below its top level")
    return Requirement("repository", f"{top} ({where})", "always", None,
                       True), True


def dependency_report(repo_root: Path, config: Dict[str, Dict[str, object]],
                      offline: bool = False) -> List[Requirement]:
    """Each requirement this project's configuration makes of the machine,
    what the machine has, and the refusal where a needed one is missing
    (issue #354): git, the repository, `origin`, `gh`, the test command,
    Python and the venv, in that order.

    *offline* is the half `aide check` and `install.py` run — git, the
    repository, `origin` and the test command, the lines marked
    ``in_check``: the `gh` login is asked of the forge, and the interpreter
    and the venv cost spawns a check has no use for. A
    requirement that cannot be asked because an earlier one is missing (no
    `origin` without a repository) says so and adds no refusal of its own.
    Under ``[git] mode`` other than ``local`` — any value but ``local`` runs
    as a mode that pushes — `origin` is needed, and `gh` too unless ``[git]
    forge = "none"`` declares no forge, which leaves the `gh` line out
    (issue #355).
    """
    lines: List[Requirement] = []
    git_line, git_runs = _git_requirement(repo_root, offline)
    lines.append(git_line)
    repo_line, in_repo = _repository_requirement(repo_root, git_runs)
    lines.append(repo_line)

    mode = config.get("git", {}).get("mode", "auto-merge")
    pushes = mode != "local"
    setting = f'[git] mode = "{mode}"' if pushes else None
    unneeded = '' if pushes else ' (not needed under [git] mode = "local")'
    if not in_repo:
        lines.append(Requirement("origin", "not asked — no repository",
                                 setting, None, True))
    else:
        url = origin_url(repo_root)
        refusal = None
        if url is None and pushes:
            refusal = missing_origin(mode)
        lines.append(Requirement("origin", (url or "none") + unneeded,
                                 setting, refusal, True))

    no_forge = declared_forge(config) == "none"
    # Out of a gh refusal's ways out under `pr`, which needs a forge.
    other = (' or [git] forge = "none"' if mode != "pr" else "")
    if not offline and not no_forge:
        try:
            gh = resolve_tool("gh", repo_root)
            misconfigured = None
        except ToolMisconfigured as exc:
            gh, misconfigured = None, str(exc)
        refusal = None
        if misconfigured is not None:
            found = "not run"
            refusal = misconfigured if pushes else None
        elif gh is None:
            found = "not on PATH"
            if pushes:
                refusal = (f"{setting} in aide.toml needs gh, which opens and "
                           f"reads the queue's pull request — install it, or "
                           f"name one in [tools] gh in "
                           f"{LOCAL_CONFIG.as_posix()}, or set [git] mode = "
                           f'"local"{other}')
        elif not pushes:
            found = gh                  # never asked: `local` asks no forge
        else:
            _, why = _gh(repo_root, ["auth", "status"])
            found = f"{gh}, " + ("logged in" if why is None
                                 else f"no login confirmed ({why})")
            if why is not None:
                refusal = (f"{setting} in aide.toml needs gh logged in, and "
                           f"'gh auth status' did not confirm one ({why}) — "
                           f"run 'gh auth login', or set [git] mode = "
                           f'"local"{other}')
        lines.append(Requirement("gh", found + unneeded, setting, refusal))

    raw = str(config["python"].get("test_command", "python -m pytest")).split()
    if not raw:
        lines.append(Requirement(
            "test command", "empty", "always",
            "[python] test_command is empty in aide.toml — set it", True))
    else:
        argv = resolve_test_command(repo_root, config)
        if argv[0] != raw[0]:
            lines.append(Requirement("test command",
                                     f"{raw[0]} → {argv[0]} (the venv)",
                                     "always", None, True))
        elif argv[0] == "git" and not git_runs:
            lines.append(Requirement("test command", "git, as above",
                                     "always", None, True))
        else:
            try:
                found_at = resolve_tool(argv[0], repo_root)
                refusal = None
            except ToolMisconfigured as exc:
                found_at, refusal = None, str(exc)
            if refusal is not None:
                pass
            elif found_at is None and raw[0] == "python":
                build = (f"build the venv ('{aide_command(repo_root, 'env --bootstrap')}'), "
                         if has_venv(config) else "")
                instead = ""
                if shutil.which("python3"):
                    instead = (" — this machine has python3, so '"
                               + " ".join(["python3", *raw[1:]])
                               + "' would run")
                refusal = (f"the test command's 'python' is not on PATH, and "
                           f"there is no venv to run it from — {build}put a "
                           f"python on PATH, or change [python] test_command "
                           f"in aide.toml{instead}")
            elif found_at is None:
                refusal = str(RunnerMissing(argv[0], repo_root))
            lines.append(Requirement("test command",
                                     f"{argv[0]} → {found_at or 'not found'}",
                                     "always", refusal, True))

    if offline:
        return lines
    printed = printed_python(repo_root)
    bare = printed.strip('"')
    if _has_directory(bare) and not os.path.isabs(bare):
        bare = str(Path(repo_root) / bare)
    printed_at = shutil.which(bare)
    if printed_at is None and os.name == "nt" and _has_directory(bare):
        printed_at = _pathext_file(bare)
    found = (f"the engine runs on {sys.executable} "
             f"({sys.version_info[0]}.{sys.version_info[1]}); the commands it "
             f"suggests start {printed}"
             + (f" ({printed_at})" if printed_at else ", which is not found"))
    # A note, never a refusal: the printed interpreter decides only what a
    # suggestion says, not what any verb runs (§4).
    note = None
    if printed_at is None:
        fix = (f"set [tools] python = \"python3\" in "
               f"{LOCAL_CONFIG.as_posix()} — this machine has python3"
               if printed != "python3" and shutil.which("python3")
               else f"put one on PATH, or name the interpreter to print in "
                    f"[tools] python in {LOCAL_CONFIG.as_posix()}")
        note = (f"the engine prints '{printed}' in the commands it suggests, "
                f"and this machine has no {printed} on PATH; {fix}")
    lines.append(Requirement("python", found, "always", None, note=note))

    if has_venv(config):
        venv = str(config["python"].get("venv", ".venv"))
        status, detail = env_report(repo_root, config)
        refusal = None
        if status != "ok":
            refusal = (f"the venv is {status} — {detail}; run "
                       f"'{aide_command(repo_root, 'env --bootstrap')}' to "
                       f'build it, or set [python] venv = "" in aide.toml '
                       f"for a project with no venv")
        lines.append(Requirement("venv", f"{status} — {detail}",
                                 f'[python] venv = "{venv}"', refusal))
    return lines


#: What `aide check` puts before an error about the machine rather than the
#: documents (issue #354): reported to a person, never fixed by editing
#: `aide.toml` to fit.
MACHINE_PREFIX = "this machine: "


def dependency_errors(repo_root: Path,
                      config: Dict[str, Dict[str, object]]) -> List[str]:
    """`aide check`'s errors from the offline half of the dependency report:
    a missing git, repository, `origin` or test command (issue #354)."""
    found = [r.refusal for r in dependency_report(repo_root, config, offline=True)
             if r.refusal and r.in_check]
    return list(dict.fromkeys(found))


#: Seconds a ``[validation]`` expression may run. Generous — importing a GPU
#: stack and initialising its driver takes seconds — but finite: a profile is
#: evaluated inside unattended runs, where a hang stalls the loop silently.
PROFILE_TIMEOUT = 120


def evaluate_profile(repo_root: Path, config: Dict[str, Dict[str, object]],
                     expr: str, timeout: float = PROFILE_TIMEOUT
                     ) -> Tuple[bool, str]:
    """``(satisfied, detail)`` for a ``[validation]`` expression, evaluated in
    the project venv (this interpreter when there is none).

    It evaluates the expression and nothing else: whether this machine
    provides the capability, never whether the gated path works. *detail* is
    the last stderr line, or why the expression could not be evaluated.

    An expression that times out, or an interpreter that cannot be started, is
    **not satisfied**: the reading under which validation records
    ``❓ Unverified`` rather than passing. The one evaluation
    ``aide env --profile`` and ``aide status --profiles`` share, so the two can
    never disagree about whether this machine has a capability.
    """
    vpy = venv_python(repo_root, config)
    interpreter = (str(vpy) if has_venv(config) and vpy.exists()
                   else sys.executable)
    code = f"import sys\nsys.exit(0 if ({expr}) else 1)"
    try:
        # §6: name the codec — a traceback carrying a non-ASCII path decodes
        # differently under a Windows locale, and this text is reported to a user.
        res = subprocess.run([interpreter, "-c", code], cwd=str(repo_root),
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                             encoding="utf-8", errors="replace", timeout=timeout)
    except subprocess.TimeoutExpired:
        return False, f"timed out after {timeout:g}s"
    except OSError as exc:
        return False, f"interpreter '{interpreter}' cannot be run: {exc}"
    detail = (res.stderr or "").strip().splitlines()
    return res.returncode == 0, detail[-1] if detail else ""


def cmd_env(args: argparse.Namespace) -> int:
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)

    if getattr(args, "profile", None):
        # Evaluate a named [validation] environment profile deterministically.
        profiles = {k: str(v) for k, v in (config.get("validation") or {}).items()}
        expr = profiles.get(args.profile)
        if expr is None:
            known = ", ".join(sorted(profiles)) or "(none defined)"
            print(f"aide env: unknown profile '{args.profile}' — [validation] defines: {known}",
                  file=sys.stderr)
            return 2
        satisfied, detail = evaluate_profile(repo_root, config, expr)
        if satisfied:
            print(f"aide env: profile '{args.profile}' satisfied")
            return 0
        suffix = f" ({detail})" if detail else ""
        print(f"aide env: profile '{args.profile}' NOT satisfied{suffix} — "
              f"validation gated on it must record '❓ Unverified', never a silent pass")
        return 1

    if args.bootstrap and not has_venv(config):
        print('aide env: [python] venv = "" in aide.toml says this project '
              'keeps no venv, so there is none to build — set it to a '
              'directory to build one there', file=sys.stderr)
        return 1
    if args.bootstrap:
        # The venv alone, as before the report existed: the validator runs
        # this to get a suite runner, and a gh login it does not need for
        # that must not read as a failed build.
        status, detail = env_report(repo_root, config)
        if status == "ok":
            print(f"aide env: OK ({detail})")
            return 0
        return _bootstrap_venv(repo_root, config)
    return _print_dependency_report(repo_root, config)


def _print_dependency_report(repo_root: Path,
                             config: Dict[str, Dict[str, object]]) -> int:
    """Print `dependency_report`, one line per requirement, then each
    refusal and the verdict: exit 0 when nothing needed is missing, else 1."""
    lines = dependency_report(repo_root, config)
    print("aide env: what this machine has for this project's configuration")
    width = max(len(r.name) for r in lines)
    for r in lines:
        needed = ("needed always" if r.needed_by == "always"
                  else f"needed by {r.needed_by}" if r.needed_by
                  else "not needed")
        print(f"  {r.name:<{width}}  {r.found} · {needed}")
    for r in lines:
        if r.note:
            print(f"aide env: note: {r.note}")
    refusals = list(dict.fromkeys(r.refusal for r in lines if r.refusal))
    for refusal in refusals:
        print(f"aide env: {refusal}")
    if refusals:
        print(f"aide env: FAIL — {len(refusals)} requirement(s) this "
              f"configuration needs are not met on this machine")
        return 1
    venv = next((r.found for r in lines if r.name == "venv"), None)
    print(f"aide env: OK ({venv.partition(' — ')[2] if venv else 'no venv'})")
    return 0


#: The first tokens of `[python] bootstrap` that name Python itself, and are
#: replaced by the venv's interpreter (issue #378). The set is the one
#: `resolve_test_command` binds, plus the `python3` a POSIX host may be
#: written for. Not `py`: the Windows launcher's own arguments (`py -3.12`)
#: choose an interpreter, and inside a venv that already has one that would
#: be a different Python, or an argument the venv's Python refuses.
_BOOTSTRAP_PYTHONS = ("python", "python3")


def bootstrap_argv(tokens: List[str], vpy: Path,
                   repo_root: Path) -> Tuple[List[str], bool]:
    """How `env --bootstrap` runs `[python] bootstrap` (split on whitespace,
    as *tokens*) in the venv whose interpreter is *vpy*: the argv, and
    whether it is a command to look up (True) rather than *vpy* run with
    arguments (False).

    Before issue #378 every bootstrap but a leading `pip` ran as `<vpy>
    <value>`, so `uv sync` looked for a script file named `uv` and could
    never succeed. The command reading applies only to a first word that
    reading could never have run, so every bootstrap that worked runs the
    same way:

    1. A leading option (`-m poetry install`, `-c …`) or `.py` file
       (`setup.py develop`) is arguments to the venv's Python.
    2. A leading `pip` is the venv's `python -m pip`.
    3. A leading `python` or `python3` is replaced by the venv's Python.
    4. A first word naming an existing file under *repo_root* (`manage
       install`, `tools/bootstrap`, `app.pyz install`), or a directory
       there holding a `__main__.py`, is arguments to the venv's Python, as
       before — so a repository shell script is written
       `sh tools/bootstrap.sh`, and a repository that is itself the tool
       (a root `invoke/__main__.py`) runs its own tree. An absolute path, or
       one leading out of the repository, is a command.
    5. Anything else (`uv sync`, `make dev`) is a command.

    An empty bootstrap installs nothing and never reaches here:
    `_bootstrap_venv` builds the venv alone, since a bare `<vpy>` would wait
    on stdin.
    """
    first = tokens[0]
    if first.startswith("-") or first.lower().endswith(".py"):
        return [str(vpy), *tokens], False
    if first == "pip":
        return [str(vpy), "-m", *tokens], False
    if first in _BOOTSTRAP_PYTHONS:
        return [str(vpy), *tokens[1:]], False
    if _repo_python_target(first, Path(repo_root)):
        return [str(vpy), *tokens], False
    return list(tokens), True


def _repo_python_target(first: str, repo_root: Path) -> bool:
    """Whether *first* names a file inside *repo_root*, or a directory there
    holding a `__main__.py` — what `<vpy> <first>` could run before issue
    #378. An absolute path, or one leading out of the repository, is not:
    `repo_root / "/opt/uv/bin/uv"` is `/opt/uv/bin/uv`, a program to run."""
    root = repo_root.resolve()
    named = (root / first).resolve()
    try:
        named.relative_to(root)
    except ValueError:
        return False
    return named.is_file() or (named / "__main__.py").is_file()


def bootstrap_command_env(venv: Path, scripts: Path) -> Dict[str, str]:
    """The environment a bootstrap *command* runs in: this process's, with
    the venv's script directory *scripts* first on PATH, `VIRTUAL_ENV`
    naming the venv — what activating it sets, and what `poetry install` or
    `pdm install` install into — and `UV_PROJECT_ENVIRONMENT` naming it too,
    since `uv sync` ignores `VIRTUAL_ENV` without `--active` and would fill
    the project's `.venv` instead of a venv configured elsewhere.
    `PYTHONHOME` is dropped, as activation drops it."""
    env = dict(os.environ)
    env.pop("PYTHONHOME", None)
    env["VIRTUAL_ENV"] = str(venv)
    env["UV_PROJECT_ENVIRONMENT"] = str(venv)
    env["PATH"] = os.pathsep.join(
        p for p in (str(scripts), env.get("PATH", "")) if p)
    return env


def _bootstrap_unfound(program: str, repo_root: Path, scripts: Path) -> str:
    """Why the bootstrap command's *program* cannot be found, in the words
    `RunnerMissing` uses for the test command's (issue #352). A path to a
    file never reaches here: `bootstrap_argv` hands any existing file to the
    venv's Python, so a path is missing or names a directory."""
    if _has_directory(program):
        at = Path(program)
        if not at.is_absolute():
            at = repo_root / at
        where = "is not a file" if at.exists() else "does not exist"
    else:
        where = f"is neither in {scripts} nor on PATH"
    return (f"the [python] bootstrap program '{program}' {where} — install "
            f"it, or fix [python] bootstrap in aide.toml")


def _bootstrap_venv(repo_root: Path, config: Dict[str, Dict[str, object]]) -> int:
    """Build and populate the venv from `[python] interpreter`; 0 when built."""
    venv = _venv_dir(repo_root, config)
    # Whitespace, as `test_command` is split: shlex would re-read a value
    # that works today — a Windows path's backslashes, a quote pip was
    # handed literally — and nothing in the issue needed quoting.
    bootstrap = str(config["python"].get("bootstrap", "pip install -e .[dev]")).split()
    interpreter = _configured_interpreter(config)
    # A stale venv is rebuilt from nothing: `-m venv` over an existing tree
    # re-points the scripts and pyvenv.cfg at the new interpreter and keeps
    # the old site-packages beside them, which is neither venv.
    venv_args = ["-m", "venv", *(["--clear"] if venv.exists() else []), str(venv)]
    print(f"aide env: bootstrapping {venv} with {' '.join(interpreter)} …")
    try:
        made = subprocess.run([*interpreter, *venv_args], cwd=str(repo_root), check=False)
    except OSError as exc:
        print(f"aide env: [python] interpreter '{' '.join(interpreter)}' cannot "
              f"be run ({exc}) — nothing was built. Install it, or name one "
              f"this machine has in aide.toml.", file=sys.stderr)
        return 1
    if made.returncode != 0:
        print(f"aide env: '{' '.join(interpreter)} -m venv' exited "
              f"{made.returncode} — nothing was built.", file=sys.stderr)
        return 1
    vpy = venv_python(repo_root, config)
    # `bootstrap = ""` builds the venv and installs nothing: run as before,
    # it was a bare `<vpy>`, an interactive Python waiting on stdin.
    cmd, is_command = (bootstrap_argv(bootstrap, vpy, repo_root)
                       if bootstrap else ([], False))
    env: Optional[Dict[str, str]] = None
    unrun: Optional[str] = None
    if is_command:
        # Looked up here, on the PATH it will run with: on Windows a list
        # argv is not searched for on the child's PATH, and `uv` is `uv.exe`.
        # The record then names the program that ran, venv or not.
        env = bootstrap_command_env(venv, vpy.parent)
        found = resolve_tool(cmd[0], repo_root, path=env["PATH"])
        if found is None:
            unrun = _bootstrap_unfound(cmd[0], repo_root, vpy.parent)
        else:
            cmd = [found, *cmd[1:]]
    # The shell's statuses for a command that did not start: 127 not found,
    # 126 found and not executable.
    returncode = 127 if cmd else 0
    if unrun is None and cmd:
        try:
            returncode = subprocess.run(cmd, cwd=str(repo_root), env=env,
                                        check=False).returncode
        except OSError as exc:
            returncode = 126
            unrun = f"'{cmd[0]}' cannot be run ({exc})"
    # The record is what lets a later `env` tell a finished install from one
    # that aborted after the editable project landed (issue #166). Written
    # on every outcome, so a completed rebuild clears an earlier failure.
    record: Dict[str, object] = {
        "exit": returncode, "command": cmd,
        "interpreter": interpreter,
        "python": _python_version([str(vpy)], repo_root)}
    if unrun is not None:
        record["unrun"] = unrun
    (venv / _BOOTSTRAP_RECORD).write_text(json.dumps(record, indent=2) + "\n",
                                          encoding="utf-8")
    if unrun is not None:
        print(f"aide env: bootstrap FAILED — {unrun}. The venv exists but "
              f"nothing was installed in it, and `env` reports it stale "
              f"until a bootstrap completes.", file=sys.stderr)
        return 1
    if returncode != 0:
        print(f"aide env: bootstrap FAILED — '{' '.join(cmd)}' exited "
              f"{returncode}. The venv exists but its install did "
              f"not finish, and `env` reports it stale until a bootstrap "
              f"completes.", file=sys.stderr)
        return 1
    final, detail = env_report(repo_root, config)
    print(f"aide env: bootstrap done ({final}: {detail})")
    return 0 if final == "ok" else 1


def _slug(title: str, max_words: int = 5) -> str:
    words = re.findall(r"[A-Za-z0-9]+", title.lower())
    return "-".join(words[:max_words]) or "item"


def _queue_titles(text: str) -> Dict[int, str]:
    titles: Dict[int, str] = {}
    for line in text.splitlines():
        m = re.match(r"^###\s+Item\s+0*(\d+)\s*:\s*(.+?)\s*$", line)
        if m:
            titles[int(m.group(1))] = m.group(2)
    return titles


#: Marks the start of a **forward-looking** aside inside a Dependencies section
#: — later items that depend on THIS one, not items this one depends on (e.g.
#: "**Downstream:** item 099 depends on this item's CI job"). Item numbers
#: after this marker are never read as blocking dependencies: extracting every
#: "Item NNN" mention in the section without it would misread "X depends on
#: this" as "this depends on X" and block on a backward reference to a later,
#: still-open item. Authors: put such asides after this exact marker so the
#: parser (and a human skimming the section) can tell the two apart.
_DEPENDENCIES_DOWNSTREAM_MARKER_RE = re.compile(r"\*\*Downstream\b", re.IGNORECASE)

#: Marks a quoted human-gate reach ("waits on gate-<hex> — `Blocks: items 119,
#: 120, 121`"). Transcribing the gate row's cell is the natural way to say
#: which gate holds this item, and the numbers in the quote are the GATE's
#: reach, not items this one depends on — read as blockers they grew edges
#: (and cycles) nobody authored. Like ``**Downstream``, the marker must be
#: DELIBERATE markup — a backticked or bold ``Blocks:`` label, the forms a
#: quoted table cell actually takes — never bare prose: "hard blocks: Items
#: 027 and 028 must land first" states real blockers, and an exclusion plain
#: English could trip would silently drop them. The pattern consumes to the
#: end of the line and no further: the quote opens no subsection, so a
#: dependency bullet on the next line must still be read (which also means a
#: reach quote must not wrap — keep it on one line, as the template says).
_DEPENDENCIES_BLOCKS_QUOTE_RE = re.compile(
    r"(?:`|\*\*)blocks\*{0,2}\s*:[^\n]*", re.IGNORECASE)


def _item_dependencies(repo_root: Path, config, number: int) -> List[int]:
    """Item numbers named in the spec's Dependencies section (best effort).

    Uses the same multi-item/range-aware, case-insensitive extraction as every
    other "does this reference item NNN" call site (`_referenced_item_numbers`)
    — a naive first-number-only regex here previously left every number after
    the first in "Items 093, 094, 095" unrecognised as a blocker. Text at or
    after a "**Downstream" marker is excluded (see
    `_DEPENDENCIES_DOWNSTREAM_MARKER_RE`), so a forward-looking "item 099
    depends on this" aside does not register as a backward blocker; likewise
    the rest of any line from a backticked or bold "Blocks:" marker on (see
    `_DEPENDENCIES_BLOCKS_QUOTE_RE`), so a quoted gate reach does not either.
    """
    idir = docs_dir(repo_root, config) / "items"
    specs = item_spec_paths(idir, number)
    if not specs:
        return []
    text = specs[0].read_text(encoding=_ENCODING)
    m = re.search(r"^##\s+Dependencies\s*$(.*?)(^##\s|\Z)", text, re.MULTILINE | re.DOTALL)
    section = m.group(1) if m else ""
    downstream = _DEPENDENCIES_DOWNSTREAM_MARKER_RE.search(section)
    if downstream is not None:
        section = section[: downstream.start()]
    section = _DEPENDENCIES_BLOCKS_QUOTE_RE.sub("", section)
    deps = set(_referenced_item_numbers(section))
    deps.discard(number)
    return sorted(deps)


def _pick_item(repo_root: Path, config, queue_text: str,
               claim_branches: List[str]) -> Optional[Tuple[int, str]]:
    """First queue item that is planned, unclaimed, and unblocked. (number, title).

    "Unblocked" covers four things: its `## Dependencies` are all under way,
    no claim branch exists for it, **no unresolved human gate holds it**, and,
    for a queue-end item, no other item of its queue still blocks
    (`queue_end_holds`). An item every bullet of which sits in a withdrawn
    stage is not planned work at all, and is skipped first
    (`withdrawn_stage_items`, issue #387). A
    gate naming items (directly, or via a stage reach) skips just those, so the
    queue keeps producing other work; an `all` gate stops everything, which is
    the point of declaring one — a pending decision that could invalidate what
    comes next must not have the loop racing ahead of it. A gates row too
    mis-shaped to read stops everything too, since what it holds is unknown.
    """
    ppath = docs_dir(repo_root, config) / "progress.md"
    plines = ppath.read_text(encoding=_ENCODING).splitlines() if ppath.is_file() else []
    _, _, item_status = _parse_item_status(plines) if plines else ([], [], {})
    gate_blocked, block_everything = gate_blocked_items(plines)
    if block_everything or unreadable_gate_rows(plines):
        return None
    # Anchored resolution, like every other branch->item call site since 1.5.0.
    # The old unanchored search read `aide/queue-016` as item 016 and
    # `aide/specs-queue-015` as item 015, marking those items permanently
    # "claimed" and therefore unclaimable — a queue branch is not an item claim.
    # This call site was missed when the shared helper landed.
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    claimed_nums = {n for n in (_branch_item_number(br, prefix) for br in claim_branches)
                    if n is not None}
    titles = _queue_titles(queue_text)
    withdrawn = withdrawn_stage_items(plines)
    holds = queue_end_holds(repo_root, config, queue_text, item_status,
                            withdrawn)
    for num in queue_item_numbers(queue_text):
        if item_status.get(num, "planned") != "planned":
            continue
        # A 📋 item whose every bullet sits in a withdrawn stage is work the
        # plan no longer wants (issue #387); a dropped item is ❌, and so
        # never reaches here.
        if num in withdrawn:
            continue
        if num in claimed_nums:
            continue
        if num in gate_blocked:
            continue
        # A queue-end item waits for the rest of its queue, spec or no spec
        # and wherever the file lists it (issue #347).
        if holds.get(num):
            continue
        deps = _item_dependencies(repo_root, config, num)
        # 🔍 blocks like 🚧 does: an item whose PR is still open is work that is
        # not in the base, so claiming a dependent off that base would branch
        # from a tree missing the very thing the dependency provides. Under
        # `auto-merge` this window is milliseconds; under `pr` it is however
        # long the human takes, which is exactly when it matters.
        # A ❌, ⏸️ or withdrawn-stage 📋 dependency has left the way
        # (`still_blocks`, issue #393).
        if any(still_blocks(d, item_status, withdrawn) for d in deps):
            continue
        return num, titles.get(num, f"item {num}")
    return None


def _open_queue_texts(repo_root: Path, config) -> List[str]:
    """Texts of the open queues, lowest-numbered first (derived state).

    Open as `claim` reads it: a 📋 item of a withdrawn stage, which it never
    offers, keeps no queue open (`queue_is_open`, issue #389).
    """
    qdir = docs_dir(repo_root, config) / "queue"
    if not qdir.is_dir():
        return []
    ppath = docs_dir(repo_root, config) / "progress.md"
    plines = ppath.read_text(encoding=_ENCODING).splitlines() if ppath.is_file() else []
    item_status = _parse_item_status(plines)[2]
    withdrawn = withdrawn_stage_items(plines)
    out: List[str] = []
    for path in iter_queue_paths(qdir):
        text = path.read_text(encoding=_ENCODING)
        if queue_is_open(text, item_status, withdrawn):
            out.append(text)
    return out


def _withdrawn_queued_lines(repo_root: Path, config) -> List[str]:
    """One line per 📋 item a queue lists every bullet of which sits in a
    withdrawn stage — what `claim` names when no queue is open but such
    items are still undropped (issue #389), with the remedy its ``none
    left`` report gives."""
    qdir = docs_dir(repo_root, config) / "queue"
    ppath = docs_dir(repo_root, config) / "progress.md"
    if not qdir.is_dir() or not ppath.is_file():
        return []
    plines = ppath.read_text(encoding=_ENCODING).splitlines()
    withdrawn = withdrawn_stage_items(plines)
    if not withdrawn:
        return []
    item_status = _parse_item_status(plines)[2]
    out: List[str] = []
    for path in iter_queue_paths(qdir):
        text = path.read_text(encoding=_ENCODING)
        titles = _queue_titles(text)
        for n in queue_item_numbers(text):
            if n in withdrawn and item_status.get(n, "planned") == "planned":
                stages = withdrawn[n]
                out.append(
                    f"  {n:03d} {titles.get(n, 'item ' + str(n))} — in "
                    f"withdrawn stage{'' if len(stages) == 1 else 's'} "
                    f"{', '.join(stages)} (❌ summary row), still 📋 in "
                    f"{path.name} — drop it ('aide progress set {n:03d} "
                    f"dropped --reason …'), or take the stage's summary row "
                    f"off ❌")
    return out


def _live_queue_text(repo_root: Path, config, number: Optional[int]) -> Optional[str]:
    """The queue to work: an explicit number, else the lowest-numbered OPEN
    queue (state derived from progress.md). Falls back to the highest queue
    declaring ``Status: Live`` only when progress.md is missing (legacy)."""
    qdir = docs_dir(repo_root, config) / "queue"
    if number is not None:
        path = queue_path(qdir, number)
        return path.read_text(encoding=_ENCODING) if path is not None else None
    if not qdir.is_dir():
        return None
    if (docs_dir(repo_root, config) / "progress.md").is_file():
        open_texts = _open_queue_texts(repo_root, config)
        return open_texts[0] if open_texts else None
    for path in sorted(iter_queue_paths(qdir), reverse=True):
        text = path.read_text(encoding=_ENCODING)
        if is_live_queue(text):
            return text
    return None


def _report_nothing_claimable(repo_root: Path, config, prefix: str,
                              candidates: List[str],
                              claim_branches: List[str]) -> int:
    """Say why `claim` found nothing, and exit non-zero when that is a defect.

    "none left" is a claim about the ground checked, not the repository
    (conventions.md §2), and `/aide-run-queue` reads it as "the queue is
    finished — stop and report". Every reason a queue can be open while
    nothing in it is offerable therefore has to be said out loud, because the
    alternative is a run that ends reporting success over work it never
    started: issue #137, where a failed push left a claim branch behind and
    the next run called the queue exhausted.

    Three of the reasons are ordinary — a claim in flight, a dependency not
    landed, a stage withdrawn under a 📋 item (issue #387) — and keep exit
    0. An **unpublished** claim is not: it is a `claim` whose push failed,
    holding an item on evidence no other checkout can see, so it exits 1 and
    says how to finish or release it. Nor is an
    **unreadable gate row**, which holds every item on a gate nobody can read:
    exit 1, naming the row.

    Every report that exits 0 with items still open ends on an ``early
    ready:`` fact (issue #331), which is what the queue-end step keys on to
    mark the queue's PR ready while a person decides a gate: see
    `_early_ready`. A bare ``none left`` carries none — that is exhaustion,
    the step's own trigger.
    """
    ppath = docs_dir(repo_root, config) / "progress.md"
    plines = ppath.read_text(encoding=_ENCODING).splitlines() if ppath.is_file() else []
    _, _, item_status = _parse_item_status(plines) if plines else ([], [], {})

    unreadable = unreadable_gate_rows(plines)
    if unreadable:
        print("none left — every item is held by a human-gate row aide cannot "
              "read, since what it blocks is unknown:")
        for lineno, problem in unreadable:
            print(f"  progress.md:{lineno}: a row that {problem}")
        print("  Repair the row — a '|' inside a cell is the usual cause — and "
              "claim again. `aide check` names it too.")
        return 1
    # Queue scan order, not numeric order: `_pick_item` walks the candidate
    # queues in order and each queue in its own order, so a report that
    # renumbered the items it rejected would not be describing the same walk.
    # It shows under `loop.claim_scope = "all-open"`, where sorting numerically
    # interleaves two queues that were scanned one after the other.
    scan_order: List[int] = []
    seen = set()
    titles: Dict[int, str] = {}
    holds: Dict[int, List[int]] = {}
    all_withdrawn = withdrawn_stage_items(plines)
    for qt in candidates:
        titles.update(_queue_titles(qt))
        holds.update(queue_end_holds(repo_root, config, qt, item_status,
                                     all_withdrawn))
        for n in queue_item_numbers(qt):
            if n not in seen:
                seen.add(n)
                scan_order.append(n)
    open_items = {n for n in seen
                  if item_status.get(n, "planned") == "planned"}
    open_ordered = [n for n in scan_order if n in open_items]
    # 📋 items of a withdrawn stage (issue #387) are named, never offered,
    # and wait on nothing a gate or a claim could release: every reading
    # below of what holds the queue takes the rest.
    withdrawn = {n: st for n, st in all_withdrawn.items()
                 if n in open_items}
    live_items = open_items - set(withdrawn)
    live_ordered = [n for n in open_ordered if n not in withdrawn]

    # Attribute the empty result to a gate ONLY when a gate actually explains
    # it: an `all` gate, or a gate reaching an item that is still open in a
    # queue we just scanned. A gate holding unrelated items — or naming
    # nothing — is not why this run found no work, and blaming it would be a
    # false explanation, which is worse than none.
    def _reached(g):
        if g.blocks_all:
            return set(live_items)
        if g.stage is not None:
            return set(gate_stage_items(plines, g)) & live_items
        return set(g.blocks) & live_items

    all_gates = human_gates(plines)
    relevant = [(n, g, gid) for n, (g, gid)
                in enumerate(zip(all_gates, gate_ids(all_gates)), start=1)
                if g.kind != "approved" and (g.blocks_all or _reached(g))]
    if not relevant and not open_items:
        print("none left")
        return 0

    claimed: Dict[int, str] = {}
    for br in claim_branches:
        num = _branch_item_number(br, prefix)
        if num is not None:
            claimed.setdefault(num, br)
    # A claim branch origin lacks holds its item without being work in flight,
    # for one of three reasons (issue #364), and each exits 1: an exit 0 would
    # tell the runner to wait on a hold nothing in the loop will release.
    stranded = {n: pair for n, pair
                in _off_origin_claim_branches(repo_root, config, prefix).items()
                if n in live_items}
    gated: set = set()
    for _, g, _ in relevant:
        gated |= _reached(g)
    early = _early_ready(repo_root, config, live_ordered,
                         [(n, g) for n, g, _ in relevant], gated,
                         claimed, item_status, scan_order, holds,
                         all_withdrawn)

    def _withdrawn_reason(num: int) -> str:
        stages = withdrawn[num]
        return (f"in withdrawn stage{'' if len(stages) == 1 else 's'} "
                f"{', '.join(stages)} (❌ summary row), so not offered — drop "
                f"it ('aide progress set {num:03d} dropped --reason …'), or "
                f"take the stage's summary row off ❌")

    def _stranded_reason(num: int) -> str:
        br, why = stranded[num]
        if why.kind == OFF_ORIGIN_UNPUBLISHED:
            return (f"claimed by {br}, WHICH ORIGIN HAS NEVER SEEN — the "
                    f"claim's push did not land, so this item is held by a "
                    f"claim no other checkout can see")
        if why.kind == OFF_ORIGIN_GONE_LANDED:
            return (f"claimed by {br}, which origin has DELETED and whose every "
                    f"commit is already in {why.where} — its work landed or "
                    f"the claim was abandoned; either way it is not in flight")
        return (f"claimed by {br}, which origin has deleted and whose work "
                f"COULD NOT BE FOUND in {why.where} — not in flight: it landed "
                f"in a shape that cannot be measured here, or this checkout "
                f"holds the only copy of it")

    def _stranded_lines() -> None:
        for num in open_ordered:
            if num in stranded:
                print(f"  {num:03d} {titles.get(num, 'item ' + str(num))} — "
                      f"{_stranded_reason(num)}")

    def _stranded_notice() -> None:
        kinds = {why.kind for _, why in stranded.values()}
        if OFF_ORIGIN_UNPUBLISHED in kinds:
            print("  An unpublished claim is a failed 'aide claim' push, not "
                  "work in flight. Publish it ('git push -u origin <branch>') "
                  "or release the item ('git branch -D <branch>'), then claim "
                  "again.")
        if OFF_ORIGIN_GONE_LANDED in kinds:
            hints = sorted({_gc_merged_hint(why.where, config)
                            for _, why in stranded.values()
                            if why.kind == OFF_ORIGIN_GONE_LANDED})
            print("  A claim branch deleted on origin with all of it already "
                  "in its base is never re-published. If its work is the "
                  "item's, record it ('aide progress set <NNN> done') first; "
                  "then " + " / ".join(f"'{h}'" for h in hints) + " deletes "
                  "the branch, releasing the item if it is still open.")
        if OFF_ORIGIN_GONE_UNFOUND in kinds:
            print("  A claim branch deleted on origin whose work could not be "
                  "found in its base is never re-published blindly. A squash "
                  "merge the base has since built over, or git older than "
                  "2.38, hides landed work, so check whether its work merged: if "
                  "it did, record the item ('aide progress set <NNN> done') "
                  "and delete the branch ('git branch -D <branch>'); if not, "
                  "land its work or release the item.")

    if relevant:
        print("none left — held by an unresolved human gate:")
        for n, g, gid in relevant:
            held = sorted(_reached(g))
            where = "everything" if g.blocks_all else (
                f"{g.reach} — holding " + ", ".join(f"{i:03d}" for i in held))
            print(f"  gate {n}: {g.text}{f' ({gid})' if gid else ''} — blocks {where}")
        print("  A person decides these, never an agent. Once decided: "
              "aide gate approve <n|ID> --evidence \"…\" (or gate decline <n|ID>).")
        # No gate reaches a withdrawn stage's 📋 item (`_reached` takes the
        # live ones), so it is named here or nowhere (issue #389).
        for num in open_ordered:
            if num in withdrawn:
                print(f"  {num:03d} {titles.get(num, 'item ' + str(num))} — "
                      f"{_withdrawn_reason(num)}")
        # A broken state is not hidden behind a gate: an unpublished or
        # deleted claim exits 1 on this path exactly as on the per-item one.
        if stranded:
            _stranded_lines()
            _stranded_notice()
            return 1
        print(early)
        return 0

    # Open items, none offered. Give the reason per item, in the order
    # `_pick_item` rejects them, so the two cannot drift into disagreeing
    # about why an item was skipped.

    print(f"none left — {len(open_ordered)} item(s) still open, none claimable:")
    for num in open_ordered:
        head = f"  {num:03d} {titles.get(num, 'item ' + str(num))} —"
        br = claimed.get(num)
        if num in withdrawn:
            print(f"{head} {_withdrawn_reason(num)}")
        elif num in stranded:
            print(f"{head} {_stranded_reason(num)}")
        elif br is not None:
            print(f"{head} claimed by {br}, already in flight")
        else:
            blockers = [d for d in _item_dependencies(repo_root, config, num)
                        if still_blocks(d, item_status, all_withdrawn)]
            held_by = holds.get(num, [])
            blockers += [d for d in held_by if d not in blockers]
            if blockers:
                print(f"{head} waiting on "
                      + ", ".join(f"{d:03d} ({item_status.get(d, 'planned')})"
                                  for d in blockers)
                      + (" — a queue-end item, held until the rest of "
                         "its queue has left the way" if held_by else ""))
            else:
                print(f"{head} open and unblocked, yet not offered — please "
                      f"report this")

    if stranded:
        _stranded_notice()
        return 1
    print(early)
    return 0


def _early_ready(repo_root: Path, config, open_ordered: List[int],
                 gates: List[Tuple[int, "HumanGate"]], gated: set,
                 claimed: Dict[int, str], item_status: Dict[int, str],
                 scan_order: List[int],
                 holds: Optional[Dict[int, List[int]]] = None,
                 withdrawn: Collection[int] = ()) -> str:
    """The ``early ready:`` line ending a ``none left — …`` report that exits 0.

    ``yes`` when every gate holding the queue is still ⏳ awaiting its
    decision, every open item waits on one of them — one reaches it, or it
    waits only on items that do — no open item is claimed, and at least one
    item of the queues checked is ✅. Then nothing but a person's decision
    stands between the queue and its end, and the queue's PR already carries
    built work for CI to check while they decide: the queue-end step's early
    trigger (issue #331). ``no`` otherwise, with the first reason found, in
    the order the clauses are listed.

    A ❌ declined gate is not a decision pending but one made against the
    plan, which is re-planned rather than shipped, so it says ``no``. The ✅
    clause is what keeps a queue held whole by its own plan gate, nothing
    built, from reading as ready. An ``all`` gate over a queue with nothing
    open says ``yes`` in words of its own: every item has left the queue,
    so the batch is as built as it will be, and CI on it is what the person
    deciding the gate would want to see.

    The fact is the engine's so the runner never reads it out of the reason
    prose, which is worded for a person and has changed before.
    """
    held = {n for n in gated if n not in claimed}
    # An item waiting only on held items is held too: to a fixed point, since
    # a chain of dependencies can hang off one gated item, listed in any order.
    # A queue-end item waits on its queue-mates (`holds`, issue #347) as it
    # waits on a declared dependency.
    holds = holds or {}
    deps = {n: [d for d in _item_dependencies(repo_root, config, n)
                if still_blocks(d, item_status, withdrawn)]
            for n in open_ordered}
    for n in open_ordered:
        deps[n] += [d for d in holds.get(n, []) if d not in deps[n]]
    grew = True
    while grew:
        grew = False
        for n in open_ordered:
            if n in held or n in claimed or not deps[n]:
                continue
            if all(d in held for d in deps[n]):
                held.add(n)
                grew = True
    landed = [n for n in scan_order if item_status.get(n) == "complete"]
    loose = [n for n in open_ordered if n not in held]
    busy = [n for n in loose if n in claimed]
    settled = [(n, g) for n, g in gates if g.kind != "awaiting"]
    if not gates:
        why = "no gate holds an open item"
    elif settled:
        n, g = settled[0]
        why = (f"gate {n} is declined, so the plan is re-planned, not shipped"
               if g.kind == "declined" else
               f"gate {n} has a status aide cannot read")
    elif busy:
        why = f"{busy[0]:03d} is claimed, so work is still in flight"
    elif loose:
        why = f"{loose[0]:03d} waits on something no human gate holds"
    elif not landed:
        why = ("no item of the queue is ✅ yet, so there is no built work "
               "for CI to check")
    elif not open_ordered:
        return (f"early ready: yes — nothing is left open, a human gate "
                f"holds the queue's end, and {len(landed)} item(s) are ✅")
    else:
        return (f"early ready: yes — every open item waits on a human gate, "
                f"and {len(landed)} item(s) are ✅")
    return f"early ready: no — {why}"


def cmd_claim(args: argparse.Namespace) -> int:
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    if not _require_repository("claim", repo_root):
        return 1
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    mode = str(config["git"].get("mode", "auto-merge"))
    if not _require_origin("claim", repo_root, mode):
        return 1
    scope = str(config["loop"].get("claim_scope", "live-queue"))
    if mode != "local":
        git(["fetch", "--all", "--prune"], repo_root, check=False)

    if args.queue is None and scope == "all-open":
        # Cross-queue claiming (opt-in): scan every open queue in number order.
        candidates = _open_queue_texts(repo_root, config)
    else:
        queue_text = _live_queue_text(repo_root, config, args.queue)
        candidates = [queue_text] if queue_text is not None else []
    if not candidates:
        print("aide claim: no open queue found", file=sys.stderr)
        if args.queue is None:
            # A queue left with only a withdrawn stage's 📋 items is not open
            # (issue #389), and this is the last place they could be named.
            for line in _withdrawn_queued_lines(repo_root, config):
                print(line, file=sys.stderr)
        return 1
    branches = _list_claim_branches(repo_root, prefix)
    pick = None
    for queue_text in candidates:
        pick = _pick_item(repo_root, config, queue_text, branches)
        if pick is not None:
            break
    if pick is None:
        return _report_nothing_claimable(repo_root, config, prefix,
                                         candidates, branches)
    number, title = pick
    branch = claim_branch_name(prefix, number, title)

    # What this claim branches off, and what its `merge` will return it to.
    # `switch -c` already branches from whatever is checked out, so claiming
    # from a queue branch has always branched correctly — only the merge target
    # was fixed. Inferring the base from a *recognised queue branch* (never from
    # an arbitrary branch, which would silently retarget a merge) closes that
    # half without asking every caller to pass a flag it cannot know.
    current = _current_branch(repo_root)
    base = args.base or (current if _is_queue_branch(current, prefix)
                         else str(config["git"].get("main_branch", "main")))

    if not _local_branch_exists(repo_root, base):
        print(f"aide claim: base '{base}' is not a local branch — an item is "
              f"branched from its base and merged back into it, so the base "
              f"must be a branch this checkout can update", file=sys.stderr)
        return 1

    pin_report = _interface_pin_report(repo_root, config, number)
    if args.dry_run:
        print(f"would claim item {number:03d} -> {branch} ({title}); base {base}")
        if pin_report:
            print(pin_report)
        return 0
    # Branch FROM the base, explicitly. `switch -c` with no start point uses
    # HEAD, which would let the branch's actual starting point disagree with
    # the base it records — claiming with `--base main` while a queue branch is
    # checked out would start from the queue branch and then merge the whole of
    # it into main. Naming the start point makes the two agree by construction.
    git(["switch", "-c", branch, base], repo_root)
    _record_branch_base(repo_root, branch, base)
    # `/aide-run-queue` reaches its roles through `sync` and this verb, never
    # through `check`, so the §1 guarantee is kept here too: on the new branch,
    # before the push, so the inbox lands with the item and the claim's own
    # base is left exactly as it was.
    ensure_insights_inbox(repo_root, config, verb="claim")
    if mode != "local":
        failure = _push_new_branch(repo_root, branch)
        if failure is not None:
            # The branch is KEPT, not rolled back. The push may have reached
            # origin before the client gave up, and deleting here would then
            # leave a remote claim branch blocking the item with nothing local
            # left to explain it. What must not happen is the half-claim
            # reading as a claim: `_pick_item` skips any item with a claim
            # branch, so before this the next run said "none left" and an
            # unattended loop finished, successfully, having built nothing.
            # `claim`, `status` and `check` all name an unpublished
            # claim now, so it cannot pass for work in flight.
            print(f"aide claim: {failure}\n"
                  f"Item {number:03d} is claimed LOCALLY ONLY: {branch} exists "
                  f"here (base {base}) and origin has never seen it, so no "
                  f"other checkout can see the claim. Publish it with "
                  f"'git push -u origin {branch}' once the remote is "
                  f"reachable, or release the item with 'git switch {base} && "
                  f"git branch -D {branch}'.", file=sys.stderr)
            return 1
    note = "" if base == str(config["git"].get("main_branch", "main")) else f" (base {base})"
    print(f"claimed item {number:03d}: {branch} — {title}{note}")
    if pin_report:
        print(pin_report)
    return 0


def interface_pins(spec_text: str, deps: List[int],
                   item_status: Dict[int, str]) -> List[Tuple[int, str, int, str]]:
    """``(bullet index, label, dependency, status)`` for each Assumption that
    pins a dependency's interface — the re-check signal of conventions.md §5.

    An Assumption naming an item under ``## Dependencies`` was written before
    that item was built, and a claim happens only once it has left the way, so
    the pin is what says "re-check me". Three shapes are not the signal and
    are skipped here exactly as §5 lists them: an engine-marked audit entry
    (`assumption_engine_pin`), a bullet already carrying a re-check, and —
    reported rather than skipped — a dependency that left the queue as ❌/⏸️,
    or as 📋 in a withdrawn stage, which has no code to check against
    (`_interface_pin_report` decides which, issue #393).
    """
    out: List[Tuple[int, str, int, str]] = []
    for index, bullet in enumerate(_assumption_bullets(spec_text), 1):
        named = [d for d in _referenced_item_numbers(bullet) if d in deps]
        if not named or assumption_engine_pin(bullet) is not None:
            continue
        # A *recorded* re-check carries a version or a date somewhere in the
        # bullet; "to be re-checked before tests" carries neither, and is
        # exactly the bullet to surface.
        if (re.search(r"re-?checked", bullet, re.IGNORECASE)
                and re.search(r"\d+\.\d+\.\d+|\d{4}-\d{2}-\d{2}", bullet)):
            continue
        m = re.match(r"^\s*[-*]\s+\**\s*([^:*]{1,40}?)\s*(?:\(|:|\*\*)", bullet)
        label = m.group(1).strip() if m else f"assumption #{index}"
        for dep in named:
            out.append((index, label, dep, item_status.get(dep, "unknown")))
    return out


def _interface_pin_report(repo_root: Path, config, number: int) -> Optional[str]:
    idir = docs_dir(repo_root, config) / "items"
    specs = item_spec_paths(idir, number)
    if not specs:
        return None
    deps = _item_dependencies(repo_root, config, number)
    if not deps:
        return None
    ppath = docs_dir(repo_root, config) / "progress.md"
    plines = (ppath.read_text(encoding=_ENCODING).splitlines()
              if ppath.is_file() else [])
    item_status = _parse_item_status(plines)[2]
    pins = interface_pins(specs[0].read_text(encoding=_ENCODING), deps,
                          item_status)
    if not pins:
        return None
    # Left the way without landing — ❌, ⏸️, or 📋 in a withdrawn stage
    # (`still_blocks`, issue #393) — so there is no code to check against.
    withdrawn = withdrawn_stage_items(plines)
    parts = [f"{label} (item {dep:03d}"
             + (", no code to check against" if st != "complete"
                and not still_blocks(dep, item_status, withdrawn) else "")
             + ")"
             for _, label, dep, st in pins]
    distinct = len({index for index, _, _, _ in pins})
    return (f"aide claim: {distinct} assumption(s) pin a dependency's interface "
            f"— re-check before tests are written (conventions.md §5): "
            + "; ".join(parts))


def _find_claim_branch(repo_root: Path, prefix: str, number: int) -> Optional[str]:
    for br in _list_claim_branches(repo_root, prefix):
        if _branch_item_number(br, prefix) == number:
            return br
    return None


def _git_dir(repo_root: Path) -> Path:
    """The repository's git directory, resolved.

    Not ``repo_root / ".git"``: that is a *file* in a linked worktree or a
    submodule, so probing `.git/MERGE_HEAD` there answers "no in-progress
    merge" for every such consumer — the exact reading the caller below must
    not get wrong.
    """
    out = git(["rev-parse", "--git-dir"], repo_root, check=False).stdout.strip()
    if not out:
        return repo_root / ".git"
    path = Path(out)
    return path if path.is_absolute() else repo_root / path


#: In-progress git operations, and how git names each one's marker in the git
#: directory. `switch` and `pull --rebase` on top of any of them either refuse
#: (leaving a half-merge the loop cannot read) or rewrite commits the human is
#: mid-way through authoring.
_INTERRUPTED_OPS: Tuple[Tuple[str, str], ...] = (
    ("rebase-merge", "a rebase is in progress"),
    ("rebase-apply", "a rebase or 'git am' is in progress"),
    ("MERGE_HEAD", "a merge is in progress with conflicts unresolved"),
    ("CHERRY_PICK_HEAD", "a cherry-pick is in progress"),
    ("REVERT_HEAD", "a revert is in progress"),
)


def _unmerged_paths(repo_root: Path) -> List[str]:
    """Every path git currently holds unmerged, repo-relative, sorted."""
    try:
        out = git(["diff", "--name-only", "--diff-filter=U"], repo_root, check=False)
    except (OSError, subprocess.SubprocessError):
        return []
    if out.returncode != 0:
        return []
    return sorted(set(root_relative(
        repo_root, [line.strip() for line in out.stdout.splitlines() if line.strip()])))


def _interrupted_op(repo_root: Path) -> Optional[str]:
    """The in-progress git operation this tree is stopped in, or ``None``.

    One reading of `_INTERRUPTED_OPS`, shared by the callers that ask the
    question for different reasons: `_unsafe_tree_state` asks it *before*
    acting, `_stalled_pull` asks it *after* a `pull --rebase` came back
    non-zero. The second is what tells a failed pull that stopped on a
    conflict apart from one that never started — no upstream configured, an
    unreachable origin — since only the former leaves a marker behind.
    """
    gdir = _git_dir(repo_root)
    for marker, what in _INTERRUPTED_OPS:
        if (gdir / marker).exists():
            return what
    return None


def _continue_command(repo_root: Path) -> str:
    """What finishes the operation this tree is stopped in, once staged."""
    gdir = _git_dir(repo_root)
    if (gdir / "rebase-merge").exists() or (gdir / "rebase-apply").exists():
        return "git rebase --continue"
    if (gdir / "CHERRY_PICK_HEAD").exists():
        return "git cherry-pick --continue"
    if (gdir / "REVERT_HEAD").exists():
        return "git revert --continue"
    return "git commit --no-edit"


def _abort_command(repo_root: Path) -> str:
    """What throws away the operation this tree is stopped in.

    The mirror of `_continue_command`, and derived the same way rather than
    written as a fixed pair: `_stalled_pull` reaches this with a cherry-pick or
    a revert marker whenever the pull refused because one was *already* in
    progress, and `git rebase --abort` is not merely unhelpful there — it fails.
    """
    gdir = _git_dir(repo_root)
    if (gdir / "rebase-merge").exists() or (gdir / "rebase-apply").exists():
        return "git rebase --abort"
    if (gdir / "CHERRY_PICK_HEAD").exists():
        return "git cherry-pick --abort"
    if (gdir / "REVERT_HEAD").exists():
        return "git revert --abort"
    return "git merge --abort"


def _inbox_conflict_hint(repo_root: Path,
                         config: Dict[str, Dict[str, object]]) -> Optional[str]:
    """Name `insights resolve` when the stalled operation is stuck on the inbox.

    The verb is useless to the role that needs it unless the thing that stalls
    says so. `insights.md` is append-only and every role captures into it
    (`_ALWAYS_AUTHORISED`), so two open branches conflict here as a matter of
    course — while the agent that runs `aide merge` is the `validator`, which
    preloads a different skill and has read nothing about the inbox. A message
    at the point of the stall reaches every role, every runtime, and a human,
    without any of them having had to read anything first.

    It also says whether the inbox is the *only* unmerged path, because that
    decides whether the verb finishes the job or is merely one of the steps.
    """
    ddir = docs_dir(repo_root, config)
    try:
        rel = (ddir / "insights.md").relative_to(repo_root).as_posix()
    except ValueError:          # a docs_dir outside the repo: no relative name
        return None
    unmerged = _unmerged_paths(repo_root)
    if rel not in unmerged:
        return None
    verb = aide_command(repo_root, "insights resolve")
    warn = (f"Do NOT resolve {rel} by hand — it is append-only, so the "
            f"conflict is a union of entries, and retyping the block is where "
            f"a captured claim gets reworded (conventions.md §1).")
    others = [p for p in unmerged if p != rel]
    if not others:
        return (f"{rel} is the ONLY unmerged path. {warn} `{verb}` writes the "
                f"union and stages it (add --dry-run to read it first), then "
                f"`{_continue_command(repo_root)}` finishes this.")
    return (f"{rel} is one of {len(unmerged)} unmerged paths. {warn} `{verb}` "
            f"settles that one; the rest are yours: {', '.join(others)}.")


def _stalled_pull(repo_root: Path, config: Dict[str, Dict[str, object]],
                  res: "subprocess.CompletedProcess") -> Optional[str]:
    """One line for a ``pull --rebase`` that stopped mid-way, else ``None``.

    ``git pull --rebase`` comes back non-zero for two unrelated reasons and
    only one of them is a state the caller must not act on. A pull that never
    started — no upstream for this branch, an origin that cannot be reached, a
    refused fetch — leaves the repository byte-for-byte as it was, and every
    call site below has always continued past it into a local operation that
    is still correct; making that a refusal would stall an unattended run over
    a missing remote. A pull that stopped **inside** the rebase leaves
    conflicts in the index and a marker in the git directory, and there the
    next `merge`, `commit` or `switch` cannot run at all — git refuses, naming
    that second operation rather than the rebase that caused it, so the
    operator reads a failure of something they did not ask for while the tree
    sits in a state neither message describes (issue #178).

    So the discriminator is the marker, not the exit code — and the message
    names the operation git reports rather than assuming a rebase, since a
    pull that refused because a cherry-pick or a merge was already under way
    lands here with that marker and no rebase of its own. The message names
    `insights resolve` when the inbox is what stopped it: `insights.md` is
    append-only and every role captures into it, which makes it the conflict
    this loop produces as a matter of course, and none of the three roles that
    reach these call sites has read anything about it.
    """
    if res.returncode == 0:
        return None
    what = _interrupted_op(repo_root)
    if what is None:
        return None
    return f"git pull --rebase could not complete — {_stopped_state(repo_root, config, what)}"


def _stopped_state(repo_root: Path, config: Dict[str, Dict[str, object]],
                   what: str) -> str:
    """*what* is in progress, and the two ways out of it — one sentence.

    Shared by `_stalled_pull` (a pull that stopped, or refused because *what*
    was already under way) and the guard `_commit_docs_files` runs before it
    commits, so both name the same state the same way. Never "the rebase
    stopped": *what* is whichever of `_INTERRUPTED_OPS` is in progress, and a
    cherry-pick ALREADY under way is the reachable case at the committer.
    Naming the operation git reports, and the abort that matches it, is the
    whole point — a message that guessed `git rebase --abort` there would hand
    the reader a command that fails. `insights resolve` is named when the
    inbox is what stopped it.
    """
    hint = _inbox_conflict_hint(repo_root, config)
    return (f"{what}."
            + (f" {hint}" if hint else "")
            + f" Finish that state — resolve and stage, then "
              f"`{_continue_command(repo_root)}` — or abort it "
              f"(`{_abort_command(repo_root)}`), then re-run.")


def _dirty_paths(repo_root: Path) -> List[str]:
    """Tracked paths carrying uncommitted changes, as git reports them.

    `-z`, not plain `--porcelain`: without it git **quotes and escapes** a path
    holding a space or a non-ASCII byte — `"docs/h\303\251llo/progress.md"` —
    which is neither the path on disk nor anything a caller can compare one
    against. NUL-terminated records never quote and never escape, so a consumer
    whose docs directory has a space in it reads the same as everyone else.

    Paths are relative to the git **worktree top level**, not to the cwd and not
    to `repo_root` — git is consistent about that, and a caller resolving them
    must be too.
    """
    out = git(["status", "--porcelain", "-z"], repo_root, check=False).stdout
    fields = out.split("\0")
    paths: List[str] = []
    i = 0
    while i < len(fields):
        record, i = fields[i], i + 1
        if len(record) < 4:                     # the empty tail after the last NUL
            continue
        code, path = record[:2], record[3:]
        if code[0] in "RC":
            i += 1                              # a rename/copy's SOURCE is its own field
        if code == "??":                        # untracked — see _unsafe_tree_state
            continue
        paths.append(path)
    return paths


def _unsafe_tree_state(repo_root: Path,
                       tick_path: Optional[Path] = None) -> Optional[str]:
    """Why this tree must not be switched/pulled/merged, or None if it may be.

    `aide merge` exists so that agents do not improvise git (§3), which means a
    consumer obeying §3 has no remaining place to be careful: whatever the verb
    does unconditionally is what happens. It already refuses one adjacent
    footgun with a precise diagnosis — a base that resolves but is not a local
    branch — and this is the same class, an operation that silently produces a
    wrong result while reporting success (issue #133).

    Untracked files are deliberately NOT dirty here. They survive `switch` and
    `pull` untouched, a loop leaves them around constantly, and a merge that
    genuinely collides with one aborts with git's own message through the merge
    path below. Refusing on them would block the common case to catch nothing.
    """
    interrupted = _interrupted_op(repo_root)
    if interrupted:
        return interrupted
    paths = _dirty_paths(repo_root)
    if not paths:
        return None
    # The one dirty tree this verb is likely to have caused itself: `--no-commit`
    # (on `merge` or on `progress set`) writes the tick and deliberately leaves
    # it uncommitted, and the NEXT merge — of any item — then meets this check.
    # The state is genuinely unsafe (git refuses `pull --rebase` over ANY
    # unstaged change, not merely a conflicting one), so it is still a refusal;
    # what it must not be is a mystery.
    #
    # Compared as resolved paths against the worktree top, never as strings
    # against `repo_root`: `aide.toml` may sit BELOW git's top level, and there
    # git's `docs/aide/progress.md` is this repo's `sub/docs/aide/progress.md`.
    if tick_path is not None and len(paths) == 1:
        top = git_toplevel(repo_root)
        try:
            is_tick = (Path(top or repo_root) / paths[0]).resolve() == tick_path.resolve()
        except OSError:                          # an unresolvable path is not the tick
            is_tick = False
        if is_tick:
            return (f"{paths[0]} carries an uncommitted status tick — a "
                    f"`--no-commit` run wrote it and left committing to you. It "
                    f"is the only change in the tree; commit or discard it")
    shown = ", ".join(paths[:3])
    more = f" (+{len(paths) - 3} more)" if len(paths) > 3 else ""
    return f"the working tree has uncommitted changes: {shown}{more}"


def _has_unpushed_merge(repo_root: Path, upstream: str = "@{u}") -> bool:
    """Does HEAD carry a merge commit its upstream has not seen?

    The one shape `git pull --rebase` must not run over: rebasing DROPS the
    merge and replays both parents' commits individually, so a conflict a human
    resolved by hand inside that merge comes back (issue #133). No upstream
    means nothing to rebase against, which is not this shape. *upstream* names
    the ref to compare against when the branch has no tracking ref of its own
    — `sync --item` pulls `origin/<claim>` by name, so it asks about that ref
    (issue #235).
    """
    res = git(["rev-list", "--merges", f"{upstream}..HEAD"], repo_root, check=False)
    return res.returncode == 0 and bool(res.stdout.strip())


class _Terminated(BaseException):
    """Raised in place of a terminating signal, so a `finally` can run.

    Deliberately a `BaseException`: it is not an error the surrounding code
    should ever catch and continue past, exactly like the `KeyboardInterrupt`
    it stands beside.
    """


@contextlib.contextmanager
def _restore_on_signal(signals: Tuple[str, ...] = ("SIGTERM", "SIGHUP")):
    """Context manager: turn terminating signals into `_Terminated` inside it.

    `KeyboardInterrupt` already unwinds the stack, so a `try` arm covers Ctrl-C
    for free. `SIGTERM` does not — Python's default handler ends the process
    where it stands, no `finally`, no `except` — and SIGTERM is exactly how the
    unattended cases in issue #174 arrive: a CI job's timeout, a runner's wall
    clock, a supervisor tearing down a stuck step. Without this, the crash-safe
    restore below would cover only the case a human is present to watch.

    `SIGKILL` and a hard OOM kill remain uncoverable by construction, which is
    why the refusal in `cmd_merge` (issue #174, half 2) exists as well: this
    makes the interrupted run tidy up, that makes the *next* run safe whether
    or not it did.

    Best effort about where it can be installed: `signal.signal` is main-thread
    only and not every name exists on every platform (Windows has no SIGHUP).
    A signal it cannot claim is simply left alone.
    """
    def _raise(signum, _frame):
        raise _Terminated(signum)

    previous = []
    for name in signals:
        sig = getattr(signal, name, None)
        if sig is None:
            continue
        try:
            previous.append((sig, signal.signal(sig, _raise)))
        except (ValueError, OSError, RuntimeError):
            continue
    try:
        yield
    finally:
        for sig, old in previous:
            try:
                signal.signal(sig, old)
            except (ValueError, OSError, RuntimeError):
                pass


def _restore_claim_branch(repo_root: Path, branch: str, tip: str,
                          base: Optional[str] = None) -> None:
    """Put back a claim branch deleted ahead of a step that then failed.

    `merge` deletes the claim branch BEFORE the post-merge test run (so the run
    sees the refs a fresh clone would). Every exit after that point must
    therefore be re-runnable: without the ref, `_find_claim_branch` finds
    nothing and the retry dies at "no claim branch found" — with the work
    merged, un-ticked and unpushed, which is the state a human least wants to
    meet a refusal in.

    Re-runnable means *against the same base*, not merely runnable. `git
    branch -d` takes the branch's config section with the ref, and
    `branch.<claim>.aide-base` is the only input `resolve_base` has beyond
    `--base` — so a retry that found the ref put back resolved its base to
    `main_branch` and said nothing. A consumer's invited re-run fast-forwarded
    a whole queue branch onto `main` and pushed it, past its
    one-reviewed-PR-per-queue gate, with nothing in the output naming `main`
    (issue #167). *base* is the base THIS run resolved to and merged into —
    not what the branch recorded beforehand: a run given `--base` landed
    somewhere the record did not say, and a retry must land there again. It
    is written unconditionally, so a `branch -d` that refused (record intact,
    and possibly stale against `--base`) is corrected the same way as one
    that succeeded.
    """
    if tip and branch not in _local_branches(repo_root):
        git(["branch", branch, tip], repo_root, check=False)
    if base:
        _record_branch_base(repo_root, branch, base)


def _promote_item_to_complete(repo_root: Path, config, number: int,
                              before: Dict[Path, Optional[bytes]],
                              no_commit: bool = False,
                              extra_rels: Tuple[str, ...] = ()
                              ) -> Optional[Tuple[str, bool]]:
    """Record item *number* as ✅ in progress.md and commit it with *extra_rels*.

    Returns ``None`` when there is nothing more to do — the commit made, or
    none owed — else ``(reason, committed)`` from `_commit_or_put_back`, for
    `cmd_merge` to refuse its push on (issue #312). *before* is the snapshot
    `cmd_merge` took ahead of every file the tick's commit carries — this
    progress.md and whatever *extra_rels* name — so a commit that did not
    happen leaves each of them as it was before the ledger row and the inbox
    entry were written, and the re-run writes them once. Not "best effort,
    never fatal" any longer: that held while the merge counted as landed the
    moment it was made, and the push after it then carried the merge to
    origin without any of this (the docstring of `_commit_docs_files` has
    the rest).

    Deliberately quiet about a no-op: the item may already be ✅ (a re-run, or a
    consumer still driving the old `progress set NNN done` ordering), and the
    merge itself is the thing that succeeded. It is *not* quiet about a missing
    progress.md, which is a real misconfiguration — but that alone is a
    sentence, never a refused push: there is nothing to tick.

    Since 1.53.0 `cmd_merge`'s document gate reaches a lost progress.md first:
    with `docs_dir` present it is an `aide check` error, and the merge is
    refused before this runs (issue #232). The branch below is left for a repo
    with no document set at all, where the check passes and there is nothing
    to tick.

    *extra_rels* are paths the same commit carries — the ledger row `merge`
    has just appended (§1 → `ledger.md`). One commit, because the row and the
    ✅ are one fact about one item: two would let a run land the tick and lose
    the row, leaving a ledger a reader has to reconcile against progress.md.
    They are committed even where the tick itself is a no-op (an item ticked
    by hand ahead of its merge), since the row is new then. A re-run over an
    item the earlier run already ticked and recorded brings no row (issue
    #346): with no path to commit — a no-op tick and no row — nothing is
    committed and nothing is owed, and the push that failed is all it retries.
    """
    progress_path = docs_dir(repo_root, config) / "progress.md"
    rels = list(extra_rels)
    if not progress_path.is_file():
        print(f"aide merge: item {number:03d} merged, but {progress_path} was "
              f"not found, so its status was NOT recorded", file=sys.stderr)
    else:
        text = progress_path.read_text(encoding=_ENCODING)
        splits: List[BulletSplit] = []
        updated = set_item_status(text, number, "complete", splits)
        if updated != text:
            progress_path.write_text(updated, encoding="utf-8")
            print(f"item {number:03d}: set to done (merged)")
            _report_bullet_splits(number, updated.splitlines(), splits)
            rels.insert(0, str(config["project"].get("docs_dir", "docs/aide"))
                        + "/progress.md")
    if rels and _commits_here(no_commit, repo_root, before):
        failure, committed = _commit_or_put_back(
            repo_root, config, f"progress(aide): item {number:03d} -> done",
            rels, before)
        if failure is not None:
            return failure, committed
    return None


# --------------------------------------------------------------------------- #
# the merge's suite run — failure identity, the base run, the result store
# (issue #275, §4)
# --------------------------------------------------------------------------- #
#: pytest's exit code for "the run finished and some tests failed" — the one
#: red exit whose report names every failure. 2 (interrupted), 3 (internal
#: error), 4 (usage) and 5 (nothing collected) each leave a report that is not
#: the whole suite, so a comparison drawn from one would be a guess.
_PYTEST_TESTS_FAILED = 1
#: Long options that make what a run executes depend on the order failures
#: arrive in, or on an earlier run's cache. Either way the failure set stops
#: being a property of the tree, and comparing two of them compares runs.
_ORDER_DEPENDENT_LONG = ("--exitfirst", "--maxfail", "--lf", "--last-failed",
                         "--ff", "--failed-first", "--sw", "--stepwise",
                         "--sw-skip", "--stepwise-skip")
#: pytest's short options that take a value, which may be attached to them
#: (`-rxs`, `-kfoo`): an `x` after one of these is the value, not `-x`.
_PYTEST_VALUED_SHORT = "kmprWoc"
#: How long a stored result is kept. Long enough for a merge retried the next
#: day to reuse its base run, short enough that the store never needs a verb.
SUITE_RESULT_MAX_AGE = 7 * 24 * 3600
#: The most failure ids one inbox line names before it says how many more.
_INHERITED_LISTED_MAX = 20


class SuiteRun(NamedTuple):
    """One run of the test command, as the merge gate reads it.

    *failures* is the set of failing test ids, sorted — ``()`` for a green
    run — or ``None`` when the run cannot say which tests failed, with
    *unidentified* saying why. *reused* marks a result read back from the
    store rather than run now.
    """
    returncode: int
    seconds: float
    failures: Optional[Tuple[str, ...]]
    unidentified: str = ""
    reused: bool = False


def is_pytest_command(argv: List[str]) -> bool:
    """Whether *argv* runs pytest as a module: ``<python> -m pytest …``.

    Read from the resolved command, so it holds whether the leading `python`
    was bound to the venv or named an interpreter outright — the shape
    `_test_runner_module` reads from the configured string, one token wider.
    """
    return len(argv) >= 3 and argv[1] == "-m" and argv[2] == "pytest"


def order_dependent_flag(argv: List[str]) -> Optional[str]:
    """The first argument that makes a pytest run's failure set order-bound."""
    for token in argv[3:]:
        if token.startswith("--"):
            if token.split("=", 1)[0] in _ORDER_DEPENDENT_LONG:
                return token
        elif token.startswith("-") and len(token) > 1:
            for letter in token[1:]:
                if letter == "x":
                    return token
                if letter in _PYTEST_VALUED_SHORT or not letter.isalpha():
                    break
    return None


def failure_identity_refusal(argv: List[str]) -> Optional[str]:
    """Why a red run of *argv* cannot be compared with the base, or ``None``."""
    if not is_pytest_command(argv):
        return ("the test command is not `<python> -m pytest`, and pytest's "
                "report is the only one this verb reads failures from")
    flag = order_dependent_flag(argv)
    if flag is not None:
        return (f"the test command carries {flag}, which makes which tests "
                f"fail depend on the run rather than on the tree")
    return None


def _module_path(parts: List[str], root: Optional[Path]) -> Tuple[Optional[str], List[str]]:
    """The longest prefix of dotted *parts* that is a ``.py`` file under *root*."""
    if root is not None:
        for i in range(len(parts), 0, -1):
            rel = "/".join(parts[:i]) + ".py"
            if (root / rel).is_file():
                return rel, parts[i:]
    return None, parts


def _junit_node_id(classname: str, name: str, root: Optional[Path]) -> str:
    """A pytest-style node id from a JUnit ``testcase``'s two attributes.

    pytest writes ``classname="tests.test_x.TestC"`` and ``name="test_a[1]"``
    for ``tests/test_x.py::TestC::test_a[1]``, and for a collection error an
    empty classname with the module, dotted, as the name. The module is found
    by asking which dotted prefix is a file under *root*; where none is, the
    dotted form stands. Both sides of a comparison are read by this function
    in the same checkout, so what matters is that it is deterministic.
    """
    if classname:
        path, rest = _module_path(classname.split("."), root)
        return "::".join([path, *rest, name]) if path else f"{classname}::{name}"
    path, rest = _module_path(name.split("."), root)
    return path if path and not rest else name


def junit_failure_ids(xml_text: str,
                      root: Optional[Path] = None) -> Optional[Tuple[str, ...]]:
    """The ids of every failed or errored test case in a JUnit XML report.

    ``None`` when the text is not a report — unparseable, or with no
    ``testsuite`` in it — so an unreadable file is never read as a green one.
    A collection error is a case with an ``error`` child like any other.
    """
    import xml.etree.ElementTree as ET
    try:
        tree = ET.fromstring(xml_text)
    except ET.ParseError:
        return None
    if tree.tag not in ("testsuites", "testsuite"):
        return None
    ids: Set[str] = set()
    for case in tree.iter("testcase"):
        if case.find("failure") is None and case.find("error") is None:
            continue
        ids.add(_junit_node_id(case.get("classname", "") or "",
                               case.get("name", "") or "", root))
    return tuple(sorted(ids))


def _run_suite_argv(argv: List[str], repo_root: Path) -> subprocess.CompletedProcess:
    """The one entry the engine runs the test command through: a program that
    is not there is `RunnerMissing`, never a `FileNotFoundError` traceback
    (issue #352), and an empty command is refused by each verb before this."""
    try:
        return subprocess.run(argv, cwd=str(repo_root))
    except (FileNotFoundError, PermissionError):
        # PermissionError: a path that names a file with no execute bit.
        if resolve_tool(argv[0], repo_root) is None:
            raise RunnerMissing(argv[0], repo_root) from None
        raise


def run_test_suite(repo_root: Path, argv: List[str],
                   identify: bool) -> SuiteRun:
    """Run *argv* in *repo_root* and time it; with *identify*, name the failures.

    Identification appends two pytest options to this run only:
    ``--junitxml`` into a temporary directory, and
    ``--continue-on-collection-errors``, without which one module that fails
    to import stops the session before any test runs — exit 2, and a report
    naming nothing else. The report is read, then deleted with its directory.
    """
    if not identify:
        start = time.monotonic()
        res = _run_suite_argv(argv, repo_root)
        # A green run has no failures to name whatever the runner, so it
        # reads back from the store as green (`read_suite_result`).
        if res.returncode == 0:
            return SuiteRun(0, time.monotonic() - start, ())
        return SuiteRun(res.returncode, time.monotonic() - start, None,
                        "failures were not identified")
    with tempfile.TemporaryDirectory(prefix="aide-junit-") as tmp:
        report = Path(tmp) / "report.xml"
        start = time.monotonic()
        res = _run_suite_argv([*argv, "--continue-on-collection-errors",
                               f"--junitxml={report}"], repo_root)
        seconds = time.monotonic() - start
        if res.returncode == 0:
            return SuiteRun(0, seconds, ())
        if res.returncode != _PYTEST_TESTS_FAILED:
            return SuiteRun(res.returncode, seconds, None,
                            f"pytest exited {res.returncode}, not "
                            f"{_PYTEST_TESTS_FAILED}, so its report is not "
                            f"the whole suite")
        try:
            text = report.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            return SuiteRun(res.returncode, seconds, None,
                            "pytest wrote no readable JUnit report")
        ids = junit_failure_ids(text, repo_root)
        if not ids:
            return SuiteRun(res.returncode, seconds, None,
                            "pytest's JUnit report names no failing test")
        return SuiteRun(res.returncode, seconds, ids)


def suite_results_dir(repo_root: Path) -> Optional[Path]:
    """Where suite results are kept: ``<git common dir>/aide/test-results``.

    Inside git's own directory, so nothing there is ever committed, pushed or
    reported as untracked, and shared by every worktree of the repository
    since a result is keyed by tree rather than by checkout.
    """
    try:
        res = git(["rev-parse", "--git-common-dir"], repo_root, check=False)
    except (OSError, subprocess.SubprocessError):
        return None
    common = res.stdout.strip()
    if res.returncode != 0 or not common:
        return None
    path = Path(common)
    if not path.is_absolute():
        path = repo_root / path
    return path / "aide" / "test-results"


def suite_result_key(tree: str, argv: List[str]) -> str:
    """The store's key: the tree, and a digest of the exact command run."""
    digest = hashlib.sha256("\0".join(argv).encode("utf-8")).hexdigest()[:16]
    return f"{tree}-{digest}"


def head_tree(repo_root: Path) -> Optional[str]:
    """``HEAD``'s tree id, or ``None`` where git cannot say."""
    res = git(["rev-parse", "HEAD^{tree}"], repo_root, check=False)
    return res.stdout.strip() or None if res.returncode == 0 else None


def tree_is_clean(repo_root: Path) -> bool:
    """No tracked change and no half-finished operation — a run of this
    checkout is a run of ``HEAD``'s tree. Untracked files do not count, as in
    ``_unsafe_tree_state``: a suite run leaves caches behind routinely."""
    return not _interrupted_op(repo_root) and not _dirty_paths(repo_root)


def read_suite_result(repo_root: Path, tree: str, argv: List[str],
                     now: Optional[float] = None) -> Optional[SuiteRun]:
    """A stored run of exactly *argv* over *tree*, or ``None``.

    Only a result the gate can compare is returned: exit 0 or pytest's
    tests-failed exit, with its failures named, recorded within
    ``SUITE_RESULT_MAX_AGE``. Anything else — absent, unreadable, another
    command, a record that does not say what it claims to — is a miss, and a
    miss costs a run rather than a wrong answer.
    """
    found = _read_suite_record(repo_root, tree, argv, now)
    return None if found is None else found[0]


def _read_suite_record(repo_root: Path, tree: str, argv: List[str],
                       now: Optional[float] = None
                       ) -> Optional[Tuple[SuiteRun, Dict[str, object]]]:
    """`read_suite_result`, with the record it was read from beside it."""
    folder = suite_results_dir(repo_root)
    if folder is None:
        return None
    path = folder / f"{suite_result_key(tree, argv)}.json"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
    now = time.time() if now is None else now
    try:
        if (data["tree"] != tree or data["argv"] != list(argv)
                or now - float(data["timestamp"]) > SUITE_RESULT_MAX_AGE):
            return None
        returncode = int(data["returncode"])
        failures = data["failures"]
        seconds = float(data["seconds"])
    except (KeyError, TypeError, ValueError):
        return None
    if returncode not in (0, _PYTEST_TESTS_FAILED) or not isinstance(failures, list):
        return None
    if (returncode == 0) != (not failures):
        return None
    return (SuiteRun(returncode, seconds, tuple(str(f) for f in failures),
                     reused=True), data)


def write_suite_result(repo_root: Path, tree: str, argv: List[str],
                      run: SuiteRun, now: Optional[float] = None,
                      provenance: Optional[Dict[str, str]] = None) -> Optional[Path]:
    """Record *run* of *argv* over *tree*, and prune what has aged out.

    The caller decides that the run was of *tree* — `tree_is_clean` before it
    started — since only the caller knows. *provenance* is who ran it, on
    which branch and at which commit (`recorded_suite_run`); the key never
    includes it, so a later run of the same tree and command replaces the
    record whoever made it. Best effort: a store that cannot be written costs
    the next run a re-run and nothing else, so an error here is ``None``
    rather than an exception.
    """
    folder = suite_results_dir(repo_root)
    if folder is None:
        return None
    now = time.time() if now is None else now
    record = {"tree": tree, "argv": list(argv), "returncode": run.returncode,
              "failures": None if run.failures is None else list(run.failures),
              "seconds": round(run.seconds, 3), "timestamp": now,
              **(provenance or {})}
    path = folder / f"{suite_result_key(tree, argv)}.json"
    try:
        folder.mkdir(parents=True, exist_ok=True)
        prune_suite_results(folder, now)
        partial = path.with_suffix(".json.tmp")
        partial.write_text(json.dumps(record, indent=1), encoding="utf-8")
        os.replace(str(partial), str(path))
    except OSError:
        return None
    return path


def prune_suite_results(folder: Path, now: Optional[float] = None) -> List[Path]:
    """Delete every stored result older than ``SUITE_RESULT_MAX_AGE``.

    Age is the record's own timestamp, or the file's mtime where the record
    cannot be read. Returns what was removed.
    """
    now = time.time() if now is None else now
    removed: List[Path] = []
    for path in sorted(folder.glob("*.json")):
        try:
            stamp = float(json.loads(path.read_text(encoding="utf-8"))["timestamp"])
        except (OSError, ValueError, KeyError, TypeError):
            try:
                stamp = path.stat().st_mtime
            except OSError:
                continue
        if now - stamp > SUITE_RESULT_MAX_AGE:
            try:
                path.unlink()
                removed.append(path)
            except OSError:
                pass
    return removed


#: Who recorded a stored run, in its record's ``by``: the `test` verb, whose
#: run `aide merge` may take in place of its own (`validated_suite_run`), or
#: the merge's gate itself, whose runs only ever stand in for a base run.
SUITE_RECORDED_BY_TEST = "aide test"
SUITE_RECORDED_BY_MERGE = "aide merge"


def _head_commit(repo_root: Path) -> Optional[str]:
    res = git(["rev-parse", "--verify", "--quiet", "HEAD"], repo_root, check=False)
    return res.stdout.strip() or None if res.returncode == 0 else None


def _checkout_id(repo_root: Path) -> str:
    """This working tree, as a record names it: the store is shared by every
    worktree of the repository, and their untracked inputs are not."""
    try:
        return str(Path(repo_root).resolve())
    except OSError:
        return str(repo_root)


def recorded_suite_run(repo_root: Path, argv: List[str], identify: bool,
                       by: str = SUITE_RECORDED_BY_MERGE) -> Tuple[SuiteRun, Optional[str]]:
    """Run the suite over ``HEAD``, and record the run where it is ``HEAD``'s.

    The store's one writer: a run starting from a clean tree is recorded under
    ``HEAD``'s tree, with *by*, the branch and the commit it ran at — and a
    run over any other tree is not, since its result belongs to no commit.
    Nor is one whose ``HEAD`` moved, or whose tree gained a tracked change,
    while it ran. ``(run, tree)``, *tree*
    being what it was recorded under, or ``None`` where it was not.
    """
    tree = head_tree(repo_root) if tree_is_clean(repo_root) else None
    commit = _head_commit(repo_root) if tree is not None else None
    branch = _current_branch(repo_root) if tree is not None else ""
    run = run_test_suite(repo_root, argv, identify)
    if (tree is None or commit is None or _head_commit(repo_root) != commit
            or not tree_is_clean(repo_root)):
        return run, None
    written = write_suite_result(repo_root, tree, argv, run, provenance={
        "by": by, "branch": branch, "commit": commit,
        "checkout": _checkout_id(repo_root)})
    return run, (tree if written is not None else None)


class ValidatedRun(NamedTuple):
    """What `validated_suite_run` found: the run, and the commit it ran at."""
    run: SuiteRun
    commit: str
    changed: Tuple[str, ...]


def validated_suite_run(repo_root: Path, config, argv: List[str], branch: str,
                        tip: str) -> Tuple[Optional[ValidatedRun], str]:
    """The run `aide test` recorded that stands for this checkout, or why none does.

    What `aide merge` asks before it runs the suite itself. A stored run
    stands for the post-merge tree only where all of these hold:

    * the tree has no tracked change, and ``HEAD``'s tree is the claim
      branch's at *tip* — the merge brought in nothing the branch did not
      have: a fast-forward, or a merge commit over a base that had not moved;
    * the run is of exactly *argv*, and was recorded by `aide test` in this
      checkout with the claim branch *branch* checked out, at a commit *tip*
      contains — so a run from another item, from before this branch existed,
      or from another worktree with other untracked inputs, never stands in;
    * nothing changed between that commit and *tip* but the progress document,
      which is what validation writes after its suite run (`progress set
      in-review`, `progress accept`) and what the `aide check` beside the
      merge's gate reads in full.

    The newest such run wins. ``(found, "")``, or ``(None, why)``.
    """
    if not tree_is_clean(repo_root):
        return None, "the tree has tracked changes, so no stored run is its run"
    tree = head_tree(repo_root)
    tip_tree = git(["rev-parse", "--verify", "--quiet", f"{tip}^{{tree}}"],
                   repo_root, check=False).stdout.strip()
    if tree is None or not tip_tree:
        return None, "git could not name the trees to compare"
    if tree != tip_tree:
        return None, (f"the post-merge tree is not {branch}'s at {tip[:10]} — "
                      f"the base had moved, so the merge made a tree no run "
                      f"has seen")
    folder = suite_results_dir(repo_root)
    records: List[Dict[str, object]] = []
    for path in sorted(folder.glob("*.json")) if folder and folder.is_dir() else []:
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if (isinstance(data, dict) and data.get("by") == SUITE_RECORDED_BY_TEST
                and data.get("branch") == branch and data.get("argv") == list(argv)
                and data.get("checkout") == _checkout_id(repo_root)):
            records.append(data)
    if not records:
        return None, (f"no `aide test` run of this test command is recorded "
                      f"on {branch} in this checkout")

    def _stamp(record) -> float:
        try:
            return float(record.get("timestamp", 0))
        except (TypeError, ValueError):
            return 0.0

    progress_rel = str(PurePosixPath(
        str(config["project"].get("docs_dir", "docs/aide")).replace("\\", "/"))
        / "progress.md")
    why = (f"no `aide test` run recorded on {branch} is one of {tip[:10]}'s "
           f"commits that this gate can read")
    for data in sorted(records, key=_stamp, reverse=True):
        commit = str(data.get("commit") or "")
        if not commit or not _contains(repo_root, commit, tip):
            continue
        commit_tree = git(["rev-parse", "--verify", "--quiet",
                           f"{commit}^{{tree}}"], repo_root,
                          check=False).stdout.strip()
        if not commit_tree or commit_tree != data.get("tree"):
            continue
        # Read back through the store's own reader: its age, exit and failure
        # checks apply, and a later run of that tree may have replaced it.
        found = _read_suite_record(repo_root, commit_tree, argv)
        if found is None or found[1].get("commit") != commit:
            continue
        diff = git(["diff", "--name-only", "--no-renames", commit, tip],
                   repo_root, check=False)
        if diff.returncode != 0:
            continue
        changed = tuple(sorted(root_relative(
            repo_root, [l.strip() for l in diff.stdout.splitlines() if l.strip()])))
        others = [c for c in changed if c != progress_rel]
        if others:
            why = (f"{branch} changed {others[0]}"
                   + (f" and {len(others) - 1} other path(s)" if len(others) > 1 else "")
                   + f" after the last `aide test` run recorded on it, at "
                     f"{commit[:10]}")
            break
        return ValidatedRun(found[0], commit, changed), ""
    return None, why


def _first_parent_ancestor(repo_root: Path, rev: str) -> Optional[str]:
    res = git(["rev-parse", "--verify", "--quiet", f"{rev}^1"], repo_root, check=False)
    return res.stdout.strip() or None if res.returncode == 0 else None


def _contains(repo_root: Path, ancestor: str, rev: str) -> bool:
    return git(["merge-base", "--is-ancestor", ancestor, rev], repo_root,
               check=False).returncode == 0


#: How far back along the base's first-parent line `landed_pre_merge_base`
#: walks before it gives up — a retry comes after a handful of fix commits.
_PRE_MERGE_WALK_MAX = 200


def landed_pre_merge_base(repo_root: Path, base: str, branch: str,
                          tip: str) -> Optional[str]:
    """The commit *base* stood at just before *branch* (tip *tip*) merged in.

    For a retried merge, where the merge happened in an earlier run. Two
    readings, and ``None`` unless one of them is unambiguous:

    * **A merge commit.** Walk *base*'s first-parent line back to the first
      commit whose first parent does not contain *tip*. Where that commit is a
      merge, its first parent is the base as it stood.
    * **A fast-forward.** The walk reaches *tip* itself, and the history no
      longer records where the base stood. The base's reflog does: the one
      entry git wrote as ``merge <branch>: …`` holds the value it moved from.
    """
    current = git(["rev-parse", "--verify", "--quiet", base], repo_root,
                  check=False).stdout.strip()
    if not current or not _contains(repo_root, tip, current):
        return None
    for _ in range(_PRE_MERGE_WALK_MAX):
        if current == tip:
            return _reflog_pre_merge(repo_root, base, branch, tip)
        parent = _first_parent_ancestor(repo_root, current)
        if parent is None:
            return None
        if not _contains(repo_root, tip, parent):
            parents = git(["rev-list", "--parents", "-n", "1", current],
                          repo_root, check=False).stdout.split()
            return parent if len(parents) >= 3 else None
        current = parent
    return None


def _reflog_pre_merge(repo_root: Path, base: str, branch: str,
                      tip: str) -> Optional[str]:
    res = git(["rev-parse", "--git-path", f"logs/refs/heads/{base}"],
              repo_root, check=False)
    rel = res.stdout.strip()
    if res.returncode != 0 or not rel:
        return None
    path = Path(rel) if Path(rel).is_absolute() else repo_root / rel
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return None
    olds = []
    for line in lines:
        head, _, message = line.partition("\t")
        if message.startswith(f"merge {branch}:"):
            olds.append(head.split(" ", 1)[0])
    if len(olds) != 1 or not _contains(repo_root, olds[0], tip):
        return None
    return olds[0]


def base_suite_run(repo_root: Path, argv: List[str], sha: str,
                   base: str) -> Tuple[Optional[SuiteRun], str]:
    """The suite over commit *sha*, run in place, with *base* checked out after.

    A stored result for *sha*'s tree is used where there is one. Otherwise
    HEAD is detached at *sha*, the suite runs, and *base* is switched back —
    in a `finally`, so an exception or a signal turned into one
    (`_restore_on_signal`) still leaves the branch checked out. Changes the run
    made to tracked files are discarded on the way back: the tree was clean
    before the switch, so any there are the base run's own.

    In place and not in a separate worktree: the post-merge run saw this
    checkout's untracked and ignored inputs — data, a built extension, the
    venv — and a worktree without them fails more tests at the base, which is
    exactly the error that would admit a regression as inherited.
    ``(run, "")``, or ``(None, why)``.
    """
    tree = git(["rev-parse", f"{sha}^{{tree}}"], repo_root, check=False).stdout.strip()
    if tree:
        stored = read_suite_result(repo_root, tree, argv)
        if stored is not None:
            return stored, ""
    if not tree_is_clean(repo_root):
        return None, ("the post-merge run left tracked changes in the tree, "
                      "so the base cannot be checked out beside them")
    # The switch sits inside the `try`, and the `finally` asks git where HEAD
    # is rather than trusting a flag: a signal landing between the switch and
    # the line after it would otherwise leave HEAD detached with no restore.
    try:
        switched = git(["switch", "--detach", sha], repo_root, check=False)
        if switched.returncode != 0:
            return None, (f"the base could not be checked out: "
                          f"{(switched.stderr or switched.stdout).strip()}")
        run, _ = recorded_suite_run(repo_root, argv, identify=True)
    finally:
        back = None
        if _current_branch(repo_root) != base:
            back = git(["switch", "--discard-changes", base], repo_root,
                       check=False)
    # Verified, never assumed: every commit after this — the tick, the ledger
    # row, the inbox entry — lands on whatever HEAD is, and a detached one
    # carries them onto no branch at all.
    if _current_branch(repo_root) != base:
        detail = ((back.stderr or back.stdout).strip() if back is not None
                  else "")
        raise RuntimeError(
            f"after the run at the base, {base} could not be checked out "
            f"again, so HEAD is still detached at {sha[:10]}"
            + (f" ({detail})" if detail else "")
            + f". Run 'git switch {base}' before anything else, then re-run "
              f"the merge")
    return run, ""


def _judge_red_run(repo_root: Path, argv: List[str], post: SuiteRun,
                   refusal: Optional[str], pre_merge: Optional[str],
                   landed: bool, base: str, branch: str,
                   tip: str) -> Tuple[Optional[Tuple[str, ...]], str]:
    """Read a red post-merge run against the base: ``(inherited, report)``.

    *inherited* is the failures the gate admits — every post-merge failure,
    each one also failing where *base* stood before the merge — or ``None``
    when the gate refuses: a failure the base does not have, or a run that
    cannot be compared at all. *report* says which and lists the sets; on a
    refusal it is appended to the refusal message, so it opens with a newline.
    """
    why = refusal or (post.unidentified if post.failures is None else "")
    if not why and pre_merge is None and landed:
        pre_merge = landed_pre_merge_base(repo_root, base, branch, tip)
    if not why and pre_merge is None:
        why = (f"where {base} stood before this merge cannot be identified "
               f"from its history or its reflog")
    base_run: Optional[SuiteRun] = None
    if not why:
        base_run, why = base_suite_run(repo_root, argv, pre_merge, base)
        if not why and (base_run is None or base_run.failures is None):
            why = (f"the run at the base could not name its failures: "
                   f"{base_run.unidentified if base_run else 'no result'}")
    if why or base_run is None or base_run.failures is None or post.failures is None:
        return None, (f"\naide merge: the failures were not compared with "
                      f"the base, so any failure refuses: {why}.")
    where = (f"{pre_merge[:10]}, where {base} stood before the merge"
             + (" (a stored result for that tree, not re-run)"
                if base_run.reused else ""))
    at_base = set(base_run.failures)
    new = [f for f in post.failures if f not in at_base]
    old = [f for f in post.failures if f in at_base]
    if new:
        return None, (f"\naide merge: {len(new)} failure(s) are this item's — "
                      f"they do not fail at {where}:" + _listed(new)
                      + (f"\naide merge: {len(old)} other(s) fail there too, "
                         f"and are inherited:" + _listed(old) if old else ""))
    return tuple(old), (f"aide merge: the post-merge run has {len(old)} "
                        f"failure(s), and every one also fails at {where}, "
                        f"which has {len(at_base)} — inherited, not this "
                        f"item's, so the gate admits the merge. Inherited:"
                        + _listed(old))


def _open_insight_text(text: str) -> str:
    """Every open entry of an inbox, trail included, as one string to search."""
    return "\n".join("\n".join([e.raw, *e.trail])
                     for e in parse_insights(text) if not e.ticked)


def _names_id(haystack: str, test_id: str) -> bool:
    """Whether *haystack* names *test_id* as a whole id, not inside a longer one."""
    return re.search(r"(?<![\w./:\[-])" + re.escape(test_id) + r"(?![\w.:\[-])",
                     haystack) is not None


def inherited_failures_entry(text: str, ids: List[str], number: int, base: str,
                             date: str) -> Optional[str]:
    """The one ``defect`` line naming the ids no open entry names yet, or None."""
    open_text = _open_insight_text(text)
    fresh = [i for i in ids if not _names_id(open_text, i)]
    if not fresh:
        return None
    shown = fresh[:_INHERITED_LISTED_MAX]
    listed = ", ".join(f"`{i}`" for i in shown)
    if len(fresh) > len(shown):
        listed += f" (+{len(fresh) - len(shown)} more)"
    stamp = _engine_stamp()
    marker = f"*(item {number:03d}, {date}" + (f", {stamp}" if stamp else "") + ")*"
    plural = "s" if len(fresh) != 1 else ""
    return (f"- [ ] defect — {len(fresh)} test{plural} failing on {base} "
            f"before item {number:03d} merged, admitted by `aide merge` as "
            f"inherited: {listed} {marker}")


def tick_ci_reopening_gap(repo_root: Path, config, number: int, base: str,
                          date: str) -> Tuple[Optional[str], Optional[str]]:
    """Tick the `gap` of item *number*'s CI reopening as it merges back (#332).

    ``(rel_path, message)``: the inbox's path when it was written, and what to
    print; ``(None, None)`` when there is nothing to do — the item's latest
    reopening is not a CI one, or its gap is already ticked or gone.

    Read before the tick flips the item: the latest ``reopened:`` line is the
    reopening this merge answers, and its reason, stamp included, is the text
    `reopen` wrote into the entry, so the match is exact and no other gap —
    an earlier round's, another item's, a non-CI reopening's — is touched.
    Ticked at the merge rather than on a green check: the green-check tick
    had to be pushed on its own, and that push re-ran CI over a tree changed
    in insights.md alone. A round whose check stays red reopens the item
    again, and that reopening captures a gap of its own.
    """
    ddir = docs_dir(repo_root, config)
    ppath, ipath = ddir / "progress.md", insights_path(ddir)
    if not (ppath.is_file() and ipath.is_file()):
        return None, None
    latest = [r for r in reopened_items(
        ppath.read_text(encoding=_ENCODING).splitlines()) if r.item == number]
    if not latest or not latest[0].reason.startswith(_CI_REASON_PREFIX):
        return None, None
    reason = latest[0].reason
    stamp = _CI_ROUND_RE.search(reason)
    text = ipath.read_text(encoding=_ENCODING)
    claim = f"{_REOPEN_GAP_LEAD}: {reason}"
    hits = [e for e in parse_insights(text)
            if not e.ticked and e.type == "gap" and e.item == number
            and e.text == claim]
    if not hits:
        return None, None
    pointer = (f"re-merged into {base}"
               + (f" in CI round {stamp.group(1)}" if stamp else ""))
    for e in hits:
        text, _ = tick_insight_text(text, e.ordinal, pointer, date)
    ipath.write_text(text, encoding="utf-8")
    rel = str(config["project"].get("docs_dir", "docs/aide")) + "/insights.md"
    return rel, (f"insights.md: ticked the gap of item {number:03d}'s CI "
                 f"reopening — {pointer}")


def route_inherited_failures(repo_root: Path, config, number: int, base: str,
                             ids: List[str], date: str) -> Tuple[Optional[str], str]:
    """Append the inherited-failures entry; ``(rel_path, message)``.

    No path when nothing was written — no inbox, or every id already named by
    an open entry — and the message says which.
    """
    path = insights_path(docs_dir(repo_root, config))
    if not path.is_file():
        return None, ("no insights.md, so the inherited failures were not "
                      "captured — they are listed above")
    text = path.read_text(encoding=_ENCODING)
    entry = inherited_failures_entry(text, ids, number, base, date)
    if entry is None:
        return None, ("insights.md: every inherited failure is already named "
                      "by an open entry, so none was added")
    if text and not text.endswith("\n"):
        text += "\n"
    path.write_text(text + entry + "\n", encoding="utf-8")
    rel = str(config["project"].get("docs_dir", "docs/aide")) + "/insights.md"
    return rel, "insights.md: captured a defect entry for the inherited failures"


def _listed(ids, indent: str = "  ") -> str:
    return "".join(f"\n{indent}{i}" for i in ids)


def cmd_test(args: argparse.Namespace) -> int:
    """Run the suite as `aide merge` runs it, and record the result (#275)."""
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    cmd = resolve_test_command(repo_root, config)
    if not cmd:
        print("aide test: [python] test_command is empty in aide.toml",
              file=sys.stderr)
        return 2
    refusal = failure_identity_refusal(cmd)
    repo = in_repository(repo_root)
    clean = repo and tree_is_clean(repo_root)
    sys.stdout.flush()
    run, tree = recorded_suite_run(repo_root, cmd, identify=refusal is None,
                                   by=SUITE_RECORDED_BY_TEST)
    seconds = int(round(run.seconds))
    if run.returncode == 0:
        outcome = f"green in {seconds}s"
    elif run.failures:
        outcome = (f"exit {run.returncode} in {seconds}s, "
                   f"{len(run.failures)} failing test(s) named")
    else:
        outcome = (f"exit {run.returncode} in {seconds}s, failures not named: "
                   f"{run.unidentified or refusal}")
    if tree is not None:
        commit = _head_commit(repo_root) or ""
        print(f"aide test: {outcome}. Recorded for {_current_branch(repo_root)} "
              f"at {commit[:10]}, where `aide merge` can take it in place of "
              f"its own run.")
    else:
        # The cause that was there before the run is named first: outside a
        # repository, or before the first commit, there is nothing to record
        # a run against, and "HEAD changed while it ran" would send a reader
        # looking for a change nobody made (issue #352).
        if not repo:
            why = (f"{repo_root} is not inside a git repository, so there is "
                   f"no commit to record the run against")
        elif _head_commit(repo_root) is None:
            why = ("the repository has no commit yet, so there is none to "
                   "record the run against")
        elif not clean:
            why = ("the tree has tracked changes or an operation in progress, "
                   "so the run is of no commit")
        else:
            why = ("HEAD or a tracked file changed while it ran, or the result "
                   "store could not be written")
        print(f"aide test: {outcome}. NOT recorded: {why}.", file=sys.stderr)
    code = run.returncode
    return code if code >= 0 else 128 - code


def _merge_dropped_item(repo_root: Path, config, number: int,
                        base: str) -> str:
    """Where item *number* reads ❌ dropped — ``"the working tree"``, ``"on
    <base>"`` or both, joined — or ``""`` where neither does (issue #381).

    Both are read because a drop is recorded where its owner stood: on the
    queue branch the item lands on, or on the checkout the merge runs from.
    `held_from_forward` decides, so a ❌ beside started work — a hand edit,
    which `restored` refuses — does not hold the merge. The item branch is
    deliberately not read: a drop is the owner's, made on the queue branch
    or the checkout, never from inside the item being built.
    """
    rel = _progress_rel(config)
    places: List[str] = []
    path = repo_root / rel
    if path.is_file():
        try:
            text = path.read_text(encoding=_ENCODING)
        except (OSError, UnicodeDecodeError):
            text = ""
        if held_from_forward(text.splitlines(), number) == "excluded":
            places.append("the working tree")
    shown = git(["show", f"{base}:./{rel}"], repo_root, check=False)
    if (shown.returncode == 0
            and held_from_forward(shown.stdout.splitlines(), number) == "excluded"):
        places.append(f"on {base}")
    return " and ".join(places)


def _merge_withdrawn_item(repo_root: Path, config, number: int, base: str,
                          branch: str) -> Tuple[str, List[str]]:
    """Where item *number* reads 📋 with every bullet in a withdrawn stage —
    ``("the working tree" | "on <base>" | both joined, stages)`` — or
    ``("", [])`` (issue #389).

    Read where a drop is (`_merge_dropped_item`): the working tree and the
    base, the owner's places. A 🚧 item of a withdrawn stage is NOT refused
    — §2 reads it as live work until its owner drops it, the line #388 drew
    for the stale ground, and the owner's own drop is the signal. The 🚧 is
    recorded on the item branch (`progress set NNN in-progress`, the
    builder's step), never on the base, so the claim branch is read for the
    item's status too: any copy reading it other than 📋 lets the merge on.
    An item the claim branch never started, in a stage withdrawn on the
    base, is the one `claim` would no longer offer, and is refused.
    """
    rel = _progress_rel(config)
    copies: List[Tuple[str, List[str]]] = []
    path = repo_root / rel
    if path.is_file():
        try:
            copies.append(("the working tree",
                           path.read_text(encoding=_ENCODING).splitlines()))
        except (OSError, UnicodeDecodeError):
            pass
    shown = git(["show", f"{base}:./{rel}"], repo_root, check=False)
    if shown.returncode == 0:
        copies.append((f"on {base}", shown.stdout.splitlines()))
    on_branch = git(["show", f"{branch}:./{rel}"], repo_root, check=False)
    statuses = [_parse_item_status(lines)[2].get(number, "planned")
                for _, lines in copies]
    if on_branch.returncode == 0:
        statuses.append(_parse_item_status(
            on_branch.stdout.splitlines())[2].get(number, "planned"))
    if any(st != "planned" for st in statuses):
        return "", []
    places: List[str] = []
    stages: List[str] = []
    for where, lines in copies:
        found = withdrawn_stage_items(lines).get(number)
        if found:
            places.append(where)
            stages += [st for st in found if st not in stages]
    return " and ".join(places), stages


def cmd_merge(args: argparse.Namespace) -> int:
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    mode = str(config["git"].get("mode", "auto-merge"))
    # Refused before git is touched, as `aide test` refuses it: an empty
    # command reached the post-merge run as `subprocess.run([])` and left the
    # merge made and unpushed behind an IndexError (issue #352).
    if not args.no_test and not resolve_test_command(repo_root, config):
        print("aide merge: [python] test_command is empty in aide.toml — set "
              "it, or pass --no-test", file=sys.stderr)
        return 2
    if not _require_repository("merge", repo_root):
        return 1
    # Before anything is run, merged or written (issue #377): the push is
    # the last thing an `auto-merge` merge does, after the suite and the ✅.
    if not _require_origin("merge", repo_root, mode):
        return 1
    branch = args.branch or _find_claim_branch(repo_root, prefix, args.number)
    if not branch:
        print(f"aide merge: no claim branch found for item {args.number:03d}", file=sys.stderr)
        return 1

    # Where this item lands: --base > what the claim recorded > main_branch.
    # Hard-wiring main_branch is what forced a consumer to merge every item of a
    # queue by hand — the queue file, a roadmap deliverable and nine item specs
    # lived only on the queue branch and had to land as one reviewed PR, so each
    # item needed to merge *back into* that branch.
    recorded_base = _recorded_branch_base(repo_root, branch)
    main = resolve_base(repo_root, config, args.base, branch)
    # Named on every run, whatever chose it. The fallback to main_branch is
    # right for a branch this machine never claimed, and it is exactly the
    # case a retargeted merge hides in: the one run that quietly landed a
    # queue on `main` reported nothing a transcript could catch (issue #167).
    if args.base:
        chosen = "from --base"
    elif recorded_base:
        chosen = f"recorded for {branch} at claim, or by an earlier merge run"
    else:
        # Refused, not defaulted (issue #174). `claim` records a base for every
        # branch it creates, so a claim branch with none is a branch whose
        # record was LOST — most often with the ref itself, by the `branch -d`
        # below in a run that was then killed before it could put either back.
        # `resolve_base` cannot tell that apart from "this machine never
        # claimed it"; `merge` can, because it is the verb that does the
        # deleting, and the two readings differ by a force-push: a consumer's
        # re-run took the silent `main_branch` fallback and fast-forwarded a
        # whole queue branch onto `main`, past its one-reviewed-PR-per-queue
        # gate, with nothing in the output naming `main`.
        #
        # A first merge onto `main` from a hand-made branch is the legitimate
        # shape this refuses, and `--base` is what it passes — one word, said
        # once, in exchange for the fallback never being taken by accident.
        print(f"aide merge: no base is recorded for {branch}, so this run "
              f"cannot tell where item {args.number:03d} is meant to land. "
              f"Guessing would mean the [git] main_branch default "
              f"('{main}'), and a claim branch reaches this state by losing "
              f"its record — typically to an interrupted earlier merge — so "
              f"the guess is exactly as likely to be a queue branch's work "
              f"pushed onto {main}. Re-run with the base named: "
              f"'merge {args.number:03d} --base <branch>'.", file=sys.stderr)
        return 1
    print(f"aide merge: item {args.number:03d} lands on {main} ({chosen})")
    if not _local_branch_exists(repo_root, main):
        detail = ("it resolves, but not to a local branch — `git switch` would "
                  "detach HEAD, and a merge into a detached HEAD updates no "
                  "branch while still reporting success"
                  if _ref_exists(repo_root, main) else "no such local branch")
        print(f"aide merge: base '{main}' cannot be merged into: {detail}. "
              f"Pass a local branch as --base.", file=sys.stderr)
        return 1

    dropped_in = _merge_dropped_item(repo_root, config, args.number, main)
    if dropped_in:
        # Refused before anything moves (issue #381): ❌ ranks lowest, so the
        # tick used to flip a dropped item ✅ with no reason on the record —
        # the owner's decision against the work, undone by a merge. A ⏸️
        # item is still ticked: a merge records work that landed.
        print(f"aide merge: item {args.number:03d} is ❌ dropped in "
              f"progress.md ({dropped_in}), and a dropped item is not "
              f"merged — nothing was merged, pushed or written. If the work "
              f"is wanted after all, restore it with `aide progress set "
              f"{args.number:03d} restored --reason …`, then re-run "
              f"'aide merge {args.number:03d}'.", file=sys.stderr)
        return 1
    withdrawn_in, stages = _merge_withdrawn_item(repo_root, config,
                                                 args.number, main, branch)
    if withdrawn_in:
        # The withdrawn-stage half of the refusal above (issue #389): a 📋
        # item every bullet of which sits in a stage whose summary row is ❌
        # is work `claim` no longer offers, and ticking it ✅ would undo the
        # withdrawal. A 🚧 one is NOT refused — live work until its owner
        # drops it (§2, the line #388 drew), so `_merge_withdrawn_item`
        # reads the claim branch, where the builder records the 🚧.
        print(f"aide merge: item {args.number:03d} is 📋 in withdrawn "
              f"stage{'' if len(stages) == 1 else 's'} {', '.join(stages)} "
              f"(❌ summary row, {withdrawn_in}), and a withdrawn stage's "
              f"unstarted item is not merged — nothing was merged, pushed or "
              f"written. Drop it ('aide progress set {args.number:03d} "
              f"dropped --reason …'), or take the stage's summary row off ❌ "
              f"and re-run 'aide merge {args.number:03d}'.", file=sys.stderr)
        return 1

    if mode == "pr":
        failure = _push_new_branch(repo_root, branch)
        if failure is not None:
            print(f"aide merge (pr mode): {failure}\n"
                  f"Nothing else was done — item {args.number:03d} is NOT "
                  f"ticked, and no PR can be opened over a branch origin does "
                  f"not have. The work is intact on {branch}. Resolve the "
                  f"push, then re-run 'aide merge {args.number:03d}'.",
                  file=sys.stderr)
            return 1
        print(f"aide merge (pr mode): pushed {branch}. Open a PR against {main} "
              f"to land it (e.g. 'gh pr create'); merge is left to the human "
              f"review gate. Item {args.number:03d} stays 🔍 until it merges — "
              f"then run 'aide progress set {args.number:03d} done'.")
        return 0

    unsafe = _unsafe_tree_state(repo_root, docs_dir(repo_root, config) / "progress.md")
    if unsafe:
        # Resolution before abortion, and only when there is something to
        # resolve: an agent that reads "abort" literally aborts, re-runs, and
        # meets the identical conflict — a loop, and one this verb can end.
        hint = _inbox_conflict_hint(repo_root, config)
        print(f"aide merge: refusing to merge item {args.number:03d} — {unsafe}. "
              f"`git switch` and `git pull --rebase` from here rewrite or "
              f"discard work this process did not create."
              + (f"\naide merge: {hint}" if hint else "")
              + f"\naide merge: finish that state — resolve and stage, then "
                f"`{_continue_command(repo_root)}` — or abort it "
                f"(`git rebase --abort` / `git merge --abort`, or commit the "
                f"changes), then re-run. Aborting a conflict you have not "
                f"resolved brings it back on the next attempt.",
              file=sys.stderr)
        return 1

    # The ledger's derived cells, taken while the claim branch still exists:
    # the run is about to merge it and delete it, and the row's counts are a
    # diff of that branch against the base this run resolved (§1 →
    # `ledger.md`). Derived here, written after the tick — a row records a
    # merge that happened, so nothing is written where nothing lands. A
    # failure to derive costs the row and never the merge.
    findings = getattr(args, "findings", None)
    no_review = review_is_off(config)
    if not no_review and findings is None:
        # A reviewer ran and its triage reached no flag: the row lands with
        # three blanks that read as "counts nobody passed", which is exactly
        # what happened. Said once, on stderr, because the row is still worth
        # writing and the merge is still worth landing (§1 → `ledger.md`).
        print(f"aide merge: [loop] review is on and no --findings was passed, "
              f"so item {args.number:03d}'s row records no finding counts. "
              f"The row is still written; pass "
              f"'--findings {','.join(r + '=N' for r in LEDGER_FINDING_RANKS)}' "
              f"from the role that triaged them to record what the review "
              f"cost.", file=sys.stderr)
    pending_row: Optional[List[str]] = None
    try:
        pending_row = ledger_cells(
            repo_root, config, args.number, "merged",
            rounds=getattr(args, "rounds", None),
            findings=findings,
            branch=branch, base=main, no_review=no_review)
    except (OSError, UnicodeDecodeError, subprocess.SubprocessError) as exc:
        print(f"aide merge: the ledger row could not be derived "
              f"({type(exc).__name__}: {exc}), so item {args.number:03d} "
              f"will land with no row in the ledger", file=sys.stderr)

    git(["switch", main], repo_root)

    # Already an ancestor? Then the merge is not the missing step, and doing it
    # again can only churn. This is the case that bit a consumer: a conflict
    # resolved by hand left a merge commit on the base that had not been
    # pushed, and the re-run's `pull --rebase` linearised it — dropping the
    # merge, replaying both parents, and reintroducing the very conflict the
    # human had just resolved (issue #133). Asking git first costs one call and
    # is what makes the verb re-runnable, which a loop needs it to be.
    landed = git(["merge-base", "--is-ancestor", branch, main],
                 repo_root, check=False).returncode == 0
    # Where the base stood before this merge — what a red post-merge run is
    # compared with (§4). Read now for a merge this run makes; for one an
    # earlier run made, only if the run turns out red (`landed_pre_merge_base`).
    pre_merge: Optional[str] = None
    if landed:
        print(f"aide merge: {branch} is already merged into {main} — skipping "
              f"the merge; the tick, the push and the cleanup still run.")
    else:
        if mode != "local":
            # `--rebase` is right for a linear local divergence and WRONG over
            # an unpushed merge commit (above). `--ff-only` integrates origin
            # where it can and refuses instead of rewriting where it cannot.
            if _has_unpushed_merge(repo_root):
                ff = git(["pull", "--ff-only"], repo_root, check=False)
                if ff.returncode != 0:
                    print(f"aide merge: {main} carries a merge commit origin "
                          f"has not seen, and origin has moved on. Rebasing "
                          f"over it would linearise the merge and bring back "
                          f"the conflicts it resolved, so this verb stops "
                          f"rather than choosing for you: push that merge "
                          f"('git push'), or integrate origin by hand, then "
                          f"re-run.\n{ff.stdout}{ff.stderr}", file=sys.stderr)
                    return 1
            else:
                pulled = git(["pull", "--rebase"], repo_root, check=False)
                stalled = _stalled_pull(repo_root, config, pulled)
                if stalled is not None:
                    # The sharpest of the three: `git merge` refuses outright
                    # while a rebase is in progress, so without this the
                    # operator reads the MERGE's failure for a stall the pull
                    # caused, on a base branch that is now mid-rebase.
                    print(f"aide merge: {stalled}\n"
                          f"aide merge: nothing was merged and item "
                          f"{args.number:03d} is NOT ticked — the work is "
                          f"intact on {branch}. Re-run once {main} is settled.",
                          file=sys.stderr)
                    return 1
        pre_merge = git(["rev-parse", "HEAD"], repo_root,
                        check=False).stdout.strip() or None
        merge_res = git(["merge", "--no-edit", branch], repo_root, check=False)
        if merge_res.returncode != 0:
            # The one conflict this loop produces as a matter of course gets
            # named here rather than left in git's output, because this is
            # where it lands and the role standing here has read nothing about
            # the inbox.
            hint = _inbox_conflict_hint(repo_root, config)
            print(f"aide merge: merge of {branch} failed:\n"
                  f"{merge_res.stdout}{merge_res.stderr}"
                  + (f"\naide merge: {hint}\n" if hint else ""),
                  file=sys.stderr)
            return 1

    # The claim branch goes BEFORE the test run, so the run sees the refs a
    # fresh clone would (issue #125). With it still present, a consumer whose
    # test command includes `aide check` got "stale claim branch … item NNN is
    # already ✅" — a failure class the item's acceptance baseline had never
    # seen, produced by nothing but this ordering. Its tip is remembered so any
    # later exit can put the branch back exactly as it was — with the base
    # this run merged into as its record, since `branch -d` discards the old
    # one with the ref and a retry must land where this run did (issue #167).
    branch_tip = git(["rev-parse", branch], repo_root, check=False).stdout.strip()
    branch_base = main

    # Every exit from here to the push must put the branch back, not just the
    # two this function writes out longhand: the window covers a whole test
    # suite, and a run killed inside it (Ctrl-C, a CI timeout, an unattended
    # runner's wall clock) left the item merged into its base with the claim
    # branch gone and nothing to say where it had been. The next run's
    # `resolve_base` then fell back to `main_branch` and a consumer's queue was
    # fast-forwarded onto `main` and pushed, past its one-reviewed-PR-per-queue
    # gate (issue #174). The `except` arm is what covers the killed run; the
    # two explicit calls inside stay, because each carries a message about the
    # specific failure it is reporting.
    #
    # It ends at the push on purpose. Past that the merge has left this
    # repository and the retry has nothing left to do, so putting the branch
    # back would leave a stale claim branch behind a ✅ item — the very state
    # deleting it before the tests avoids.
    #
    # It begins BEFORE the deletion, with the tip already read: a signal
    # landing between `branch -d` and a handler installed after it ended the
    # process with the claim branch gone and nothing to put it back (#275).
    with _restore_on_signal():
        try:
            # `-d` can refuse even though the work landed (e.g. `pull
            # --rebase` rewrote main so the branch tip is no longer an
            # ancestor); this process just established that the branch is
            # merged, so escalating to -D is safe. VERIFY the outcome, never
            # assume it.
            del_res = git(["branch", "-d", branch], repo_root, check=False)
            if del_res.returncode != 0:
                del_res = git(["branch", "-D", branch], repo_root, check=False)
            local_gone = branch not in _local_branches(repo_root)

            suite_cell = ""
            inherited: Optional[Tuple[str, ...]] = None
            if not args.no_test:
                cmd = resolve_test_command(repo_root, config)
                refusal = failure_identity_refusal(cmd)
                # The run validation recorded, where it is a run of this very
                # tree (issue #275): taken in place of a second suite run, and
                # judged exactly as one — a red one still meets the base.
                validated, why_not = validated_suite_run(
                    repo_root, config, cmd, branch, branch_tip)
                if validated is not None:
                    post = validated.run
                    since = list(validated.changed)
                    print(f"aide merge: the post-merge tree is the one `aide "
                          f"test` ran over on {branch} at "
                          f"{validated.commit[:10]}"
                          + (f", but for {', '.join(since)}" if since else "")
                          + f" — reusing that run (exit {post.returncode}, "
                            f"{int(round(post.seconds))}s) rather than running "
                            f"the suite again.")
                else:
                    print(f"aide merge: running the suite: {why_not}.")
                    sys.stdout.flush()
                    post, _ = recorded_suite_run(repo_root, cmd,
                                                 identify=refusal is None)
                suite_cell = str(int(round(post.seconds))) + (
                    LEDGER_REUSED_SUFFIX if validated is not None else "")
                if post.returncode == 0:
                    inherited = () if refusal is None else None
                else:
                    inherited, report = _judge_red_run(
                        repo_root, cmd, post, refusal, pre_merge, landed,
                        main, branch, branch_tip)
                    if inherited is None:
                        _restore_claim_branch(repo_root, branch, branch_tip, branch_base)
                        print(f"aide merge: the post-merge test run FAILED, so item "
                              f"{args.number:03d} is NOT ✅ and nothing was pushed — the "
                              f"tick and the push are what this run refuses, not the merge "
                              f"itself. {branch} is merged into {main} in THIS repository "
                              f"only, and the claim branch is back with its base. Fix the "
                              f"failures on {main}, commit, then re-run "
                              f"'merge {args.number:03d} --base {main}': the merge is "
                              f"already an ancestor, so the retry only re-tests, ticks and "
                              f"pushes.{report}", file=sys.stderr)
                        return 1
                    print(report)

            # The document gate, beside the test run and refusing the same two
            # things: the tick and the push, so the item stays 🔍. Nothing else
            # in the loop ran `aide check` mechanically — a consumer's ✅ stage
            # over ⏸️ deliverables sat on its base for two weeks until an
            # engine update surfaced it, and one without its own test pinning
            # `run_checks` would never have seen it (issue #232). In-process,
            # and not skipped by --no-test: it is not the project's tests.
            doc_errors, doc_warnings = run_checks(repo_root, config)
            if doc_errors:
                _restore_claim_branch(repo_root, branch, branch_tip, branch_base)
                listed = "".join(f"\nerror: {e}" for e in doc_errors)
                print(f"aide merge: `aide check` reports {len(doc_errors)} "
                      f"error(s) after the merge, so item {args.number:03d} "
                      f"is NOT ✅ and nothing was pushed. {branch} is merged "
                      f"into {main} in THIS repository only, and the claim "
                      f"branch is back with its base. The check reads the "
                      f"whole document set, so an error may predate this "
                      f"item. Fix the documents on {main}, commit, then re-run "
                      f"'merge {args.number:03d} --base {main}'.{listed}",
                      file=sys.stderr)
                return 1
            if doc_warnings:
                print(f"aide merge: `aide check` reports {len(doc_warnings)} "
                      f"warning(s), which do not block a merge; "
                      f"'{aide_command(repo_root, 'check')}' lists them.")

            # ✅ is set HERE, by the process that just did the merge, so it always means
            # "merged" — not "an agent said so before attempting one". The validator
            # marks the item 🔍 before this call; whether it becomes ✅ is a fact about
            # git, and in `pr` mode the return above leaves it 🔍 for the human's merge.
            #
            # It must precede the push: the tick is a commit like any other, and the
            # single `git push` below is the only one that carries `main` to origin.
            # Recording it afterwards stranded it locally, so origin's progress.md
            # under-reported — and on a queue's last item nothing would ever push it.
            # Beside the tick and in the same commit as it: one item, one
            # row, whatever it took to get there (§1 → `ledger.md`). A ledger
            # write that fails is a warning after the merge and never an exit
            # code — capture is worth a sentence, never a landed item. The
            # COMMIT of what was written is another matter (below).
            #
            # Every file the tick's commit may carry, as it is before any of
            # them is written: a commit that does not happen puts each back,
            # so the re-run appends the row and the entry once (issue #312).
            ddir = docs_dir(repo_root, config)
            before = _snapshot([ddir / "progress.md", ledger_path(ddir),
                                insights_path(ddir)])
            ledger_rel = None
            recorded = (None if pending_row is None else
                        _merged_row_already_recorded(repo_root, config,
                                                     args.number, pending_row))
            if recorded is not None:
                # A re-run after a push that failed (issue #346): the earlier
                # run's tick commit landed here, row and all, and only the
                # push did not. That row is the one measured while the claim
                # branch still had its diff and the run was validation's; this
                # run's would read 0 tests, 0 files and a fresh suite time.
                print(f"aide merge: ledger row for item {args.number:03d} "
                      f"already recorded ({recorded}) — not appended")
            elif pending_row is not None:
                pending_row[LEDGER_COLUMNS.index("Suite s")] = suite_cell
                pending_row[LEDGER_COLUMNS.index("Inherited")] = (
                    "" if inherited is None else str(len(inherited)))
                try:
                    ledger_rel = append_ledger_row(repo_root, config,
                                                   pending_row, "merge")
                except (OSError, UnicodeDecodeError) as exc:
                    print(f"aide merge: item {args.number:03d} merged, but its "
                          f"ledger row could not be written "
                          f"({type(exc).__name__}: {exc})", file=sys.stderr)
            extra_rels = [ledger_rel] if ledger_rel else []
            if inherited:
                # One engine-written `defect` for the failures it just
                # admitted, in the tick's commit so it is pushed with it (§4).
                # Like the row: a sentence on failure, never an exit code.
                import datetime as _dt
                try:
                    inbox_rel, note = route_inherited_failures(
                        repo_root, config, args.number, main, list(inherited),
                        _dt.date.today().isoformat())
                except (OSError, UnicodeDecodeError) as exc:
                    inbox_rel, note = None, (
                        f"the inherited failures could not be captured in "
                        f"insights.md ({type(exc).__name__}: {exc})")
                # Both outcomes that wrote or needed nothing open with the
                # file's name; anything else is a capture that did not happen.
                print(f"aide merge: {note}",
                      file=sys.stdout if note.startswith("insights.md:")
                      else sys.stderr)
                if inbox_rel and inbox_rel not in extra_rels:
                    extra_rels.append(inbox_rel)
            # The gap this item's CI reopening captured closes as it merges
            # back, in the tick's commit (issue #332). Like the row: a
            # sentence on failure, never an exit code.
            import datetime as _dt
            try:
                gap_rel, note = tick_ci_reopening_gap(
                    repo_root, config, args.number, main,
                    _dt.date.today().isoformat())
            except (OSError, UnicodeDecodeError, ValueError) as exc:
                gap_rel, note = None, (
                    f"aide merge: the gap of item {args.number:03d}'s CI "
                    f"reopening could not be ticked ({type(exc).__name__}: "
                    f"{exc})")
            if note:
                print(note, file=sys.stdout if gap_rel else sys.stderr)
            if gap_rel and gap_rel not in extra_rels:
                extra_rels.append(gap_rel)
            failed = _promote_item_to_complete(
                repo_root, config, args.number, before,
                getattr(args, "no_commit", False), tuple(extra_rels))
            if failed is not None:
                # The tick's commit did not land, so the push must not run:
                # it is the one that carries `main` to origin, and it would
                # carry the merge without the ✅, the row or the entry, then
                # delete the claim branch a re-run needs (issue #312). This
                # used to be best effort on the ground that the merge had
                # landed — in THIS repository only, which is the same state
                # a red run or a document error leaves, and is refused the
                # same way: the branch back with its base, nothing pushed,
                # exit 1. `local` mode pushes nothing but stops here too, so
                # the claim branch is there for the retry.
                reason, committed = failed
                _restore_claim_branch(repo_root, branch, branch_tip, branch_base)
                if committed:
                    # HEAD moved: the ✅ is in a commit here and is kept, and
                    # what it lacks — its replay onto origin stopped, or a path
                    # it should carry is not in it — `_commit_docs_files` has
                    # already printed in full.
                    print(f"aide merge: item {args.number:03d} is ✅ in a "
                          f"commit on {main}, but {reason}\n"
                          f"aide merge: nothing was pushed — {branch} is "
                          f"merged into {main} in THIS "
                          f"repository only, and the claim branch is back "
                          f"with its base. Fix what the message above names "
                          f"— settle a stopped replay on {main}, or un-ignore "
                          f"a path the commit left out — then re-run "
                          f"'merge {args.number:03d} --base {main}'.",
                          file=sys.stderr)
                else:
                    print(f"aide merge: item {args.number:03d} is NOT ✅ and "
                          f"nothing was pushed — the commit recording it "
                          f"could not be made: {reason}\n"
                          f"aide merge: {branch} is merged into {main} in "
                          f"THIS repository only, the claim branch is back "
                          f"with its base, and the files the tick wrote are "
                          f"as they were. Fix that cause, then re-run "
                          f"'merge {args.number:03d} --base {main}': the "
                          f"merge is already an ancestor, so the retry only "
                          f"re-tests, ticks and pushes.", file=sys.stderr)
                return 1

            remote_gone = True
            if mode != "local":
                push_res = git(["push"], repo_root, check=False)
                if push_res.returncode != 0:
                    # Reported, not swallowed: a silent failure here leaves ✅ on a
                    # merge origin never received, which is the same class of lie as
                    # ticking an item whose tests fail. The remote claim branch is
                    # deliberately NOT deleted, so the work still exists somewhere
                    # other than this checkout.
                    _restore_claim_branch(repo_root, branch, branch_tip, branch_base)
                    print(f"aide merge: item {args.number:03d} is merged and ✅ here, "
                          f"but pushing {main} to origin FAILED, so neither the merge "
                          f"nor the tick has left this repository and the claim branch "
                          f"is kept, with its base. Resolve the push, then re-run "
                          f"'merge {args.number:03d} --base {main}'.\n"
                          f"{push_res.stdout}{push_res.stderr}", file=sys.stderr)
                    return 1
                del_remote = git(["push", "origin", "--delete", branch], repo_root, check=False)
                remote_gone = (del_remote.returncode == 0
                               or "remote ref does not exist" in (del_remote.stderr or ""))
        except BaseException as exc:
            # BaseException, so `KeyboardInterrupt` and `_Terminated` are caught
            # alongside an ordinary bug. Nothing is swallowed: the restore is a
            # side effect on the way out and the original exception continues to
            # unwind, so an interrupted run still exits as interrupted.
            #
            # The restore is owed either way; the WORDING is not. A run that
            # reported itself "interrupted" would send a human hunting for a
            # signal nobody sent — the same failure the `--no-commit` message
            # was fixed for in issue #133. So the cause is named. A program
            # that is not there (`MissingTool`: the test command, or git gone
            # mid-run) is a state a person fixes, not a bug, so it is
            # reported and the verb exits 1 (issue #352); an interrupt or a
            # genuine bug still re-raises, and its traceback says the rest.
            missing = isinstance(exc, MissingTool)
            unrestored: Optional[str] = None
            try:
                _restore_claim_branch(repo_root, branch, branch_tip, branch_base)
            except MissingTool as restore_exc:
                # git itself went with the test run: the message must not
                # claim a restore that never ran, and names the two commands
                # that do it by hand.
                unrestored = str(restore_exc)
            cause = (f"{exc}; that stopped the run" if missing
                     else "interrupted"
                     if isinstance(exc, (KeyboardInterrupt, _Terminated))
                     else f"failed with {type(exc).__name__}")
            if unrestored is None:
                kept = (f"so {branch} has been put back with {main} recorded "
                        f"as its base")
            else:
                by_hand = f"'git branch {branch} {branch_tip}'"
                if branch_base:
                    by_hand += (f" and 'git config branch.{branch}."
                                f"{_BASE_CONFIG_KEY} {branch_base}'")
                kept = (f"and {branch} could NOT be put back ({unrestored}). "
                        f"Restore it by hand: {by_hand}")
            print(f"aide merge: {cause} after {main} took the merge of "
                  f"{branch} but before it was pushed, {kept}. The merge is "
                  f"in THIS repository only. Re-run "
                  f"'merge {args.number:03d} --base {main}'.", file=sys.stderr)
            if missing:
                return 1
            raise

    if local_gone and remote_gone:
        print(f"aide merge: item {args.number:03d} merged to {main} and claim branch {branch} deleted")
    else:
        where = [] if local_gone else ["local"]
        if not remote_gone:
            where.append("remote")
        print(f"aide merge: item {args.number:03d} merged to {main}, but the "
              f"{'/'.join(where)} claim branch {branch} could NOT be deleted:\n"
              f"{(del_res.stderr or '').strip()}\n"
              f"Run '{aide_command(repo_root, 'gc')}' to sweep it up.",
              file=sys.stderr)
    return 0


# --------------------------------------------------------------------------- #
# sync / gc — the scripted git workflow (no exploratory git needed)
# --------------------------------------------------------------------------- #
def _local_branches(repo_root: Path) -> List[str]:
    out = git(["branch", "--format=%(refname:short)"], repo_root, check=False).stdout
    return [l.strip() for l in out.splitlines() if l.strip()]


def _remote_branches(repo_root: Path) -> List[str]:
    out = git(["branch", "-r", "--format=%(refname:short)"], repo_root, check=False).stdout
    names = []
    for l in out.splitlines():
        name = l.strip()
        if name.startswith("origin/") and "HEAD" not in name:
            names.append(name.split("/", 1)[1])
    return names


#: Why a prefixed branch this checkout has is missing from origin (issue #364).
#: ``unpublished``: origin never had it — no upstream on origin under its own
#: name, so no push of it ever landed. ``gone-landed``: it was published and has
#: since been deleted on origin, and everything on it is already in a base.
#: ``gone-unfound``: published, deleted on origin, and its work could not be
#: found in any base — which is a measurement, not a verdict: a squash merge
#: the base has since built over, or any squash merge under git < 2.38, reads
#: this way too, so the reports say what was measured and never "unlanded".
OFF_ORIGIN_UNPUBLISHED = "unpublished"
OFF_ORIGIN_GONE_LANDED = "gone-landed"
OFF_ORIGIN_GONE_UNFOUND = "gone-unfound"


class OffOrigin(NamedTuple):
    """One prefixed branch this checkout has and origin's tracking refs lack."""
    kind: str
    #: gone-landed: the ref its work is already in. gone-unfound: every ref
    #: that was asked, joined for a sentence. unpublished: None.
    where: Optional[str] = None


def _branches_off_origin(repo_root: Path, config,
                         prefix: str) -> Dict[str, OffOrigin]:
    """Branches under *prefix* that this checkout has and origin has not, and why.

    Read against the remote-tracking refs, so it reports what the last fetch
    saw — `claim` fetches first and `status` does too unless asked not to.

    "Origin lacks it now" is not "origin never had it" (issue #364): a queue
    branch whose PR merged is routinely deleted on origin — hosting may do it
    on merge — and advising `git push -u` for it recreates a branch deleted on
    purpose. Every engine push is `push -u` (`_push_new_branch`), so an upstream
    of ``refs/remotes/origin/<the same name>`` whose ref is gone is git's own
    record that a push landed and the branch was removed since. Ancestry alone
    cannot be the test: a claim whose push just failed sits at its base's tip,
    already "in" main, and is exactly the half-claim of issue #137.

    A published-then-deleted branch is ``gone-landed`` when its tip is an
    ancestor of — or, where git can measure it, its content already in — its
    recorded base, ``main_branch`` or ``origin/<main_branch>``; otherwise
    ``gone-unfound``. Those probes run only for gone branches, which are rare,
    and the listing itself is one ``for-each-ref`` spawn (issue #74).

    ``gone-unfound`` is what was measured, not that the work never landed. A
    squash merge that the base has since changed again over the same lines
    makes ``merge-tree`` conflict, and git < 2.38 cannot ask at all, so landed
    work reads this way too. No cheap probe closes that: patch-id matching
    breaks on a squash whose context moved or whose conflicts were resolved on
    the host. So the reports name both readings and send a person to the PR.

    No origin at all is deliberately *not* an exemption. Off ``local`` mode
    the engine pushes every branch it creates, so a repository with no remote
    fails every push; issue #137's own reproduction is exactly that, and a
    claim branch there is unpublished in the strongest sense — there is
    nowhere for it to have gone. ``local`` mode is the one configuration where
    an unpushed claim branch is the design rather than a failure.
    """
    if str(config["git"].get("mode", "auto-merge")) == "local":
        return {}
    # Tab-separated: a refname cannot contain a control character, so the
    # split is exact on every platform, and no shell is involved.
    listing = git(["for-each-ref", "--format=%(refname)%09%(upstream)",
                   "refs/heads/", "refs/remotes/origin/"],
                  repo_root, check=False).stdout
    local: Dict[str, str] = {}
    remote: Set[str] = set()
    for line in listing.splitlines():
        ref, _, upstream = line.partition("\t")
        ref = ref.strip()
        if ref.startswith("refs/remotes/origin/"):
            remote.add(ref[len("refs/remotes/origin/"):])
        elif ref.startswith("refs/heads/"):
            local[ref[len("refs/heads/"):]] = upstream.strip()
    out: Dict[str, OffOrigin] = {}
    main = str(config["git"].get("main_branch", "main"))
    can_measure: Optional[bool] = None
    for br in sorted(local):
        if not br.startswith(prefix) or br in remote:
            continue
        if local[br] != f"refs/remotes/origin/{br}":
            out[br] = OffOrigin(OFF_ORIGIN_UNPUBLISHED)
            continue
        targets: List[str] = []
        for ref in (_recorded_branch_base(repo_root, br), main, f"origin/{main}"):
            if ref and ref != br and ref not in targets:
                targets.append(ref)
        # Exit 0 is "ancestor"; 1 is "not", and 128 an unreadable ref — both
        # simply move on to the next base.
        landed = next((t for t in targets
                       if git(["merge-base", "--is-ancestor", br, t],
                              repo_root, check=False).returncode == 0), None)
        if landed is None:
            # A squash merge leaves the tip off every base: ask for content.
            if can_measure is None:
                can_measure = _has_merge_tree(repo_root)
            if can_measure:
                landed = next((t for t in targets
                               if _branch_content_landed(repo_root, t, br) is True),
                              None)
        out[br] = (OffOrigin(OFF_ORIGIN_GONE_LANDED, landed) if landed
                   else OffOrigin(OFF_ORIGIN_GONE_UNFOUND, " or ".join(targets)))
    return out


def _gc_merged_hint(landed_in: str, config) -> str:
    """The `gc` invocation that collects a branch whose work is in *landed_in*."""
    main = str(config["git"].get("main_branch", "main"))
    return ("aide gc --merged" if landed_in == main
            else f"aide gc --merged --base {landed_in}")


def _off_origin_claim_branches(repo_root: Path, config,
                               prefix: str) -> Dict[int, Tuple[str, OffOrigin]]:
    """Item number -> (claim branch, why origin lacks it), for claim branches
    this checkout has and origin has not.

    Off ``local`` mode a claim is published by construction: `claim` creates
    the branch and pushes it in the same breath, and refuses out loud when the
    push does not land. So a claim branch origin has never seen is a claim
    that did not finish — visible here, invisible to every other checkout, and
    counted as a claim by `_pick_item` regardless. That is the half-claim of
    issue #137, and naming it is what stops it reading as work in flight.

    A claim branch origin *had* and has deleted is not in flight either, but it
    is not a failed push: its work landed, the claim was abandoned (§2: delete
    the remote branch), or its work cannot be found in a base — removed before
    it landed, or landed in a shape that cannot be measured. The kind says
    which, so `claim` never advises re-publishing it (issue #364).

    ``local`` mode is the one configuration that reports nothing: there, an
    unpushed claim branch is the design. A repository with no origin at all is
    *not* an exemption — see `_branches_off_origin`, which this narrows.
    """
    out: Dict[int, Tuple[str, OffOrigin]] = {}
    for br, why in _branches_off_origin(repo_root, config, prefix).items():
        num = _branch_item_number(br, prefix)
        if num is not None:
            out.setdefault(num, (br, why))
    return out


def _branch_item_number(branch: str, prefix: str) -> Optional[int]:
    """Item number claimed by *branch*, or None when it is not a claim branch.

    A claim branch is ``<branch_prefix>NNN-short-name`` (conventions.md §4), so
    the number must sit *immediately* after the prefix. Anchoring is what makes
    this correct: queue numbers and item numbers share one namespace with no
    syntactic marker between them, so an unanchored digit search reads
    ``aide/queue-016`` as item 016 — an unrelated, usually long-finished work
    item — and ``aide/specs-queue-015`` likewise.

    That misread is not cosmetic. ``gc`` targets any branch whose item is ✅ and
    deletes it with ``git branch -D`` plus a remote delete, independently of
    ``--merged``; under the old unanchored match that destroyed an in-flight
    queue branch, and the unreviewed queue file and item specs living only on it.
    """
    m = re.match(re.escape(prefix) + r"0*(\d+)(?:-|$)", branch)
    return int(m.group(1)) if m else None


#: Branches the framework itself tells authors to create that are deliberately
#: NOT item claims: `/aide-create-queue`'s hand-off and `/aide-run-roadmap` name
#: `<prefix>queue-NNN`, `/aide-spec-queue` names `<prefix>specs-queue-NNN`.
#: Recognised positively so they are reported as what they are, rather than
#: lumped in with a branch nothing can parse.
#:
#: Built from `_QUEUE_TOKEN`/`_SPECS_TOKEN` — the same literals the constructors
#: below and `queue_name` use — so the recogniser cannot drift from the names
#: actually produced. 1.13.0 centralised branch *parsing*; until 1.20.0 two of
#: the three shapes had no constructor at all and were typed by an agent copying
#: a string out of a markdown file, which is why the round-trip test that now
#: pins this could not previously be written.
_QUEUE_BRANCH_RE = re.compile(
    "(?:" + re.escape(_SPECS_TOKEN) + ")?" + re.escape(_QUEUE_TOKEN) + r"\d+$")


def claim_branch_name(prefix: str, number: int, title: str) -> str:
    """``<prefix>NNN-short-name`` — the branch `aide claim` creates for an item."""
    return f"{prefix}{number:03d}-{_slug(title)}"


def queue_branch_name(prefix: str, number: int) -> str:
    """``<prefix>queue-NNN`` — the branch a queue is planned and run on."""
    return f"{prefix}{queue_name(number)}"


def specs_queue_branch_name(prefix: str, number: int) -> str:
    """``<prefix>specs-queue-NNN`` — the branch a queue's specs are authored on."""
    return f"{prefix}{_SPECS_TOKEN}{queue_name(number)}"


def _is_queue_branch(branch: str, prefix: str) -> bool:
    """True when *branch* is a queue/specs-queue branch rather than a claim."""
    return (branch.startswith(prefix)
            and _QUEUE_BRANCH_RE.match(branch[len(prefix):]) is not None)


def _has_origin(repo_root: Path) -> bool:
    out = git(["remote"], repo_root, check=False).stdout
    return "origin" in out.split()


def missing_origin(mode: str) -> str:
    """The one sentence a mode that pushes is refused with where there is no
    remote named origin: `aide env`'s origin line, plain `aide check`'s
    `this machine:` error and `_require_origin` all say it (issues #354,
    #377)."""
    return (f'[git] mode = "{mode}" in aide.toml needs a remote named origin '
            f"— add one ('git remote add origin <url>'), or set [git] mode = "
            f'"local"')


def _require_origin(verb: str, repo_root: Path, mode: str) -> bool:
    """Print `missing_origin` and return False when *mode* pushes and this
    checkout has no remote named origin; True otherwise.

    Asked before the verb changes anything (issue #377). `claim`, `queue
    start`, `queue restack` and `merge` each push last, so a missing origin
    used to be found after their local half was done: `merge` under
    `auto-merge` ran the suite, merged, ticked ✅ and committed, then failed
    at the push — and every re-run paid the suite again to fail at the same
    place. §4: a requirement the machine cannot meet is refused up front.
    """
    if mode == "local" or _has_origin(repo_root):
        return True
    print(f"aide {verb}: {missing_origin(mode)}", file=sys.stderr)
    return False


# --------------------------------------------------------------------------- #
# Base refs — what a claim branched from, and what its merge returns to
# --------------------------------------------------------------------------- #
#: Where a claim branch remembers its base. A git-config key under the branch's
#: own section, so it travels with the branch through switch/rebase and needs no
#: file in the repo. It is deliberately *local* config: the base is a fact about
#: this checkout's branching, not something to commit and share. A machine that
#: never ran the `claim` falls back to `main_branch`, and `--base` is always
#: available — nothing silently merges somewhere unexpected.
_BASE_CONFIG_KEY = "aide-base"


def _record_branch_base(repo_root: Path, branch: str, base: str) -> None:
    git(["config", f"branch.{branch}.{_BASE_CONFIG_KEY}", base],
        repo_root, check=False)


#: Beside the base, and local for the same reason: the commit a queue branch
#: was started from, recorded by `queue start` (issue #301).
_START_CONFIG_KEY = "aide-start"


def _record_branch_start(repo_root: Path, branch: str, sha: str) -> None:
    if sha:
        git(["config", f"branch.{branch}.{_START_CONFIG_KEY}", sha],
            repo_root, check=False)


def _recorded_branch_start(repo_root: Path, branch: str) -> Optional[str]:
    res = git(["config", "--get", f"branch.{branch}.{_START_CONFIG_KEY}"],
              repo_root, check=False)
    return res.stdout.strip() or None


def _recorded_branch_base(repo_root: Path, branch: str) -> Optional[str]:
    if not branch:
        return None
    res = git(["config", "--get", f"branch.{branch}.{_BASE_CONFIG_KEY}"],
              repo_root, check=False)
    value = res.stdout.strip()
    return value or None


def _current_branch(repo_root: Path) -> str:
    return git(["rev-parse", "--abbrev-ref", "HEAD"],
               repo_root, check=False).stdout.strip()


def _ref_exists(repo_root: Path, ref: str) -> bool:
    return git(["rev-parse", "--verify", "--quiet", ref],
               repo_root, check=False).returncode == 0


def _local_branch_exists(repo_root: Path, ref: str) -> bool:
    """True only for an existing **local branch**, not any resolvable ref.

    A base must be a local branch, and merely resolving is not enough: `git
    switch` on a tag, a raw commit or a remote-tracking ref like `origin/main`
    detaches HEAD. A merge into a detached HEAD updates no branch at all, yet
    still reports success and lets the claim branch be deleted — the work
    survives only as an unreferenced commit. So the check is on the ref's
    *kind*, not its existence.
    """
    return git(["show-ref", "--verify", "--quiet", f"refs/heads/{ref}"],
               repo_root, check=False).returncode == 0


def _remote_or_local(repo_root: Path, ref: str) -> str:
    """``origin/<ref>`` when it resolves, else *ref* unchanged.

    Used where the question is "what has this branch actually diverged from" —
    the remote-tracking ref is what CI compares against and what the branch will
    merge into, and a local ref sitting behind the work answers that wrongly.
    """
    if _has_origin(repo_root):
        remote = f"origin/{ref}"
        if _ref_exists(repo_root, remote):
            return remote
    return ref


def resolve_base(repo_root: Path, config: Dict[str, Dict[str, object]],
                 explicit: Optional[str] = None,
                 branch: Optional[str] = None) -> str:
    """The base ref for a branch: explicit ``--base`` > recorded > config.

    ``main_branch`` stays the default and is never removed as one — this only
    adds the two ways a branch can legitimately have a *different* base, which
    is what stacked work produces: a queue branch's items branch off it and must
    merge back into it, so the whole queue lands as one reviewed PR.
    """
    if explicit:
        return explicit
    if branch is None:
        branch = _current_branch(repo_root)
    recorded = _recorded_branch_base(repo_root, branch)
    if recorded:
        return recorded
    return str(config["git"].get("main_branch", "main"))


# --------------------------------------------------------------------------- #
# Scope check — a branch's diff against its item's `## Authorised paths`
# --------------------------------------------------------------------------- #
_AUTHORISED_HEADING = "## Authorised paths"
#: The two sub-lists of that section (conventions.md §1), matched case- and
#: punctuation-insensitively so `**May change:**`, `**May change**` and
#: `May change:` all read the same.
_MAY_CHANGE_LABEL = "may change"
_ASSERTS_LABEL = "asserts against"

#: Loop bookkeeping the `aide` CLI and the agent roles are mandated to write on
#: *any* item, whatever that item is about — so a change to one is never
#: evidence of scope creep, and listing them would force every spec to repeat
#: the same boilerplate bullets just to pass. Kept explicit and wildcard-free so
#: the set cannot silently grow into a scope hole:
#:
#: - ``progress.md`` — rewritten by ``aide progress set`` on every item.
#: - ``insights.md`` — the compound-engineering inbox; conventions.md §1 names
#:   appending to it as the one write allowed outside an agent's edit scope, so
#:   flagging it would punish exactly the behaviour the framework requires.
#: - ``insights/archive-*.md`` — where ``aide insights archive`` moves closed
#:   entries. The one pattern here, added deliberately rather than by widening
#:   the rule: it is bounded to a single directory *and* a single filename
#:   shape, and ``path_matches`` anchors a bare ``*`` per path segment, so it
#:   cannot reach a subdirectory or a second name. It buys nothing an attacker
#:   or a careless agent wants — only the file the verb above it writes.
#:
#: The item's own spec is authorised separately, by number, in ``cmd_scope`` —
#: the builder records Decisions & Trade-offs there on every item.
_ALWAYS_AUTHORISED = ("progress.md", "insights.md", "insights/archive-*.md")


def _always_authorised_paths(ddir_rel: str) -> Tuple[str, ...]:
    """The always-authorised names as repo-relative patterns, the spelling item
    specs use. One joiner for the three enforcement sites — the pin lint in
    `item_spec_warnings`, the overlap exclusion in `queue_spec_findings`, and
    `cmd_scope` — so what counts as loop bookkeeping cannot drift between
    them."""
    return tuple(f"{ddir_rel}/{name}" for name in _ALWAYS_AUTHORISED)


class AuthorisedPaths(NamedTuple):
    """The two lists of an item spec's ``## Authorised paths`` section."""

    may_change: List[str]
    asserts_against: List[str]


def _strip_dot_slash(path: str) -> str:
    """Drop a leading ``./``, and only that.

    Never ``lstrip("./")``, which strips leading *characters* from that set and
    so silently renames the dotfiles specs routinely authorise —
    ``.gitattributes`` to ``gitattributes``, ``.github/workflows/ci.yml`` to
    ``github/workflows/ci.yml`` — turning a declared path into one that matches
    nothing git ever reports.
    """
    while path.startswith("./"):
        path = path[2:]
    return path


def _sub_list_label(line: str) -> Optional[str]:
    """The normalised sub-list label on *line*, or None if it is not one."""
    text = line.strip().strip("*_").strip().rstrip(":").strip().lower()
    if text == _MAY_CHANGE_LABEL:
        return _MAY_CHANGE_LABEL
    if text == _ASSERTS_LABEL:
        return _ASSERTS_LABEL
    return None


def _bullet_path(line: str) -> Optional[str]:
    """The repo-relative path a section bullet declares, or None.

    A bullet is ``- `path` — why``: the path is the FIRST backtick span, never
    the whole body, because the reason that follows it is prose. Falls back to
    the text before the first dash/colon separator for a bullet written without
    backticks. Returns None for a bullet that declares no path — an unfilled
    ``{{slot}}`` (``aide check`` already errors on those, so failing here as
    well would report one authoring slip twice) or a literal "None."

    A line is a bullet only when its marker is followed by whitespace
    (`_LIST_MARKER_RE`, issue #270): a wrapped reason whose continuation line
    opens on ``**bold**`` is emphasis, and reading it as a bullet granted its
    first backtick span as a phantom authorised path.
    """
    stripped = line.strip()
    if not _LIST_MARKER_RE.match(stripped):
        return None
    body = stripped[1:].strip()
    if not body or "{{" in body:
        return None
    m = re.search(r"`([^`]+)`", body)
    if m:
        candidate = m.group(1)
    else:
        candidate = _BULLET_REASON_RE.split(body, maxsplit=1)[0]
    candidate = candidate.strip().strip("`").strip()
    if not candidate or candidate.rstrip(".").lower() == "none":
        return None
    return _strip_dot_slash(candidate)


#: Every backtick span on a line, and where a bullet's reason starts. The two
#: together locate the bullet's PATH POSITION — the run before the reason
#: separator — which is the only place a span is a path claim. `_bullet_path`
#: splits on the same separator for a bullet written without backticks, so the
#: two readings of "where the path ends" cannot drift apart.
_BACKTICK_SPAN_RE = re.compile(r"`([^`]+)`")
#: The dash may END the line — `- `path` —` with the reason wrapped below is a
#: common way to write a long one, and reading it as "no reason yet" would take
#: the whole reason for more path position.
_BULLET_REASON_RE = re.compile(r"\s+[—–-](?:\s+|$)|:")

#: A Markdown list marker: the marker character, then whitespace. A
#: continuation line opening `**not** in the project group …` is emphasis, not
#: a bullet. The parser (`_bullet_path`) and the lint both gate on this one
#: pattern, so they cannot disagree about which lines are bullets — until issue
#: #270 the parser tested only the first character, and a continuation line
#: opening on `**Relationship to `vision.md`**` authorised `vision.md`.
_LIST_MARKER_RE = re.compile(r"[-*+]\s")


def _authorised_section_lines(text: str) -> Optional[List[str]]:
    """The lines under ``## Authorised paths``, or None when it is absent.

    One slicer for the parser and the spec-time lint below, so the lint cannot
    warn about a bullet the parser never looked at, or stay silent about one it
    did — the whole point of the warning is to describe what `aide scope` will
    actually do with the section.
    """
    lines = text.splitlines()
    start = None
    for i, line in enumerate(lines):
        if line.strip() == _AUTHORISED_HEADING:
            start = i + 1
            break
    if start is None:
        return None

    end = len(lines)
    for i in range(start, len(lines)):
        if _ANY_HEADER_RE.match(lines[i]) and lines[i].strip() != _AUTHORISED_HEADING:
            end = i
            break
    return lines[start:end]


def _path_position(line: str) -> Tuple[str, bool]:
    """The run of *line* before its reason separator, and whether one was seen.

    Everything after the separator is the reason, and a bullet is required to
    carry one — so a backticked name there is prose about the work, not a path
    claim. Measured on two real consumers, treating it as a path claim produced
    82 and 224 findings, almost all of them identifiers and TOML keys quoted in
    reasons; the spec that *reported* issue #119 would have raised six.
    """
    m = _BULLET_REASON_RE.search(line)
    return (line[: m.start()], True) if m else (line, False)


def dropped_bullet_spans(text: str) -> List[Tuple[str, List[str]]]:
    """``(path read, spans dropped)`` for each over-full Authorised-paths bullet.

    The contract is one path per bullet (conventions.md §1 → authorised-paths),
    and until issue #119 the two ways to break it were both silent: a bullet
    listing several comma-separated `` `path` `` spans authorised only the
    first, and a path list wrapped onto a continuation line lost everything
    below the first line, since the parser only ever inspects bullet lines. The
    narrowing surfaced much later as an `aide scope` FAIL naming paths the
    spec's own prose plainly authorised — three of one item's four bullets had
    that shape.

    Only the **path position** is read: the bullet's opening line up to its
    reason separator, plus the continuation lines while no separator has been
    seen yet, which is exactly the wrapped-list shape. That limit is what makes
    the lint worth reading rather than a source of noise to page past, and it
    is a limit: a path named after the separator is not distinguishable from a
    reason that mentions a file, so a second path written there stays silent.
    The bullet is closed by a blank line, a sub-list label, or the next bullet
    — the same shape a Markdown reader sees, so an author can predict what the
    lint attributes where.

    Silently narrowing an authorisation is the worst of the three behaviours
    available, so what IS found is reported where it is authored. A *warning*,
    not an error: the bullet is legible to a human, existing specs carry the
    shape, and the remedy (split the bullet) is the author's to apply.
    """
    section = _authorised_section_lines(text)
    if section is None:
        return []
    found: List[Tuple[str, List[str]]] = []
    open_bullet: Optional[Tuple[str, List[str]]] = None
    for line in section:
        stripped = line.strip()
        if not stripped or _sub_list_label(line) is not None:
            open_bullet = None
            continue
        if _LIST_MARKER_RE.match(stripped):
            open_bullet = None
            path = _bullet_path(line)
            # A bullet the parser declines — an unfilled `{{slot}}`, a literal
            # "None." — is somebody else's finding (`aide check` errors on the
            # slot), and nothing under it was going to be read anyway.
            if path is None:
                continue
            head, reason = _path_position(stripped[1:].strip())
            entry = (path, _BACKTICK_SPAN_RE.findall(head)[1:])
            found.append(entry)
            if not reason:
                open_bullet = entry
        elif open_bullet is not None:
            head, reason = _path_position(line)
            open_bullet[1].extend(_BACKTICK_SPAN_RE.findall(head))
            if reason:
                open_bullet = None
    return [(path, dropped) for path, dropped in found if dropped]


def declares_nothing(parsed: Optional[AuthorisedPaths]) -> bool:
    """True when a spec's scope cannot be compared with anything.

    An **empty May change is not the same as nothing declared**: a
    queue-end item legitimately changes only the loop bookkeeping every
    item may write, while still pinning the tree it validates under *Asserts
    against*. Treating that as undeclared would drop exactly the specs whose
    whole purpose is to assert — so the test is that *both* lists are empty.
    """
    return parsed is None or not (parsed.may_change or parsed.asserts_against)


def parse_authorised_paths(text: str) -> Optional[AuthorisedPaths]:
    """Parse an item spec's ``## Authorised paths`` section.

    Returns None when the section is absent — distinct from a present-but-empty
    section (``AuthorisedPaths([], [])``), because the two need different
    remedies and neither may be read as "unconstrained" (conventions.md §1).

    Bullets appearing before either sub-list label are read as **May change**,
    which is what makes the flat single-list form — the shape consumers wrote
    before the labels existed — parse correctly rather than silently empty.
    """
    section = _authorised_section_lines(text)
    if section is None:
        return None

    may_change: List[str] = []
    asserts_against: List[str] = []
    current = may_change
    for line in section:
        label = _sub_list_label(line)
        if label is not None:
            current = may_change if label == _MAY_CHANGE_LABEL else asserts_against
            continue
        path = _bullet_path(line)
        if path is not None:
            current.append(path)
    return AuthorisedPaths(may_change, asserts_against)


def path_matches(changed: str, pattern: str) -> bool:
    """True when repo-relative *changed* is covered by *pattern*.

    Three forms, per conventions.md §1:

    - ``dir/**`` — the directory and anything at any depth below it.
    - any other pattern containing ``*``, ``?`` or ``[`` — an ordinary shell
      glob matched **per path segment**, so ``tests/golden/*.json`` covers a
      JSON file in that directory but not one a level deeper. Anchoring per
      segment is the point: ``fnmatch``'s ``*`` crosses ``/`` and would quietly
      widen every glob a spec writes into a subtree wildcard.
    - anything else — an exact path.
    """
    pattern = _strip_dot_slash(pattern.strip())
    if pattern.endswith("/**"):
        prefix = pattern[: -len("/**")]
        return changed == prefix or changed.startswith(prefix + "/")
    if any(ch in pattern for ch in "*?["):
        pat_parts = pattern.split("/")
        path_parts = changed.split("/")
        if len(pat_parts) != len(path_parts):
            return False
        return all(fnmatch.fnmatchcase(p, g) for p, g in zip(path_parts, pat_parts))
    return changed == pattern


def scope_findings(changed: List[str], authorised: AuthorisedPaths,
                   always: Tuple[str, ...] = ()) -> Tuple[List[str], List[str]]:
    """``(unauthorised, contradictions)`` for a branch's *changed* paths.

    A contradiction is a path the spec declared under **Asserts against** — "my
    tests pin this without changing it" — and then changed anyway. It is
    reported separately from an unauthorised path because the remedy differs:
    one widens a list, the other means an assertion in this very item is now
    asserting against state the item moved.
    """
    unauthorised = [p for p in changed
                    if not any(path_matches(p, a) for a in always)
                    and not any(path_matches(p, g) for g in authorised.may_change)]
    contradictions = [p for p in changed
                      if any(path_matches(p, g) for g in authorised.asserts_against)]
    return unauthorised, contradictions


#: `AC3`, `ac3` — the criterion number a test name carries. Not `mac3` or
#: `ac30` for AC3: the token is bounded on both sides.
_AC_TOKEN_RE = re.compile(r"(?<![a-z0-9])ac(\d+)(?![0-9])")
_AC_HEADING_RE = re.compile(r"^##\s+Acceptance Criteria\b", re.MULTILINE | re.IGNORECASE)
_TESTING_HEADING_RE = re.compile(r"^##\s+Testing Strategy\b", re.MULTILINE | re.IGNORECASE)
#: `## Review findings` — the bullets a review round's regression tests trace
#: to (issue #319). Optional: a spec without it names no labels there.
_REVIEW_HEADING_RE = re.compile(r"^##\s+Review findings\b", re.MULTILINE | re.IGNORECASE)
#: A case label: the first token of a Testing Strategy **bullet**, closed by a
#: colon — `- empty-input: the walker yields nothing` — with or without
#: backticks or bold around the token. One word, so "existing tests to
#: reconcile:" and a `tests/test_x.py:` module name are prose, not labels;
#: and a bullet, so a prose "Note: …" line in the section is not one either
#: (a generic label would silence every test whose name contains it).
_CASE_LABEL_RE = re.compile(r"^\s*[-*]\s+[`*_]*([A-Za-z][A-Za-z0-9_-]*)[`*_]*\s*:")
#: The same label closed by a full stop instead (issue #315), which needs the
#: token wrapped in emphasis or backticks — `- **empty-input.** the walker …`,
#: `- **empty-input**. …`, `` - `empty-input`. … `` — and text after it on the
#: line. A full stop ends nearly every short prose bullet, so an unwrapped
#: `- Note. The walker …` is prose: read as a label, `note` would silence
#: every test whose name contains it. `- **done.**` alone is prose too.
_STOP_LABEL_RE = re.compile(
    r"^\s*[-*]\s+([`*_]+)([A-Za-z][A-Za-z0-9_-]*)(?:\.\1|\1\.)\s+\S")


def _case_label(line: str) -> Optional[str]:
    """The case label *line* opens with, or None (`_CASE_LABEL_RE`,
    `_STOP_LABEL_RE`)."""
    m = _CASE_LABEL_RE.match(line)
    if m:
        return m.group(1)
    m = _STOP_LABEL_RE.match(line)
    return m.group(2) if m else None


_FENCE_RE = re.compile(r"^[ \t]*(```|~~~).*?^[ \t]*\1[^\n]*$", re.MULTILINE | re.DOTALL)


def _section_text(text: str, heading: "re.Pattern") -> str:
    """The body under *heading*, up to the next `## `, with every fenced block
    inside that slice removed — a fence is code, not a bullet list. The slice
    is cut first, so a fence left open in an earlier section cannot swallow
    this one."""
    m = heading.search(text)
    if m is None:
        return ""
    rest = text[m.end():]
    nxt = re.search(r"^##\s", rest, re.MULTILINE)
    section = rest if nxt is None else rest[: nxt.start()]
    return _FENCE_RE.sub("", section)


def spec_acceptance_numbers(text: str) -> List[int]:
    """The criterion numbers a spec's ``## Acceptance Criteria`` names."""
    return sorted({int(n) for n in re.findall(r"\bAC(\d+)\b",
                                             _section_text(text, _AC_HEADING_RE))})


def _section_labels(text: str, heading: "re.Pattern") -> List[str]:
    out: List[str] = []
    for line in _section_text(text, heading).splitlines():
        label = _case_label(line)
        if label and label not in out:
            out.append(label)
    return out


def testing_strategy_labels(text: str) -> List[str]:
    """The case labels a spec's ``## Testing Strategy`` names, in order."""
    return _section_labels(text, _TESTING_HEADING_RE)


def review_finding_labels(text: str) -> List[str]:
    """The labels a spec's optional ``## Review findings`` names, in order —
    the same bullet shape as a Testing Strategy case (issue #319)."""
    return _section_labels(text, _REVIEW_HEADING_RE)


def spec_case_labels(text: str) -> List[str]:
    """Every label a test the item adds may trace to: the Testing Strategy's
    cases, then the Review findings' — what `aide scope` and the ledger's
    reconciled split both read."""
    out = testing_strategy_labels(text)
    return out + [lbl for lbl in review_finding_labels(text) if lbl not in out]


#: One test function the branch added: its file, its name, and the literal
#: ids of its `pytest.mark.parametrize` cases (issue #314) — empty for an
#: unparametrised test.
AddedTest = Tuple[str, str, Tuple[str, ...]]


def _str_constants(node: "ast.AST") -> List[str]:
    """The string constants among *node*'s first-level elements (a list or
    tuple), or *node* itself when it is one."""
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return [node.value]
    if isinstance(node, (ast.List, ast.Tuple)):
        return [e.value for e in node.elts
                if isinstance(e, ast.Constant) and isinstance(e.value, str)]
    return []


def _is_parametrize(func: "ast.AST") -> bool:
    """`pytest.mark.parametrize` or `mark.parametrize`, however imported."""
    if not (isinstance(func, ast.Attribute) and func.attr == "parametrize"):
        return False
    mark = func.value
    return ((isinstance(mark, ast.Attribute) and mark.attr == "mark")
            or (isinstance(mark, ast.Name) and mark.id == "mark"))


def _parametrize_ids(fn: "ast.AST") -> Tuple[str, ...]:
    """The literal case ids of every `parametrize` decorator on *fn*.

    Static, never collected: a string argvalue, the first-level strings of a
    tuple or list argvalue, a `pytest.param`'s string arguments and its
    `id=`, and each string in an explicit `ids=[...]`. Anything computed —
    a name, a call, a comprehension — is not read, and contributes nothing.
    """
    out: List[str] = []
    for dec in getattr(fn, "decorator_list", []):
        if not (isinstance(dec, ast.Call) and _is_parametrize(dec.func)):
            continue
        argvalues = dec.args[1] if len(dec.args) > 1 else None
        for kw in dec.keywords:
            if kw.arg == "argvalues":
                argvalues = kw.value
            elif kw.arg == "ids":
                out.extend(_str_constants(kw.value)
                           if isinstance(kw.value, (ast.List, ast.Tuple)) else [])
        if isinstance(argvalues, (ast.List, ast.Tuple)):
            for case in argvalues.elts:
                if (isinstance(case, ast.Call) and isinstance(case.func, ast.Attribute)
                        and case.func.attr == "param"):
                    for arg in case.args:
                        out.extend(_str_constants(arg))
                    out.extend(kw.value.value for kw in case.keywords
                               if kw.arg == "id" and isinstance(kw.value, ast.Constant)
                               and isinstance(kw.value.value, str))
                else:
                    out.extend(_str_constants(case))
    return tuple(dict.fromkeys(out))


def _test_functions(source: str) -> List[Tuple[str, Tuple[str, ...]]]:
    """``(name, parametrize ids)`` for every `test*` function in *source*."""
    try:
        tree = ast.parse(source.lstrip("\ufeff"))
    except SyntaxError:
        return []
    return [(n.name, _parametrize_ids(n)) for n in ast.walk(tree)
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
            and n.name.startswith("test")]


def _test_function_names(source: str) -> List[str]:
    return [name for name, _ in _test_functions(source)]


def _under_dir(rel: str, directory: str) -> bool:
    """*rel* (a posix path git printed) sits under *directory* (whatever
    `aide.toml` spelled: `tests`, `./tests`, `tests\\unit`, `.`)."""
    root = tuple(p for p in PurePosixPath(directory.replace("\\", "/")).parts
                 if p not in (".", ""))
    return PurePosixPath(rel).parts[: len(root)] == root


def _tests_dir_rel(repo_root: Path, config) -> Optional[str]:
    """`tests_dir` as a path relative to the repo, whatever `aide.toml`
    spelled; None when an absolute value points outside the repository, where
    no git-relative path can match it."""
    raw = str(config["project"].get("tests_dir", "tests"))
    path = Path(raw)
    if not path.is_absolute():
        return raw
    try:
        return path.resolve().relative_to(repo_root.resolve()).as_posix()
    except ValueError:
        return None


def renamed_paths(repo_root: Path, merge_base: str) -> Dict[str, str]:
    """``{new path: old path}`` for every rename git detects vs *merge_base*."""
    # `core.quotePath=false`: with the default, a non-ASCII OLD path comes back
    # quoted and octal-escaped, and `git show <mb>:"…"` then finds nothing.
    status = git(["-c", "core.quotePath=false", "diff", "--name-status", "-M",
                  merge_base], repo_root, check=False)
    out: Dict[str, str] = {}
    if status.returncode != 0:
        return out
    for line in status.stdout.splitlines():
        cells = line.split("\t")
        if len(cells) == 3 and cells[0][:1] in ("R", "C"):
            new, old = root_relative(repo_root, [cells[2].strip(), cells[1].strip()])
            out[new] = old
    return out


def added_test_functions(repo_root: Path, config, changed: List[str],
                         merge_base: str,
                         renamed: Optional[Dict[str, str]] = None,
                         ref: Optional[str] = None) -> List[AddedTest]:
    """``(path, name, ids)`` for every test function the branch added, *ids*
    being its literal `parametrize` case ids (`_parametrize_ids`).

    A test file among *changed* is read from the working tree and compared to
    its version at *merge_base* — under its old name where *renamed* says the
    branch moved it; a name present in both is an edit to an existing test (a
    reconcile the spec listed, §6) and is not the item's own. A file that did
    not exist at the base contributes every test in it.

    *ref* reads the new side from a ref instead of the working tree, for a
    caller that must count a branch it is not standing on — `aide merge`
    writing a ledger row (§1 → `ledger.md`) is about to merge the branch and
    delete it, and a count that depended on the checkout would be a different
    number on either side of that. A path the ref does not carry contributes
    nothing, exactly as a path missing from the working tree does.
    """
    tests_dir = _tests_dir_rel(repo_root, config)
    renamed = renamed or {}
    out: List[AddedTest] = []
    if tests_dir is None:
        return out
    for rel in changed:
        if not rel.endswith(".py") or not _under_dir(rel, tests_dir):
            continue
        if ref is None:
            path = repo_root / rel
            if not path.is_file():
                continue
            try:
                new = _test_functions(path.read_text(encoding=_ENCODING))
            except (OSError, UnicodeDecodeError):
                continue
        else:
            at_ref = git(["show", f"{ref}:./{rel}"], repo_root, check=False)
            if at_ref.returncode != 0:
                continue
            new = _test_functions(at_ref.stdout)
        shown = git(["show", f"{merge_base}:./{renamed.get(rel, rel)}"], repo_root, check=False)
        # Keyed on the name alone: a function present at the base is an edit,
        # whatever its parametrize ids became.
        old = set(_test_function_names(shown.stdout)) if shown.returncode == 0 else set()
        out.extend((rel, name, ids) for name, ids in new if name not in old)
    return out


def _unpack_added(entry: Tuple) -> AddedTest:
    """An added test as ``(path, name, ids)`` — a two-tuple has no ids."""
    rel, name, *rest = entry
    return rel, name, tuple(rest[0]) if rest else ()


def _traces_to(name: str, ac_numbers: List[int], labels: List[str],
               ids: Tuple[str, ...] = ()) -> bool:
    """*name* carries one of *ac_numbers* (`ac3`) or one of *labels*, or one
    of its parametrize *ids* does (issue #314).

    The name matches a label anywhere in it, as it always has. An id is
    compared normalised the same way (lower case, `-` read as `_`), and a
    label or `acN` must stand in it as a whole token — bounded by anything
    but a letter or digit — since an id is often a free-text value rather
    than a name built from its case: label `call` matches id `bool-call`,
    and does not match `recall`.
    """
    wanted = set(ac_numbers)
    norm = [lbl.lower().replace("-", "_") for lbl in labels]
    low = name.lower()
    if any(int(n) in wanted for n in _AC_TOKEN_RE.findall(low)):
        return True
    if any(lbl in low for lbl in norm):
        return True
    for raw in ids:
        ident = raw.lower().replace("-", "_")
        if any(int(n) in wanted for n in _AC_TOKEN_RE.findall(ident)):
            return True
        if any(re.search(rf"(?<![a-z0-9]){re.escape(lbl)}(?![a-z0-9])", ident)
               for lbl in norm):
            return True
    return False


def traceability_warnings(added: List[Tuple], ac_numbers: List[int],
                          labels: List[str], rel_spec: str,
                          owner: Optional[int] = None) -> List[str]:
    """§6: a test the item adds names the criterion (`ac3`), the Testing
    Strategy case or the Review findings entry it covers — by its name or by
    one of its parametrize ids; one that names none is a test nobody asked
    for. A warning, never a FAIL: the rule is new and a consumer lives with
    the report before it gates anything.

    *owner* is set when the tests sit in another item's test file and
    *rel_spec* is that item's spec (`split_reconciled_tests`), and the warning
    then says whose file it is — the branch carries it, the spec it is read
    against is not the one being scoped."""
    where = (f" — in item {owner:03d}'s test file, which this branch changed"
             if owner is not None else "")
    out: List[str] = []
    for entry in added:
        rel, name, ids = _unpack_added(entry)
        if not _traces_to(name, ac_numbers, labels, ids):
            out.append(f"warning: {rel}::{name} names no AC number and no "
                       f"Testing Strategy or Review findings case of "
                       f"{rel_spec}{where} — a test the spec did not ask for "
                       f"(conventions.md §6)")
    return out


#: `test_007_walker.py` — a test file named for the item that owns it. The
#: digits are confirmed against the spec filename's own zero-padding
#: (`_item_spec_glob`), so `test_7_x.py` and `test_0007_x.py` name no item,
#: exactly as `7-x.md` and `0007-x.md` name no spec (`item_spec_number`).
_OWNED_TEST_FILE_RE = re.compile(r"test_(\d+)_")


def owning_item(rel: str) -> Optional[int]:
    """The item number a test file's name says owns it, or None."""
    m = _OWNED_TEST_FILE_RE.match(PurePosixPath(rel).name)
    if not m:
        return None
    number = int(m.group(1))
    return number if f"{number:03d}" == m.group(1) else None


class ReconciledTests(NamedTuple):
    """The added tests in one other item's test files, split against its spec."""
    spec: str                  # that item's spec, repo-relative
    reconciled: List[AddedTest]  # traced to its criteria or cases
    untraced: List[AddedTest]    # traced to neither


def split_reconciled_tests(repo_root: Path, config,
                           added: List[Tuple], number: int,
                           ) -> Tuple[List[AddedTest], Dict[int, ReconciledTests]]:
    """``(own, others)``: *added* split by the item whose test file each sits in.

    A test in ``test_NNN_…py`` for an item other than *number* was reconciled
    there by this branch — a rename or edit this item's spec prescribed — and
    its criterion number is that item's (§6). So it is traced against **that
    item's spec**, never *number*'s: tracing it against the scoped spec both
    reported a prescribed reconcile as unrequested and silently credited an
    ``ac2`` to whichever item happened to have an AC2 too (issue #262). The
    traced ones are ``others[N].reconciled``; the rest still name nothing
    anyone asked for and are ``others[N].untraced``.

    A file whose owner has no spec, one that cannot be read, or one with no
    ``## Acceptance Criteria`` heading is not resolved to that owner and
    stays in *own* — today's reading, against the scoped spec. An owner
    whose spec cannot be checked is not one to credit a test to, and staying
    in *own* keeps the test counted by the ledger and warned on by `scope`.
    `aide scope` and the ledger's tests-added cell both read this split, so
    the tests one reports as reconciled are exactly the ones the other does
    not count.
    """
    idir = docs_dir(repo_root, config) / "items"
    specs: Dict[int, Optional[Tuple[str, List[int], List[str]]]] = {}
    own: List[AddedTest] = []
    others: Dict[int, ReconciledTests] = {}
    for entry in added:
        rel, name, ids = test = _unpack_added(entry)
        owner = owning_item(rel)
        if owner is None or owner == number:
            own.append(test)
            continue
        if owner not in specs:
            specs[owner] = None
            found = item_spec_paths(idir, owner)
            if found:
                try:
                    text = found[0].read_text(encoding=_ENCODING)
                except (OSError, UnicodeDecodeError):
                    text = ""
                if _AC_HEADING_RE.search(text):
                    specs[owner] = (found[0].relative_to(repo_root).as_posix(),
                                    spec_acceptance_numbers(text),
                                    spec_case_labels(text))
        if specs[owner] is None:
            own.append(test)
            continue
        rel_spec, acs, labels = specs[owner]
        bucket = others.setdefault(owner, ReconciledTests(rel_spec, [], []))
        traced = _traces_to(name, acs, labels, ids)
        (bucket.reconciled if traced else bucket.untraced).append(test)
    return own, others


def _scope_base_ref(repo_root: Path, config, explicit: Optional[str]) -> str:
    """The ref ``scope`` diffs against: ``--base`` > the branch's recorded base
    > ``main_branch``.

    An explicit ``--base`` is used **verbatim** — the caller named a ref, so
    silently substituting ``origin/`` for it would make ``--base main`` mean
    something the caller did not write, and leave no way to ask for the local
    ref at all. The two *derived* answers do prefer their ``origin/``
    counterpart, since neither was chosen by anyone.

    The remote-tracking preference is the footgun this exists to avoid: on a
    checkout whose local ``main`` sits behind the work, the merge-base with it
    *is* it, so every file the earlier items touched gets reported against the
    current item's spec. Consulting the recorded base first is what makes the
    verb correct on stacked work — an item claimed from a queue branch has
    diverged from *that*, not from ``main``, and diffing against ``main`` would
    report every sibling item already merged into the queue.
    """
    if explicit:
        return explicit
    return _remote_or_local(repo_root, resolve_base(repo_root, config))


def cmd_scope(args: argparse.Namespace) -> int:
    """Check that this branch's changed files stay inside the item's spec.

    The diff-time counterpart to a byte-hash "scope fence": it asserts the
    claim the fence encoded — "item N changed only these files" — once, on the
    branch, instead of enshrining it as a suite assertion that outlives its
    truth and goes red the moment a later item is authorised to touch the
    pinned file (conventions.md §1).

    Exit 0 in scope · 1 something changed outside it · 2 could not check.
    """
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    if not _require_repository("scope", repo_root):
        return 2
    prefix = str(config["git"].get("branch_prefix", "aide/"))

    number = args.number
    if number is None:
        branch = _current_branch(repo_root)
        if _is_queue_branch(branch, prefix):
            print(f"aide scope: {branch} is a queue branch, not an item claim — "
                  "per-item scope is checked on each claim branch as it merges "
                  "here, and a queue branch legitimately aggregates many items' "
                  "authorised paths. Nothing to check.")
            return 0
        number = _branch_item_number(branch, prefix)
        if number is None:
            print(f"aide scope: cannot tell which item to check — branch "
                  f"'{branch}' is not {prefix}NNN-short-name. Name the item "
                  f"explicitly: aide scope NNN", file=sys.stderr)
            return 2

    idir = docs_dir(repo_root, config) / "items"
    specs = item_spec_paths(idir, number)
    if not specs:
        print(f"aide scope: no spec for item {number:03d} under {idir}",
              file=sys.stderr)
        return 2
    spec = specs[0]
    rel_spec = spec.relative_to(repo_root).as_posix()

    spec_text = spec.read_text(encoding=_ENCODING)
    authorised = parse_authorised_paths(spec_text)
    if declares_nothing(authorised):
        what = ("has no '## Authorised paths' section" if authorised is None
                else "declares no path under '## Authorised paths'")
        print(f"aide scope: {rel_spec} {what} — cannot check scope. This is "
              "reported, never passed silently: an undeclared spec is not an "
              "unconstrained one. Add the section (see conventions.md §1) and "
              "re-run.", file=sys.stderr)
        return 2

    base = _scope_base_ref(repo_root, config, args.base)
    mb = git(["merge-base", base, "HEAD"], repo_root, check=False)
    if mb.returncode != 0:
        print(f"aide scope: could not resolve a merge-base with '{base}' — "
              f"{mb.stderr.strip()}", file=sys.stderr)
        return 2
    diff = git(["diff", "--name-only", mb.stdout.strip()], repo_root, check=False)
    if diff.returncode != 0:
        print(f"aide scope: git diff failed — {diff.stderr.strip()}",
              file=sys.stderr)
        return 2

    # Relative to repo_root, which may sit below git's top level; a change
    # outside it comes back as `../…` and is reported, never dropped.
    changed = root_relative(repo_root, [ln.strip() for ln in
                                        diff.stdout.splitlines() if ln.strip()])
    ddir_rel = docs_dir(repo_root, config).relative_to(repo_root).as_posix()
    always = _always_authorised_paths(ddir_rel) + (rel_spec,)
    unauthorised, contradictions = scope_findings(changed, authorised, always)

    traced: List[str] = []
    added = added_test_functions(repo_root, config, changed, mb.stdout.strip(),
                                 renamed_paths(repo_root, mb.stdout.strip()))
    own, others = split_reconciled_tests(repo_root, config, added, number)
    if _tests_dir_rel(repo_root, config) is None:
        print("notice: tests_dir lies outside the repository — traceability "
              "not checked")
    elif own and _AC_HEADING_RE.search(spec_text) is None:
        print(f"notice: {rel_spec} has no '## Acceptance Criteria' heading — "
              "traceability not checked")
    elif own:
        traced = traceability_warnings(
            own, spec_acceptance_numbers(spec_text),
            spec_case_labels(spec_text), rel_spec)
    for owner, split in sorted(others.items()):
        if split.reconciled:
            print(f"notice: reconciled {len(split.reconciled)} test(s) in item "
                  f"{owner:03d}'s test files ({split.spec})")
        traced += traceability_warnings(split.untraced, [], [], split.spec, owner)
    for line in traced:
        print(line)
    note = f", {len(traced)} traceability warning(s)" if traced else ""

    for path in contradictions:
        print(f"error: {path} changed, but {rel_spec} lists it under "
              "'Asserts against' as pinned-not-changed")
    for path in unauthorised:
        print(f"error: {path} not authorised by {rel_spec}")

    total = len(unauthorised) + len(contradictions)
    if total:
        print(f"aide scope: FAIL (item {number:03d}, {total} of {len(changed)} "
              f"changed file(s) outside scope, vs {base}{note})")
        return 1
    print(f"aide scope: OK (item {number:03d}, {len(changed)} changed file(s) "
          f"all authorised, vs {base}{note})")
    return 0


def _landed_review_items(repo_root: Path, config, prefix: str,
                         explicit: Optional[str] = None) -> List[str]:
    """Lines naming every 🔍 item whose branch has since landed in its base.

    Each claim is measured against its own base, resolved the way every other
    verb resolves one — *explicit* (``--base``) > the base that claim recorded >
    ``main_branch`` (issue #213). Measuring every claim against ``main_branch``
    meant stacked work never came home: an item merged into its queue branch is
    not in main until the queue lands, so it stayed 🔍 with nothing saying why.

    ``main_branch`` is still measured when that base does not report the work
    landed. A queue branch is deleted once it lands (`gc --merged` collects it),
    and `merge-tree` against a ref that no longer exists exits 1 exactly as a
    conflict does — so without the second measurement a 🔍 item whose queue
    had landed *and been cleaned up* was never reported again, though its work
    was in main. Work in main has landed wherever it was first merged.

    In `pr` mode nothing inside the loop ever observes the merge — the human
    does it on the forge, hours or days later — so 🔍 needs a way home or it is
    a state items enter and never leave. This is that way home, and it needs no
    knowledge of what a PR is: the same content oracle `gc` uses answers "has
    this work landed?" without a forge call that would silently degrade to
    "no open PRs found" when `gh` is missing or unauthenticated.

    Reports rather than edits. `sync` is a preflight, and a preflight that
    rewrites a tracked document as a side effect is not one.
    """
    item_status = _progress_item_status(repo_root, config)
    reviewing = {n for n, st in item_status.items() if st == "in-review"}
    if not reviewing or not _has_merge_tree(repo_root):
        return []
    local = _local_branches(repo_root)
    main = str(config["git"].get("main_branch", "main"))
    lines: List[str] = []
    for br in sorted(_list_claim_branches(repo_root, prefix)):
        num = _branch_item_number(br, prefix)
        if num not in reviewing:
            continue
        ref = _gc_ref(br, local)
        base = resolve_base(repo_root, config, explicit, br)
        candidates = [base] if base == main else [base, main]
        landed = next((b for b in candidates
                       if _branch_content_landed(repo_root, b, ref) is True), None)
        if landed is not None:
            base = landed
            lines.append(f"aide sync: item {num:03d} is 🔍 but its work is now in "
                         f"{base} — run "
                         f"'{aide_command(repo_root, f'progress set {num:03d} done')}'")
    return lines


def cmd_sync(args: argparse.Namespace) -> int:
    """Deterministic preflight: fetch, verify a clean start point, land on the
    right branch. Replaces the exploratory ``git status``/``git branch``/
    ``git fetch`` sequence agents otherwise improvise before starting work.
    Exit 0 == safe to start; exit 1 prints the one reason work must not start.
    """
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    mode = str(config["git"].get("mode", "auto-merge"))
    main = str(config["git"].get("main_branch", "main"))
    # Outside a repository every read below comes back empty, and empty read
    # as "on '', tree clean" — an OK for a start point that does not exist.
    if not _require_repository("sync", repo_root):
        return 1

    # Whether origin was asked, for the success line: `mode` alone said
    # "remotes fetched" over a repository with no origin (issue #352).
    fetched = mode != "local" and _has_origin(repo_root)
    if fetched:
        res = git(["fetch", "--all", "--prune"], repo_root, check=False)
        if res.returncode != 0:
            print(f"aide sync: fetch failed — {res.stderr.strip()}", file=sys.stderr)
            return 1

    dirty = git(["status", "--porcelain"], repo_root, check=False).stdout.strip()
    if dirty:
        print("aide sync: working tree not clean — commit or stash before starting:",
              file=sys.stderr)
        print(dirty, file=sys.stderr)
        return 1

    branch = git(["rev-parse", "--abbrev-ref", "HEAD"], repo_root, check=False).stdout.strip()

    # Bring main up to date when we're on it (safe fast-forward only).
    if branch == main and mode != "local" and _has_origin(repo_root):
        counts = git(["rev-list", "--left-right", "--count", f"{main}...origin/{main}"],
                     repo_root, check=False).stdout.split()
        if len(counts) == 2:
            ahead, behind = int(counts[0]), int(counts[1])
            if behind and not ahead:
                git(["merge", "--ff-only", f"origin/{main}"], repo_root, check=False)
                print(f"aide sync: fast-forwarded {main} ({behind} commit(s))")
            elif behind:
                print(f"aide sync: {main} has diverged from origin/{main} "
                      f"({ahead} ahead / {behind} behind) — reconcile first", file=sys.stderr)
                return 1

    if args.item is not None:
        claim = _find_claim_branch(repo_root, prefix, args.item)
        if not claim:
            print(f"aide sync: no claim branch for item {args.item:03d} — run "
                  f"'{aide_command(repo_root, 'claim')}' first", file=sys.stderr)
            return 1
        if branch != claim:
            res = git(["switch", claim], repo_root, check=False)
            if res.returncode != 0:
                print(f"aide sync: could not switch to {claim}:\n{res.stderr}", file=sys.stderr)
                return 1
            branch = claim
        if mode != "local" and _has_origin(repo_root) and claim in _remote_branches(repo_root):
            if _has_unpushed_merge(repo_root, f"origin/{claim}"):
                # The same guard the bookkeeping and post-merge pulls have
                # (issue #235): `pull --rebase` over a local merge commit
                # linearises it silently, or stops mid-rebase on the conflict
                # the merge resolved — on a checkout other roles may share.
                # `--ff-only` refuses instead of rewriting.
                ff = git(["pull", "--ff-only", "origin", claim], repo_root, check=False)
                if ff.returncode != 0:
                    print(f"aide sync: {claim} carries a merge commit origin "
                          f"has not seen, and origin/{claim} has moved on. "
                          f"Rebasing over it would linearise the merge and "
                          f"bring back the conflicts it resolved, so this verb "
                          f"stops rather than choosing for you: push the claim "
                          f"branch first ('git push origin {claim}'), or "
                          f"integrate origin by hand, then re-run.\n"
                          f"{ff.stdout}{ff.stderr}", file=sys.stderr)
                    return 1
                pulled = ff
            else:
                pulled = git(["pull", "--rebase", "origin", claim], repo_root, check=False)
            stalled = _stalled_pull(repo_root, config, pulled)
            if stalled is not None:
                print(f"aide sync: {stalled}\n"
                      f"aide sync: this verb exists to say the start point is "
                      f"safe, and it is not — work must not start here.",
                      file=sys.stderr)
                return 1
            if pulled.returncode != 0:
                # Non-zero, but the tree is untouched: origin unreachable, the
                # ref gone. Not a reason to refuse — the branch is checked out
                # and clean, which is what this verb promises — but the success
                # line below says "remotes fetched", and that would overclaim.
                why = next((l.strip() for l in
                            (pulled.stderr + pulled.stdout).splitlines()
                            if l.strip()), "git gave no reason")
                print(f"aide sync: {claim} was NOT refreshed from origin — "
                      f"{why}. The branch is clean and work can start; it may "
                      f"be behind origin.", file=sys.stderr)

    for line in _landed_review_items(repo_root, config, prefix):
        print(line)

    print(f"aide sync: OK — on '{branch}', tree clean"
          + (", remotes fetched" if fetched
             else "" if mode == "local" else ", no origin to fetch"))
    return 0


# --------------------------------------------------------------------------- #
# status — the stack of unmerged queue branches, and what it means (issue #303)
# --------------------------------------------------------------------------- #
#: How long one forge call may take before `status` reports it could not look.
_GH_TIMEOUT = 20
#: `gh`'s pull-request states, as the stack lines spell them.
_PR_STATES = {"OPEN": "open", "MERGED": "merged", "CLOSED": "closed"}


def _gh(repo_root: Path, args: List[str]) -> Tuple[Optional[str], Optional[str]]:
    """Run the forge's CLI: ``(stdout, None)``, or ``(None, why it could not)``.

    The one place the engine asks `gh` anything: `status` reads through it,
    and `queue pr` / `queue ready` open and flip the queue's own PR through
    it (issue #330). Never raises: missing, unauthenticated, offline and timed out all come
    back as a reason, which is what lets `status` tell "no PR" from "could
    not look" (issue #303). Located by `resolve_tool`: `[tools] gh` in
    `.aide/local.toml`, else PATH, where the `gh.exe` the GitHub CLI installs
    on Windows is found as `gh` is on POSIX; a key naming a `gh` that is not
    there is the reason, never a look on PATH instead (issue #353). Tests
    replace this function; nothing else in the engine calls the forge.
    """
    try:
        exe = resolve_tool("gh", repo_root)
    except ToolMisconfigured as exc:
        return None, str(exc)
    if exe is None:
        return None, "gh is not on PATH"
    try:
        # §6: PR titles are arbitrary UTF-8 and are printed straight through.
        res = subprocess.run([exe, *args], cwd=str(repo_root),
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                             encoding="utf-8", errors="replace",
                             timeout=_GH_TIMEOUT)
    except subprocess.TimeoutExpired:
        return None, f"gh did not answer within {_GH_TIMEOUT}s"
    except (OSError, subprocess.SubprocessError) as exc:
        return None, f"gh could not start ({exc})"
    if res.returncode != 0:
        why = next((l.strip() for l in (res.stderr + res.stdout).splitlines()
                    if l.strip()), "")
        return None, f"gh exited {res.returncode}" + (f": {why}" if why else "")
    return res.stdout, None


class BranchPr(NamedTuple):
    """The one pull request `status` and `queue pr` / `queue ready` answer by.

    ``state`` is ``open``, ``draft``, ``merged`` or ``closed``; ``checks``
    the head commit's CI state as `checks_state` reads it, with ``failing``
    the names of the checks that failed and ``checks_why`` why it is
    ``unknown``.
    """
    number: int
    state: str
    checks: str
    failing: List[str]
    checks_why: Optional[str]
    running: Tuple[str, ...] = ()

    @property
    def label(self) -> str:
        return f"#{self.number}/{self.state}"


def _branch_pr_facts(repo_root: Path, branch: str
                     ) -> Tuple[Optional[BranchPr], Optional[str]]:
    """*branch*'s pull request, ``(None, None)`` for none, ``(None, why)``.

    Every PR whose head is *branch*, in any state: an open one wins, then a
    draft, else the newest — a PR closed and followed by another is answered
    by the second.
    An open PR still in draft is ``draft``, never ``open``: GitHub reports a
    draft as OPEN, and the loop keeps its own queue PR in draft until the
    batch is built, so only a PR marked ready is one awaiting review. The
    head commit's check rollup comes in the same call, so CI state costs no
    second spawn (issue #330). Where that call fails — a token that may not
    read checks, or a rollup slow enough to time out — it is asked once more
    without the rollup, so ``pr=`` reads as it did before checks were asked
    for, and ``checks`` is ``unknown`` with the first call's reason. A `gh`
    that is missing or cannot start is not asked twice.
    """
    def ask(fields: str) -> Tuple[Optional[str], Optional[str]]:
        return _gh(repo_root, ["pr", "list", "--head", branch, "--state", "all",
                               "--json", fields, "--limit", "20"])

    out, why = ask("number,state,isDraft,statusCheckRollup")
    rollup_why: Optional[str] = None
    if (out is None and why is not None
            and not why.startswith(("gh is not on PATH", "gh could not start",
                                    "[tools] gh", LOCAL_CONFIG.as_posix()))):
        rollup_why = why
        out, why = ask("number,state,isDraft")
    if out is None:
        return None, why
    try:
        found = []
        for p in json.loads(out or "[]"):
            state = _PR_STATES[str(p["state"]).upper()]
            if state == "open" and p.get("isDraft") is True:
                state = "draft"
            found.append((int(p["number"]), state, p.get("statusCheckRollup")))
    except (ValueError, KeyError, TypeError, AttributeError):
        return None, "gh answered in a shape status cannot read"
    if not found:
        return None, None
    rank = {"open": 2, "draft": 1}
    number, state, rollup = max(found, key=lambda f: (rank.get(f[1], 0), f[0]))
    if rollup_why is not None:
        return BranchPr(number, state, "unknown", [],
                        f"the forge answered without checks ({rollup_why})"), None
    checks, failing, checks_why = checks_state(rollup)
    running = tuple(running_checks(rollup)) if checks == "failure" else ()
    return BranchPr(number, state, checks, failing, checks_why, running), None


#: A check run's ``status`` before it completes, and a commit status's
#: ``state`` while it waits: the check has not answered yet.
_CHECK_PENDING = frozenset({"QUEUED", "IN_PROGRESS", "WAITING", "PENDING",
                            "REQUESTED", "EXPECTED"})
#: A completed check run's ``conclusion``, or a commit status's ``state``,
#: that fails the commit. Cancelled, timed out and stale are not green.
_CHECK_FAILED = frozenset({"FAILURE", "ERROR", "TIMED_OUT", "CANCELLED",
                           "ACTION_REQUIRED", "STARTUP_FAILURE", "STALE"})
#: Neither passes nor fails the commit: a check that did not run.
_CHECK_IGNORED = frozenset({"NEUTRAL", "SKIPPED"})


def checks_state(rollup: object) -> Tuple[str, List[str], Optional[str]]:
    """A head commit's check rollup as ``(checks, failing, why)``.

    *rollup* is `gh`'s ``statusCheckRollup``: check runs (``status``, and
    ``conclusion`` once ``COMPLETED``) and commit statuses (``state``) mixed.
    Any failed check is ``failure``, naming each; else any still running is
    ``pending``; else any passed is ``success``; else ``none`` — no check
    at all, or only skipped and neutral ones. A value it cannot read is
    ``unknown``, with the reason, never a guess.
    """
    if rollup is None:
        return "none", [], None
    if not isinstance(rollup, list):
        return "unknown", [], "gh answered checks in a shape status cannot read"
    failing: List[str] = []
    pending = passed = False
    for c in rollup:
        if not isinstance(c, dict):
            return "unknown", [], "gh answered checks in a shape status cannot read"
        name = str(c.get("name") or c.get("context") or "?")
        if "state" in c and "status" not in c:
            value = str(c.get("state") or "").upper()
        else:
            status = str(c.get("status") or "").upper()
            value = (str(c.get("conclusion") or "").upper()
                     if status == "COMPLETED" else status)
        if value in _CHECK_FAILED:
            if name not in failing:     # a matrix repeats a job's name
                failing.append(name)
        elif value in _CHECK_PENDING:
            pending = True
        elif value == "SUCCESS":
            passed = True
        elif value not in _CHECK_IGNORED:
            return "unknown", [], (f"check {name} reads {value or 'nothing'}, "
                                   f"which status cannot read")
    if failing:
        return "failure", failing, None
    if pending:
        return "pending", [], None
    return ("success" if passed else "none"), [], None


def running_checks(rollup: object) -> List[str]:
    """The checks of *rollup* still running, each named once (issue #332).

    `checks_state` answers ``failure`` the moment one check fails, whatever
    is still running; this is what tells a caller that red is not settled
    yet — a leg still running may fail too, and its log cannot be read. A
    rollup `checks_state` cannot read has none.
    """
    out: List[str] = []
    for c in rollup if isinstance(rollup, list) else []:
        if not isinstance(c, dict):
            return []
        name = str(c.get("name") or c.get("context") or "?")
        if "state" in c and "status" not in c:
            value = str(c.get("state") or "").upper()
        else:
            status = str(c.get("status") or "").upper()
            value = (str(c.get("conclusion") or "").upper()
                     if status == "COMPLETED" else status)
        if value in _CHECK_PENDING and name not in out:
            out.append(name)
    return out


def _docs_rel(config: Dict[str, Dict[str, object]]) -> str:
    """docs_dir as a git pathspec — forward slashes on every platform."""
    return str(config["project"].get("docs_dir", "docs/aide")
               ).replace("\\", "/").strip("/")


def _branch_queue_files(repo_root: Path, config: Dict[str, Dict[str, object]],
                        ref: str, base: str, own: int) -> Dict[int, str]:
    """The queue files *ref* carries as its own: number -> path at *ref*.

    Its own number's file, and every queue file *ref* added over its merge
    base with *base* — a maintenance queue and the stage queue after it ride
    one branch, named by the lower (`/aide-run-roadmap`). A file tidied
    (modified) on the branch is the previous queue's, and is not one.
    """
    qrel = f"{_docs_rel(config)}/queue"
    added = git(["diff", "--name-only", "--diff-filter=A", f"{base}...{ref}",
                 "--", qrel], repo_root, check=False).stdout.split("\n")
    listed = git(["ls-tree", "--name-only", ref, f"{qrel}/"],
                 repo_root, check=False).stdout.split("\n")
    added_nums = {queue_number(Path(p.strip())) for p in added if p.strip()}
    out: Dict[int, str] = {}
    for p in (l.strip() for l in listed):
        n = queue_number(Path(p)) if p.endswith(".md") else None
        if n is not None and (n == own or n in added_nums) and n not in out:
            out[n] = p
    return out


def _branch_queue_items(repo_root: Path, config: Dict[str, Dict[str, object]],
                        ref: str, base: str, branch: str) -> Set[int]:
    """The items of every queue *branch* carries as its own, read at *ref*.

    Empty for a branch that is not a ``<prefix>queue-NNN`` branch, and for
    one whose queue files cannot be read.
    """
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    if not _is_stack_branch(branch, prefix):
        return set()
    own = int(branch[len(prefix) + len(_QUEUE_TOKEN):])
    items: Set[int] = set()
    for path in _branch_queue_files(repo_root, config, ref, base, own).values():
        shown = git(["show", f"{ref}:./{path}"], repo_root, check=False)
        if shown.returncode == 0:
            items.update(queue_item_numbers(shown.stdout))
    return items


def _queue_branch_ci(repo_root: Path, config: Dict[str, Dict[str, object]],
                     ref: str, base: str, branch: str) -> Tuple[bool, int]:
    """``(fixing, rounds)`` for *branch*'s own queues, read at *ref*.

    ``fixing``: is an item of them reopened and still open? That is a queue
    PR turned back to draft for a fix round (`aide progress reopen`), as
    opposed to one never marked ready (issue #330). ``rounds``: the CI fix
    rounds they have begun, as `ci_fix_rounds` counts them (issue #332).
    Read from the branch's own progress.md and queue files, so it answers for
    every branch of the stack, not only the one checked out. Anything
    unreadable answers ``(False, 0)``: the plain ``draft`` it leaves is the
    older reading.
    """
    items = _branch_queue_items(repo_root, config, ref, base, branch)
    if not items:
        return False, 0
    shown = git(["show", f"{ref}:./{_docs_rel(config)}/progress.md"],
                repo_root, check=False)
    if shown.returncode != 0:
        return False, 0
    lines = shown.stdout.splitlines()
    fixing = any(r.item in items and r.status in _OPEN_STATUSES
                 for r in reopened_items(lines))
    return fixing, ci_fix_rounds(lines, items)[0]


class StackBranch(NamedTuple):
    """One unmerged queue branch as `status` reports it (issue #303).

    Each field is one token of the ``stack N:`` line, spelled as printed:
    ``base`` the recorded base or ``?``; ``pr`` ``#N/open|draft|merged|closed``,
    ``#N/draft(fixing)``, ``none``, ``unknown`` (could not look) or ``-``
    (local mode, or no forge declared); ``checks``
    ``none|pending|success|failure|unknown``, or ``-`` with no PR to ask
    about and beside one under ``[git] ci = "none"`` (no CI declared, the
    one ``-`` beside a PR); ``lower`` ``current``, ``moved``,
    ``landed``, ``gone``, ``unknown`` or ``-`` (based on no queue branch);
    ``orphaned`` ``yes``, ``no``, ``unknown`` or ``-``. ``failing`` names
    each failed check and ``checks_why`` why checks are unknown; each is
    printed on a line of its own below the stack line, as is each of
    ``running``, a check still running beside a failed one. ``ci_rounds`` is the
    CI fix rounds its queues have begun, read for a draft or a failing PR
    only, and printed below them when above 0 (issue #332).
    """
    name: str
    base: str
    pr: str
    lower: str
    orphaned: str
    checks: str = "-"
    failing: Tuple[str, ...] = ()
    checks_why: Optional[str] = None
    ci_rounds: int = 0
    running: Tuple[str, ...] = ()


class StackFacts(NamedTuple):
    """The stack, bottom first, and the two facts `status` derives from it."""
    branches: List[StackBranch]
    cap: Optional[int]
    cap_problem: Optional[str]
    runnable: Tuple[str, str]           # (yes|no, why)
    awaiting_review: Tuple[str, str]    # (yes|no|unknown, why)
    could_not_look: Optional[str]       # gh's reason, where it could not answer


def queue_stack_facts(repo_root: Path, config: Dict[str, Dict[str, object]],
                      live_work: List[int]) -> StackFacts:
    """The stack of unmerged queue branches, and runnable / awaiting review.

    The stack is `_unmerged_queue_branches` — the set `queue start` counts
    against the cap — ordered bottom first by recorded base. The forge is
    asked about each branch's pull request only off `local` mode and where
    `[git] forge` declares one, its checks only where `[git] ci` does, and about
    a recorded lower that has left the stack without landing (``gone``), so a
    lower closed and then deleted still orphans what sits on it. A lower that
    git says landed is not orphaning, whatever its PR says: content is git's
    to judge, as `restack` judges it. *live_work* is the live queue's items
    still 📋 or 🚧 — the work a launch would start.
    """
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    mode = str(config["git"].get("mode", "auto-merge"))
    pushes = mode != "local"
    no_forge = declared_forge(config) == "none"
    # The forge is asked only where one is declared and the mode is not
    # offline; origin's branches are git's, read under any pushing mode.
    look = pushes and not no_forge
    no_ci = declared_ci(config) == "none"
    unmerged = _unmerged_queue_branches(repo_root, config)
    local = set(_local_branches(repo_root))
    remote = (set(_remote_branches(repo_root))
              if pushes and _has_origin(repo_root) else set())

    def newest(b: str) -> str:
        """Origin's tip where it is ahead of this checkout's, else the local one."""
        there = f"origin/{b}" if b in remote else None
        if b not in local:
            return there or b
        if there and _is_ancestor(repo_root, b, there):
            return there
        return b

    bases: Dict[str, Optional[str]] = {
        b: (_recorded_branch_base(repo_root, b) if b in local else None)
        for b in unmerged}

    def depth(b: str) -> int:
        d, x, seen = 0, bases.get(b), {b}
        while x in unmerged and x not in seen:
            seen.add(x)
            d += 1
            x = bases.get(x)
        return d

    order = sorted(unmerged, key=lambda b: (depth(b), b))

    def lower_state(b: str) -> str:
        base = bases.get(b)
        if base is None:
            return "unknown"
        if not _is_stack_branch(base, prefix):
            return "-"
        if base in unmerged:
            return ("current" if _is_ancestor(repo_root, newest(base), newest(b))
                    else "moved")
        return "landed" if base in local or base in remote else "gone"

    lowers = {b: lower_state(b) for b in order}
    prs: Dict[str, str] = {}
    rounds: Dict[str, int] = {}
    facts: Dict[str, BranchPr] = {}
    why_not: Optional[str] = None
    if look:
        asked = order + sorted({str(bases[b]) for b in order
                                if lowers[b] == "gone"})
        for b in asked:
            if why_not is not None:
                prs[b] = "unknown"
                continue
            got, why_not = _branch_pr_facts(repo_root, b)
            if why_not is not None:
                prs[b] = "unknown"
            elif got is None:
                prs[b] = "none"
            else:
                if no_ci:               # no CI declared: no checks read (#355)
                    got = got._replace(checks="-", failing=[], running=())
                facts[b] = got
                prs[b] = got.label
                # A draft with reopened items still open is one a CI fix
                # round turned back, not one never marked ready (issue #330);
                # a draft or a red PR is where a runner reads how many fix
                # rounds have begun (issue #332). Asked of no other PR, so a
                # green or pending one costs no git spawn.
                if bases.get(b) and (got.state == "draft"
                                     or got.checks == "failure"):
                    fixing, rounds[b] = _queue_branch_ci(
                        repo_root, config, newest(b), str(bases[b]), b)
                    if got.state == "draft" and fixing:
                        prs[b] = f"{got.label}(fixing)"

    def orphaned(b: str) -> str:
        if not look:
            return "-"
        unsure = False
        x, seen = bases.get(b), {b}
        if x is None:
            return "unknown"
        while x and _is_stack_branch(x, prefix) and x not in seen:
            seen.add(x)
            if x not in unmerged and (x in local or x in remote):
                break                   # landed: git's verdict, not the PR's
            state = prs.get(x, "unknown")
            if state.endswith("/closed"):
                return "yes"
            if state == "unknown":
                unsure = True
            if x not in unmerged:
                break                   # gone: nothing below it to read
            if bases.get(x) is None:
                unsure = True
                break
            x = bases.get(x)
        return "unknown" if unsure else "no"

    def checks(b: str) -> Tuple[str, Tuple[str, ...], Optional[str]]:
        if not look or no_ci:           # no forge, or no CI declared (#355)
            return "-", (), None
        if b in facts:
            f = facts[b]
            return f.checks, tuple(f.failing), f.checks_why
        return ("unknown", (), why_not) if prs.get(b) == "unknown" else ("-", (), None)

    branches = [StackBranch(b, bases.get(b) or "?", prs.get(b, "-"),
                            lowers[b], orphaned(b), *checks(b),
                            rounds.get(b, 0),
                            tuple(facts[b].running) if b in facts else ())
                for b in order]
    cap, cap_problem = max_open_queues(config)

    closed = [s for s in branches if s.pr.endswith("/closed")]
    stranded = [s.name for s in branches if s.orphaned == "yes"]
    if closed or stranded:
        what = "; ".join(f"{s.name}'s PR {s.pr.split('/')[0]} was closed "
                         f"without merging" for s in closed)
        if stranded:
            what += ("; " if what else "") + (
                f"{', '.join(stranded)} "
                f"{'is' if len(stranded) == 1 else 'are'} orphaned")
        runnable = ("no", what)
    elif live_work:
        runnable = ("yes", f"the live queue has "
                    f"{_plural(len(live_work), 'item', 'items')} to build "
                    f"({', '.join(f'{n:03d}' for n in live_work)})")
    elif cap_problem:
        runnable = ("no", cap_problem)
    elif cap is not None and len(branches) < cap:
        runnable = ("yes", f"the stack holds {len(branches)} of [loop] "
                    f"max_open_queues {cap}, so another queue may start")
    else:
        runnable = ("no", f"the live queue has nothing to build and the stack "
                    f"is at [loop] max_open_queues {cap}")

    open_prs = [s for s in branches if s.pr.endswith("/open")]
    if not look:
        awaiting = ("no", "no forge is declared" if no_forge
                    else "local mode opens no pull requests")
    elif open_prs:
        awaiting = ("yes", ", ".join(f"{s.pr.split('/')[0]} ({s.name})"
                                     for s in open_prs))
    elif any(s.pr == "unknown" for s in branches):
        awaiting = ("unknown", f"could not look ({why_not})")
    elif any("/draft" in s.pr for s in branches):
        awaiting = ("no", "no queue PR is ready for review; "
                    + ", ".join(f"{s.pr.split('/')[0]} ({s.name})"
                                for s in branches if "/draft" in s.pr)
                    + " still a draft")
    elif branches:
        awaiting = ("no", "no queue branch's PR is open")
    else:
        awaiting = ("no", "no queue branch is unmerged")
    return StackFacts(branches, cap, cap_problem, runnable, awaiting, why_not)


def cmd_status(args: argparse.Namespace) -> int:
    """One-call roadmap-state report: branch + divergence, derived queue
    states, claim branches, and (best effort) open PRs — replacing the several
    manual git/gh round-trips a resuming orchestrator otherwise makes."""
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    mode = str(config["git"].get("mode", "auto-merge"))
    # Outside a repository the lines below read "branch: (unknown)" and
    # "tree: clean" — empty git output parsed as an answer (issue #352).
    if not _require_repository("status", repo_root):
        return 1

    if not args.no_fetch and mode != "local" and _has_origin(repo_root):
        git(["fetch", "--all", "--prune"], repo_root, check=False)

    branch = _current_branch(repo_root)
    # Report divergence from the base this branch actually has, not always from
    # main — on stacked work the interesting distance is to the queue branch.
    main = resolve_base(repo_root, config, args.base, branch)
    line = f"branch: {branch or '(unknown)'}"
    if mode != "local" and _has_origin(repo_root):
        counts = git(["rev-list", "--left-right", "--count", f"{main}...origin/{main}"],
                     repo_root, check=False).stdout.split()
        if len(counts) == 2:
            ahead, behind = counts
            line += f" · {main}: {ahead} ahead / {behind} behind origin/{main}"
    print(f"aide status — {repo_root.name}")
    print(f"  {line}")

    dirty = git(["status", "--porcelain"], repo_root, check=False).stdout.strip()
    print(f"  tree: {'dirty (' + str(len(dirty.splitlines())) + ' path(s))' if dirty else 'clean'}")

    ppath = docs_dir(repo_root, config) / "progress.md"
    plines = (ppath.read_text(encoding=_ENCODING).splitlines()
              if ppath.is_file() else [])
    item_status = _parse_item_status(plines)[2]
    # Open as `claim` reads it (`queue_is_open`, issue #393): a 📋 item of a
    # withdrawn stage is never offered, so it neither keeps a queue open nor
    # moves the live marker, and is named on its queue's line instead.
    withdrawn = withdrawn_stage_items(plines)
    qdir = docs_dir(repo_root, config) / "queue"
    live_seen = False
    live_work: List[int] = []
    if iter_queue_paths(qdir):
        for path in iter_queue_paths(qdir):
            nums = queue_item_numbers(path.read_text(encoding=_ENCODING))
            idle = [n for n in nums if n in withdrawn
                    and item_status.get(n, "planned") == "planned"]
            open_nums = [n for n in nums
                         if still_blocks(n, item_status, withdrawn)]
            aside = (("not offered, 📋 in a withdrawn stage: "
                      + ", ".join(f"{n:03d}" for n in idle)) if idle else "")
            if open_nums:
                tag = " (live)" if not live_seen else ""
                if not live_seen:
                    # 🔍 is open but not work: it waits on a person.
                    live_work = [n for n in open_nums
                                 if item_status.get(n, "planned")
                                 in ("planned", "in-progress")]
                live_seen = True
                listed = ", ".join(f"{n:03d}" for n in open_nums)
                print(f"  {path.name}: open{tag} — {len(open_nums)}/{len(nums)} items open ({listed})"
                      + (f"; {aside}" if aside else ""))
            else:
                print(f"  {path.name}: done" + (f" — {aside}" if aside else ""))
    else:
        print("  queues: none")

    # Outcome targets not yet ✅ Met — the goal-level state a summary table's
    # stage icons deliberately do not carry (conventions.md §1).
    ppath = docs_dir(repo_root, config) / "progress.md"
    if ppath.is_file():
        plines = ppath.read_text(encoding=_ENCODING).splitlines()
        gates = human_gates(plines)
        for n, (g, gid) in enumerate(zip(gates, gate_ids(gates)), start=1):
            if g.kind == "approved":
                continue
            reach = g.reach
            label = {"declined": "❌ declined", "awaiting": "⏳ awaiting a decision"}.get(
                g.kind, "⚠ unrecognised status")
            print(f"  gate {n}: {g.text}{f' ({gid})' if gid else ''} "
                  f"[blocks {reach}] — {label}")
        # Every table, not only gates: a row no reader can use is missing
        # from the lines above, and would otherwise be missing from here.
        for table, i, _, problem in _unreadable_rows(plines):
            held = (" — holding every item until it is fixed"
                    if table is _HUMAN_GATES else "")
            print(f"  unreadable: progress.md:{i + 1}: {table.name} row "
                  f"{problem}{held}")
        for t in outcome_targets(plines):
            if t.kind == "met":
                continue
            label = {"not-met": "❌ not met", "unverified": "❓ unverified"}.get(
                t.kind, "⚠ unrecognised status")
            objs = f" [{', '.join(t.objectives)}]" if t.objectives else ""
            print(f"  target: {t.text}{objs} — {label}")
        # Capabilities not yet ✅ Verified (issue #207). Profiles run only on
        # request, and only for a ❓ Unverified row: an expression is project
        # code that may import a GPU stack, and a row with any other Status —
        # `⏸️ Out of scope` — is not one to be told it can be verified now.
        profiles = {k: str(v) for k, v in (config.get("validation") or {}).items()}
        verdicts: Dict[str, Tuple[bool, str]] = {}
        for c in gated_capabilities(plines):
            if c.kind == "verified":
                continue
            label = "❓ unverified" if c.kind == "unverified" else "⚠ unrecognised status"
            for name in c.profiles:
                if name not in profiles:
                    label += f"; profile '{name}' is not defined in [validation]"
                    continue
                if not (args.profiles and c.kind == "unverified"):
                    label += f"; profile '{name}'"
                    continue
                if name not in verdicts:
                    verdicts[name] = evaluate_profile(repo_root, config, profiles[name])
                satisfied, detail = verdicts[name]
                label += (f"; profile '{name}' is satisfied here — the gated path "
                          f"can be run and the row verified" if satisfied
                          else f"; profile '{name}' is not satisfied here"
                          + (f" ({detail})" if detail else ""))
            stages = (f" [stage {', '.join(map(str, c.stages))}]"
                      if c.stages else "")
            print(f"  capability: {c.text}{stages} — {label}")
        for r in retracted_criteria(plines):
            again = ""
            if r.reaccepted:
                again = (f"; re-accepted on {r.reaccepted_on}"
                         if r.reaccepted_on else "; re-accepted since")
            print(f"  retracted: stage {r.stage} criterion {r.criterion} "
                  f"({r.date}) — {r.reason}{again}")
        for r in reopened_items(plines):
            again = ""
            if r.completed:
                again = (f"; completed again on {r.completed_on}"
                         if r.completed_on else "; completed again since")
            print(f"  reopened: item {r.item:03d} ({r.date}) — {r.reason}"
                  f"{again}")

    branches = _list_claim_branches(repo_root, prefix)
    # Guarded the way `run_checks` guards it: a git spawn is not worth
    # paying on every `status` in the common "claims: none" case, and the
    # windows leg spends ~13x on a spawn (issue #74).
    off_origin = (_branches_off_origin(repo_root, config, prefix)
                  if branches else {})

    def _gone_note(br: str) -> str:
        """The note for a branch origin had and deleted (issue #364), or ''."""
        why = off_origin.get(br)
        if why is None or why.kind == OFF_ORIGIN_UNPUBLISHED:
            return ""
        if why.kind == OFF_ORIGIN_GONE_LANDED:
            return (f" — deleted on origin, all of it already in {why.where} "
                    f"('{_gc_merged_hint(why.where, config)}' deletes it)")
        return (f" — deleted on origin, its work NOT FOUND in {why.where}: "
                f"check whether its work merged — this checkout may hold the "
                f"only copy")

    unpublished = {br for br, why in off_origin.items()
                   if why.kind == OFF_ORIGIN_UNPUBLISHED}
    withdrawn_items: Dict[int, str] = {}
    ppath = docs_dir(repo_root, config) / "progress.md"
    if branches and ppath.is_file():
        withdrawn_items = spent_by_withdrawal(
            ppath.read_text(encoding=_ENCODING).splitlines(), item_status)
    if branches:
        for br in branches:
            num = _branch_item_number(br, prefix)
            if num is None:
                kind = "queue branch" if _is_queue_branch(br, prefix) else "unrecognised"
                extra = (" — NOT on origin" if br in unpublished
                         else _gone_note(br))
                print(f"  branch: {br} ({kind} — not an item claim){extra}")
                continue
            st = item_status.get(num, "planned")
            note = ""
            if st == "complete":
                note = " — STALE (item ✅; run 'aide gc')"
            elif num in withdrawn_items:
                note = f" — STALE (item {withdrawn_items[num]}; run 'aide gc')"
            elif st == "in-review":
                # Recommending `gc` here would be recommending the deletion of
                # an open PR's head branch. It is awaiting a human, not stale.
                note = " — awaiting review (merge the PR, then 'aide progress "
                note += f"set {num:03d} done')"
            # Composes with the status note rather than replacing it: a branch
            # can be both stale and unpublished, and a reader needs both.
            if br in unpublished:
                note += (f" — NOT on origin: the claim's push did not land, so "
                         f"no other checkout can see this claim "
                         f"('git push -u origin {br}' to publish it)")
            note += _gone_note(br)
            print(f"  claim: {br} (item {num:03d}: {st}){note}")
    else:
        print("  claims: none")

    for line in _landed_review_items(repo_root, config, prefix, args.base):
        print("  " + line.replace("aide sync: ", ""))

    # The stack and the two facts read from it (issue #303) — one token per
    # field, so a program reads them and `/aide-run-roadmap` points at them.
    facts = queue_stack_facts(repo_root, config, live_work)
    print(f"  stack: {len(facts.branches)}/"
          f"{facts.cap if facts.cap is not None else '?'}"
          + (" — bottom first" if facts.branches else ""))
    for n, sb in enumerate(facts.branches, start=1):
        print(f"  stack {n}: {sb.name} base={sb.base} pr={sb.pr} "
              f"checks={sb.checks} lower={sb.lower} orphaned={sb.orphaned}")
        for name in sb.failing:
            print(f"    failing check: {name}")
        for name in sb.running:
            print(f"    pending check: {name}")
        if sb.checks == "unknown" and sb.checks_why:
            print(f"    checks unknown: {sb.checks_why}")
        if sb.ci_rounds:
            print(f"    ci fix rounds: {sb.ci_rounds}")
    print(f"  runnable: {facts.runnable[0]} — {facts.runnable[1]}")
    print(f"  awaiting review: {facts.awaiting_review[0]} — "
          f"{facts.awaiting_review[1]}")

    # Every open PR, best effort — and "could not look" said, never silence.
    # Not asked at all in `local` mode, which makes no network call (§4).
    if mode == "local":
        print("  open PRs: - (local mode)")
        return 0
    if declared_forge(config) == "none":
        print("  open PRs: - (no forge declared)")
        return 0
    if facts.could_not_look is not None:
        out, why = None, facts.could_not_look
    else:
        out, why = _gh(repo_root, ["pr", "list", "--state", "open"])
    if out is None:
        print(f"  open PRs: unknown — could not look ({why})")
    elif out.strip():
        print("  open PRs:")
        for l in out.strip().splitlines():
            print(f"    {l}")
    else:
        print("  open PRs: none")
    return 0


def _merged_prefixed_branches(repo_root: Path, main: str, prefix: str) -> List[str]:
    """Prefixed local branches already merged into *main*, per git itself.

    Ancestry-based, so it misses **every** squash merge — which is the shape
    GitHub's "Squash and merge" produces. `_branch_content_landed` is the
    stronger oracle and is preferred wherever git is new enough; this remains
    the fallback on git < 2.38, where being conservative means deleting *less*.
    """
    out = git(["branch", "--merged", main, "--format=%(refname:short)"],
              repo_root, check=False).stdout
    return [l.strip() for l in out.splitlines() if l.strip().startswith(prefix)]


#: `git merge-tree --write-tree` landed in git 2.38 (Oct 2022). As of Aug 2026
#: the only realistic holdout is Ubuntu 22.04 LTS (git 2.34.1, in standard
#: support until April 2027); 24.04, Debian 12, Git for Windows, macOS CLT and
#: this repo's CI are all past it. There is deliberately **no fallback oracle**:
#: on older git `gc` refuses to delete on the ✅ ground rather than degrading to
#: a weaker test, so old git is always *more* conservative and there is one
#: oracle to keep honest rather than two.
_MERGE_TREE_MIN_GIT = (2, 38)


def _git_version(repo_root: Path) -> Optional[Tuple[int, int]]:
    """(major, minor) of the git on PATH, or None when it cannot be read."""
    out = git(["--version"], repo_root, check=False).stdout
    m = re.search(r"(\d+)\.(\d+)", out)
    return (int(m.group(1)), int(m.group(2))) if m else None


def _has_merge_tree(repo_root: Path) -> bool:
    version = _git_version(repo_root)
    return version is not None and version >= _MERGE_TREE_MIN_GIT


def _branch_content_landed(repo_root: Path, base: str,
                           branch_ref: str) -> Optional[bool]:
    """True when merging *branch_ref* into *base* would change *base* not at all.

    The question `gc` actually needs answered before force-deleting: is this
    branch's work already in the base? `git branch --merged` answers a *different*
    question (is the tip an ancestor) and so misses every squash merge, which is
    why `gc` reaches for `-D` in the first place. `git cherry` gets a
    single-commit squash right and a multi-commit squash wrong — a false alarm on
    the exact shape "Squash and merge" produces. Measured against fixtures of all
    three shapes:

    ======================  ===============  ============  =================
    branch                  branch --merged  git cherry    merge-tree
    ======================  ===============  ============  =================
    1 commit, squashed      misses           correct       no-op
    2 commits, squashed     misses           false alarm   no-op
    genuinely unmerged      correct          correct       would change base
    ======================  ===============  ============  =================

    Comparing the merged tree to the base's own tree also stays correct after the
    base advances with unrelated work, since that work is in both sides.

    Returns None when the answer cannot be established (unreadable ref, git too
    old, unexpected output) — a caller must treat that as "do not delete", never
    as "landed".
    """
    if not _has_merge_tree(repo_root):
        return None
    # Resolve first, so an unreadable ref is reported as unmeasurable rather than
    # as content: `merge-tree` exits 1 for a bad ref exactly as it does for a
    # conflict, and mapping both to False made `gc` skip for the right reason but
    # state the wrong one — "has content not in main" about a ref it never read.
    if not _ref_exists(repo_root, branch_ref):
        return None
    res = git(["merge-tree", "--write-tree", base, branch_ref], repo_root, check=False)
    if res.returncode == 1:
        return False  # conflicts: the branch certainly carries content the base lacks
    if res.returncode != 0:
        return None
    merged = res.stdout.strip().splitlines()
    base_tree = git(["rev-parse", f"{base}^{{tree}}"], repo_root, check=False).stdout.strip()
    if not merged or not base_tree:
        return None
    return merged[0].strip() == base_tree


def _checked_out_branches(repo_root: Path) -> set:
    """Branch names `gc` must never delete because a checkout is sitting on them.

    Three ways that happens, and the guard has to cover all three or the preview
    promises a delete `--yes` cannot perform:

    - **This worktree, on a branch.** The original case.
    - **This worktree, detached.** `git rev-parse --abbrev-ref HEAD` returns the
      literal string `HEAD`, and no branch is ever equal to that — so the guard
      silently protected nothing. Detached, the thing to protect is every branch
      at the checked-out commit.
    - **Another worktree.** `git branch -D` refuses these (git's own check), so
      without asking `git worktree list` the preview lists a branch the delete
      then bounces off.
    """
    protected = set()
    # `worktree list --porcelain` names the branch of every attached worktree —
    # including this one when it is not detached — as `branch refs/heads/<name>`.
    out = git(["worktree", "list", "--porcelain"], repo_root, check=False).stdout
    for line in out.splitlines():
        if line.startswith("branch refs/heads/"):
            protected.add(line[len("branch refs/heads/"):].strip())

    name = _current_branch(repo_root)
    if name and name != "HEAD":
        protected.add(name)
        return protected
    head = git(["rev-parse", "HEAD"], repo_root, check=False).stdout.strip()
    if not head:
        return protected
    points_at = git(["branch", "--points-at", head, "--format=%(refname:short)"],
                    repo_root, check=False).stdout
    protected.update(l.strip() for l in points_at.splitlines() if l.strip())
    return protected


def _plural(n: int, one: str, many: str) -> str:
    return f"{n} {one}" if n == 1 else f"{n} {many}"


def _gc_empty_notes(repo_root: Path, prefix: str, main: str,
                    merged_flag: bool, local: List[str],
                    remote: List[str]) -> List[str]:
    """Why an empty ``gc`` result may still leave cleanup available.

    Two things the bare message hides. First, the default invocation checks
    only the item ground, so a branch that no longer resolves to an item —
    every queue and specs-queue branch — is structurally invisible to it while
    ``--merged`` would take it. Second, `gc` only ever looks at branches under
    ``prefix``, so a merged branch named anything else is never considered on
    either ground.

    Returns [] when there is genuinely nothing further to say, so the common
    case stays a single terse line. The ``--merged`` probe runs only on this
    empty path, never in the normal one.
    """
    notes: List[str] = []
    if not merged_flag and (local or remote):
        main_branch = str(load_config(repo_root)["git"].get("main_branch", "main"))
        extra = [b for b in _merged_prefixed_branches(repo_root, main, prefix)
                 if _gc_merged_ground_skip(b, main, main_branch, prefix) is None]
        if extra:
            notes.append(
                f"{_plural(len(extra), 'branch', 'branches')} under '{prefix}' "
                f"{'is' if len(extra) == 1 else 'are'} merged into {main} — "
                f"'aide gc --merged' will take {'it' if len(extra) == 1 else 'them'}")
    others = [b for b in _local_branches(repo_root)
              if not b.startswith(prefix) and b != main]
    if others:
        notes.append(
            f"{_plural(len(others), 'local branch', 'local branches')} outside "
            f"the '{prefix}' scope {'was' if len(others) == 1 else 'were'} not "
            f"considered — gc only ever manages claim branches")
    return notes


def _gc_merged_ground_skip(branch: str, base: str, main_branch: str,
                           prefix: str) -> Optional[str]:
    """Why *branch* is not a target on the ``--merged`` ground under *base*,
    or None when it may be one (issue #403).

    Two branches are never collected there, however git answers. The base
    itself, which every ancestry and content test calls merged into itself.
    And a queue branch under a base other than `main_branch`: on a stack of
    queue branches each one below the base is an ancestor of it, so it reads
    as merged — into its successor, not into `main_branch` — while its own PR,
    still unreviewed, is its route there. Deleting it on origin closes that
    PR. A claim branch merged into a queue base is a different shape: it
    landed where it was meant to land, and the queue branch's PR carries its
    work, so it stays a target.
    """
    if base in (branch, f"origin/{branch}"):
        return "it is the base"
    if (_is_queue_branch(branch, prefix)
            and base not in (main_branch, f"origin/{main_branch}")):
        return (f"a queue branch merged into {base}, not into {main_branch} "
                f"— its own PR is still its route to {main_branch}; gc "
                f"takes it once {main_branch} holds its work")
    return None


def _gc_ref(branch: str, local: List[str]) -> str:
    """The ref to measure *branch* by: the local branch, else its remote copy."""
    return branch if branch in local else f"origin/{branch}"


def cmd_gc(args: argparse.Namespace) -> int:
    """Delete claim branches whose work has landed (item ✅ in progress.md —
    or ❌, dropped or withdrawn with its stage — or ``--merged`` branches
    already merged into the base, a queue branch only when that base is
    main_branch). Dry-run by default; pass
    ``--yes`` to delete. The one verb that deletes work, so it is never
    implicit: `queue discard` deletes a branch only where it carries none."""
    repo_root = find_repo_root(args.repo)
    config = load_config(repo_root)
    if not _require_repository("gc", repo_root):
        return 1
    prefix = str(config["git"].get("branch_prefix", "aide/"))
    mode = str(config["git"].get("mode", "auto-merge"))
    # The `--merged` ground is "already merged into <base>", so it takes a base
    # like everything else: on stacked work the branches that have landed have
    # landed into the queue branch, and asking about `main` finds none of them.
    main = resolve_base(repo_root, config, args.base)
    main_branch = str(config["git"].get("main_branch", "main"))

    if mode != "local" and _has_origin(repo_root):
        git(["fetch", "--all", "--prune"], repo_root, check=False)

    progress_path = docs_dir(repo_root, config) / "progress.md"
    item_status: Dict[int, str] = {}
    withdrawn_items: Dict[int, str] = {}
    if progress_path.is_file():
        plines = progress_path.read_text(encoding=_ENCODING).splitlines()
        _, _, item_status = _parse_item_status(plines)
        withdrawn_items = spent_by_withdrawal(plines, item_status)

    local = [b for b in _local_branches(repo_root) if b.startswith(prefix)]
    remote = [b for b in _remote_branches(repo_root) if b.startswith(prefix)]

    # The content oracle is what makes `-D` on the ✅ ground safe; without it
    # that ground refuses outright (see `_MERGE_TREE_MIN_GIT`).
    can_measure = _has_merge_tree(repo_root)

    merged_local: List[str] = []
    if args.merged:
        merged_local = _merged_prefixed_branches(repo_root, main, prefix)

    targets: Dict[str, str] = {}  # branch -> reason
    skips: Dict[str, str] = {}    # branch -> why it is NOT acted on
    protected = _checked_out_branches(repo_root)
    for br in sorted(set(local) | set(remote)):
        # Only a positively-identified item claim is deletable on the "item is
        # ✅" ground. A queue branch shares the number namespace but not the
        # lifecycle: it aggregates many items and lands as one reviewed PR, so
        # deleting it because some same-numbered item finished would discard
        # unreviewed work. It stays eligible under --merged only while the
        # base is main_branch: under a queue base, every queue branch below it
        # on the stack reads as merged into it, and is not in main (#403).
        num = _branch_item_number(br, prefix)
        # A ❌ item's branch — dropped, or withdrawn with its stage — is on
        # the item ground too (issue #387): `merge` refuses it, so nothing
        # else ever collects it. Same oracle, so a ❌ branch carrying work
        # is skipped exactly as a ✅ one is, and `--abandon` is its route.
        if num is not None and (item_status.get(num) == "complete"
                                or num in withdrawn_items):
            reason = (f"item {num:03d} is ✅" if num not in withdrawn_items
                      else f"item {num:03d} is {withdrawn_items[num]}")
            # `progress.md` is a document, edited by agents and humans; git is
            # the authority on whether the commits landed, and until 1.20.0 it
            # was never asked. A ✅ can outrun the merge easily — a commit added
            # after the validator marked it done, a hand-edit, the `pr`-mode
            # window — and the action here is `git branch -D` plus a remote
            # delete, where the remote half is unrecoverable on a plain git host.
            if args.abandon:
                targets[br] = reason + "; --abandon"
            elif not can_measure:
                skips[br] = (f"{reason}, but this git cannot verify the work "
                             f"landed (needs "
                             f"{_MERGE_TREE_MIN_GIT[0]}.{_MERGE_TREE_MIN_GIT[1]}+ "
                             f"for 'merge-tree --write-tree'); use --merged or "
                             f"--abandon")
            else:
                landed = _branch_content_landed(repo_root, main, _gc_ref(br, local))
                if landed is True:
                    targets[br] = reason
                elif landed is False:
                    skips[br] = (f"{reason} but the branch has content not in "
                                 f"{main}; re-check it, or pass --abandon to "
                                 f"delete it anyway")
                else:
                    # Not the same statement, and this is the one verb that
                    # deletes work: say the measurement failed, not that the branch
                    # carries work it may not carry.
                    skips[br] = (f"{reason}, but whether its work is in {main} "
                                 f"could not be determined (ref "
                                 f"'{_gc_ref(br, local)}' unreadable); not "
                                 f"deleting — pass --abandon to delete anyway")
        elif args.merged:
            if br in merged_local:
                ground = f"merged into {main}"
            elif (can_measure and _branch_content_landed(
                    repo_root, main, _gc_ref(br, local)) is True):
                # `--merged` is built on `git branch --merged`, which is
                # ancestry-based and so misses every squash merge — the very
                # shape `-D` was reached for. The same oracle that guards the
                # ✅ ground closes that.
                ground = f"content already in {main}"
            else:
                continue
            # Asked only once git has said the branch is merged, so a branch
            # the ground would not take anyway is never reported as skipped.
            why = _gc_merged_ground_skip(br, main, main_branch, prefix)
            if why is None:
                targets[br] = ground
            elif main not in (br, f"origin/{br}"):
                skips[br] = why

    if not targets and not skips:
        # "Nothing to clean" is a claim about the ground and the scope this run
        # actually checked, not about the repository — say which. The default
        # invocation checks only the item ground, and every invocation ignores
        # branches outside `prefix` (deliberately: gc is the one verb that
        # deletes work and must not delete branches it does not own). Left unqualified,
        # the message reads as "no cleanup is available here" and the next
        # reach is the raw `git branch -d` the CLI exists to replace.
        print("aide gc: nothing to clean")
        for note in _gc_empty_notes(repo_root, prefix, main, args.merged, local, remote):
            print(f"  {note}")
        return 0

    # Every skip is decided BEFORE anything is printed, so the preview is the
    # set `--yes` acts on rather than a promise it then quietly narrows. A dry
    # run that overstates trains the reader to skim it, and this is the one
    # verb that deletes work — the list a human is asked to approve must be exact.
    for br in [b for b in targets if b in protected]:
        del targets[br]
        skips[br] = ("checked out (here or in another worktree) — git refuses to "
                     "delete a branch a checkout is sitting on")

    def _where(br: str) -> str:
        return ("local+remote" if br in local and br in remote
                else "local" if br in local else "remote")

    for br in sorted(skips):
        print(f"skipping {br} ({_where(br)}): {skips[br]}")
    for br, reason in targets.items():
        if not args.yes:
            print(f"would delete {br} ({_where(br)}; {reason})")
            continue
        failures: List[str] = []
        if br in local:
            # -D: a ✅/merged item's branch may have landed via squash/PR, so
            # git's ancestry-based -d safety check can refuse a branch whose
            # work is in fact on main. Safe here only because the content check
            # above already asked git whether the work landed.
            res = git(["branch", "-D", br], repo_root, check=False)
            if res.returncode != 0:
                failures.append(f"local ({(res.stderr or '').strip()})")
        if br in remote and mode != "local":
            res = git(["push", "origin", "--delete", br], repo_root, check=False)
            if res.returncode != 0:
                failures.append(f"remote ({(res.stderr or '').strip()})")
        # Report what git did, not what was asked of it. `-D` still refuses a
        # branch checked out in ANOTHER worktree, which `_checked_out_branches`
        # cannot see from here — and printing "deleted" over a refusal makes the
        # report the very thing this verb was just fixed to stop being: a claim
        # that does not match what happened.
        if failures:
            print(f"could NOT delete {br} ({_where(br)}; {reason}): "
                  f"{'; '.join(failures)}", file=sys.stderr)
        else:
            print(f"deleted {br} ({_where(br)}; {reason})")
    if not targets:
        print("aide gc: nothing to delete")
    if not args.yes and targets:
        print("aide gc: dry run — re-run with --yes to delete")
    return 0


# --------------------------------------------------------------------------- #
# CLI
# --------------------------------------------------------------------------- #
def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="aide", description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--repo", type=Path, default=None, help="repo root (default: search up for aide.toml)")
    sub = parser.add_subparsers(dest="command", required=True)

    p_check = sub.add_parser(
        "check", help="consistency gate over docs/aide, "
        "plus the test-hygiene lints over tests_dir, which "
        "run with a notice even in a repo with no docs_dir "
        "(writes only a missing insights.md, from the "
        "template, and the file --report names)",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "Without --queue, where aide.toml is there, the check also "
            "ERRORS on each requirement of its configuration this machine "
            "lacks that is decided offline: git, the repository, a remote "
            "named origin under a [git] mode other than local, and the test "
            "command's program, each prefixed `this machine:` and worded as "
            "`aide env` words it. Such an error is the machine's, for a "
            "person to meet, not a document to edit. A --queue run judges "
            "documents only. gh's login, the interpreter and the venv are "
            "reported by `aide env` alone.\n"
            "\n"
            "--queue NNN checks one queue's specs against each other: two items "
            "claiming one path under May change (warning), one item changing a "
            "path another pins under Asserts against (error), a dependency "
            "cycle, and a dependency on an item that exists nowhere.\n"
            "\n"
            "Three discounts apply. Spent items (\u2705 merged or \u274c excluded in "
            "progress.md) are discounted on both sides of every comparison, and "
            "a finding against one is an error no later item can clear. A "
            "declared dependency is discounted in one direction: when the "
            "pinning item names the changing one under ## Dependencies, "
            "directly or through a chain of items on the same queue, the edit "
            "landing cannot break its pin. Only links that still order count: a "
            "dependency claim no longer waits for (\u2705, \u274c, \u23f8\ufe0f) earns no "
            "exemption, and neither does a chain whose middle item no longer "
            "blocks. The cycle check keeps only items whose status still blocks "
            "a claim; deferred items stay in the path comparisons.\n"
            "\n"
            "--queue NNN also warns on whether the queue needs a queue-end "
            "item. The queue closes stage N when an item it lists is "
            "referenced by a stage N deliverable not \u23f8\ufe0f and every stage N "
            "deliverable that is \U0001f4cb, \U0001f6a7 or \U0001f50d "
            "names only items listed on this queue or an earlier one. Such a "
            "bullet with no item reference keeps the stage open; \u2705, "
            "\u274c and \u23f8\ufe0f bullets never do. A stage it closes "
            "needs one when it has an "
            "unticked acceptance box no item spec's Acceptance Criteria "
            "annotate as `closes Stage N criterion M`, a \u2753 Unverified "
            "capability row whose Introduced by cell names it, or an item "
            "the stage's own deliverables reference, whatever its status "
            "but \u274c or \u23f8\ufe0f, whose spec has an Environment / Hardware "
            "Dependencies section and which no capability row covers \u2014 "
            "a row whose Introduced by cell references the item covers it, "
            "whatever stage the cell names, and each row naming the stage and "
            "no item covers one more, lowest item number first. A queue-end "
            "item is one titled "
            "`Validate stage N`, and neither its own spec nor an excluded "
            "item's annotates anything here. The check warns when a stage "
            "with a need has no queue-end item for it among the queue's "
            "final items or still open anywhere on it, naming each reason; "
            "when an open queue-end item is listed ahead of an open item "
            "that is not one, which `aide claim` holds it behind; and when "
            "a queue-end item not "
            "\u2705, \u274c or \u23f8\ufe0f names no stage, a stage the "
            "queue does not close, or one with no need, unless `aide "
            "progress reopen` sent it back and it is still open: it was "
            "needed once, and is back for a fix. A queue whose items "
            "are all \u2705, \u274c or \u23f8\ufe0f gets none of them.\n"
            "\n"
            "Over progress.md's tables, ERRORS: a missing stage summary "
            "table, objective coverage table or stage section; a stage "
            "summary row marked \u2705 over a stage whose deliverables do not "
            "roll up to \u2705 (`aide progress -h` states the rollup), and a "
            "stage header or Objective row so marked over a rollup that is "
            "not \u2705 \u2014 an Objective row's rollup being the same "
            "rule over the rollups of the stages its Delivered by cell "
            "names, less any whose summary row is \u274c, and \u274c where "
            "every stage it names has such a row; an "
            "objective marked \u2705 over an "
            "Outcome target that is \u274c Not met \u2014 the goal-level "
            "mirror of that over-claim; and a row of the stage summary, "
            "objective coverage, Outcome targets or Human gates table that "
            "its reader cannot use \u2014 the wrong cell count (a '|' inside "
            "a cell, usually), a Stage cell that is not an integer, an "
            "objective coverage row not starting G<n>, an empty Target cell, "
            "a summary or objective Status cell with no "
            "icon \u2014 since the row is dropped from every check it would "
            "have fed. Each table is read under its template heading, or, "
            "for a summary or objective table without one, wherever its rows "
            "are found. Warnings, and a warning never moves the exit "
            "code \u2014 only an error does: any other stage header, "
            "summary row or Objective row whose status is not its rollup, "
            "compared in full \u2014 a cell `aide progress set` would leave "
            "as it reads, one it never downgrades or a \u23f8\ufe0f set by "
            "hand, is named all the same, and an Objective row whose Outcome "
            "target is not \u2705 Met is compared with \U0001f6a7 where its "
            "stages roll up to \u2705; a stage whose deliverables roll "
            "up to \u2705 under a summary row that is not; a stage header "
            "disagreeing with its summary row, where neither was named "
            "against the rollup; an Objective row whose Delivered by "
            "cell names no stage with a section; a summary row with no stage "
            "section, an objective marked \u2705 over a target not yet \u2705 "
            "Met, an Outcome target or human gate whose Status is not one of "
            "its table's marks, and every human gate still blocking \u2014 a "
            "normal state rather than a defect \u2014 save a \u274c declined "
            "gate whose reach holds nothing open: a Blocks cell left empty "
            "(\u2014), or items and stages all \u2705 or \u274c, a "
            "\U0001f4cb item every bullet of which sits in a withdrawn "
            "stage counting as \u274c; never `all` or `stage N+`. A "
            "summary row marked "
            "\u274c is left out of every stage comparison "
            "above, deliverables and header alike: the stage is "
            "dropped, so its bullets no longer speak for it; a header or "
            "Objective row marked \u274c is not compared with its rollup "
            "either. A summary row "
            "or header marked \u23f8\ufe0f over deliverables that do not "
            "roll up to \u23f8\ufe0f is a warning, and so is a stage whose "
            "deliverables roll up to \u23f8\ufe0f under a summary row or "
            "header that is not. Each cell is named once: a \u2705 cell "
            "over a rollup that is not \u2705 is its error alone, a "
            "stage's other off cells share one warning, and an Objective "
            "row named against its rollup is not compared with its Outcome "
            "targets.\n"
            "\n"
            "Over the Environment-Gated Capability Verification table, "
            "warnings only, since no other check gates on it: a row its "
            "reader cannot use (the wrong cell count, or an empty Capability "
            "cell); a Status that is neither \u2705 Verified nor \u2753 "
            "Unverified; a profile named in the Package / Tool cell that "
            "[validation] does not define; and a row still \u2753 Unverified "
            "with an empty or dash-only Notes cell whose introducing stage "
            "\u2014 the first `Stage N` run in its Introduced by cell \u2014 "
            "is \u2705 in the stage summary.\n"
            "\n"
            "Among the other lints over docs/aide, these are warnings: a "
            "file under items/ not named NNN-<slug>.md, which `aide scope`, "
            "`aide claim` and `aide check --queue` never find, reported in "
            "place of every other spec lint; an Authorised paths bullet whose "
            "second backtick span or continuation line is silently dropped, "
            "named span by span; one path listed under both May change and "
            "Asserts against, or an Asserts-against glob covering a "
            "May-change path (one direction only \u2014 a literal pin under "
            "a May-change glob is the legitimate carve-out, left for "
            "`aide scope` to judge); an always-authorised path pinned "
            "under Asserts against; a marked assumption pinning an engine "
            "whose feature line predates the installed one, in a spec that "
            "is not a record; a roadmap.md "
            "stage whose Dependencies name a later-numbered stage in the "
            "blocking slot \u2014 the text up to its first semicolon, "
            "spaced dash, sentence end, 'independent of' or 'queue "
            "before', where a stage number is one "
            "after the word Stage or Stages, or a slot of bare numbers "
            "\u2014 unless progress.md shows that stage \u23f8\ufe0f on "
            "its header or summary row; a roadmap.md stage under way \u2014 "
            "its deliverables rolling up to \U0001f6a7, or a \U0001f4cb "
            "item of it listed in an open queue \u2014 while an earlier "
            "stage its blocking slot names is \u23f8\ufe0f on its header or "
            "summary row, or withdrawn by a \u274c summary row, where a "
            "stage itself \u23f8\ufe0f or withdrawn is never under way; a "
            "progress.md stage section with no "
            "Stage summary row, \u23f8\ufe0f and \u274c stages included, "
            "where a row the reader cannot use still counts for the stage "
            "its Stage cell names; a vision.md G-code with no row in "
            "roadmap.md's coverage table, whose rows are read by the G-codes "
            "opening their first cell, past one leading parenthetical; a "
            "stage a roadmap.md coverage row names with no '## Stage N' "
            "section in roadmap.md, the Delivered by cell read as the "
            "Dependencies slot is, by number after the word Stage or Stages "
            "or from a cell of bare numbers; every "
            "retracted acceptance criterion and every reopened item, a "
            "normal state rather than a defect, each reported once, by its "
            "latest retraction or reopening, and never as open once the box "
            "is ticked or the item \u2705 again \u2014 then as re-accepted "
            "or completed again, with the newest trail date since when there "
            "is one; and an insights entry whose shape is off \u2014 loose "
            "either side of the date, strict about the date, and never "
            "applied to an archived entry; a ledger row no reader can "
            "use \u2014 the wrong cell count, an Item cell that is not an "
            "item number, an Outcome that is neither merged nor abandoned, "
            "or a count cell that is neither an integer nor "
            "blank \u2014 reported only where ledger.md exists, since a "
            "check never creates it; and a document whose aide-template "
            "line above its title records a version other than the installed template's, "
            "names a template this engine does not ship, or cannot be read "
            "\u2014 read on vision.md, roadmap.md, progress.md, "
            "insights.md and ledger.md, on a queue while it is open and on an "
            "item spec "
            "until its item is \u2705 or \u274c, and never on a document with "
            "no such line. A claim branch is reported stale when its item "
            "is \u2705, or \u274c by its own bullets, or \U0001f4cb with "
            "every bullet in a stage whose summary row is \u274c; a "
            "\U0001f6a7 or \u23f8\ufe0f item in such a stage is not, until "
            "it is dropped. A "
            "\U0001f50d item's claim branch is not reported stale.\n"
            "\n"
            "Over insight citations in docs/aide and tests_dir, the inbox and "
            "its archives excepted: an insight ID written after the word "
            "insight, or after entry on a line that says insight or inbox, "
            "that resolves to no entry in insights.md or "
            "insights/archive-*.md is an ERROR; one that matches two "
            "different claims is a warning naming their longer IDs; and a "
            "citation by position \u2014 insight 28, insights.md entry 28, "
            "or entry 28 on a line that says insight or inbox \u2014 is a "
            "warning naming the ID that position held when the citing line "
            "was last committed, read from git blame and that commit's "
            "insights.md; today's holder for a line not yet committed, and "
            "today's, labelled as such, where there is no git history to "
            "read; in a test as in a document other than a record.\n"
            "\n"
            "Over human-gate citations in docs/aide, the inbox and its "
            "archives excepted: a gate-<hex> token that names no row of "
            "progress.md's Human gates table is an ERROR; one that matches "
            "two different Gate cells is a warning naming their longer IDs; "
            "and a citation by position \u2014 gate 3, human gate #3 \u2014 "
            "is a warning naming the ID that row holds today, read only "
            "while progress.md's Human gates table has a row and never in a "
            "record. A token inside a "
            "path, a file name, a URL or a heading anchor is not a citation, "
            "and tests_dir is not read. A position, insight or gate, is never "
            "zero-padded: 037 is an item number.\n"
            "\n"
            "A record is the spec of an item progress.md shows \u2705, "
            "\u274c or \u23f8\ufe0f, or \U0001f4cb with every bullet in a "
            "stage whose summary row is \u274c, or a queue naming items none "
            "of which is still open; an ID naming nothing is an ERROR there "
            "too."))
    p_check.add_argument("--queue", type=int, default=None,
                         help="also check this queue's specs against each other "
                              "(scope overlaps, pinned state, dependency graph)")
    p_check.add_argument("--report", default=None,
                         help="with --queue: write the findings as JSON to this path")
    p_check.set_defaults(func=cmd_check)

    p_prog = sub.add_parser(
        "progress", help="edit progress.md status / acceptance",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "set:     flip an item's deliverable bullet and roll its stage "
            "up; a marker naming several items is desugared into one bullet "
            "per item first, and only the named item moves \u2014 the others "
            "keep the status they had. `set NNN deferred --reason TEXT` "
            "flips it to \u23f8\ufe0f and writes a dated "
            "`deferred: <reason>` line under it; `set --stage N "
            "--deliverable K deferred --reason TEXT` does the same to the "
            "Kth deliverable bullet of stage N, for a bullet no item marker "
            "names, and `set --stage N --deliverable K dropped --reason TEXT` "
            "flips such a bullet to \u274c instead, with a dated `dropped: "
            "<reason>` line, for a deliverable the stage does not need. "
            "`set NNN resumed --reason TEXT` takes a \u23f8\ufe0f item back "
            "to \U0001f4cb with a dated `resumed: <reason>` line, and "
            "`set --stage N --deliverable K resumed --reason TEXT` does the "
            "same to such a bullet. `set NNN dropped --reason TEXT` flips an "
            "item's bullets to \u274c with a dated `dropped: <reason>` line, "
            "and `set NNN restored --reason TEXT` takes a \u274c item back "
            "to \U0001f4cb with a dated `restored: <reason>` line, as `set "
            "--stage N --deliverable K restored --reason TEXT` does for such "
            "a bullet\n"
            "accept:  tick one acceptance criterion (--criterion N) or every "
            "one in the stage (--all), with --evidence\n"
            "amend:   append a dated correction under a ticked box; the tick "
            "stands (--evidence required)\n"
            "retract: untick a box, keep the original attestation visible, "
            "and capture a `gap` insight (--reason required)\n"
            "reword:  change a criterion's text in progress.md and roadmap.md, "
            "or in neither; where roadmap.md has no acceptance block for the "
            "stage, in progress.md alone; refuses over a ticked, annotated or "
            "corrected box. `reword --item NNN --text TEXT` takes no stage and "
            "instead rewrites the prose of the one deliverable bullet whose "
            "trailing marker names the item, whatever its status, keeping its "
            "icon and marker\n"
            "reopen:  send a \u2705 item back to \U0001f4cb \u2014 its "
            "deliverable bullet flips, a dated `reopened: <reason>` line goes "
            "under it, its stage rolls back down, and a `gap` insight is "
            "captured (--reason required)\n"
            "\n"
            "The rollup, applied by set and read by `aide check`: a stage is "
            "\u2705 when every deliverable bullet in it is \u2705 or \u274c "
            "and at least one is \u2705; \u23f8\ufe0f when every bullet is "
            "\u2705, \u274c or \u23f8\ufe0f and at least one is "
            "\u23f8\ufe0f; \U0001f6a7 when any bullet is "
            "\u2705, \U0001f6a7 or \U0001f50d; otherwise \U0001f4cb. "
            "\U0001f50d and \u23f8\ufe0f are both kept out of the \u2705 "
            "rule \u2014 an item awaiting review or deferred has not shipped. "
            "They differ below it: \U0001f50d also satisfies the \U0001f6a7 "
            "rule, so a stage holding one is always \U0001f6a7, while "
            "\u23f8\ufe0f gives way to any open bullet \u2014 a stage "
            "holding \u23f8\ufe0f and \U0001f4cb reads \U0001f4cb. "
            "The stage header, its summary-table "
            "row, and any Objective row delivered solely by \u2705 stages "
            "follow, as does an Objective row whose stages are all \u2705 "
            "or \u23f8\ufe0f, which reads \u23f8\ufe0f; an objective "
            "linked to an Outcome target that is not "
            "\u2705 Met never rolls up. A stage whose summary row is "
            "\u274c is withdrawn and left out of every Objective row that "
            "names it, and a row naming withdrawn stages alone reads "
            "\u274c. A header, summary row or Objective "
            "row marked \u23f8\ufe0f by hand stays as it reads until a verb "
            "moves a bullet of its stage. Apart from deferring, dropping, "
            "resuming and restoring, set never downgrades a status; an item "
            "whose bullets are all \u23f8\ufe0f or \U0001f4cb leaves "
            "\u23f8\ufe0f by resuming alone, back to \U0001f4cb, one whose "
            "bullets are all \u274c or \U0001f4cb leaves \u274c by "
            "restoring alone, back to \U0001f4cb, "
            "and only reopen moves a \u2705 item back. No rollup ever "
            "ticks an acceptance box.\n"
            "\n"
            "reword matches the Nth box to the Nth non-`Target:` bullet of the "
            "roadmap stage's Validation / acceptance block; if the two cannot "
            "be lined up, nothing is written and the message says which counts "
            "disagreed.\n"
            "\n"
            "reword --item writes the new prose on the bullet's first line, in "
            "place of all of its wrapped lines, and leaves every line under the "
            "bullet as it was. It writes progress.md alone: roadmap.md's "
            "deliverables carry no item marker, so there is no bullet of the "
            "item to mirror. It refuses, writing nothing, when no bullet or "
            "more than one names the item, when the bullet's marker names "
            "several items, or when the text is empty, starts with a status "
            "icon or ends with an item reference.\n"
            "\n"
            "Neither amend nor retract takes --all: each attestation was made "
            "separately and is corrected or withdrawn separately. Both refuse "
            "without a stated reason. `aide check` warns on every retracted "
            "criterion and `aide status` prints it.\n"
            "\n"
            "reopen refuses, writing nothing, unless every deliverable bullet "
            "whose trailing marker names the item is \u2705, and refuses "
            "without a stated reason. The reason goes on the trail line under "
            "each flipped bullet and into the `gap` entry; the bullet's text "
            "and marker, other items and every acceptance box are left as "
            "they were. `aide check` warns on every reopened item and "
            "`aide status` prints it, worded by the item's status today: one "
            "\u2705 again since reads as reopened and completed again, never "
            "as open.\n"
            "\n"
            "A reason starting `CI ` is a CI reopening, the queue-end step's "
            "fix round, and reopen appends its round to it as `[CI round N]`. "
            "The count is kept over one set of items: those of every queue "
            "the checked-out queue branch carries, where it has a recorded "
            "base, and else those of the queue file listing the item. N is "
            "the highest round stamped on a CI reopening of one of them while "
            "an item of them whose latest reopening is a CI one is still "
            "\U0001f4cb, \U0001f6a7 or \U0001f50d, and one more than that "
            "when none is. A reason that already ends in such a stamp is "
            "refused, exit 2, and so is one starting `CI:` or `CI-`, which "
            "would silently not be a CI reopening; any other reason, `CI/CD "
            "\u2026` or a bare `CI` included, is an ordinary one.\n"
            "\n"
            "set NNN deferred refuses, writing nothing, without a stated "
            "reason, or when a deliverable bullet whose trailing marker names "
            "the item is \u2705 or \u274c \u2014 reopen a \u2705 item "
            "first. Each \U0001f4cb, \U0001f6a7 or \U0001f50d bullet it "
            "flips gets the reason on a trail line, and its stage rolls "
            "up again, moving down where its bullets now say less; an item "
            "already "
            "\u23f8\ufe0f throughout is no change. No insight is "
            "captured: a deferral is a decision about order, not a finding.\n"
            "\n"
            "set NNN resumed flips each \u23f8\ufe0f bullet whose trailing "
            "marker names the item back to \U0001f4cb, writes the reason on "
            "a dated trail line under it, and rolls its stage up again, "
            "moving down where its bullets now say less; an item already "
            "\U0001f4cb throughout is no change. The item is then claimable: "
            "claim offers it, or, where a claim branch from before the "
            "deferral still exists, holds it as in flight on that branch. It "
            "refuses, writing nothing, without a stated reason, or when a "
            "bullet naming the item is \U0001f6a7, \U0001f50d, \u2705 or "
            "\u274c \u2014 only deferred work is resumed. set NNN in-progress, "
            "in-review and done each refuse a \u23f8\ufe0f item, writing "
            "nothing, and name the resume.\n"
            "\n"
            "set NNN dropped flips each \U0001f4cb, \U0001f6a7, \U0001f50d "
            "or \u23f8\ufe0f bullet whose trailing marker names the item to "
            "\u274c, writes the reason on a dated trail line under it, and "
            "rolls its stage up again, moving down where its bullets now say "
            "less; an item already \u274c throughout is no change. It "
            "refuses, writing nothing, without a stated reason, when a "
            "bullet naming the item is \u2705 \u2014 reopen it first "
            "\u2014 or when the drop would leave every deliverable bullet of "
            "a stage \u274c, unless that stage's summary row is already "
            "\u274c.\n"
            "\n"
            "set NNN restored flips each \u274c bullet whose trailing marker "
            "names the item back to \U0001f4cb, writes the reason on a dated "
            "trail line under it, and rolls its stage up again, moving down "
            "where its bullets now say less; an item already \U0001f4cb "
            "throughout is no change. It refuses, writing nothing, without a "
            "stated reason, or when a bullet naming the item is \U0001f6a7, "
            "\U0001f50d, \u2705 or \u23f8\ufe0f \u2014 only dropped work "
            "is restored. set NNN in-progress, in-review and done each "
            "refuse an item whose bullets are all \u274c or \U0001f4cb, "
            "writing nothing, and name the restore; `aide merge` refuses "
            "it too.\n"
            "\n"
            "set --stage N --deliverable K counts the stage's deliverable "
            "bullets from 1 in file order, a wrapped line belonging to its "
            "bullet, and takes no NNN and no status but deferred, dropped, "
            "resumed or restored. Each form refuses, writing nothing, without a stated reason, "
            "when stage N has no Kth bullet, or when that bullet carries an item "
            "marker \u2014 its status is its item's.\n"
            "\n"
            "set --stage N --deliverable K deferred also refuses a bullet "
            "that is \u2705 or \u274c. Otherwise it writes what set NNN "
            "deferred writes, and a bullet already \u23f8\ufe0f is no "
            "change.\n"
            "\n"
            "set --stage N --deliverable K resumed writes what set NNN "
            "resumed writes, to a \u23f8\ufe0f bullet; it refuses any "
            "other but \U0001f4cb, which is no change. Resume such a bullet "
            "before it is itemised: an item born on a \u23f8\ufe0f bullet "
            "is \u23f8\ufe0f from the start.\n"
            "\n"
            "set --stage N --deliverable K restored writes what set NNN "
            "restored writes, to a \u274c bullet; it refuses any other but "
            "\U0001f4cb, which is no change.\n"
            "\n"
            "set --stage N --deliverable K dropped flips a \U0001f4cb, "
            "\U0001f6a7, \U0001f50d or \u23f8\ufe0f bullet to \u274c, "
            "writes the reason on a dated trail line under it, and rolls its "
            "stage up again, moving down where its bullets now say less; "
            "\u274c counts toward the \u2705 rule above where "
            "\u23f8\ufe0f does not. It refuses a \u2705 bullet, which shipped, and a "
            "bullet already \u274c is no change. It also refuses, writing "
            "nothing, a drop that would leave every deliverable bullet of the "
            "stage \u274c, which the rollup reads as \U0001f4cb: a stage "
            "with nothing left to deliver is withdrawn whole, by a \u274c "
            "on its summary row and on any Objective row only it delivers. "
            "A stage whose summary row is already \u274c is withdrawn, so "
            "neither drop form refuses there. "
            "No insight is captured: "
            "dropping a deliverable is a decision about scope, not a "
            "finding."))
    p_prog.add_argument("action",
                        choices=["set", "accept", "amend", "retract", "reword",
                                 "reopen"])
    p_prog.add_argument("number", type=_progress_number, nargs="?", default=None,
                        help="item number (set, reopen) | stage number "
                             "(every other action; none for reword --item)")
    p_prog.add_argument("status", nargs="?", default=None,
                        help="set: in-progress | in-review | done | deferred "
                             "| dropped | resumed | restored (in-review = "
                             "pushed, awaiting a human's merge; the last four "
                             "need --reason and take --stage and "
                             "--deliverable in place of NNN for a bullet no "
                             "item marker names)")
    #: A criterion or a deliverable bullet, never both in one call: the two
    #: `reword` forms address different lines by different keys (issue #320).
    p_target = p_prog.add_mutually_exclusive_group()
    p_target.add_argument("--criterion", type=int, default=None,
                          help="1-based acceptance-criterion index within the stage")
    p_target.add_argument("--item", type=int, default=None, metavar="NNN",
                          help="reword: the item whose deliverable bullet's "
                               "prose --text replaces, in place of STAGE and "
                               "--criterion")
    p_prog.add_argument("--stage", type=int, default=None, metavar="N",
                        help="set deferred|dropped|resumed|restored: the "
                             "stage whose "
                             "deliverable bullet --deliverable names, in "
                             "place of NNN")
    p_prog.add_argument("--deliverable", type=int, default=None, metavar="K",
                        help="set deferred|dropped|resumed|restored: the "
                             "1-based position "
                             "of a deliverable bullet with no item marker "
                             "among the stage's deliverable bullets")
    p_prog.add_argument("--all", action="store_true", dest="all_criteria",
                        help="accept: every acceptance criterion in the stage "
                             "(amend/retract/reword act on one criterion only)")
    p_prog.add_argument("--evidence", default=None,
                        help="accept: annotation appended to the ticked criterion; "
                             "amend: the corrected evidence, appended as a dated line")
    p_prog.add_argument("--reason", default=None,
                        help="retract: why the attestation is withdrawn; "
                             "reopen: why the item is not done after all; "
                             "set deferred: why the item waits; "
                             "set dropped: why the stage does not need the "
                             "deliverable or item; set resumed: why the "
                             "deferred work is wanted now; set restored: why "
                             "the dropped work is wanted after all (required "
                             "for all six)")
    p_prog.add_argument("--text", default=None,
                        help="reword: the criterion's new wording, or with "
                             "--item the bullet's new prose (required)")
    p_prog.add_argument("--date", default=None,
                        help="amend/retract/reopen/set "
                             "deferred|dropped|resumed|restored: "
                             "ISO date for the trail line (default: today)")
    p_prog.add_argument("--no-commit", action="store_true", help="edit only, do not git commit")
    p_prog.set_defaults(func=cmd_progress, progress_parser=p_prog)

    p_gate = sub.add_parser("gate", help="list / resolve human gates in progress.md")
    p_gate.add_argument("action", choices=["list", "approve", "decline"])
    p_gate.add_argument("number", nargs="?", default=None, metavar="N|ID",
                        help="the gate to resolve (approve/decline): its "
                             "gate-<hex> ID, or its 1-based row as `aide gate "
                             "list` numbers it today")
    p_gate.add_argument("--evidence", "--reason", dest="note", default=None,
                        help="decision note written into the gate's last cell")
    p_gate.add_argument("--no-commit", action="store_true", help="edit only, do not git commit")
    p_gate.set_defaults(func=cmd_gate)

    p_queue = sub.add_parser(
        "queue", help="queue branch creation / maintenance, a planned "
        "queue's plan-review gate, keeping a stack of queue branches "
        "merged forward (restack), the queue's own PR (pr, ready), and "
        "discarding a queue branch nothing was committed on (discard)",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "start NNN creates <prefix>queue-NNN from --base (default "
            "main_branch), records that base and the commit it started from, "
            "and off local mode pushes it; --specs creates "
            "<prefix>specs-queue-NNN instead, which is never counted or "
            "stacked. Off local mode a checkout with no remote named origin "
            "is refused, exit 1, before the base, the cap or --dry-run is "
            "considered. A queue branch is unmerged until its own work has "
            "landed in main_branch, judged exactly as restack judges it "
            "(below), against this checkout's main_branch — and, off local "
            "mode, over origin's queue branches as last fetched too; one git "
            "cannot judge counts as unmerged. start refuses, exit 3, when "
            "[loop] max_open_queues (default 1) queue branches are already "
            "unmerged, naming them and the key. A branch whose PR merged "
            "counts until this checkout's main_branch holds its work, so "
            "updating main_branch is what clears it: a pull from origin "
            "off local mode, and in local mode merging the queue branch "
            "into main_branch; one git "
            "cannot judge is cleared by `aide gc --merged --yes` if it "
            "landed, or by `aide queue restack NNN --base main_branch`, which "
            "records its start, if it is open. Below the cap, while any "
            "queue branch is unmerged, the new queue stacks on the top of "
            "the one stack they form: --base names an unmerged queue branch, "
            "and walking recorded bases down from it reaches every unmerged "
            "queue branch. A base beside the stack (main_branch included), a "
            "base another unmerged branch is already stacked on, and an "
            "unmerged branch outside that walk are refused, exit 1. --dry-run "
            "runs every check and changes nothing. Exit 0: started (or would "
            "be). 1: refused — also a base that is not a local branch, a "
            "branch that exists here or on origin, an invalid "
            "max_open_queues, or a failed push. 2: usage. 3: the cap.\n"
            "\n"
            "gate NNN [--through MMM] raises the plan-review gate for queue "
            "NNN, or for queues NNN to MMM together (a maintenance queue and "
            "the stage queue after it), as [loop] plan_review (default "
            "\"queue\") says. \"queue\" writes one row, Gate cell `Queue NNN "
            "plan reviewed before build` (`Queues NNN–MMM plan reviewed "
            "before build` for a range), blocking every item those queue "
            "files list. \"stage\" writes one row per stage the queues open, "
            "Gate cell `Stage N plan reviewed before build`, blocking `stage "
            "N`: the queues open stage N when one of their items is "
            "referenced by a stage N deliverable in progress.md and no item "
            "stage N's deliverables reference is listed in a queue file "
            "numbered below NNN. \"none\" writes nothing and says so. A row "
            "whose Gate cell the table already holds is not written again, "
            "whatever its status, so a re-run raises nothing new. Each new "
            "row is ⏳ Awaiting, appended to the ## Human gates table (made "
            "at the end of progress.md when the section is absent) and "
            "committed on the current branch like every document verb, "
            "unless --no-commit; each gate is printed with its ID. Every "
            "other row is left as it is. Exit 0: "
            "raised, already raised, or nothing to raise. 1: a queue file "
            "missing or listing no items, no progress.md, an invalid "
            "plan_review, or a failed commit — where no commit was made, "
            "progress.md is put back byte for byte, so a re-run raises and "
            "commits the gate. 2: usage.\n"
            "\n"
            "restack keeps a stack of queue branches consistent: main_branch "
            "<- <prefix>queue-N <- <prefix>queue-M <- ..., each started with "
            "`aide queue start M --base <prefix>queue-N`. The stack is read "
            "from the base each queue branch recorded at `queue start`; a "
            "specs-queue branch is never part of one. Bottom up, each lower "
            "branch is merged into the one above it wherever the upper does "
            "not already contain it. It merges and never rebases, so nothing "
            "is ever force-pushed. Its merge commits honour commit.gpgSign "
            "and run no commit hook, on every git version.\n"
            "\n"
            "Each stack branch's own landing is judged at its own step, "
            "whatever lies below it. A branch whose content has landed in "
            "main_branch — by a merge commit, a squash or a rebase "
            "merge, judged by the same merge-tree comparison `gc` uses, or by "
            "a fast-forward past the commit it started from — is left "
            "alone, and main_branch is merged into the branch above it with "
            "the landed branch's tip as the merge base, so a squash merge "
            "does not conflict with the commits it squashed; that branch's "
            "recorded base becomes main_branch. Where a branch started is "
            "the start commit `queue start` recorded for it, or, above "
            "another branch, that branch's tip; a branch with no commits "
            "beyond its lower is not judged on its own, and is handed "
            "main_branch when its lower has landed. A "
            "branch whose tip is on main_branch's first-parent history and "
            "still at its start has no commits of its own, and is open; an "
            "open branch beneath one that landed keeps its record and is "
            "left alone, and once the branch above it is handed to "
            "main_branch it holds no stack. Only a bottom branch can go "
            "unjudged: with no start recorded (one started before 2.14.0, or "
            "on another machine) git cannot tell a fast-forward landing from "
            "a branch with no commits of its own, so each branch above it "
            "that has not itself landed is left as it is, the run exits 1 "
            "and never reports the stack consistent, and the message names "
            "both remedies. On git older than 2.38 only an ancestry merge is "
            "seen, so a squash-merged branch reads as still open; before "
            "2.40 main_branch is merged over git's own merge base.\n"
            "\n"
            "It reads git and never a pull request: a PR closed without "
            "merging looks exactly like one still open, so a caller checks "
            "for a closed PR before it restacks.\n"
            "\n"
            "A queue branch with no recorded base (this checkout did not "
            "start it) is not read into any stack, and is listed with the "
            "remedy: `restack NNN --base REF` records REF as queue NNN's "
            "base, creating the local branch from origin where only origin "
            "has it, and merges REF in unless the branch has nothing REF "
            "lacks; the base is written after that merge, so a run that "
            "stops keeps the record it found. Where no start is recorded it "
            "records one, the branch's merge base with REF. A recorded base naming a queue "
            "branch this checkout does not have, or a cycle, refuses the run "
            "before anything changes.\n"
            "\n"
            "Off local mode it fetches first, fast-forwards each stack "
            "branch origin is ahead on, refuses a branch that has diverged "
            "from origin, and once every merge has succeeded pushes, without "
            "force, each stack branch it merged into or that is ahead of "
            "origin; with no remote named origin it refuses, exit 1, before "
            "anything changes, --dry-run included. local mode never fetches "
            "or pushes.\n"
            "\n"
            "It needs a clean tree, and refuses a stack branch checked out "
            "in another worktree. A conflict aborts that merge, leaves the "
            "tree clean and HEAD where it started, pushes nothing, and names "
            "both branches: a stop, never a resolution. Merges made before "
            "it stay local, and a re-run pushes them. --dry-run prints the "
            "merges, base records and pushes it would make and changes "
            "nothing.\n"
            "\n"
            "Exit 0: the stack is consistent, whether or not this run merged "
            "anything; a re-run with nothing moved merges nothing and says "
            "so. 1: stopped — a conflict, an unclean tree, a diverged "
            "or unreadable stack branch, a lower branch it cannot judge, a "
            "failed signature, or a failed fetch or push. 2: usage "
            "(NNN without --base, or --base without NNN).\n"
            "\n"
            "pr [NNN] opens the draft pull request of queue branch "
            "<prefix>queue-NNN (default: the current branch, which must be "
            "one) against the base `queue start` recorded, and does nothing "
            "else. Its title is `aide: work queue NNN`, or `aide: work queues "
            "NNN-MMM` when the branch also adds queue file MMM (a maintenance "
            "queue and the stage queue after it); its body is exactly one of "
            "--body or --body-file, which the caller writes. It pushes the "
            "branch first where origin lacks commits the branch has. A branch "
            "that already has an open or draft PR is left alone, exit 0, and "
            "the PR named. It refuses, exit 1: a branch that is not a queue "
            "branch, local mode or no origin, no recorded base, no commits "
            "ahead of that base, a PR on the branch that was closed or merged "
            "(no second one is opened over it), a forge that could not be "
            "asked, and a failed push or create. 2: usage.\n"
            "\n"
            "ready [NNN] marks that branch's pull request ready for review, "
            "and does nothing else. It pushes the branch first where origin "
            "lacks commits the branch has, so CI sees the tree the queue "
            "built. A PR already ready is left alone, exit 0, and says so. "
            "--undo turns the PR back into a draft for a fix round, and "
            "pushes nothing; one already a draft is left alone, exit 0. Both "
            "refuse, exit 1: a branch that is not a queue branch, local mode "
            "or no origin, a branch with no PR (`queue pr` opens it), a PR "
            "closed or merged, a forge that could not be asked, and a failed "
            "push or change. Under [git] forge = \"none\" both refuse, exit "
            "1, before the forge is asked anything: no forge is declared. "
            "Before the mode or the forge is considered, both refuse, exit "
            "1, a queue branch whose tip carries no queue file of its own "
            "number: nothing is planned on it, so a pull request would have "
            "no plan to carry.\n"
            "\n"
            "An option the action does not read is refused, exit 2, before "
            "anything is done: pr and ready take no --dry-run, --base, "
            "--through, --date, --specs or --no-commit, pr no --undo and ready "
            "no --body or --body-file; start, tidy, gate and restack take "
            "no --body, --body-file or --undo; and discard takes none of "
            "them.\n"
            "\n"
            "discard NNN discards a queue branch `queue start` made that "
            "carries no commits beyond its recorded base, locally and on "
            "origin; it refuses one that does. Origin's copy, as last "
            "fetched, is counted too, and deleted only while origin still "
            "holds the commit counted. With nothing on the branch to lose "
            "there is no preview and no confirmation. A checked-out branch "
            "is left for its base first, and uncommitted changes to tracked "
            "files are refused. local mode never touches origin, and off "
            "local mode with no remote named origin only the local branch "
            "is deleted. The branch's recorded base and start go with it. "
            "Exit 0: discarded; origin's copy found already gone there "
            "counts as deleted. 1: refused, nothing discarded — no such "
            "branch here or on origin, one on origin only, no recorded "
            "base, a commit beyond the base or commits git could not count, "
            "a queue file of the number or the one after it written and not "
            "committed, the branch checked out in another worktree, "
            "uncommitted changes or an unfinished merge or rebase while it "
            "is checked out, or a switch or push git refused "
            "(after a switch, the message says the checkout is now on the "
            "base); and a local delete git refused, where origin's copy, if "
            "any, is already gone and the message says so. 2: usage."))
    p_queue.add_argument("action", choices=["start", "tidy", "restack", "gate",
                                            "pr", "ready", "discard"])
    p_queue.add_argument("number", type=int, nargs="?", default=None,
                         help="queue number (start, tidy, gate, discard; restack only "
                              "with --base; pr, ready: default the current "
                              "queue branch)")
    p_queue.add_argument("--through", type=int, default=None, metavar="MMM",
                         help="gate: one gate over queues NNN to MMM (a "
                              "maintenance queue and its stage queue)")
    p_queue.add_argument("--no-commit", action="store_true",
                         help="gate: write the row, do not git commit")
    p_queue.add_argument("--specs", action="store_true",
                         help="start: create the specs-queue branch instead")
    p_queue.add_argument("--base", default=None,
                         help="start: branch from this ref (default: "
                              "main_branch); restack: record this ref as "
                              "queue NNN's base, then restack")
    p_queue.add_argument("--dry-run", action="store_true",
                         help="start, restack: print what would be done, "
                              "change nothing")
    p_queue.add_argument("--date", default=None, help="tidy: override the supersede date (YYYY-MM-DD)")
    p_queue.add_argument("--body", default=None,
                         help="pr: the PR body, as text")
    p_queue.add_argument("--body-file", default=None, metavar="PATH",
                         help="pr: the PR body, read from this file")
    p_queue.add_argument("--undo", action="store_true",
                         help="ready: turn the PR back into a draft")
    p_queue.set_defaults(func=cmd_queue)

    p_ins = sub.add_parser(
        "insights", help="add / list / tick / archive / resolve the insight inbox",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "add:     capture one entry \u2014 append `- [ ] TYPE \u2014 CLAIM "
            "*(PROVENANCE, YYYY-MM-DD, engine X.Y.Z)*` at the end of the "
            "inbox, the date today's and the engine version read from "
            ".aide/VERSION, the provenance and its comma left out when "
            "--provenance is not given; print the entry's ID, the one list "
            "prints, and commit. Refuses with exit 2, writing nothing, a type "
            "that is not knowledge, defect, gap, automation or framework, an "
            "empty claim, a line break in the claim or the provenance, and a "
            "claim or provenance whose line would read back as a different "
            "entry. In a POSIX shell, single-quote the claim so backticks in "
            "it stay literal, and write an apostrophe inside it as '\\''\n"
            "list:    number the entries by position and print them all, "
            "ticked ones included; --open narrows to the untriaged, and an "
            "archived entry is in neither. Each entry is printed with its ID "
            "— the capture date and the leading hex of a SHA-256 of the "
            "claim text, whitespace collapsed — which no tick, trail, "
            "archive or merge changes; four hex digits, more only where two "
            "different claims of one date would share them. list N or list "
            "ID prints that one entry with its trail, and an ID is found in "
            "the archives too\n"
            "tick:    the one in-place edit — tick entry N (or ID) with --pointer; on "
            "an entry already ticked, append a dated trail line instead; "
            "with --trail, append the dated line under entry N and leave "
            "its checkbox as it is, which is how a judgement that keeps an "
            "entry open (a duplicate, a reason it stays) is recorded\n"
            "archive: move closed entries older than --before into "
            "insights/archive-YYYY-QN.md, each with its trail, line for line; "
            "an entry it cannot date is named and left behind; the archive is "
            "frozen and no longer shape-checked; what remains is renumbered, "
            "so re-run list. Every citation by position in docs/aide or "
            "tests_dir whose number the move changes is listed before "
            "anything moves, dry run or not, with the ID that position holds before the move and "
            "whether it is archived or renumbered; the archive still "
            "proceeds\n"
            "resolve: write the union of a conflicted inbox — the shared "
            "history, then each side's new entries in capture order; a tick "
            "on either side stands and keeps its pointer, trail lines merge "
            "in date order, and two ticks with different pointers keep both "
            "and say so. Refuses, writing nothing, anything that is not a "
            "pure append: a claim reworded, reordered or deleted on one side, "
            "or a side that archived.\n"
            "\n"
            "A missing insights.md is created from .aide/templates/insights.md "
            "by list and add (and by check, claim and queue start) and "
            "committed when "
            "git can — on a branch, with an identity; otherwise it is left "
            "untracked and the notice says why."))
    p_ins.add_argument("action", choices=["add", "list", "tick", "archive", "resolve"])
    p_ins.add_argument("number", nargs="?", default=None, metavar="N|ID|TYPE",
                       help="tick: the entry number or ID from `insights list`; "
                            "list: print that one entry; add: the entry's type")
    p_ins.add_argument("claim", nargs="?", default=None, metavar="CLAIM",
                       help="add: the claim, one line")
    p_ins.add_argument("--provenance", default=None,
                       help="add: where the insight came from, free-form "
                            "(item NNN, queue-NNN, items NNN-NNN); omitted "
                            "when not given")
    p_ins.add_argument("--open", action="store_true", dest="open_only",
                       help="list: only entries still untriaged")
    p_ins.add_argument("--type", default=None,
                       help="list: one of " + ", ".join(_INSIGHT_TYPES))
    p_ins.add_argument("--trail", action="store_true",
                       help="list: also print each entry's status trail; "
                            "tick: append the dated --pointer line under entry N "
                            "without ticking it")
    p_ins.add_argument("--pointer", default=None,
                       help="tick: where the claim landed (a doc, item, or issue)")
    p_ins.add_argument("--before", default=None,
                       help="archive: move entries closed before this date (YYYY-MM-DD)")
    p_ins.add_argument("--date", default=None,
                       help="tick, resolve: override the trail-line date "
                            "(default: today)")
    p_ins.add_argument("--dry-run", action="store_true",
                       help="resolve: print what the union would be, write nothing")
    p_ins.add_argument("--yes", action="store_true",
                       help="archive: actually move (default: dry run)")
    p_ins.add_argument("--no-commit", action="store_true", help="edit only, do not git commit")
    p_ins.set_defaults(func=cmd_insights)

    p_ledger = sub.add_parser(
        "ledger", help="record what an item cost where no merge will, and "
        "read the rows back (one row per item, docs/aide/ledger.md)",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "abandon: the row for an item that never merged \u2014 one "
            "stopped at the validation-round cap, which is exactly the item a "
            "reader at a queue boundary is looking for and the one `aide "
            "merge` never sees.\n"
            "\n"
            "The cells are derived as `merge` derives them, from the "
            "documents and \u2014 where the claim branch is still there "
            "\u2014 a diff against the base it recorded; a branch already "
            "gone costs the two diff cells and nothing else on the row. "
            "--rounds is required and the verb exits 2 without it: the round "
            "count is why the row exists, and an abandoned item recorded "
            "without one says nothing a reader can use. --findings is "
            "optional, and a rank left out of it is a blank cell \u2014 "
            "except under a project whose [loop] review is off, where the "
            "three finding cells carry the same `-` mark `merge` writes. An "
            "item "
            "already recorded as abandoned with the same counts is not "
            "recorded twice: a re-run appends nothing and exits 0, while a "
            "different count is a new abandonment and a new row.\n"
            "\n"
            "It writes the ledger and nothing else: progress.md keeps "
            "whatever status the run left it, since what becomes of an "
            "abandoned item is a decision, not a record: its owner's, and "
            "`aide progress set NNN dropped --reason TEXT` records one "
            "against the work. The file is created "
            "from .aide/templates/ledger.md when this is the first row, and "
            "committed on the branch the run is standing on, with no pull.\n"
            "\n"
            "report: reads the ledger and writes nothing \u2014 a table, or "
            "with --json the same numbers for a reader to annotate; --queue "
            "NNN keeps that queue's rows. Rows are grouped by their Engine "
            "cell as written, and within it by Kind, never pooled across "
            "kinds. Each group shows its Stage cells, merged and abandoned "
            "counts, rounds per item and how many rows took each round "
            "count, tests per acceptance criterion, findings per item by "
            "rank, and how many of its caller-supplied cells (Rounds and "
            "the three finding cells) are blank. Every ratio carries its n, "
            "the rows it is drawn from. A blank cell joins no ratio and is "
            "counted as unrecorded; a `-` finding cell joins no finding "
            "ratio; a merged row whose Tests and Files are both 0 is read "
            "as unrecorded in those two cells, never as zero \u2014 except "
            "where the item already has an earlier merged row on the same "
            "queue: that repeat is a merge re-run's duplicate and is left "
            "out, and the earlier row counts. Any other repeat merged row is "
            "a reopened item merged again, and both count. Finding ratios "
            "are withheld "
            "from a group whose Engine cell is not 1.59.0 or later, where a "
            "blank finding cell may also mean no review ran. Rounds are a "
            "distribution, not a share at the round cap: the cap is a "
            "setting, and it may have moved under the rows. A row with a "
            "cell count no ledger template draws is skipped and named "
            "(under --queue, only one whose Queue cell names that queue). A "
            "missing ledger is reported and exits 0; report never creates "
            "one.\n"
            "\n"
            "The groups are descriptive and not comparable: another engine, "
            "another setting or another batch of work sits behind each, and "
            "a small one is an anecdote."))
    p_ledger.add_argument("action", choices=["abandon", "report"])
    p_ledger.add_argument("number", type=int, nargs="?", default=None,
                          help="abandon: the item (required)")
    p_ledger.add_argument("--rounds", type=_non_negative_argument, default=None,
                          help="abandon: build\u2194validate rounds the item took "
                               "before it was abandoned (required)")
    p_ledger.add_argument("--findings", type=_findings_argument, default=None,
                          help="abandon: findings by rank: blocking=A,minor=B,nit=C "
                               "\u2014 any subset, any order")
    p_ledger.add_argument("--no-commit", action="store_true",
                          help="abandon: write the row, do not git commit")
    p_ledger.add_argument("--queue", type=_non_negative_argument, default=None,
                          metavar="NNN",
                          help="report: only the rows whose Queue cell is NNN")
    p_ledger.add_argument("--json", action="store_true", dest="as_json",
                          help="report: print the readings as JSON")
    p_ledger.set_defaults(func=cmd_ledger)

    register_git_subcommands(sub)  # claim / merge / env (git layer)
    return parser


def register_git_subcommands(sub) -> None:
    """Attach the claim / merge / env subparsers (git layer)."""
    p_claim = sub.add_parser(
        "claim", help="pick + claim the next unclaimed 📋 item",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "Picks the first 📋 item the queue lists \u2014 its own "
            "order, not the item numbers \u2014 whose dependencies have all "
            "left the way (\u2705, \u274c, \u23f8\ufe0f, or a "
            "\U0001f4cb item of a withdrawn stage) and that no unresolved "
            "human gate reaches. An "
            "item every deliverable bullet of which sits in a stage whose "
            "Stage summary row is \u274c \u2014 withdrawn whole \u2014 "
            "is not offered either, and the report names the stage; an item "
            "dropped by its own bullets is \u274c, not \U0001f4cb. Such a "
            "\U0001f4cb item keeps no queue open, so the default queue is "
            "the lowest-numbered one with other work open, and where no queue "
            "is open the refusal names each one still listed; a \U0001f6a7 "
            "or \U0001f50d item of a withdrawn stage still keeps its queue "
            "open. A "
            "queue-end item, one titled `Validate stage N`, waits besides on "
            "every other item its queue lists that is not one, as on a "
            "dependency, with or without a spec and wherever the queue lists "
            "it, bar an item whose dependencies lead back to it and a "
            "\U0001f4cb item of a withdrawn stage. It "
            "will not offer a blocked item: where a gate holds the pick, the "
            "report names that gate, what it blocks and who may resolve it, "
            "and each item of a withdrawn stage besides, "
            "rather than an unexplained \"none left\". Every \"none left "
            "\u2014 \u2026\" report that exits 0 ends with an `early ready:` "
            "line, yes or no before an em dash: yes when every gate holding "
            "the queue is still \u23f3 awaiting its decision, every open item "
            "waits on one \u2014 one reaches it, or it waits only on items "
            "that do \u2014 no open item is claimed, and at least one item of "
            "the queues checked is \u2705; no otherwise, with the reason. A "
            "\u274c declined gate makes it no. An `all` gate over a queue "
            "with nothing left open is read the same way, a yes in words of "
            "its own. A bare "
            "\"none left\" (nothing open, no gate) carries no such line. An "
            "unpublished claim \u2014 a claim branch origin has never seen "
            "\u2014 exits 1 with how to publish or release it, whether or not "
            "a gate holds the rest. A claim branch origin had and has since "
            "deleted exits 1 the same way, named as already in its base or "
            "as work that could not be found there, and is never advised a "
            "push. Off local mode a checkout with no remote named origin is "
            "refused, exit 1, before anything is picked, created or fetched, "
            "--dry-run included. "
            "A human-gates row it "
            "cannot read holds every item, since what it blocks is unknown: "
            "the report names the row and exits 1. A missing insights.md "
            "is created from the template on the way through. When the "
            "item's spec exists and an Assumption names an item under its "
            "## Dependencies, the claim names that assumption as pinning a "
            "dependency's interface, to be re-checked before tests are "
            "written; an engine-marked assumption and one already carrying a "
            "re-check are not named, and a dependency that left the queue as "
            "\u274c, \u23f8\ufe0f or a \U0001f4cb item of a withdrawn stage "
            "is named as having no code to check against."))
    p_claim.add_argument("--queue", type=int, default=None,
                         help="queue number (default: the lowest-numbered open queue)")
    p_claim.add_argument("--base", default=None,
                         help="branch this claim off, and merge it back into "
                              "(default: the current branch when it is a queue "
                              "branch, else main_branch)")
    p_claim.add_argument("--dry-run", action="store_true", help="print the pick, do not create/push a branch")
    p_claim.set_defaults(func=cmd_claim)

    p_merge = sub.add_parser(
        "merge", help="merge a validated item per git.mode",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "Lands the item's claim branch on its base per git.mode, re-runs "
            "the suite and `aide check`, writes the \u2705 and appends one "
            "ledger row. Off local mode a checkout with no remote named "
            "origin is refused, exit 1, before anything is run, merged, "
            "pushed or written.\n"
            "\n"
            "The row is one per item, in docs/aide/ledger.md \u2014 created "
            "from .aide/templates/ledger.md the first time there is a row to "
            "write, and committed together with the \u2705 so the two can "
            "never disagree. Every cell is derived here: the item, its queue, "
            "its stage, its kind \u2014 validate-stage from an item titled "
            "`Validate stage N`, maintenance from an inbox entry ticked with "
            "this item's number, else normal \u2014 how many acceptance "
            "criteria its spec "
            "carries, how many test functions and files the branch added "
            "against the base this run resolved \u2014 less the tests "
            "`aide scope` reports as reconciled in another item's test file, "
            "which are that item's \u2014 the engine version, "
            "today's date, the post-merge suite run's wall time in whole "
            "seconds and how many inherited failures it admitted (below). The "
            "exceptions are --rounds and --findings, which "
            "no document holds and only the caller has.\n"
            "\n"
            "A count nobody passed is a blank cell and never a 0 \u2014 an "
            "unrecorded run must not read as a cheap one \u2014 and a cell "
            "nothing could measure is blank for the same reason, so an item "
            "whose spec or branch has gone still gets its row. Under pr mode "
            "this verb pushes and stops, so it writes neither the tick nor a "
            "row. A ledger write that fails is reported after the merge and "
            "never changes the exit code: the merge is made, and capture is "
            "worth a sentence rather than an item. A commit of what was "
            "written that git does not make is another matter: the run "
            "pushes nothing, puts the claim branch back with its base, leaves "
            "progress.md, the ledger and insights.md as they were before the "
            "tick, and exits 1, so the re-run writes the row once. A commit "
            "that is made but whose replay onto origin stops is kept, and "
            "refuses the push the same way. A push that fails after the "
            "tick's commit is made keeps that commit, and the re-run finds "
            "the item \u2705 with its merged row and appends no second one; "
            "the second row of an item is written only by a merge of it "
            "after `aide progress reopen` sent it back. An item "
            "stopped at the "
            "validation-round cap never reaches this verb, and "
            "`aide ledger abandon` writes its row instead.\n"
            "\n"
            "An item progress.md shows \u274c dropped \u2014 every bullet "
            "naming it \u274c or \U0001f4cb, in the working tree or on the "
            "base \u2014 is refused before anything is merged, pushed or "
            "written, exit 1, and the refusal names `aide progress set NNN "
            "restored`. A \u23f8\ufe0f item is merged and ticked: a merge "
            "records work that landed. An item \U0001f4cb with every "
            "bullet in a stage whose summary row is \u274c, in the working "
            "tree or on the base, is refused the same way, and the refusal "
            "names `aide progress set NNN dropped`; one the claim branch, "
            "the working tree or the base reads \U0001f6a7 is merged, since "
            "started work is live until its owner drops it.\n"
            "\n"
            "The finding cells read [loop] review, from aide.toml. Where it "
            "is off no reviewer ran, so the three of them are written as `-` "
            "rather than left blank, and a blank in them means a count that "
            "should have been passed and was not. --findings passed anyway "
            "under off wins over the mark, since a count is a claim its "
            "caller made. Where review is on and --findings is absent the "
            "run warns on stderr, writes the row and still exits 0. The "
            "counts are of in-scope findings; one outside the item is an "
            "insights.md line and no cell here.\n"
            "\n"
            "A red post-merge run is compared with the base where the test "
            "command runs pytest as a module (`<python> -m pytest ...`): the "
            "run writes a JUnit report, and the same command is then run on "
            "the base as it stood before this merge, in this checkout, or its "
            "result reused where this repository already recorded a run of "
            "that tree. When every failure after the merge also fails at the "
            "base, the failures are inherited rather than this item's: the "
            "merge is admitted, both sets are printed, the row's Inherited "
            "cell counts them, and one defect entry naming those no open "
            "insights.md entry names yet is committed with the tick. A "
            "failure the base does not have refuses the tick and the push, "
            "listed apart from the inherited ones. Any other runner, an "
            "order-dependent flag (-x, --maxfail, --lf, --ff, --sw), a pytest "
            "exit other than 1 and a base that cannot be identified keep the "
            "plain gate, where any red run refuses. The Suite s cell is blank "
            "under --no-test, and Inherited is blank wherever no comparison "
            "could be made.\n"
            "\n"
            "Before running the suite it looks for a run `aide test` recorded "
            "of the same tree on the claim branch, and takes that run in "
            "place of its own where `aide test -h` says it may: the run is "
            "judged the same way, the output names the commit it ran at, and "
            "the Suite s cell reads its seconds followed by (reused). Any "
            "other merge runs the suite, and prints why it could not reuse "
            "one.\n"
            "\n"
            "Where the item's latest reopening is a CI one (a reason `aide "
            "progress reopen` stamped `[CI round N]`), the open `gap` entry "
            "that reopening captured is ticked with the pointer `re-merged "
            "into <base> in CI round N` and committed with the tick (not in "
            "pr mode, where this verb writes no tick: the gap stays open, as "
            "the row stays unwritten, and `aide progress set NNN done` ticks "
            "neither); no other entry is touched, an earlier round's "
            "included. A commit that is not made puts insights.md back with "
            "the rest."))
    p_merge.add_argument("number", type=int)
    p_merge.add_argument("branch", nargs="?", default=None, help="claim branch (default: found from number)")
    p_merge.add_argument("--base", default=None,
                         help="merge into this ref (default: what the claim "
                              "recorded, else main_branch)")
    p_merge.add_argument("--no-test", action="store_true",
                         help="skip the post-merge test run; the aide check "
                              "gate beside it still runs, and an error in it "
                              "still refuses the tick and the push")
    p_merge.add_argument("--no-commit", action="store_true",
                         help="do not commit the progress.md status the merge "
                              "records, nor the ledger row and any inbox "
                              "entry beside it")
    p_merge.add_argument("--rounds", type=_non_negative_argument, default=None,
                         help="build\u2194validate rounds this item took, for "
                              "the ledger row (absent: a blank cell)")
    p_merge.add_argument("--findings", type=_findings_argument, default=None,
                         help="review findings by rank for the ledger row: "
                              "blocking=A,minor=B,nit=C \u2014 any subset, "
                              "any order")
    p_merge.set_defaults(func=cmd_merge)

    p_test = sub.add_parser(
        "test", help="run the test command and record the result for merge",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "Runs [python] test_command exactly as `aide merge` runs it \u2014 "
            "a leading python bound to the venv, and, where the command runs "
            "pytest as a module with no order-dependent flag, a JUnit report "
            "naming each failure \u2014 and exits with the command's own exit "
            "code.\n"
            "\n"
            "The result is recorded where the tree has no tracked change and "
            "HEAD does not move during the run: the tree, the command, the "
            "exit code, the failing tests, the wall time, and the branch and "
            "commit it ran at, in the same store under the git directory that "
            "`aide merge` keeps its base runs in. A run over a tree with "
            "tracked changes is not recorded, and says so on stderr.\n"
            "\n"
            "`aide merge` takes a recorded run in place of its own suite run "
            "when the post-merge tree is the claim branch's tip tree, the "
            "command is the same, and the run was recorded by this verb on "
            "that claim branch in the same checkout, at a commit the tip "
            "contains, with nothing "
            "but the progress document changed since. It says so, judges the "
            "run exactly as one of its own, and writes the row's Suite s cell "
            "as the recorded run's seconds followed by (reused). Where the "
            "base had moved, or anything else changed, it runs the suite."))
    p_test.set_defaults(func=cmd_test)

    p_env = sub.add_parser(
        "env", help="what this machine has for this project's configuration "
                    "(git, repository, origin, gh, test command, Python, venv "
                    "health) + venv bootstrap",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "Reports, one line each, what this project's configuration needs "
            "of this machine and what the machine has: git, with its version "
            "and the merge-tree features gc (2.38+) and queue restack (2.40+) "
            "use; the repository, and whether aide.toml is at its top level; "
            "a remote named origin; gh, and whether `gh auth status` confirms "
            "a login; the test command's program; the interpreter the engine "
            "runs on and the one its suggested commands print ([tools] python "
            "in .aide/local.toml); and the venv \u2014 it exists, its last "
            "bootstrap finished, it is the [python] interpreter's version, "
            "import_check and a `python -m` test runner import.\n"
            "\n"
            "origin and gh are needed under every [git] mode but local. "
            "[git] forge = \"none\" declares no forge: gh is then not needed, "
            "and its line is left out. A "
            "requirement the configuration needs and this machine lacks is a "
            "refusal naming the setting that needs it and the two ways out "
            "\u2014 meet it, or change the setting \u2014 and exits 1; nothing "
            "is adapted to fit the machine. A printed interpreter this "
            "machine lacks is a note that fails nothing: it decides only "
            "what a suggestion says. [python] venv = \"\" means the "
            "project keeps no venv: the venv line is left out, and --bootstrap "
            "refuses. Exits 0 when every requirement the configuration needs "
            "is met. `aide check` without --queue errors on the offline "
            "part of the same report.\n"
            "\n"
            "--bootstrap builds the venv where it is missing or stale and "
            "reports on the venv alone: exit 0 when the venv is OK, whatever "
            "else the report would refuse. It installs with [python] "
            "bootstrap, split on whitespace and read by its first word: pip "
            "runs as the venv's `python -m pip`; python or python3 is "
            "replaced by the venv's Python; an option (-m, -c), a .py file "
            "or another file in the repository is passed to the venv's "
            "Python, as every bootstrap but pip was before; anything else "
            "is a command, found in the venv's script directory first and "
            "then on PATH, and run with that directory first on PATH and "
            "VIRTUAL_ENV and UV_PROJECT_ENVIRONMENT set to the venv. A "
            "command found in neither is a failed bootstrap that names it. "
            "Only a first word the old reading could never have run is a "
            "command, so a bootstrap that worked runs the same way, and a "
            "shell script in the repository is written `sh <script>`. An "
            "empty bootstrap builds the venv and installs nothing."))
    p_env.add_argument("--bootstrap", action="store_true",
                       help="create + populate the venv if missing/stale, from "
                            "[python] interpreter when set; reports on the "
                            "venv alone")
    p_env.add_argument("--profile", default=None,
                       help="evaluate a named [validation] environment profile "
                            "(exit 0 iff satisfied; one that runs past "
                            f"{PROFILE_TIMEOUT}s or cannot start is not satisfied)")
    p_env.set_defaults(func=cmd_env)

    p_sync = sub.add_parser("sync", help="preflight: fetch, verify clean tree, land on the right branch")
    p_sync.add_argument("--item", type=int, default=None,
                        help="verify/switch to this item's claim branch")
    p_sync.set_defaults(func=cmd_sync)

    p_gc = sub.add_parser(
        "gc", help="delete claim branches whose work has landed (dry-run by default)",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "Deletes claim branches, local and remote, whose item is \u2705 in "
            "progress.md, and with --merged also branches already merged into "
            "the base. A queue branch is taken on that ground only when the "
            "base is main_branch: one merged into any other base is skipped, "
            "since it has landed in the queue stacked on it and its own PR is "
            "still its route to main_branch. An item \u274c by its own bullets, or \U0001f4cb "
            "with every bullet in a stage whose summary row is \u274c, is "
            "on the \u2705 ground too. On the \u2705 ground a branch goes "
            "only when "
            "`git merge-tree --write-tree` says merging it into the base would "
            "change nothing; a branch that still carries unlanded content is "
            "skipped with the base named, unless --abandon. merge-tree "
            "--write-tree needs git >= 2.38: on older git the \u2705 ground "
            "refuses rather than falling back to a weaker test.\n"
            "\n"
            "Every skip \u2014 checked out, unlanded, unmeasurable (a ref the "
            "oracle could not read), git too old \u2014 is decided "
            "before anything is printed and shown as `skipping <branch> "
            "(local | remote | local+remote): <reason>` on both paths, so the "
            "dry run is exactly the set --yes "
            "deletes."))
    p_gc.add_argument("--merged", action="store_true",
                      help="also delete claim branches already merged into the base")
    p_gc.add_argument("--base", default=None,
                      help="ref --merged is measured against (default: the "
                           "current branch's recorded base, else main_branch)")
    p_gc.add_argument("--abandon", action="store_true",
                      help="delete a ✅ or ❌ item's branch even though its "
                           "content is not in the base — for a genuinely "
                           "abandoned claim")
    p_gc.add_argument("--yes", action="store_true", help="actually delete (default: dry run)")
    p_gc.set_defaults(func=cmd_gc)

    p_status = sub.add_parser(
        "status", help="one-call roadmap-state report (branch, queues, "
        "claims, PRs, open gates, unmet targets, unverified capabilities, "
        "retracted criteria)",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "A \U0001f50d item's claim branch is reported as awaiting review, "
            "never as stale and never with a `gc` recommendation \u2014 that "
            "would be recommending the deletion of an open PR's head branch. "
            "Because in `pr` mode nothing inside the loop observes the merge, "
            "status (like `aide sync`) also names any \U0001f50d item whose "
            "work has since landed in the base that claim recorded (or "
            "`--base`), or in main_branch, by the same merge-tree "
            "comparison `gc` uses, and prints the `aide progress set NNN done` "
            "that closes it. Those bases are the local branches, never "
            "origin/<base>: a merge made on the forge is seen once that branch "
            "is pulled, not by the fetch alone. Every human gate still "
            "blocking, every Outcome "
            "target not yet \u2705 Met, every retracted acceptance "
            "criterion and every progress.md table row no reader can use is "
            "printed too, so none of them lives only in one commit's diff. "
            "So is every item `aide progress reopen` sent back, and a "
            "retracted criterion or reopened item that has since been "
            "re-accepted or completed again says so. "
            "So is every environment-gated capability not yet ✅ "
            "Verified, with the [validation] profile its Package / Tool cell "
            "names. With --profiles, each profile a ❓ Unverified row names "
            "is evaluated once, as `aide env --profile` evaluates it (the "
            "expression only, never the gated tests), and reported satisfied "
            "or not; one that times out or cannot start is not satisfied — "
            "a satisfied profile under an unverified row is a row this "
            "machine can verify now.\n\n"
            "The stack of unmerged queue branches \u2014 the ones `aide queue "
            "start` counts against [loop] max_open_queues \u2014 is printed "
            "bottom first, after a `stack: N/CAP` line: one `stack N: <branch> "
            "base= pr= checks= lower= orphaned=` line each, a field one token a "
            "program can read. base= is the branch's recorded base, ? where "
            "none is recorded. pr= is its pull request as #N/open, #N/draft (open "
            "but not yet marked ready), #N/merged or #N/closed (an open or "
            "draft one first, else the newest), none where gh "
            "found none, unknown where gh could not be asked, and - in local "
            "mode, which asks no forge. A draft reads #N/draft(fixing) when an "
            "item of the queues the branch carries (its own queue file and "
            "every queue file it adds over its base) was sent back by `aide "
            "progress reopen` and is still open, read from the branch's own "
            "progress.md: a PR turned back to draft for a fix round, not one "
            "never marked ready. checks= is the CI state of that PR's head "
            "commit: failure when any check failed, each failing check then "
            "named on a `failing check:` line below it; else pending while "
            "any has not finished; else success when any passed; else none "
            "\u2014 no check at all, or only skipped and neutral ones, which "
            "is what a CI that skips drafts reports. Just after a push or "
            "`aide queue ready`, none can also mean CI has not registered a "
            "run yet, so a caller waiting on CI does not take its first none "
            "as the answer. A cancelled, timed-out "
            "or stale check is a failed one. Under failure, each check still "
            "running is named on a `pending check:` line below the failing "
            "ones: the red is not settled until none is left, since a leg "
            "still running may fail too. checks= is unknown where gh "
            "could not be asked, could be asked only without checks (pr= is "
            "then read without them) or answered a state status cannot read, the "
            "reason on a `checks unknown:` line below it, and - where there "
            "is no PR and in local mode. For a draft or a PR whose checks= "
            "is failure, a `ci fix rounds: N` line below those counts the CI "
            "fix rounds the queues the branch carries have begun: the highest "
            "`[CI round N]` `aide progress reopen` stamped on a CI reopening "
            "of one of their items, read from the branch's own progress.md; "
            "no line where none has begun. lower= is moved when the queue branch "
            "below has commits this one lacks, so `aide queue restack` is due, "
            "and current when it has none; landed or gone when the recorded "
            "lower is no longer unmerged and is still a branch, or is not; - on a base "
            "that is no queue branch. orphaned= is yes when a PR below it in "
            "the stack was closed without merging, and a lower git says "
            "landed never orphans; unknown when one below it could not be "
            "looked up or has no recorded base; - in local mode.\n\n"
            "Under [git] forge = \"none\" no forge is asked at all: pr=, "
            "checks= and orphaned= are - as in local mode, awaiting review "
            "is no and the open-PR list is -. Under [git] ci = \"none\" "
            "checks= is - on every stack line, a PR or not: no CI is "
            "declared, so none is read.\n\n"
            "Two facts follow, each `yes`, `no` or (the second only) "
            "`unknown` before an em dash, and a repo can be both. "
            "runnable: is no when a queue PR in the stack was closed without "
            "merging or a branch is orphaned; otherwise yes when the live "
            "queue has a \U0001f4cb or \U0001f6a7 item or the stack is below "
            "[loop] max_open_queues, and no when neither. awaiting review: "
            "is yes when a queue branch's PR is open and ready for review \u2014 a "
            "draft is the loop's own PR still being built, and counts for "
            "nothing \u2014 unknown when none was seen ready but gh could not "
            "be asked, and no otherwise \u2014 in "
            "local mode always. The open-PR list says it could not look, and "
            "gh's reason, rather than going silent; in local mode it is - "
            "and gh is not asked."))
    p_status.add_argument("--no-fetch", action="store_true", help="skip the fetch --all --prune preflight")
    p_status.add_argument("--profiles", action="store_true",
                          help="evaluate the [validation] profile each "
                               "❓ Unverified capability row names (each "
                               f"bounded by {PROFILE_TIMEOUT}s)")
    p_status.add_argument("--base", default=None,
                          help="ref to report ahead/behind against, and to "
                               "measure every \U0001f50d claim's landed work "
                               "against before main_branch (default: the current "
                               "branch's recorded base for ahead/behind, each "
                               "claim's own for landed work; else main_branch)")
    p_status.set_defaults(func=cmd_status)

    p_scope = sub.add_parser(
        "scope", help="check this branch's diff against the item's authorised paths",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        description=(
            "Diffs the branch against the merge-base with the item's base and "
            "reports every changed path outside the spec's ## Authorised paths; "
            "a path listed under Asserts against and then changed is reported "
            "separately. With no number the item is read from the current "
            "claim branch, and a queue branch resolves to no item and is "
            "skipped. The base is --base if given, else the branch's recorded "
            "base, else main_branch; the two derived answers prefer "
            "origin/<base> over the local ref.\n"
            "\n"
            "Also warns, never fails, on traceability: every test function the "
            "branch added under tests_dir must name an AC number the spec's "
            "## Acceptance Criteria carries (ac3) or a case label its "
            "## Testing Strategy or its optional ## Review findings names (the "
            "first word of a bullet, closed by a colon, or by a full stop when "
            "the word is in bold or backticks and text follows: `empty-input: "
            "...`, `**empty-input.** ...`); a test "
            "naming none is reported as one the spec did not ask for. A "
            "parametrised test also traces through its literal "
            "pytest.mark.parametrize ids — a string argvalue, the strings of a "
            "tuple argvalue, a pytest.param id and each string in ids=[...], "
            "read without running anything — where the label or acN stands as "
            "a whole word of the id. A function present in the file at "
            "the base is an edit, not an addition, and is not checked, a "
            "renamed file being read under its old name; a spec with no "
            "## Acceptance Criteria heading is a notice and no warnings.\n"
            "\n"
            "A test file named test_NNN_<topic>.py for an item other than the "
            "one scoped is item NNN's, changed here to reconcile it: its added "
            "tests trace against item NNN's spec instead, and the scoped spec "
            "is not read for them. The ones that trace are reported as "
            "reconciled, in one notice per item, and not warned on; the rest "
            "warn, naming item NNN's spec. Where item NNN has no spec, or none "
            "with an ## Acceptance Criteria heading, the file is read as the "
            "scoped item's own.\n"
            "\n"
            "Exit 0: in scope, or nothing to check (a queue branch). 1: "
            "something changed outside it. 2: could not check (no spec, no "
            "section, or no base to diff against)."))
    p_scope.add_argument("number", type=int, nargs="?", default=None,
                         help="item number (default: read from the current claim branch)")
    p_scope.add_argument("--base", default=None,
                         help="base ref to diff against (default: the branch's "
                              "recorded base, else <main_branch>; derived answers "
                              "prefer origin/<base>, falling back to the local ref)")
    p_scope.set_defaults(func=cmd_scope)


#: The verbs, by action, that write a document and then commit it through
#: `_commits_here` — ``None`` for every action of the verb.
_RECORDING_ACTIONS: Dict[str, Optional[Tuple[str, ...]]] = {
    "gate": ("approve", "decline"),
    "progress": None,
    "insights": ("add", "tick", "archive"),
    "ledger": ("abandon",),
    "queue": ("gate",),
}


def _records_an_edit(args: argparse.Namespace) -> bool:
    """Will this run write a document and commit it?"""
    if getattr(args, "no_commit", False) or args.command not in _RECORDING_ACTIONS:
        return False
    actions = _RECORDING_ACTIONS[args.command]
    return actions is None or getattr(args, "action", None) in actions


def main(argv: Optional[List[str]] = None) -> int:
    # Windows consoles often default to a non-UTF-8 codepage (cp1252), where
    # printing a status icon raises UnicodeEncodeError and kills the command
    # instead of reporting. Reconfigure once here so no caller ever needs the
    # PYTHONIOENCODING env-var dance.
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding="utf-8", errors="replace")
        except (AttributeError, ValueError, OSError):
            pass
    parser = build_parser()
    args, extra = parser.parse_known_args(argv)
    if extra:
        # argparse fills optional positionals at the first positional it
        # meets, so in `progress set --stage N --deliverable K deferred` the
        # status arrives after NUMBER and STATUS were already matched empty.
        # That one word, on that one form, is taken as the NUMBER slot, where
        # `cmd_progress` reads it; anything else is the error parse_args gives.
        if (getattr(args, "func", None) is cmd_progress and len(extra) == 1
                and not extra[0].startswith("-") and args.number is None
                and args.status is None
                and (args.stage is not None or args.deliverable is not None)):
            args.number = _progress_number(extra[0])
        else:
            parser.error(f"unrecognized arguments: {' '.join(extra)}")
    global _GIT_OPTIONAL
    _TOPLEVEL.clear()
    _GIT_OPTIONAL = False
    try:
        if _records_an_edit(args):
            # Asked before the verb writes anything: a repository git cannot
            # be run over refuses here, so no success line is printed for an
            # edit `_commits_here` would then put back (issue #352).
            in_repository(find_repo_root(args.repo))
        return args.func(args)
    except ConfigError as exc:
        # A broken aide.toml is a user-fixable state, not a crash. Every
        # subcommand loads the config, so catching it once here keeps the
        # traceback off the screen for all of them.
        print(f"error: {exc}", file=sys.stderr)
        return 2
    except MissingTool as exc:
        # git or the test command is not there (issue #352): one sentence
        # naming it, exit 1 — the same end whichever verb met it first. `scope`
        # keeps its own contract, where 1 is "out of bounds" and "could not
        # check" is 2.
        verb = args.command
        if args.command == "queue":
            verb += f" {args.action}"
        print(f"aide {verb}: {exc}", file=sys.stderr)
        return 2 if args.command == "scope" else 1


if __name__ == "__main__":
    sys.exit(main())
